/* ============================================================
   Branchline — offline mind map app
   Single-file app logic. No external dependencies, no network.
   Storage: IndexedDB (persistent, per-browser-profile "database").
   ============================================================ */

(function () {
  "use strict";

  // Small "vNN" badge in the toolbar (see #version-badge in index.html)
  // showing which app.js is actually loaded — reads the real ?v= off
  // this very <script> tag (and style.css's <link>) rather than a
  // separately-hardcoded number, so it can never drift out of sync with
  // the BUMP_VERSION numbers above the tags in index.html.
  (function showVersionBadge() {
    const badge = document.getElementById("version-badge");
    if (!badge) return;
    const versionOf = (url) => {
      const m = (url || "").match(/[?&]v=([^&]+)/);
      return m ? m[1] : "?";
    };
    const jsV = versionOf(document.currentScript && document.currentScript.src);
    const cssLink = document.querySelector('link[rel="stylesheet"][href*="style.css"]');
    const cssV = versionOf(cssLink && cssLink.href);
    badge.textContent = `v${jsV}`;
    badge.title = `app.js v${jsV} · style.css v${cssV}`;
  })();

  /* ---------------- constants ---------------- */

  const PALETTE = [
    "#6F94CC", "#F39236", "#E84D42", "#0BC09C", "#499FE0",
    "#756BD1", "#E86BB8", "#F2C94C", "#5DBB63", "#C46DD1"
  ];

  const NODE_H = 40;
  const ROOT_H = 64;
  // These now represent the actual visual gap between a node's rendered
  // right edge and its child's left edge (place() adds the parent's real
  // width on top of this before positioning the child — see the layout
  // functions), so they're deliberately modest: they no longer have to
  // also account for however wide a typical node happens to be.
  const X_GAP = 70;
  // Gap between the root ("mother node" / title) and its direct children is
  // wider than the gap between later generations, so first-level branches
  // sit further out from the center.
  const ROOT_X_GAP = X_GAP * 2;
  const SLOT_GAP = 14;
  const DB_NAME = "branchline_db";
  const DB_VERSION = 3;
  const STORE = "mindmaps";
  const HANDLE_STORE = "handles";
  // Photos used to live inline as base64 data URLs right inside each
  // node's `images` array — simple, but it meant every autosave, every
  // undo/redo snapshot, and every local IndexedDB write had to carry
  // full-resolution photo bytes along with the node tree, even for a
  // one-character text edit on a completely different node. They now
  // live in their own object store, keyed by a short id; nodes only
  // hold that id. See PhotoDB below and getNodeImages/getNodeImageIds.
  const PHOTO_STORE = "photos";
  const DRAG_THRESHOLD = 4;

  /* ---------------- tiny helpers ---------------- */

  function uid() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 9);
  }

  function debounce(fn, ms) {
    let t;
    return function (...args) {
      clearTimeout(t);
      t = setTimeout(() => fn.apply(this, args), ms);
    };
  }

  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

  /* ================= Date helpers (task due dates / Calendar) =================
     Dates are stored as plain "YYYY-MM-DD" strings (local calendar day,
     no time/timezone component) so a task's due date means the same
     day everywhere it's viewed — same convention as the standalone
     Tasks app's calendar. */
  function toISODate(d) {
    const y = d.getFullYear(), m = String(d.getMonth() + 1).padStart(2, "0"), day = String(d.getDate()).padStart(2, "0");
    return `${y}-${m}-${day}`;
  }
  function fromISODate(s) {
    const parts = String(s || "").split("-").map(Number);
    if (parts.length !== 3 || parts.some(isNaN)) return null;
    return new Date(parts[0], parts[1] - 1, parts[2]);
  }
  function isSameDate(a, b) {
    return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
  }
  function startOfToday() {
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    return d;
  }

  function luminance(hex) {
    const c = hex.replace("#", "");
    const r = parseInt(c.substr(0, 2), 16) / 255;
    const g = parseInt(c.substr(2, 2), 16) / 255;
    const b = parseInt(c.substr(4, 2), 16) / 255;
    return 0.299 * r + 0.587 * g + 0.114 * b;
  }

  function hexToRgba(hex, alpha) {
    const c = hex.replace("#", "");
    const r = parseInt(c.substr(0, 2), 16);
    const g = parseInt(c.substr(2, 2), 16);
    const b = parseInt(c.substr(4, 2), 16);
    return `rgba(${r},${g},${b},${alpha})`;
  }

  function hexToRgb(hex) {
    const c = (hex || "#000000").replace("#", "");
    return [parseInt(c.substr(0, 2), 16), parseInt(c.substr(2, 2), 16), parseInt(c.substr(4, 2), 16)];
  }

  function rgbToHex(r, g, b) {
    const h = (n) => clamp(Math.round(n), 0, 255).toString(16).padStart(2, "0");
    return `#${h(r)}${h(g)}${h(b)}`;
  }

  function blendHex(hex, mixHex, amt) {
    const [r1, g1, b1] = hexToRgb(hex);
    const [r2, g2, b2] = hexToRgb(mixHex);
    return rgbToHex(r1 + (r2 - r1) * amt, g1 + (g2 - g1) * amt, b1 + (b2 - b1) * amt);
  }

  const DEFAULT_BG = "#FFF8E1";

  function defaultBg() {
    return DEFAULT_BG;
  }

  function defaultTheme() {
    return {
      background: null,          // null = use the app's default canvas background
      connectorMode: "branch",   // "branch" | "custom"
      connectorColor: "#7c9eff",
      connectorShape: "curved",  // "curved" | "elbow" — map-wide default, set via the root node's right-click menu; any node/connector can override with its own connectorShape
      connectorArrow: false,     // map-wide default arrowhead setting — same idea, per-hop connectorStyle overrides it
      fontMode: "auto",          // "auto" | "custom"
      fontColor: "#f2f3f7"
    };
  }

  function ensureTheme(map) {
    if (!map) return;
    map.theme = Object.assign(defaultTheme(), map.theme || {});
  }

  // Default distance for the hop from a node's parent to the node itself,
  // at a given depth (depth 1 = a direct child of the root). The
  // root-to-first-level hop is wider (ROOT_X_GAP); every hop after that
  // uses a normal X_GAP. Elbow connectors are right-angled rather than a
  // sweeping curve, so they read cleanly at closer range — by default
  // they use half the normal spacing (a custom xGap on a node still
  // always wins, regardless of connector shape).
  function defaultGapForDepth(depth) {
    const base = depth === 1 ? ROOT_X_GAP : X_GAP;
    const isElbow = state.current && state.current.theme && state.current.theme.connectorShape === "elbow";
    return isElbow ? base / 2 : base;
  }

  // The actual distance to use for the hop from a node's parent to the
  // node itself: its own explicit override (set by right-clicking the
  // connector — see openConnectorContextMenu) if it has one, else the
  // normal default for its depth.
  function gapFor(node) {
    return (typeof node.xGap === "number" && node.xGap >= 0) ? node.xGap : defaultGapForDepth(node._depth);
  }

  function haloColorFor(bg) {
    return luminance(bg) > 0.55 ? "rgba(8,10,14,0.42)" : "rgba(255,255,255,0.30)";
  }

  // Solid (non-translucent) contrast color for the text caret — used so the
  // blinking cursor stays visible even when a node's own text color happens
  // to be close to whatever it's sitting on top of (this matters most for
  // level-3+ nodes, which have no fill of their own and sit directly on the
  // user's chosen canvas background).
  function caretColorFor(bg) {
    return luminance(bg) > 0.55 ? "#0d1020" : "#ffffff";
  }

  function applyTheme() {
    if (!state.current) return;
    ensureTheme(state.current);
    const bg = state.current.theme.background || defaultBg();
    document.documentElement.style.setProperty("--bg", bg);
  }


  /* ---------------- IndexedDB layer ---------------- */

  const DB = {
    _db: null,
    open() {
      if (this._db) return Promise.resolve(this._db);
      return new Promise((resolve, reject) => {
        const req = indexedDB.open(DB_NAME, DB_VERSION);
        req.onupgradeneeded = (e) => {
          const db = e.target.result;
          if (!db.objectStoreNames.contains(STORE)) {
            db.createObjectStore(STORE, { keyPath: "id" });
          }
          if (!db.objectStoreNames.contains(HANDLE_STORE)) {
            db.createObjectStore(HANDLE_STORE);
          }
          if (!db.objectStoreNames.contains(PHOTO_STORE)) {
            const photos = db.createObjectStore(PHOTO_STORE, { keyPath: "id" });
            photos.createIndex("mapId", "mapId", { unique: false });
          }
        };
        req.onsuccess = (e) => { this._db = e.target.result; resolve(this._db); };
        req.onerror = (e) => reject(e.target.error);
      });
    },
    async getHandle(key) {
      const db = await this.open();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(HANDLE_STORE, "readonly");
        const req = tx.objectStore(HANDLE_STORE).get(key);
        req.onsuccess = () => resolve(req.result || null);
        req.onerror = (e) => reject(e.target.error);
      });
    },
    async setHandle(key, value) {
      const db = await this.open();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(HANDLE_STORE, "readwrite");
        tx.objectStore(HANDLE_STORE).put(value, key);
        tx.oncomplete = () => resolve();
        tx.onerror = (e) => reject(e.target.error);
      });
    },
    async getAll() {
      const db = await this.open();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE, "readonly");
        const req = tx.objectStore(STORE).getAll();
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = (e) => reject(e.target.error);
      });
    },
    async put(map) {
      const db = await this.open();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE, "readwrite");
        tx.objectStore(STORE).put(map);
        tx.oncomplete = () => resolve();
        tx.onerror = (e) => reject(e.target.error);
      });
    },
    async delete(id) {
      const db = await this.open();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE, "readwrite");
        tx.objectStore(STORE).delete(id);
        tx.oncomplete = () => resolve();
        tx.onerror = (e) => reject(e.target.error);
      });
    }
  };

  // Converts a data: URL string into a Blob without a network round trip
  // (fetch() on a data:/blob: URL works in most browsers but isn't
  // guaranteed, and is slower than just decoding the base64 directly).
  // Used to get incoming photos (file upload, paste, crop, label-bake —
  // all of which still hand over a data: URL) into Blob form before they
  // ever touch PhotoDB or the in-memory cache.
  // The decode half of dataUrlToBlob on its own — addPhotoRecord needs the
  // raw bytes to fingerprint them before deciding whether an identical
  // photo is already stored.
  function dataUrlToBytes(dataUrl) {
    const commaIdx = dataUrl.indexOf(",");
    const header = dataUrl.slice(0, commaIdx);
    const body = dataUrl.slice(commaIdx + 1);
    const mimeMatch = /data:([^;]+)/.exec(header);
    const mime = mimeMatch ? mimeMatch[1] : "application/octet-stream";
    const binary = atob(body);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return { bytes, mime };
  }
  function dataUrlToBlob(dataUrl) {
    const { bytes, mime } = dataUrlToBytes(dataUrl);
    return new Blob([bytes], { type: mime });
  }

  // The reverse — only needed where a photo has to leave this browser
  // as a fully self-contained blob of JSON (Export .json, Google Drive,
  // the connected local folder), since a Blob/object URL only means
  // anything inside this tab.
  function blobToDataUrl(blob) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = () => reject(reader.error);
      reader.readAsDataURL(blob);
    });
  }

  // Photos, stored one row per photo: { id, mapId, blob }. Kept in their
  // own store (see PHOTO_STORE above) so the node tree itself only ever
  // carries small id strings.
  //
  // Older rows (saved before this app stored a Blob) instead have
  // { id, mapId, data } — a base64 data: URL. Base64 inflates the raw
  // bytes by roughly a third and, more importantly, ends up living as a
  // giant JS string in memory for as long as the map is open — a Blob's
  // bytes are held by the browser outside the JS heap and only need a
  // short-lived object URL (see photoUrl/loadPhotoCacheForMap below) to
  // be displayed. Legacy rows are converted to Blob form the first time
  // they're read (see loadPhotoCacheForMap) and written back, so this is
  // a one-time cost per photo, not a repeated one.
  const PhotoDB = {
    async put(rec) {
      const db = await DB.open();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(PHOTO_STORE, "readwrite");
        tx.objectStore(PHOTO_STORE).put(rec);
        tx.oncomplete = () => resolve();
        tx.onerror = (e) => reject(e.target.error);
      });
    },
    // Bulk insert is dramatically faster during a first/new-device sync:
    // a Drive map can contain dozens or hundreds of inline photos. The old
    // migration opened one IndexedDB transaction per photo, so the browser
    // spent most of the sync repeatedly creating/committing transactions.
    // One transaction for the whole batch keeps the same data model while
    // cutting that overhead down to a single commit.
    async putMany(records) {
      if (!records || !records.length) return;
      const db = await DB.open();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(PHOTO_STORE, "readwrite");
        const store = tx.objectStore(PHOTO_STORE);
        records.forEach((rec) => store.put(rec));
        tx.oncomplete = () => resolve();
        tx.onerror = (e) => reject(e.target.error);
        tx.onabort = (e) => reject((e && e.target && e.target.error) || new Error("Photo batch write aborted"));
      });
    },
    async delete(id) {
      const db = await DB.open();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(PHOTO_STORE, "readwrite");
        tx.objectStore(PHOTO_STORE).delete(id);
        tx.oncomplete = () => resolve();
        tx.onerror = (e) => reject(e.target.error);
      });
    },
    async getAllForMap(mapId) {
      const db = await DB.open();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(PHOTO_STORE, "readonly");
        const req = tx.objectStore(PHOTO_STORE).index("mapId").getAll(IDBKeyRange.only(mapId));
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = (e) => reject(e.target.error);
      });
    },
    async deleteAllForMap(mapId) {
      const db = await DB.open();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(PHOTO_STORE, "readwrite");
        const idx = tx.objectStore(PHOTO_STORE).index("mapId");
        const req = idx.openKeyCursor(IDBKeyRange.only(mapId));
        req.onsuccess = (e) => {
          const cursor = e.target.result;
          if (!cursor) return;
          tx.objectStore(PHOTO_STORE).delete(cursor.primaryKey);
          cursor.continue();
        };
        tx.oncomplete = () => resolve();
        tx.onerror = (e) => reject(e.target.error);
      });
    },
    // Every row in the store, regardless of which map (if any) it still
    // claims to belong to — used only to hunt for rows whose mapId no
    // longer matches any map this browser actually knows about (a map
    // permanently deleted by an older build that didn't clean up its
    // photos first, an interrupted permanentlyDeleteMap/emptyTrash call,
    // etc.). Never used on the normal read path — that's getAllForMap,
    // scoped to one map via the index so it stays fast even with a lot
    // of rows.
    async getAllRaw() {
      const db = await DB.open();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(PHOTO_STORE, "readonly");
        const req = tx.objectStore(PHOTO_STORE).getAll();
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = (e) => reject(e.target.error);
      });
    },
    async deleteMany(ids) {
      if (!ids.length) return;
      const db = await DB.open();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(PHOTO_STORE, "readwrite");
        const store = tx.objectStore(PHOTO_STORE);
        ids.forEach(id => store.delete(id));
        tx.oncomplete = () => resolve();
        tx.onerror = (e) => reject(e.target.error);
      });
    }
  };

  // In-memory id -> object-URL cache for whichever map is currently
  // open, populated by loadPhotoCacheForMap() (see openMap). Every
  // rendering/editing call site keeps working with a plain URL string
  // exactly as before via getNodeImages()/photoUrl(); only code that
  // actually needs the photo's raw bytes (duplicate, export/sync) reads
  // photoBlobCache instead.
  //
  // photoCache holds the *display* form (an object URL — cheap, just a
  // short registration the browser resolves internally to the Blob's
  // bytes) while photoBlobCache holds the actual Blob each one points
  // to, so a photo's bytes only ever exist once in memory no matter how
  // many nodes reference it. Object URLs are explicitly revoked (see
  // revokePhotoCache/deletePhotoRecord below) since, unlike a plain
  // string, the browser won't reclaim one just because nothing points to
  // it anymore — an un-revoked URL keeps its Blob alive for the rest of
  // the page's life.
  let photoCache = new Map();
  let photoBlobCache = new Map();

  // ---- Identical photos share one id ---------------------------------
  // Every stored photo is fingerprinted (length + a 64-bit hash of its
  // bytes). addPhotoRecord looks the fingerprint up before creating a
  // record: if the very same photo is already stored on this map, the
  // existing id is handed back instead of storing the bytes a second
  // time — so two nodes showing the same picture reference one id, one
  // Blob and one PhotoDB row. Rules that keep that safe:
  //  - the bytes are only dropped once NOTHING in the map still points at
  //    the id (see deletePhotoRecord / photoIsReferenced);
  //  - an owner (a node, a cell, one link's photo list) never holds the
  //    same id twice — it gets its own id, sharing the same in-memory Blob;
  //  - edits (crop / text / combine) always get a fresh id (noDedupe).
  // Photos already stored when a map opens are fingerprinted in the
  // background (indexPhotoFingerprints), so until that finishes a
  // duplicate can still slip through as a separate record — harmless, and
  // "Merge identical photos" in the Storage panel folds those together.
  let photoFpById = new Map();   // id -> fingerprint
  let photoIdsByFp = new Map();  // fingerprint -> Set of ids
  let photoFpGeneration = 0;     // bumped whenever the cache is reloaded, cancelling a stale index pass
  let photoFpIndexPromise = Promise.resolve();

  function fingerprintBytes(bytes) {
    let u8 = bytes;
    if (u8.byteOffset % 4 !== 0) u8 = u8.slice(); // Uint32Array needs a 4-byte aligned start
    const len = u8.length;
    const nWords = len >>> 2;
    const words = new Uint32Array(u8.buffer, u8.byteOffset, nWords);
    const C1 = 0xcc9e2d51, C2 = 0x1b873593;
    let h1 = 0x9747b28c, h2 = 0x5bd1e995;
    for (let i = 0; i < nWords; i++) {
      const w = words[i];
      let k = Math.imul(w, C1); k = (k << 15) | (k >>> 17); k = Math.imul(k, C2);
      h1 ^= k; h1 = (h1 << 13) | (h1 >>> 19); h1 = (Math.imul(h1, 5) + 0xe6546b64) | 0;
      let k2 = Math.imul(w ^ 0x9e3779b9, C2); k2 = (k2 << 16) | (k2 >>> 16); k2 = Math.imul(k2, C1);
      h2 ^= k2; h2 = (h2 << 11) | (h2 >>> 21); h2 = (Math.imul(h2, 5) + 0x52dce729) | 0;
    }
    let tail = 0;
    for (let i = nWords << 2; i < len; i++) tail = (tail << 8) | u8[i];
    if (tail) {
      let k = Math.imul(tail, C1); k = (k << 15) | (k >>> 17); k = Math.imul(k, C2); h1 ^= k;
      let k2 = Math.imul(tail ^ 0x9e3779b9, C2); k2 = (k2 << 16) | (k2 >>> 16); k2 = Math.imul(k2, C1); h2 ^= k2;
    }
    const fmix = (h) => {
      h ^= h >>> 16; h = Math.imul(h, 0x85ebca6b);
      h ^= h >>> 13; h = Math.imul(h, 0xc2b2ae35);
      h ^= h >>> 16; return h >>> 0;
    };
    return `${len}-${fmix(h1 ^ len).toString(36)}${fmix(h2 ^ len).toString(36)}`;
  }
  function rememberPhotoFingerprint(id, fp) {
    if (!id || !fp) return;
    photoFpById.set(id, fp);
    let set = photoIdsByFp.get(fp);
    if (!set) { set = new Set(); photoIdsByFp.set(fp, set); }
    set.add(id);
  }
  function forgetPhotoFingerprint(id) {
    const fp = photoFpById.get(id);
    if (!fp) return;
    photoFpById.delete(id);
    const set = photoIdsByFp.get(fp);
    if (set) { set.delete(id); if (!set.size) photoIdsByFp.delete(fp); }
  }
  // Fingerprints every photo that was already stored when the map opened.
  // One photo at a time with a yield in between, and after a short pause
  // so it never competes with the map's first render.
  async function indexPhotoFingerprints(gen) {
    await new Promise((r) => setTimeout(r, 1200));
    const entries = Array.from(photoBlobCache.entries());
    for (let i = 0; i < entries.length; i++) {
      if (gen !== photoFpGeneration) return;
      const [id, blob] = entries[i];
      if (photoFpById.has(id) || photoBlobCache.get(id) !== blob) continue;
      try {
        const buf = await blob.arrayBuffer();
        if (gen !== photoFpGeneration) return;
        if (photoBlobCache.get(id) === blob) rememberPhotoFingerprint(id, fingerprintBytes(new Uint8Array(buf)));
      } catch (e) { /* unreadable photo — just leave it out of the index */ }
      if (i % 4 === 3) await new Promise((r) => setTimeout(r, 0));
    }
  }

  function revokePhotoCache() {
    photoCache.forEach((url) => { try { URL.revokeObjectURL(url); } catch (e) { /* already gone */ } });
  }

  async function loadPhotoCacheForMap(mapId) {
    revokePhotoCache();
    photoCache = new Map();
    photoBlobCache = new Map();
    photoFpGeneration++;
    photoFpById = new Map();
    photoIdsByFp = new Map();
    photoFpIndexPromise = Promise.resolve();
    if (!mapId) return;
    try {
      const rows = await PhotoDB.getAllForMap(mapId);
      const migrations = [];
      rows.forEach(r => {
        let blob = r.blob;
        if (!blob && r.data) {
          // Legacy base64 row — convert once and persist the Blob form
          // so every future load of this photo skips this step.
          try {
            blob = dataUrlToBlob(r.data);
            migrations.push(PhotoDB.put({ id: r.id, mapId, blob }));
          } catch (e) { console.error("Migrating photo to blob storage failed", e); return; }
        }
        if (!blob) return;
        photoBlobCache.set(r.id, blob);
        photoCache.set(r.id, URL.createObjectURL(blob));
      });
      if (migrations.length) Promise.all(migrations).catch(e => console.error("Migrating photo storage failed", e));
    } catch (e) { console.error("Loading photos failed", e); }
    photoFpIndexPromise = indexPhotoFingerprints(photoFpGeneration);
  }

  // Adds a brand-new photo (from a file/paste) to the store + cache for
  // the currently open map and returns its id. Fire-and-forget on the
  // actual disk write — the cache is updated synchronously so rendering
  // never has to wait on it. Still takes a data: URL, same as every
  // existing caller (file upload, paste, crop apply, label bake) already
  // produces — only the storage/display form changes, right here.
  //
  // If an identical photo is already stored on this map, that photo's id is
  // returned and nothing new is stored (see "Identical photos share one id"
  // above). `opts.avoid` — the ids the caller's owner (node/cell/link)
  // already holds — keeps one owner from getting the same id twice; in that
  // case a separate id is made that still shares the existing Blob in
  // memory. `opts.noDedupe` always makes a fresh record (edits).
  function addPhotoRecord(dataUrl, opts) {
    const o = opts || {};
    const { bytes, mime } = dataUrlToBytes(dataUrl);
    const fp = fingerprintBytes(bytes);
    let shareBlob = null;
    if (!o.noDedupe) {
      const twins = photoIdsByFp.get(fp);
      if (twins) {
        const avoid = o.avoid || [];
        for (const twinId of twins) {
          if (!photoBlobCache.has(twinId)) continue;
          if (!avoid.includes(twinId)) return twinId;
          if (!shareBlob) shareBlob = photoBlobCache.get(twinId);
        }
      }
    }
    const id = uid();
    const blob = shareBlob || new Blob([bytes], { type: mime });
    photoBlobCache.set(id, blob);
    photoCache.set(id, URL.createObjectURL(blob));
    rememberPhotoFingerprint(id, fp);
    if (state.current) PhotoDB.put({ id, mapId: state.current.id, blob }).catch(e => console.error("Saving photo failed", e));
    return id;
  }

  // Copies an existing photo onto a brand-new id — used when a photo is
  // Alt/Option-dragged onto another node (a real copy, not a shared
  // reference) so each node ends up owning its own photo record. The two
  // ids can safely share the same underlying Blob (Blobs are immutable)
  // instead of duplicating the bytes in memory.
  //
  // Identical photos now share one id (see above), so a copy simply reuses
  // the id — one stored photo, referenced from both nodes — unless the
  // destination already holds that id (`avoid`), in which case it gets its
  // own id still backed by the same in-memory Blob.
  function duplicatePhotoRecord(oldId, avoid) {
    const blob = photoBlobCache.get(oldId);
    if (!blob) return oldId; // shouldn't happen; fail safe by sharing the id
    if (!Array.isArray(avoid) || !avoid.includes(oldId)) return oldId;
    const id = uid();
    photoBlobCache.set(id, blob);
    photoCache.set(id, URL.createObjectURL(blob));
    const fp = photoFpById.get(oldId);
    if (fp) rememberPhotoFingerprint(id, fp);
    if (state.current) PhotoDB.put({ id, mapId: state.current.id, blob }).catch(e => console.error("Saving photo failed", e));
    return id;
  }

  // ---- Photos embedded inline in notes ---------------------------------
  // A note's rich-text body can hold pasted/dropped screenshots too (see
  // noteInsertImages below). Those now live in PhotoDB exactly like a
  // node's attached photos — the note's stored HTML carries only a
  // data-photo-id="…" attribute on the <img>, never the picture's bytes —
  // so two identical screenshots pasted into one note (or two different
  // notes on the same map) share one PhotoDB row instead of each paste
  // inflating the note's own HTML with a fresh copy of the same base64.
  // Ids only ever appear in that one attribute, so a plain string scan is
  // enough; no need to parse the HTML into a live DOM just to read it.
  function extractNotePhotoIds(html) {
    const ids = [];
    if (!html || html.indexOf("data-photo-id") === -1) return ids;
    const re = /data-photo-id="([^"]+)"/g;
    let m;
    while ((m = re.exec(html))) ids.push(m[1]);
    return ids;
  }
  // Every note-bearing "owner" shape (a node, a table cell's attach record,
  // a task, a subtask) stores its notes the same way — see getNodeNotes/
  // getTaskNotes/getCellNotes — so this only needs to look at `.notes`.
  function addNoteOwnerPhotoIds(owner, ids) {
    if (!owner || !Array.isArray(owner.notes)) return;
    owner.notes.forEach((n) => { if (n && n.html) extractNotePhotoIds(n.html).forEach((id) => ids.add(id)); });
  }
  function addTaskListNotePhotoIds(tasks, ids) {
    (tasks || []).forEach((t) => {
      if (!t) return;
      addNoteOwnerPhotoIds(t, ids);
      (t.subtasks || []).forEach((s) => addNoteOwnerPhotoIds(s, ids));
    });
  }

  // Every id any node, table cell, link comment, or inline note image in
  // this tree points at.
  function collectReferencedPhotoIds(root) {
    const ids = new Set();
    const addList = (list) => (list || []).forEach((id) => { if (id) ids.add(id); });
    (function walk(node) {
      if (!node) return;
      getNodeImageIds(node).forEach((id) => ids.add(id));
      getCellImageIds(node).forEach((id) => ids.add(id));
      if (node.linkPhotos) Object.values(node.linkPhotos).forEach(addList);
      addNoteOwnerPhotoIds(node, ids);
      addTaskListNotePhotoIds(node.tasks, ids);
      if (node.table && Array.isArray(node.table.attach)) {
        node.table.attach.forEach((row) => (row || []).forEach((a) => {
          if (!a) return;
          if (a.linkPhotos) Object.values(a.linkPhotos).forEach(addList);
          addNoteOwnerPhotoIds(a, ids);
          addTaskListNotePhotoIds(a.tasks, ids);
        }));
      }
      (node.children || []).forEach(walk);
    })(root);
    return ids;
  }
  function photoIsReferenced(id) {
    return !!state.current && collectReferencedPhotoIds(state.current.root).has(id);
  }

  // Swaps fromId for toId wherever ONE node holds it — its own photos
  // (carrying the per-photo tags/notes/comments/favorite/date over to the
  // new id), its table cells' photos, and its link-comment photos. A list
  // that already holds toId is left alone so no owner ends up with the
  // same id twice. Returns how many lists changed.
  function replacePhotoIdInNode(node, fromId, toId) {
    if (!node || fromId === toId) return 0;
    let changed = 0;
    const swap = (arr) => {
      if (!Array.isArray(arr) || !arr.includes(fromId) || arr.includes(toId)) return false;
      for (let i = 0; i < arr.length; i++) if (arr[i] === fromId) arr[i] = toId;
      return true;
    };
    const renameMeta = () => {
      ["photoTags", "photoNotes", "photoComments", "photoFavorites", "photoTimestamps"].forEach((k) => {
        const m = node[k];
        if (m && Object.prototype.hasOwnProperty.call(m, fromId)) {
          if (!Object.prototype.hasOwnProperty.call(m, toId)) m[toId] = m[fromId];
          delete m[fromId];
        }
      });
    };
    if (Array.isArray(node.images) && node.images.length) {
      if (swap(node.images)) { changed++; renameMeta(); }
    } else if (node.image === fromId) {
      node.images = [toId]; node.image = null; changed++; renameMeta();
    }
    if (node.linkPhotos) Object.values(node.linkPhotos).forEach((arr) => { if (swap(arr)) changed++; });
    // Ids embedded inline in a note (see noteInsertImages/extractNotePhotoIds)
    // live inside data-photo-id="…" attributes in the note's stored HTML
    // rather than in an array, so they need their own swap: a literal
    // string replace of the attribute value (ids are plain uid() strings,
    // never containing regex-special characters, so this is safe without
    // parsing the HTML into a DOM).
    const swapNoteOwner = (owner) => {
      if (!owner || !Array.isArray(owner.notes)) return;
      owner.notes.forEach((n) => {
        if (n && n.html && n.html.indexOf(fromId) !== -1) {
          const swapped = n.html.split(`data-photo-id="${fromId}"`).join(`data-photo-id="${toId}"`);
          if (swapped !== n.html) { n.html = swapped; changed++; }
        }
      });
    };
    const swapTaskList = (tasks) => (tasks || []).forEach((t) => {
      if (!t) return;
      swapNoteOwner(t);
      (t.subtasks || []).forEach(swapNoteOwner);
    });
    swapNoteOwner(node);
    swapTaskList(node.tasks);
    if (node.table && Array.isArray(node.table.attach)) {
      node.table.attach.forEach((row) => (row || []).forEach((a) => {
        if (!a) return;
        if (Array.isArray(a.images) && a.images.length) { if (swap(a.images)) changed++; }
        else if (a.image === fromId) { a.images = [toId]; a.image = null; changed++; }
        if (a.linkPhotos) Object.values(a.linkPhotos).forEach((arr) => { if (swap(arr)) changed++; });
        swapNoteOwner(a);
        swapTaskList(a.tasks);
      }));
    }
    return changed;
  }

  function deletePhotoRecord(id) {
    // Identical photos can share one id, so only drop the bytes once nothing
    // in the map points at this id any more. (If a caller deletes before
    // removing its own reference the bytes simply linger until the idle
    // orphan sweep — never the other way round.)
    if (photoIsReferenced(id)) return;
    forgetPhotoFingerprint(id);
    const url = photoCache.get(id);
    if (url) { try { URL.revokeObjectURL(url); } catch (e) { /* already gone */ } }
    photoCache.delete(id);
    photoBlobCache.delete(id);
    // Don't touch the disk row yet. The map that's stored in IndexedDB may
    // STILL point at this id (crop / add-text / combine swap a photo for a
    // new id, and the map save that records the swap is debounced and can
    // even queue behind a slow Drive upload). Deleting the row right now
    // left a window where a refresh loaded a map referencing a photo that
    // no longer existed — the photo just vanished. The row is deleted by
    // releasePhotoDeletes() once a map save that no longer references it
    // has actually landed.
    pendingPhotoDeletes.add(id);
  }

  // ids whose PhotoDB row is waiting for a durable map save (see above).
  const pendingPhotoDeletes = new Set();
  // Called right BEFORE a map write starts: takes ownership of everything
  // queued so far. Only ids removed from the tree before this moment are
  // guaranteed to be absent from the map that write stores.
  function takePendingPhotoDeletes() {
    const ids = Array.from(pendingPhotoDeletes);
    pendingPhotoDeletes.clear();
    return ids;
  }
  // Called after that write succeeded. Skips any id the map points at again
  // (e.g. an undo re-attached it in the meantime).
  async function releasePhotoDeletes(ids, map) {
    if (!ids || !ids.length) return;
    try {
      const still = map && map.root ? collectReferencedPhotoIds(map.root) : new Set();
      const doomed = ids.filter((id) => !still.has(id));
      if (doomed.length) await PhotoDB.deleteMany(doomed);
    } catch (e) { console.error("Deleting photos failed", e); }
  }
  // The write failed — keep the rows and try again with the next save.
  function requeuePhotoDeletes(ids) {
    (ids || []).forEach((id) => pendingPhotoDeletes.add(id));
  }

  function photoUrl(id) {
    return photoCache.get(id) || "";
  }

  // Walks a map's node tree, migrating any legacy inline photo (a plain
  // `data:` URL, either from before this store existed or from a Drive/
  // folder/export file — see inlinePhotosForPortableCopy) into its own
  // PhotoDB record, replacing it in the tree with just the new id. Ids
  // already present (anything not starting with "data:") are left alone.
  // Safe to call repeatedly — already-migrated nodes are a no-op.
  async function ensurePhotosMigrated(map) {
    if (!map || !map.root) return;
    const puts = [];
    (function walk(node) {
      if (!node) return;
      const raw = Array.isArray(node.images) ? node.images : (node.image ? [node.image] : []);
      // Tracks old raw value (the data URL that used to double as both the
      // photo's content AND its tag key) -> its freshly-minted id, so tags
      // keyed on that old value can be carried over below instead of lost.
      const idForOldValue = new Map();
      if (raw.length) {
        const ids = raw.map((val) => {
          if (typeof val === "string" && val.startsWith("data:")) {
            const id = uid();
            idForOldValue.set(val, id);
            puts.push({ id, mapId: map.id, blob: dataUrlToBlob(val) });
            return id;
          }
          return val;
        });
        node.images = ids;
        node.image = null;
      }
      // photoTags used to be keyed by the raw data URL itself; remap any
      // such keys onto the new id using the mapping just built above, so
      // a photo's tags survive the move into its own store. A key that
      // isn't a data URL is already an id (map's been through this
      // before) and is left as-is.
      if (node.photoTags) {
        const remapped = {};
        Object.keys(node.photoTags).forEach((k) => {
          const newKey = k.startsWith("data:") ? idForOldValue.get(k) : k;
          if (newKey) remapped[newKey] = node.photoTags[k];
        });
        node.photoTags = remapped;
      }
      // Same remap for photo comments (added later, but keyed the same way).
      if (node.photoComments) {
        const remapped = {};
        Object.keys(node.photoComments).forEach((k) => {
          const newKey = k.startsWith("data:") ? idForOldValue.get(k) : k;
          if (newKey) remapped[newKey] = node.photoComments[k];
        });
        node.photoComments = remapped;
      }
      // Same migration for a table node's per-cell photos: a portable
      // copy (import, or a device that just pulled this map from Drive/
      // a folder) stores each cell's photo as a raw data URL — see
      // inlinePhotosForPortableCopy — so it needs the same one-time move
      // into PhotoDB, keyed by its own fresh id, that node.images gets
      // above.
      if (node.table && Array.isArray(node.table.attach)) {
        node.table.attach.forEach(row => (row || []).forEach((a) => {
          if (!a) return;
          if (typeof a.image === "string" && a.image.startsWith("data:")) {
            const id = uid();
            puts.push({ id, mapId: map.id, blob: dataUrlToBlob(a.image) });
            a.image = id;
          }
          if (Array.isArray(a.images) && a.images.length) {
            a.images = a.images.map((val) => {
              if (typeof val === "string" && val.startsWith("data:")) {
                const id = uid();
                puts.push({ id, mapId: map.id, blob: dataUrlToBlob(val) });
                return id;
              }
              return val;
            });
          }
        }));
      }
      // A note's inline images normally already reference PhotoDB via
      // data-photo-id (see noteInsertImages) — nothing to do for those.
      // But a note that still carries a raw `data:` <img> (an old note
      // saved before that existed, or one just brought in from a Drive/
      // folder/import file — see inlinePhotosForPortableCopy, which
      // inlines them back to plain data: URLs for portability) gets the
      // same one-time move into its own PhotoDB record here, so it picks
      // up the same dedup benefit instead of sitting there as loose
      // base64 forever.
      const migrateNoteOwner = (owner) => {
        if (!owner || !Array.isArray(owner.notes)) return;
        owner.notes.forEach((n) => {
          if (!n || !n.html || n.html.indexOf("<img") === -1) return;
          n.html = n.html.replace(/<img\b[^>]*\bsrc="(data:[^"]*)"[^>]*>/g, (tag, dataUrl) => {
            const id = uid();
            puts.push({ id, mapId: map.id, blob: dataUrlToBlob(dataUrl) });
            return tag
              .replace(`src="${dataUrl}"`, "")
              .replace("<img", `<img data-photo-id="${id}"`);
          });
        });
      };
      const migrateTaskList = (tasks) => (tasks || []).forEach((t) => {
        if (!t) return;
        migrateNoteOwner(t);
        (t.subtasks || []).forEach(migrateNoteOwner);
      });
      migrateNoteOwner(node);
      migrateTaskList(node.tasks);
      if (node.table && Array.isArray(node.table.attach)) {
        node.table.attach.forEach(row => (row || []).forEach((a) => {
          if (!a) return;
          migrateNoteOwner(a);
          migrateTaskList(a.tasks);
        }));
      }
      (node.children || []).forEach(walk);
    })(map.root);
    if (puts.length) await PhotoDB.putMany(puts);
    map._photosMigrated = true;
  }

  // The reverse of ensurePhotosMigrated: produces a deep-cloned, fully
  // self-contained copy of a map with every node.images id resolved back
  // to its actual data URL — used anywhere the map needs to travel
  // outside this browser's own IndexedDB (Export .json, Google Drive,
  // the connected local folder), since none of those destinations can
  // see this browser's PhotoDB.
  async function inlinePhotosForPortableCopy(map) {
    if (!map || !map.root) return map;
    const rows = await PhotoDB.getAllForMap(map.id);
    const lookup = new Map();
    // Rows are stored as a Blob (see PhotoDB above) apart from any
    // not-yet-migrated legacy row, which is already a portable base64
    // string as-is. Either way, the map needs actual inline data: URLs
    // here — a Blob/object URL only means anything inside this tab.
    await Promise.all(rows.map(async (r) => {
      if (r.data) { lookup.set(r.id, r.data); return; }
      if (r.blob) {
        try { lookup.set(r.id, await blobToDataUrl(r.blob)); }
        catch (e) { console.error("Inlining photo failed", e); }
      }
    }));
    // Also fold in anything only in the in-memory cache but not yet
    // flushed to disk (a photo added in the last <1s, say).
    if (state.current && state.current.id === map.id) {
      await Promise.all(Array.from(photoBlobCache.entries()).map(async ([id, blob]) => {
        if (lookup.has(id)) return;
        try { lookup.set(id, await blobToDataUrl(blob)); }
        catch (e) { console.error("Inlining photo failed", e); }
      }));
    }
    const clone = JSON.parse(JSON.stringify(map));
    (function walk(node) {
      if (!node) return;
      if (Array.isArray(node.images)) {
        node.images = node.images.map(id => lookup.get(id) || id);
      }
      // photoTags/photoNotes are keyed by the photo's local id, which is
      // meaningless once this map leaves this browser (Drive/folder/
      // export all carry inline bytes, not local ids — see above). Remap
      // those keys onto the same data URL the photo itself is being
      // inlined to here, so that when this file comes back in through
      // ensurePhotosMigrated(), its existing "data:"-keyed remap logic
      // (see the idForOldValue map there) can reattach the tags/notes to
      // whatever fresh id that photo gets — instead of leaving them
      // keyed to a stale local id that no longer matches anything, which
      // silently dropped tags/notes on any photo that survived a round
      // trip through Drive/folder sync or Export .json.
      if (node.photoTags) {
        const remapped = {};
        Object.keys(node.photoTags).forEach((k) => { remapped[lookup.get(k) || k] = node.photoTags[k]; });
        node.photoTags = remapped;
      }
      if (node.photoNotes) {
        const remapped = {};
        Object.keys(node.photoNotes).forEach((k) => { remapped[lookup.get(k) || k] = node.photoNotes[k]; });
        node.photoNotes = remapped;
      }
      if (node.photoComments) {
        const remapped = {};
        Object.keys(node.photoComments).forEach((k) => { remapped[lookup.get(k) || k] = node.photoComments[k]; });
        node.photoComments = remapped;
      }
      if (node.table && Array.isArray(node.table.attach)) {
        node.table.attach.forEach(row => (row || []).forEach((a) => {
          if (!a) return;
          if (a.image) a.image = lookup.get(a.image) || a.image;
          if (Array.isArray(a.images)) a.images = a.images.map(id => lookup.get(id) || id);
        }));
      }
      // A note's inline images (see noteInsertImages/extractNotePhotoIds)
      // only ever hold a data-photo-id="…" reference in storage, same as
      // node.images holding bare ids — resolve those back to real inline
      // data: URLs too, so an exported/synced copy of this note still
      // shows its pictures outside this browser.
      const inlineNoteOwner = (owner) => {
        if (!owner || !Array.isArray(owner.notes)) return;
        owner.notes.forEach((n) => {
          if (!n || !n.html || n.html.indexOf("data-photo-id") === -1) return;
          n.html = n.html.replace(/<img\b[^>]*\bdata-photo-id="([^"]+)"[^>]*>/g, (tag, id) => {
            const dataUrl = lookup.get(id);
            if (!dataUrl) return tag; // photo missing from PhotoDB — leave the tag as-is rather than break the note
            return tag.includes("src=") ? tag.replace(/src="[^"]*"/, `src="${dataUrl}"`) : tag.replace("<img", `<img src="${dataUrl}"`);
          });
        });
      };
      const inlineTaskList = (tasks) => (tasks || []).forEach((t) => {
        if (!t) return;
        inlineNoteOwner(t);
        (t.subtasks || []).forEach(inlineNoteOwner);
      });
      inlineNoteOwner(node);
      inlineTaskList(node.tasks);
      if (node.table && Array.isArray(node.table.attach)) {
        node.table.attach.forEach(row => (row || []).forEach((a) => {
          if (!a) return;
          inlineNoteOwner(a);
          inlineTaskList(a.tasks);
        }));
      }
      (node.children || []).forEach(walk);
    })(clone.root);
    return clone;
  }

  // Load the editable affirmation-lines pool from IndexedDB (falling back
  // to the built-in defaults the first time the app runs), and save it
  // back whenever the person edits it in the manager modal.
  async function loadAffirmationQuotes() {
    try {
      const saved = await DB.getHandle(AFFIRMATION_QUOTES_KEY);
      if (Array.isArray(saved) && saved.length) {
        affirmationQuotesList = saved;
      }
    } catch (e) { /* IndexedDB unavailable — keep the built-in defaults */ }
  }
  async function saveAffirmationQuotes() {
    try {
      await DB.setHandle(AFFIRMATION_QUOTES_KEY, affirmationQuotesList);
    } catch (e) { /* best-effort — keep working in-memory even if this fails */ }
  }

  /* ---------------- database folder (File System Access API) ----------------
     IndexedDB is always the source of truth for fast reads, but when a
     folder is connected every mind map is also mirrored there as a plain
     .json file, so the "database" is a real folder the person can see,
     back up, or move between machines. */

  const FolderDB = {
    dir: null,
    supported: typeof window.showDirectoryPicker === "function",
    needsPermission: false,
    lastFile: {},

    async verify(handle, allowPrompt) {
      try {
        const opts = { mode: "readwrite" };
        if ((await handle.queryPermission(opts)) === "granted") return true;
        if (!allowPrompt) return false;
        if ((await handle.requestPermission(opts)) === "granted") return true;
        return false;
      } catch (e) { return false; }
    },

    async restore() {
      if (!this.supported) return;
      try {
        const handle = await DB.getHandle("mapsFolder");
        if (!handle) return;
        this.dir = handle;
        const ok = await this.verify(handle, false);
        this.needsPermission = !ok;
      } catch (e) { /* handle no longer valid; ignore */ }
    },

    async pick() {
      if (!this.supported) {
        alert("This browser can't connect a local folder for saving. Your maps still autosave to the browser's built-in database — use Export .json to back them up as files.");
        return;
      }
      try {
        const handle = await window.showDirectoryPicker();
        const ok = await this.verify(handle, true);
        if (!ok) return;
        this.dir = handle;
        this.needsPermission = false;
        this.lastFile = {};
        await DB.setHandle("mapsFolder", handle);
        await this.syncFromFolder();
        for (const m of state.maps) await this.save(m);
        await autoRemoveDuplicateMaps();
        renderSidebar();
        updateFolderUI();
      } catch (e) {
        if (e && e.name !== "AbortError") console.error("Folder connect failed", e);
      }
    },

    filenameFor(map) {
      const safe = (map.title || "untitled").toLowerCase()
        .replace(/[^a-z0-9]+/g, "-").replace(/(^-+|-+$)/g, "").slice(0, 40) || "untitled";
      return `${safe}-${map.id}.json`;
    },

    async save(map) {
      if (!this.dir || this.needsPermission || !map) return;
      try {
        const name = this.filenameFor(map);
        const prev = this.lastFile[map.id];
        if (prev && prev !== name) {
          try { await this.dir.removeEntry(prev); } catch (e) {}
        }
        const fh = await this.dir.getFileHandle(name, { create: true });
        const w = await fh.createWritable();
        // The folder mirror is meant to be a real, self-contained backup
        // file, so it carries actual photo bytes inline rather than this
        // browser's local-only photo ids.
        const portable = await inlinePhotosForPortableCopy(map);
        await w.write(JSON.stringify(portable, null, 2));
        await w.close();
        this.lastFile[map.id] = name;
      } catch (e) { console.error("Folder save failed", e); }
    },

    async remove(map) {
      if (!this.dir || this.needsPermission || !map) return;
      const name = this.lastFile[map.id] || this.filenameFor(map);
      try { await this.dir.removeEntry(name); } catch (e) {}
      delete this.lastFile[map.id];
    },

    async syncFromFolder() {
      if (!this.dir) return;
      const ok = await this.verify(this.dir, true);
      this.needsPermission = !ok;
      if (!ok) return;
      try {
        for await (const [name, handle] of this.dir.entries()) {
          if (handle.kind !== "file" || !name.endsWith(".json")) continue;
          try {
            const file = await handle.getFile();
            const data = JSON.parse(await file.text());
            if (!data || !data.id || !data.root) continue;
            const existing = state.maps.find(m => m.id === data.id);
            // Skip entirely if our copy is already current — otherwise
            // ensurePhotosMigrated below still runs on every sync and
            // re-migrates this file's inline photo bytes into brand-new
            // PhotoDB records each time, even though `data` is about to
            // be thrown away unused, silently duplicating photo storage
            // on every refresh.
            if (existing && (existing.updatedAt || 0) >= (data.updatedAt || 0)) {
              this.lastFile[data.id] = name;
              continue;
            }
            ensureTheme(data);
            ensureLayout(data);
            ensureFavorite(data);
            ensureTrash(data);
            ensureSidesRepaired(data);
            // Folder files always carry inline photo bytes (see save()
            // above) — pull them into this browser's own photo store.
            await ensurePhotosMigrated(data);
            if (!existing) {
              state.maps.push(data);
              await DB.put(data);
            } else {
              Object.assign(existing, data);
              await DB.put(existing);
            }
            this.lastFile[data.id] = name;
          } catch (e) { /* skip unreadable/unrelated file */ }
        }
        sortMaps(state.maps);
      } catch (e) { console.error("Folder sync failed", e); }
    }
  };

  function updateFolderUI() {
    const btn = $("#btn-connect-folder");
    const status = $("#folder-status");
    if (!btn || !status) return;
    if (!FolderDB.supported) {
      status.textContent = "Folder sync isn't supported in this browser";
      btn.textContent = "Connect folder";
      btn.disabled = true;
      return;
    }
    btn.disabled = false;
    if (FolderDB.dir && !FolderDB.needsPermission) {
      status.textContent = `Database folder: ${FolderDB.dir.name}`;
      btn.textContent = "Change";
    } else if (FolderDB.dir && FolderDB.needsPermission) {
      status.textContent = "Folder connected — click to allow access";
      btn.textContent = "Allow access";
    } else {
      status.textContent = "Saving to browser storage only";
      btn.textContent = "Connect folder";
    }
  }

  /* ---------------- Google Drive sync ----------------
     Mirrors every map to Google Drive as its own .json file, the same way
     FolderDB mirrors to a local folder — same merge-by-updatedAt policy,
     just a different backend. This is what actually gets your maps from
     one device/browser to another (a local "Connect folder" only syncs
     devices that share a filesystem, e.g. via Dropbox/iCloud).

     REQUIRES a Google Cloud OAuth Client ID pasted into GOOGLE_CLIENT_ID
     below — see the "Google Drive sync setup" section of the README for
     how to get one. Without it, the sign-in button just explains that. */
  const GOOGLE_CLIENT_ID = "270018625814-4jfdor9fci625de9b4j7hjta15urcqoe.apps.googleusercontent.com";
  const DRIVE_SCOPE = "https://www.googleapis.com/auth/drive.file";
  const DRIVE_SIGNED_IN_KEY = "driveWasSignedIn";
  const DRIVE_TOKEN_CACHE_KEY = "branchline_drive_token";

  // Translates the handful of error codes GIS's error_callback actually
  // sends into something a person can act on, instead of a bare code like
  // "popup_failed_to_open".
  function describeGisError(err) {
    const code = (err && err.type) || String(err || "");
    if (code === "popup_failed_to_open") return "Google's sign-in popup was blocked by the browser. Allow popups for this page and try again.";
    if (code === "popup_closed") return "The Google sign-in popup was closed before finishing.";
    return "Google sign-in failed (" + code + "). This often means this page's exact origin isn't listed under \"Authorized JavaScript origins\" for this OAuth client in Google Cloud Console.";
  }

  // Waits for Google Identity Services to finish loading, instead of
  // failing the instant a click arrives a beat early. The gsi/client
  // script tag is loaded async (see index.html), so on a fresh page load
  // it can still be in flight for anywhere from tens of ms to a couple
  // of seconds after the rest of the app — including this sign-in
  // button — is already interactive. Polls rather than hooking the
  // script's load event so it works no matter when it's called relative
  // to that script finishing (including if it already has).
  function waitForGis(timeoutMs) {
    if (window.google && google.accounts && google.accounts.oauth2) return Promise.resolve(true);
    return new Promise((resolve) => {
      const startedAt = Date.now();
      const check = () => {
        if (window.google && google.accounts && google.accounts.oauth2) { resolve(true); return; }
        if (Date.now() - startedAt >= timeoutMs) { resolve(false); return; }
        setTimeout(check, 100);
      };
      check();
    });
  }

  // The access token itself is cached in localStorage (not just in memory)
  // so an F5 reload can reuse it directly — no Google round-trip, no
  // popup — for as long as it's still valid (Google issues these with
  // roughly a 1-hour lifetime; there's no way to get a longer-lived one
  // without a backend server, which this app deliberately doesn't have).
  function saveCachedDriveToken(token, expiresAt) {
    try { localStorage.setItem(DRIVE_TOKEN_CACHE_KEY, JSON.stringify({ token, expiresAt })); } catch (e) {}
  }
  function loadCachedDriveToken() {
    try {
      const parsed = JSON.parse(localStorage.getItem(DRIVE_TOKEN_CACHE_KEY) || "null");
      if (parsed && parsed.token && parsed.expiresAt > Date.now() + 60000) return parsed;
    } catch (e) {}
    return null;
  }
  function clearCachedDriveToken() {
    try { localStorage.removeItem(DRIVE_TOKEN_CACHE_KEY); } catch (e) {}
  }

  // How often the background poll checks Drive for changes made on other
  // devices. DriveDB.FRESH_WINDOW_MS is derived from this, so change it
  // here only.
  const DRIVE_POLL_INTERVAL_MS = 10000;

  const DriveDB = {
    tokenClient: null,
    accessToken: null,
    tokenExpiresAt: 0,
    // The in-flight requestToken() call, if any: { silent, promise, reject }.
    // See _requestTokenNow() — this exists so a later call can tell
    // whether it's safe to cancel the one already running, instead of
    // always barging in front of it.
    _activeRequest: null,

    // ---- One status field instead of a pile of booleans ----
    // "out"        — signed out.
    // "connecting" — signed in, first sync of this session hasn't
    //                finished yet (editing stays locked until it does,
    //                so a stale local copy can't get overwritten or
    //                overwrite something newer).
    // "ok"         — signed in, synced, everything reaching Drive fine.
    // "reauth"     — Google session died; needs an explicit reconnect
    //                click (silent refresh can't recover this on its
    //                own — see silentRefresh()).
    // "broken"     — signed in with a live token, but syncing/uploading
    //                is failing (network, Drive outage, etc.) — usually
    //                recovers on its own once the connection is back.
    // isEditingAllowed() only allows edits in "ok" (see below); every UI
    // string that used to branch on 4-5 separate flags now just branches
    // on this one.
    status: "out",
    get signedIn() { return this.status !== "out"; },
    get dataSynced() { return this.status === "ok" || this.status === "reauth" || this.status === "broken"; },
    get needsReauth() { return this.status === "reauth"; },
    driveBroken() { return this.status === "broken"; },

    // True while a syncFromDrive()/verifyRemote() pass is running —
    // both are "talk to Drive and reconcile" passes that must never
    // overlap each other, so callers only ever need to know "busy or
    // not", not which of the two it is.
    busy: false,
    // True while pushLocalNewer() is actively uploading — kept separate
    // from `busy` because the UI shows a distinct "Uploading changes…"
    // message for it.
    pushingLocal: false,
    lastLocalPushTryAt: 0,

    // Timestamp (ms) of the last time this device successfully talked to
    // Drive — purely a UI value (see updateDriveUI's "Synced Xm ago"),
    // never persisted or compared against anything.
    lastSyncedAt: 0,

    // Failed-attempt counters that feed into `status`. Poll failures
    // (can't reach Drive at all) push toward "broken"; silent-refresh
    // failures (token can't renew itself) push toward "reauth" and are
    // throttled by a cooldown so a dead connection can't hammer Google's
    // silent sign-in check every second.
    consecutivePollFailures: 0,
    MAX_POLL_FAILURES: 3,
    consecutiveSilentFailures: 0,
    MAX_SILENT_FAILURES: 3,
    lastSilentFailureAt: 0,
    SILENT_RETRY_COOLDOWN_MS: 30000,

    // Maps with edits Drive hasn't confirmed receiving yet.
    unsyncedMaps() {
      return state.maps.filter((m) => {
        const known = this.fileIndex[m.id];
        return !!known && (m.updatedAt || 0) > (known.updatedAt || 0);
      });
    },

    // "Am I on the latest version?" — kept for informational/UI timing
    // purposes (freshUntil/isFresh). It is NOT what gates the edit lock
    // or the "checking for a newer version" banner anymore — those are
    // driven by conflictDetected below, so a routine poll that simply
    // hasn't run yet (the timer aging out between cycles) never pauses
    // editing on its own; only Drive actually confirming another device
    // saved something newer does.
    FRESH_WINDOW_MS: DRIVE_POLL_INTERVAL_MS + 6000,
    freshUntil: 0,
    isFresh() { return Date.now() < this.freshUntil; },
    // True only when a Drive check has actually confirmed this device is
    // behind — either another device's saved copy is newer
    // (remoteBehindLocal), or a download of that newer copy just failed
    // (so it's still out there, unconfirmed). Cleared the moment a full
    // sync pass completes with nothing outstanding. This — not the
    // freshUntil timer — is what the edit lock and "checking for a
    // newer version" banner key off, so editing only ever pauses for a
    // real, known reason, never for a routine periodic recheck.
    conflictDetected: false,

    // Human-readable progress for the sync pill/modal. The old UI could sit
    // on a generic "Syncing…" for a long time, which made a large first sync
    // look frozen even while it was downloading photo-heavy maps. These are
    // deliberately UI-only; they never participate in conflict decisions.
    syncPhase: "",
    syncProgressDone: 0,
    syncProgressTotal: 0,
    syncProgressPercent: 0,
    syncStartedAt: 0,
    setSyncProgress(phase, done, total, percent) {
      this.syncPhase = phase || "";
      this.syncProgressDone = Number(done || 0);
      this.syncProgressTotal = Number(total || 0);
      if (!phase) {
        this.syncProgressPercent = 0;
        this.syncStartedAt = 0;
      } else {
        if (!this.syncStartedAt) this.syncStartedAt = Date.now();
        if (Number.isFinite(Number(percent))) {
          this.syncProgressPercent = Math.max(0, Math.min(100, Math.round(Number(percent))));
        } else if (this.syncProgressTotal > 0) {
          this.syncProgressPercent = Math.max(0, Math.min(100,
            Math.round((this.syncProgressDone / this.syncProgressTotal) * 100)));
        } else if (!this.syncProgressPercent) {
          this.syncProgressPercent = 1;
        }
      }
      try { updateDriveUI(); } catch (e) {}
    },
    // True if Drive holds a newer copy of any map this device already has.
    remoteBehindLocal(remoteFiles) {
      return remoteFiles.some((f) => {
        const id = f.appProperties && f.appProperties.branchlineId;
        if (!id) return false;
        const existing = state.maps.find(m => m.id === id);
        const remoteUpdatedAt = Number((f.appProperties && f.appProperties.updatedAt) || 0);
        return !!existing && remoteUpdatedAt > (existing.updatedAt || 0);
      });
    },
    // Check-only pass (no downloads, nothing touched locally): used while
    // a map edit is in progress, when the full sync can't run because it
    // would swap the tree out from under the editor. It keeps the
    // freshness stamp current, and clears it the moment another device
    // saves something newer.
    async verifyRemote() {
      const remoteFiles = await this.listRemote();
      const listedAt = Date.now();
      const behind = this.remoteBehindLocal(remoteFiles);
      this.conflictDetected = behind;
      this.freshUntil = behind ? 0 : listedAt + this.FRESH_WINDOW_MS;
      this.consecutivePollFailures = 0;
    },
    // map id -> { fileId, updatedAt } for every map we know is mirrored to
    // Drive, so save/remove don't have to search every time.
    fileIndex: {},

    configured() {
      return !!GOOGLE_CLIENT_ID && !GOOGLE_CLIENT_ID.startsWith("PASTE_");
    },

    // Keeps you signed in for as long as Google will allow without ever
    // needing another click on "Sign in with Google" — refreshes the
    // access token silently in the background, well before it actually
    // expires. Runs on its own timer so a session stays alive even while
    // the tab sits in the background or idle. A pure client-side app
    // like this only ever gets short-lived (~1hr) access tokens, never a
    // long-lived refresh token (that requires a backend), so this just
    // keeps refreshing on a rolling basis for as long as it keeps
    // succeeding, and only actually ends the session on an explicit
    // "Sign out" or a refresh Google itself starts rejecting.
    refreshTimer: null,
    scheduleRefresh() {
      if (this.refreshTimer) { clearTimeout(this.refreshTimer); this.refreshTimer = null; }
      if (!this.signedIn) return;
      // Refresh 5 minutes before the current token expires (or almost
      // immediately if it's already past that point) — never less than a
      // few seconds out, so a failing refresh can't spin in a tight loop.
      const delay = Math.max(5000, this.tokenExpiresAt - Date.now() - 5 * 60 * 1000);
      this.refreshTimer = setTimeout(async () => {
        try {
          await this.silentRefresh();
          this.scheduleRefresh(); // got a fresh token — line up the next one
        } catch (e) {
          console.error("Background Drive token refresh failed, will retry", e);
          if (this.needsReauth) return; // stop the loop — see silentRefresh()
          // A transient network hiccup or a momentarily-blocked silent
          // check shouldn't end the session early — keep trying rather
          // than giving up after one failure.
          this.refreshTimer = setTimeout(() => this.scheduleRefresh(), 2 * 60 * 1000);
        }
      }, delay);
    },

    // On page load: reuse a still-valid cached token with no network
    // round-trip at all if we have one (the common case for an F5 within
    // the same hour); otherwise fall back to a silent (no popup) Google
    // re-auth attempt, but only if we'd signed in successfully before —
    // so a person who's never connected Drive never sees a Google popup
    // flash by uninvited.
    async restore() {
      if (!this.configured()) return;
      const cached = loadCachedDriveToken();
      if (cached) {
        this.accessToken = cached.token;
        this.tokenExpiresAt = cached.expiresAt;
        this.status = "connecting";
        this.setSyncProgress("Checking Drive…", 0, 0, 2);
        updateDriveUI("Syncing…");
        try {
          await this.syncFromDrive();
          this.status = "ok";
          await this.pushLocalNewer({ force: true, includeNew: true });
          this.setSyncProgress("", 0, 0);
          renderSidebar();
          // Repaint the already-open map's canvas with whatever this sync
          // just pulled in — without this, the currently-open map (and any
          // node badges/score bars on it) stays showing the pre-sync local
          // copy until the first poll tick happens to call renderAll().
          // Same guard as pollDriveUpdates: don't tear down an active edit
          // box mid-keystroke or clobber a change still mid-save.
          if (!state.editingId && !unsavedEdits) renderAll();
          updateDriveUI();
          startDriveSyncPolling();
          this.scheduleRefresh();
          syncTaskTemplatesWithDrive();
          return;
        } catch (e) {
          console.error("Cached Drive token didn't work, falling back", e);
          this.accessToken = null;
          this.status = "out";
          clearCachedDriveToken();
          // fall through to the silent-reauth attempt below
        }
      }
      let was = false;
      try { was = await DB.getHandle(DRIVE_SIGNED_IN_KEY); } catch (e) {}
      if (!was) return;
      try { await this.signIn(true); } catch (e) { /* silent attempt only — fail quietly */ }
    },

    // NOTE: deliberately no longer reused across calls — see requestToken()
    // below for why each call gets its own throwaway client instead.
    ensureTokenClient() {
      return !!(window.google && google.accounts && google.accounts.oauth2);
    },

    requestToken(silent) {
      // Google Identity Services simply does not work when the page is
      // opened as a local file (origin "null" / file://) — there is no
      // way to authorize that as a JS origin in Google Cloud Console, and
      // GIS fails silently rather than raising an error: no popup, no
      // callback, no exception. Catch that up front with a clear message
      // instead of leaving the button looking like it did nothing.
      if (location.protocol === "file:") {
        return Promise.reject(new Error(
          "Google sign-in can't run from a file opened directly (file://). " +
          "Serve this folder over http/https instead — e.g. run a local " +
          "server and open http://localhost, or host it (GitHub Pages, " +
          "etc.), and make sure that exact origin is added under " +
          "\"Authorized JavaScript origins\" for this OAuth client."
        ));
      }
      // Fast path: GIS has already finished loading, true for the vast
      // majority of clicks. Go straight to requestAccessToken() below with
      // no async gap at all, so the call stays inside this click's own
      // user gesture — Safari in particular blocks the popup outright if
      // it isn't.
      if (this.ensureTokenClient()) return this._requestTokenNow(silent);
      // Slow path: the accounts.google.com/gsi/client script (loaded
      // async in index.html) hasn't finished downloading/executing yet.
      // Wait for it instead of bailing out with "hasn't loaded yet — try
      // again", which is exactly why sign-in so often needed a second
      // click before — the click itself did nothing wrong, it just lost
      // a race that had nothing to do with the user.
      return waitForGis(8000).then((ready) => {
        if (!ready) throw new Error("Google sign-in script hasn't loaded — check your connection and try again.");
        return this._requestTokenNow(silent);
      });
    },

    _requestTokenNow(silent) {
      // Never let a new call barge in front of one that's already
      // running. A silent background check is still allowed to lose to
      // an explicit click — a person acting right now always outranks an
      // automatic check — but nothing is ever allowed to cancel an
      // explicit request that's already in flight; the safest thing a
      // second call can do there is wait on the one already running
      // (which also means an accidental double-click never opens a
      // second popup).
      if (this._activeRequest) {
        if (this._activeRequest.silent && !silent) {
          this._activeRequest.reject(new Error("Superseded by a newer sign-in request"));
        } else {
          return this._activeRequest.promise;
        }
      }
      let rejectExternally = null;
      const promise = new Promise((resolve, reject) => {
        if (!this.ensureTokenClient()) { reject(new Error("Google sign-in script hasn't loaded — check your connection and try again.")); return; }
        // Watchdog: if neither the success callback nor error_callback
        // ever fires, don't leave the button hung forever with no
        // feedback.
        let settled = false;
        const timeoutId = setTimeout(() => {
          if (settled) return;
          settled = true;
          reject(new Error("Google sign-in didn't respond after 15 seconds — it may have been blocked by a popup blocker, or this page's origin isn't authorized for this OAuth client yet. Check the browser console for details."));
        }, 15000);
        const settle = (fn, arg) => {
          if (settled) return; // a second callback firing for the same call, or one arriving after this call was itself superseded — ignore rather than double-settle
          settled = true;
          clearTimeout(timeoutId);
          fn(arg);
        };
        rejectExternally = (err) => settle(reject, err);
        // A fresh, throwaway token client for THIS call only, rather than
        // reusing one shared client across calls, so a stale response can
        // only ever reach its own (already-settled, now-inert) closure,
        // never a newer call's.
        const client = google.accounts.oauth2.initTokenClient({
          client_id: GOOGLE_CLIENT_ID,
          scope: DRIVE_SCOPE,
          callback: (resp) => {
            if (resp && resp.access_token) {
              this.accessToken = resp.access_token;
              this.tokenExpiresAt = Date.now() + ((resp.expires_in || 3300) * 1000);
              saveCachedDriveToken(this.accessToken, this.tokenExpiresAt);
              // Any successful token — silent or explicit — proves Google
              // auth is working again: drop out of "reauth"/"broken" back
              // to "ok" (both only ever happen after a first successful
              // sync, so "ok" is always the right landing spot here).
              if (this.status === "reauth" || this.status === "broken") this.status = "ok";
              this.consecutivePollFailures = 0;
              this.consecutiveSilentFailures = 0;
              settle(resolve, resp.access_token);
            } else {
              settle(reject, resp && resp.error ? new Error(resp.error) : new Error("Sign-in didn't return a token"));
            }
          },
          error_callback: (err) => settle(reject, new Error(describeGisError(err))),
        });
        client.requestAccessToken({ prompt: silent ? "none" : "consent" });
      });
      const entry = { silent, promise, reject: (err) => { if (rejectExternally) rejectExternally(err); } };
      this._activeRequest = entry;
      promise.catch(() => {}).finally(() => {
        if (this._activeRequest === entry) this._activeRequest = null;
      });
      return promise;
    },

    // Silent token refreshes normally happen invisibly, but when the
    // cached token has been expired for a while, GIS's "prompt: none"
    // check can briefly flash a real tab to accounts.google.com on
    // mobile Chrome instead of a truly silent iframe check. Tolerable as
    // a one-off; two things stop it becoming a repeating annoyance: a
    // cooldown between retries, and a hard stop (→ "reauth") after
    // MAX_SILENT_FAILURES in a row, so updateDriveUI() shows a
    // "Reconnect" prompt instead — a real tap gives the browser a
    // genuine user gesture to work with, which the silent path can't get
    // on some mobile browsers.
    async silentRefresh() {
      if (this.needsReauth) {
        throw new Error("Google session needs to be reconnected — tap \u201cReconnect Google\u201d.");
      }
      if (this.lastSilentFailureAt && Date.now() - this.lastSilentFailureAt < this.SILENT_RETRY_COOLDOWN_MS) {
        throw new Error("Drive session refresh recently failed — will retry shortly");
      }
      try {
        const token = await this.requestToken(true);
        this.lastSilentFailureAt = 0;
        this.consecutiveSilentFailures = 0;
        return token;
      } catch (e) {
        // Being superseded isn't a real auth failure — a newer (usually
        // explicit, user-initiated) request just took over this same
        // slot. Don't let that count against MAX_SILENT_FAILURES; the
        // request that superseded it reports its own outcome.
        if (e && e.message === "Superseded by a newer sign-in request") throw e;
        this.lastSilentFailureAt = Date.now();
        this.consecutiveSilentFailures++;
        if (this.consecutiveSilentFailures >= this.MAX_SILENT_FAILURES) {
          this.status = "reauth";
          updateDriveUI();
        }
        throw e;
      }
    },

    async getToken() {
      if (this.accessToken && Date.now() < this.tokenExpiresAt - 60000) return this.accessToken;
      return this.silentRefresh(); // token expired mid-session — refresh silently
    },

    // Thin wrapper around fetch that attaches the bearer token and retries
    // once (with a forced fresh token) on a 401, since a token can expire
    // between getToken() returning it and the request actually landing.
    async api(url, opts, _retried) {
      const token = await this.getToken();
      const input = opts || {};
      const timeoutMs = Number(input.timeoutMs || 45000);
      const fetchOpts = { ...input };
      delete fetchOpts.timeoutMs;
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeoutMs);
      let res;
      try {
        res = await fetch(url, {
          ...fetchOpts,
          signal: fetchOpts.signal || controller.signal,
          headers: { ...(fetchOpts && fetchOpts.headers), Authorization: `Bearer ${token}` }
        });
      } catch (e) {
        if (e && e.name === "AbortError") throw new Error("Google Drive request timed out");
        throw e;
      } finally {
        clearTimeout(timer);
      }
      if (res.status === 401 && !_retried) {
        this.accessToken = null;
        return this.api(url, opts, true);
      }
      return res;
    },

    async signIn(silent) {
      if (!this.configured()) {
        alert("Google Drive sync needs to be set up first — a developer needs to add a Google OAuth Client ID to the app (see the README's \"Google Drive sync setup\" section).");
        return;
      }
      await this.requestToken(!!silent);
      if (this.status === "out") this.status = "connecting";
      try { await DB.setHandle(DRIVE_SIGNED_IN_KEY, true); } catch (e) {}
      this.setSyncProgress("Checking Drive…", 0, 0, 2);
      updateDriveUI("Syncing…");
      try {
        await this.syncFromDrive();
        this.status = "ok";
        await this.pushLocalNewer({ force: true, includeNew: true });
        this.setSyncProgress("", 0, 0);
      } catch (e) {
        console.error("Drive sync failed", e);
        if (!silent) alert("Signed in, but syncing with Drive failed: " + (e.message || e) + "\n\nYour maps are still safe locally — try signing in again, or check the browser console for details.");
      }
      renderSidebar();
      // See the matching comment in restore() above — repaint the open
      // map immediately so a fresher score/badge from this sync doesn't
      // sit stale on screen until the next poll tick.
      if (!state.editingId && !unsavedEdits) renderAll();
      updateDriveUI();
      startDriveSyncPolling();
      this.scheduleRefresh();
      syncTaskTemplatesWithDrive();
    },

    signOut() {
      if (this.refreshTimer) { clearTimeout(this.refreshTimer); this.refreshTimer = null; }
      // Deliberately NOT calling google.accounts.oauth2.revoke() here.
      // revoke() doesn't just drop this browser's token — it revokes the
      // whole OAuth consent grant for this Google account + this app's
      // client ID, which invalidates every other device/browser's access
      // token issued under that same grant too. A plain local sign-out
      // (forget the token here, let it expire naturally on Google's side
      // within the hour) keeps other devices' sessions untouched.
      this.accessToken = null;
      this.status = "out";
      this.freshUntil = 0;
      this.conflictDetected = false;
      this.fileIndex = {};
      this.lastSyncedAt = 0;
      this.setSyncProgress("", 0, 0);
      DB.setHandle(DRIVE_SIGNED_IN_KEY, false).catch(() => {});
      clearCachedDriveToken();
      updateDriveUI();
      stopDriveSyncPolling();
    },

    // Lists every Drive file this app has access to (drive.file scope
    // limits that to files the app itself created), along with the
    // metadata we tagged them with — cheap compared to downloading every
    // file's content just to check whether it changed.
    async listRemote() {
      const fields = encodeURIComponent("files(id,name,appProperties)");
      const q = encodeURIComponent("trashed=false");
      const res = await this.api(`https://www.googleapis.com/drive/v3/files?q=${q}&fields=${fields}&spaces=drive&pageSize=1000`);
      if (!res.ok) throw new Error("Couldn't list Drive files (" + res.status + ")");
      const data = await res.json();
      return (data.files || []).filter(f => f.appProperties && f.appProperties.branchlineId);
    },

    async downloadFile(fileId) {
      const res = await this.api(`https://www.googleapis.com/drive/v3/files/${fileId}?alt=media`);
      if (!res.ok) throw new Error("Couldn't download a map from Drive (" + res.status + ")");
      return res.json();
    },

    filenameFor(map) {
      const safe = (map.title || "untitled").toLowerCase()
        .replace(/[^a-z0-9]+/g, "-").replace(/(^-+|-+$)/g, "").slice(0, 40) || "untitled";
      return `${safe}-${map.id}.json`;
    },

    // Both create and update go through Drive's *resumable* upload
    // protocol (rather than the 5MB-capped "multipart" one) since a
    // mindmap full of full-resolution photos can easily exceed that.
    async startResumableSession(url, method, metadata) {
      const res = await this.api(url, {
        method,
        headers: { "Content-Type": "application/json; charset=UTF-8" },
        body: JSON.stringify(metadata)
      });
      if (!res.ok) throw new Error("Couldn't start a Drive upload (" + res.status + ")");
      const uploadUrl = res.headers.get("Location");
      if (!uploadUrl) throw new Error("Drive didn't return an upload session URL");
      return uploadUrl;
    },

    async createFile(map) {
      const metadata = { name: this.filenameFor(map), appProperties: { branchlineId: map.id, updatedAt: String(map.updatedAt || 0) } };
      const uploadUrl = await this.startResumableSession(
        "https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable&fields=id", "POST", metadata
      );
      const putRes = await this.api(uploadUrl, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(map),
        timeoutMs: 180000
      });
      if (!putRes.ok) throw new Error("Couldn't upload a map to Drive (" + putRes.status + ")");
      const data = await putRes.json();
      return data.id;
    },

    async updateFile(fileId, map) {
      const metadata = { name: this.filenameFor(map), appProperties: { branchlineId: map.id, updatedAt: String(map.updatedAt || 0) } };
      const uploadUrl = await this.startResumableSession(
        `https://www.googleapis.com/upload/drive/v3/files/${fileId}?uploadType=resumable`, "PATCH", metadata
      );
      const putRes = await this.api(uploadUrl, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(map),
        timeoutMs: 180000
      });
      if (!putRes.ok) throw new Error("Couldn't update a map on Drive (" + putRes.status + ")");
    },

    // A 200 from the upload request means Google accepted the bytes, but the
    // old code immediately called the map "Synced" without checking what Drive
    // now reports for that file. On mobile, a tab can be suspended at awkward
    // moments and that made the UI look safer than it really was. A save is now
    // considered complete only after a direct Drive metadata read confirms the
    // exact updatedAt stamp we just uploaded.
    async verifyUploadedStamp(fileId, expectedStamp) {
      for (let i = 0; i < 4; i++) {
        const fields = encodeURIComponent("id,appProperties,modifiedTime");
        const res = await this.api(`https://www.googleapis.com/drive/v3/files/${fileId}?fields=${fields}`);
        if (res.ok) {
          const data = await res.json();
          const actual = Number((data.appProperties && data.appProperties.updatedAt) || 0);
          if (actual >= expectedStamp) return true;
        }
        await new Promise(r => setTimeout(r, 450 + i * 350));
      }
      return false;
    },

    // Tiny metadata read used immediately before EVERY normal upload. The
    // previous sync model could still lose cross-device edits in one narrow
    // race: PC uploads, then before the phone's next 10s poll the phone edits
    // its stale copy and autosave uploads it straight over the PC version.
    // Verifying the remote stamp here turns autosave into a compare-before-
    // write operation: if Drive changed since this device last confirmed it,
    // we refuse to upload the stale tree and let syncFromDrive merge/pull it
    // first. Manual "Upload" can explicitly bypass this after its own warning.
    async readRemoteStamp(fileId) {
      const fields = encodeURIComponent("id,appProperties,modifiedTime");
      const res = await this.api(`https://www.googleapis.com/drive/v3/files/${fileId}?fields=${fields}`);
      if (!res.ok) throw new Error("Couldn't verify the current Drive revision (" + res.status + ")");
      const data = await res.json();
      return {
        updatedAt: Number((data.appProperties && data.appProperties.updatedAt) || 0),
        modifiedTime: data.modifiedTime || null
      };
    },

    async save(map, opts) {
      if (!this.signedIn || !map) return false;
      const skipRemoteGuard = !!(opts && opts.skipRemoteGuard);
      try {
        const knownBefore = this.fileIndex[map.id];
        if (knownBefore && !skipRemoteGuard) {
          const remoteNow = await this.readRemoteStamp(knownBefore.fileId);
          if (remoteNow.updatedAt > (knownBefore.updatedAt || 0)) {
            // Another device changed Drive after our last confirmed base.
            // Never overwrite it from autosave. Mark this device stale and
            // schedule a full reconcile just after the local save finishes;
            // syncFromDrive's existing three-way merge/conflict-copy logic
            // will preserve both sides, then push the merged result.
            this.conflictDetected = true;
            this.freshUntil = 0;
            try { updateDriveUI(); } catch (e) {}
            setTimeout(() => { try { pollDriveUpdates(true); } catch (e) {} }, 900);
            return false;
          }
        }
        // The Drive copy is what actually crosses devices, so — same as
        // the folder mirror — it needs real photo bytes inline rather
        // than this browser's local-only photo ids.
        const portable = await inlinePhotosForPortableCopy(map);
        // The stamp of the copy actually being uploaded — NOT the live
        // map's, which can have moved on during a slow upload. Recording
        // the live one made edits made mid-upload look already synced.
        const uploadedStamp = portable.updatedAt || map.updatedAt;
        const known = this.fileIndex[map.id];
        let fileId;
        if (known) {
          fileId = known.fileId;
          await this.updateFile(fileId, portable);
        } else {
          fileId = await this.createFile(portable);
        }

        // Do not advance fileIndex / sync-base until Drive itself proves it
        // has this exact revision. If verification fails, the map remains
        // dirty and the retry loop will push it again instead of silently
        // treating a local-only edit as synced.
        const verified = await this.verifyUploadedStamp(fileId, uploadedStamp);
        if (!verified) throw new Error("Drive did not confirm the uploaded revision yet");
        this.fileIndex[map.id] = { fileId, updatedAt: uploadedStamp };
        setSyncBase(map.id, uploadedStamp);
        await setSyncSnapshot(map.id, map);
        this.lastSyncedAt = Date.now();
        this.consecutivePollFailures = 0;
        if (this.status === "broken") this.status = "ok";
        updateDriveUI();
        return true;
      } catch (e) {
        // A failed upload used to be a console-only event: the toolbar
        // still said "Saved" (which was true — locally), the sidebar
        // still said "Synced 4m ago" (also true, and useless), and the
        // person kept editing into what was effectively a local-only
        // copy. Treat it as the connection loss it is: flag it, lock
        // editing, and say so on screen.
        console.error("Drive save failed", e);
        const tokenLooksExpired = !this.accessToken || Date.now() >= this.tokenExpiresAt;
        this.status = tokenLooksExpired ? "reauth" : "broken";
        try { updateDriveUI(); } catch (e2) {}
        return false;
      }
    },

    // ---- Shared settings file (currently: saved task-list templates) ----
    // Kept in ONE small Drive file, tagged appProperties.branchlineSettings
    // (NOT branchlineId), so listRemote()/syncFromDrive() never mistake it
    // for a map. Oldest-created first so every device agrees which file is
    // the "primary" if a race ever produces two.
    async listSettingsFiles() {
      const q = encodeURIComponent("trashed=false and appProperties has { key='branchlineSettings' and value='1' }");
      const fields = encodeURIComponent("files(id,name)");
      const res = await this.api(`https://www.googleapis.com/drive/v3/files?q=${q}&fields=${fields}&spaces=drive&pageSize=20&orderBy=createdTime`);
      if (!res.ok) throw new Error("Couldn't list Drive settings (" + res.status + ")");
      const data = await res.json();
      return data.files || [];
    },
    async writeSettingsFile(fileId, payload) {
      const metadata = { name: "branchline-settings.json", appProperties: { branchlineSettings: "1" } };
      const url = fileId
        ? `https://www.googleapis.com/upload/drive/v3/files/${fileId}?uploadType=resumable`
        : "https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable&fields=id";
      const uploadUrl = await this.startResumableSession(url, fileId ? "PATCH" : "POST", metadata);
      const putRes = await this.api(uploadUrl, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      if (!putRes.ok) throw new Error("Couldn't upload settings to Drive (" + putRes.status + ")");
      return fileId || (await putRes.json()).id;
    },

    async remove(map) {
      if (!this.signedIn || !map) return;
      const known = this.fileIndex[map.id];
      if (!known) return;
      try {
        await this.api(`https://www.googleapis.com/drive/v3/files/${known.fileId}`, { method: "DELETE" });
      } catch (e) { /* best-effort */ }
      delete this.fileIndex[map.id];
    },

    // The push half of sync. syncFromDrive() only ever *pulls*, and skips
    // any map whose local copy is newer than Drive's — so if an upload
    // was cut short (phone backgrounded mid-upload, network drop, expired
    // login), that edit used to sit on this device only, invisible to
    // every other device, until the next edit happened to trigger a
    // fresh upload. This finds every map whose local `updatedAt` is
    // ahead of what Drive last confirmed and uploads it again.
    // `includeNew` also uploads maps Drive has never seen (used right
    // after sign-in, when nothing else could be creating them at the
    // same time).
    //
    // Returns true if it pushed anything. Skipped while an edit is still
    // being typed or saved — runPersistNow() uploads those itself, and a
    // second overlapping upload of the same map could land out of order.
    async pushLocalNewer(opts) {
      const { force = false, includeNew = false } = opts || {};
      if (this.status !== "ok" && this.status !== "broken") return false;
      if (this.pushingLocal) return false;
      // Retry a failing push at most every 15s, but always let an explicit
      // trigger (returning to the tab, coming back online) go straight
      // through.
      if (!force && Date.now() - this.lastLocalPushTryAt < 15000) return false;
      const busy = () => {
        // While uploads are failing, an open editor mustn't block the
        // retry — the lock this causes would otherwise never lift.
        try { return !!(((state.editingId && this.status !== "broken")) || unsavedEdits || persistTimer || persistInFlight); }
        catch (e) { return false; }
      };
      if (busy()) return false;
      const stale = state.maps.filter(m => {
        const known = this.fileIndex[m.id];
        if (!known) return includeNew || this.status === "broken";
        return (m.updatedAt || 0) > (known.updatedAt || 0);
      });
      if (!stale.length) return false;
      this.lastLocalPushTryAt = Date.now();
      this.pushingLocal = true;
      const uploadStartPct = this.syncProgressPercent >= 60 ? this.syncProgressPercent : 5;
      try {
        for (let i = 0; i < stale.length; i++) {
          const m = stale[i];
          if (busy()) break; // an edit started mid-pass — its own save takes over
          const beforePct = uploadStartPct + Math.round((95 - uploadStartPct) * (i / stale.length));
          this.setSyncProgress(`Uploading map ${i + 1}/${stale.length}…`, i, stale.length, beforePct);
          await this.save(m);
          const afterPct = uploadStartPct + Math.round((95 - uploadStartPct) * ((i + 1) / stale.length));
          this.setSyncProgress(`Uploading map ${i + 1}/${stale.length}…`, i + 1, stale.length, afterPct);
        }
      } finally {
        this.pushingLocal = false;
      }
      // save() flags status "broken" on failure instead of throwing — if
      // this pass ended that way, retry soon (~5s) rather than waiting
      // the full 15s, since editing is locked while uploads fail.
      if (this.status === "broken") this.lastLocalPushTryAt = Date.now() - 10000;
      return true;
    },

    // Pulls in anything new/changed from Drive, same merge rule as
    // FolderDB: newer `updatedAt` wins, and a map neither side has ever
    // seen just gets added. Only actually downloads a file's content when
    // its tagged updatedAt looks newer than what we already have.
    //
    // Also mirrors deletions: if a map this device previously knew was on
    // Drive (it's in fileIndex from an earlier sync) has since vanished
    // from the Drive listing, that means it was deleted on another
    // device — so it's deleted here too. A map that's only ever existed
    // locally (never made it into fileIndex yet) is never touched by
    // this.
    // Resolves to true only if this pass actually changed local data, so
    // callers like pollDriveUpdates can skip re-rendering when nothing did.
    async syncFromDrive() {
      let changed = false;
      let downloadFailed = false;
      this.setSyncProgress("Listing Drive maps…", 0, 0, 5);
      const remoteFilesRaw = await this.listRemote();
      const listedAt = Date.now();

      // Prefer the last-opened map first. It doesn't change conflict rules,
      // but on a phone/PC hand-off it gets its newest bytes into the local
      // DB before less relevant maps.
      let lastOpenId = null;
      try { lastOpenId = localStorage.getItem(LAST_OPENED_MAP_KEY); } catch (e) {}
      const remoteFiles = remoteFilesRaw.slice().sort((a, b) => {
        const aid = a.appProperties && a.appProperties.branchlineId;
        const bid = b.appProperties && b.appProperties.branchlineId;
        if (aid === lastOpenId && bid !== lastOpenId) return -1;
        if (bid === lastOpenId && aid !== lastOpenId) return 1;
        return 0;
      });

      // The instant the listing shows another device saved something
      // newer, this device is on an old version: lock editing right now,
      // not after the (possibly slow, photo-heavy) download below lands.
      if (this.remoteBehindLocal(remoteFiles)) {
        this.freshUntil = 0;
        this.conflictDetected = true;
        try { updateStaleSyncBanner(); refreshEditLockUI(); } catch (e) {}
      }

      // Decide which files will actually need their JSON body. The old first
      // sync downloaded each one sequentially; because Drive copies contain
      // inline photo bytes, a few large maps multiplied network latency badly.
      // We prefetch up to three bodies in parallel, while keeping all merge /
      // IndexedDB mutations below sequential so conflict behavior stays stable.
      const targets = [];
      for (const f of remoteFiles) {
        const id = f.appProperties && f.appProperties.branchlineId;
        if (!id) continue;
        const remoteUpdatedAt = Number((f.appProperties && f.appProperties.updatedAt) || 0);
        const existing = state.maps.find(m => m.id === id);
        if (!existing || (existing.updatedAt || 0) < remoteUpdatedAt) {
          targets.push(f);
          continue;
        }
        if ((existing.updatedAt || 0) > remoteUpdatedAt) {
          const base = getSyncBase(id);
          if (base !== undefined && (existing.updatedAt || 0) > base && remoteUpdatedAt > base) targets.push(f);
        }
      }

      const deferredByFile = new Map();
      targets.forEach((f) => {
        let resolve;
        const promise = new Promise((r) => { resolve = r; });
        deferredByFile.set(f.id, { promise, resolve });
      });
      let targetCursor = 0;
      const workerCount = Math.min(3, targets.length);
      const workers = Array.from({ length: workerCount }, async () => {
        while (true) {
          const idx = targetCursor++;
          if (idx >= targets.length) return;
          const f = targets[idx];
          try {
            const data = await this.downloadFile(f.id);
            deferredByFile.get(f.id).resolve({ data, error: null });
          } catch (error) {
            deferredByFile.get(f.id).resolve({ data: null, error });
          }
        }
      });
      const prefetchedDownload = async (fileId) => {
        const d = deferredByFile.get(fileId);
        if (!d) return this.downloadFile(fileId);
        const out = await d.promise;
        if (out.error) throw out.error;
        return out.data;
      };

      const previouslyKnownIds = new Set(Object.keys(this.fileIndex));
      const seenRemoteIds = new Set();
      let processedDownloads = 0;
      const showDownloadProgress = () => {
        if (!targets.length) return;
        const pct = 10 + Math.round(60 * (processedDownloads / targets.length));
        this.setSyncProgress(
          `Downloading changed maps ${Math.min(processedDownloads + 1, targets.length)}/${targets.length}…`,
          processedDownloads,
          targets.length,
          pct
        );
      };

      for (const f of remoteFiles) {
        const id = f.appProperties && f.appProperties.branchlineId;
        if (!id) continue;
        seenRemoteIds.add(id);
        const remoteUpdatedAt = Number((f.appProperties && f.appProperties.updatedAt) || 0);
        this.fileIndex[id] = { fileId: f.id, updatedAt: remoteUpdatedAt };
        const existing = state.maps.find(m => m.id === id);
        if (existing) {
          const localUpdatedAt = existing.updatedAt || 0;
          const baseBefore = getSyncBase(id);

          // Critical first-sync/poll optimization: an unchanged map does NOT
          // need its entire merge-base tree written back to IndexedDB every
          // 10 seconds. Only refresh that snapshot if the agreed revision has
          // actually moved. The old unconditional write was costly on large
          // maps and made a metadata-only sync feel much slower than it was.
          if (localUpdatedAt === remoteUpdatedAt) {
            if (baseBefore !== remoteUpdatedAt) {
              setSyncBase(id, remoteUpdatedAt);
              await setSyncSnapshot(id, existing);
            }
            continue;
          }

          // First time this device sees a differing map since sync tracking
          // began: establish a conservative base before conflict handling.
          if (baseBefore === undefined) {
            setSyncBase(id, Math.min(localUpdatedAt, remoteUpdatedAt));
            await setSyncSnapshot(id, existing);
          }

          if (localUpdatedAt > remoteUpdatedAt) {
            // Ours is newer and will be uploaded. But if Drive ALSO changed
            // since our last agreed base, fetch it and three-way merge first.
            const base = getSyncBase(id);
            if (base !== undefined && localUpdatedAt > base && remoteUpdatedAt > base) {
              try {
                showDownloadProgress();
                const other = await prefetchedDownload(f.id);
                processedDownloads++;
                if (other && other.root) {
                  let merged = null;
                  try {
                    const snapshot = await getSyncSnapshot(id);
                    if (snapshot) merged = mergeMapContent(snapshot, existing, other);
                  } catch (e) { merged = null; }
                  if (merged) {
                    existing.root = merged.root;
                    existing.links = merged.links;
                    existing.title = merged.title;
                    existing.updatedAt = nextUpdatedAt(existing);
                    await DB.put(existing);
                    showToast("Combined your edits with changes from another device");
                  } else {
                    await saveConflictCopy(other, "other device");
                  }
                }
                setSyncBase(id, remoteUpdatedAt);
                await setSyncSnapshot(id, existing);
                changed = true;
              } catch (e) {
                console.error("Couldn't fetch the other device's copy", e);
                downloadFailed = true;
              }
            }
            continue;
          }
        }

        try {
          showDownloadProgress();
          const data = await prefetchedDownload(f.id);
          processedDownloads++;
          if (!data || !data.id || !data.root) continue;

          // About to replace this device's copy with Drive's. If this device
          // has edits Drive never received, merge them if possible, otherwise
          // preserve a separate unsynced copy.
          let mergedContent = null;
          if (existing) {
            const base = getSyncBase(id);
            if (base !== undefined && (existing.updatedAt || 0) > base) {
              try {
                const snapshot = await getSyncSnapshot(id);
                if (snapshot) mergedContent = mergeMapContent(snapshot, existing, data);
              } catch (e) { mergedContent = null; }
              if (mergedContent) {
                showToast("Combined your edits with changes from another device");
              } else {
                const localPortable = await inlinePhotosForPortableCopy(existing);
                await saveConflictCopy(localPortable, "unsynced copy");
              }
            }
          }

          ensureTheme(data);
          ensureLayout(data);
          ensureFavorite(data);
          ensureTrash(data);
          ensureSidesRepaired(data);
          // Drive files carry inline photo bytes. Bulk migration now stores
          // all of a map's photos in one IndexedDB transaction instead of one
          // transaction per photo.
          await ensurePhotosMigrated(data);
          if (existing) {
            Object.assign(existing, data);
            if (mergedContent) {
              existing.root = mergedContent.root;
              existing.links = mergedContent.links;
              existing.title = mergedContent.title;
              existing.updatedAt = nextUpdatedAt(existing);
            }
            await DB.put(existing);
          } else {
            state.maps.push(data);
            await DB.put(data);
          }
          setSyncBase(id, Math.max(remoteUpdatedAt, data.updatedAt || 0));
          await setSyncSnapshot(id, existing || data);
          changed = true;
        } catch (e) {
          console.error("Drive download failed for one map", e);
          downloadFailed = true;
        }
      }

      if (workers.length) await Promise.all(workers);

      for (const id of previouslyKnownIds) {
        if (seenRemoteIds.has(id)) continue;
        delete this.fileIndex[id];
        const existing = state.maps.find(m => m.id === id);
        if (!existing) continue;
        await DB.delete(id);
        await FolderDB.remove(existing);
        changed = true;
        state.maps = state.maps.filter(m => m.id !== id);
        if (state.current && state.current.id === id) {
          state.current = null;
          const next = activeMaps();
          if (next.length) await openMap(next[0].id);
          else {
            revokePhotoCache();
            photoCache = new Map();
            photoBlobCache = new Map();
            clearCanvas();
          }
        }
      }

      sortMaps(state.maps);
      this.lastSyncedAt = Date.now();
      if (this.status === "broken") this.status = "ok";
      this.consecutivePollFailures = 0;
      if (!downloadFailed) {
        this.freshUntil = listedAt + this.FRESH_WINDOW_MS;
        this.conflictDetected = false;
      } else {
        this.conflictDetected = true;
      }
      if (targets.length) this.setSyncProgress("Drive download check complete", targets.length, targets.length, 70);
      else this.setSyncProgress("Drive is already up to date", 0, 0, 70);
      return changed;
    }
  };

  /* ---------------- sync safety net ----------------
     Three helpers that keep "synced" honest and stop a refresh from
     discarding work that never reached Drive. */

  // For every map, the version stamp it had the last time this device
  // KNEW it matched Drive (right after a download, or right after an
  // upload that actually succeeded). A map whose own updatedAt is above
  // this has edits Drive has never seen ("dirty"). Kept in localStorage
  // so it survives a reload — which is exactly when it matters.
  const SYNC_BASE_KEY = "branchline_sync_base_v1";
  function readSyncBases() {
    try { return JSON.parse(localStorage.getItem(SYNC_BASE_KEY) || "{}") || {}; }
    catch (e) { return {}; }
  }
  function getSyncBase(id) {
    const v = readSyncBases()[id];
    return typeof v === "number" ? v : undefined;
  }
  function setSyncBase(id, value) {
    try {
      const all = readSyncBases();
      all[id] = value;
      localStorage.setItem(SYNC_BASE_KEY, JSON.stringify(all));
    } catch (e) {}
  }

  // Version stamps come from each device's own clock, and the newest
  // stamp wins. A phone whose clock runs even a few seconds behind the PC
  // therefore stamped its NEWER edit with an OLDER number, so the next
  // download (or a refresh) quietly replaced it with the PC's copy. This
  // never stamps below what Drive already has, so a real edit always wins.
  function nextUpdatedAt(map) {
    const known = DriveDB.fileIndex && DriveDB.fileIndex[map.id];
    return Math.max(Date.now(), (map.updatedAt || 0) + 1, ((known && known.updatedAt) || 0) + 1);
  }

  // True while a local save or upload is still pending/running. Wrapped
  // because the variables live further down the file.
  function localSaveBusy() {
    try { return !!(unsavedEdits || persistTimer || persistInFlight); }
    catch (e) { return false; }
  }

  // Keeps a losing version instead of throwing it away: stores it as its
  // own map in the sidebar ("… (unsynced copy 9/20 14:05)"). `portable`
  // must be a self-contained map (photos inline, e.g. straight from Drive
  // or from inlinePhotosForPortableCopy).
  async function saveConflictCopy(portable, label) {
    try {
      const copy = JSON.parse(JSON.stringify(portable));
      const t = new Date();
      const pad = (n) => String(n).padStart(2, "0");
      copy.id = uid();
      copy.title = `${copy.title || "Untitled map"} (${label} ${t.getMonth() + 1}/${t.getDate()} ${pad(t.getHours())}:${pad(t.getMinutes())})`;
      copy.updatedAt = Date.now();
      copy.trashedAt = null;
      await ensurePhotosMigrated(copy);
      await DB.put(copy);
      state.maps.push(copy);
      showToast(`Kept a copy of the version that would have been overwritten: "${copy.title}"`);
      return copy;
    } catch (e) {
      console.error("Couldn't keep a conflict copy", e);
      return null;
    }
  }

  /* ---------------- node-level three-way merge ----------------
     Before this, ANY overlap (this device changed a map AND Drive's
     copy also changed since they last agreed) fell straight back to
     keeping the loser as a separate "conflict copy" map — safe, but it
     meant two people editing two *different* nodes of the same map
     always split into two maps instead of combining into one.

     This attempts a conservative three-way merge first: base (the tree
     as it stood the last time this device and Drive were known to
     agree — see getSyncSnapshot), local (this device's tree now), and
     remote (Drive's tree now). It only ever combines changes it's
     CERTAIN don't collide:
       - a node edited on only one side since base → take that side's edit
       - a node added on only one side → keep it
       - a node deleted on only one side → keep it anyway (losing a node
         is worse than an occasional node that should have been deleted
         coming back — the person can delete it again)
       - a node edited (or reparented) DIFFERENTLY on both sides → bail
         out of the whole merge immediately

     "Bail out" means throw MERGE_CONFLICT, which the caller catches and
     falls back to the exact old behavior (keep the loser as a separate
     map). So this can only ever make conflict copies rarer — it never
     makes the safety net weaker. */
  const MERGE_CONFLICT = Symbol("merge-conflict");

  function ownFieldsOf(node) {
    const { children, ...rest } = node || {};
    return rest;
  }

  // node id -> its parent's id (or null for the root), for every node in
  // the tree. Used to detect "moved to a different parent" — the one
  // kind of change this pass refuses to guess about.
  function buildParentMap(root) {
    const map = new Map();
    (function walk(node, parentId) {
      if (!node) return;
      map.set(node.id, parentId);
      (node.children || []).forEach(c => walk(c, node.id));
    })(root, null);
    return map;
  }

  // node id -> node, for every node in the tree.
  function buildNodeMap(root) {
    const map = new Map();
    (function walk(node) {
      if (!node) return;
      map.set(node.id, node);
      (node.children || []).forEach(walk);
    })(root);
    return map;
  }

  // Merges one node's own fields (not children) three ways. Returns the
  // merged own-fields object, or throws MERGE_CONFLICT if both sides
  // changed it differently since base.
  function mergeOwnFields(baseNode, localNode, remoteNode) {
    const baseOwn = JSON.stringify(ownFieldsOf(baseNode));
    const localOwn = JSON.stringify(ownFieldsOf(localNode));
    const remoteOwn = JSON.stringify(ownFieldsOf(remoteNode));
    if (localOwn === remoteOwn) return ownFieldsOf(localNode);
    if (localOwn === baseOwn) return ownFieldsOf(remoteNode); // only remote changed it
    if (remoteOwn === baseOwn) return ownFieldsOf(localNode); // only local changed it
    throw MERGE_CONFLICT; // both changed it, differently
  }

  // Merges the tree rooted at each of base/local/remote. baseParent is
  // only used to detect reparenting; a node whose parent differs between
  // local and remote (and neither matches base) is a move-vs-move
  // collision and bails the whole merge.
  function mergeTree(baseRoot, localRoot, remoteRoot, baseParent) {
    const baseNodes = buildNodeMap(baseRoot);
    const localNodes = buildNodeMap(localRoot);
    const remoteNodes = buildNodeMap(remoteRoot);
    const localParent = buildParentMap(localRoot);
    const remoteParent = buildParentMap(remoteRoot);

    function mergeSubtree(id) {
      const baseNode = baseNodes.get(id);
      const localNode = localNodes.get(id);
      const remoteNode = remoteNodes.get(id);
      if (!localNode && !remoteNode) return null; // gone from both — drop it
      if (!baseNode) {
        // New since base — can only exist on one side (ids are random),
        // so just keep that side's whole subtree untouched.
        const src = localNode || remoteNode;
        return { ...ownFieldsOf(src), children: (src.children || []).map(c => mergeSubtree(c.id)).filter(Boolean) };
      }
      if (!localNode || !remoteNode) {
        // Deleted on exactly one side — keep it rather than lose it, and
        // still walk its children against whichever copy survived.
        const src = localNode || remoteNode;
        return { ...mergeOwnFields(baseNode, src, src), children: (src.children || []).map(c => mergeSubtree(c.id)).filter(Boolean) };
      }
      // Present on both sides — check it wasn't moved to two different
      // new parents (a moved-here-and-there-differently collision).
      const lp = localParent.get(id), rp = remoteParent.get(id), bp = baseParent.get(id);
      if (lp !== bp && rp !== bp && lp !== rp) throw MERGE_CONFLICT;
      const own = mergeOwnFields(baseNode, localNode, remoteNode);
      const baseChildIds = new Set((baseNode.children || []).map(c => c.id));
      const localChildIds = (localNode.children || []).map(c => c.id);
      const remoteChildIds = (remoteNode.children || []).map(c => c.id);
      const ordered = [];
      const seen = new Set();
      localChildIds.concat(remoteChildIds).forEach(cid => {
        if (!seen.has(cid)) { seen.add(cid); ordered.push(cid); }
      });
      const children = ordered.map(mergeSubtree).filter(Boolean);
      return { ...own, children };
    }

    return mergeSubtree(baseRoot.id === localRoot.id && baseRoot.id === remoteRoot.id ? baseRoot.id : localRoot.id);
  }

  // Merges links (cross-connections between nodes, {id, a, b}) by
  // simple union on id, then drops any link pointing at a node the
  // merged tree no longer has (never dangling).
  function mergeLinks(baseLinks, localLinks, remoteLinks, mergedNodeIds) {
    const byId = new Map();
    (baseLinks || []).forEach(l => byId.set(l.id, l));
    (localLinks || []).forEach(l => byId.set(l.id, l));
    (remoteLinks || []).forEach(l => byId.set(l.id, l));
    return Array.from(byId.values()).filter(l => mergedNodeIds.has(l.a) && mergedNodeIds.has(l.b));
  }

  // Merges a whole map's content three ways: root tree, links, and
  // title. Returns { root, links, title } on success, or throws
  // MERGE_CONFLICT (caller should fall back to the old conflict-copy
  // behavior) if any part collided.
  function mergeMapContent(base, local, remote) {
    if (!base || !base.root || !local || !local.root || !remote || !remote.root) throw MERGE_CONFLICT;
    const baseParent = buildParentMap(base.root);
    const mergedRoot = mergeTree(base.root, local.root, remote.root, baseParent);
    if (!mergedRoot) throw MERGE_CONFLICT;
    // Safety net: if the merge somehow produced the same node id twice
    // (a corner case in reparenting this pass doesn't fully reason
    // about), refuse the merge rather than hand back a broken tree.
    const seenIds = new Set();
    let duplicate = false;
    (function walk(n) {
      if (!n) return;
      if (seenIds.has(n.id)) duplicate = true;
      seenIds.add(n.id);
      (n.children || []).forEach(walk);
    })(mergedRoot);
    if (duplicate) throw MERGE_CONFLICT;
    const links = mergeLinks(base.links, local.links, remote.links, seenIds);
    let title;
    if (local.title === remote.title) title = local.title;
    else if (local.title === base.title) title = remote.title;
    else if (remote.title === base.title) title = local.title;
    else throw MERGE_CONFLICT;
    return { root: mergedRoot, links, title };
  }

  // The last content both this device and Drive are known to have
  // agreed on for a map — the "base" a three-way merge compares
  // against. Stored in IndexedDB (via the generic handle store), not
  // localStorage, since a mind map's tree can be too big for
  // localStorage's much smaller quota. Best-effort: if it's missing,
  // callers just skip the merge attempt and fall back to the old
  // conflict-copy behavior, so a failed read here never breaks sync.
  async function getSyncSnapshot(id) {
    try { return await DB.getHandle("syncSnapshot:" + id); } catch (e) { return null; }
  }
  async function setSyncSnapshot(id, mapLike) {
    try {
      await DB.setHandle("syncSnapshot:" + id, {
        root: mapLike.root, links: mapLike.links || [], title: mapLike.title || ""
      });
    } catch (e) { console.error("Couldn't save sync snapshot", e); }
  }

  function driveSyncStatusText() {
    if (!DriveDB.lastSyncedAt) return "Google Drive verified";
    const label = relTime(DriveDB.lastSyncedAt);
    return "Drive verified " + (label === "now" ? "just now" : label + " ago");
  }

  // The sidebar's "Syncing…" text is easy to miss (small, tucked away,
  // not even visible if the sidebar is collapsed on mobile), and before
  // this the canvas gave zero indication that what it was showing might
  // still be the pre-sync local copy. This banner is loud on purpose —
  // anyone looking at the map itself, not just the sidebar, should know
  // not to treat it as final while a sync is still in flight.
  function updateStaleSyncBanner() {
    const banner = $("#stale-sync-banner");
    if (!banner) return;
    const stillSyncing = DriveDB.signedIn && !DriveDB.dataSynced && isOnline;
    // Drive has actually confirmed another device saved something newer
    // (see DriveDB.conflictDetected) — editing is paused until this
    // device catches up. Never true just because the routine poll
    // timer hasn't ticked yet.
    const checking = DriveDB.signedIn && DriveDB.dataSynced && isOnline
      && !driveLockReason() && DriveDB.conflictDetected;
    banner.classList.toggle("hidden", !(stillSyncing || checking));
    const text = $("#stale-sync-text");
    if (text) {
      const pct = Math.max(1, DriveDB.syncProgressPercent || 1);
      text.textContent = checking
        ? "\u23f3 Verifying the newest Google Drive version before editing \u2014 this prevents a stale phone/PC copy from overwriting newer work."
        : "\u23f3 Syncing Google Drive \u2014 " + pct + "%" + (DriveDB.syncPhase ? " \u00b7 " + DriveDB.syncPhase : "");
    }
  }

  // Why editing is locked *despite* being signed in, or null when it
  // isn't. Signed-out isn't listed here on purpose — that case already
  // has its own full-screen panel (see applySignedOutGate).
  function driveLockReason() {
    if (!DriveDB.signedIn) return null;
    if (!isOnline) return "offline";
    if (DriveDB.needsReauth) return "reauth";
    if (DriveDB.driveBroken()) return "broken";
    return null;
  }

  // The loud counterpart to the small sidebar status line. The sidebar
  // text is easy to miss — it's tiny, it's off to the side, and on
  // mobile the sidebar may not even be open — which is exactly how a
  // long editing session can happen on top of a dead Drive session. This
  // sits across the top of the map itself, in red, with the one button
  // that fixes it.
  function updateDriveLostBanner() {
    const banner = $("#drive-lost-banner");
    if (!banner) return;
    const reason = driveLockReason();
    banner.classList.toggle("hidden", !reason);
    if (!reason) return;
    const text = $("#drive-lost-text");
    const btn = $("#drive-lost-reconnect");
    if (text) {
      text.textContent = reason === "offline"
        ? "\u26a0\ufe0f No internet connection \u2014 editing is locked so nothing can be written to this device only and then lost."
        : reason === "reauth"
        ? "\u26a0\ufe0f Your Google session has expired \u2014 editing is locked until you reconnect. Nothing you've already typed is lost."
        : "\u26a0\ufe0f Changes aren't reaching Google Drive \u2014 editing is locked until the connection is back. Nothing you've already typed is lost.";
    }
    if (btn) btn.classList.toggle("hidden", reason === "offline");
  }

  function updateCloudSyncPill() {
    const pill = document.getElementById("cloud-sync-pill");
    if (!pill) return;
    let stateName = "warning";
    let label = "☁ Cloud: not connected";
    if (!DriveDB.signedIn) {
      stateName = "warning";
      label = "☁ Cloud: off";
    } else if (!isOnline) {
      stateName = "error";
      label = "☁ Cloud: offline";
    } else if (DriveDB.needsReauth) {
      stateName = "error";
      label = "☁ Cloud: reconnect";
    } else if (DriveDB.driveBroken()) {
      stateName = "error";
      label = "☁ Cloud: upload failed";
    } else if (!DriveDB.dataSynced || DriveDB.busy || DriveDB.pushingLocal || localSaveBusy()) {
      stateName = "syncing";
      const pct = Math.max(1, DriveDB.syncProgressPercent || 1);
      label = DriveDB.syncPhase ? ("☁ " + DriveDB.syncPhase + " · " + pct + "%") : ("☁ Cloud: syncing… " + pct + "%");
    } else {
      const m = state.current;
      const known = m && DriveDB.fileIndex[m.id];
      const dirty = !!(m && (!known || (m.updatedAt || 0) > (known.updatedAt || 0)));
      if (dirty || DriveDB.unsyncedMaps().length) {
        stateName = "syncing";
        label = "☁ Cloud: waiting…";
      } else {
        stateName = "verified";
        label = "✓ Cloud: verified";
      }
    }
    pill.dataset.state = stateName;
    pill.textContent = label;
    pill.title = stateName === "verified"
      ? "This map's latest revision was confirmed by Google Drive. Click for sync details."
      : "Click for Google Drive sync details.";
    try { updateSyncStatusModal(); } catch (e) {}
  }

  function updateDriveUI(overrideStatus) {
    const status = $("#drive-status");
    const btn = $("#btn-google-signin");
    const onlineDot = $("#online-indicator");
    updateStaleSyncBanner();
    updateDriveLostBanner();
    if (onlineDot) {
      onlineDot.classList.toggle("offline", !isOnline);
      onlineDot.title = isOnline ? "Online" : "Offline — editing paused";
    }
    if (!status || !btn) return;
    applySignedOutGate();
    // The button's own visibility/label always reflects the real
    // signedIn/needsReauth/dataSynced state, whether or not this call
    // is just passing an override status string (e.g. "Syncing…") —
    // otherwise a mid-sync call here would leave the button showing
    // "Sign in with Google" even though we're already signed in and
    // just waiting on the initial Drive sync to finish.
    const stillSyncing = DriveDB.signedIn && !DriveDB.dataSynced && isOnline;
    if (DriveDB.needsReauth || (DriveDB.driveBroken() && isOnline)) {
      btn.textContent = "Reconnect Google";
      btn.classList.remove("hidden");
    } else if (stillSyncing) {
      // Signed in, sync in flight: no action to take yet, so don't
      // show a "Sign in with Google" (or even "Sign out") button at all.
      btn.classList.add("hidden");
    } else if (DriveDB.signedIn) {
      btn.textContent = "Sign out";
      btn.classList.remove("hidden");
    } else {
      btn.textContent = "Sign in with Google";
      btn.classList.remove("hidden");
    }
    if (overrideStatus) {
      const pct = Math.max(1, DriveDB.syncProgressPercent || 1);
      status.textContent = DriveDB.syncPhase ? (DriveDB.syncPhase + " · " + pct + "%") : overrideStatus;
      updateCloudSyncPill();
      refreshEditLockUI();
      return;
    }
    if (!isOnline) {
      // Offline trumps everything else here — even a fully signed-in,
      // fully synced device can't edit right now, so say so plainly
      // rather than showing a stale "Synced …" line that implies
      // editing still works.
      status.textContent = "Offline — editing paused";
    } else if (DriveDB.needsReauth) {
      status.textContent = "Google session expired \u2014 editing paused";
    } else if (DriveDB.driveBroken()) {
      status.textContent = "Changes NOT on Drive \u2014 retrying, editing paused";
    } else if (DriveDB.signedIn && DriveDB.dataSynced && DriveDB.conflictDetected) {
      status.textContent = "Checking for a newer version\u2026 editing paused";
    } else if (DriveDB.signedIn && DriveDB.dataSynced && (DriveDB.pushingLocal || localSaveBusy())) {
      status.textContent = "Uploading changes\u2026";
    } else if (DriveDB.signedIn && DriveDB.dataSynced && DriveDB.unsyncedMaps().length) {
      status.textContent = "\u26a0 Changes not on Drive yet \u2014 retrying\u2026";
    } else if (DriveDB.signedIn) {
      status.textContent = driveSyncStatusText();
    } else {
      status.textContent = "Not synced to Google Drive";
    }
    updateCloudSyncPill();
    refreshEditLockUI();
  }

  // Keep the edit lock (and its status text) in sync with the browser's
  // actual connectivity, not just whatever it was when the page loaded.
  window.addEventListener("online", () => {
    isOnline = true;
    // Back online: silently verify Drive. Only a real newer remote copy
    // interrupts editing; routine checks stay out of the way.
    verifyLatestOnForeground();
  });
  window.addEventListener("offline", () => {
    isOnline = false;
    updateDriveUI();
  });

  /* ---------------- sign-in-required edit lock ----------------
     The app is read-only until the person signs in with Google — every
     mutation funnels through here (directly, or via pushUndo()'s guard
     below) so there's one place that decides whether an edit is allowed
     and one place that prompts sign-in when it isn't. */

  // Tracks the browser's connectivity so editing can also be blocked
  // while offline — being signed in + synced only proves the *last*
  // sync succeeded, not that this device can still reach Drive right
  // now. Kept as its own flag (rather than re-checking navigator.onLine
  // inline everywhere) so the online/offline listeners below have one
  // place to update and the rest of the gate logic stays simple.
  let isOnline = navigator.onLine;

  // Returning to the app now uses a silent metadata check instead of
  // blocking every tap behind a visible "checking latest" state. A real
  // newer Drive revision still triggers the conflict lock below.
  let foregroundDriveCheckSeq = 0;

  // Signed in + first sync done + online + Drive actually reachable, and
  // no confirmed newer copy sitting on Drive from another device. The
  // last one only ever becomes true from an actual Drive check that
  // found (or failed to fetch) something newer — never merely because
  // the routine poll timer hasn't run yet.
  function isEditingAllowed() {
    return !!DriveDB.signedIn && !!DriveDB.dataSynced && isOnline
      && !DriveDB.needsReauth && !DriveDB.driveBroken()
      && !DriveDB.conflictDetected;
  }

  // Set only while flushing already-typed work to disk as the lock comes
  // down (see flushEditsBeforeLock) — the flush itself calls pushUndo()
  // via commitNotesToNode(), which would otherwise be refused by the very
  // lock we're applying, throwing away the text we're trying to rescue.
  let finalFlushInProgress = false;

  // Thrown by pushUndo() when editing is blocked, so the rest of whatever
  // handler called it stops right where it is instead of mutating state
  // that then has no undo entry. It's caught nowhere on purpose: letting
  // it surface as an uncaught error in the console is harmless (it never
  // escapes the single event handler that triggered it) and is exactly
  // the signal a developer would want if something did slip past a guard.
  class EditBlockedError extends Error {
    constructor() { super("Editing is blocked until you sign in with Google."); }
  }

  let signinRequiredModalEl = null, signinRequiredSigninBtn = null, signinRequiredCancelBtn = null;
  function ensureSigninRequiredModal() {
    if (signinRequiredModalEl) return;
    signinRequiredModalEl = $("#signin-required-modal");
    if (!signinRequiredModalEl) return;
    signinRequiredSigninBtn = $("#signin-required-signin");
    signinRequiredCancelBtn = $("#signin-required-cancel");
    signinRequiredSigninBtn.addEventListener("click", () => {
      closeSigninRequiredModal();
      DriveDB.signIn(false).catch(err => alert(err.message || "Google sign-in failed."));
    });
    signinRequiredCancelBtn.addEventListener("click", closeSigninRequiredModal);
    signinRequiredModalEl.addEventListener("click", (e) => {
      if (e.target === signinRequiredModalEl) closeSigninRequiredModal();
    });
  }
  function openSigninRequiredModal() {
    ensureSigninRequiredModal();
    if (!signinRequiredModalEl) return;
    const heading = signinRequiredModalEl.querySelector("h2");
    const body = signinRequiredModalEl.querySelector("p");
    const stillSyncing = DriveDB.signedIn && !DriveDB.dataSynced && isOnline;
    const offline = !isOnline;
    const disconnected = driveLockReason() === "reauth" || driveLockReason() === "broken";
    const checkingNewer = DriveDB.signedIn && DriveDB.dataSynced && !offline && !disconnected
      && DriveDB.conflictDetected;
    if (heading) heading.textContent = offline
      ? "You're offline"
      : disconnected
      ? "Disconnected from Google Drive"
      : checkingNewer
      ? "Checking for a newer version\u2026"
      : (stillSyncing ? "Syncing\u2026" : "Sign in to edit");
    if (body) body.textContent = offline
      ? "Editing is paused until you're back online, so a change made here can't drift out of sync with your other devices. Reconnect and try again."
      : disconnected
      ? "Editing is paused because changes can't reach Drive right now \u2014 anything typed from here on would live only in this browser and disappear on a refresh. Everything already typed has been saved. Reconnect to carry on."
      : checkingNewer
      ? "Another device may have saved a newer version. Editing is paused until this device has confirmed (or downloaded) the latest one, so it can't be overwritten by an old copy. This only takes a moment \u2014 try again in a second."
      : stillSyncing
      ? "Hang on \u2014 making sure this device has your latest saved changes before you start editing, so a newer version from another device can't get overwritten. This only takes a moment."
      : "This map is read-only until you sign in with Google. Editing, undo/redo, and adding tasks, notes, or photos all need a signed-in session.";
    if (signinRequiredSigninBtn) {
      signinRequiredSigninBtn.textContent = disconnected ? "Reconnect Google" : "Sign in with Google";
      signinRequiredSigninBtn.classList.toggle("hidden", stillSyncing || offline || checkingNewer);
    }
    zoomModalOpen(signinRequiredModalEl);
  }
  function closeSigninRequiredModal() {
    zoomModalClose(signinRequiredModalEl);
  }

  // The single gate every edit attempt passes through: pops the sign-in
  // modal immediately and reports "blocked" if not signed in, otherwise
  // is a silent no-op and reports "allowed".
  function requireSignIn() {
    if (finalFlushInProgress) return true;
    if (isEditingAllowed()) return true;
    openSigninRequiredModal();
    return false;
  }

  // Keeps the always-visible chrome (undo/redo, the "+" FAB) looking
  // disabled while logged out, so the lock is visible before someone
  // even tries to edit — the modal above is still what actually enforces
  // it for anything not covered by a visible button (keyboard shortcuts,
  // drag, paste, context-menu actions, etc).
  // Everything already typed but not yet committed, pushed through to
  // IndexedDB the instant before the lock comes down. Without this, the
  // half-second of typing still sitting in the note editor's own
  // debounce (and any map edit still inside persist()'s 500ms window)
  // would be refused by the lock on its way out and silently dropped —
  // the person would watch the app lock itself and take their last
  // sentence with it.
  let editLockWasLocked = false;
  function flushEditsBeforeLock() {
    finalFlushInProgress = true;
    try {
      try { if (noteEditingId) flushNoteAutosave(); } catch (e) {}
      try { flushPersist(); } catch (e) {}
    } catch (e) {
      // Can fire harmlessly during boot, before the note editor's and
      // persist layer's own state exists yet — nothing to flush then.
    } finally {
      finalFlushInProgress = false;
    }
  }

  // Makes the open note editor genuinely read-only, rather than letting
  // someone keep typing into a box whose contents the lock would refuse
  // to commit. The toolbar and per-note actions are disabled via CSS
  // (see .note-locked in style.css) rather than each button's `disabled`
  // property, so unlocking doesn't have to re-derive which of them were
  // legitimately disabled on their own (undo/redo in particular).
  function applyNoteEditorLock(locked) {
    const modal = document.getElementById("note-modal");
    if (!modal) return;
    const body = document.getElementById("note-textarea");
    const title = document.getElementById("note-title-input");
    if (body) body.contentEditable = locked ? "false" : "true";
    if (title) title.readOnly = locked;
    modal.classList.toggle("note-locked", locked);
    const lockNote = document.getElementById("note-lock-banner");
    if (lockNote) lockNote.classList.toggle("hidden", !locked);
    if (locked && body && document.activeElement === body) body.blur();
  }

  function refreshEditLockUI() {
    const locked = !isEditingAllowed();
    if (locked && !editLockWasLocked) flushEditsBeforeLock();
    editLockWasLocked = locked;
    applyNoteEditorLock(locked);
    if (!locked) closeSigninRequiredModal();
    document.body.classList.toggle("edit-locked", locked);
    const fabAddChild = $("#fab-add-child");
    const fabAddSibling = $("#fab-add-sibling");
    if (fabAddChild) fabAddChild.classList.toggle("locked", locked);
    if (fabAddSibling) fabAddSibling.classList.toggle("locked", locked);
    const titleInputEl = $("#title-input");
    if (titleInputEl) titleInputEl.readOnly = locked;
    updateUndoRedoButtons();
  }

  // Signing in only syncs once, at that moment — without this, a change
  // made on another device wouldn't show up here until you next reload
  // (or manually sign in again). Polls every DRIVE_POLL_INTERVAL_MS (10s)
  // while the tab is actually visible (skipped in background tabs to save
  // battery/quota), plus once immediately whenever you switch back to
  // this tab.
  let driveSyncTimer = null;
  // Set when a poll pulled in remote changes that the screen doesn't show
  // yet; cleared once the map/sidebar have actually been redrawn. Needed
  // because a poll can find changes while an edit is in progress (redraw
  // must wait) and the *next* poll will see nothing new to report.
  let driveRenderPending = false;
  function startDriveSyncPolling() {
    stopDriveSyncPolling();
    driveSyncTimer = setInterval(pollDriveUpdates, DRIVE_POLL_INTERVAL_MS);
  }
  function stopDriveSyncPolling() {
    if (driveSyncTimer) { clearInterval(driveSyncTimer); driveSyncTimer = null; }
  }
  async function pollDriveUpdates(force) {
    if (!DriveDB.signedIn || DriveDB.busy) return;
    if (document.visibilityState !== "visible") return;
    // Don't touch the map tree while you're actively mid-keystroke in a
    // node's text — an incoming update would swap out the very node
    // object your editor box is still pointing at. Same idea for
    // unsavedEdits: a change you just finished (blurred a node, dragged
    // something) can still be sitting in persist()'s debounce/awaits for
    // up to ~500ms+ after editingId clears, and pulling in a remote
    // version during that window would silently overwrite it.
    if (state.editingId || unsavedEdits) {
      // The full sync has to wait, but the freshness check must not:
      // otherwise a long edit would age out the "latest version" stamp
      // (locking mid-typing), and a newer copy saved by another device
      // in the meantime would go unnoticed.
      DriveDB.busy = true;
      try {
        await DriveDB.verifyRemote();
      } catch (e) {
        console.error("Drive freshness check failed", e);
        DriveDB.consecutivePollFailures++;
        if (DriveDB.consecutivePollFailures >= DriveDB.MAX_POLL_FAILURES && DriveDB.status !== "reauth") DriveDB.status = "broken";
      }
      DriveDB.busy = false;
      updateDriveUI();
      return;
    }
    DriveDB.busy = true;
    try {
      if (await DriveDB.syncFromDrive()) driveRenderPending = true;
      // Then the other direction: re-upload any map whose local copy is
      // newer than Drive's (an earlier upload that never finished — see
      // pushLocalNewer). `force` is true when this poll was triggered by
      // returning to the tab or coming back online, false for the interval timer.
      await DriveDB.pushLocalNewer({ force: force === true });
      // Re-check both conditions: either can flip from clear to set while
      // the syncFromDrive() network call above was in flight (the guards
      // above only ran before it started). If either did, don't blow away
      // whatever the user just started editing or hasn't finished saving —
      // a renderAll() here would tear down and refocus an active edit box
      // from outside the user's tap gesture (which is why the on-screen
      // keyboard would flash and immediately close on mobile), or clobber
      // a change that's still mid-save.
      // Only redraw when this poll (or an earlier one that had to wait)
      // actually brought in changes. This used to rebuild the sidebar AND
      // every node of the canvas from scratch on every poll tick even
      // when nothing had changed — which made the whole map stutter, and
      // dropped any click whose press and release straddled a rebuild
      // (the element pressed no longer exists, so no click event fires).
      if (driveRenderPending && !state.editingId && !unsavedEdits) {
        driveRenderPending = false;
        renderSidebar();
        renderAll();
      }
      DriveDB.consecutivePollFailures = 0;
    } catch (e) {
      console.error("Drive poll failed", e);
      // One failed poll is a network blip and not worth interrupting
      // anyone over; several in a row means this tab has genuinely lost
      // Drive, which the person needs to know before they type another
      // paragraph into it.
      DriveDB.consecutivePollFailures++;
      if (DriveDB.consecutivePollFailures >= DriveDB.MAX_POLL_FAILURES && DriveDB.status !== "reauth") {
        DriveDB.status = "broken";
        updateDriveUI();
      }
    }
    DriveDB.busy = false;
    DriveDB.setSyncProgress("", 0, 0);
    // The shared DRC queue lives in the small settings file rather than a
    // map file. Refresh that file occasionally while this tab stays open,
    // so a queue change made on another device arrives without a reload.
    if (Date.now() - taskTemplateLastSyncAt > 30000) syncTaskTemplatesWithDrive();
    // Refresh the "Synced Xm ago" label every tick regardless of whether
    // this particular poll changed anything — otherwise it'd only ever
    // update at the moment something actually synced, and would sit
    // frozen on a stale "2m ago" indefinitely once nothing new comes in.
    updateDriveUI();
  }
  async function verifyLatestOnForeground() {
    if (!DriveDB.signedIn || !DriveDB.dataSynced || !isOnline) return;

    const seq = ++foregroundDriveCheckSeq;
    try {
      // Let an already-running sync finish, but do not lock editing or
      // change the visible status just because the user returned to the tab.
      const started = Date.now();
      while (DriveDB.busy && Date.now() - started < 15000) {
        await new Promise(r => setTimeout(r, 120));
      }
      if (seq !== foregroundDriveCheckSeq || document.visibilityState !== "visible" || DriveDB.busy) return;

      // Metadata-only check first. In the normal case (nothing newer on
      // Drive) this is completely silent and causes no canvas rebuild.
      DriveDB.busy = true;
      try {
        await DriveDB.verifyRemote();
      } catch (e) {
        console.error("Silent foreground Drive check failed", e);
        DriveDB.consecutivePollFailures++;
        if (DriveDB.consecutivePollFailures >= DriveDB.MAX_POLL_FAILURES && DriveDB.status !== "reauth") {
          DriveDB.status = "broken";
          updateDriveUI();
        }
        return;
      } finally {
        DriveDB.busy = false;
      }

      if (seq !== foregroundDriveCheckSeq || document.visibilityState !== "visible") return;

      // Only interrupt the user when Drive actually contains a newer copy.
      // Then the existing conflict UI/lock is meaningful rather than routine.
      if (DriveDB.conflictDetected) {
        updateDriveUI();
        await pollDriveUpdates(true);
      }
    } finally {
      if (seq === foregroundDriveCheckSeq) updateDriveUI();
    }
  }

  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") {
      verifyLatestOnForeground();
      if (Date.now() - taskTemplateLastSyncAt > 30000) syncTaskTemplatesWithDrive();
    }
  });

  // "⟳ Load latest" — a manual, do-it-now version of the background poll,
  // for when you don't want to wait on (or trust) the automatic check:
  // saves whatever is pending, pulls down anything newer from Drive, then
  // uploads anything Drive is missing. Work on this device that Drive
  // never received is kept as a copy rather than overwritten (see
  // saveConflictCopy).
  const loadLatestBtn = document.getElementById("btn-load-latest");
  let loadLatestRunning = false;
  async function loadLatestFromDrive() {
    if (loadLatestRunning) return;
    if (!DriveDB.signedIn) {
      DriveDB.signIn(false).catch(err => alert(err.message || "Google sign-in failed."));
      return;
    }
    if (!isOnline) { showToast("You're offline \u2014 can't reach Google Drive"); return; }
    loadLatestRunning = true;
    const originalLabel = loadLatestBtn.textContent;
    loadLatestBtn.disabled = true;
    loadLatestBtn.textContent = "\u27f3 Loading\u2026";
    try {
      if (DriveDB.needsReauth) {
        // Session expired: an explicit sign-in (a real click) is the fix,
        // and it syncs on its own.
        await DriveDB.signIn(false);
        showToast("Reconnected and loaded the latest from Drive");
        return;
      }
      // Commit whatever is mid-edit, then let any save/upload/poll in
      // flight finish so nothing overlaps.
      try { if (document.activeElement && document.activeElement.blur) document.activeElement.blur(); } catch (e) {}
      try { flushPersist(); } catch (e) {}
      const t0 = Date.now();
      while ((DriveDB.busy || localSaveBusy()) && Date.now() - t0 < 15000) {
        await new Promise((r) => setTimeout(r, 200));
      }
      DriveDB.busy = true;
      let changed = false;
      try {
        changed = await DriveDB.syncFromDrive();
        DriveDB.status = "ok";
        await DriveDB.pushLocalNewer({ force: true });
      } finally {
        DriveDB.busy = false;
      }
      driveRenderPending = false;
      renderSidebar();
      renderAll();
      updateDriveUI();
      await syncTaskTemplatesWithDrive();
      if (DriveDB.driveBroken()) showToast("Loaded from Drive, but some of your changes still aren't uploading \u2014 retrying");
      else showToast(changed ? "\u2705 Loaded the latest from Drive" : "\u2705 Already on the latest version");
    } catch (e) {
      console.error("Load latest failed", e);
      showToast("Couldn't load from Drive: " + ((e && e.message) || e));
    } finally {
      DriveDB.setSyncProgress("", 0, 0);
      loadLatestRunning = false;
      loadLatestBtn.disabled = false;
      loadLatestBtn.textContent = originalLabel;
    }
  }
  loadLatestBtn.addEventListener("click", loadLatestFromDrive);

  // "⬆ Upload" — the push counterpart to "⟳ Load latest". Uploads the map
  // that's open right now to Google Drive immediately, for when you'd
  // rather not just trust that the automatic upload happened. It:
  //   1. commits anything mid-edit and lets in-flight saves finish,
  //   2. checks Drive first — if another device saved a NEWER copy of
  //      this map, it asks before replacing it and keeps that copy as its
  //      own map so nothing is lost (same rule as the background sync),
  //   3. force-uploads the map even if it already looks "synced",
  //   4. re-reads Drive afterwards to confirm the upload really landed.
  const uploadNowBtn = document.getElementById("btn-upload-now");
  let uploadNowRunning = false;
  async function uploadCurrentMapToDrive() {
    if (uploadNowRunning) return;
    if (!state.current) { showToast("Open a map first"); return; }
    if (!DriveDB.signedIn) {
      DriveDB.signIn(false).catch(err => alert(err.message || "Google sign-in failed."));
      return;
    }
    if (!isOnline) { showToast("You're offline \u2014 can't reach Google Drive"); return; }
    uploadNowRunning = true;
    const originalLabel = uploadNowBtn.textContent;
    uploadNowBtn.disabled = true;
    uploadNowBtn.textContent = "\u2b06 Uploading\u2026";
    let holdingFlags = false;
    try {
      if (DriveDB.needsReauth) {
        // Expired Google session: a real click is the fix.
        await DriveDB.signIn(false);
        if (!state.current) return;
      }
      // Commit whatever is mid-edit (including a note still in its
      // autosave debounce), then let any save/upload/poll in flight
      // finish so two uploads of the same map can't overlap.
      try { if (document.activeElement && document.activeElement.blur) document.activeElement.blur(); } catch (e) {}
      try { flushAllPendingSaves(); } catch (e) {}
      const t0 = Date.now();
      const busy = () => DriveDB.busy || DriveDB.pushingLocal || localSaveBusy();
      while (busy() && Date.now() - t0 < 20000) {
        await new Promise((r) => setTimeout(r, 200));
      }
      if (busy()) { showToast("Still saving \u2014 try Upload again in a moment"); return; }
      if (!state.current) return;

      // Claim the sync flags so the background poll doesn't start its own
      // upload of this same map while ours is running.
      DriveDB.busy = true;
      DriveDB.pushingLocal = true;
      holdingFlags = true;

      const map = state.current;
      const stamp = map.updatedAt || 0;
      const findRemote = async () => (await DriveDB.listRemote())
        .find(f => f.appProperties && f.appProperties.branchlineId === map.id);

      const before = await findRemote();
      if (before) {
        const remoteStamp = Number((before.appProperties && before.appProperties.updatedAt) || 0);
        // Make sure save() updates the existing Drive file rather than
        // creating a duplicate if this device hadn't indexed it yet.
        if (!DriveDB.fileIndex[map.id]) DriveDB.fileIndex[map.id] = { fileId: before.id, updatedAt: remoteStamp };
        if (remoteStamp > stamp) {
          const ok = confirm("Google Drive already has a NEWER version of this map (saved from another device).\n\nUploading will replace it with this device's version. Drive's version will be kept as a separate map in your list so nothing is lost.\n\nUpload anyway?");
          if (!ok) { showToast("Upload cancelled \u2014 tap \u27f3 Load latest to get Drive's newer version instead"); return; }
          let kept = null;
          try {
            const other = await DriveDB.downloadFile(before.id);
            if (other && other.root) kept = await saveConflictCopy(other, "other device");
          } catch (e) { console.error("Couldn't fetch Drive's newer copy", e); }
          if (!kept) { showToast("Couldn't back up Drive's newer copy first \u2014 nothing was uploaded"); return; }
          renderSidebar();
        }
      }

      await DriveDB.save(map, { skipRemoteGuard: true });
      if (DriveDB.driveBroken()) {
        showToast("\u26a0 Upload to Drive failed \u2014 check your connection and try again");
        return;
      }

      // Don't just trust that the PUT returned OK: ask Drive what it holds now.
      const after = await findRemote();
      const afterStamp = after ? Number((after.appProperties && after.appProperties.updatedAt) || 0) : 0;
      syncTaskTemplatesWithDrive();
      if (after && afterStamp >= stamp) {
        const name = (map.title || "Untitled map").slice(0, 40);
        showToast("\u2705 Uploaded \u201c" + name + "\u201d to Google Drive");
      } else {
        showToast("\u26a0 Upload finished but Drive doesn't show it yet \u2014 try again");
      }
    } catch (e) {
      console.error("Manual upload failed", e);
      showToast("Couldn't upload to Drive: " + ((e && e.message) || e));
    } finally {
      if (holdingFlags) { DriveDB.busy = false; DriveDB.pushingLocal = false; }
      uploadNowRunning = false;
      uploadNowBtn.disabled = false;
      uploadNowBtn.textContent = originalLabel;
      try { updateDriveUI(); } catch (e) {}
    }
  }
  uploadNowBtn.addEventListener("click", uploadCurrentMapToDrive);

  const cloudSyncPill = document.getElementById("cloud-sync-pill");
  const syncStatusModal = document.getElementById("sync-status-modal");
  const syncModalClose = document.getElementById("sync-modal-close");
  const syncModalCancel = document.getElementById("sync-modal-cancel");
  const syncModalNow = document.getElementById("sync-modal-now");
  let syncModalRunning = false;

  function syncStampText(stamp) {
    if (!stamp) return "Not uploaded yet";
    try {
      const d = new Date(Number(stamp));
      if (Number.isNaN(d.getTime())) return String(stamp);
      return d.toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit", second: "2-digit" });
    } catch (e) { return String(stamp); }
  }

  function updateSyncStatusModal() {
    if (!syncStatusModal) return;
    const hero = document.getElementById("sync-modal-hero");
    const stateEl = document.getElementById("sync-modal-state");
    const subEl = document.getElementById("sync-modal-substate");
    const mapEl = document.getElementById("sync-modal-map");
    const pendingEl = document.getElementById("sync-modal-pending");
    const lastEl = document.getElementById("sync-modal-last");
    const revisionEl = document.getElementById("sync-modal-revision");
    const tipEl = document.getElementById("sync-modal-tip");
    const progressEl = document.getElementById("sync-modal-progress");
    const progressFillEl = document.getElementById("sync-modal-progress-fill");
    const progressTextEl = document.getElementById("sync-modal-progress-text");

    const map = state.current;
    const known = map && DriveDB.fileIndex[map.id];
    const pendingCount = state.maps.filter((m) => {
      const k = DriveDB.fileIndex[m.id];
      return !k || (m.updatedAt || 0) > (k.updatedAt || 0);
    }).length;

    let mode = "warning";
    let heading = "Cloud sync is off";
    let detail = "Sign in with Google before editing on more than one device.";
    if (!DriveDB.signedIn) {
      mode = "warning";
    } else if (!isOnline) {
      mode = "error";
      heading = "Offline — not safe to switch devices";
      detail = "Reconnect to the internet so this device can verify its latest changes on Google Drive.";
    } else if (DriveDB.needsReauth) {
      mode = "error";
      heading = "Google reconnect required";
      detail = "Your Google session expired. Reconnect before continuing to edit.";
    } else if (DriveDB.driveBroken()) {
      mode = "error";
      heading = "Upload failed — changes are local only";
      detail = "The app is retrying. Do not switch devices until the status becomes Verified.";
    } else if (!DriveDB.dataSynced || DriveDB.busy || DriveDB.pushingLocal || localSaveBusy()) {
      mode = "syncing";
      heading = DriveDB.syncPhase || "Syncing…";
      const elapsed = DriveDB.syncStartedAt ? Math.max(1, Math.round((Date.now() - DriveDB.syncStartedAt) / 1000)) : 0;
      detail = "Comparing with Google Drive" + (elapsed ? (" · " + elapsed + "s elapsed") : "") + ". Large photo maps take longer because their Drive copy includes the photo bytes.";
    } else if (pendingCount > 0) {
      mode = "syncing";
      heading = "Waiting to upload " + pendingCount + (pendingCount === 1 ? " map" : " maps");
      detail = "Keep this tab open until the pending count reaches zero.";
    } else {
      mode = "verified";
      heading = "✓ Verified — safe to switch devices";
      detail = "Google Drive has confirmed the latest known revision. Your other device can now load it.";
    }

    const progressPct = mode === "verified"
      ? 100
      : (mode === "syncing" ? Math.max(1, DriveDB.syncProgressPercent || 1) : 0);
    if (hero) hero.dataset.state = mode;
    if (stateEl) stateEl.textContent = mode === "syncing" ? (heading + " · " + progressPct + "%") : heading;
    if (subEl) subEl.textContent = detail;
    if (progressEl) progressEl.classList.toggle("hidden", mode !== "syncing" && mode !== "verified");
    if (progressFillEl) progressFillEl.style.width = progressPct + "%";
    if (progressTextEl) progressTextEl.textContent = progressPct + "%";
    if (mapEl) mapEl.textContent = map ? ((map.title || "Untitled map") + " · " + syncStampText(map.updatedAt)) : "No map open";
    if (pendingEl) pendingEl.textContent = String(pendingCount);
    if (lastEl) {
      if (!DriveDB.lastSyncedAt) lastEl.textContent = "Not verified this session";
      else {
        const ago = relTime(DriveDB.lastSyncedAt);
        lastEl.textContent = ago === "now" ? "Just now" : ago + " ago";
      }
    }
    if (revisionEl) revisionEl.textContent = known ? syncStampText(known.updatedAt) : "Not on Drive yet";
    if (tipEl) tipEl.innerHTML = mode === "verified"
      ? "On your phone, wait for <b>Verified — safe to switch devices</b> before closing the tab or moving to your PC."
      : "Keep this device open until the status becomes <b>Verified — safe to switch devices</b>. If it stays here, press <b>Sync &amp; verify now</b>.";
    if (syncModalNow && !syncModalRunning) {
      syncModalNow.textContent = DriveDB.signedIn ? "⟳ Sync & verify now" : "Sign in with Google";
      syncModalNow.disabled = false;
    }
  }

  function openSyncStatusModal() {
    if (!syncStatusModal) return;
    updateSyncStatusModal();
    zoomModalOpen(syncStatusModal);
  }
  function closeSyncStatusModal() { zoomModalClose(syncStatusModal); }

  if (cloudSyncPill) cloudSyncPill.addEventListener("click", openSyncStatusModal);
  if (syncModalClose) syncModalClose.addEventListener("click", closeSyncStatusModal);
  if (syncModalCancel) syncModalCancel.addEventListener("click", closeSyncStatusModal);
  if (syncStatusModal) syncStatusModal.addEventListener("click", (e) => {
    if (e.target === syncStatusModal && !syncModalRunning) closeSyncStatusModal();
  });
  if (syncModalNow) syncModalNow.addEventListener("click", async () => {
    if (syncModalRunning) return;
    syncModalRunning = true;
    syncModalNow.disabled = true;
    syncModalNow.textContent = "⟳ Verifying…";
    try {
      if (!DriveDB.signedIn || DriveDB.needsReauth) {
        await DriveDB.signIn(false);
      } else {
        await loadLatestFromDrive();
      }
      // loadLatestFromDrive already performs pull -> merge -> push. One
      // extra metadata check on the open map gives the modal a very simple
      // final invariant: Drive's confirmed stamp must be at least the local
      // stamp before we tell the user it is safe to switch devices.
      const map = state.current;
      const known = map && DriveDB.fileIndex[map.id];
      if (map && known && isOnline && !DriveDB.driveBroken() && !DriveDB.needsReauth) {
        try {
          const remote = await DriveDB.readRemoteStamp(known.fileId);
          if (remote.updatedAt > (known.updatedAt || 0)) {
            // Drive changed again during our manual sync (another device
            // saved in the middle). Reconcile once more instead of showing
            // a false green "Verified" from the older fileIndex value.
            DriveDB.conflictDetected = true;
            DriveDB.freshUntil = 0;
            DriveDB.busy = true;
            try {
              await DriveDB.syncFromDrive();
              await DriveDB.pushLocalNewer({ force: true, includeNew: true });
            } finally {
              DriveDB.busy = false;
            }
          } else if (remote.updatedAt < (map.updatedAt || 0)) {
            await DriveDB.pushLocalNewer({ force: true, includeNew: true });
          }
        } catch (e) { console.error("Final sync verification failed", e); }
      }
    } catch (e) {
      console.error("Sync modal action failed", e);
      showToast("Couldn't verify Drive: " + ((e && e.message) || e));
    } finally {
      syncModalRunning = false;
      updateDriveUI();
      updateSyncStatusModal();
    }
  });

  /* ---------------- data model ---------------- */

  function newNode(text) {
    // `side` starts unset on every node. For a direct child of the root in
    // Mindmap layout it gets assigned "left"/"right" automatically the
    // first time it's laid out as a top-level branch — see layoutMindmap —
    // and then stays put across reorders. Any node at any depth can also
    // pick up an explicit "left"/"right" override once the user drags it
    // across the center line: that override makes its whole subtree fan
    // out the same direction as it, instead of blindly following whichever
    // side its parent branch happens to be on — see place() / placeLocal()
    // and maybeFlipSideOnDrop().
    //
    // `xGap` starts unset too. It's the horizontal distance from this
    // node's own parent, overriding the normal depth-based default (wider
    // for the root's direct children, ROOT_X_GAP, then X_GAP for every hop
    // after that). Set by right-clicking the connector above this node —
    // see openConnectorContextMenu() — and, unlike `side`, it only ever
    // affects this one node's own distance from its parent; descendants
    // keep using their own default (or their own override) measured onward
    // from wherever this node ends up.
    //
    // `connectorStyle` is null to inherit the map-wide arrow default, or
    // an explicit "line" (force no arrowhead) or "arrow" (force an
    // arrowhead) that overrides it for just this hop.
    //
    // `connectorShape` works the same way for the line's routing: null
    // inherits the map-wide "curved"/"elbow" default, or an explicit
    // value overrides it for just this hop. Both are set from the
    // combined "Connector style" picker on the connector's own
    // right-click menu, or in bulk from a parent node's menu.
    // `fontColor` is a per-node text color override — null to keep
    // inheriting whatever color the depth/branch rules (and the map-wide
    // custom font color, if the theme has one) would otherwise produce,
    // or an explicit hex string that wins over all of that. Set from the
    // "Font color" swatch row on the node's own right-click menu; a table
    // cell gets the same override on its own attach record instead (see
    // getCellAttach) so a single cell's text can be recolored without
    // affecting the rest of the table.
    return { id: uid(), text: text || "", children: [], collapsed: false, color: null, fontColor: null, struck: false, note: "", notes: [], image: null, images: [], url: null, urls: [], side: null, xGap: null, connectorStyle: null, connectorShape: null, table: null };
  }

  // A "table" node swaps its normal text label for a small editable grid
  // (node.table.cells, a rows x cols array of strings) — everything else
  // about it (drag, color, notes, photos, tasks, connectors...) works the
  // same as any other node. See addTableChild / computeTableBox / the
  // table-rendering branch of renderNode.
  function nodeIsTable(node) {
    return !!(node && node.table && Array.isArray(node.table.cells) && node.table.cells.length);
  }
  function defaultTableCells() {
    return [["", ""], ["", ""]];
  }

  // A table cell can carry the same small set of attachments a regular
  // node can (a photo, a note, a link, a task) — stored in a parallel
  // grid, node.table.attach[r][c], that's kept the same shape as
  // node.table.cells rather than folded into the cell's own text. Each
  // entry is `{ image, note, url, task: { text, done } }`, any of which
  // can be missing/null. ensureTableAttach pads/trims that grid to match
  // cells (rows/cols) on every render, so tableAddRow/Column/Remove*
  // don't each need their own bookkeeping for it — adding or removing a
  // row/column just works the next time the table is drawn.
  function ensureTableAttach(node) {
    if (!node.table) return [];
    const cells = node.table.cells;
    if (!Array.isArray(node.table.attach)) node.table.attach = [];
    const attach = node.table.attach;
    attach.length = cells.length;
    for (let r = 0; r < cells.length; r++) {
      if (!Array.isArray(attach[r])) attach[r] = [];
      attach[r].length = cells[r].length;
      for (let c = 0; c < cells[r].length; c++) {
        if (!attach[r][c] || typeof attach[r][c] !== "object") attach[r][c] = {};
      }
      node.table.attach[r] = attach[r];
    }
    // A row/column can only ever be removed from the end (see
    // tableRemoveRow/tableRemoveColumn), so a saved merge (see
    // mergeCellRange below) can end up pointing past the grid's current
    // bounds. Clip each merge to whatever's still there, and drop it
    // entirely once it no longer covers more than one cell — same
    // "sanitize on every render" spirit as the padding above, so no
    // removal call site needs its own merge bookkeeping.
    if (Array.isArray(node.table.merges) && node.table.merges.length) {
      const rows = cells.length;
      const cols = cells[0] ? cells[0].length : 0;
      node.table.merges = node.table.merges
        .map(m => ({ r0: m.r0, c0: m.c0, r1: Math.min(m.r1, rows - 1), c1: Math.min(m.c1, cols - 1) }))
        .filter(m => m.r0 <= m.r1 && m.c0 <= m.c1 && m.r0 < rows && m.c0 < cols && (m.r1 > m.r0 || m.c1 > m.c0));
    }
    return attach;
  }
  // A table cell can be merged with its neighbors into one rectangular
  // block — node.table.merges is a flat list of {r0, c0, r1, c1} rects
  // (inclusive), each naming the covered cells. The top-left cell of a
  // rect (r0, c0) is that block's "origin": it's the only one that
  // actually renders a <td> (with rowSpan/colSpan set to cover the rest —
  // see renderTableGrid), keeps its own text/attach record, and is what
  // buildCellIconStrip/openCellAddMenu are called with. The other cells
  // covered by the rect are simply skipped when rendering; their
  // underlying text/attach data is left untouched so unmerging restores
  // whatever was there before, rather than being lost.
  function ensureTableMerges(node) {
    if (!node.table) return [];
    if (!Array.isArray(node.table.merges)) node.table.merges = [];
    return node.table.merges;
  }
  function getCellMerge(node, r, c) {
    return ensureTableMerges(node).find(m => r >= m.r0 && r <= m.r1 && c >= m.c0 && c <= m.c1) || null;
  }
  function isMergeOrigin(node, r, c) {
    const m = getCellMerge(node, r, c);
    return !m || (m.r0 === r && m.c0 === c);
  }
  function cellSpan(node, r, c) {
    const m = getCellMerge(node, r, c);
    return m ? { rowSpan: m.r1 - m.r0 + 1, colSpan: m.c1 - m.c0 + 1 } : { rowSpan: 1, colSpan: 1 };
  }
  // Merges the rectangle between two corner cells. Any existing merge
  // that overlaps the new rectangle is dropped first — merging a
  // selection that partly overlaps other merged blocks folds everything
  // into one new block instead of leaving stale, now-inconsistent ones
  // behind.
  function mergeCellRange(node, r0, c0, r1, c1) {
    const merges = ensureTableMerges(node);
    const nr0 = Math.min(r0, r1), nr1 = Math.max(r0, r1);
    const nc0 = Math.min(c0, c1), nc1 = Math.max(c0, c1);
    node.table.merges = merges.filter(m => m.r1 < nr0 || m.r0 > nr1 || m.c1 < nc0 || m.c0 > nc1);
    node.table.merges.push({ r0: nr0, c0: nc0, r1: nr1, c1: nc1 });
  }
  function unmergeCellAt(node, r, c) {
    const merges = ensureTableMerges(node);
    const idx = merges.findIndex(m => r >= m.r0 && r <= m.r1 && c >= m.c0 && c <= m.c1);
    if (idx !== -1) merges.splice(idx, 1);
  }
  function getCellAttach(node, r, c) {
    const a = ensureTableAttach(node)[r][c];
    // A cell used to hold a single task as a.task = {text, done}. Tasks
    // are now a full list (a.tasks = [{id, text, done, stars, due,
    // subtasks, notes}]) matching node.tasks exactly, so a getNodeTasks/
    // nodeTaskProgress/the whole Tasks modal work unchanged on a cell —
    // this lazily upgrades an old single task into a one-item list the
    // first time the cell is touched, same spirit as the photo/note
    // migrations elsewhere in this file.
    if (a && a.task && a.task.text) {
      if (!Array.isArray(a.tasks)) a.tasks = [];
      a.tasks.push({ id: uid(), text: a.task.text, done: !!a.task.done, stars: 0, due: null });
    }
    if (a && a.task) a.task = null;
    return a;
  }
  function cellAttachHasAny(a) {
    return !!(a && (a.image || (a.images && a.images.length) || a.note || (a.notes && a.notes.length) || a.url || (a.urls && a.urls.length) || (a.tasks && a.tasks.length) || (a.affirmation && (a.affirmation.wins || a.affirmation.quote)) || a.timePlayedSec || (a.brainstorm && a.brainstorm.text)));
  }

  // A handful of features (the affirmation typing game, the countdown
  // "time played" timer) originally only ever lived on a whole node —
  // every one of their functions takes a node and reads/writes a couple
  // of plain fields on it (node.affirmation, node.timePlayedSec). A table
  // cell's attachment record (see getCellAttach above) is just as plain
  // an object, so instead of duplicating all of that logic for cells,
  // every call site now goes through a "target" — {nodeId, r, c}, with r
  // and c omitted for the node-level case — and resolveHost() below
  // returns whichever plain object (the node itself, or one cell's
  // attach record) that target actually refers to. Everything downstream
  // (getNodeAffirmation, getNodeTimePlayed, the game, the timer) keeps
  // working completely unchanged on top of whatever object comes back.
  function resolveHost(nodeId, r, c) {
    const node = findNode(nodeId);
    if (!node) return null;
    if (r == null || c == null) return node;
    if (!node.table) return null;
    return getCellAttach(node, r, c);
  }
  // Compares two targets ({nodeId, r, c}) for equality — used wherever a
  // running timer/game needs to check "is this the same target I'm
  // already showing/tracking", since two plain objects with the same
  // shape are never === to each other.
  function sameTarget(t1, t2) {
    if (!t1 || !t2) return t1 === t2;
    return t1.nodeId === t2.nodeId && (t1.r ?? null) === (t2.r ?? null) && (t1.c ?? null) === (t2.c ?? null);
  }
  // Every photo id currently attached to any cell of this node's table —
  // used alongside getNodeImageIds() wherever a node's photos need to be
  // enumerated for garbage collection, export, or Drive/folder sync, so a
  // cell's photo is treated as "in use" exactly like a node's own.
  function getCellImageIds(node) {
    if (!node || !node.table || !Array.isArray(node.table.attach)) return [];
    const ids = [];
    node.table.attach.forEach(row => (row || []).forEach(a => ids.push(...getCellPhotoIds(a))));
    return ids;
  }

  // Nodes used to hold a single `image` data-URL; they now hold an `images`
  // array of photo *ids* (see PhotoDB above) so multiple photos can be
  // attached without embedding their bytes in the node tree. This reads
  // either legacy shape so maps saved before that change still display
  // (ensurePhotosMigrated is what actually converts them to ids, but
  // rendering shouldn't have to wait on that finishing).
  function getNodeImageIds(node) {
    if (!node) return [];
    if (Array.isArray(node.images) && node.images.length) return node.images;
    if (node.image) return [node.image];
    return [];
  }
  // Resolves those ids to actual data URLs for rendering (img src,
  // background-image, canvas drawing, etc.) — every existing call site
  // that just wants to *look at* a node's photos keeps working exactly
  // as before; only code that needs the photo's stable identity (tags,
  // delete, drag/copy) should use getNodeImageIds instead.
  function getNodeImages(node) {
    return getNodeImageIds(node).map(id => (typeof id === "string" && id.startsWith("data:")) ? id : photoUrl(id));
  }
  function nodeHasImages(node) {
    return getNodeImageIds(node).length > 0;
  }

  // Photo tags are keyed by the photo's own (stable) id rather than its
  // index in `images`, so a tag stays attached to the right photo even
  // as photos are added, deleted, reordered, or dragged onto another
  // node — no index bookkeeping required.
  function getPhotoTags(node, photoId) {
    if (!node || !node.photoTags || !photoId) return [];
    return Array.isArray(node.photoTags[photoId]) ? node.photoTags[photoId] : [];
  }
  function setPhotoTags(node, photoId, tags) {
    if (!node || !photoId) return;
    if (!node.photoTags) node.photoTags = {};
    if (tags && tags.length) node.photoTags[photoId] = tags;
    else delete node.photoTags[photoId];
  }
  function addPhotoTag(node, photoId, tag) {
    const clean = (tag || "").trim().replace(/\s+/g, " ").slice(0, 24);
    if (!clean) return false;
    const tags = getPhotoTags(node, photoId);
    if (tags.some(t => t.toLowerCase() === clean.toLowerCase())) return false;
    setPhotoTags(node, photoId, tags.concat([clean]));
    return true;
  }
  function removePhotoTag(node, photoId, tag) {
    setPhotoTags(node, photoId, getPhotoTags(node, photoId).filter(t => t !== tag));
  }
  // When a photo is moved/copied onto another node (see completeMarkerDrop),
  // carry its tags along so they don't silently disappear. `idPairs` is a
  // list of [sourceId, targetId] — the same id for a move, a fresh id for
  // a copy (see duplicatePhotoRecord).
  function carryPhotoTags(source, target, idPairs) {
    if (!source || !target || !source.photoTags) return;
    (idPairs || []).forEach(([fromId, toId]) => {
      const tags = source.photoTags[fromId];
      if (!tags || !tags.length) return;
      if (!target.photoTags) target.photoTags = {};
      const existing = target.photoTags[toId] || [];
      target.photoTags[toId] = existing.concat(tags.filter(t => !existing.includes(t)));
    });
  }

  // Photo notes are the same rich, multi-entry note editor used for a
  // node's own notes, just scoped to one photo instead — keyed by the
  // photo's own (stable) id, same reasoning as photoTags above, so a
  // photo's notes stay attached to it through adds/deletes/reorders/
  // drags/crops. Each entry is `{id, title, html}`, identical shape to
  // a node's own `notes` array (see getNodeNotes) — the note editor
  // itself doesn't need to know which kind of target it's editing.
  function getPhotoNotes(node, photoId) {
    if (!node || !node.photoNotes || !photoId) return [];
    return Array.isArray(node.photoNotes[photoId]) ? node.photoNotes[photoId] : [];
  }
  function setPhotoNotes(node, photoId, notes) {
    if (!node || !photoId) return;
    if (!node.photoNotes) node.photoNotes = {};
    if (notes && notes.length) node.photoNotes[photoId] = notes;
    else delete node.photoNotes[photoId];
  }
  function photoHasNotes(node, photoId) {
    return getPhotoNotes(node, photoId).length > 0;
  }
  // Same carry-along behavior as carryPhotoTags — a moved/copied/cropped
  // photo keeps its notes rather than silently losing them.
  function carryPhotoNotes(source, target, idPairs) {
    if (!source || !target || !source.photoNotes) return;
    (idPairs || []).forEach(([fromId, toId]) => {
      const notes = source.photoNotes[fromId];
      if (!notes || !notes.length) return;
      if (!target.photoNotes) target.photoNotes = {};
      const existing = target.photoNotes[toId] || [];
      target.photoNotes[toId] = existing.concat(notes);
    });
  }

  // A single freeform comment per photo — same auto-growing textarea UI
  // as the video modal's inline comment box below the player (see
  // videoModalCommentInput), just anchored under the photo viewer
  // instead. Keyed by the photo's own (stable) id, same reasoning as
  // photoTags/photoNotes above, so a comment stays attached to the right
  // photo through adds/deletes/reorders/drags/crops.
  function getPhotoComment(node, photoId) {
    return (node && node.photoComments && node.photoComments[photoId]) || "";
  }
  function setPhotoComment(node, photoId, comment) {
    if (!node || !photoId) return;
    if (!node.photoComments) node.photoComments = {};
    const clean = (comment || "").trim();
    if (clean) node.photoComments[photoId] = clean;
    else delete node.photoComments[photoId];
  }
  // Same carry-along behavior as carryPhotoTags/carryPhotoNotes — a moved/
  // copied/cropped photo keeps its comment rather than silently losing it.
  function carryPhotoComments(source, target, idPairs) {
    if (!source || !target || !source.photoComments) return;
    (idPairs || []).forEach(([fromId, toId]) => {
      const comment = source.photoComments[fromId];
      if (!comment) return;
      if (!target.photoComments) target.photoComments = {};
      if (!target.photoComments[toId]) target.photoComments[toId] = comment;
    });
  }

  // A photo can be starred as a favorite, same "keyed by the photo's own
  // stable id" pattern as photoTags/photoNotes/photoComments above, so the
  // star stays attached to the right photo through adds/deletes/reorders/
  // drags/crops. Powers both the star toggle in the photo viewer and the
  // "Favorites" sidebar browser (see collectFavoriteItems).
  function getPhotoFavorite(node, photoId) {
    return !!(node && node.photoFavorites && photoId && node.photoFavorites[photoId]);
  }
  function setPhotoFavorite(node, photoId, val) {
    if (!node || !photoId) return;
    if (!node.photoFavorites) node.photoFavorites = {};
    if (val) node.photoFavorites[photoId] = true;
    else delete node.photoFavorites[photoId];
  }
  function togglePhotoFavorite(node, photoId) {
    setPhotoFavorite(node, photoId, !getPhotoFavorite(node, photoId));
    return getPhotoFavorite(node, photoId);
  }
  // Same carry-along behavior as carryPhotoTags/carryPhotoNotes/
  // carryPhotoComments — a moved/copied/cropped photo keeps its favorite
  // star rather than silently losing it.
  function carryPhotoFavorites(source, target, idPairs) {
    if (!source || !target || !source.photoFavorites) return;
    (idPairs || []).forEach(([fromId, toId]) => {
      if (!source.photoFavorites[fromId]) return;
      if (!target.photoFavorites) target.photoFavorites = {};
      target.photoFavorites[toId] = true;
    });
  }

  // When a photo was actually attached — keyed by the photo's own stable
  // id, same pattern as photoTags/photoNotes/photoComments/photoFavorites
  // above. Powers the "Photos" sidebar browser's Date sort (see
  // collectAllPhotos). Photos attached before this field existed have no
  // entry here; collectAllPhotos backfills one lazily (stamps it with
  // "now" the first time that photo is listed) rather than leaving it
  // permanently dateless — same lazy-backfill idea as a note's createdAt
  // (see captureActiveNote).
  function getPhotoTimestamp(node, photoId) {
    return (node && node.photoTimestamps && photoId && node.photoTimestamps[photoId]) || 0;
  }
  function setPhotoTimestamp(node, photoId, ts) {
    if (!node || !photoId) return;
    if (!node.photoTimestamps) node.photoTimestamps = {};
    if (ts) node.photoTimestamps[photoId] = ts;
    else delete node.photoTimestamps[photoId];
  }
  // Same carry-along behavior as carryPhotoFavorites — a moved/copied/
  // cropped photo keeps its "date added" rather than silently losing it
  // (and, for a move, looking freshly backfilled on the target node).
  function carryPhotoTimestamps(source, target, idPairs) {
    if (!source || !target || !source.photoTimestamps) return;
    (idPairs || []).forEach(([fromId, toId]) => {
      const ts = source.photoTimestamps[fromId];
      if (!ts) return;
      if (!target.photoTimestamps) target.photoTimestamps = {};
      target.photoTimestamps[toId] = ts;
    });
  }

  // On-canvas photo markers are tiny (9–18px), but a full photo is stored
  // at its original resolution (no downscaling) so the lightbox still
  // looks sharp — full quality, exactly as attached. Painting that
  // full-resolution bitmap as the background-image of a dozen little
  // thumbnails is what actually made the canvas heavy to composite once
  // a few photo-heavy nodes were on screen — every pan/drag frame has to
  // recomposite all of that
  // decoded pixel data even though only a handful of on-screen pixels are
  // ever visible. This cache holds a small, pre-cropped stand-in (keyed by
  // the full photo's own data URL, so it's computed once per photo and
  // reused everywhere that photo appears) built once and reused instead.
  // Sized for the worst case on-screen footprint of a "large" thumbnail
  // (18 CSS px) at max zoom (2.5x, see the zoom handlers) on a high-DPI
  // screen, with a little headroom — not a fixed guess — so photos stay
  // sharp all the way to full zoom instead of turning soft once the small
  // stand-in gets stretched past its own resolution.
  const THUMB_DISPLAY_PX = Math.round(clamp(18 * 2.5 * (window.devicePixelRatio || 1) * 1.15, 96, 240));
  // Bounded LRU: keyed by the *full* base64 photo data URL, so left
  // unbounded this grows forever across a session (every photo ever
  // viewed, in every map, stays resident — full-size base64 keys and
  // all) and was a real path to an "Out of memory" tab crash on long
  // sessions with lots of photos. Capped here so old entries get
  // evicted once the cache fills up instead of accumulating forever.
  const NODE_THUMB_CACHE_MAX = 300;
  const nodeThumbCache = new Map(); // full data URL -> small data URL
  const nodeThumbPending = new Set(); // full data URLs queued or in flight
  // A cold render of a photo-heavy map (thumbnail cache empty) used to call
  // getMarkerThumb for every node's photos in one synchronous pass, which
  // fired off a full-resolution decode for each one at the same time —
  // dozens/hundreds of concurrent decodes, each holding tens of MB of raw
  // pixel data, was a real "Out of memory" tab-crash path even though the
  // *cached* thumbnails themselves are tiny. Capped here so only a handful
  // of photos are ever being decoded at once; the rest wait in line and
  // pick up the (still-correct) full-res fallback image until their turn.
  const NODE_THUMB_MAX_CONCURRENT = 4;
  let nodeThumbActive = 0;
  const nodeThumbQueue = [];
  function runNextThumbJob() {
    if (nodeThumbActive >= NODE_THUMB_MAX_CONCURRENT) return;
    const job = nodeThumbQueue.shift();
    if (!job) return;
    nodeThumbActive++;
    const { fullDataUrl, onReady } = job;
    const finish = () => {
      nodeThumbActive--;
      nodeThumbPending.delete(fullDataUrl);
      runNextThumbJob();
    };
    const img = new Image();
    img.onload = () => {
      try {
        const side = Math.min(img.width, img.height) || 1;
        const sx = (img.width - side) / 2, sy = (img.height - side) / 2;
        const canvas = document.createElement("canvas");
        canvas.width = THUMB_DISPLAY_PX;
        canvas.height = THUMB_DISPLAY_PX;
        canvas.getContext("2d").drawImage(img, sx, sy, side, side, 0, 0, THUMB_DISPLAY_PX, THUMB_DISPLAY_PX);
        if (nodeThumbCache.size >= NODE_THUMB_CACHE_MAX) {
          const oldestKey = nodeThumbCache.keys().next().value;
          nodeThumbCache.delete(oldestKey);
        }
        nodeThumbCache.set(fullDataUrl, canvas.toDataURL("image/jpeg", 0.7));
        onReady();
      } finally {
        // Drop the full-res <img> reference immediately so it (and its
        // decoded bitmap) is eligible for GC right away rather than
        // lingering until this closure itself is collected.
        img.onload = img.onerror = null;
        finish();
      }
    };
    img.onerror = () => { finish(); };
    img.src = fullDataUrl;
  }
  function getMarkerThumb(fullDataUrl, onReady) {
    const cached = nodeThumbCache.get(fullDataUrl);
    if (cached) {
      // Refresh recency: delete + re-set moves this key to the end of
      // the Map's iteration order, which is what makes "delete the
      // first key" below an actual least-recently-used eviction.
      nodeThumbCache.delete(fullDataUrl);
      nodeThumbCache.set(fullDataUrl, cached);
      return cached;
    }
    if (!nodeThumbPending.has(fullDataUrl)) {
      nodeThumbPending.add(fullDataUrl);
      nodeThumbQueue.push({ fullDataUrl, onReady });
      runNextThumbJob();
    }
    return null;
  }

  // Nodes used to hold a single freeform `note` string; they now hold a
  // `notes` array (each `{id, html}`) so more than one note can be
  // attached. This reads either shape so maps saved before the change
  // still work without a migration step.
  function getNodeNotes(node) {
    if (!node) return [];
    if (Array.isArray(node.notes) && node.notes.length) return node.notes;
    if (node.note && node.note.trim()) return [{ id: uid(), title: "", html: node.note }];
    return [];
  }
  function nodeHasNotes(node) {
    return getNodeNotes(node).length > 0;
  }

  // A task's notes use the exact same rich, multi-entry note editor as a
  // node's own notes (see getNodeNotes above and openNoteModal below) —
  // title, rich text, multiple notes with paging, all of it — just scoped
  // to one task instead of the whole node. Reads either the old single
  // plain/HTML `note` string (from before this existed) or the new
  // `notes` array, same fallback shape as getNodeNotes.
  function getTaskNotes(t) {
    if (!t) return [];
    if (Array.isArray(t.notes) && t.notes.length) return t.notes;
    if (t.note && t.note.trim()) return [{ id: uid(), title: "", html: t.note }];
    return [];
  }
  function taskHasNotes(t) {
    return getTaskNotes(t).length > 0;
  }

  // A table cell's note uses the exact same rich, multi-entry note editor
  // as a node's own notes (see getNodeNotes/openNoteModal) — title, rich
  // text, multiple notes with paging, all of it — just scoped to one
  // cell's attach record instead of the whole node. Reads either the old
  // single plain-text `note` string (from before this existed) or the
  // new `notes` array, same fallback shape as getNodeNotes/getTaskNotes.
  function getCellNotes(a) {
    if (!a) return [];
    if (Array.isArray(a.notes) && a.notes.length) return a.notes;
    if (a.note && a.note.trim()) return [{ id: uid(), title: "", html: a.note }];
    return [];
  }
  function cellHasNotes(a) {
    return getCellNotes(a).length > 0;
  }

  // A table cell's photos use the exact same multi-photo model as a
  // node's own photos (see getNodeImageIds/getNodeImages above) — an
  // array of PhotoDB ids — just scoped to one cell's attach record
  // instead of the whole node. Reads either the old single plain `image`
  // id (from before this existed) or the new `images` array, same
  // fallback shape as getNodeImageIds.
  function getCellPhotoIds(a) {
    if (!a) return [];
    if (Array.isArray(a.images) && a.images.length) return a.images;
    if (a.image) return [a.image];
    return [];
  }
  function getCellPhotos(a) {
    return getCellPhotoIds(a).map(id => (typeof id === "string" && id.startsWith("data:")) ? id : photoUrl(id));
  }
  function cellHasImages(a) {
    return getCellPhotoIds(a).length > 0;
  }

  // Short label for a note, for the menus below — its title if it has
  // one, otherwise a plain-text preview of the body.
  function notePreviewText(n) {
    const title = (n.title || "").trim();
    if (title) return title.length > 40 ? title.slice(0, 39) + "…" : title;
    const tmp = document.createElement("div");
    tmp.innerHTML = n.html || "";
    const text = (tmp.textContent || "").replace(/\s+/g, " ").trim();
    if (!text) return "(empty note)";
    return text.length > 40 ? text.slice(0, 39) + "…" : text;
  }

  // Right-click on a note marker — same shape as openUrlManageMenu: each
  // row opens that note in the editor, plus a ✕ to delete it on the spot
  // without opening the editor. A "+" button up in the header gives a
  // fast one-click way to start a brand-new note, without having to
  // scan down past however many notes are already listed below it.
  function openNoteManageMenu(nodeId, x, y) {
    const node = findNode(nodeId);
    if (!node) return;
    const notes = getNodeNotes(node);
    if (!notes.length) return;
    resetContextMenu();

    const header = document.createElement("div");
    header.className = "ctx-item ctx-item-header";
    header.style.cursor = "default";
    const headerLabel = document.createElement("span");
    headerLabel.className = "ctx-item-label";
    headerLabel.textContent = `Notes (${notes.length})`;
    header.appendChild(headerLabel);
    const addBtn = document.createElement("span");
    addBtn.className = "ctx-item-add";
    addBtn.textContent = "+";
    addBtn.title = "Add a new note";
    addBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      closeContextMenu();
      openNoteModal(nodeId, notes.length);
    });
    header.appendChild(addBtn);
    ctxMenu.appendChild(header);

    notes.forEach((n, i) => {
      const it = document.createElement("div");
      it.className = "ctx-item";
      const labelSpan = document.createElement("span");
      labelSpan.className = "ctx-item-label";
      if (isDRCNote(n)) {
        // DRC notes get the same notebook+pencil image as everywhere else.
        labelSpan.textContent = notePreviewText(n);
        labelSpan.prepend(drcIconEl(16));
      } else if (isPlanNote(n)) {
        labelSpan.textContent = notePreviewText(n);
        labelSpan.prepend(planIconEl(16));
      } else {
        labelSpan.textContent = "📝 " + notePreviewText(n);
      }
      labelSpan.addEventListener("click", () => { closeContextMenu(); openNoteModal(nodeId, i); });
      it.appendChild(labelSpan);
      const removeBtn = document.createElement("span");
      removeBtn.className = "ctx-item-remove";
      removeBtn.textContent = "✕";
      removeBtn.title = "Delete this note";
      removeBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        pushUndo();
        const remaining = getNodeNotes(node).slice();
        remaining.splice(i, 1);
        node.notes = remaining;
        node.note = "";
        closeContextMenu();
        renderAll();
        persist();
      });
      it.appendChild(removeBtn);
      ctxMenu.appendChild(it);
    });
    positionContextMenu(x, y);
  }

  // Nodes used to hold a single `url` string; they now hold a `urls` array
  // so multiple links can be attached. This reads either shape so maps
  // saved before the change still work without a migration step.
  function getNodeUrls(node) {
    if (!node) return [];
    if (Array.isArray(node.urls) && node.urls.length) return node.urls;
    if (node.url) return [node.url];
    return [];
  }
  function nodeHasUrls(node) {
    return getNodeUrls(node).length > 0;
  }

  // A link's display title is kept separate from the URL itself — stored
  // on the node as { [url]: title }, content-addressed the same way photo
  // tags used to be (a URL, unlike a photo's bytes, IS a stable identity
  // on its own, so there's no need for the id-store treatment photos got —
  // see getNodeImageIds/PhotoDB above). Populated either by fetchLinkTitle
  // (best-effort, see below) or by hand via "Rename link…".
  function getLinkTitle(node, url) {
    return (node && node.linkTitles && node.linkTitles[url]) || "";
  }
  // A short freeform note about one specific link, independent of its
  // title — stored the same way as linkTitles (an { [url]: text } map on
  // the node), and surfaced as a tooltip when hovering the link's icon
  // (see attachLinkCommentTooltip) rather than inside any menu text.
  function getLinkComment(node, url) {
    return (node && node.linkComments && node.linkComments[url]) || "";
  }
  function setLinkComment(node, url, comment) {
    if (!node || !url) return;
    if (!node.linkComments) node.linkComments = {};
    const clean = (comment || "").trim();
    if (clean) node.linkComments[url] = clean;
    else delete node.linkComments[url];
  }
  function setLinkTitle(node, url, title) {
    if (!node || !url) return;
    if (!node.linkTitles) node.linkTitles = {};
    const clean = (title || "").trim();
    if (clean) node.linkTitles[url] = clean;
    else delete node.linkTitles[url];
  }
  // Photo(s) attached to a link's comment — e.g. a screenshot pasted into
  // the YouTube player's comment box. Stored as an ordered list of
  // PhotoDB ids, same { [url]: ... } map shape as linkComments/
  // linkFavorites above, so a link can carry several photos alongside
  // its text comment.
  function getLinkPhotos(node, url) {
    return (node && node.linkPhotos && node.linkPhotos[url]) || [];
  }
  function addLinkPhoto(node, url, dataUrl) {
    if (!node || !url) return null;
    const id = addPhotoRecord(dataUrl, { avoid: getLinkPhotos(node, url) });
    if (!node.linkPhotos) node.linkPhotos = {};
    if (!node.linkPhotos[url]) node.linkPhotos[url] = [];
    node.linkPhotos[url].push(id);
    return id;
  }
  function removeLinkPhoto(node, url, photoId) {
    if (!node || !node.linkPhotos || !node.linkPhotos[url]) return;
    node.linkPhotos[url] = node.linkPhotos[url].filter((id) => id !== photoId);
    if (!node.linkPhotos[url].length) delete node.linkPhotos[url];
    deletePhotoRecord(photoId);
  }
  // A link (or, since a YouTube URL is just a link that opens in the video
  // player, a video too) can be starred as a favorite — same { [url]: true }
  // map on the node as linkTitles/linkComments. Powers the star toggle in
  // the link comment modal and the video modal, and the "Favorites"
  // sidebar browser (see collectFavoriteItems).
  function getLinkFavorite(node, url) {
    return !!(node && node.linkFavorites && url && node.linkFavorites[url]);
  }
  function setLinkFavorite(node, url, val) {
    if (!node || !url) return;
    if (!node.linkFavorites) node.linkFavorites = {};
    if (val) node.linkFavorites[url] = true;
    else delete node.linkFavorites[url];
  }
  function toggleLinkFavorite(node, url) {
    setLinkFavorite(node, url, !getLinkFavorite(node, url));
    return getLinkFavorite(node, url);
  }
  // Carries link titles along when links are dragged onto another node
  // (see completeMarkerDrop's "urls" branch) — same idea as carryPhotoTags.
  function carryLinkTitles(source, target, urls) {
    if (!source || !target || !source.linkTitles) return;
    urls.forEach((u) => {
      const title = source.linkTitles[u];
      if (!title) return;
      if (!target.linkTitles) target.linkTitles = {};
      if (!target.linkTitles[u]) target.linkTitles[u] = title;
    });
  }

  // When a URL was actually added to a node — same { [url]: ts } map shape
  // as linkTitles/linkFavorites above. Powers the "Videos" sidebar
  // browser's Date sort (see collectAllVideos). Links added before this
  // field existed have no entry here; collectAllVideos backfills one
  // lazily the first time that link is listed, same idea as
  // getPhotoTimestamp above / a note's createdAt (see captureActiveNote).
  function getLinkTimestamp(node, url) {
    return (node && node.linkTimestamps && url && node.linkTimestamps[url]) || 0;
  }
  function setLinkTimestamp(node, url, ts) {
    if (!node || !url) return;
    if (!node.linkTimestamps) node.linkTimestamps = {};
    if (ts) node.linkTimestamps[url] = ts;
    else delete node.linkTimestamps[url];
  }
  // Same carry-along behavior as carryLinkTitles — a moved/copied link
  // keeps its "date added" instead of looking freshly backfilled on the
  // target node.
  function carryLinkTimestamps(source, target, urls) {
    if (!source || !target || !source.linkTimestamps) return;
    urls.forEach((u) => {
      const ts = source.linkTimestamps[u];
      if (!ts) return;
      if (!target.linkTimestamps) target.linkTimestamps = {};
      if (!target.linkTimestamps[u]) target.linkTimestamps[u] = ts;
    });
  }
  // Best-effort: tries to get the target page's actual title so the link
  // list can show a real name instead of the raw URL.
  //
  // For most ordinary websites this quietly does nothing: it only works
  // when the target server's CORS policy allows a cross-origin fetch of
  // the page (most sites don't set that header), and it's even less
  // likely to succeed at all when this app is opened as a local file
  // rather than served over http/https — which is exactly why
  // "Rename link…" exists as the reliable fallback.
  //
  // YouTube was assumed to be a reliable exception via its public "oEmbed"
  // endpoint (meant for other pages to read a video's title without
  // scraping/signing in) — but in practice YouTube's oEmbed response does
  // NOT include an Access-Control-Allow-Origin header, so the browser
  // blocks a direct fetch() to it with a CORS error, same as almost every
  // other site. This code path is kept in case a CORS-friendly proxy is
  // added later, but today it never actually succeeds — "Rename link…" is
  // the only reliable way to set a name for any link, YouTube included.
  function youtubeVideoId(u) {
    try {
      const p = new URL(u);
      const host = p.hostname.toLowerCase().replace(/^www\.|^m\./, "");
      if (host === "youtu.be") return p.pathname.slice(1) || null;
      if (host === "youtube.com") {
        if (p.pathname === "/watch") return p.searchParams.get("v");
        const m = p.pathname.match(/^\/(shorts|embed|live)\/([^/?]+)/);
        if (m) return m[2];
      }
    } catch (e) { /* not a parseable URL */ }
    return null;
  }

  // NOTE: YouTube's oEmbed endpoint does NOT send an Access-Control-Allow-Origin
  // header, so a direct browser fetch() to it is CORS-blocked in every browser,
  // every time — it is not actually more reliable than any other site. This
  // used to be assumed to work and silently never did; kept here only so a
  // future CORS proxy can be swapped in, but for now this always falls
  // through to the catch block below and the raw URL/manual rename is used.
  async function fetchLinkTitle(node, url) {
    let title = null;
    const ytId = youtubeVideoId(url);
    try {
      if (ytId) {
        const res = await fetch(`https://www.youtube.com/oembed?url=${encodeURIComponent(url)}&format=json`);
        if (res.ok) title = (await res.json()).title;
      } else {
        const res = await fetch(url, { mode: "cors" });
        if (res.ok) title = new DOMParser().parseFromString(await res.text(), "text/html").title;
      }
    } catch (e) {
      // CORS-blocked, offline, or unreachable — leave the URL as the label.
      // Logged (not surfaced to the user) so this failure is at least
      // visible in devtools instead of vanishing silently.
      console.warn("Branchline: couldn't auto-fetch link title for", url, e);
    }
    title = (title || "").trim();
    // Re-fetch the live node/url by identity — several seconds may have
    // passed, during which the node could have been deleted or this
    // exact URL removed/edited away, or the person could have already
    // set their own title manually (which should win over an auto one).
    const liveNode = findNode(node.id);
    if (!title || !liveNode || !getNodeUrls(liveNode).includes(url) || getLinkTitle(liveNode, url)) return;
    setLinkTitle(liveNode, url, title.slice(0, 80));
    renderAll();
    persist();
  }

  // Per-node checklist ("today's tasks"). Stored as node.tasks = [{id,
  // text, done}], separate from the freeform note so progress can be
  // computed and shown right on the node in the mindmap.
  function getNodeTasks(node) {
    if (!(node && Array.isArray(node.tasks))) return [];
    if (!node.starsReset) {
      // One-time reset for lists saved under the old 3-star / 3x rules:
      // every existing star is removed (even a lone one), then the list is
      // marked so stars the user adds from now on are kept. Same
      // lazy-upgrade idea as getCellAttach below, so it covers maps loaded
      // from anywhere (this browser, Drive, an import), and it's saved
      // along with the next normal save.
      node.tasks.forEach((t) => {
        if (t && getTaskStars(t) > 0) { t.stars = 0; t.starred = false; }
      });
      node.starsReset = true;
    } else {
      enforceSingleStar(node.tasks);
    }
    return node.tasks;
  }
  // Safety net: only one starred task is allowed per list (see
  // MAX_STARRED_TASKS). If a list somehow ends up with more than one (e.g. a
  // copy synced from a device on an older version), all its stars are removed.
  function enforceSingleStar(tasks) {
    let starred = 0;
    for (let i = 0; i < tasks.length; i++) {
      if (tasks[i] && getTaskStars(tasks[i]) > 0) starred++;
    }
    if (starred <= MAX_STARRED_TASKS) return;
    tasks.forEach((t) => {
      if (t && getTaskStars(t) > 0) { t.stars = 0; t.starred = false; }
    });
  }
  function nodeHasTasks(node) {
    return getNodeTasks(node).length > 0;
  }
  // Tasks carry a 0–1 "stars" priority flag, used only for progress
  // weighting (see nodeTaskProgress) — it does not affect task order.
  // Also tolerates old maps saved before this existed, which only ever
  // had a boolean `starred` flag, treated as 1 star. Old maps saved
  // while 2/3-star levels existed are clamped down to 1.
  function getTaskStars(t) {
    if (typeof t.stars === "number" && !Number.isNaN(t.stars)) return clamp(Math.round(t.stars), 0, 1);
    return t.starred ? 1 : 0;
  }
  // Only 1 task per task list (node or table cell) can be starred at
  // once — starring another is blocked until the current one is unstarred.
  // Lists saved before this limit have all their stars removed once (see
  // getNodeTasks / enforceSingleStar).
  const MAX_STARRED_TASKS = 1;
  // How many times more a starred task counts toward progress.
  const STARRED_TASK_WEIGHT = 10;
  function taskStarCapReached(host) {
    return getNodeTasks(host).filter(x => getTaskStars(x) > 0).length >= MAX_STARRED_TASKS;
  }
  function blockedByStarCap(host, t) {
    if (getTaskStars(t) > 0 || !taskStarCapReached(host)) return false;
    showToast("Only 1 starred task allowed — unstar the other one first");
    return true;
  }
  // A task's optional color label — one swatch from the same shared
  // PALETTE used for node/branch/font colors, shown as a light tinted
  // fill on the whole task row. Purely a visual tag: doesn't affect
  // progress, sorting, or the star-priority system above. Absent (no
  // `color` field) means "no color".
  function getTaskColor(t) {
    return (t && t.color) || null;
  }
  function setTaskColor(t, color) {
    if (!t) return;
    if (color) t.color = color;
    else delete t.color;
  }
  // Converts a task's color (a "#rrggbb" PALETTE swatch) into a low-alpha
  // rgba() fill so it reads as a light tint behind the row's text/icons
  // rather than a solid block. Returns null for no color.
  function taskColorTint(color) {
    if (!color || color[0] !== "#" || color.length !== 7) return null;
    const r = parseInt(color.slice(1, 3), 16);
    const g = parseInt(color.slice(3, 5), 16);
    const b = parseInt(color.slice(5, 7), 16);
    if ([r, g, b].some(Number.isNaN)) return null;
    return `rgba(${r}, ${g}, ${b}, 0.16)`;
  }
  // Font color for a task and its subtasks — always a stable per-task
  // hash pick from the shared PALETTE, independent of the task's color
  // label (getTaskColor)/background tint (taskColorTint). Two tasks that
  // share the same color-label background fill still get different font
  // colors this way, since the hash is keyed on the task's own id rather
  // than on the shared label. Tasks with no id (shouldn't normally
  // happen) fall back to the first palette entry.
  function taskAutoColor(t) {
    if (!t || !t.id) return PALETTE[0];
    const id = String(t.id);
    let hash = 0;
    for (let i = 0; i < id.length; i++) {
      hash = (hash * 31 + id.charCodeAt(i)) | 0;
    }
    return PALETTE[Math.abs(hash) % PALETTE.length];
  }
  // Global on/off switch for task font color: "dynamic" keeps the
  // per-task hash color from taskAutoColor above; "black" flattens every
  // task/subtask's font to plain black instead. Remembered across
  // reloads via localStorage, same pattern as SIDEBAR_HIDDEN_KEY.
  const TASK_FONT_BLACK_KEY = "branchline_task_font_black";
  // Saved task-list templates (see the "📋 Templates" toolbar button in
  // the tasks modal) — a node's *entire* task list (every task's text,
  // color, and subtask text) can be saved here once, under a name, then
  // dropped onto any other node as a fresh set of tasks. Shared across
  // every map/node (not per-map data), same as the quote banner lines
  // below, since a template like "Morning routine" is just as useful on
  // a different node or a different map.
  const TASK_TEMPLATES_KEY = "branchlineTaskListTemplates_v1";
  let taskFontBlackMode = false;
  try { taskFontBlackMode = localStorage.getItem(TASK_FONT_BLACK_KEY) === "1"; } catch (e) {}
  function setTaskFontBlackMode(on) {
    taskFontBlackMode = !!on;
    try { localStorage.setItem(TASK_FONT_BLACK_KEY, taskFontBlackMode ? "1" : "0"); } catch (e) {}
  }
  // Use this instead of calling taskAutoColor(t) directly anywhere a
  // task/subtask's font color is applied, so the black-mode override
  // above takes effect everywhere at once.
  function taskFontColor(t) {
    return taskFontBlackMode ? "#000000" : taskAutoColor(t);
  }
  // Shared ordering for the "★ Sort" actions (Tasks modal + day popup):
  // starred tasks first, then grouped by color label (in PALETTE order,
  // so the grouping is stable and matches the order swatches are offered
  // in), with uncolored tasks last within each star group.
  function taskColorSortIndex(t) {
    const color = getTaskColor(t);
    const idx = color ? PALETTE.indexOf(color) : -1;
    return idx === -1 ? PALETTE.length : idx;
  }
  function compareTasksByStarAndColor(a, b) {
    return (getTaskStars(b) - getTaskStars(a)) || (taskColorSortIndex(a) - taskColorSortIndex(b));
  }
  function nodeTaskProgress(node) {
    const tasks = getNodeTasks(node);
    // Progress is subtask-based: a task with subtasks contributes their
    // done/total counts. A task with none of its own counts as a single
    // unit instead (done via its own checkbox), so plain tasks still
    // move the needle. A starred task counts 10x toward the weight, so
    // marking (or completing subtasks of) a starred task moves the
    // node's ring/bar further.
    let total = 0, done = 0, failed = 0;
    tasks.forEach((t) => {
      const stars = getTaskStars(t);
      const weight = stars > 0 ? STARRED_TASK_WEIGHT : 1;
      const subs = getTaskSubtasks(t);
      if (subs.length) {
        total += subs.length * weight;
        done += subs.filter(s => s.done).length * weight;
        failed += subs.filter(s => s.failed && !s.done).length * weight;
      } else {
        total += weight;
        if (t.done) done += weight;
        else if (t.failed) failed += weight;
      }
    });
    // Each completed round of the affirmation typing game (node.affirmation.wins
    // — see below) is worth a flat 3 points toward the same done/total tally,
    // always fully "done" since a win is a win: 1 round = 3, 2 rounds = 6, etc.
    const wins = (node && node.affirmation && node.affirmation.wins) || 0;
    if (wins > 0) {
      const affirmationPoints = wins * 3;
      total += affirmationPoints;
      done += affirmationPoints;
    }
    // Every full minute actually logged on the node's countdown timer
    // (node.timePlayedSec — see getNodeTimePlayed) is worth 3 more points,
    // same "always fully done" treatment: 1m = 3, 2m = 6, etc. Partial
    // seconds under a full minute don't count yet.
    const timedMinutes = Math.floor(getNodeTimePlayed(node) / 60);
    if (timedMinutes > 0) {
      const timerPoints = timedMinutes * 3;
      total += timerPoints;
      done += timerPoints;
    }
    // Each link that's been given a comment (node.linkComments — see
    // getLinkComment/setLinkComment) is worth another flat 3 points, same
    // "always fully done" treatment as the above: one commented link = 3,
    // two commented links = 6, etc. A link with no comment set contributes
    // nothing here (it's already covered by whatever it's otherwise worth).
    const commentedLinks = getNodeUrls(node).filter(u => getLinkComment(node, u)).length;
    if (commentedLinks > 0) {
      const commentPoints = commentedLinks * 3;
      total += commentPoints;
      done += commentPoints;
    }
    // Every 2 non-empty lines jotted in the node's Brainstorm scratchpad
    // (node.brainstorm.text — see getNodeBrainstorm/brainstormPoints) is
    // worth 1 more point toward the same tally, same "always fully done"
    // treatment as the above: 2 lines = 1, 4 lines = 2, 6 lines = 3, etc.
    const brainstormPts = brainstormPoints(node);
    if (brainstormPts > 0) {
      total += brainstormPts;
      done += brainstormPts;
    }
    // DRC notes no longer add points to the task tally (used to add a
    // flat 5 per filled-in DRC note via drcPoints — see drcPoints/
    // drcNoteIsFilled, still used elsewhere for the icon/tooltip status,
    // just not counted toward done/total here anymore).
    return { done, total, failed, pct: total ? done / total : 0 };
  }

  // Subtasks — a small checklist living on a single task, stored as
  // t.subtasks = [{id, text, done}]. Checking every subtask marks the
  // parent task done automatically, and toggling the parent's own
  // checkbox cascades to all of its subtasks — the same way nested
  // checklists behave in most task apps.
  function getTaskSubtasks(t) {
    return (t && Array.isArray(t.subtasks)) ? t.subtasks : [];
  }
  function taskSubtaskProgress(t) {
    const subs = getTaskSubtasks(t);
    const total = subs.length;
    const done = subs.filter(s => s.done).length;
    return { done, total, pct: total ? done / total : 0 };
  }
  // How "done" a single task is, as a 0–1 fraction: a task with subtasks
  // is as done as its subtasks are (partial credit counts), otherwise
  // it's a flat 1 or 0 from its own checkbox.
  function taskEffectiveDoneFraction(t) {
    const subs = getTaskSubtasks(t);
    if (subs.length) return subs.filter(s => s.done).length / subs.length;
    return t.done ? 1 : 0;
  }
  // Recomputes a task's own `done` from its subtasks (all done => task
  // done). No-op for tasks without any subtasks yet.
  function syncTaskDoneFromSubtasks(t) {
    const subs = getTaskSubtasks(t);
    if (subs.length) {
      t.done = subs.every(s => s.done);
      // Mirror image: a task is failed once EVERY subtask is failed.
      t.failed = subs.every(s => s.failed);
    }
  }

  // "Failed" — the opposite of done. A task/subtask is done, failed, or
  // neither, never both: marking one clears the other. It counts toward
  // the progress total like any unfinished item (it isn't "done") but is
  // shown separately, and a failed task is never flagged overdue.
  // Stored as `failed: true` on the task/subtask object, so it rides
  // along with the map through IndexedDB, Drive and Export like `done`.
  function setTaskDone(t, on) {
    t.done = !!on;
    if (t.done) t.failed = false;
    getTaskSubtasks(t).forEach(s => { s.done = t.done; if (t.done) s.failed = false; });
  }
  function setTaskFailed(t, on) {
    t.failed = !!on;
    if (t.failed) t.done = false;
    // Cascades to every subtask, same as the done checkbox does.
    getTaskSubtasks(t).forEach(s => { s.failed = t.failed; if (t.failed) s.done = false; });
  }
  function setSubtaskDone(t, s, on) {
    s.done = !!on;
    if (s.done) s.failed = false;
    syncTaskDoneFromSubtasks(t);
  }
  function setSubtaskFailed(t, s, on) {
    s.failed = !!on;
    if (s.failed) s.done = false;
    syncTaskDoneFromSubtasks(t);
  }
  // The little ✗ button on task rows. (Subtask pills don't have one — they
  // are marked failed from their right-click menu only.)
  function makeTaskFailButton(failed, onToggle, cls) {
    const b = document.createElement("button");
    b.type = "button";
    b.className = (cls || "task-fail-btn") + (failed ? " failed" : "");
    b.textContent = "\u2717";
    b.title = failed ? "Marked as failed \u2014 click to clear" : "Mark as failed";
    b.setAttribute("aria-label", failed ? "Clear failed mark" : "Mark as failed");
    b.setAttribute("aria-pressed", failed ? "true" : "false");
    b.addEventListener("mousedown", (e) => e.stopPropagation());
    b.addEventListener("click", (e) => { e.stopPropagation(); onToggle(); });
    return b;
  }

  // Task-list templates — a whole node's task list, saved as one named
  // template (each task's text, color and subtask text plus the line
  // breaks between subtask pills — not done state,
  // ids, due dates or notes: a template is a reusable shape, not a
  // snapshot of one specific in-progress list) from the tasks modal's
  // "📋 Templates" button, then insertable onto any other node's task
  // list from that same button. Stored the same way as the quote banner
  // lines (a flat JSON array under one localStorage key), shared across
  // every map since a template is just as useful on a different node or
  // map as the one it came from.
  function getTaskListTemplates() {
    try {
      const saved = JSON.parse(localStorage.getItem(TASK_TEMPLATES_KEY));
      if (Array.isArray(saved)) return saved;
    } catch (e) {}
    return [];
  }
  function saveTaskListTemplates(list) {
    try { localStorage.setItem(TASK_TEMPLATES_KEY, JSON.stringify(list)); } catch (e) {}
  }
  // The reusable "shape" of `host`'s current task list — same array
  // saveTaskListAsTemplate/updateTaskListTemplate both store, factored
  // out so a fresh save and an overwrite of an existing template snapshot
  // the list identically.
  function snapshotTasksForTemplate(host) {
    return getNodeTasks(host).map(t => ({
      text: (t.text || "").trim() || "Untitled task",
      color: getTaskColor(t) || null,
      // brBefore = the line breaks entered *between* subtask pills (see
      // enhanceSubtaskList), remembered so a template restores the same
      // pill layout. Only stored when non-zero.
      subtasks: getTaskSubtasks(t).map(s => {
        const o = { text: s.text || "" };
        const br = Math.max(0, Math.min(5, s.brBefore | 0));
        if (br) o.brBefore = br;
        return o;
      }).filter(s => s.text.trim())
    }));
  }
  // Saves a copy of every task on `host` as a new named template. Returns
  // the saved template, or null if the list was empty (nothing to save).
  function saveTaskListAsTemplate(host, name) {
    const tasks = snapshotTasksForTemplate(host);
    if (!tasks.length) return null;
    const tpl = { id: uid(), name: (name || "").trim() || "Untitled template", tasks, updatedAt: Date.now() };
    const list = getTaskListTemplates();
    list.push(tpl);
    saveTaskListTemplates(list);
    scheduleTaskTemplateSync();
    return tpl;
  }
  // Overwrites an existing template's task snapshot in place (same id and
  // name) with `host`'s current task list — used by the 🔁 button on a
  // saved template row, so updating a template doesn't leave a stray
  // duplicate behind. Returns true if a matching template was found.
  function updateTaskListTemplate(id, host) {
    const tasks = snapshotTasksForTemplate(host);
    if (!tasks.length) return false;
    const list = getTaskListTemplates();
    const tpl = list.find(t => t.id === id);
    if (!tpl) return false;
    tpl.tasks = tasks;
    tpl.updatedAt = Date.now();
    saveTaskListTemplates(list);
    scheduleTaskTemplateSync();
    return true;
  }
  function deleteTaskListTemplate(id) {
    saveTaskListTemplates(getTaskListTemplates().filter(tpl => tpl.id !== id));
    // Remember the deletion (a "tombstone") so the other device's copy
    // doesn't just bring the template back on the next sync.
    const gone = getDeletedTaskTemplates();
    gone[id] = Date.now();
    saveDeletedTaskTemplates(gone);
    scheduleTaskTemplateSync();
  }

  /* ---- Task-template sync across devices (via Google Drive) ----
     Templates are stored per browser, so a phone never saw the ones made
     on the PC. This mirrors them through the settings file above:
     union of both sides by template id, newest edit wins, and a
     deletion record beats an older copy. Never touches maps, and any
     failure here is logged and ignored. */
  const TASK_TEMPLATES_DELETED_KEY = "branchlineTaskListTemplatesDeleted_v1";
  function getDeletedTaskTemplates() {
    try {
      const o = JSON.parse(localStorage.getItem(TASK_TEMPLATES_DELETED_KEY));
      if (o && typeof o === "object" && !Array.isArray(o)) return o;
    } catch (e) {}
    return {};
  }
  function saveDeletedTaskTemplates(o) {
    try { localStorage.setItem(TASK_TEMPLATES_DELETED_KEY, JSON.stringify(o)); } catch (e) {}
  }
  // a = local (its order is kept), b = remote.
  function mergeTaskTemplateSets(a, b) {
    const deleted = {};
    for (const src of [a.deleted, b.deleted]) {
      for (const id in (src || {})) deleted[id] = Math.max(deleted[id] || 0, Number(src[id]) || 0);
    }
    const best = new Map();
    const order = [];
    for (const t of [...(a.items || []), ...(b.items || [])]) {
      if (!t || !t.id) continue;
      const cur = best.get(t.id);
      if (!cur) { best.set(t.id, t); order.push(t.id); }
      else if ((t.updatedAt || 0) > (cur.updatedAt || 0)) best.set(t.id, t);
    }
    const items = [];
    for (const id of order) {
      const t = best.get(id);
      if (deleted[id] && deleted[id] >= (t.updatedAt || 0)) continue;
      items.push(t);
    }
    return { items, deleted };
  }
  // Order-insensitive fingerprint, so two devices that list the same
  // templates in a different order don't keep re-uploading forever.
  function taskTemplateSetSig(s) {
    const items = (s.items || []).map(t => t.id + ":" + (t.updatedAt || 0)).sort().join(",");
    const del = Object.keys(s.deleted || {}).map(id => id + ":" + s.deleted[id]).sort().join(",");
    return items + "|" + del;
  }
  // Shared "QUEUE TASKS" task for the Tasks modal. Unlike the normal
  // node-owned tasks below it, this one is global: every Tasks list reads
  // the same queue items. It rides in the same small Drive settings file
  // as task/note templates, so phone/PC share one queue. The legacy
  // DRC-named storage keys are intentionally kept so anything added in
  // v206/v207 is preserved instead of being migrated or lost.
  const DRC_QUEUE_KEY = "branchlineDRCQueue_v1";
  const DRC_QUEUE_DELETED_KEY = "branchlineDRCQueueDeleted_v1";
  function getDRCQueueItems() {
    try {
      const list = JSON.parse(localStorage.getItem(DRC_QUEUE_KEY) || "[]");
      return Array.isArray(list) ? list.filter(x => x && x.id) : [];
    } catch (e) { return []; }
  }
  function saveDRCQueueItems(list) {
    try { localStorage.setItem(DRC_QUEUE_KEY, JSON.stringify(Array.isArray(list) ? list : [])); } catch (e) {}
  }
  function getDeletedDRCQueueItems() {
    try {
      const o = JSON.parse(localStorage.getItem(DRC_QUEUE_DELETED_KEY) || "{}");
      return o && typeof o === "object" && !Array.isArray(o) ? o : {};
    } catch (e) { return {}; }
  }
  function saveDeletedDRCQueueItems(o) {
    try { localStorage.setItem(DRC_QUEUE_DELETED_KEY, JSON.stringify(o || {})); } catch (e) {}
  }
  function drcQueueSet() {
    return { items: getDRCQueueItems(), deleted: getDeletedDRCQueueItems() };
  }
  function drcQueueDisplayItems() {
    // Stable sort: unfinished/failed first; completed items always fall to
    // the end while preserving the user's order inside each group.
    return getDRCQueueItems().slice().sort((a, b) => Number(!!a.done) - Number(!!b.done));
  }
  function saveDRCQueueMutation(items, deleted) {
    saveDRCQueueItems(items);
    if (deleted) saveDeletedDRCQueueItems(deleted);
    scheduleTaskTemplateSync();
    try { renderTasksModal(); } catch (e) {}
  }
  function addDRCQueueSubtask(text) {
    const clean = (text || "").trim();
    if (!clean || !requireSignIn()) return false;
    const items = getDRCQueueItems();
    items.push({ id: uid(), text: clean, done: false, failed: false, updatedAt: Date.now() });
    saveDRCQueueMutation(items);
    return true;
  }
  function updateDRCQueueSubtask(id, mutator) {
    if (!requireSignIn()) return false;
    const items = getDRCQueueItems();
    const item = items.find(x => x.id === id);
    if (!item) return false;
    mutator(item);
    item.updatedAt = Date.now();
    saveDRCQueueMutation(items);
    return true;
  }
  function deleteDRCQueueSubtask(id) {
    if (!requireSignIn()) return false;
    const items = getDRCQueueItems();
    const item = items.find(x => x.id === id);
    if (!item) return false;
    const deleted = getDeletedDRCQueueItems();
    deleted[id] = Math.max(Number(deleted[id]) || 0, Date.now());
    saveDRCQueueMutation(items.filter(x => x.id !== id), deleted);
    return true;
  }

  let taskTemplateSyncRunning = false;
  let taskTemplateSyncQueued = false;
  let taskTemplateSyncTimer = null;
  let taskTemplateLastSyncAt = 0;
  function scheduleTaskTemplateSync() {
    clearTimeout(taskTemplateSyncTimer);
    taskTemplateSyncTimer = setTimeout(() => { syncTaskTemplatesWithDrive(); }, 1000);
  }
  // Resolves true if this device's template list changed as a result.
  async function syncTaskTemplatesWithDrive() {
    if (!DriveDB.signedIn || DriveDB.needsReauth || !isOnline) return false;
    if (taskTemplateSyncRunning) { taskTemplateSyncQueued = true; return false; }
    taskTemplateSyncRunning = true;
    let changedLocal = false;
    try {
      const files = await DriveDB.listSettingsFiles();
      // Read every settings file; if any read fails, stop — writing a merge
      // built from incomplete data could drop someone's templates.
      const remoteDocs = [];
      for (const f of files) remoteDocs.push(await DriveDB.downloadFile(f.id));
      let remote = { items: [], deleted: {} };
      let remoteNotes = { items: [], deleted: {} };
      let remoteDRCQueue = { items: [], deleted: {} };
      for (const doc of remoteDocs) {
        const tt = (doc && doc.taskTemplates) || {};
        remote = mergeTaskTemplateSets(remote, {
          items: Array.isArray(tt.items) ? tt.items : [],
          deleted: (tt.deleted && typeof tt.deleted === "object") ? tt.deleted : {}
        });
        // Saved note templates ride in the same settings file, under
        // their own key, merged the exact same way (by id, newest wins,
        // deletion records beat older copies).
        const nt = (doc && doc.noteTemplates) || {};
        remoteNotes = mergeTaskTemplateSets(remoteNotes, {
          items: Array.isArray(nt.items) ? nt.items : [],
          deleted: (nt.deleted && typeof nt.deleted === "object") ? nt.deleted : {}
        });
        const dq = (doc && doc.drcQueue) || {};
        remoteDRCQueue = mergeTaskTemplateSets(remoteDRCQueue, {
          items: Array.isArray(dq.items) ? dq.items : [],
          deleted: (dq.deleted && typeof dq.deleted === "object") ? dq.deleted : {}
        });
      }
      const local = { items: getTaskListTemplates(), deleted: getDeletedTaskTemplates() };
      const merged = mergeTaskTemplateSets(local, remote);
      const mergedSig = taskTemplateSetSig(merged);
      if (mergedSig !== taskTemplateSetSig(local)) {
        saveTaskListTemplates(merged.items);
        saveDeletedTaskTemplates(merged.deleted);
        changedLocal = true;
      }
      const localNotes = { items: getNoteTemplates(), deleted: getDeletedNoteTemplates() };
      const mergedNotes = mergeTaskTemplateSets(localNotes, remoteNotes);
      const mergedNotesSig = taskTemplateSetSig(mergedNotes);
      if (mergedNotesSig !== taskTemplateSetSig(localNotes)) {
        saveNoteTemplates(mergedNotes.items);
        saveDeletedNoteTemplates(mergedNotes.deleted);
        changedLocal = true;
      }
      const localDRCQueue = drcQueueSet();
      const mergedDRCQueue = mergeTaskTemplateSets(localDRCQueue, remoteDRCQueue);
      const mergedDRCQueueSig = taskTemplateSetSig(mergedDRCQueue);
      if (mergedDRCQueueSig !== taskTemplateSetSig(localDRCQueue)) {
        saveDRCQueueItems(mergedDRCQueue.items);
        saveDeletedDRCQueueItems(mergedDRCQueue.deleted);
        changedLocal = true;
        try { renderTasksModal(); } catch (e) {}
      }
      const somethingToStore = merged.items.length || Object.keys(merged.deleted).length
        || mergedNotes.items.length || Object.keys(mergedNotes.deleted).length
        || mergedDRCQueue.items.length || Object.keys(mergedDRCQueue.deleted).length;
      if (somethingToStore && (!files.length || files.length > 1
          || mergedSig !== taskTemplateSetSig(remote)
          || mergedNotesSig !== taskTemplateSetSig(remoteNotes)
          || mergedDRCQueueSig !== taskTemplateSetSig(remoteDRCQueue))) {
        // Keep any other keys a newer app version may have put in the file.
        const payload = Object.assign({}, remoteDocs[0] || {}, {
          v: 1, savedAt: Date.now(),
          taskTemplates: { items: merged.items, deleted: merged.deleted },
          noteTemplates: { items: mergedNotes.items, deleted: mergedNotes.deleted },
          drcQueue: { items: mergedDRCQueue.items, deleted: mergedDRCQueue.deleted }
        });
        const primaryId = await DriveDB.writeSettingsFile(files.length ? files[0].id : null, payload);
        // Two files only ever appear from a simultaneous first save on two
        // devices; both were merged above, so the extras are now redundant.
        for (const extra of files.slice(1)) {
          try { await DriveDB.api(`https://www.googleapis.com/drive/v3/files/${extra.id}`, { method: "DELETE" }); } catch (e) {}
        }
        void primaryId;
      }
      taskTemplateLastSyncAt = Date.now();
    } catch (e) {
      console.error("Task template sync failed", e);
    } finally {
      taskTemplateSyncRunning = false;
      if (taskTemplateSyncQueued) { taskTemplateSyncQueued = false; scheduleTaskTemplateSync(); }
    }
    return changedLocal;
  }
  // Appends a fresh copy of every task in a saved template onto `host`'s
  // existing task list — every task/subtask id is regenerated so they're
  // fully independent from here on, same as any other newly added task.
  // Existing tasks on `host` are left untouched.
  function insertTaskListTemplate(tpl, host) {
    if (!tpl || !host || !Array.isArray(tpl.tasks) || !tpl.tasks.length) return;
    pushUndo();
    if (!Array.isArray(host.tasks)) host.tasks = [];
    const newTasks = tpl.tasks.map(t => {
      const task = {
        id: uid(), text: t.text, done: false, stars: 0, due: null,
        subtasks: (t.subtasks || []).map(s => {
          const sub = { id: uid(), text: s.text, done: false };
          if (s.brBefore > 0) sub.brBefore = Math.min(5, s.brBefore | 0);
          return sub;
        })
      };
      if (t.color) task.color = t.color;
      return task;
    });
    host.tasks = host.tasks.concat(newTasks);
    persist();
  }

  /* ---- Note templates ----
     Same idea as the task-list templates above, for a single note: the
     note editor's "📋" button saves the open note (its title + rich text)
     under a name, then any other note — on any node, cell, task or
     subtask, in any map — can pull it in. Stored per browser in
     localStorage and mirrored through the same Drive settings file (see
     syncTaskTemplatesWithDrive), so they follow the person across
     devices. A template is a reusable shape: inline photos are left out
     (they're per-map records that wouldn't exist elsewhere) and ticked
     checklist lines come back unticked. */
  const NOTE_TEMPLATES_KEY = "branchlineNoteTemplates_v1";
  const NOTE_TEMPLATES_DELETED_KEY = "branchlineNoteTemplatesDeleted_v1";
  function getNoteTemplates() {
    try {
      const saved = JSON.parse(localStorage.getItem(NOTE_TEMPLATES_KEY));
      if (Array.isArray(saved)) return saved;
    } catch (e) {}
    return [];
  }
  function saveNoteTemplates(list) {
    try { localStorage.setItem(NOTE_TEMPLATES_KEY, JSON.stringify(list)); } catch (e) {}
  }
  function getDeletedNoteTemplates() {
    try {
      const o = JSON.parse(localStorage.getItem(NOTE_TEMPLATES_DELETED_KEY));
      if (o && typeof o === "object" && !Array.isArray(o)) return o;
    } catch (e) {}
    return {};
  }
  function saveDeletedNoteTemplates(o) {
    try { localStorage.setItem(NOTE_TEMPLATES_DELETED_KEY, JSON.stringify(o)); } catch (e) {}
  }
  // The saved note template with this name (case-insensitive) — newest one
  // if several share it. "DRC" and "Plan" are special names: see
  // getDRCTemplateText and planTemplateSeedFor.
  function findNoteTemplateByName(name) {
    const want = (name || "").trim().toLowerCase();
    let best = null;
    getNoteTemplates().forEach((t) => {
      if ((t.name || "").trim().toLowerCase() !== want) return;
      if (!best || (t.updatedAt || 0) > (best.updatedAt || 0)) best = t;
    });
    return best;
  }
  // Starting content for the first note of a task/subtask named "plan":
  // the note template called "Plan", if one has been saved.
  function planTemplateSeedFor(owner) {
    if (!owner || !isPlanText(owner.text)) return null;
    const tpl = findNoteTemplateByName("plan");
    if (!tpl) return null;
    return { title: tpl.title || "", html: tpl.html || "" };
  }
  // The reusable shape of `note` ({title, html}) — or null if there's
  // nothing worth saving (no title and no text once photos are dropped).
  function snapshotNoteForTemplate(note) {
    if (!note) return null;
    const tmp = document.createElement("div");
    tmp.innerHTML = noteHtmlFromRaw(note.html || "");
    tmp.querySelectorAll("img").forEach((img) => {
      const parent = img.parentElement;
      img.remove();
      // A line that only held a photo would be left as an empty <div>.
      if (parent && parent !== tmp && !parent.textContent.trim() && !parent.children.length) parent.remove();
    });
    // Ticked checklist lines (☑, struck through) go back to unticked.
    [tmp, ...Array.from(tmp.children)].forEach((el) => {
      const first = document.createTreeWalker(el, NodeFilter.SHOW_TEXT).nextNode();
      if (first && /^☑/.test(first.nodeValue)) first.nodeValue = first.nodeValue.replace(/^☑/, "☐");
      el.classList.remove("note-line-checked");
      if (el.getAttribute("class") === "") el.removeAttribute("class");
    });
    const title = (note.title || "").trim();
    if (!title && !tmp.textContent.trim()) return null;
    return { title, html: tmp.textContent.trim() ? tmp.innerHTML : "" };
  }
  // Saves `note` as a new named template. Returns it, or null if empty.
  function saveNoteAsTemplate(note, name) {
    const snap = snapshotNoteForTemplate(note);
    if (!snap) return null;
    const tpl = {
      id: uid(),
      name: (name || "").trim() || snap.title || "Untitled template",
      title: snap.title,
      html: snap.html,
      updatedAt: Date.now()
    };
    const list = getNoteTemplates();
    list.push(tpl);
    saveNoteTemplates(list);
    scheduleTaskTemplateSync();
    return tpl;
  }
  // Overwrites an existing template's content in place (same id + name).
  function updateNoteTemplate(id, note) {
    const snap = snapshotNoteForTemplate(note);
    if (!snap) return false;
    const list = getNoteTemplates();
    const tpl = list.find(t => t.id === id);
    if (!tpl) return false;
    tpl.title = snap.title;
    tpl.html = snap.html;
    tpl.updatedAt = Date.now();
    saveNoteTemplates(list);
    scheduleTaskTemplateSync();
    return true;
  }
  function deleteNoteTemplate(id) {
    saveNoteTemplates(getNoteTemplates().filter(tpl => tpl.id !== id));
    const gone = getDeletedNoteTemplates();
    gone[id] = Date.now();
    saveDeletedNoteTemplates(gone);
    scheduleTaskTemplateSync();
  }

  // The affirmation typing game lives on its own per node — reached from
  // the node's right-click menu ("🎮 Affirmation game"), not the tasks
  // modal. Shape: node.affirmation = {wins, quote, count, target}. `wins`
  // is how many full rounds have been completed (shown as a ✓ badge with
  // a count on the node); `quote`/`count`/`target` describe whichever
  // round is currently in progress (or null/0 if none is), so closing the
  // game mid-round and coming back later resumes instead of losing
  // progress.
  //
  // The pool of lines itself is editable from the app (see the "Edit
  // lines" manager modal) and persisted in IndexedDB under the same
  // key/value store used for folder handles, keyed AFFIRMATION_QUOTES_KEY.
  // DEFAULT_AFFIRMATION_QUOTES seeds that pool the first time the app
  // runs; affirmationQuotesList is the live, editable in-memory copy.
  function getNodeAffirmation(node) {
    return (node && node.affirmation) ? node.affirmation : null;
  }
  function nodeAffirmationWins(node) {
    const a = getNodeAffirmation(node);
    return a ? (a.wins || 0) : 0;
  }
  const DEFAULT_AFFIRMATION_QUOTES = [
    "Ta là cái biết hằng hữu bất sinh bất diệt",
    "Thêm cũng ko được bớt cũng chẳng xong",
    "Ta là cái biết thân tâm hoàn cảnh",
    "Chừng nào còn biết ơn, Chừng đó còn hạnh phúc",
    "Buồn như buồn, vui như vui, phiền não như phiền não",
    "Không cần Không muốn",
  ];
  const AFFIRMATION_QUOTES_KEY = "affirmation_quotes";
  let affirmationQuotesList = DEFAULT_AFFIRMATION_QUOTES.slice();
  const AFFIRMATION_TARGET = 20;
  // How many correct retypes a round needs, based on how many rounds
  // ("wins") have already been completed on that node: 1st=5, 2nd=10,
  // 3rd=15, and the 4th round onward is the full AFFIRMATION_TARGET (20)
  // — see affirmationTargetForRound below.
  const AFFIRMATION_TARGETS_BY_ROUND = [5, 10, 15];
  function affirmationTargetForRound(winsSoFar) {
    const n = winsSoFar || 0;
    return n < AFFIRMATION_TARGETS_BY_ROUND.length ? AFFIRMATION_TARGETS_BY_ROUND[n] : AFFIRMATION_TARGET;
  }
  // Commas don't count in the affirmation game: they're treated like a
  // space, so typing them or skipping them are both fine ("ơn, Chừng",
  // "ơn,Chừng" and "ơn Chừng" all match).
  function stripAffirmationCommas(s) {
    return (s || "").replace(/[,，、]/g, " ").replace(/\s+/g, " ");
  }
  function normalizeAffirmationText(s) {
    return stripAffirmationCommas(s).trim().toLocaleLowerCase("vi");
  }

  // The "Brainstorm" note-typing score task — reached from the same
  // right-click menu as the Affirmation game and Timer, but simpler than
  // either: no target quote, no countdown, just a plain free-typed
  // scratchpad (host.brainstorm = {text}) that autosaves as you type.
  // Follows the same host-based {nodeId, r, c} pattern as the timer/game
  // above (see resolveHost) so it works identically on a whole node or a
  // single table cell. Every 2 non-empty lines written is worth 1 point
  // toward the node's task score (see nodeTaskProgress above).
  function getNodeBrainstorm(host) {
    return (host && host.brainstorm) ? host.brainstorm : null;
  }
  function getBrainstormText(host) {
    const b = getNodeBrainstorm(host);
    return (b && b.text) || "";
  }
  function brainstormLineCount(host) {
    return getBrainstormText(host).split("\n").filter(l => l.trim().length > 0).length;
  }
  function brainstormPoints(host) {
    return Math.floor(brainstormLineCount(host) / 2);
  }

  // A "DRC" note (see getDRCTemplateText / the drc flag set on it above) is
  // considered "filled in" — and worth points below — once the person has
  // typed more than one line into it, or at least 10 letters total,
  // beyond the template's own fixed section labels. Splits the note's
  // per-line HTML (one <div> per line, matching noteHtmlFromRaw) back
  // into plain-text lines, drops any line that's just one of the fixed
  // labels, then checks what's left.
  function noteLinesFromHtml(html) {
    if (!html) return [];
    const divChunks = html.match(/<div[^>]*>[\s\S]*?<\/div>/gi);
    const chunks = (divChunks && divChunks.length) ? divChunks : [html];
    return chunks.map(chunk => chunk
      .replace(/^<div[^>]*>/i, "").replace(/<\/div>$/i, "")
      .replace(/<br\s*\/?>/gi, "")
      .replace(/<[^>]+>/g, "")
      .replace(/&nbsp;/gi, " ")
      .trim());
  }
  // A note counts as a "DRC" note purely by its title — typed manually,
  // left over from an older note, or set by the 📋 DRC… shortcut/the
  // task-named-"DRC" auto-prefill — so this matches consistently
  // regardless of how the note came to be. Same comparison the task-name
  // check above uses (trim + uppercase).
  function isDRCNote(note) {
    return !!(note && (note.title || "").trim().toUpperCase() === "DRC");
  }
  // "Plan" gets its own icon too (the green-checklist PLAN sheet — see
  // NODE_PLAN_ICON_IMG). It applies when the note's own title is "plan",
  // or — for a task's/subtask's note, where the owner's name doubles as
  // the note's title — when the task/subtask itself is named "plan".
  // Case-insensitive, trimmed, same comparison as DRC above. Unlike DRC
  // this is icon-only: no template, points, or single-note rule.
  function isPlanText(str) {
    return (str || "").trim().toLowerCase() === "plan";
  }
  function isPlanNote(note) {
    return !!(note && isPlanText(note.title));
  }
  // owner = the task/subtask the note belongs to (omit for node/cell notes).
  function isPlanNoteFor(note, owner) {
    return isPlanNote(note) || !!(owner && isPlanText(owner.text));
  }
  function drcNoteIsFilled(note) {
    const labels = drcTemplateLines();
    const lines = noteLinesFromHtml(note && note.html)
      .filter(l => !labels.some(lbl => lbl.toLowerCase() === l.toLowerCase()));
    const typedLines = lines.filter(l => l.length > 0);
    const typedChars = typedLines.join("").length;
    return typedLines.length > 1 || typedChars >= 10;
  }
  // Count of filled-in DRC notes on the node (there can be more than one —
  // each "📋 DRC…" click starts a fresh one, so this adds up like a daily
  // streak). No longer fed into nodeTaskProgress's score — kept only for
  // the "(N filled in)" count in the DRC context-menu row.
  function drcPoints(node) {
    return getNodeNotes(node).filter(n => isDRCNote(n) && drcNoteIsFilled(n)).length * 5;
  }

  // Shared cap for the node icon strip (see renderNode/computeNodeBox):
  // photos, notes, and links each collapse from "one icon per item" down
  // to a single representative icon + a "Nx" count badge once there are
  // more than this many, so a node with dozens of any one thing still
  // reads as one compact cell instead of a wall of tiny icons.
  const STRIP_OVERFLOW_CAP = 16;
  // How many cells a bucket of items (all the notes, or all the links)
  // contributes to the strip's layout — every item while under the cap,
  // or just the one stand-in cell once collapsed.
  function stripBucketCount(len) {
    return len > STRIP_OVERFLOW_CAP ? 1 : len;
  }

  // Bare host/paths ("example.com") still work as a link this way — without
  // a scheme, clicking would otherwise try to load it as a path relative to
  // this local file instead of a real web address.
  function normalizeUrl(raw) {
    const trimmed = (raw || "").trim();
    if (!trimmed) return "";
    if (/^[a-z][a-z0-9+.-]*:\/\//i.test(trimmed)) return trimmed;
    return "https://" + trimmed;
  }

  // Shortens a URL for display in menus — strips the scheme and clips
  // long paths so a single entry never blows out the context menu width.
  function shortenUrlForMenu(u) {
    const stripped = (u || "").replace(/^[a-z][a-z0-9+.-]*:\/\//i, "");
    return stripped.length > 34 ? stripped.slice(0, 33) + "…" : stripped;
  }

  // Recognizable icon per link destination, so a node's link markers and
  // the link picker/manage menus read at a glance instead of every link
  // showing the same generic 🔗 — checked as an ordered list of
  // host/path patterns rather than a lookup map since e.g. Docs and
  // Sheets share the same docs.google.com host and only differ by path.
  // Each icon is a small brand-colored SVG (not an emoji) so it reads as
  // "the real logo" rather than a generic glyph.
  const LINK_ICON_SVGS = {
    youtube: '<svg viewBox="0 0 24 24"><rect x="1" y="5" width="22" height="14" rx="4" fill="#FF0000"/><path d="M10 8.6l6.5 3.4-6.5 3.4z" fill="#fff"/></svg>',
    docs: '<svg viewBox="0 0 24 24"><path d="M6 2h8l5 5v14a1 1 0 01-1 1H6a1 1 0 01-1-1V3a1 1 0 011-1z" fill="#2684FC"/><path d="M14 2l5 5h-5z" fill="#0F62D6"/><rect x="5.5" y="10.5" width="9" height="1.6" rx=".8" fill="#fff"/><rect x="5.5" y="13.7" width="9" height="1.6" rx=".8" fill="#fff"/><rect x="5.5" y="16.9" width="6" height="1.6" rx=".8" fill="#fff"/></svg>',
    sheets: '<svg viewBox="0 0 24 24"><path d="M6 2h8l5 5v14a1 1 0 01-1 1H6a1 1 0 01-1-1V3a1 1 0 011-1z" fill="#0F9D58"/><path d="M14 2l5 5h-5z" fill="#57BB8F"/><rect x="7.5" y="10" width="9" height="8.5" rx="1.1" fill="#fff"/><line x1="7.5" y1="12.9" x2="16.5" y2="12.9" stroke="#0F9D58" stroke-width="1"/><line x1="7.5" y1="15.7" x2="16.5" y2="15.7" stroke="#0F9D58" stroke-width="1"/><line x1="10.5" y1="10" x2="10.5" y2="18.5" stroke="#0F9D58" stroke-width="1"/><line x1="13.5" y1="10" x2="13.5" y2="18.5" stroke="#0F9D58" stroke-width="1"/></svg>',
    slides: '<svg viewBox="0 0 24 24"><path d="M6 2h8l5 5v14a1 1 0 01-1 1H6a1 1 0 01-1-1V3a1 1 0 011-1z" fill="#F4B400"/><path d="M14 2l5 5h-5z" fill="#FBDA8E"/><rect x="7" y="11" width="10" height="6" rx=".8" fill="#fff"/></svg>',
    forms: '<svg viewBox="0 0 24 24"><path d="M6 2h8l5 5v14a1 1 0 01-1 1H6a1 1 0 01-1-1V3a1 1 0 011-1z" fill="#673AB7"/><path d="M14 2l5 5h-5z" fill="#C6B3E6"/><rect x="7" y="11" width="6" height="1.3" fill="#fff"/><rect x="14.5" y="10.6" width="2" height="2" rx=".3" fill="#fff"/><rect x="7" y="14" width="6" height="1.3" fill="#fff"/><rect x="14.5" y="13.6" width="2" height="2" rx=".3" fill="#fff"/></svg>',
    photos: '<svg viewBox="0 0 24 24"><path d="M12 12 L12 0 A6 6 0 0 1 12 12 Z" fill="#E94235"/><path d="M12 12 L24 12 A6 6 0 0 1 12 12 Z" fill="#4A82F2"/><path d="M12 12 L12 24 A6 6 0 0 1 12 12 Z" fill="#31A354"/><path d="M12 12 L0 12 A6 6 0 0 1 12 12 Z" fill="#FBBB05"/></svg>',
    drive: '<svg viewBox="0 0 24 24"><path d="M8.5 3h7l7.3 12.6h-7z" fill="#FFC107"/><path d="M1.7 15.6l3.8-6.6 7.3 12.6H9.3z" fill="#4CAF50"/><path d="M15.3 21.6H8.8l3.7-6.6h7.3z" fill="#2196F3"/></svg>',
    link: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M9.5 14.5l5-5"/><path d="M8 16.5l-1.8 1.8a3.5 3.5 0 01-5-5L3 11.5"/><path d="M16 7.5l1.8-1.8a3.5 3.5 0 015 5L21 12.5"/></svg>',
  };
  const LINK_ICON_RULES = [
    { test: (h, p) => h === "docs.google.com" && p.startsWith("/spreadsheets"), key: "sheets" },
    { test: (h, p) => h === "docs.google.com" && p.startsWith("/presentation"), key: "slides" },
    { test: (h, p) => h === "docs.google.com" && p.startsWith("/forms"), key: "forms" },
    { test: (h) => h === "docs.google.com", key: "docs" },
    { test: (h) => h === "sheets.google.com", key: "sheets" },
    { test: (h) => h === "slides.google.com", key: "slides" },
    { test: (h) => h === "forms.google.com" || h === "forms.gle", key: "forms" },
    { test: (h) => h === "photos.google.com" || h === "photos.app.goo.gl", key: "photos" },
    { test: (h) => h === "youtube.com" || h === "www.youtube.com" || h === "youtu.be" || h === "m.youtube.com", key: "youtube" },
    { test: (h) => h === "drive.google.com", key: "drive" },
  ];
  function linkIconKey(u) {
    try {
      const parsed = new URL(u);
      const host = parsed.hostname.toLowerCase();
      const path = parsed.pathname;
      for (const rule of LINK_ICON_RULES) {
        if (rule.test(host, path)) return rule.key;
      }
    } catch (e) { /* not a parseable absolute URL — fall through */ }
    return "link";
  }
  // Builds a "[icon] title" (or "[icon] shortened-url" when no title has
  // been fetched/set) row label as a small DOM fragment — the icon comes
  // from our own trusted SVG map (safe as innerHTML) but the label text
  // goes through textContent so it can never be interpreted as markup.
  function linkRowFragment(u, node) {
    const frag = document.createDocumentFragment();
    const iconSpan = document.createElement("span");
    iconSpan.className = "ctx-item-link-icon";
    iconSpan.innerHTML = linkIconFor(u);
    frag.appendChild(iconSpan);
    const label = getLinkTitle(node, u) || shortenUrlForMenu(u);
    frag.appendChild(document.createTextNode(" " + label));
    return frag;
  }

  function linkIconFor(u) {
    return LINK_ICON_SVGS[linkIconKey(u)];
  }

  // A table cell's links use the exact same multi-link model as a node's
  // own links (see getNodeUrls/getLinkTitle above) — an array of URLs
  // plus a { [url]: title } map for display names — just scoped to one
  // cell's attach record instead of the whole node. Reads either the old
  // single plain `url` string (from before this existed) or the new
  // `urls` array, same fallback shape as getNodeUrls.
  function getCellUrls(a) {
    if (!a) return [];
    if (Array.isArray(a.urls) && a.urls.length) return a.urls;
    if (a.url) return [a.url];
    return [];
  }
  function cellHasUrls(a) {
    return getCellUrls(a).length > 0;
  }
  function getCellLinkTitle(a, url) {
    return (a && a.linkTitles && a.linkTitles[url]) || "";
  }
  function setCellLinkTitle(a, url, title) {
    if (!a || !url) return;
    if (!a.linkTitles) a.linkTitles = {};
    const clean = (title || "").trim();
    if (clean) a.linkTitles[url] = clean;
    else delete a.linkTitles[url];
  }
  // Same per-link comment as getLinkComment/setLinkComment above, just
  // scoped to a table cell's own attach record.
  function getCellLinkComment(a, url) {
    return (a && a.linkComments && a.linkComments[url]) || "";
  }
  function setCellLinkComment(a, url, comment) {
    if (!a || !url) return;
    if (!a.linkComments) a.linkComments = {};
    const clean = (comment || "").trim();
    if (clean) a.linkComments[url] = clean;
    else delete a.linkComments[url];
  }
  // Same per-link attached photo(s) as getLinkPhotos/addLinkPhoto/
  // removeLinkPhoto above, just scoped to a table cell's own attach record.
  function getCellLinkPhotos(a, url) {
    return (a && a.linkPhotos && a.linkPhotos[url]) || [];
  }
  function addCellLinkPhoto(a, url, dataUrl) {
    if (!a || !url) return null;
    const id = addPhotoRecord(dataUrl, { avoid: getCellLinkPhotos(a, url) });
    if (!a.linkPhotos) a.linkPhotos = {};
    if (!a.linkPhotos[url]) a.linkPhotos[url] = [];
    a.linkPhotos[url].push(id);
    return id;
  }
  function removeCellLinkPhoto(a, url, photoId) {
    if (!a || !a.linkPhotos || !a.linkPhotos[url]) return;
    a.linkPhotos[url] = a.linkPhotos[url].filter((id) => id !== photoId);
    if (!a.linkPhotos[url].length) delete a.linkPhotos[url];
    deletePhotoRecord(photoId);
  }
  // Same "[icon] title" row-label builder as linkRowFragment above, just
  // reading a cell's own linkTitles instead of a node's.
  function cellLinkRowFragment(u, a) {
    const frag = document.createDocumentFragment();
    const iconSpan = document.createElement("span");
    iconSpan.className = "ctx-item-link-icon";
    iconSpan.innerHTML = linkIconFor(u);
    frag.appendChild(iconSpan);
    const label = getCellLinkTitle(a, u) || shortenUrlForMenu(u);
    frag.appendChild(document.createTextNode(" " + label));
    return frag;
  }
  // Same best-effort auto-title fetch as fetchLinkTitle above, scoped to
  // one cell instead of a node — re-resolves the live cell by {nodeId,
  // r, c} since several seconds may have passed before this resolves.
  async function fetchCellLinkTitle(nodeId, r, c, url) {
    let title = null;
    const ytId = youtubeVideoId(url);
    try {
      if (ytId) {
        const res = await fetch(`https://www.youtube.com/oembed?url=${encodeURIComponent(url)}&format=json`);
        if (res.ok) title = (await res.json()).title;
      } else {
        const res = await fetch(url, { mode: "cors" });
        if (res.ok) title = new DOMParser().parseFromString(await res.text(), "text/html").title;
      }
    } catch (e) {
      console.warn("Branchline: couldn't auto-fetch link title for", url, e);
    }
    title = (title || "").trim();
    const liveNode = findNode(nodeId);
    if (!liveNode || !liveNode.table) return;
    const a = getCellAttach(liveNode, r, c);
    if (!title || !getCellUrls(a).includes(url) || getCellLinkTitle(a, url)) return;
    setCellLinkTitle(a, url, title.slice(0, 80));
    renderAll();
    persist();
  }

  // Native prompt for adding a new URL to a node — appends it to the
  // node's `urls` array, then immediately asks for an optional display
  // name too. Asking up front is the *only* reliable way to get a
  // readable name — auto-fetching the real page title (see
  // fetchLinkTitle) fails for virtually all sites, YouTube included,
  // since browsers block the cross-origin fetch with a CORS error
  // before the response can even be read. Leaving this second prompt
  // blank still attempts the background fetch on the off chance a
  // particular link/proxy setup allows it, but don't count on it.
  function addNodeUrl(nodeId) {
    if (!requireSignIn()) return;
    const node = findNode(nodeId);
    if (!node) return;
    const input = window.prompt("URL to add to this node:", "https://");
    if (input === null) return; // cancelled
    const trimmed = input.trim();
    if (!trimmed) return;
    const url = normalizeUrl(trimmed);
    const name = window.prompt("Name for this link (leave blank to use the URL):", "");
    pushUndo();
    const urls = getNodeUrls(node).slice();
    urls.push(url);
    node.urls = urls;
    node.url = null; // fully migrated onto the array field
    setLinkTimestamp(node, url, Date.now());
    if (name && name.trim()) setLinkTitle(node, url, name);
    renderAll();
    persist();
    if (!getLinkTitle(node, url)) fetchLinkTitle(node, url);
  }

  // Native prompt for editing (or, if cleared, removing) one existing URL
  // by its index in the node's `urls` array. Changing the URL text
  // itself invalidates whatever title (fetched or manual) was attached
  // to the old address, and re-triggers a fetch for the new one.
  function editNodeUrl(nodeId, index) {
    if (!requireSignIn()) return;
    const node = findNode(nodeId);
    if (!node) return;
    const urls = getNodeUrls(node).slice();
    if (index < 0 || index >= urls.length) return;
    const oldUrl = urls[index];
    const input = window.prompt("Edit URL (clear to remove):", oldUrl);
    if (input === null) return; // cancelled
    const trimmed = input.trim();
    pushUndo();
    if (trimmed) {
      const newUrl = normalizeUrl(trimmed);
      urls[index] = newUrl;
      if (newUrl !== oldUrl) {
        setLinkTitle(node, oldUrl, null);
        node.urls = urls;
        node.url = null;
        renderAll();
        persist();
        fetchLinkTitle(node, newUrl);
        return;
      }
    } else {
      setLinkTitle(node, oldUrl, null);
      urls.splice(index, 1);
    }
    node.urls = urls;
    node.url = null;
    renderAll();
    persist();
  }

  // Native prompt for giving a link its own custom name, independent of
  // whatever fetchLinkTitle did or didn't manage to find automatically.
  // This is the reliable path — most ordinary sites don't allow the
  // cross-origin title fetch to succeed at all (see fetchLinkTitle).
  function renameNodeUrl(nodeId, index) {
    if (!requireSignIn()) return;
    const node = findNode(nodeId);
    if (!node) return;
    const urls = getNodeUrls(node);
    if (index < 0 || index >= urls.length) return;
    const url = urls[index];
    const input = window.prompt("Name for this link (leave blank to just show the URL):", getLinkTitle(node, url));
    if (input === null) return; // cancelled
    pushUndo();
    setLinkTitle(node, url, input);
    renderAll();
    persist();
  }

  // Removes one URL from a node by its index in the `urls` array — the
  // context menu's ✕ next to each attached link, for a one-click removal
  // that doesn't need the edit prompt's "clear the field" workaround.
  function removeNodeUrl(nodeId, index) {
    const node = findNode(nodeId);
    if (!node) return;
    const urls = getNodeUrls(node).slice();
    if (index < 0 || index >= urls.length) return;
    pushUndo();
    setLinkTitle(node, urls[index], null);
    urls.splice(index, 1);
    node.urls = urls;
    node.url = null;
    renderAll();
    persist();
  }

  // Right-click on a single link marker — same shape as openNoteManageMenu:
  // just this one link's rename/remove, since each link now has its own
  // icon rather than one shared icon for the lot.
  // Lists every link on a node — the overflow icon's counterpart to
  // openNoteManageMenu below, reachable once a node has passed the
  // STRIP_OVERFLOW_CAP link count and collapsed to one icon + a count
  // badge (see renderNode), so every individual link is still reachable
  // for opening, renaming, or removing.
  function openLinksManageMenu(nodeId, x, y) {
    const node = findNode(nodeId);
    if (!node) return;
    const urls = getNodeUrls(node);
    if (!urls.length) return;
    resetContextMenu();

    const header = document.createElement("div");
    header.className = "ctx-item ctx-item-header";
    header.style.cursor = "default";
    const headerLabel = document.createElement("span");
    headerLabel.className = "ctx-item-label";
    headerLabel.textContent = `Links (${urls.length})`;
    header.appendChild(headerLabel);
    const addBtn = document.createElement("span");
    addBtn.className = "ctx-item-add";
    addBtn.textContent = "+";
    addBtn.title = "Add a new link";
    addBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      closeContextMenu();
      addNodeUrl(nodeId);
    });
    header.appendChild(addBtn);
    ctxMenu.appendChild(header);

    urls.forEach((u, i) => {
      const it = document.createElement("div");
      it.className = "ctx-item";
      it.title = u;
      const labelSpan = document.createElement("span");
      labelSpan.className = "ctx-item-label";
      labelSpan.appendChild(linkRowFragment(u, node));
      labelSpan.addEventListener("click", () => {
        closeContextMenu();
        openLinkSmart(u, {
          videoKey: `${nodeId}|${u}`,
          get: () => getLinkComment(findNode(nodeId) || node, u),
          set: (v) => setLinkComment(findNode(nodeId) || node, u, v),
          getFavorite: () => getLinkFavorite(findNode(nodeId) || node, u),
          setFavorite: (v) => setLinkFavorite(findNode(nodeId) || node, u, v),
          getPhotos: () => getLinkPhotos(findNode(nodeId) || node, u),
          addPhoto: (dataUrl) => addLinkPhoto(findNode(nodeId) || node, u, dataUrl),
          removePhoto: (id) => removeLinkPhoto(findNode(nodeId) || node, u, id),
        });
      });
      it.appendChild(labelSpan);
      const rename = document.createElement("span");
      rename.className = "ctx-item-remove ctx-item-rename";
      rename.textContent = "✎";
      rename.title = "Rename";
      rename.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); renameNodeUrl(nodeId, i); });
      it.appendChild(rename);
      const rm = document.createElement("span");
      rm.className = "ctx-item-remove";
      rm.textContent = "✕";
      rm.title = "Remove";
      rm.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); removeNodeUrl(nodeId, i); });
      it.appendChild(rm);
      ctxMenu.appendChild(it);
    });
    positionContextMenu(x, y);
  }

  function openUrlSingleManageMenu(nodeId, index, x, y) {
    const node = findNode(nodeId);
    if (!node) return;
    const urls = getNodeUrls(node);
    const u = urls[index];
    if (!u) return;
    resetContextMenu();
    const it = document.createElement("div");
    it.className = "ctx-item";
    it.title = u;
    const labelSpan = document.createElement("span");
    labelSpan.className = "ctx-item-label";
    labelSpan.appendChild(linkRowFragment(u, node));
    it.appendChild(labelSpan);
    const popup = document.createElement("span");
    popup.className = "ctx-item-remove ctx-item-popup";
    popup.textContent = "🪟";
    popup.title = "Open in a new window (smaller than this one)";
    popup.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); openUrlAsPopup(u); });
    it.appendChild(popup);
    const rename = document.createElement("span");
    rename.className = "ctx-item-remove ctx-item-rename";
    rename.textContent = "✎";
    rename.title = "Rename";
    rename.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); renameNodeUrl(nodeId, index); });
    it.appendChild(rename);
    const comment = document.createElement("span");
    comment.className = "ctx-item-remove ctx-item-comment";
    comment.textContent = "💬";
    comment.title = "Comment";
    comment.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); commentOnNodeUrl(nodeId, index); });
    it.appendChild(comment);
    const rm = document.createElement("span");
    rm.className = "ctx-item-remove";
    rm.textContent = "✕";
    rm.title = "Remove";
    rm.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); removeNodeUrl(nodeId, index); });
    it.appendChild(rm);
    it.addEventListener("click", () => { closeContextMenu(); editNodeUrl(nodeId, index); });
    ctxMenu.appendChild(it);
    positionContextMenu(x, y);
  }

  // Opens the same paragraph-friendly comment editor as the video
  // modal's inline comment box (see openLinkCommentModal) — the "💬"
  // button next to a link's rename/remove buttons in its right-click
  // menu. The comment only ever shows as a hover tooltip on the link's
  // own icon (see attachLinkCommentTooltip); it has no other effect on
  // the link.
  function commentOnNodeUrl(nodeId, index) {
    if (!requireSignIn()) return;
    const node = findNode(nodeId);
    if (!node) return;
    const urls = getNodeUrls(node);
    const u = urls[index];
    if (!u) return;
    openLinkCommentModal(u, {
      get: () => getLinkComment(findNode(nodeId) || node, u),
      set: (v) => setLinkComment(findNode(nodeId) || node, u, v),
      getFavorite: () => getLinkFavorite(findNode(nodeId) || node, u),
      setFavorite: (v) => setLinkFavorite(findNode(nodeId) || node, u, v),
    });
  }

  function newMindMap(title) {
    const root = newNode(title || "Central idea");
    return {
      id: uid(),
      title: title || "Untitled map",
      createdAt: Date.now(),
      updatedAt: Date.now(),
      favorite: false,
      trashedAt: null,  // timestamp when moved to trash, or null if not trashed — see deleteMap/restoreMap
      root,
      links: [],   // cross-links: [{ id, a: nodeId, b: nodeId }] — connections that
                   // aren't part of the parent/child tree (e.g. "this idea relates to that one")
      view: { scale: 1, tx: 0, ty: 0 },
      theme: defaultTheme(),
      layout: "mindmap"   // "mindmap" | "righty" | "timeline" (legacy "logic" is migrated to "righty" by ensureLayout)
    };
  }

  function ensureFavorite(map) {
    if (!map) return;
    if (typeof map.favorite !== "boolean") map.favorite = false;
  }

  function ensureTrash(map) {
    if (!map) return;
    if (typeof map.trashedAt !== "number") map.trashedAt = null;
  }

  // The sidebar's regular map list and "open next map" fallbacks should
  // never surface a trashed map — only the trash modal does. Kept as
  // helpers rather than filtering state.maps itself, since state.maps is
  // the full source of truth (trashed maps still need to persist, sync,
  // and show up in the trash modal).
  function activeMaps() {
    return state.maps.filter(m => !m.trashedAt);
  }
  function trashedMapsList() {
    return state.maps.filter(m => m.trashedAt);
  }

  // Favorited maps always float to the top; within each group (favorite /
  // not), most-recently-updated first — same ordering used everywhere the
  // map list is touched, so the sidebar stays consistent no matter which
  // code path last modified it.
  function sortMaps(list) {
    list.sort((a, b) => {
      const fa = a.favorite ? 1 : 0, fb = b.favorite ? 1 : 0;
      if (fa !== fb) return fb - fa;
      return (b.createdAt || b.updatedAt || 0) - (a.createdAt || a.updatedAt || 0);
    });
    return list;
  }

  function ensureLinks(map) {
    if (!map) return;
    if (!Array.isArray(map.links)) map.links = [];
  }

  function ensureLayout(map) {
    if (!map) return;
    // "Logic chart" was removed as its own menu option since it was
    // identical to "Righty mindmap" (both just layoutMindmap(root, false)
    // — see layout() below) — migrate any map saved with the old value
    // so it keeps rendering exactly the same way under the new name.
    if (map.layout === "logic") map.layout = "righty";
    if (map.layout !== "timeline" && map.layout !== "righty") map.layout = "mindmap";
  }

  // Per-map clock/calendar visibility — see isClockHidden/setClockHidden.
  // Defaults to hidden (true) for maps that have never had the toggle
  // touched, so the root node's live clock and the toolbar's 📅 Calendar
  // button stay out of the way unless someone opts in for that specific map.
  function ensureClockHidden(map) {
    if (!map) return;
    if (typeof map.clockHidden !== "boolean") map.clockHidden = true;
  }

  // One-time data repair, run once per map (flagged via map._sidesRepaired
  // so it never runs again after that, even across reopens). An earlier
  // version of Timeline mode's per-branch left/right split wrote its
  // auto-balanced choice directly onto node.side — but .side is a field
  // Mindmap mode's own layout also reads for every node, not just root's
  // direct children, so any map that had been opened in Timeline before
  // that was fixed could pick up "phantom" side flips deep in the tree
  // that the person never actually dragged. Back in Mindmap mode those
  // phantom flips make a node fan the opposite way from its own branch,
  // sending its connector line all the way across the canvas instead of
  // following its siblings. This clears any such non-top-level side just
  // once — a real user-dragged deep override made after this fix is safe
  // and is never touched by this again.
  function ensureSidesRepaired(map) {
    if (!map || map._sidesRepaired || !map.root) return;
    (function strip(node, depth) {
      if (depth > 1 && node.side) node.side = null;
      (node.children || []).forEach(c => strip(c, depth + 1));
    })(map.root, 0);
    map._sidesRepaired = true;
  }

  // One-time data repair: the affirmation typing game used to live as a
  // special task (t.type === "affirmation") inside a node's regular task
  // list. It now lives on its own as node.affirmation = {wins, quote,
  // count, target}, reached from the right-click menu instead of the
  // tasks modal. Any old affirmation-type task found on a node folds its
  // progress into the new counter (a completed one adds a win; an
  // in-progress one is resumed) and is removed from node.tasks so the
  // task list is plain checkboxes again. Flagged via map._affirmationMigrated
  // so it only ever runs once per map.
  function ensureAffirmationMigrated(map) {
    if (!map || map._affirmationMigrated || !map.root) return;
    (function walk(node) {
      const tasks = (node && Array.isArray(node.tasks)) ? node.tasks : [];
      const oldAffirmations = tasks.filter(t => t && t.type === "affirmation");
      if (oldAffirmations.length) {
        if (!node.affirmation) node.affirmation = { wins: 0, quote: null, count: 0, target: AFFIRMATION_TARGET };
        oldAffirmations.forEach(t => {
          if (t.done) {
            node.affirmation.wins = (node.affirmation.wins || 0) + 1;
          } else if (!node.affirmation.quote) {
            // Resume whichever in-progress round was found first.
            node.affirmation.quote = t.quote || t.text || null;
            node.affirmation.count = t.count || 0;
            node.affirmation.target = t.target || AFFIRMATION_TARGET;
          }
        });
        node.tasks = tasks.filter(t => !t || t.type !== "affirmation");
      }
      (node.children || []).forEach(walk);
    })(map.root);
    map._affirmationMigrated = true;
  }

  function sampleMindMap() {
    const m = newMindMap("Welcome to Branchline");
    const c1 = newNode("Try Tab to add a child");
    const c2 = newNode("Try Enter to add a sibling");
    const c3 = newNode("Double-click to rename");
    const c4 = newNode("Right-click for more actions");
    const g1 = newNode("Deeper branches fade in style");
    c1.children.push(g1);
    m.root.children.push(c1, c2, c3, c4);
    return m;
  }

  /* ---------------- app state ---------------- */

  const state = {
    maps: [],
    current: null,       // full mindmap object
    selectedId: null,
    editingId: null,
    linkFromId: null,    // when set, we're in "pick the other end of a link" mode
    moveSourceId: null,  // when set, we're in "pick where to move this node" mode
                          // (started from a node's right-click menu, as an
                          // alternative to drag-and-drop reparenting)
    highlightId: null,   // when set, this node + its branch stay sharp and
                          // every other node/connector is blurred — a
                          // transient view setting, never persisted (see
                          // the `persist` function below, which only
                          // saves `state.current`)
    selectedCell: null,   // {nodeId, r, c} of the last-clicked table cell,
                          // or null — lets a paste anywhere on the page
                          // land on that cell's photos instead of the
                          // selected node's own (see the paste handler
                          // below and handleCellPhotoFiles).
    cellRangeAnchor: null, // {nodeId, r, c} of the last *non*-shift cell
                          // click — the fixed corner a shift-click range
                          // is measured from (see handleTableCellClick).
    cellRange: null,      // {nodeId, r0, c0, r1, c1} rectangle of table
                          // cells currently selected via shift-click, or
                          // null — drives the range highlight and is what
                          // "Merge cells" (see mergeCellRange) acts on.
    scale: 1, tx: 60, ty: 60,
    undoStack: [],
    redoStack: []
  };

  /* ---------------- DOM refs ---------------- */

  const $ = (sel) => document.querySelector(sel);
  const listEl = $("#mindmap-list");
  const worldEl = $("#world");
  const svgEl = $("#lines-svg");
  const nodesLayer = $("#nodes-layer");
  const viewportEl = $("#viewport");
  const titleInput = $("#title-input");
  const layoutSelect = $("#layout-select");
  const saveStatus = $("#save-status");
  const emptyState = $("#empty-state");
  const nodeFabs = $("#node-fabs");
  const ctxMenu = $("#ctx-menu");

  // Every open*ContextMenu function below starts by wiping and rebuilding
  // the menu's contents (it's one reused element for every kind of
  // right-click/long-press menu in the app).
  function resetContextMenu() {
    ctxMenu.innerHTML = "";
    ctxMenu.classList.remove("hidden");
  }

  // Shared positioning for every ctx-menu popup (the node right-click menu,
  // and the smaller link/note picker popups). Reads the menu's *real*
  // rendered width/height instead of assuming a fixed size — the node menu
  // especially varies a lot (a node with photos, notes, tasks, links, and
  // the branch-color swatch grid can run much taller than a guessed 300px),
  // which is what was letting the bottom of the menu run off a phone
  // screen with no way to reach it. Clamped on every side (not just
  // bottom/right) with the same margin the drag handler uses, so the menu
  // never opens partly off the top/left edge either. Call this only after
  // the menu's contents are fully built and appended — it needs the real
  // getBoundingClientRect().
  function positionContextMenu(x, y) {
    const margin = 8;
    const rect = ctxMenu.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const left = clamp(x, margin, Math.max(margin, vw - rect.width - margin));
    const top = clamp(y, margin, Math.max(margin, vh - rect.height - margin));
    ctxMenu.style.left = left + "px";
    ctxMenu.style.top = top + "px";
  }
  const hintBar = $("#hint-bar");

  // Floating tooltip for a link's comment (see getLinkComment/
  // getCellLinkComment) — a single shared element reused for every link
  // icon rather than one per icon, shown on mouseenter and hidden on
  // mouseleave. Deliberately not the native `title` attribute: that's
  // already used for the link's own title/URL, and the native tooltip
  // can't be styled or hold multi-line text comfortably.
  let linkCommentTooltipEl = null;
  function getLinkCommentTooltipEl() {
    if (!linkCommentTooltipEl) {
      linkCommentTooltipEl = document.createElement("div");
      linkCommentTooltipEl.className = "link-comment-tooltip";
      document.body.appendChild(linkCommentTooltipEl);
    }
    return linkCommentTooltipEl;
  }
  function hideLinkCommentTooltip() {
    if (linkCommentTooltipEl) linkCommentTooltipEl.classList.remove("visible");
  }
  function showLinkCommentTooltip(anchorEl, title, comment) {
    const tip = getLinkCommentTooltipEl();
    tip.innerHTML = "";
    if (title) {
      const titleEl = document.createElement("div");
      titleEl.className = "link-comment-tooltip-title";
      titleEl.textContent = title;
      tip.appendChild(titleEl);
    }
    if (comment) {
      const commentEl = document.createElement("div");
      commentEl.className = "link-comment-tooltip-comment";
      commentEl.textContent = comment;
      tip.appendChild(commentEl);
    }
    tip.classList.add("visible");
    const margin = 8;
    const rect = anchorEl.getBoundingClientRect();
    const tipRect = tip.getBoundingClientRect();
    let left = rect.left + rect.width / 2 - tipRect.width / 2;
    left = clamp(left, margin, Math.max(margin, window.innerWidth - tipRect.width - margin));
    let top = rect.top - tipRect.height - 8;
    if (top < margin) top = rect.bottom + 8; // flip below if no room above
    tip.style.left = left + "px";
    tip.style.top = top + "px";
  }
  // Wires up the hover-to-show behavior on one link icon element.
  // `getComment` and `getTitle` are called fresh on every hover (rather
  // than being baked in once) so an edit made through the right-click
  // menu is reflected the next time the same icon is hovered, without
  // needing a full re-render. `getTitle` is only ever consulted for a
  // YouTube video/short (see youtubeVideoId) — that's the one case where
  // the link's title is a genuinely useful thing to surface here (the
  // video's real name, not just the URL), stacked above the comment in
  // this one styled tooltip. Every other link's title stays exactly
  // where it already was: the native `title` attribute.
  function attachLinkCommentTooltip(el, url, getComment, getTitle) {
    el.addEventListener("mouseenter", () => {
      const title = (youtubeVideoId(url) && getTitle) ? getTitle() : null;
      const comment = getComment();
      if (title || comment) showLinkCommentTooltip(el, title, comment);
    });
    el.addEventListener("mouseleave", hideLinkCommentTooltip);
  }

  /* ---------------- persistence flow ---------------- */

  async function loadAllMaps() {
    state.maps = await DB.getAll();
    state.maps.forEach(ensureFavorite);
    // Catches maps saved by an earlier version of the app, before photos
    // moved into their own store — anything still holding inline base64
    // gets migrated in place (writes are also persisted back to DB.put
    // so this only ever has to happen once per map).
    for (const m of state.maps) {
      if (!m._photosMigrated) {
        await ensurePhotosMigrated(m);
        await DB.put(m);
      }
    }
    sortMaps(state.maps);
  }

  // Drives the "Synced Xs/Xm ago" label. Kept separate from `persist()`
  // itself so the label keeps counting up on its own tick (see the
  // interval below) instead of only updating at the moment a save
  // happens and then sitting frozen on a stale value.
  let lastSavedAt = 0;

  // Same idea as relTime() below but with second-level granularity for
  // the first minute, since jumping straight from "Saved" to "1m ago"
  // reads as much less immediate/trustworthy than "20s ago".
  function relTimeShort(ts) {
    const s = Math.floor((Date.now() - ts) / 1000);
    if (s < 5) return "just now";
    if (s < 60) return s + "s ago";
    return relTime(ts) + " ago";
  }

  function updateSaveStatusLabel() {
    if (!lastSavedAt || saveStatus.classList.contains("saving")) return;
    saveStatus.textContent = "Local saved " + relTimeShort(lastSavedAt);
  }

  // Ticks once a second while the tab is visible so the label keeps
  // advancing (20s ago -> 21s ago -> ... -> 1m ago) without needing a
  // new save. Paused in background tabs, matching the Drive poll's
  // battery/quota-saving behavior elsewhere in this file.
  setInterval(() => {
    if (document.visibilityState === "visible") updateSaveStatusLabel();
  }, 1000);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") updateSaveStatusLabel();
  });

  /* ---------------- root node live clock ---------------- */
  // The central/root node doubles as a small live clock: current local
  // time, UTC/US(NY)/UK world clocks, the Vietnamese weekday+date, and
  // the lunar date — ported from the standalone clock.html widget this
  // app started life alongside. The block itself is built once per
  // render (see renderNode), then this ticker just walks back in and
  // refreshes its text every second — cheap DOM writes, no renderAll —
  // so nothing about the map's actual data (or undo history) is touched
  // just because a second went by.

  const ROOT_CLOCK_CAN = ["Giáp","Ất","Bính","Đinh","Mậu","Kỷ","Canh","Tân","Nhâm","Quý"];
  const ROOT_CLOCK_CHI = ["Tý","Sửu","Dần","Mão","Thìn","Tỵ","Ngọ","Mùi","Thân","Dậu","Tuất","Hợi"];

  function rcINT(d) { return Math.floor(d); }

  function rcJdFromDate(dd, mm, yy) {
    const a = rcINT((14 - mm) / 12);
    const y = yy + 4800 - a;
    const m = mm + 12 * a - 3;
    let jd = dd + rcINT((153 * m + 2) / 5) + 365 * y + rcINT(y / 4) - rcINT(y / 100) + rcINT(y / 400) - 32045;
    if (jd < 2299161) jd = dd + rcINT((153 * m + 2) / 5) + 365 * y + rcINT(y / 4) - 32083;
    return jd;
  }

  function rcGetNewMoonDay(k, timeZone) {
    const T = k / 1236.85;
    const T2 = T * T;
    const T3 = T2 * T;
    const dr = Math.PI / 180;
    let Jd1 = 2415020.75933 + 29.53058868 * k + 0.0001178 * T2 - 0.000000155 * T3;
    Jd1 += 0.00033 * Math.sin((166.56 + 132.87 * T - 0.009173 * T2) * dr);
    const M = 359.2242 + 29.10535608 * k - 0.0000333 * T2 - 0.00000347 * T3;
    const Mpr = 306.0253 + 385.81691806 * k + 0.0107306 * T2 + 0.00001236 * T3;
    const F = 21.2964 + 390.67050646 * k - 0.0016528 * T2 - 0.00000239 * T3;
    let C1 = (0.1734 - 0.000393 * T) * Math.sin(M * dr) + 0.0021 * Math.sin(2 * dr * M);
    C1 -= 0.4068 * Math.sin(Mpr * dr) + 0.0161 * Math.sin(2 * dr * Mpr);
    C1 -= 0.0004 * Math.sin(3 * dr * Mpr);
    C1 += 0.0104 * Math.sin(2 * dr * F) - 0.0051 * Math.sin((M + Mpr) * dr);
    C1 -= 0.0074 * Math.sin((M - Mpr) * dr) + 0.0004 * Math.sin((2 * F + M) * dr);
    C1 -= 0.0004 * Math.sin((2 * F - M) * dr) - 0.0006 * Math.sin((2 * F + Mpr) * dr);
    C1 += 0.0010 * Math.sin((2 * F - Mpr) * dr) + 0.0005 * Math.sin((2 * Mpr + M) * dr);
    let deltaT;
    if (T < -11) {
      deltaT = 0.001 + 0.000839 * T + 0.0002261 * T2 - 0.00000845 * T3 - 0.000000081 * T * T3;
    } else {
      deltaT = -0.000278 + 0.000265 * T + 0.000262 * T2;
    }
    return rcINT(Jd1 + C1 - deltaT + 0.5 + timeZone / 24);
  }

  function rcGetSunLongitude(jdn, timeZone) {
    const T = (jdn - 2451545.5 - timeZone / 24) / 36525;
    const T2 = T * T;
    const dr = Math.PI / 180;
    const M = 357.52910 + 35999.05030 * T - 0.0001559 * T2 - 0.00000048 * T * T2;
    const L0 = 280.46645 + 36000.76983 * T + 0.0003032 * T2;
    let DL = (1.914600 - 0.004817 * T - 0.000014 * T2) * Math.sin(dr * M);
    DL += (0.019993 - 0.000101 * T) * Math.sin(dr * 2 * M) + 0.000290 * Math.sin(dr * 3 * M);
    let L = L0 + DL;
    L = L * dr;
    L = L - Math.PI * 2 * rcINT(L / (Math.PI * 2));
    return rcINT(L / Math.PI * 6);
  }

  function rcGetLunarMonth11(yy, timeZone) {
    const off = rcJdFromDate(31, 12, yy) - 2415021;
    const k = rcINT(off / 29.530588853);
    let nm = rcGetNewMoonDay(k, timeZone);
    const sunLong = rcGetSunLongitude(nm, timeZone);
    if (sunLong >= 9) nm = rcGetNewMoonDay(k - 1, timeZone);
    return nm;
  }

  function rcGetLeapMonthOffset(a11, timeZone) {
    const k = rcINT((a11 - 2415021.076998695) / 29.530588853 + 0.5);
    let last = 0;
    let i = 1;
    let arc = rcGetSunLongitude(rcGetNewMoonDay(k + i, timeZone), timeZone);
    do {
      last = arc;
      i++;
      arc = rcGetSunLongitude(rcGetNewMoonDay(k + i, timeZone), timeZone);
    } while (arc !== last && i < 14);
    return i - 1;
  }

  function convertSolar2Lunar(dd, mm, yy, timeZone) {
    const dayNumber = rcJdFromDate(dd, mm, yy);
    const k = rcINT((dayNumber - 2415021.076998695) / 29.530588853);
    let monthStart = rcGetNewMoonDay(k + 1, timeZone);
    if (monthStart > dayNumber) monthStart = rcGetNewMoonDay(k, timeZone);
    let a11 = rcGetLunarMonth11(yy, timeZone);
    let b11 = a11;
    let lunarYear;
    if (a11 >= monthStart) {
      lunarYear = yy;
      a11 = rcGetLunarMonth11(yy - 1, timeZone);
    } else {
      lunarYear = yy + 1;
      b11 = rcGetLunarMonth11(yy + 1, timeZone);
    }
    const lunarDay = dayNumber - monthStart + 1;
    const diff = rcINT((monthStart - a11) / 29);
    let lunarLeap = 0;
    let lunarMonth = diff + 11;
    if (b11 - a11 > 365) {
      const leapMonthDiff = rcGetLeapMonthOffset(a11, timeZone);
      if (diff >= leapMonthDiff) {
        lunarMonth = diff + 10;
        if (diff === leapMonthDiff) lunarLeap = 1;
      }
    }
    if (lunarMonth > 12) lunarMonth -= 12;
    if (lunarMonth >= 11 && diff < 4) lunarYear -= 1;
    return [lunarDay, lunarMonth, lunarYear, lunarLeap];
  }

  function getVietnameseWeekday(date) {
    return ["Chủ nhật","Thứ hai","Thứ ba","Thứ tư","Thứ năm","Thứ sáu","Thứ bảy"][date.getDay()];
  }

  function getCanChiYear(year) {
    return ROOT_CLOCK_CAN[(year + 6) % 10] + " " + ROOT_CLOCK_CHI[(year + 8) % 12];
  }

  function formatTimeInZone(date, timeZone) {
    try {
      return new Intl.DateTimeFormat("en-GB", {
        timeZone, hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false
      }).format(date);
    } catch (e) {
      return "--:--:--";
    }
  }

  // Every value the clock block shows, computed fresh from `now` — used
  // both to fill the block in the moment it's created (renderNode) and
  // to refresh it in place every second (rootClockTick) below.
  function rootClockValues(now) {
    const h = String(now.getHours()).padStart(2, "0");
    const m = String(now.getMinutes()).padStart(2, "0");
    const s = String(now.getSeconds()).padStart(2, "0");
    const uh = String(now.getUTCHours()).padStart(2, "0");
    const um = String(now.getUTCMinutes()).padStart(2, "0");
    const us_ = String(now.getUTCSeconds()).padStart(2, "0");
    const dd = now.getDate(), mm = now.getMonth() + 1, yy = now.getFullYear();
    const lunar = convertSolar2Lunar(dd, mm, yy, 7);
    const leapText = lunar[3] ? " nhuận" : "";
    return {
      time: `${h}:${m}:${s}`,
      utc: `${uh}:${um}:${us_}`,
      us: formatTimeInZone(now, "America/New_York"),
      uk: formatTimeInZone(now, "Europe/London"),
      solar: `${getVietnameseWeekday(now)}, ngày ${dd} tháng ${mm} năm ${yy}`,
      lunar: `Âm lịch: ngày ${lunar[0]} tháng ${lunar[1]}${leapText} năm ${getCanChiYear(lunar[2])}`,
    };
  }

  // Only one root node is ever on screen at a time (one map open at
  // once), so a plain class query is enough — no need to track an id.
  function rootClockTick() {
    const block = nodesLayer.querySelector(".node.depth-0 .node-clock-block");
    if (!block) return;
    const v = rootClockValues(new Date());
    const timeEl = block.querySelector(".node-clock-time");
    if (timeEl) timeEl.textContent = v.time;
    const utcEl = block.querySelector('[data-tz="utc"]');
    if (utcEl) utcEl.textContent = v.utc;
    const usEl = block.querySelector('[data-tz="us"]');
    if (usEl) usEl.textContent = v.us;
    const ukEl = block.querySelector('[data-tz="uk"]');
    if (ukEl) ukEl.textContent = v.uk;
    const solarEl = block.querySelector(".node-clock-solar");
    if (solarEl) solarEl.textContent = v.solar;
    const lunarEl = block.querySelector(".node-clock-lunar");
    if (lunarEl) lunarEl.textContent = v.lunar;
  }
  setInterval(() => {
    if (document.visibilityState === "visible") rootClockTick();
  }, 1000);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") rootClockTick();
  });

  // True from the moment an edit schedules a save until that save has
  // actually finished writing everywhere (local DB, folder, Drive) —
  // covers both persist()'s own 500ms debounce delay and the awaits
  // inside it. DriveDB.syncFromDrive() callers (pollDriveUpdates, plus
  // the sign-in/restore sync) check this the same way they check
  // state.editingId, so an incoming sync can't overwrite a change that
  // hasn't finished saving yet, even after you've clicked away from the
  // node itself.
  let unsavedEdits = false;
  let persistTimer = null;

  // Reconciles PhotoDB against whatever photo ids the map's node tree
  // actually references right now, deleting any leftover rows (from a
  // deleted node, a crop/text-edit replacing an id, "Remove all photos"
  // racing an in-flight write, etc.).
  //
  // Called two ways: manually, from the Storage panel's "Clean up
  // current map" button; and automatically, but only via
  // scheduleAutoPhotoCleanup/runAutoPhotoCleanup below, which delay this
  // until 60s after the map's last save with no further edits in
  // between. That restriction is the fix for a real bug this used to
  // have: this function used to run after every single autosave, so ANY
  // moment where the in-memory node tree was transiently incomplete/
  // stale right when a save fired (a race during map load/sync, a bug
  // elsewhere, an interrupted operation, etc.) could make it look like
  // photos were "orphaned" and permanently delete their bytes from
  // PhotoDB — with no undo. Running it only after a full minute of
  // settled quiet (and re-checking the map hasn't changed, nothing's
  // syncing, etc. — see runAutoPhotoCleanup) avoids that same trap while
  // still cleaning things up without a manual click every time.
  async function gcOrphanedPhotos(map) {
    if (!map) return;
    try {
      // Includes photos attached to link comments (video/link screenshots),
      // which the sweep used to overlook.
      const referenced = collectReferencedPhotoIds(map.root);
      const rows = await PhotoDB.getAllForMap(map.id);
      for (const r of rows) {
        if (!referenced.has(r.id)) {
          await PhotoDB.delete(r.id);
          forgetPhotoFingerprint(r.id);
          const url = photoCache.get(r.id);
          if (url) { try { URL.revokeObjectURL(url); } catch (e) { /* already gone */ } }
          photoCache.delete(r.id);
          photoBlobCache.delete(r.id);
        }
      }
    } catch (e) { /* best-effort cleanup, safe to skip on failure */ }
  }

  // Photo rows only ever get orphaned by rare edge cases (an interrupted
  // operation, a bug elsewhere) — the ordinary paths (deleting a node,
  // replacing a photo via crop/text/combine) already delete the old
  // photo id directly, right when it happens. So this doesn't need to
  // run often; it just needs to run at a moment when the in-memory tree
  // is guaranteed to be complete and settled, which the comment above
  // used to rule out for every automatic call site. Idle-after-save is
  // the one moment that's actually safe: scheduleAutoPhotoCleanup below
  // is called every time a save finishes, and (re)starts a fresh 60s
  // timer — so it only ever fires a full minute after the LAST edit,
  // never mid-edit, never mid-sync, and never for a map that isn't the
  // one still open (all checked again in runAutoPhotoCleanup itself,
  // since 60s is long enough for any of that to have changed).
  let autoCleanupTimer = null;
  function scheduleAutoPhotoCleanup(mapId) {
    if (autoCleanupTimer) clearTimeout(autoCleanupTimer);
    autoCleanupTimer = setTimeout(() => runAutoPhotoCleanup(mapId), 60000);
  }
  function cancelAutoPhotoCleanup() {
    if (autoCleanupTimer) { clearTimeout(autoCleanupTimer); autoCleanupTimer = null; }
  }
  async function runAutoPhotoCleanup(mapId) {
    autoCleanupTimer = null;
    // Re-check everything now, not just at schedule time: a full minute
    // has passed, plenty of time for the user to have switched maps,
    // started typing again, backgrounded the tab mid-sync, etc.
    if (!state.current || state.current.id !== mapId) return;
    if (unsavedEdits || persistTimer) return; // another edit landed since scheduling — wait for the next idle window instead
    if (document.visibilityState !== "visible") return;
    if (DriveDB.busy) return;
    try {
      await gcOrphanedPhotos(state.current);
    } catch (e) { /* best-effort — a normal manual cleanup can always catch anything missed */ }
  }

  async function runPersistNow() {
    persistTimer = null;
    if (!state.current) { unsavedEdits = false; return; }
    saveStatus.textContent = "Saving…";
    saveStatus.className = "save-status saving";
    state.current.updatedAt = nextUpdatedAt(state.current);
    state.current.view = { scale: state.scale, tx: state.tx, ty: state.ty };
    const mapToSave = state.current;
    try {
      const deferredPhotoDeletes = takePendingPhotoDeletes();
      try {
        await DB.put(mapToSave);
      } catch (putErr) {
        requeuePhotoDeletes(deferredPhotoDeletes);
        throw putErr;
      }
      // The stored map no longer references those photos — safe to drop them.
      await releasePhotoDeletes(deferredPhotoDeletes, mapToSave);
      await FolderDB.save(mapToSave);
      // Local save (IndexedDB + connected folder) is the fast part and
      // is what this toolbar status is meant to reflect — flip it to
      // "Saved" here instead of waiting on Drive's network PUT below
      // too. The local IndexedDB write itself is now cheap no matter how

      // many photos are attached (they live in their own store — see
      // PhotoDB — not inlined into this JSON), but the folder mirror and
      // Drive upload below still re-embed photo bytes so those files stay
      // self-contained/portable, so on a photo-heavy map the Drive PUT in
      // particular can still take a few seconds over the network; without
      // this split, the toolbar would sit on "Saving…" that whole time
      // even though the actual local save finished instantly. Drive's own
      // progress is tracked separately by the sidebar's "Synced Xs ago"
      // status (see updateDriveUI/driveSyncStatusText), which only
      // updates once the Drive upload genuinely completes.
      const idx = state.maps.findIndex(m => m.id === mapToSave.id);
      if (idx >= 0) state.maps[idx] = mapToSave; else state.maps.unshift(mapToSave);
      sortMaps(state.maps);
      renderSidebar();
      lastSavedAt = Date.now();
      saveStatus.className = "save-status saved";
      updateSaveStatusLabel();
      // Local save landed clean, so the tree this save() call captured is
      // complete and consistent — (re)start the 60s idle window that lets
      // the automatic orphan-photo sweep run (see scheduleAutoPhotoCleanup
      // above). Every subsequent save just pushes this back out, so it
      // only actually fires once a full minute of quiet has passed.
      scheduleAutoPhotoCleanup(mapToSave.id);
    } catch (e) {
      unsavedEdits = false;
      throw e;
    }
    try {
      // Not awaited by the toolbar status above, but still tracked via
      // unsavedEdits until it finishes — an incoming Drive sync must
      // still wait for this device's own pending upload to land first,
      // or it could overwrite this edit with the older remote copy.
      await DriveDB.save(mapToSave);
    } finally {
      unsavedEdits = false;
    }
  }

  // Guards against overlapping saves: on a photo-heavy map, FolderDB/
  // DriveDB.save() re-embeds every photo as base64 and re-uploads the
  // whole map, which can take several real seconds over the network.
  // Without this, persist()'s 500ms debounce only ever cancelled a
  // pending *timer* — if a save was already mid-upload when the next
  // edit's timer fired, runPersistNow() would start a second full
  // upload of the same (large) file right on top of the first, and the
  // two could land out of order. kickPersist() below makes sure only
  // one runPersistNow() is ever in flight at a time, queuing at most one
  // more pass for right after the current one finishes.
  let persistInFlight = false;
  let persistAgainAfter = false;
  // runPersistNow() ends with the Drive upload, which on a photo-heavy map
  // can take many seconds. While one is running, the next save used to just
  // wait its turn — so an edit made in that window was not in IndexedDB at
  // all until the upload finished, and a refresh threw it away. This writes
  // the current state to IndexedDB straight away; the queued full pass still
  // runs afterwards and does the folder mirror + Drive upload as before.
  function saveLocalWhileBusy() {
    const m = state.current;
    if (!m) return;
    m.updatedAt = nextUpdatedAt(m);
    m.view = { scale: state.scale, tx: state.tx, ty: state.ty };
    const deferredPhotoDeletes = takePendingPhotoDeletes();
    DB.put(m)
      .then(() => releasePhotoDeletes(deferredPhotoDeletes, m))
      .catch((e) => { requeuePhotoDeletes(deferredPhotoDeletes); console.error("Local save failed", e); });
  }
  function kickPersist() {
    if (persistInFlight) { persistAgainAfter = true; saveLocalWhileBusy(); return; }
    persistInFlight = true;
    runPersistNow()
      .catch((e) => console.error("Persist failed", e))
      .finally(() => {
        persistInFlight = false;
        if (persistAgainAfter) { persistAgainAfter = false; kickPersist(); }
      });
  }

  function persist() {
    unsavedEdits = true;
    try { updateCloudSyncPill(); } catch (e) {}
    if (persistTimer) clearTimeout(persistTimer);
    persistTimer = setTimeout(kickPersist, 500);
  }

  // Forces a pending save through right away instead of waiting out the
  // rest of the 500ms debounce — used when the tab is about to be
  // backgrounded or closed (see the visibilitychange/pagehide listeners
  // below), since a mobile OS can suspend a background tab mid-timer,
  // silently dropping whatever edit was still waiting to be written to
  // disk/Drive.
  function flushPersist() {
    // Also catches the case where something (like the node countdown
    // timer, which only calls persist() every ~10s to avoid re-saving
    // photo-heavy maps every second) has updated state and flagged
    // unsavedEdits without a pending debounce timer in flight — without
    // this, up to that many seconds of progress could be lost if the
    // tab is closed in between.
    if (!persistTimer && !unsavedEdits) return;
    if (persistTimer) clearTimeout(persistTimer);
    persistTimer = null;
    kickPersist();
  }
  // A note's own text lives only in noteWorkingList/the DOM until its
  // separate 500ms autosave timer (see scheduleNoteAutosave/
  // flushNoteAutosave below) copies it onto the node — flushPersist()
  // above only flushes what's *already* been committed. Without also
  // flushing that inner timer here, typing into a note and backgrounding
  // the tab within that 500ms window (switching apps, locking the
  // screen) drops the just-typed text before it ever reaches persist(),
  // so it's lost locally too — not just unsynced.
  function flushAllPendingSaves() {
    if (typeof noteEditingId !== "undefined" && noteEditingId) flushNoteAutosave();
    flushPersist();
  }
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") flushAllPendingSaves();
  });
  window.addEventListener("pagehide", flushAllPendingSaves);

  // Anything typed but not yet safely on Drive. Covers three separate
  // stages of "not saved yet", because a refresh can land in any of
  // them: still in the note editor's 500ms debounce, still in persist()'s
  // own debounce or mid-write, or written locally but never accepted by
  // Drive (the case a dead Google session produces).
  function hasUnsyncedWork() {
    try {
      if (unsavedEdits || persistTimer || persistInFlight) return true;
      if (noteEditingId && noteSaveTimer) return true;
      if (!DriveDB.signedIn) return false;
      for (const m of state.maps) {
        const known = DriveDB.fileIndex[m.id];
        if (!known || (m.updatedAt || 0) > (known.updatedAt || 0)) return true;
      }
    } catch (e) { return false; }
    return false;
  }

  // pagehide's flush above kicks off async IndexedDB and Drive writes,
  // and a page being torn down is under no obligation to wait for them —
  // a refresh at the wrong moment can abort the transaction mid-write,
  // which is how a session's work can vanish on F5 even though the app
  // had "saved" it. This is the only mechanism a browser gives a page to
  // buy that time: ask the person first. The prompt only appears when
  // there is genuinely something unwritten, so a normal refresh on a
  // fully-synced map is untouched.
  window.addEventListener("beforeunload", (e) => {
    if (!hasUnsyncedWork()) return;
    e.preventDefault();
    e.returnValue = "";
    return "";
  });

  // Panning/zooming the canvas only changes where you're *looking* — not
  // the map's actual content — so it must never bump `updatedAt` the way
  // persist() does. `updatedAt` is what Drive/folder sync uses to decide
  // whose copy is newer; if a pure view change bumped it, simply opening
  // a map on another device and glancing around (nudging the scroll a
  // pixel, say) would make that device's copy look like the "latest"
  // edit even though its actual content is stale — and that stale
  // content would then overwrite a genuine edit made elsewhere. This
  // still saves the view locally (so your pan/zoom position is
  // remembered next time you open this map) but never touches
  // `updatedAt` and never pushes to Folder/Drive sync — view position
  // is treated as a per-device thing, not something worth syncing.
  const persistViewOnly = debounce(async () => {
    if (!state.current) return;
    state.current.view = { scale: state.scale, tx: state.tx, ty: state.ty };
    await DB.put(state.current);
  }, 500);

  // Every snapshot here is a full JSON.stringify of the map's whole node
  // tree — and that tree carries each node's attached photos inline as
  // base64 data URLs. Capping the stacks at 60 *entries* (below) bounds
  // how many edits back you can go, but says nothing about how much
  // memory those 60 entries actually take: a photo-heavy map re-clones
  // every one of its embedded images into a brand-new string on every
  // single edit (even a one-character text change), so 60 of those
  // snapshots can add up to hundreds of MB sitting in the JS heap for
  // one open map — the actual cause of the "Out of Memory" crashes some
  // photo-heavy maps were hitting after a while. This keeps the same
  // 60-entry depth for ordinary (photo-light) maps, where it costs
  // nothing, but for anything bigger it also evicts the oldest entries
  // once the stack's total size passes a fixed budget, so memory use
  // stays bounded regardless of how many photos a map carries.
  const UNDO_STACK_MAX_BYTES = 25 * 1024 * 1024; // ~25MB per stack
  function pushBoundedSnapshot(stack, json, maxCount) {
    stack.push(json);
    if (stack.length > (maxCount || 60)) stack.shift();
    let total = 0;
    for (const s of stack) total += s.length;
    while (total > UNDO_STACK_MAX_BYTES && stack.length > 1) {
      total -= stack.shift().length;
    }
  }

  function pushUndo() {
    if (!state.current) return;
    if (!requireSignIn()) throw new EditBlockedError();
    pushBoundedSnapshot(state.undoStack, JSON.stringify({ root: state.current.root, links: state.current.links || [] }));
    state.redoStack = [];
  }

  function undo() {
    if (!requireSignIn()) return;
    if (!state.current || state.undoStack.length === 0) return;
    pushBoundedSnapshot(state.redoStack, JSON.stringify({ root: state.current.root, links: state.current.links || [] }));
    const snap = JSON.parse(state.undoStack.pop());
    state.current.root = snap.root;
    state.current.links = snap.links || [];
    state.selectedId = null;
    state.selectedCell = null;
    state.cellRangeAnchor = null;
    state.cellRange = null;
    renderAll();
    persist();
  }

  function redo() {
    if (!requireSignIn()) return;
    if (!state.current || state.redoStack.length === 0) return;
    pushBoundedSnapshot(state.undoStack, JSON.stringify({ root: state.current.root, links: state.current.links || [] }));
    const snap = JSON.parse(state.redoStack.pop());
    state.current.root = snap.root;
    state.current.links = snap.links || [];
    state.selectedId = null;
    state.selectedCell = null;
    state.cellRangeAnchor = null;
    state.cellRange = null;
    renderAll();
    persist();
  }

  // Keeps the toolbar undo/redo buttons' enabled state in sync with the
  // stacks. Called from renderAll() (covers pushUndo/undo/redo, map loads,
  // and clearCanvas) rather than threaded through every call site.
  function updateUndoRedoButtons() {
    const undoBtn = $("#btn-undo");
    const redoBtn = $("#btn-redo");
    if (!undoBtn || !redoBtn) return;
    const locked = !isEditingAllowed();
    undoBtn.disabled = locked || !state.current || state.undoStack.length === 0;
    redoBtn.disabled = locked || !state.current || state.redoStack.length === 0;
  }

  /* ---------------- sidebar ---------------- */

  const signedOutState = $("#signed-out-state");
  const sidebarSignedOutNote = $("#mindmap-list-signed-out");

  // Nothing map-related is shown until a Google session is BOTH confirmed
  // AND actually synced — signedIn flips true the instant we have a fresh
  // token, which is *before* syncFromDrive() has pulled this device's
  // latest copy down (see DriveDB.signIn/.restore). Gating on signedIn
  // alone let updateDriveUI()'s "Syncing…" call (which also calls this)
  // un-hide #world early, while renderSidebar() (the only thing that
  // hides the "Sign in with Google" panel) hadn't run yet — so for that
  // whole sync window you'd see stale/cached map content AND the sign-in
  // panel on screen at once. Requiring dataSynced too closes that gap.
  function mapsReadyToShow() {
    return !!DriveDB.signedIn && !!DriveDB.dataSynced;
  }

  // Toggles the body-level CSS gate (canvas/FABs, see style.css) and
  // keeps the signed-out/syncing panel's own text in sync with *why*
  // it's showing, so a signed-in-but-still-syncing tab says "Syncing…"
  // rather than the misleading "Sign in with Google" (which also
  // shouldn't invite a redundant second sign-in tap mid-sync).
  function applySignedOutGate() {
    const ready = mapsReadyToShow();
    document.body.classList.toggle("signed-out", !ready);
    if (ready) return;
    const stillSyncing = DriveDB.signedIn && !DriveDB.dataSynced;
    const heading = signedOutState.querySelector("p");
    const btn = $("#btn-signed-out-signin");
    if (heading) heading.textContent = stillSyncing ? "Syncing your maps…" : "Sign in with Google to see your mind maps.";
    if (btn) btn.classList.toggle("hidden", stillSyncing);
    if (sidebarSignedOutNote) sidebarSignedOutNote.textContent = stillSyncing ? "Syncing your maps…" : "Sign in with Google to see your maps.";
  }

  function renderSidebar() {
    sortMaps(state.maps);
    listEl.innerHTML = "";
    applySignedOutGate();
    if (!mapsReadyToShow()) {
      emptyState.classList.add("hidden");
      nodeFabs.classList.add("hidden");
      signedOutState.classList.remove("hidden");
      if (sidebarSignedOutNote) sidebarSignedOutNote.classList.remove("hidden");
      return; // don't build any map list items until signed in AND synced
    }
    signedOutState.classList.add("hidden");
    if (sidebarSignedOutNote) sidebarSignedOutNote.classList.add("hidden");
    const visibleMaps = activeMaps();
    if (visibleMaps.length === 0) {
      emptyState.classList.remove("hidden");
      nodeFabs.classList.add("hidden");
    } else {
      emptyState.classList.add("hidden");
      nodeFabs.classList.remove("hidden");
    }
    updateTrashBadge();
    for (const m of visibleMaps) {
      const li = document.createElement("li");
      const isMoveTarget = !!state.moveSourceId && (!state.current || m.id !== state.current.id);
      li.className = "map-item"
        + (state.current && m.id === state.current.id ? " active" : "")
        + (isMoveTarget ? " move-target" : "");
      const star = document.createElement("span");
      star.className = "item-star" + (m.favorite ? " favorited" : "");
      star.textContent = m.favorite ? "★" : "☆";
      star.title = m.favorite ? "Remove from favorites" : "Add to favorites";
      star.addEventListener("click", (e) => { e.stopPropagation(); toggleFavorite(m.id); });
      const dot = document.createElement("span"); dot.className = "dot";
      const name = document.createElement("span"); name.className = "name"; name.textContent = m.title || "Untitled map";
      const meta = document.createElement("span"); meta.className = "meta"; meta.textContent = relTime(m.updatedAt);
      const del = document.createElement("span"); del.className = "item-del"; del.textContent = "✕";
      del.title = "Move to trash";
      del.addEventListener("click", (e) => { e.stopPropagation(); deleteMap(m.id); });
      li.append(star, dot, name, meta, del);
      if (isMoveTarget) {
        li.title = "Move here";
        li.addEventListener("click", () => completeMoveToMap(m.id));
      } else {
        li.addEventListener("click", () => openMap(m.id));
      }
      listEl.appendChild(li);
    }
  }

  // Favoriting doesn't go through the debounced `persist()` (that only ever
  // saves state.current) since you can star any map in the list, including
  // ones that aren't currently open — so it saves directly instead.
  async function toggleFavorite(id) {
    if (!requireSignIn()) return;
    const m = state.maps.find(x => x.id === id);
    if (!m) return;
    m.favorite = !m.favorite;
    await DB.put(m);
    await FolderDB.save(m);
    await DriveDB.save(m);
    renderSidebar();
  }

  function relTime(ts) {
    const s = Math.floor((Date.now() - ts) / 1000);
    if (s < 60) return "now";
    if (s < 3600) return Math.floor(s / 60) + "m";
    if (s < 86400) return Math.floor(s / 3600) + "h";
    return Math.floor(s / 86400) + "d";
  }

  const LAST_OPENED_MAP_KEY = "branchline_last_opened_map";
  async function openMap(id) {
    const m = state.maps.find(x => x.id === id);
    if (!m) return;
    commitEditIfActive();
    cancelAutoPhotoCleanup(); // leaving the map it was scheduled for — never let it fire against the next one
    state.current = m;
    ensureTheme(state.current);
    ensureLinks(state.current);
    ensureLayout(state.current);
    ensureFavorite(state.current);
    ensureTrash(state.current);
    ensureClockHidden(state.current);
    document.getElementById("app").classList.toggle("hide-clock-widgets", isClockHidden());
    ensureSidesRepaired(state.current);
    ensureAffirmationMigrated(state.current);
    if (!state.current._photosMigrated) await ensurePhotosMigrated(state.current);
    await loadPhotoCacheForMap(state.current.id);
    state.selectedId = null;
    state.selectedCell = null;
    state.cellRangeAnchor = null;
    state.cellRange = null;
    state.editingId = null;
    state.linkFromId = null;
    state.moveSourceId = null;
    state.highlightId = null;
    state.undoStack = [];
    state.redoStack = [];
    const v = m.view || { scale: 1, tx: 60, ty: 60 };
    state.scale = v.scale || 1; state.tx = v.tx || 60; state.ty = v.ty || 60;
    // Belongs to whichever map was open before — without clearing it, the
    // first render of the newly-opened map would "compensate" tx/ty against
    // a stale bounding box from a completely different tree.
    state.originX = undefined;
    state.originY = undefined;
    titleInput.value = m.title || "";
    layoutSelect.value = state.current.layout || "mindmap";
    renderSidebar();
    renderAll();
    applyTransform();
    // Remembered across reloads so boot() can reopen whichever map you
    // were last looking at, rather than always the top of the sidebar
    // list (most recently *edited*, which isn't necessarily the same map).
    try { localStorage.setItem(LAST_OPENED_MAP_KEY, id); } catch (e) {}
  }

  async function createMap() {
    if (!requireSignIn()) return;
    const m = newMindMap("Untitled map");
    state.maps.unshift(m);
    await DB.put(m);
    await openMap(m.id);
    titleInput.focus();
    titleInput.select();
  }

  // Soft delete: moves the map to the trash (see #trash-modal) instead of
  // removing it outright. It stays in state.maps (and keeps syncing to the
  // folder/Drive like any other edit) but is filtered out of the regular
  // sidebar list by activeMaps(). Only permanentlyDeleteMap actually
  // removes it from storage.
  async function deleteMap(id) {
    if (!requireSignIn()) return;
    const m = state.maps.find(x => x.id === id);
    if (!m) return;
    if (!confirm(`Move "${m.title || 'Untitled map'}" to trash?`)) return;

    // Optimistic UI: mark the map trashed and remove it from the visible
    // sidebar immediately. Previously we waited for IndexedDB/folder/Drive
    // saves first, so on a slow Drive connection the row (and, for the open
    // map, its canvas) could sit there for a noticeable moment even though
    // the delete had already been accepted.
    m.trashedAt = Date.now();
    const deletingCurrent = !!(state.current && state.current.id === id);
    let nextOpenPromise = null;

    if (deletingCurrent) {
      state.current = null;
      const next = activeMaps();

      // Remove the trashed row right now and clear the old canvas so there
      // is no visual ghost while the next map's photos/data are loading.
      renderSidebar();
      clearCanvas();

      if (next.length) {
        nextOpenPromise = openMap(next[0].id);
      } else {
        // No map left open — release the trashed map's photos instead of
        // leaving their object URLs (and the Blobs they keep alive)
        // resident in memory with nothing on screen to show for them.
        revokePhotoCache();
        photoCache = new Map();
        photoBlobCache = new Map();
      }
    } else {
      // For a non-open map this is all that's needed to make the sidebar
      // update instantly; persistence can finish afterwards.
      renderSidebar();
    }

    // Persist after the visual update. Run the independent saves together so
    // a slow network sync never blocks the UI. Keep awaiting them here so the
    // caller still observes completion, but the user already sees the result.
    const persistPromise = Promise.all([
      DB.put(m),
      FolderDB.save(m),
      DriveDB.save(m)
    ]);

    if (nextOpenPromise) {
      await Promise.all([persistPromise, nextOpenPromise]);
    } else {
      await persistPromise;
    }
  }

  async function restoreMap(id) {
    if (!requireSignIn()) return;
    const m = state.maps.find(x => x.id === id);
    if (!m) return;
    m.trashedAt = null;
    await DB.put(m);
    await FolderDB.save(m);
    await DriveDB.save(m);
    renderSidebar();
    renderTrashModal();
  }

  // Strips fields that only ever exist to make one specific instance of a
  // node/map unique (its id, and the createdAt/updatedAt stamps on it) so
  // two independently-created copies of otherwise-identical content
  // compare equal below. Recurses into every nested object/array (notes,
  // tasks, photos, links, table cells, etc.) — not just top-level nodes —
  // since a duplicate map is a full deep copy, ids and all, all the way
  // down.
  function stripIdentifiersForDupeCheck(value) {
    if (Array.isArray(value)) return value.map(stripIdentifiersForDupeCheck);
    if (value && typeof value === "object") {
      const out = {};
      for (const k of Object.keys(value)) {
        if (k === "id" || k === "createdAt" || k === "updatedAt") continue;
        out[k] = stripIdentifiersForDupeCheck(value[k]);
      }
      return out;
    }
    return value;
  }

  // A content "fingerprint" for a map: its whole tree of nodes plus
  // cross-links, with every id/timestamp stripped out (see above) so two
  // maps that are otherwise word-for-word identical fingerprint the same
  // even though every node under them got its own fresh id when each copy
  // was created.
  function mapContentFingerprint(map) {
    return JSON.stringify(stripIdentifiersForDupeCheck({ root: map.root, links: map.links || [] }));
  }

  // Auto-cleanup run once at boot (see boot() below): finds active,
  // non-trashed maps in the sidebar that share both the exact same title
  // and the exact same content fingerprint, and trashes every copy but
  // the most recently updated one. Soft-deletes (same as deleteMap) so a
  // false match is always recoverable from the trash modal, and skips any
  // map already in the trash — this only ever tidies the regular sidebar
  // list. Returns how many duplicates were trashed, for the console.
  async function autoRemoveDuplicateMaps() {
    const bestForSignature = new Map(); // signature -> map currently being kept
    const toTrash = [];
    for (const m of activeMaps()) {
      const signature = (m.title || "").trim() + "\u0000" + mapContentFingerprint(m);
      const kept = bestForSignature.get(signature);
      if (!kept) {
        bestForSignature.set(signature, m);
        continue;
      }
      if ((m.updatedAt || 0) > (kept.updatedAt || 0)) {
        bestForSignature.set(signature, m);
        toTrash.push(kept);
      } else {
        toTrash.push(m);
      }
    }
    for (const dup of toTrash) {
      dup.trashedAt = Date.now();
      await DB.put(dup);
      await FolderDB.save(dup);
      await DriveDB.save(dup);
    }
    return toTrash.length;
  }

  async function permanentlyDeleteMap(id) {
    if (!requireSignIn()) return;
    const m = state.maps.find(x => x.id === id);
    if (!m) return;
    if (!confirm(`Permanently delete "${m.title || 'Untitled map'}"? This cannot be undone.`)) return;
    await DB.delete(id);
    await PhotoDB.deleteAllForMap(id);
    await FolderDB.remove(m);
    await DriveDB.remove(m);
    state.maps = state.maps.filter(x => x.id !== id);
    renderTrashModal();
    renderSidebar();
  }

  async function emptyTrash() {
    if (!requireSignIn()) return;
    const trashed = trashedMapsList();
    if (!trashed.length) return;
    if (!confirm(`Permanently delete all ${trashed.length} map${trashed.length === 1 ? "" : "s"} in the trash? This cannot be undone.`)) return;
    // Each step below can fail independently (a blocked IndexedDB
    // transaction, a Drive API hiccup, etc.). Previously an error from
    // any single one aborted this whole loop — since state.maps/the UI
    // only updated *after* the loop finished, one bad map meant nothing
    // visibly happened at all, even for maps that deleted fine before
    // it. Isolating each map's cleanup, and updating state/UI as each
    // one actually succeeds, means one failure no longer silently blocks
    // every other deletion.
    const failed = [];
    for (const m of trashed) {
      try {
        await DB.delete(m.id);
        await PhotoDB.deleteAllForMap(m.id);
        await FolderDB.remove(m);
        await DriveDB.remove(m);
        state.maps = state.maps.filter(x => x.id !== m.id);
      } catch (e) {
        console.error("Failed to permanently delete map from trash", m.id, e);
        failed.push(m);
      }
    }
    renderTrashModal();
    renderSidebar();
    if (failed.length) {
      alert(`${failed.length} of ${trashed.length} map${trashed.length === 1 ? "" : "s"} couldn't be deleted (still in the trash) — check the console for details, or try again.`);
    }
  }

  function updateTrashBadge() {
    const badge = $("#trash-count-badge");
    if (!badge) return;
    const n = trashedMapsList().length;
    badge.textContent = String(n);
    badge.classList.toggle("hidden", n === 0);
  }

  function clearCanvas() {
    nodesLayer.innerHTML = "";
    svgEl.innerHTML = "";
    titleInput.value = "";
    layoutSelect.value = "mindmap";
    emptyState.classList.remove("hidden");
    nodeFabs.classList.add("hidden");
    updateUndoRedoButtons();
  }

  /* ---------------- layout engine ---------------- */

  const TIMELINE_ROOT_GAP = 34;  // gap from root down to the first branch's row
  const TIMELINE_ROW_GAP = 20;   // gap between one branch's row and the next

  // Shared depth/size measuring pass, used by every layout mode.
  function measureTree(node, depth) {
    node._depth = depth;
    computeNodeBox(node);
    if (node.collapsed || !node.children || node.children.length === 0) return;
    for (const c of node.children) measureTree(c, depth + 1);
  }

  // Shared bounding-box pass (including any manual drag offsets), used by
  // every layout mode once node._x/_y have been assigned.
  function computeBBox(root) {
    let minX = 0, maxX = 0, minY = 0, maxY = 0;
    (function walk(n) {
      const w = n._w, h = n._h;
      const nx = nodeCenterX(n), ny = n._y + (n.oy || 0);
      minX = Math.min(minX, nx - w / 2);
      maxX = Math.max(maxX, nx + w / 2);
      minY = Math.min(minY, ny - h / 2);
      maxY = Math.max(maxY, ny + h / 2);
      if (!n.collapsed) (n.children || []).forEach(walk);
    })(root);
    return { minX, maxX, minY, maxY };
  }

  function layout(root) {
    const mode = (state.current && state.current.layout) || "mindmap";
    if (mode === "logic" || mode === "righty") layoutMindmap(root, false);
    else if (mode === "timeline") layoutTimeline(root);
    else layoutMindmap(root, true);
    // The layout passes above place every node at its automatic slot, then
    // manual drag offsets (ox/oy) are added on top at render time. Dragging
    // a node — or editing text so a box grows — can push it into a sibling
    // it wasn't overlapping before. Rather than only fixing that when the
    // user explicitly clicks "Auto-arrange" (which wipes every manual nudge
    // in the whole map), resolve any leftover overlaps here on every
    // render, so nodes never visually collide but manual positioning is
    // otherwise left alone.
    resolveOverlaps(root);
    return computeBBox(root);
  }

  // Nudges any two overlapping node boxes apart vertically (never
  // horizontally, so each node's depth column — and therefore the whole
  // branch/tree reading order — stays put) until nothing overlaps. Runs as
  // a handful of relaxation passes since separating one pair can introduce
  // a new overlap with a third node.
  function resolveOverlaps(root) {
    const nodes = [];
    // Track each node's parent (just for this pass) so we can tell ancestor
    // pairs apart from unrelated ones below, and so an overlap fix can carry
    // a node's whole subtree along with it instead of leaving children
    // behind at their old spot.
    const parentOf = new Map();
    (function collect(n, parent) {
      if (n !== root) nodes.push(n);
      if (parent) parentOf.set(n, parent);
      if (!n.collapsed) (n.children || []).forEach(c => collect(c, n));
    })(root, null);

    function isAncestor(a, b) {
      // true if `a` is an ancestor of `b` — an ancestor/descendant pair is
      // expected to sit close together (that's the whole point of the
      // connector between them) and pushing them apart would just detach
      // the child from its parent's column, so those pairs are skipped.
      let p = parentOf.get(b);
      while (p) {
        if (p === a) return true;
        p = parentOf.get(p);
      }
      return false;
    }

    // Moves a node AND everything under it by the same amount, so a node's
    // children stay put relative to their parent — i.e. each node's own
    // subtree keeps its internal vertical alignment — instead of the parent
    // drifting away from children left behind at their pre-push position
    // (which is what used to cause a moved branch's descendants to overlap
    // an unrelated neighboring branch).
    function shiftSubtree(n, dy) {
      n._y += dy;
      if (!n.collapsed) (n.children || []).forEach(c => shiftSubtree(c, dy));
    }

    const PAD = 10;
    const MAX_PASSES = 8;
    for (let pass = 0; pass < MAX_PASSES; pass++) {
      let moved = false;
      for (let i = 0; i < nodes.length; i++) {
        for (let j = i + 1; j < nodes.length; j++) {
          const a = nodes[i], b = nodes[j];
          if (isAncestor(a, b) || isAncestor(b, a)) continue;
          const ax = nodeCenterX(a), ay = a._y + (a.oy || 0);
          const bx = nodeCenterX(b), by = b._y + (b.oy || 0);
          const overlapX = (a._w / 2 + b._w / 2 + PAD) - Math.abs(ax - bx);
          const overlapY = (a._h / 2 + b._h / 2 + PAD) - Math.abs(ay - by);
          if (overlapX > 0 && overlapY > 0) {
            moved = true;
            const push = overlapY / 2;
            if (ay <= by) { shiftSubtree(a, -push); shiftSubtree(b, push); }
            else { shiftSubtree(a, push); shiftSubtree(b, -push); }
          }
        }
      }
      if (!moved) break;
    }
  }

  // Classic radial mind map. With splitSides=true, top-level branches
  // alternate left/right of the root (the default "Mindmap" layout). With
  // splitSides=false, every branch fans out to the right only, stacked
  // top to bottom (the "Righty mindmap" layout).
  function layoutMindmap(root, splitSides) {
    const children = root.children || [];
    const right = [], left = [];
    if (splitSides) {
      // Each top-level branch keeps whatever side it was already assigned
      // (persisted on the node itself), so reordering siblings — or adding
      // a new one — never flips a side that wasn't the one actually being
      // dragged. Only a node that has never had a side (brand new, or from
      // a map saved before this existed) gets one now, balanced against
      // whatever's already assigned so a fresh map still fans out evenly.
      let rightCount = children.filter(c => c.side === "right").length;
      let leftCount = children.filter(c => c.side === "left").length;
      children.forEach(c => {
        if (c.side !== "left" && c.side !== "right") {
          if (leftCount < rightCount) { c.side = "left"; leftCount++; }
          else { c.side = "right"; rightCount++; }
        }
      });
      children.forEach(c => (c.side === "left" ? left : right).push(c));
    } else {
      children.forEach(c => right.push(c));
    }

    root._x = 0; root._y = 0; root._depth = 0;
    computeNodeBox(root);

    // How much vertical room a node's whole subtree needs to stack without
    // overlapping ITSELF — its own height, or the combined height of its
    // children (with gaps) if that's bigger. This is computed bottom-up and
    // is purely local to the node: it has no idea what any other branch, or
    // any node at the "same level" elsewhere in the tree, looks like. That's
    // what let's place() below give every node a private slot sized to its
    // own subtree, so alignment only ever has to work *inside* that node —
    // an unrelated node at the same depth in a different branch never needs
    // to line up with it, and can't be pushed into it either.
    function subtreeExtent(node) {
      if (node.collapsed || !node.children || node.children.length === 0) {
        return (node._subtreeH = node._h || NODE_H);
      }
      let total = 0;
      node.children.forEach((c, i) => {
        total += subtreeExtent(c);
        if (i > 0) total += SLOT_GAP;
      });
      return (node._subtreeH = Math.max(node._h || NODE_H, total));
    }

    // Places a node at vertical center `y`, inside the slot [y -
    // node._subtreeH/2, y + node._subtreeH/2] already reserved for its
    // whole subtree by the caller. Children are stacked and centered
    // entirely within that local slot, so a node's own layout never
    // depends on, or disturbs, anything outside its own subtree.
    function place(node, depth, sign, y, parentOffset) {
      // A node normally just inherits the direction its ancestor branch is
      // already fanning (the `sign` handed down from the caller). But if
      // this particular node has its own explicit left/right override
      // (set when the user drags it across the center line — see
      // maybeFlipSideOnDrop), that wins instead, and everything under it
      // switches to fan the same way, regardless of which side its parent
      // is on.
      // Only a top-level branch (depth 1, i.e. a direct child of root) is
      // allowed to pick its own side — that's what makes each branch fan
      // one direction only. A deeper node can still end up with a leftover
      // .side (e.g. from being dragged across its branch's local spine
      // while in Timeline mode), but Mindmap mode must ignore that here,
      // or a single branch would fan both left and right at once.
      // This whole override is also gated on splitSides: in the
      // one-direction layout (Righty mindmap, splitSides=false) every
      // top-level branch must fan the same way regardless of any leftover
      // .side a node picked up from a previous stint in real (two-sided)
      // Mindmap mode — otherwise a branch dragged left back when the map
      // was in Mindmap mode would keep sitting on the left forever after
      // switching to a right-only layout.
      const nodeSign = (splitSides && depth === 1 && (node.side === "left" || node.side === "right"))
        ? (node.side === "left" ? -1 : 1)
        : sign;
      // Distance out from the center builds up hop by hop from the parent's
      // own OUTER edge (not just its anchor point), so a wide parent node
      // — one whose text pushed its box wider than the default gap — still
      // leaves enough room before its child starts. A custom xGap on one
      // node (see gapFor) still shifts it and everything past it without
      // disturbing anything closer in; it's just measured from the actual
      // rendered edge now instead of a flat distance from the root.
      const offset = parentOffset + gapFor(node);
      node._x = nodeSign * offset;
      if (node.collapsed || !node.children || node.children.length === 0) {
        node._y = y;
        return;
      }
      let total = 0;
      node.children.forEach((c, i) => {
        total += c._subtreeH;
        if (i > 0) total += SLOT_GAP;
      });
      let cursor = y - total / 2;
      node.children.forEach(c => {
        const center = cursor + c._subtreeH / 2;
        place(c, depth + 1, nodeSign, center, offset + node._w);
        cursor += c._subtreeH + SLOT_GAP;
      });
      // center parent over its children
      const first = node.children[0]._y;
      const last = node.children[node.children.length - 1]._y;
      node._y = (first + last) / 2;
    }

    function layoutSide(list, sign) {
      if (list.length === 0) return;
      list.forEach(n => measureTree(n, 1));
      list.forEach(n => subtreeExtent(n));
      let total = 0;
      list.forEach((n, i) => {
        total += n._subtreeH;
        if (i > 0) total += SLOT_GAP;
      });
      let cursor = -total / 2;
      list.forEach(n => {
        const center = cursor + n._subtreeH / 2;
        // The root is centered on the spine (not anchored like everything
        // past it), so its "outer edge" toward this fan direction is half
        // its own width, not 0 — otherwise a wide root would suffer the
        // same too-close-to-its-child overlap that wide non-root nodes do.
        place(n, 1, sign, center, root._w / 2);
        cursor += n._subtreeH + SLOT_GAP;
      });
    }

    layoutSide(right, 1);
    layoutSide(left, -1);

    return computeBBox(root);
  }

  // Vertical "spine" layout: the root sits in the middle with each
  // top-level branch stacked along the spine above or below it. Each
  // branch's own descendants fan out sideways from that branch —
  // splitting between left and right (like a mini mind map hanging off
  // the spine) rather than being locked to a single side for the whole
  // branch, so a branch with a lot of children doesn't need to push way
  // out to one side while the other side sits empty.
  //
  // A branch normally sits below the root (the original, and still
  // default, arrangement), but dragging it above the root instead flips
  // an explicit node.vSide === "above" flag (see maybeFlipVSideOnDrop/
  // maybeFlipVSideDuringDrag) that sends it — and it alone, not its
  // siblings — up onto the other half of the spine. Only a top-level
  // branch has a vSide; it has no meaning at any other depth, so it's
  // left untouched everywhere else (same treatment as .side).
  function layoutTimeline(root) {
    const children = root.children || [];
    root._x = 0; root._y = 0; root._depth = 0;
    measureTree(root, 0);

    // Pass 1: lay out each branch's own subtree in isolation, centered on
    // its own local y=0 (not yet placed on the spine), and record how
    // tall that centered subtree actually is. This has to happen before
    // any row is positioned, because — see pass 2 below — a row needs to
    // know the height of the row AFTER it, not just its own, to leave a
    // clean gap on both sides.
    const laidOut = children.map((branch) => {
      branch._x = 0; // always sits directly on the spine

      // Split this branch's own direct children left/right, exactly like
      // the Mindmap layout splits the root's children — each child keeps
      // whatever side it was already assigned (persisted on the node
      // itself via maybeFlipSideOnDrop), and only a side-less child (brand
      // new, or from a map saved before this existed) gets balanced onto
      // whichever side currently has fewer. Crucially, that auto-balance
      // is NOT written back onto c.side: .side is a shared field that
      // Mindmap mode's own place() also reads for every node (not just
      // root's direct children), so persisting an auto-assigned side here
      // would leak into Mindmap mode and make that same node split away
      // from its branch there too. Only a genuinely user-dragged side
      // (already present on the node) is meant to carry across layouts —
      // an auto-balanced one is scoped to this Timeline render only.
      //
      // That auto-assigned side is still cached on the node (as _autoSide,
      // a runtime-only field, never saved) so it's STABLE across renders —
      // computed once per side-less child and reused after that. Without
      // this, the balance below is recomputed from scratch every layout
      // purely off the current left/right counts, so dragging one sibling
      // to explicitly flip its own side would shift those counts and could
      // flip a completely different, untouched sibling to the other side
      // too. Caching means only a node you actually drag ever changes side.
      const bChildren = branch.children || [];
      const right = [], left = [];
      if (bChildren.length) {
        let rightCount = bChildren.filter(c => c.side === "right" || (!c.side && c._autoSide === "right")).length;
        let leftCount = bChildren.filter(c => c.side === "left" || (!c.side && c._autoSide === "left")).length;
        bChildren.forEach(c => {
          if (c.side === "left") { left.push(c); return; }
          if (c.side === "right") { right.push(c); return; }
          if (c._autoSide === "left") { left.push(c); return; }
          if (c._autoSide === "right") { right.push(c); return; }
          if (leftCount < rightCount) { left.push(c); leftCount++; c._autoSide = "left"; }
          else { right.push(c); rightCount++; c._autoSide = "right"; }
        });
      }

      // Same local, bottom-up sizing idea as the Mindmap layout's
      // subtreeExtent(): how much vertical room a node's own subtree needs,
      // based only on itself and its own descendants — never on any other
      // branch or any node elsewhere at the "same level". That's what lets
      // each node's children be spaced purely relative to each other.
      function subtreeExtent(node) {
        if (node.collapsed || !node.children || node.children.length === 0) {
          return (node._subtreeH = node._h || NODE_H);
        }
        let total = 0;
        node.children.forEach((c, i) => {
          total += subtreeExtent(c);
          if (i > 0) total += SLOT_GAP;
        });
        return (node._subtreeH = Math.max(node._h || NODE_H, total));
      }

      // Same recursive placement as the Mindmap layout's place(): a node
      // normally inherits the direction its ancestor is already fanning,
      // but its own explicit side override (set by dragging it across the
      // spine) wins instead, and everything under it follows that instead.
      // `y` is the vertical center of the slot already reserved for this
      // node's whole subtree, so its children only ever need to fit inside
      // that local slot.
      function place(node, curSign, y, parentOffset) {
        const nodeSign = node.side === "left" ? -1 : node.side === "right" ? 1 : curSign;
        // Measured from the parent's own OUTER edge (not just its anchor
        // point), so a wide parent — one whose text pushed its box wider
        // than the default gap — still leaves enough room before its own
        // child starts, instead of the child's edge landing inside it.
        const offset = parentOffset + gapFor(node);
        node._x = nodeSign * offset;
        if (node.collapsed || !node.children || node.children.length === 0) {
          node._y = y;
          return;
        }
        let total = 0;
        node.children.forEach((c, i) => {
          total += c._subtreeH;
          if (i > 0) total += SLOT_GAP;
        });
        let cursor = y - total / 2;
        node.children.forEach(c => {
          const center = cursor + c._subtreeH / 2;
          place(c, nodeSign, center, offset + node._w);
          cursor += c._subtreeH + SLOT_GAP;
        });
        const first = node.children[0]._y;
        const last = node.children[node.children.length - 1]._y;
        node._y = (first + last) / 2;
      }

      // Lays out one side's subtree(s) stacked top-to-bottom and centered
      // on this branch's own local y=0 — same idea as the Mindmap layout's
      // layoutSide(), just scoped to one branch instead of the whole map.
      // Returns the side's total stacked height so the row height below can
      // be the TALLER of the two sides, not their sum.
      function layoutSide(list, sign) {
        if (list.length === 0) return 0;
        list.forEach(n => subtreeExtent(n));
        let total = 0;
        list.forEach((n, i) => {
          total += n._subtreeH;
          if (i > 0) total += SLOT_GAP;
        });
        let cursor = -total / 2;
        list.forEach(n => {
          const center = cursor + n._subtreeH / 2;
          // The branch itself sits centered on the spine (branch._x === 0,
          // same treatment as the root), so its outer edge toward this fan
          // direction is half its own width, not 0.
          place(n, sign, center, branch._w / 2);
          cursor += n._subtreeH + SLOT_GAP;
        });
        return total;
      }

      const rightHeight = layoutSide(right, 1);
      const leftHeight = layoutSide(left, -1);
      const localHeight = Math.max(branch._h || NODE_H, rightHeight, leftHeight);
      branch._y = 0; // both sides were just centered around this same baseline
      return { branch, localHeight };
    });

    // Split the rows into the two halves of the spine. A side-less branch
    // (no explicit vSide — every branch before this feature existed, and
    // every new one by default) goes below, exactly as before; only a
    // branch explicitly dragged above the root (vSide === "above") moves
    // to the top half. Relative order within each half is whatever order
    // those branches already have in the (single, shared) children array.
    const belowLaidOut = laidOut.filter(({ branch }) => branch.vSide !== "above");
    const aboveLaidOut = laidOut.filter(({ branch }) => branch.vSide === "above");

    // Place each row along the spine. Two branches can have very
    // different heights (especially now that each one's own children can
    // split across both sides instead of piling onto a single side), so
    // spacing rows by "previous branch's height + gap" alone isn't
    // enough — a short branch followed by a tall one would let the tall
    // one's top half creep up into the short one's row. Advancing by
    // HALF the previous row's height plus HALF the next row's height
    // (plus the fixed gap) instead guarantees the same clean gap between
    // every pair of rows regardless of how lopsided their heights are —
    // which is what keeps different branches' node boxes, and the
    // connector curves fanning off them, from ever overlapping.
    //
    // Below-the-root half: unchanged from the original single-direction
    // layout, just scoped to belowLaidOut instead of every branch.
    let spineCursor = (root._h || ROOT_H) / 2 + TIMELINE_ROOT_GAP + (belowLaidOut.length ? belowLaidOut[0].localHeight / 2 : 0);
    belowLaidOut.forEach(({ branch, localHeight }, i) => {
      if (i > 0) {
        spineCursor += belowLaidOut[i - 1].localHeight / 2 + TIMELINE_ROW_GAP + localHeight / 2;
      }
      const offset = spineCursor;
      (function shift(n) {
        n._y += offset;
        if (!n.collapsed) (n.children || []).forEach(shift);
      })(branch);
    });

    // Above-the-root half: the exact mirror image, growing upward
    // (negative y) instead of downward. Walked back-to-front so that the
    // branch LAST in the array sits closest to the root (directly above
    // it) and the branch FIRST in the array ends up furthest away — i.e.
    // reading the above group top-to-bottom on screen matches its order
    // in the array, just like the below group does.
    let spineCursorUp = -((root._h || ROOT_H) / 2 + TIMELINE_ROOT_GAP + (aboveLaidOut.length ? aboveLaidOut[aboveLaidOut.length - 1].localHeight / 2 : 0));
    for (let i = aboveLaidOut.length - 1; i >= 0; i--) {
      const { branch, localHeight } = aboveLaidOut[i];
      if (i < aboveLaidOut.length - 1) {
        spineCursorUp -= aboveLaidOut[i + 1].localHeight / 2 + TIMELINE_ROW_GAP + localHeight / 2;
      }
      const offset = spineCursorUp;
      (function shift(n) {
        n._y += offset;
        if (!n.collapsed) (n.children || []).forEach(shift);
      })(branch);
    }

    return computeBBox(root);
  }

  /* ---------------- text measuring / wrapping ---------------- */

  const measureCanvas = document.createElement("canvas");
  const measureCtx = measureCanvas.getContext("2d");

  function measureW(text) { return measureCtx.measureText(text).width; }

  function breakLongWord(word, maxW) {
    const parts = [];
    let cur = "";
    for (const ch of word) {
      const t = cur + ch;
      if (cur && measureW(t) > maxW) { parts.push(cur); cur = ch; }
      else cur = t;
    }
    if (cur) parts.push(cur);
    return parts;
  }

  function wrapParagraph(para, maxW) {
    if (!para) return [""];
    const words = para.split(/\s+/).filter(Boolean);
    if (words.length === 0) return [""];
    const lines = [];
    let cur = "";
    for (const word of words) {
      if (measureW(word) > maxW) {
        if (cur) { lines.push(cur); cur = ""; }
        const chunks = breakLongWord(word, maxW);
        for (let i = 0; i < chunks.length - 1; i++) lines.push(chunks[i]);
        cur = chunks[chunks.length - 1] || "";
        continue;
      }
      const test = cur ? cur + " " + word : word;
      if (measureW(test) <= maxW) {
        cur = test;
      } else {
        if (cur) lines.push(cur);
        cur = word;
      }
    }
    if (cur) lines.push(cur);
    return lines.length ? lines : [""];
  }

  function wrapText(text, maxW) {
    const paras = (text || "").split(/\n/);
    let lines = [];
    for (const p of paras) lines = lines.concat(wrapParagraph(p, maxW));
    return lines.length ? lines : [""];
  }

  // Computes and caches this node's rendered box size (node._w / node._h)
  // based on its current text, so long text wraps and grows the node
  // instead of being clipped or overflowing it.

  // Estimates the pixel size of a table node's grid (see nodeIsTable) by
  // wrapping each cell's text the same way computeNodeBox wraps a normal
  // node's label, then taking the widest cell in each column / tallest
  // cell in each row — the same shape of estimate as the text path below,
  // just per-cell instead of per-node. The per-column/row pixel widths it
  // returns are stashed on the node (see computeNodeBox) so renderNode can
  // build a real <table> whose <col>/<tr> sizes match this estimate
  // exactly, instead of the two drifting apart.
  const TABLE_CELL_PAD_X = 16;
  const TABLE_CELL_PAD_Y = 10;
  const TABLE_CELL_MIN_W = 44;
  const TABLE_CELL_MAX_W = 140;
  const TABLE_CELL_LINE_H = 16;
  const TABLE_CELL_MIN_H = 26;
  // Fixed strip reserved under every cell's text for its photo/note/link/
  // task icons + the "+" add button (see buildCellIconStrip) — always
  // reserved, even on an empty cell, so a cell's height doesn't jump
  // around as attachments are added/removed.
  const TABLE_CELL_ICON_STRIP_H = 18;
  function computeTableBox(node) {
    measureCtx.font = `400 12.5px -apple-system, BlinkMacSystemFont, "Segoe UI", "Inter", Helvetica, Arial, sans-serif`;
    const cells = node.table.cells;
    const rows = cells.length;
    const cols = Math.max(1, ...cells.map(r => r.length));
    const colWidths = new Array(cols).fill(TABLE_CELL_MIN_W);
    const rowHeights = new Array(rows).fill(TABLE_CELL_MIN_H + TABLE_CELL_ICON_STRIP_H);
    const maxTextW = TABLE_CELL_MAX_W - TABLE_CELL_PAD_X;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const cellText = (cells[r] && cells[r][c]) || "";
        const lines = wrapText(cellText, maxTextW);
        const widest = Math.max(0, ...lines.map(l => measureW(l)));
        const w = clamp(Math.ceil(widest) + TABLE_CELL_PAD_X, TABLE_CELL_MIN_W, TABLE_CELL_MAX_W);
        const h = Math.max(TABLE_CELL_MIN_H, lines.length * TABLE_CELL_LINE_H + TABLE_CELL_PAD_Y) + TABLE_CELL_ICON_STRIP_H;
        colWidths[c] = Math.max(colWidths[c], w);
        rowHeights[r] = Math.max(rowHeights[r], h);
      }
    }
    const BORDER = 1;
    const tableW = colWidths.reduce((a, b) => a + b, 0) + (cols + 1) * BORDER;
    const tableH = rowHeights.reduce((a, b) => a + b, 0) + (rows + 1) * BORDER;
    return { tableW, tableH, colWidths, rowHeights };
  }

  function computeNodeBox(node) {
    const depth = node._depth || 0;
    const padX = depth === 0 ? 56 : 32;
    const vPad = depth === 0 ? 28 : 16;
    const baseH = depth === 0 ? ROOT_H : NODE_H;
    const minW = depth === 0 ? 130 : 56;

    let w, h, lines;
    if (nodeIsTable(node)) {
      const tbox = computeTableBox(node);
      node._tableColWidths = tbox.colWidths;
      node._tableRowHeights = tbox.rowHeights;
      // +6 mirrors the SAFETY buffer the text path below uses — a small
      // cushion so the outer box's own 2px border always fully encloses
      // the <table> built to these exact column/row pixel widths, instead
      // of clipping it by a couple of stray pixels.
      w = Math.max(tbox.tableW + padX + 6, minW);
      h = Math.max(tbox.tableH + vPad + 6, baseH);
      lines = [];
    } else {
    const fontWeight = depth === 0 ? 800 : depth === 1 ? 600 : depth === 2 ? 500 : 400;
    const fontSize = depth === 0 ? 21 : depth === 3 ? 12.5 : 13.5;
    measureCtx.font = `${fontWeight} ${fontSize}px -apple-system, BlinkMacSystemFont, "Segoe UI", "Inter", Helvetica, Arial, sans-serif`;
    const text = node.text || "(untitled)";
    // Small safety buffer so a slight mismatch between canvas-measured width
    // and actual rendered width never causes the CSS wrap to break a word
    // mid-letter (e.g. "Risk" -> "Ris"/"k").
    const SAFETY = 6;
    const maxBoxW = depth === 0 ? 340 : 230;
    const maxTextW = maxBoxW - padX;

    const oneLineW = Math.ceil(measureW(text)) + padX + SAFETY;
    if (oneLineW <= maxBoxW && !/\n/.test(text)) {
      w = clamp(oneLineW, minW, maxBoxW);
      lines = [text];
    } else {
      lines = wrapText(text, maxTextW);
      const widest = Math.max(...lines.map(l => measureW(l)));
      w = clamp(Math.ceil(widest) + padX + SAFETY, minW, maxBoxW);
    }

    const lineHeight = depth === 0 ? 24 : depth === 3 ? 16 : 17;
    h = Math.max(baseH, Math.ceil(lines.length * lineHeight + vPad));
    }

    // Reserve room inside the box for the combined note/link/photo strip,
    // which renders in normal flow below the text (see renderNode) instead
    // of floating outside the frame or overlapping the label. Matches the
    // sizing renderNode/CSS actually use so the box always fully encloses it.
    const nodeImages = getNodeImages(node);
    // The time-played total (see renderNode/openTimerModal) is now a
    // same-size trailing cell of this same strip rather than a wider
    // pill, so it counts toward itemCount just like a note/link icon.
    // Notes and links each collapse to a single stand-in cell past
    // STRIP_OVERFLOW_CAP too (see stripBucketCount/renderNode), so the
    // box reserves exactly as much room as actually gets drawn either way.
    const stripIconCountForBox = stripBucketCount(getNodeNotes(node).length) + stripBucketCount(getNodeUrls(node).length) + (nodeAffirmationWins(node) ? 1 : 0) + (getNodeTimePlayed(node) ? 1 : 0) + (brainstormPoints(node) > 0 ? 1 : 0);
    let stripW = 0, stripH = 0;
    if (stripIconCountForBox || nodeImages.length) {
      // Past STRIP_OVERFLOW_CAP photos, collapse down to a single cover
      // thumbnail with a count badge (see renderNode) instead of a wall
      // of thumbnails, so a node with dozens of photos still reads as
      // one compact cell.
      const overflow = nodeImages.length > STRIP_OVERFLOW_CAP;
      const shownCount = overflow ? 1 : nodeImages.length;
      const itemCount = stripIconCountForBox + shownCount;
      const large = itemCount <= 10;
      const thumb = large ? 18 : 13.5;
      const gap = 3;
      const cols = Math.min(itemCount, 5);
      const rows = Math.ceil(itemCount / 5);
      stripW = cols * thumb + (cols - 1) * gap;
      stripH = 5 /* margin-top */ + rows * thumb + (rows - 1) * gap;
    }

    // Reserve room for the task-progress bar + percentage label, which
    // render in normal flow below the text/photos (see renderNode) so the
    // box always fully encloses them instead of floating over the label.
    // A minimum width is enforced too, so the bar+label row always has
    // enough room to sit comfortably even on a short one-word node.
    const taskProgForBox = nodeTaskProgress(node);
    let barH = 0, barMinW = 0;
    if (taskProgForBox.total) {
      barH = 6 /* margin-top */ + 8 /* bar height */;
      barMinW = 56 /* track */ + 6 /* gap */ + 30 /* "100%" label */ + padX;
    }

    // Reserve room for the root node's live clock block (current time,
    // UTC/US/UK world clocks, weekday+date, lunar date — see
    // renderNode). Fixed dimensions since, unlike the text above, its
    // content never depends on anything the person typed.
    const ROOT_CLOCK_W = 300;
    const ROOT_CLOCK_H = 116;
    const clockW = depth === 0 && !isClockHidden() ? ROOT_CLOCK_W + padX : 0;
    const clockH = depth === 0 && !isClockHidden() ? ROOT_CLOCK_H : 0;

    node._w = Math.max(w, stripW + padX, barMinW, clockW);
    node._h = h + stripH + barH + clockH;
    node._lines = lines;
    return { w: node._w, h: node._h };
  }

  // A node's box is anchored on its `_x` layout position rather than
  // centered on it: nodes fanning right keep their LEFT edge fixed at
  // `_x` and grow rightward as their text does, nodes fanning left keep
  // their RIGHT edge fixed and grow leftward, and the root (which has no
  // single direction) stays centered as before. This is what makes every
  // sibling at a given depth/side line up on the same vertical edge no
  // matter how long each one's own text is, since `_x` (before any manual
  // drag offset) is identical across siblings by default.
  function nodeLeftX(node) {
    const base = node._x + (node.ox || 0);
    // Depth 0 (the root) and any node whose automatic `_x` is exactly 0
    // — e.g. a Timeline branch's own root, which sits centered on the
    // vertical spine rather than fanning left/right — stay centered like
    // before. Everything actually fanning out gets the anchored treatment.
    if (node._depth === 0 || node._x === 0) return base - node._w / 2;
    return node._x >= 0 ? base : base - node._w;
  }
  function nodeRightX(node) { return nodeLeftX(node) + node._w; }
  function nodeCenterX(node) { return nodeLeftX(node) + node._w / 2; }

  /* ---------------- branch color resolution ---------------- */

  function branchColorFor(root, node) {
    // find the top-level ancestor (depth 1) that node descends from
    if (node === root) return null;
    let color = null;
    (function find(n, top) {
      for (const c of n.children || []) {
        const t = top || c;
        if (c === node) { color = t.color; return; }
        find(c, t);
      }
    })(root, null);
    return color;
  }

  function assignBranchColors(root) {
    const children = root.children || [];
    // Colors are cached on each branch (c.color) so they stay stable across
    // re-renders/reorders. That caching is exactly why a naive `i %
    // PALETTE.length` goes wrong: once a branch is deleted or the list is
    // reordered, a *new* branch can land on the same index another branch
    // used earlier — and that other branch's cached color never moved, so
    // you'd get a repeat before all 10 palette colors were even used.
    // Instead, only fill in colors for branches that don't have one yet,
    // and actively skip whatever colors are already in use by siblings —
    // so every branch gets a distinct color until the palette itself runs
    // out (only then does it start repeating).
    const used = new Set(children.filter(c => c.color).map(c => c.color));
    let cursor = 0;
    children.forEach((c) => {
      if (c.color) return;
      let color = null;
      for (let k = 0; k < PALETTE.length; k++) {
        const candidate = PALETTE[(cursor + k) % PALETTE.length];
        if (!used.has(candidate)) { color = candidate; cursor = (cursor + k + 1) % PALETTE.length; break; }
      }
      if (!color) color = PALETTE[cursor % PALETTE.length]; // palette exhausted; a repeat is unavoidable
      c.color = color;
      used.add(color);
    });
  }

  /* ---------------- rendering ---------------- */

  function renderAll() {
    if (!state.current) { clearCanvas(); return; }
    updateUndoRedoButtons();
    emptyState.classList.add("hidden");
    nodeFabs.classList.remove("hidden");
    applyTheme();
    assignBranchColors(state.current.root);
    const bbox = layout(state.current.root);
    const pad = 140;
    const width = (bbox.maxX - bbox.minX) + pad * 2;
    const height = (bbox.maxY - bbox.minY) + pad * 2;
    const originX = -bbox.minX + pad;
    const originY = -bbox.minY + pad;
    // The world's coordinate origin shifts whenever the tree's bounding box
    // changes (e.g. collapsing/expanding a branch shrinks or grows it), even
    // though the camera (tx/ty) itself didn't change. Left alone, that
    // origin shift reads as the whole map sliding on screen. Counteract it
    // by nudging tx/ty the opposite way, so whatever was on screen stays on
    // screen.
    if (state.originX !== undefined && state.originY !== undefined) {
      state.tx -= (originX - state.originX) * state.scale;
      state.ty -= (originY - state.originY) * state.scale;
    }
    state.originX = originX;
    state.originY = originY;

    worldEl.style.width = width + "px";
    worldEl.style.height = height + "px";
    svgEl.setAttribute("width", width);
    svgEl.setAttribute("height", height);
    svgEl.setAttribute("viewBox", `0 0 ${width} ${height}`);

    nodesLayer.innerHTML = "";
    svgEl.innerHTML = svgDefs();

    const nodes = [];
    (function collect(n) { nodes.push(n); if (!n.collapsed) (n.children || []).forEach(collect); })(state.current.root);

    // lines first (under nodes)
    const layoutMode = state.current.layout || "mindmap";
    const branches = state.current.root.children || [];
    for (const n of nodes) {
      if (n.collapsed || !n.children || n.children.length === 0) continue;
      for (const c of n.children) {
        // In Timeline mode the root only visually connects to the first
        // branch; the rest chain branch-to-branch down the spine (drawn below).
        if (layoutMode === "timeline" && n === state.current.root) continue;
        drawConnector(n, c, originX, originY);
      }
    }
    if (layoutMode === "timeline" && branches.length) {
      // The root chains to each half of the spine separately — branches
      // below it (the default) chain downward as before, and any branch
      // dragged above the root (vSide === "above") chains upward instead.
      const belowBranches = branches.filter(b => b.vSide !== "above");
      const aboveBranches = branches.filter(b => b.vSide === "above");
      if (belowBranches.length) {
        drawConnector(state.current.root, belowBranches[0], originX, originY, { orientation: "v" });
        for (let i = 0; i < belowBranches.length - 1; i++) {
          drawConnector(belowBranches[i], belowBranches[i + 1], originX, originY, { orientation: "v", colorNode: belowBranches[i + 1], depth: 1 });
        }
      }
      if (aboveBranches.length) {
        // aboveBranches is in array order, but on screen the LAST one sits
        // closest to the root (see layoutTimeline) — so the chain runs
        // root -> last -> ... -> first, the mirror of the downward chain.
        const last = aboveBranches.length - 1;
        drawConnector(state.current.root, aboveBranches[last], originX, originY, { orientation: "v" });
        for (let i = last; i > 0; i--) {
          drawConnector(aboveBranches[i], aboveBranches[i - 1], originX, originY, { orientation: "v", colorNode: aboveBranches[i - 1], depth: 1 });
        }
      }
    }

    if (state.current.links && state.current.links.length) {
      const byId = new Map(nodes.map(n => [n.id, n]));
      for (const link of state.current.links) {
        const a = byId.get(link.a), b = byId.get(link.b);
        if (a && b) drawLink(a, b, originX, originY, link);
      }
    }

    for (const n of nodes) {
      renderNode(n, originX, originY);
    }

    if (state.linkFromId) {
      const from = nodes.find(n => n.id === state.linkFromId);
      if (from) {
        const div = nodesLayer.querySelector(`.node[data-id="${from.id}"]`);
        if (div) div.classList.add("link-source");
      } else {
        state.linkFromId = null;
      }
    }

    if (state.moveSourceId) {
      const from = nodes.find(n => n.id === state.moveSourceId);
      if (from) {
        const div = nodesLayer.querySelector(`.node[data-id="${from.id}"]`);
        if (div) div.classList.add("move-source");
      } else {
        state.moveSourceId = null;
      }
    }

    titleInput.value = state.current.title || "";
    updateLinkHint();
    applyHighlight();
    applyTransform();
  }

  // Blurs every node/connector except a chosen node and its whole branch
  // (descendants), so that part of the map stands out against everything
  // else. Re-applied at the end of every renderAll() since that rebuilds
  // nodesLayer/svgEl from scratch and would otherwise drop the classes.
  function applyHighlight() {
    nodesLayer.querySelectorAll(".node").forEach(div => div.classList.remove("highlight-dim", "highlight-focus"));
    svgEl.querySelectorAll(".connector").forEach(g => g.classList.remove("highlight-dim", "highlight-focus"));
    const activeId = state.highlightId;
    if (!activeId) return;
    const node = findNode(activeId);
    if (!node) { state.highlightId = null; return; }
    const ids = new Set();
    (function collect(n) { ids.add(n.id); (n.children || []).forEach(collect); })(node);
    nodesLayer.querySelectorAll(".node").forEach(div => {
      div.classList.add(ids.has(div.dataset.id) ? "highlight-focus" : "highlight-dim");
    });
    svgEl.querySelectorAll(".connector").forEach(g => {
      const inBranch = ids.has(g.dataset.parent) && ids.has(g.dataset.child);
      g.classList.add(inBranch ? "highlight-focus" : "highlight-dim");
    });
  }

  function setHighlight(nodeId) {
    state.highlightId = (state.highlightId === nodeId) ? null : nodeId;
    applyHighlight();
  }
  function clearHighlight() {
    if (!state.highlightId) return;
    state.highlightId = null;
    applyHighlight();
  }

  // Cross-links connect two arbitrary nodes rather than a parent to its
  // child, so there's no fixed "side" to route from/to — instead we aim
  // each end at the edge of its node along the straight line between their
  // centers, then bow the middle out a bit so it reads as distinct from
  // the tree connectors underneath it.
  function linkPath(a, b, ox, oy) {
    const ax = ox + nodeCenterX(a), ay = oy + a._y + (a.oy || 0);
    const bx = ox + nodeCenterX(b), by = oy + b._y + (b.oy || 0);
    const dx = bx - ax, dy = by - ay;
    const dist = Math.hypot(dx, dy) || 1;
    const ux = dx / dist, uy = dy / dist;
    const edgeOffset = (n) => Math.abs(ux) > Math.abs(uy) ? (n._w / 2) : (n._h / 2);
    const x1 = ax + ux * edgeOffset(a), y1 = ay + uy * edgeOffset(a);
    const x2 = bx - ux * edgeOffset(b), y2 = by - uy * edgeOffset(b);
    const mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
    const bow = Math.min(36, dist * 0.18);
    const cx = mx + -uy * bow, cy = my + ux * bow;
    return `M ${x1} ${y1} Q ${cx} ${cy}, ${x2} ${y2}`;
  }

  function drawLink(a, b, ox, oy, link) {
    const path = linkPath(a, b, ox, oy);
    const bg = (state.current.theme && state.current.theme.background) || defaultBg();
    const color = "#e0b04a";

    const g = document.createElementNS("http://www.w3.org/2000/svg", "g");
    g.setAttribute("class", "connector link-connector");
    g.dataset.link = link.id;

    const halo = document.createElementNS("http://www.w3.org/2000/svg", "path");
    halo.setAttribute("d", path);
    halo.setAttribute("stroke", haloColorFor(bg));
    halo.setAttribute("stroke-width", "4.6");
    halo.setAttribute("fill", "none");
    halo.setAttribute("stroke-linecap", "round");
    g.appendChild(halo);

    const el = document.createElementNS("http://www.w3.org/2000/svg", "path");
    el.setAttribute("d", path);
    el.setAttribute("stroke", color);
    el.setAttribute("stroke-width", "2");
    el.setAttribute("stroke-dasharray", "1, 7");
    el.setAttribute("stroke-linecap", "round");
    el.setAttribute("fill", "none");
    el.setAttribute("opacity", "0.9");
    g.appendChild(el);

    g.addEventListener("contextmenu", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openLinkContextMenu(e.clientX, e.clientY, link);
    });

    svgEl.appendChild(g);
  }

  function svgDefs() {
    return `<defs>
      <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
        <feGaussianBlur stdDeviation="2.2" result="blur"/>
        <feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge>
      </filter>
      <marker id="connector-arrow" viewBox="0 0 10 10" refX="8" refY="5"
              markerWidth="6.5" markerHeight="6.5" orient="auto-start-reverse">
        <path d="M 0 0 L 10 5 L 0 10 z" fill="context-stroke"/>
      </marker>
    </defs>`;
  }

  // Rounded right-angle ("elbow") connector: a horizontal run out of the
  // parent, a rounded corner, a vertical run, another rounded corner, then
  // a horizontal run into the child — the classic org-chart look. Falls
  // back to a plain straight segment if there isn't room for the bend.
  function roundedElbowPath(x1, y1, x2, y2, r) {
    const dx = x2 - x1, dy = y2 - y1;
    if (Math.abs(dx) < 1 || Math.abs(dy) < 1) {
      return `M ${x1} ${y1} L ${x2} ${y2}`;
    }
    const mx = x1 + dx / 2;
    const rr = Math.min(r, Math.abs(dx) / 2, Math.abs(dy) / 2);
    const sx = dx >= 0 ? 1 : -1;
    const sy = dy >= 0 ? 1 : -1;
    return `M ${x1} ${y1} L ${mx - sx * rr} ${y1} Q ${mx} ${y1} ${mx} ${y1 + sy * rr} L ${mx} ${y2 - sy * rr} Q ${mx} ${y2} ${mx + sx * rr} ${y2} L ${x2} ${y2}`;
  }

  // Same "elbow" idea, but for vertically-stacked hops (Timeline layout's
  // spine) — the bend happens on a horizontal run at the vertical midpoint
  // instead of a vertical run at the horizontal midpoint.
  function roundedElbowPathVertical(x1, y1, x2, y2, r) {
    const dx = x2 - x1, dy = y2 - y1;
    if (Math.abs(dx) < 1 || Math.abs(dy) < 1) {
      return `M ${x1} ${y1} L ${x2} ${y2}`;
    }
    const my = y1 + dy / 2;
    const rr = Math.min(r, Math.abs(dx) / 2, Math.abs(dy) / 2);
    const sx = dx >= 0 ? 1 : -1;
    const sy = dy >= 0 ? 1 : -1;
    return `M ${x1} ${y1} L ${x1} ${my - sy * rr} Q ${x1} ${my} ${x1 + sx * rr} ${my} L ${x2 - sx * rr} ${my} Q ${x2} ${my} ${x2} ${my + sy * rr} L ${x2} ${y2}`;
  }

  function connectorPath(parent, child, ox, oy) {
    const px = parent._x + (parent.ox || 0), py = parent._y + (parent.oy || 0);
    const cx = child._x + (child.ox || 0), cy = child._y + (child.oy || 0);
    const sign = cx >= px ? 1 : -1;
    // Route from whichever edge of the parent box faces the child to
    // whichever edge of the child box faces the parent — with the new
    // anchored (non-centered) boxes, the child's parent-facing edge sits
    // at its fixed `_x` position, so it lines up with every sibling at
    // the same depth regardless of how wide any of their text boxes are.
    const x1 = ox + (sign > 0 ? nodeRightX(parent) : nodeLeftX(parent));
    const y1 = oy + py;
    const x2 = ox + (sign > 0 ? nodeLeftX(child) : nodeRightX(child));
    const y2 = oy + cy;
    // Connector shape — "elbow" draws a rounded right-angle org-chart-style
    // path; anything else (including "curved" and legacy/unknown values)
    // falls back to the default S-curve below. A hop's own connectorShape
    // wins if set (from the combined "Connector style" picker); otherwise
    // it falls back to the map-wide default from the root node's menu.
    const shape = child.connectorShape || (state.current.theme && state.current.theme.connectorShape) || "curved";
    if (shape === "elbow") {
      return roundedElbowPath(x1, y1, x2, y2, 14);
    }
    const dx = (x2 - x1) * 0.55;
    return `M ${x1} ${y1} C ${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`;
  }

  // Same idea as connectorPath, but for nodes stacked vertically (the
  // root-to-first-branch and branch-to-branch spine links in the Timeline
  // layout) rather than side by side. The x coordinate deliberately
  // ignores each node's manual horizontal nudge (ox) — the spine is meant
  // to read as one continuous straight line down the middle of the map
  // regardless of how far any individual branch has been dragged
  // sideways, so only the node's automatic layout position (_x, which is
  // always 0 for the root/branches in Timeline mode) feeds the x here.
  function connectorPathVertical(parent, child, ox, oy) {
    const ph = parent._h, ch = child._h;
    const py = parent._y + (parent.oy || 0);
    const cy = child._y + (child.oy || 0);
    const sign = cy >= py ? 1 : -1;
    const y1 = oy + py + sign * (ph / 2);
    const x1 = ox + parent._x;
    const y2 = oy + cy - sign * (ch / 2);
    const x2 = ox + child._x;
    const shape = child.connectorShape || (state.current.theme && state.current.theme.connectorShape) || "curved";
    if (shape === "elbow") {
      return roundedElbowPathVertical(x1, y1, x2, y2, 14);
    }
    const dy = (y2 - y1) * 0.55;
    return `M ${x1} ${y1} C ${x1} ${y1 + dy}, ${x2} ${y2 - dy}, ${x2} ${y2}`;
  }

  function drawConnector(parent, child, ox, oy, opts) {
    opts = opts || {};
    const orientation = opts.orientation || "h";
    const path = orientation === "v"
      ? connectorPathVertical(parent, child, ox, oy)
      : connectorPath(parent, child, ox, oy);
    const theme = state.current.theme;
    const colorNode = opts.colorNode || child;
    const color = theme.connectorMode === "custom"
      ? theme.connectorColor
      : (colorNode.color || branchColorFor(state.current.root, colorNode) || "#5b6272");
    const depth = opts.depth != null ? opts.depth : child._depth;
    // Thickness steps down by level so the trunk clearly reads as more
    // important than a leaf twig — matches the box-styling tiers (pill,
    // solid box, outlined box, plain text). Level 3+ is dotted, so it gets
    // a noticeably thinner stroke than a solid line of the same "weight"
    // would need, since dots read as thin even at low width.
    const width = depth <= 1 ? 3 : depth === 2 ? 1.8 : 1.1;
    const bg = theme.background || defaultBg();

    const g = document.createElementNS("http://www.w3.org/2000/svg", "g");
    g.setAttribute("class", "connector");
    g.dataset.parent = parent.id;
    g.dataset.child = child.id;
    g.dataset.orientation = orientation;

    // halo underneath, so the line always reads clearly against whatever
    // background color is chosen
    const halo = document.createElementNS("http://www.w3.org/2000/svg", "path");
    halo.setAttribute("d", path);
    halo.setAttribute("stroke", haloColorFor(bg));
    // Dotted level's halo gets a smaller bump than solid lines, so the halo
    // dots don't balloon past the thin dots they're meant to frame.
    halo.setAttribute("stroke-width", depth >= 3 ? width + 0.9 : width + 1.8);
    halo.setAttribute("fill", "none");
    halo.setAttribute("stroke-linecap", "round");
    // Keep the halo dotted in lockstep with the main line at level 3+, so it
    // doesn't show through the gaps as a solid line underneath the dots.
    if (depth >= 3) halo.setAttribute("stroke-dasharray", `0.1, ${width * 2.6}`);
    g.appendChild(halo);

    const el = document.createElementNS("http://www.w3.org/2000/svg", "path");
    el.setAttribute("d", path);
    el.setAttribute("stroke", color);
    el.setAttribute("stroke-width", width);
    el.setAttribute("fill", "none");
    el.setAttribute("stroke-linecap", "round");
    el.setAttribute("opacity", depth <= 1 ? "0.95" : "1");
    if (depth === 1) el.setAttribute("filter", "url(#glow)");
    // From level 3 down, switch to a dotted line — reinforces that these
    // are the least important tier, on top of the thinner stroke.
    if (depth >= 3) el.setAttribute("stroke-dasharray", `0.1, ${width * 2.6}`);
    // "Arrow" connector style — set per-hop via the combined "Connector
    // style" picker (see openConnectorContextMenu), or inherited from the
    // map-wide default (root node's menu) when this hop has no override —
    // adds an arrowhead pointing from parent to child, colored to match
    // the line via context-stroke. An explicit "line" override always
    // wins over the map-wide default.
    const wantsArrow = child.connectorStyle === "arrow"
      || (!child.connectorStyle && !!(theme && theme.connectorArrow));
    if (orientation !== "v" && wantsArrow) {
      el.setAttribute("marker-end", "url(#connector-arrow)");
    }
    g.appendChild(el);

    // A real parent→child hop (as opposed to the "v" spine connectors
    // chaining sibling branches together in Timeline mode) has an actual
    // distance the user can customize — right-click it to open a small
    // input for that. A wide invisible stroke sits on top so thin (or
    // dotted, level-3+) lines are still easy to hover and right-click.
    if (orientation !== "v") {
      const hit = document.createElementNS("http://www.w3.org/2000/svg", "path");
      hit.setAttribute("d", path);
      hit.setAttribute("class", "connector-hit");
      hit.setAttribute("stroke", "#000");
      hit.setAttribute("stroke-width", Math.max(14, width + 12));
      hit.setAttribute("fill", "none");
      hit.setAttribute("opacity", "0");
      g.appendChild(hit);

      g.addEventListener("contextmenu", (e) => {
        e.preventDefault();
        e.stopPropagation();
        openConnectorContextMenu(e.clientX, e.clientY, parent, child);
      });
    }

    svgEl.appendChild(g);
  }

  // Fast-path update used while dragging or typing: recompute just the
  // connector path(s) touching one node, without a full re-render.
  function updateConnectorDom(parent, child, ox, oy) {
    const g = svgEl.querySelector(`g.connector[data-parent="${parent.id}"][data-child="${child.id}"]`);
    if (!g) return;
    const orientation = g.dataset.orientation || "h";
    const path = orientation === "v"
      ? connectorPathVertical(parent, child, ox, oy)
      : connectorPath(parent, child, ox, oy);
    g.querySelectorAll("path").forEach(p => p.setAttribute("d", path));
  }

  // Refreshes every connector touching a node, whether it's that node's tree
  // parent/children or (in Timeline mode) a spine link to a sibling branch.
  function refreshConnectorsFor(node) {
    const touching = svgEl.querySelectorAll(`g.connector[data-parent="${node.id}"], g.connector[data-child="${node.id}"]`);
    touching.forEach(g => {
      const p = findNode(g.dataset.parent), c = findNode(g.dataset.child);
      if (p && c) updateConnectorDom(p, c, state.originX, state.originY);
    });
  }

  // Fast-path used while dragging: move a node's div and the connectors
  // touching it, without re-running the full layout.
  function updateNodePositionDom(node) {
    const div = nodesLayer.querySelector(`.node[data-id="${node.id}"]`);
    if (div) {
      const w = node._w || NODE_H, h = node._h || NODE_H;
      div.style.left = (state.originX + nodeLeftX(node)) + "px";
      div.style.top = (state.originY + node._y + (node.oy || 0) - h / 2) + "px";
    }
    refreshConnectorsFor(node);
  }

  // Fast-path used while dragging: move one cross-link's path without a
  // full re-render (mirrors updateNodePositionDom for tree connectors).
  function updateLinkDom(link, a, b) {
    const g = svgEl.querySelector(`g.connector[data-link="${link.id}"]`);
    if (!g) return;
    const path = linkPath(a, b, state.originX, state.originY);
    g.querySelectorAll("path").forEach(p => p.setAttribute("d", path));
  }

  // Re-runs layout (which may reorder siblings, flip a side, or resize the
  // canvas) but — unlike renderAll() — never touches nodesLayer.innerHTML or
  // svgEl.innerHTML, so every existing node div and connector line is just
  // moved to its new spot instead of being torn down and recreated. That
  // full rebuild is what caused the visible blink when a drag crossed the
  // center line or reordered siblings. Only safe to call when the set of
  // nodes/connectors on screen hasn't changed shape (nothing added or
  // removed, no collapse toggled) — exactly the case while a drag is live.
  //
  // freezeOrigin (used while a drag is in progress) keeps state.originX/
  // originY and the world/svg canvas size exactly as they were, instead of
  // recomputing them from the fresh bounding box. Every node's on-screen
  // position is originX/originY plus its own local coordinate, so without
  // this, a side-flip or reorder that shifts the bounding box (e.g. a
  // branch now reaching further left) shifts that shared origin — which
  // visibly nudges EVERY node, including ones that didn't logically move
  // at all, like the dragged node's parent or the root. Freezing origin
  // during the drag keeps those untouched nodes visually still; the
  // canvas is resized/recentered properly in one shot once the drag ends.
  function repositionAll(freezeOrigin) {
    if (!state.current) return;
    const bbox = layout(state.current.root);

    if (!freezeOrigin) {
      const pad = 140;
      const width = (bbox.maxX - bbox.minX) + pad * 2;
      const height = (bbox.maxY - bbox.minY) + pad * 2;
      state.originX = -bbox.minX + pad;
      state.originY = -bbox.minY + pad;

      worldEl.style.width = width + "px";
      worldEl.style.height = height + "px";
      svgEl.setAttribute("width", width);
      svgEl.setAttribute("height", height);
      svgEl.setAttribute("viewBox", `0 0 ${width} ${height}`);
    }

    const nodes = [];
    (function collect(n) { nodes.push(n); if (!n.collapsed) (n.children || []).forEach(collect); })(state.current.root);
    for (const n of nodes) updateNodePositionDom(n);

    if (state.current.links && state.current.links.length) {
      for (const link of state.current.links) {
        const a = findNode(link.a), b = findNode(link.b);
        if (a && b) updateLinkDom(link, a, b);
      }
    }
  }

  let dragCandidate = null;
  let suppressNextNodeClick = false;

  // On touch, a finger landing on a node and immediately moving is far more
  // often the start of a canvas pan/scroll than an attempt to drag that
  // node — so a node drag only actually arms after the finger has held
  // still on the node for TOUCH_DRAG_HOLD_MS. Until then, the touch is
  // "pending": if it moves more than TOUCH_DRAG_CANCEL_DIST before the
  // hold completes, it's treated as a pan starting from the node instead
  // (see the pointermove listener below); if it lifts before the hold
  // completes, it's just a tap (the existing click listener already
  // handles that). Mouse/pen drags are unaffected and still start
  // immediately on mousedown/pointerdown, since there's no scrolling
  // gesture to disambiguate from there.
  const TOUCH_DRAG_HOLD_MS = 350;
  const TOUCH_DRAG_CANCEL_DIST = 10;
  let touchDragArm = null;
  function clearTouchDragArm() {
    if (touchDragArm) { clearTimeout(touchDragArm.timer); touchDragArm = null; }
  }

  // Tracks every touch currently down anywhere in the viewport (canvas
  // background or on a node), keyed by pointerId, so a second finger
  // landing mid-gesture can be recognized as the start of a pinch-zoom
  // regardless of what the first finger touched. Mouse/pen pointers are
  // never added here — only "touch" ones (see viewportEl's pointerdown
  // listener below), since pinch is a touch-only gesture.
  const activePointers = new Map();

  // Dragging a node's task ring / progress bar / photo strip onto a
  // *different* node moves (or, with Alt/Option held, copies) that data
  // over — an easy way to reassign a checklist or a batch of photos
  // without opening menus. Uses native HTML5 drag-and-drop rather than
  // the mouse-based dragCandidate mechanism above (which is reserved for
  // repositioning/reparenting whole nodes), so the two never collide.
  let markerDragState = null;

  function startMarkerDrag(e, node, type, extra) {
    e.stopPropagation();
    if (!requireSignIn()) { e.preventDefault(); return; }
    markerDragState = Object.assign({ type, sourceNodeId: node.id }, extra);
    e.dataTransfer.effectAllowed = "copyMove";
    // Firefox requires data to actually be set for the drag to proceed.
    try { e.dataTransfer.setData("text/plain", ""); } catch (err) {}
    e.currentTarget.classList.add("marker-dragging");
  }

  function endMarkerDrag(e) {
    e.currentTarget.classList.remove("marker-dragging");
    markerDragState = null;
    nodesLayer.querySelectorAll(".node.marker-drop-target, .node-table-cell.marker-drop-target").forEach(d => d.classList.remove("marker-drop-target"));
  }

  // Applies a completed marker drop: merges the dragged data onto the
  // target (a whole node, or — when targetR/targetC are given — one
  // specific table cell of that node), then (unless the user held Alt/
  // Option to copy) clears it from the source so it reads as a move
  // rather than a duplication. The source is likewise either a whole
  // node or one of its cells, per markerDragState.sourceR/sourceC (set
  // by startMarkerDrag — see the cell icon strip and the node-level
  // strip below). Node and cell attach records share the same field
  // shapes (images/notes/urls/tasks/linkTitles — see getCellAttach and
  // the getNode*/getCell* pairs above), so every branch below reads and
  // writes `source`/`target` without caring which kind either one is —
  // that's what makes node→cell, cell→node, and cell→cell drags all
  // fall out of the same code as the original node→node case.
  function completeMarkerDrop(targetId, copy, targetR, targetC) {
    if (!markerDragState) return;
    const { type, sourceNodeId, photoIndex, overflowFrom, sourceR, sourceC } = markerDragState;
    const hasTargetCell = targetR != null && targetC != null;
    const hasSourceCell = sourceR != null && sourceC != null;
    // Dropping something exactly back where it came from is a no-op —
    // same node AND same cell (or same node with neither side scoped to
    // a cell, i.e. a whole-node marker dropped on its own node).
    if (sourceNodeId === targetId &&
        (hasSourceCell === hasTargetCell) &&
        (!hasSourceCell || (sourceR === targetR && sourceC === targetC))) {
      return;
    }
    const sourceNode = findNode(sourceNodeId);
    const targetNode = findNode(targetId);
    if (!sourceNode || !targetNode) return;
    const source = hasSourceCell ? getCellAttach(sourceNode, sourceR, sourceC) : sourceNode;
    const target = hasTargetCell ? getCellAttach(targetNode, targetR, targetC) : targetNode;
    if (!source || !target) return;

    if (type === "tasks") {
      const srcTasks = getNodeTasks(source);
      if (!srcTasks.length) return;
      pushUndo();
      const carried = copy
        ? srcTasks.map(t => Object.assign({}, t, {
            id: uid(),
            subtasks: getTaskSubtasks(t).map(s => Object.assign({}, s, { id: uid() })),
          }))
        : srcTasks;
      target.tasks = getNodeTasks(target).concat(carried);
      if (!copy) source.tasks = [];
    } else if (type === "photos") {
      const srcIds = getNodeImageIds(source);
      if (!srcIds.length) return;
      pushUndo();
      const carriedIds = copy ? srcIds.map((id) => duplicatePhotoRecord(id, getNodeImageIds(target))) : srcIds;
      const pairs = srcIds.map((id, i) => [id, carriedIds[i]]);
      carryPhotoTags(source, target, pairs);
      carryPhotoNotes(source, target, pairs);
      carryPhotoComments(source, target, pairs);
      carryPhotoFavorites(source, target, pairs);
      carryPhotoTimestamps(source, target, pairs);
      target.images = getNodeImageIds(target).concat(carriedIds);
      if (!copy) {
        source.images = []; source.image = null;
        // A real move (not a copy) reuses the same id on the target (see
        // carriedIds above), so the tags/notes/comments just carried over
        // would otherwise also linger under the SOURCE's own id — a
        // leftover that showed up as a permanently broken, unclickable
        // entry in the tag browser once this node no longer actually held
        // that photo (see collectPhotoTagGroups).
        srcIds.forEach(id => { setPhotoTags(source, id, null); setPhotoNotes(source, id, null); setPhotoComment(source, id, null); setPhotoTimestamp(source, id, null); });
      }
    } else if (type === "photo") {
      // A single thumbnail, dragged by its index in the source's images.
      const srcIds = getNodeImageIds(source);
      if (photoIndex == null || photoIndex < 0 || photoIndex >= srcIds.length) return;
      pushUndo();
      const movedId = srcIds[photoIndex];
      const carriedId = copy ? duplicatePhotoRecord(movedId, getNodeImageIds(target)) : movedId;
      carryPhotoTags(source, target, [[movedId, carriedId]]);
      carryPhotoNotes(source, target, [[movedId, carriedId]]);
      carryPhotoComments(source, target, [[movedId, carriedId]]);
      carryPhotoFavorites(source, target, [[movedId, carriedId]]);
      carryPhotoTimestamps(source, target, [[movedId, carriedId]]);
      target.images = getNodeImageIds(target).concat([carriedId]);
      if (!copy) {
        const remaining = srcIds.slice();
        remaining.splice(photoIndex, 1);
        source.images = remaining;
        source.image = null;
        // Same cleanup as the bulk "photos" case above.
        setPhotoTags(source, movedId, null);
        setPhotoNotes(source, movedId, null);
        setPhotoComment(source, movedId, null);
        setPhotoTimestamp(source, movedId, null);
      }
    } else if (type === "photos-overflow") {
      // The "+N" badge — everything past the thumbnails actually shown.
      const srcIds = getNodeImageIds(source);
      const carried = srcIds.slice(overflowFrom || 0);
      if (!carried.length) return;
      pushUndo();
      const carriedIds = copy ? carried.map(duplicatePhotoRecord) : carried;
      const pairs = carried.map((id, i) => [id, carriedIds[i]]);
      carryPhotoTags(source, target, pairs);
      carryPhotoNotes(source, target, pairs);
      carryPhotoComments(source, target, pairs);
      carryPhotoFavorites(source, target, pairs);
      carryPhotoTimestamps(source, target, pairs);
      target.images = getNodeImageIds(target).concat(carriedIds);
      if (!copy) {
        source.images = srcIds.slice(0, overflowFrom || 0);
        source.image = null;
        // Same cleanup as the bulk "photos" case above.
        carried.forEach(id => { setPhotoTags(source, id, null); setPhotoNotes(source, id, null); setPhotoComment(source, id, null); setPhotoTimestamp(source, id, null); });
      }
    } else if (type === "notes") {
      // A cell's notes move as one unit, since a cell shows a single
      // combined note icon rather than one icon per note (contrast
      // "note-single", used for the node-level per-note icons).
      const srcNotes = getNodeNotes(source);
      if (!srcNotes.length) return;
      pushUndo();
      target.notes = getNodeNotes(target).concat(srcNotes);
      target.note = "";
      if (!copy) { source.notes = []; source.note = ""; }
    } else if (type === "note-single") {
      // A single note, dragged by its index in the source's notes — same
      // shape as the "photo" single-thumbnail case above, since each note
      // now has its own icon rather than one shared icon for the lot.
      const { noteIndex } = markerDragState;
      const srcNotes = getNodeNotes(source);
      if (noteIndex == null || noteIndex < 0 || noteIndex >= srcNotes.length) return;
      pushUndo();
      target.notes = getNodeNotes(target).concat([srcNotes[noteIndex]]);
      target.note = "";
      if (!copy) {
        const remaining = srcNotes.slice();
        remaining.splice(noteIndex, 1);
        source.notes = remaining;
        source.note = "";
      }
    } else if (type === "urls") {
      const srcUrls = getNodeUrls(source);
      if (!srcUrls.length) return;
      pushUndo();
      carryLinkTitles(source, target, srcUrls);
      carryLinkTimestamps(source, target, srcUrls);
      target.urls = getNodeUrls(target).concat(srcUrls);
      target.url = null;
      if (!copy) { source.urls = []; source.url = null; }
    } else if (type === "url-single") {
      // A single link, dragged by its index in the source's urls — same
      // shape as the "photo"/"note-single" single-item cases above.
      const { urlIndex } = markerDragState;
      const srcUrls = getNodeUrls(source);
      if (urlIndex == null || urlIndex < 0 || urlIndex >= srcUrls.length) return;
      pushUndo();
      const movedUrl = srcUrls[urlIndex];
      carryLinkTitles(source, target, [movedUrl]);
      carryLinkTimestamps(source, target, [movedUrl]);
      target.urls = getNodeUrls(target).concat([movedUrl]);
      target.url = null;
      if (!copy) {
        const remaining = srcUrls.slice();
        remaining.splice(urlIndex, 1);
        source.urls = remaining;
        source.url = null;
      }
    } else {
      return;
    }
    renderAll();
    persist();
  }

  // Same little sticky-note glyph the node-level note marker uses (see
  // the photo/note/link strip in renderNode) — shared here so a note
  // attached to a table cell reads as the same icon as a note attached
  // to a whole node.
  // The DRC notebook+pencil icon — one image used everywhere a DRC is
  // shown (node strip marker, right-click menu row, notes browser).
  const NODE_DRC_ICON_DATA_URL = "data:image/png;base64,";
  const NODE_DRC_ICON_IMG = '<img src="' + NODE_DRC_ICON_DATA_URL + '" alt="DRC" style="width:100%;height:100%;object-fit:contain;">';
  // Small inline DRC icon sized for text rows (menu labels, list icons).
  function drcIconEl(px) {
    const el = document.createElement("span");
    el.className = "drc-icon-inline";
    el.style.width = px + "px";
    el.style.height = px + "px";
    el.innerHTML = NODE_DRC_ICON_IMG;
    return el;
  }
  // The PLAN checklist-sheet icon — shown instead of the yellow sticky
  // note for any note titled "plan" or belonging to a task/subtask named
  // "plan" (see isPlanNote/isPlanNoteFor). Same embedding approach as the
  // DRC icon: a base64 PNG with the outer white background made
  // transparent.
  const NODE_PLAN_ICON_DATA_URL = "data:image/png;base64,";
  const NODE_PLAN_ICON_IMG = '<img src="' + NODE_PLAN_ICON_DATA_URL + '" alt="Plan" style="width:100%;height:100%;object-fit:contain;">';
  function planIconEl(px) {
    const el = document.createElement("span");
    el.className = "plan-icon-inline";
    el.style.width = px + "px";
    el.style.height = px + "px";
    el.innerHTML = NODE_PLAN_ICON_IMG;
    return el;
  }
  const CELL_NOTE_ICON_SVG = '<svg viewBox="0 0 24 24"><rect x="2.3" y="6.3" width="15.4" height="15.4" rx="1" fill="#E08A2E" stroke="#000" stroke-width="1.3" stroke-linejoin="round"/><path d="M6.3 4.3a1 1 0 011-1h12a1 1 0 011 1v12.9l-4.3 4.3H7.3a1 1 0 01-1-1z" fill="#F6E266" stroke="#000" stroke-width="1.3" stroke-linejoin="round" stroke-linecap="round"/><path d="M20.3 17.2l-4.3 4.3v-3a1.3 1.3 0 011.3-1.3z" fill="#F0C24E" stroke="#000" stroke-width="1.3" stroke-linejoin="round"/><line x1="9" y1="8.2" x2="18" y2="8.2" stroke="#000" stroke-width="1.15" stroke-linecap="round"/><line x1="9" y1="11.1" x2="18" y2="11.1" stroke="#000" stroke-width="1.15" stroke-linecap="round"/><line x1="9" y1="14" x2="14.5" y2="14" stroke="#000" stroke-width="1.15" stroke-linecap="round"/><path d="M14.4 4.6l3.5-3.5" stroke="#000" stroke-width="1.3" stroke-linecap="round"/><circle cx="19" cy="1.9" r="1.5" fill="#DC7A93" stroke="#000" stroke-width="1"/></svg>';
  // Small inline sticky-note icon sized for text rows (Notes/Favorites
  // browser list rows) — the exact same SVG as the node/cell note
  // markers (CELL_NOTE_ICON_SVG), so a plain note reads as the same
  // yellow note everywhere instead of falling back to a generic emoji.
  // Mirrors drcIconEl's shape/sizing convention above.
  function noteIconEl(px) {
    const el = document.createElement("span");
    el.className = "note-icon-inline";
    el.style.width = px + "px";
    el.style.height = px + "px";
    el.innerHTML = CELL_NOTE_ICON_SVG;
    return el;
  }

  // Same brain glyph the node-level brainstorm marker uses (see the
  // photo/note/link strip in renderNode) — shared here so a cell's own
  // Brainstorm scratchpad reads as the same icon as a node's.
  const CELL_BRAINSTORM_ICON_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 18V5"/><path d="M15 13a4.17 4.17 0 0 1-3-4 4.17 4.17 0 0 1-3 4"/><path d="M12 5A3 3 0 1 1 17.598 6.5"/><path d="M12 5A3 3 0 1 0 6.402 6.5"/><path d="M17.997 5.125a4 4 0 0 1 2.526 5.77"/><path d="M18 18a4 4 0 0 0 2-7.464"/><path d="M19.967 17.483A4 4 0 1 1 12 18a4 4 0 1 1-7.967-.517"/><path d="M6 18a4 4 0 0 1-2-7.464"/><path d="M6.003 5.125a4 4 0 0 0-2.526 5.77"/></svg>';

  // A hidden, dedicated file input for cell photos (kept separate from
  // nodeImageInput so picking a photo for a cell can never get confused
  // with picking one for the node itself if both were somehow triggered
  // close together).
  let pendingCellPhoto = null;
  const cellImageInput = document.createElement("input");
  cellImageInput.type = "file";
  cellImageInput.accept = "image/*";
  cellImageInput.multiple = true;
  cellImageInput.style.display = "none";
  document.body.appendChild(cellImageInput);

  // Adds one or more photos to a cell's attach record — exactly
  // handleNodePhotoFiles below, scoped to one cell's `images` array
  // instead of the whole node's.
  function handleCellPhotoFiles(nodeId, r, c, fileList) {
    const node = findNode(nodeId);
    const files = Array.from(fileList || []).filter(f => f && f.type && f.type.startsWith("image/"));
    if (!node || !node.table || !files.length) return;
    const a = getCellAttach(node, r, c);
    if (!Array.isArray(a.images)) a.images = getCellPhotoIds(a);
    pushUndo();
    let remaining = files.length;
    let hadError = false;
    const done = () => {
      remaining--;
      if (remaining === 0) {
        a.image = null; // fully migrated onto the images array
        renderAll();
        persist();
        if (hadError) alert("Some images couldn't be read.");
      }
    };
    files.forEach((file) => {
      const reader = new FileReader();
      reader.onload = () => {
        a.images.push(addPhotoRecord(reader.result, { avoid: getCellPhotoIds(a) }));
        done();
      };
      reader.onerror = () => { hadError = true; done(); };
      reader.readAsDataURL(file);
    });
  }

  cellImageInput.addEventListener("change", () => {
    if (cellImageInput.files && cellImageInput.files.length && pendingCellPhoto) {
      handleCellPhotoFiles(pendingCellPhoto.nodeId, pendingCellPhoto.r, pendingCellPhoto.c, cellImageInput.files);
    }
    cellImageInput.value = ""; // reset so picking the same file again still fires change
    pendingCellPhoto = null;
  });
  function openCellPhotoPicker(node, r, c) {
    if (!requireSignIn()) return;
    pendingCellPhoto = { nodeId: node.id, r, c };
    cellImageInput.click();
  }

  // Opens a cell's note in the exact same rich note editor used for a
  // node's own notes and a task's notes (see openNoteModal) — title,
  // rich text, multiple notes with paging, all of it — just scoped to
  // this one cell's attach record instead of the whole node.
  function editCellNote(node, r, c) {
    if (!requireSignIn()) return;
    openNoteModal(node.id, undefined, null, null, { r, c });
  }

  // Native prompt for adding a new URL to a cell — appends it to the
  // cell's `urls` array, then immediately asks for an optional display
  // name too. Exactly the node-level addNodeUrl flow above, just scoped
  // to one cell's attach record instead of the whole node.
  function addCellUrl(node, r, c) {
    if (!requireSignIn()) return;
    const input = window.prompt("URL to add to this cell:", "https://");
    if (input === null) return; // cancelled
    const trimmed = input.trim();
    if (!trimmed) return;
    const url = normalizeUrl(trimmed);
    const name = window.prompt("Name for this link (leave blank to use the URL):", "");
    pushUndo();
    const a = getCellAttach(node, r, c);
    const urls = getCellUrls(a).slice();
    urls.push(url);
    a.urls = urls;
    a.url = null; // fully migrated onto the array field
    if (name && name.trim()) setCellLinkTitle(a, url, name);
    renderAll();
    persist();
    if (!getCellLinkTitle(a, url)) fetchCellLinkTitle(node.id, r, c, url);
  }

  // Native prompt for editing (or, if cleared, removing) one existing URL
  // by its index in the cell's `urls` array — exactly editNodeUrl above,
  // scoped to a cell.
  function editCellUrlByIndex(node, r, c, index) {
    if (!requireSignIn()) return;
    const a = getCellAttach(node, r, c);
    const urls = getCellUrls(a).slice();
    if (index < 0 || index >= urls.length) return;
    const oldUrl = urls[index];
    const input = window.prompt("Edit URL (clear to remove):", oldUrl);
    if (input === null) return; // cancelled
    const trimmed = input.trim();
    pushUndo();
    if (trimmed) {
      const newUrl = normalizeUrl(trimmed);
      urls[index] = newUrl;
      if (newUrl !== oldUrl) {
        setCellLinkTitle(a, oldUrl, null);
        a.urls = urls;
        a.url = null;
        renderAll();
        persist();
        fetchCellLinkTitle(node.id, r, c, newUrl);
        return;
      }
    } else {
      setCellLinkTitle(a, oldUrl, null);
      urls.splice(index, 1);
    }
    a.urls = urls;
    a.url = null;
    renderAll();
    persist();
  }

  // Native prompt for giving a cell's link its own custom name — exactly
  // renameNodeUrl above, scoped to a cell.
  function renameCellUrl(node, r, c, index) {
    if (!requireSignIn()) return;
    const a = getCellAttach(node, r, c);
    const urls = getCellUrls(a);
    if (index < 0 || index >= urls.length) return;
    const url = urls[index];
    const input = window.prompt("Name for this link (leave blank to just show the URL):", getCellLinkTitle(a, url));
    if (input === null) return; // cancelled
    pushUndo();
    setCellLinkTitle(a, url, input);
    renderAll();
    persist();
  }

  // Removes one URL from a cell by its index — exactly removeNodeUrl
  // above, scoped to a cell.
  function removeCellUrl(node, r, c, index) {
    const a = getCellAttach(node, r, c);
    const urls = getCellUrls(a).slice();
    if (index < 0 || index >= urls.length) return;
    pushUndo();
    setCellLinkTitle(a, urls[index], null);
    urls.splice(index, 1);
    a.urls = urls;
    a.url = null;
    renderAll();
    persist();
  }

  // Right-click on one of a cell's link icons — exactly
  // openUrlSingleManageMenu above, scoped to a cell: rename/remove this
  // one link, click to edit its URL.
  function openCellUrlManageMenu(node, r, c, index, x, y) {
    const a = getCellAttach(node, r, c);
    const urls = getCellUrls(a);
    const u = urls[index];
    if (!u) return;
    resetContextMenu();
    const it = document.createElement("div");
    it.className = "ctx-item";
    it.title = u;
    const labelSpan = document.createElement("span");
    labelSpan.className = "ctx-item-label";
    labelSpan.appendChild(cellLinkRowFragment(u, a));
    it.appendChild(labelSpan);
    const popup = document.createElement("span");
    popup.className = "ctx-item-remove ctx-item-popup";
    popup.textContent = "🪟";
    popup.title = "Open in a new window (smaller than this one)";
    popup.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); openUrlAsPopup(u); });
    it.appendChild(popup);
    const rename = document.createElement("span");
    rename.className = "ctx-item-remove ctx-item-rename";
    rename.textContent = "✎";
    rename.title = "Rename";
    rename.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); renameCellUrl(node, r, c, index); });
    it.appendChild(rename);
    const comment = document.createElement("span");
    comment.className = "ctx-item-remove ctx-item-comment";
    comment.textContent = "💬";
    comment.title = "Comment";
    comment.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); commentOnCellUrl(node, r, c, index); });
    it.appendChild(comment);
    const rm = document.createElement("span");
    rm.className = "ctx-item-remove";
    rm.textContent = "✕";
    rm.title = "Remove";
    rm.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); removeCellUrl(node, r, c, index); });
    it.appendChild(rm);
    it.addEventListener("click", () => { closeContextMenu(); editCellUrlByIndex(node, r, c, index); });
    ctxMenu.appendChild(it);
    positionContextMenu(x, y);
  }

  // Same comment editor as commentOnNodeUrl, scoped to one table cell's
  // link (see getCellLinkComment/setCellLinkComment).
  function commentOnCellUrl(node, r, c, index) {
    if (!requireSignIn()) return;
    const a = getCellAttach(node, r, c);
    const urls = getCellUrls(a);
    const u = urls[index];
    if (!u) return;
    openLinkCommentModal(u, {
      get: () => getCellLinkComment(getCellAttach(node, r, c), u),
      set: (v) => setCellLinkComment(getCellAttach(node, r, c), u, v),
    });
  }

  // The "+" button's menu — same reused ctx-menu the node right-click
  // menu and the note/link picker popups use (see openContextMenu /
  // openNoteManageMenu), just scoped to one cell instead of a whole
  // node. Lets you add, replace, or remove each of the six attachment
  // kinds a cell can carry: photo, note, link, task, timer, and the
  // affirmation game — the last two reuse the exact same modal/interface
  // as their node-level counterparts (see openTimerModal/openAffirmationGame),
  // just aimed at this one cell instead of the whole node.
  function openCellAddMenu(node, r, c, x, y) {
    if (!requireSignIn()) return;
    resetContextMenu();
    const a = getCellAttach(node, r, c);
    const items = [];
    items.push(["Add photo…", () => openCellPhotoPicker(node, r, c)]);
    if (cellHasImages(a)) {
      // No cell-aware openPhotoModal yet (see the deferred item on
      // generalizing photoModalState to carry r/c) — until that lands,
      // this just opens the first photo in a new tab, same as clicking a
      // thumbnail does, so the menu at least has an entry here matching
      // the node menu's "View photo(s)…" for parity.
      const cellPhotos = getCellPhotos(a);
      items.push([cellPhotos.length > 1 ? "View photo(s)…" : "View photo…", () => window.open(cellPhotos[0], "_blank", "noopener")]);
    }
    if (cellHasImages(a)) items.push(["Remove all photos", () => {
      pushUndo();
      const removedCellIds = getCellPhotoIds(a).slice();
      a.images = null;
      a.image = null;
      removedCellIds.forEach(id => { if (!String(id).startsWith("data:")) deletePhotoRecord(id); });
      renderAll();
      persist();
    }]);
    items.push([cellHasNotes(a) ? "Edit note…" : "Add note…", () => editCellNote(node, r, c)]);
    if (cellHasNotes(a)) items.push(["Remove note", () => { pushUndo(); a.note = null; a.notes = null; renderAll(); persist(); }]);
    items.push(["Add link…", () => addCellUrl(node, r, c)]);
    {
      // Full task list for this cell — the exact same modal a node's
      // "Tasks…" menu entry opens (see openTasksModal), just scoped to
      // this cell's own attach record instead of the node.
      const prog = nodeTaskProgress(a);
      const label = prog.total ? `Tasks… (${prog.done}/${prog.total})` : "Add tasks…";
      items.push([label, () => openTasksModal(node.id, r, c)]);
    }
    {
      const played = getNodeTimePlayed(a);
      const label = played ? `Timer — ${formatTimePlayed(played)}…` : "Add timer…";
      items.push([label, () => openTimerModal(node.id, r, c)]);
      if (played) items.push(["Remove timer", () => { pushUndo(); a.timePlayedSec = 0; renderAll(); persist(); }]);
    }
    {
      const wins = nodeAffirmationWins(a);
      const label = wins ? `🎮 Affirmation game (✓ ${wins})` : "🎮 Affirmation game";
      items.push([label, () => openAffirmationGame(node.id, r, c)]);
    }
    {
      const pts = brainstormPoints(a);
      const label = pts > 0 ? `🧠 Brainstorm (${pts} pt${pts === 1 ? "" : "s"})…` : "🧠 Brainstorm…";
      items.push([label, () => openBrainstormModal(node.id, r, c)]);
    }
    // "Merge cells" only shows up once a multi-cell rectangle is actually
    // selected in this same table (see state.cellRange/handleTableCellClick,
    // set by shift-clicking a second cell) — merging folds that whole
    // rectangle into the cell this menu was opened on, whichever one that
    // is, since mergeCellRange always uses the rectangle's own top-left
    // corner as the origin regardless of which cell you clicked. "Unmerge"
    // instead shows up whenever this cell is already part of an existing
    // merge (see getCellMerge), letting a merged block be split back
    // apart from any of its cells' own "+" menu.
    if (state.cellRange && state.cellRange.nodeId === node.id &&
        (state.cellRange.r1 > state.cellRange.r0 || state.cellRange.c1 > state.cellRange.c0)) {
      const rr = state.cellRange;
      const mergeRows = rr.r1 - rr.r0 + 1, mergeCols = rr.c1 - rr.c0 + 1;
      items.push([`Merge cells (${mergeRows}×${mergeCols})`, () => {
        pushUndo();
        mergeCellRange(node, rr.r0, rr.c0, rr.r1, rr.c1);
        state.cellRange = null;
        renderAll();
        persist();
      }]);
    }
    const currentMerge = getCellMerge(node, r, c);
    if (currentMerge && (currentMerge.r1 > currentMerge.r0 || currentMerge.c1 > currentMerge.c0)) {
      items.push(["Unmerge cells", () => { pushUndo(); unmergeCellAt(node, r, c); renderAll(); persist(); }]);
    }
    items.forEach(([label, fn]) => {
      const it = document.createElement("div");
      it.className = "ctx-item";
      const labelSpan = document.createElement("span");
      labelSpan.className = "ctx-item-label";
      labelSpan.textContent = label;
      it.appendChild(labelSpan);
      it.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); fn(); });
      ctxMenu.appendChild(it);
    });

    // Same swatch picker as a node's own "Node color"/"Branch color" row
    // (see openContextMenu) — stored on this cell's attach record instead,
    // so filling one cell doesn't touch the rest of the table (see the
    // cell-building loop's td.style.background, and note the fill is
    // painted on the whole merged block's single <td> when this cell is
    // part of one — see cellSpan/isMergeOrigin).
    {
      const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep);
      const label = document.createElement("div");
      label.className = "ctx-item"; label.style.cursor = "default";
      label.textContent = "Fill color";
      ctxMenu.appendChild(label);
      const sw = document.createElement("div"); sw.className = "ctx-swatches";
      const resetSwatch = document.createElement("span");
      resetSwatch.className = "ctx-swatch ctx-swatch-reset" + (!a.fillColor ? " active" : "");
      resetSwatch.title = "Default";
      resetSwatch.addEventListener("click", (e) => { e.stopPropagation(); pushUndo(); a.fillColor = null; closeContextMenu(); renderAll(); persist(); });
      sw.appendChild(resetSwatch);
      PALETTE.forEach(c => {
        const s = document.createElement("span");
        s.className = "ctx-swatch" + (a.fillColor === c ? " active" : "");
        s.style.background = c;
        s.addEventListener("click", (e) => { e.stopPropagation(); pushUndo(); a.fillColor = c; closeContextMenu(); renderAll(); persist(); });
        sw.appendChild(s);
      });
      ctxMenu.appendChild(sw);
    }

    // Same per-cell text-color override as a node's own "Font color" row
    // (see openContextMenu) — stored on this cell's attach record instead
    // of the node, so recoloring one cell's text doesn't touch the rest
    // of the table (see the cell-building loop's textEl.style.color).
    {
      const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep);
      const label = document.createElement("div");
      label.className = "ctx-item"; label.style.cursor = "default";
      label.textContent = "Font color";
      ctxMenu.appendChild(label);
      const sw = document.createElement("div"); sw.className = "ctx-swatches";
      const resetSwatch = document.createElement("span");
      resetSwatch.className = "ctx-swatch ctx-swatch-reset" + (!a.fontColor ? " active" : "");
      resetSwatch.title = "Default";
      resetSwatch.addEventListener("click", (e) => { e.stopPropagation(); pushUndo(); a.fontColor = null; closeContextMenu(); renderAll(); persist(); });
      sw.appendChild(resetSwatch);
      PALETTE.forEach(c => {
        const s = document.createElement("span");
        s.className = "ctx-swatch" + (a.fontColor === c ? " active" : "");
        s.style.background = c;
        s.addEventListener("click", (e) => { e.stopPropagation(); pushUndo(); a.fontColor = c; closeContextMenu(); renderAll(); persist(); });
        sw.appendChild(s);
      });
      ctxMenu.appendChild(sw);
    }

    // Left/center/right alignment for this cell's text — stored on the
    // cell's attach record (a.align: null means the default left align,
    // same "null = default" convention fillColor/fontColor use above)
    // so aligning one cell never touches the rest of the table.
    {
      const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep);
      const label = document.createElement("div");
      label.className = "ctx-item"; label.style.cursor = "default";
      label.textContent = "Text align";
      ctxMenu.appendChild(label);
      const row = document.createElement("div"); row.className = "ctx-align-row";
      [["left", "Left"], ["center", "Center"], ["right", "Right"]].forEach(([val, txt]) => {
        const btn = document.createElement("div");
        const isActive = (a.align || "left") === val;
        btn.className = "ctx-align-btn" + (isActive ? " active" : "");
        btn.textContent = txt;
        btn.addEventListener("click", (e) => {
          e.stopPropagation();
          pushUndo();
          a.align = val === "left" ? null : val;
          closeContextMenu();
          renderAll();
          persist();
        });
        row.appendChild(btn);
      });
      ctxMenu.appendChild(row);
    }

    positionContextMenu(x, y);
  }

  // The row of small icons under a cell's text — one per attachment it
  // currently holds (photo/note/link/task), plus a trailing "+" to add
  // more. Mirrors the node-level photo/note/link strip (see renderNode)
  // at a smaller scale, and reads/writes node.table.attach[r][c] instead
  // of the node's own fields.
  function buildCellIconStrip(node, r, c) {
    const a = getCellAttach(node, r, c);
    const strip = document.createElement("div");
    strip.className = "node-table-cell-icons";
    strip.addEventListener("mousedown", (e) => e.stopPropagation());
    strip.addEventListener("pointerdown", (e) => e.stopPropagation());
    strip.addEventListener("click", (e) => e.stopPropagation());

    // One thumbnail per photo (capped, with a "+N" overflow badge past
    // the cap), same treatment as the node-level photo strip (see
    // renderNode) — click to view, drag onto a node to move/copy it
    // there (see startMarkerDrag/completeMarkerDrop), right-click a
    // single thumbnail to remove just that one.
    const cellImages = getCellPhotos(a);
    if (cellImages.length) {
      const overflow = cellImages.length > 4;
      const shownCount = overflow ? 1 : cellImages.length;
      for (let i = 0; i < shownCount; i++) {
        const thumb = document.createElement("span");
        thumb.className = "node-table-cell-icon node-table-cell-photo";
        const fullSrc = cellImages[i];
        const cachedThumb = getMarkerThumb(fullSrc, () => {
          const liveThumb = nodesLayer.querySelector(`.node[data-id="${node.id}"] .node-table-cell[data-r="${r}"][data-c="${c}"] .node-table-cell-photo[data-src-index="${i}"]`);
          if (liveThumb) liveThumb.style.backgroundImage = `url("${nodeThumbCache.get(fullSrc)}")`;
        });
        thumb.dataset.srcIndex = String(i);
        thumb.style.backgroundImage = `url("${cachedThumb || fullSrc}")`;
        thumb.draggable = true;
        thumb.addEventListener("dragend", endMarkerDrag);
        thumb.addEventListener("click", (e) => { e.stopPropagation(); window.open(fullSrc, "_blank", "noopener"); });
        if (overflow) {
          thumb.title = `${cellImages.length} photos — click to view the first, drag to move them all onto a node or cell (hold Alt to copy)`;
          thumb.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "photos", { sourceR: r, sourceC: c }));
          const badge = document.createElement("span");
          badge.className = "node-marker-count";
          badge.textContent = String(cellImages.length);
          thumb.appendChild(badge);
        } else {
          thumb.title = "Click to view — drag onto a node or cell to move it there (hold Alt to copy) — right-click to remove";
          thumb.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "photo", { photoIndex: i, sourceR: r, sourceC: c }));
          thumb.addEventListener("contextmenu", (e) => {
            e.preventDefault();
            e.stopPropagation();
            if (!requireSignIn()) return;
            pushUndo();
            const ids = getCellPhotoIds(a).slice();
            const removedId = ids[i];
            ids.splice(i, 1);
            a.images = ids;
            a.image = null;
            if (!String(removedId).startsWith("data:")) deletePhotoRecord(removedId);
            renderAll();
            persist();
          });
        }
        strip.appendChild(thumb);
      }
    }
    if (cellHasNotes(a)) {
      const noteIcon = document.createElement("span");
      noteIcon.className = "node-table-cell-icon node-table-cell-note";
      const notes = getCellNotes(a);
      // A cell whose notes are all DRC notes gets the DRC image, same as a
      // node's own DRC marker.
      noteIcon.innerHTML = notes.every(isDRCNote) ? NODE_DRC_ICON_IMG : (notes.every(isPlanNote) ? NODE_PLAN_ICON_IMG : CELL_NOTE_ICON_SVG);
      noteIcon.title = (notes.length > 1 ? `Notes (${notes.length})…` : notePreviewText(notes[0])) + " — drag onto a node or cell to move (hold Alt to copy)";
      noteIcon.draggable = true;
      noteIcon.addEventListener("click", () => editCellNote(node, r, c));
      noteIcon.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "notes", { sourceR: r, sourceC: c }));
      noteIcon.addEventListener("dragend", endMarkerDrag);
      strip.appendChild(noteIcon);
    }
    // One icon per link (instead of a single icon), same treatment as
    // the node-level link markers (see renderNode) — each link is
    // independently visible, clickable, and editable via right-click.
    getCellUrls(a).forEach((u, i) => {
      const linkIcon = document.createElement("span");
      linkIcon.className = "node-table-cell-icon node-table-cell-link";
      linkIcon.innerHTML = linkIconFor(u);
      const linkTitle = getCellLinkTitle(a, u);
      linkIcon.title = (linkTitle || u) + " — drag onto a node or cell to move (hold Alt to copy)";
      linkIcon.draggable = true;
      attachLinkCommentTooltip(linkIcon, u, () => getCellLinkComment(getCellAttach(node, r, c), u), () => getCellLinkTitle(getCellAttach(node, r, c), u));
      linkIcon.addEventListener("click", () => openLinkSmart(u, {
        get: () => getCellLinkComment(getCellAttach(node, r, c), u),
        set: (v) => setCellLinkComment(getCellAttach(node, r, c), u, v),
        getPhotos: () => getCellLinkPhotos(getCellAttach(node, r, c), u),
        addPhoto: (dataUrl) => addCellLinkPhoto(getCellAttach(node, r, c), u, dataUrl),
        removePhoto: (id) => removeCellLinkPhoto(getCellAttach(node, r, c), u, id),
      }));
      linkIcon.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "url-single", { urlIndex: i, sourceR: r, sourceC: c }));
      linkIcon.addEventListener("dragend", endMarkerDrag);
      linkIcon.addEventListener("contextmenu", (e) => {
        e.preventDefault();
        openCellUrlManageMenu(node, r, c, i, e.clientX, e.clientY);
      });
      strip.appendChild(linkIcon);
    });
    // Same task list a node carries (see getNodeTasks/openTasksModal) —
    // this cell just shows it as a compact "done/total" pill instead of
    // the full progress bar a node's box has room for (see the
    // .node-progress-row block in renderNode below); clicking it opens
    // the exact same Tasks modal, scoped to this cell. Draggable onto
    // another node to move the whole list there (hold Alt to copy),
    // mirroring the node-level progress row's own drag behavior.
    const cellTaskProg = nodeTaskProgress(a);
    if (cellTaskProg.total) {
      const taskEl = document.createElement("span");
      taskEl.className = "node-table-cell-icon node-table-cell-tasks" + (cellTaskProg.pct >= 1 ? " done" : "");
      taskEl.textContent = `✓${cellTaskProg.done}/${cellTaskProg.total}`;
      taskEl.title = `${cellTaskProg.done} of ${cellTaskProg.total} tasks done — click to open, drag onto a node or cell to move them there (hold Alt to copy)`;
      taskEl.draggable = true;
      taskEl.addEventListener("click", (e) => { e.stopPropagation(); openTasksModal(node.id, r, c); });
      taskEl.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "tasks", { sourceR: r, sourceC: c }));
      taskEl.addEventListener("dragend", endMarkerDrag);
      strip.appendChild(taskEl);
    }
    const cellAffirmationWins = nodeAffirmationWins(a);
    if (cellAffirmationWins) {
      // Same checkmark-with-count marker as the node-level strip (see
      // renderNode) — click jumps straight into a new round for this cell.
      const affIcon = document.createElement("span");
      affIcon.className = "node-table-cell-icon node-table-cell-affirmation";
      affIcon.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M4.5 12.5l5 5L19.5 7"/></svg>';
      affIcon.title = `Affirmation game — ${cellAffirmationWins} round${cellAffirmationWins === 1 ? "" : "s"} completed. Click to play again.`;
      affIcon.addEventListener("click", () => openAffirmationGame(node.id, r, c));
      if (cellAffirmationWins > 1) {
        const affCount = document.createElement("span");
        affCount.className = "node-marker-count";
        affCount.textContent = String(cellAffirmationWins);
        affIcon.appendChild(affCount);
      }
      strip.appendChild(affIcon);
    }
    const cellTimePlayed = getNodeTimePlayed(a);
    if (cellTimePlayed) {
      // Same "logged time" badge as the node-level strip (see renderNode)
      // — click opens the timer modal for this cell.
      const tbadge = document.createElement("span");
      tbadge.className = "node-table-cell-icon node-table-cell-timer";
      tbadge.title = `${formatTimePlayed(cellTimePlayed)} logged — click to add more`;
      tbadge.addEventListener("click", () => openTimerModal(node.id, r, c));
      const tlabel = document.createElement("span");
      tlabel.textContent = formatTimePlayed(cellTimePlayed);
      tbadge.appendChild(tlabel);
      strip.appendChild(tbadge);
    }
    const cellBrainstormPts = brainstormPoints(a);
    if (cellBrainstormPts > 0) {
      // Same brain-with-count marker as the node-level strip (see
      // renderNode) — click jumps straight into the scratchpad for this cell.
      const bIcon = document.createElement("span");
      bIcon.className = "node-table-cell-icon node-table-cell-brainstorm";
      bIcon.textContent = "🧠";
      bIcon.title = `Brainstorm — ${cellBrainstormPts} point${cellBrainstormPts === 1 ? "" : "s"} (${brainstormLineCount(a)} lines). Click to keep writing.`;
      bIcon.addEventListener("click", () => openBrainstormModal(node.id, r, c));
      if (cellBrainstormPts > 1) {
        const bCount = document.createElement("span");
        bCount.className = "node-marker-count";
        bCount.textContent = String(cellBrainstormPts);
        bIcon.appendChild(bCount);
      }
      strip.appendChild(bIcon);
    }

    const addBtn = document.createElement("span");
    addBtn.className = "node-table-cell-icon node-table-cell-add";
    addBtn.textContent = "+";
    addBtn.title = "Add a photo, note, link, task, timer, affirmation game, or brainstorm to this cell";
    addBtn.addEventListener("click", (e) => openCellAddMenu(node, r, c, e.clientX, e.clientY));
    strip.appendChild(addBtn);

    return strip;
  }

  // Builds the actual <table> for a table node (see nodeIsTable) inside
  // its div, using the exact column widths / row heights computeNodeBox
  // (via computeTableBox) already worked out — so what's on screen always
  // matches the box the layout/connector code positioned it with. Every
  // cell holds its own contentEditable text field plus a small icon strip
  // (see buildCellIconStrip) for that cell's own photo/note/link/task
  // attachments; text edits commit on blur (see the "blur" listener
  // below) rather than live per-keystroke, which keeps this simple at
  // the cost of the box only resizing to fit new text once you click
  // away from the cell.
  function renderTableGrid(div, node) {
    ensureTableAttach(node);
    const cells = node.table.cells;
    const cols = Math.max(1, ...cells.map(r => r.length));
    const colWidths = node._tableColWidths || new Array(cols).fill(TABLE_CELL_MIN_W);
    const rowHeights = node._tableRowHeights || cells.map(() => TABLE_CELL_MIN_H);

    const table = document.createElement("table");
    table.className = "node-table" + (node.table.gridStyle === "outline" ? " node-table-outline" : "");
    table.addEventListener("mousedown", (e) => e.stopPropagation());
    table.addEventListener("pointerdown", (e) => e.stopPropagation());
    table.addEventListener("dblclick", (e) => e.stopPropagation());

    const colgroup = document.createElement("colgroup");
    colWidths.forEach((w) => {
      const col = document.createElement("col");
      col.style.width = w + "px";
      colgroup.appendChild(col);
    });
    table.appendChild(colgroup);

    const tbody = document.createElement("tbody");
    cells.forEach((row, r) => {
      const tr = document.createElement("tr");
      tr.style.height = (rowHeights[r] || TABLE_CELL_MIN_H) + "px";
      for (let c = 0; c < cols; c++) {
        // A cell covered by another cell's merge (see mergeCellRange)
        // renders no <td> of its own at all — the origin cell's rowSpan/
        // colSpan below covers this spot instead.
        if (!isMergeOrigin(node, r, c)) continue;
        const span = cellSpan(node, r, c);
        const a = getCellAttach(node, r, c);
        const td = document.createElement("td");
        td.className = "node-table-cell";
        td.dataset.r = String(r);
        td.dataset.c = String(c);
        if (span.rowSpan > 1) td.rowSpan = span.rowSpan;
        if (span.colSpan > 1) td.colSpan = span.colSpan;
        if (a.fillColor) td.style.background = a.fillColor;
        if (state.cellRange && state.cellRange.nodeId === node.id &&
            r >= state.cellRange.r0 && r <= state.cellRange.r1 &&
            c >= state.cellRange.c0 && c <= state.cellRange.c1) {
          td.classList.add("range-selected");
        }
        td.addEventListener("click", (e) => { e.stopPropagation(); handleTableCellClick(node, r, c, e.shiftKey); });
        td.addEventListener("contextmenu", (e) => {
          e.preventDefault(); e.stopPropagation();
          if (!requireSignIn()) return;
          openCellAddMenu(node, r, c, e.clientX, e.clientY);
        });

        // Accept a photo/note/link/task marker dragged from a node or
        // another cell (see startMarkerDrag/completeMarkerDrop) — stops
        // propagation so it lands on this one cell instead of also
        // bubbling up to the whole-node drop handler below.
        td.addEventListener("dragover", (e) => {
          if (!markerDragState) return;
          if (markerDragState.sourceNodeId === node.id && markerDragState.sourceR === r && markerDragState.sourceC === c) return;
          e.preventDefault();
          e.stopPropagation();
          e.dataTransfer.dropEffect = e.altKey ? "copy" : "move";
          td.classList.add("marker-drop-target");
        });
        td.addEventListener("dragleave", (e) => {
          if (e.relatedTarget && td.contains(e.relatedTarget)) return;
          td.classList.remove("marker-drop-target");
        });
        td.addEventListener("drop", (e) => {
          if (!markerDragState) return;
          if (markerDragState.sourceNodeId === node.id && markerDragState.sourceR === r && markerDragState.sourceC === c) return;
          e.preventDefault();
          e.stopPropagation();
          td.classList.remove("marker-drop-target");
          completeMarkerDrop(node.id, e.altKey, r, c);
        });

        const textEl = document.createElement("div");
        textEl.className = "node-table-cell-text";
        textEl.contentEditable = "true";
        textEl.spellcheck = false;
        textEl.textContent = row[c] || "";
        textEl.style.color = a.fontColor || "";
        textEl.style.textAlign = a.align || "";
        textEl.addEventListener("click", (e) => { e.stopPropagation(); handleTableCellClick(node, r, c, e.shiftKey); });
        textEl.addEventListener("blur", () => {
          const newText = textEl.textContent;
          if (newText === (cells[r][c] || "")) return;
          if (!requireSignIn()) { textEl.textContent = cells[r][c] || ""; return; }
          pushUndo();
          cells[r][c] = newText;
          renderAll();
          persist();
        });
        td.appendChild(textEl);
        td.appendChild(buildCellIconStrip(node, r, c));
        tr.appendChild(td);
      }
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    div.appendChild(table);
  }

  // Click handling for a table cell, shared by the cell's <td> and its
  // text div. A plain click selects just that one cell and plants a new
  // range anchor there (see state.cellRangeAnchor); a shift-click, as
  // long as the anchor belongs to this same table, extends the
  // selection into a rectangle between the anchor and the clicked cell
  // (see state.cellRange) — that rectangle is what "Merge cells" (in
  // openCellAddMenu) acts on.
  //
  // A plain click on a cell that's already the selected one (no range to
  // draw or clear) is just caret placement inside the contentEditable text
  // box that's already on screen — skip the renderAll() in that case, since
  // rebuilding the grid would swap in a fresh <div> and throw away the caret
  // position the browser just set from this very click. Every other case
  // (selecting a different cell, or drawing/clearing a range highlight)
  // still needs the full redraw.
  function handleTableCellClick(node, r, c, shiftKey) {
    if (shiftKey && state.cellRangeAnchor && state.cellRangeAnchor.nodeId === node.id) {
      const anchor = state.cellRangeAnchor;
      state.cellRange = {
        nodeId: node.id,
        r0: Math.min(anchor.r, r), r1: Math.max(anchor.r, r),
        c0: Math.min(anchor.c, c), c1: Math.max(anchor.c, c),
      };
      state.selectedId = node.id;
      state.selectedCell = { nodeId: node.id, r, c };
      renderAll();
      return;
    }
    const alreadySelected = !state.cellRange && state.selectedCell &&
      state.selectedCell.nodeId === node.id && state.selectedCell.r === r && state.selectedCell.c === c;
    state.cellRangeAnchor = { nodeId: node.id, r, c };
    state.cellRange = null;
    selectNode(node.id, { nodeId: node.id, r, c });
    if (alreadySelected) return;
    renderAll();
  }


  function renderNode(node, ox, oy) {
    const depth = node._depth;
    const w = node._w || NODE_H;
    const h = node._h || (depth === 0 ? ROOT_H : NODE_H);
    const div = document.createElement("div");
    // Older saves may have `glow: true` from before named intensities
    // existed — treat that the same as "soft" instead of producing a
    // dead "glow-true" class that matches no CSS rule.
    const glowVariant = node.glow === true ? "soft" : node.glow;
    div.className = `node depth-${Math.min(depth, 3)}` + (node.id === state.selectedId ? " selected" : "") + (node.struck ? " struck" : "") + (glowVariant ? ` glow-${glowVariant}` : "");
    div.dataset.id = node.id;
    div.style.left = (ox + nodeLeftX(node)) + "px";
    div.style.top = (oy + node._y + (node.oy || 0) - h / 2) + "px";
    div.style.width = w + "px";
    div.style.height = h + "px";
    div.title = node.text;

    const theme = state.current.theme;
    if (depth === 0) {
      // The root/"mother topic" node has its own optional custom color
      // (node.color), separate from branch colors below it — when set,
      // it replaces the default navy/orange look with a matching
      // gradient fill and border, the same way a branch's color tints
      // its own node. Falls back to the original fixed look when unset.
      const rootColor = node.color;
      if (rootColor) {
        const lighter = blendHex(rootColor, "#ffffff", 0.18);
        const darker = blendHex(rootColor, "#000000", 0.5);
        div.style.background = `linear-gradient(155deg, ${lighter} 0%, ${darker} 65%)`;
        div.style.border = `2px solid ${rootColor}`;
        div.style.setProperty("--sel-color", rootColor);
      } else {
        div.style.border = "2px solid #F5A25C";
      }
    }

    const color = depth === 0 ? null : (node.color || branchColorFor(state.current.root, node) || "#5b6272");
    // What's actually visible behind this node's text, used both to keep
    // the editing caret visible and, for the solid-filled first level
    // only, to pick a plain black/white text color with good contrast
    // against that fill — every level below that tints its text with
    // the branch color instead (see below).
    let effectiveBg = theme.background || defaultBg();
    if (color) {
      div.style.setProperty("--sel-color", color);
      if (depth === 1) {
        div.style.background = color;
        effectiveBg = color;
      } else if (depth === 2) {
        // Level 3: outlined box only — transparent fill, branch color on the border.
        div.style.background = "transparent";
        div.style.borderColor = color;
      } else {
        // Level 4 and deeper: no box at all — no fill, no border — just
        // the text, tinted with the branch color so nodes still read as
        // part of their branch without a bordered box around them.
        div.style.background = "transparent";
        div.style.color = color;
      }
    }
    if (depth === 0) effectiveBg = node.color ? blendHex(node.color, "#000000", 0.5) : "#0A0B24"; // matches --root-fill, or the custom root color's dark gradient end
    // Level 3+ nodes (outlined boxes and, deeper still, no box at all)
    // have their text tinted with the branch color instead of plain
    // black/white, so the color story stays consistent all the way down
    // the branch rather than only kicking in once the box disappears —
    // unless the user has set a custom font color, which still wins.
    div.style.color = node.fontColor
      ? node.fontColor
      : (color && depth > 1 && theme.fontMode !== "custom")
      ? color
      : (theme.fontMode === "custom" ? theme.fontColor : caretColorFor(effectiveBg));
    div.style.caretColor = caretColorFor(effectiveBg);

    // The root node's title used to scroll like a marquee when it ran
    // long, rather than wrapping/clipping — removed at the user's
    // request in favor of plain text, same as every other node.
    if (nodeIsTable(node)) {
      renderTableGrid(div, node);
    } else {
    div.textContent = node.text || (node.id === state.editingId ? "" : "(untitled)");

    if (node.id === state.editingId) {
      div.contentEditable = "true";
      div.spellcheck = false;
      div.addEventListener("input", () => autosizeEditingBox(div, node));
      // Pasting an image while typing a node's text would otherwise let
      // the browser embed it directly inline in the contenteditable box
      // (rendered at full size, blowing up the node on the canvas). Route
      // it to the node's photo attachments instead, same as pasting an
      // image with the node just selected (not being edited) already does.
      div.addEventListener("paste", (e) => {
        const items = e.clipboardData && e.clipboardData.items;
        if (!items) return;
        const imageItem = Array.from(items).find(i => i.type && i.type.startsWith("image/"));
        if (!imageItem) return;
        const file = imageItem.getAsFile();
        if (!file) return;
        e.preventDefault();
        handleNodePhotoFiles(node.id, [file]);
      });
    }
    }

    // The root node doubles as a small live clock — current time,
    // UTC/US(NY)/UK world clocks, the Vietnamese weekday+date, and the
    // lunar date, right in the map's central node. Filled in once here
    // (see rootClockValues) and kept ticking afterward by rootClockTick,
    // a separate 1-second interval that just walks back in and updates
    // this block's text — see "root node live clock" above. Hidden while
    // actively editing the title, same as every other marker below.
    if (depth === 0 && node.id !== state.editingId && !isClockHidden()) {
      const clockBlock = document.createElement("span");
      clockBlock.className = "node-clock-block";
      const v = rootClockValues(new Date());

      const timeEl = document.createElement("span");
      timeEl.className = "node-clock-time";
      timeEl.textContent = v.time;
      clockBlock.appendChild(timeEl);

      const worldRow = document.createElement("span");
      worldRow.className = "node-clock-world";
      [["UTC", "utc", v.utc], ["NY", "us", v.us], ["UK", "uk", v.uk]].forEach(([label, key, val]) => {
        const cell = document.createElement("span");
        cell.className = "node-clock-tz";
        const lab = document.createElement("b");
        lab.textContent = label;
        const t = document.createElement("span");
        t.dataset.tz = key;
        t.textContent = val;
        cell.appendChild(lab);
        cell.appendChild(t);
        worldRow.appendChild(cell);
      });
      clockBlock.appendChild(worldRow);

      const solarEl = document.createElement("span");
      solarEl.className = "node-clock-solar";
      solarEl.textContent = v.solar;
      clockBlock.appendChild(solarEl);

      const lunarEl = document.createElement("span");
      lunarEl.className = "node-clock-lunar";
      lunarEl.textContent = v.lunar;
      clockBlock.appendChild(lunarEl);

      div.appendChild(clockBlock);
    }

    // collapse toggle — hidden while actively editing so it doesn't sit
    // inside the contenteditable box and throw off caret placement.
    if (node.children && node.children.length > 0 && node.id !== state.editingId) {
      const toggle = document.createElement("span");
      toggle.className = "node-collapse";
      if (depth > 0 && node._x < 0) {
        toggle.style.right = "auto";
        toggle.style.left = "-9px";
      }
      if (node.collapsed) {
        // Collapsed: the toggle doubles as the child-count badge — the
        // number itself sits on the clickable circle instead of a separate
        // inert badge floating at the corner, so tapping the count is what
        // expands the branch back open.
        toggle.classList.add("node-collapse-count");
        toggle.textContent = String(countAll(node));
        toggle.title = "Expand children";
      } else {
        toggle.textContent = "–";
      }
      toggle.addEventListener("mousedown", (e) => { e.stopPropagation(); });
      toggle.addEventListener("pointerdown", (e) => { e.stopPropagation(); });
      toggle.addEventListener("click", (e) => {
        e.stopPropagation();
        pushUndo();
        node.collapsed = !node.collapsed;
        renderAll();
        persist();
      });
      div.appendChild(toggle);
    }

    const nodeUrls = getNodeUrls(node);
    const nodeNotes = getNodeNotes(node);
    // Tasks with their own note(s) surface a note marker on the node too,
    // same icon as a node's own notes, so a note tucked away inside a
    // task's checklist isn't invisible from the mindmap itself.
    const tasksWithNotes = getNodeTasks(node).filter(taskHasNotes);
    // Every subtask that has its own note(s) — same idea as tasksWithNotes,
    // just one level down (see getTaskSubtasks/taskHasNotes, which work on
    // a subtask object exactly like a task one).
    const subtasksWithNotes = getNodeTasks(node).flatMap((t) =>
      getTaskSubtasks(t).filter(taskHasNotes).map((s) => ({ t, s }))
    );
    const affirmationWins = nodeAffirmationWins(node);
    const taskProg = nodeTaskProgress(node);

    const nodeImages = getNodeImages(node);
    const nodeImageIds = getNodeImageIds(node);
    const timePlayed = getNodeTimePlayed(node);
    const brainstormPts = brainstormPoints(node);
    // Note, link, affirmation-completion, and time-played markers all
    // render inline as cells of this same strip, right alongside the
    // photo thumbnails, instead of floating outside the node — so every
    // attachment/status indicator for a node lives in one place, all at
    // the same cell size. Only the task-progress bar stays separate,
    // since it's a full-width row rather than a small cell.
    const stripIconCount = stripBucketCount(nodeNotes.length) + stripBucketCount(nodeUrls.length) + tasksWithNotes.length + subtasksWithNotes.length + (affirmationWins ? 1 : 0) + (timePlayed ? 1 : 0) + (brainstormPts > 0 ? 1 : 0);
    if ((stripIconCount || nodeImages.length) && node.id !== state.editingId) {
      const strip = document.createElement("span");
      // A handful of items deserve bigger cells than a full grid of them
      // would — "large" only kicks in when everything still fits in one
      // row (under the 5-column cap). Past STRIP_OVERFLOW_CAP photos,
      // collapse to a single cover thumbnail + count badge (see the loop
      // below) rather than one tile per photo, so a node with many photos
      // stays compact. Notes and links get the exact same treatment
      // further down (see notesOverflow/urlsOverflow below).
      const overflow = nodeImages.length > STRIP_OVERFLOW_CAP;
      const shownCount = overflow ? 1 : nodeImages.length;
      const itemCount = stripIconCount + shownCount;
      const large = itemCount <= 10;
      strip.className = "node-photo-strip" + (large ? " large" : "");
      strip.addEventListener("mousedown", (e) => { e.stopPropagation(); });
      strip.addEventListener("pointerdown", (e) => { e.stopPropagation(); });
      if (nodeImages.length) {
        // Dragging the strip's own background (not a specific icon/thumb,
        // which each have their own drag handlers) moves every photo at
        // once — matches dragging the old standalone photo strip.
        strip.title = "Drag onto another node to move the photos there (hold Alt to copy)";
        strip.draggable = true;
        strip.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "photos"));
        strip.addEventListener("dragend", endMarkerDrag);
      }
      // Pin the strip's actual width in JS to exactly what fits `cols`
      // cells per row (same formula computeNodeBox uses to reserve room
      // in the node box), instead of trusting the CSS max-width to land
      // on the same number — a few px of drift between the two would
      // make the browser wrap to an extra row the box never made room
      // for, pushing cells outside the frame.
      const thumbPx = large ? 18 : 13.5;
      const gapPx = 3;
      const cols = Math.min(itemCount, 5);
      strip.style.width = (cols * thumbPx + (cols - 1) * gapPx) + "px";

      // Shared markup for the note icon — same SVG whether it's one of a
      // node's own notes, a task's note, or (once collapsed) the single
      // stand-in icon for an overflowed pile of notes.
      const NODE_NOTE_ICON_SVG = '<svg viewBox="0 0 24 24"><rect x="2.3" y="6.3" width="15.4" height="15.4" rx="1" fill="#E08A2E" stroke="#000" stroke-width="1.3" stroke-linejoin="round"/><path d="M6.3 4.3a1 1 0 011-1h12a1 1 0 011 1v12.9l-4.3 4.3H7.3a1 1 0 01-1-1z" fill="#F6E266" stroke="#000" stroke-width="1.3" stroke-linejoin="round" stroke-linecap="round"/><path d="M20.3 17.2l-4.3 4.3v-3a1.3 1.3 0 011.3-1.3z" fill="#F0C24E" stroke="#000" stroke-width="1.3" stroke-linejoin="round"/><line x1="9" y1="8.2" x2="18" y2="8.2" stroke="#000" stroke-width="1.15" stroke-linecap="round"/><line x1="9" y1="11.1" x2="18" y2="11.1" stroke="#000" stroke-width="1.15" stroke-linecap="round"/><line x1="9" y1="14" x2="14.5" y2="14" stroke="#000" stroke-width="1.15" stroke-linecap="round"/><path d="M14.4 4.6l3.5-3.5" stroke="#000" stroke-width="1.3" stroke-linecap="round"/><circle cx="19" cy="1.9" r="1.5" fill="#DC7A93" stroke="#000" stroke-width="1"/></svg>';

      // DRC note marker — the exact notebook+pencil icon the user
      // supplied, embedded as a base64 PNG data URI (background flood-
      // filled to transparent, palette-quantized to keep this constant
      // small) so a "Daily Report Card" note reads as visibly different
      // from a regular note at a glance on the node itself (see the
      // isDRCNote branch below).

      // Brainstorm marker icon — Lucide's "brain" glyph, drawn with
      // currentColor like the affirmation checkmark so its purple tint
      // comes purely from CSS (.node-brainstorm-marker) rather than
      // being baked into the SVG.
      const NODE_BRAINSTORM_ICON_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 18V5"/><path d="M15 13a4.17 4.17 0 0 1-3-4 4.17 4.17 0 0 1-3 4"/><path d="M12 5A3 3 0 1 1 17.598 6.5"/><path d="M12 5A3 3 0 1 0 6.402 6.5"/><path d="M17.997 5.125a4 4 0 0 1 2.526 5.77"/><path d="M18 18a4 4 0 0 0 2-7.464"/><path d="M19.967 17.483A4 4 0 1 1 12 18a4 4 0 1 1-7.967-.517"/><path d="M6 18a4 4 0 0 1-2-7.464"/><path d="M6.003 5.125a4 4 0 0 0-2.526 5.77"/></svg>';

      // One icon per note (instead of a single icon plus a count badge),
      // same cell size/box as a photo thumbnail — each is independently
      // clickable/draggable, so a node with several notes reads at a
      // glance as "several notes" without needing to decode a number.
      // Past STRIP_OVERFLOW_CAP notes, same collapse-to-one-icon treatment
      // as photos: a single note icon carrying a count badge stands in
      // for the lot, and click/right-click both open the full list
      // (openNoteManageMenu) instead of one specific note.
      const notesOverflow = nodeNotes.length > STRIP_OVERFLOW_CAP;
      (notesOverflow ? nodeNotes.slice(0, 1) : nodeNotes).forEach((n, i) => {
        const noteIcon = document.createElement("span");
        noteIcon.className = "node-photo-thumb node-note-marker" + (isDRCNote(n) ? " node-drc-marker" : "");
        noteIcon.innerHTML = isDRCNote(n) ? NODE_DRC_ICON_IMG : (isPlanNote(n) ? NODE_PLAN_ICON_IMG : NODE_NOTE_ICON_SVG);
        noteIcon.draggable = true;
        noteIcon.addEventListener("dragend", endMarkerDrag);
        if (notesOverflow) {
          noteIcon.title = `${nodeNotes.length} notes — click to view the list, or drag to move them all onto another node (hold Alt to copy)`;
          noteIcon.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "notes"));
          noteIcon.addEventListener("click", (e) => { e.stopPropagation(); openNoteManageMenu(node.id, e.clientX, e.clientY); });
          const badge = document.createElement("span");
          badge.className = "node-marker-count";
          badge.textContent = String(nodeNotes.length);
          noteIcon.appendChild(badge);
        } else {
          // DRC notes get a status-aware tooltip (filled-in or not)
          // instead of the plain content preview, so hovering tells you
          // at a glance whether today's report still needs filling out.
          noteIcon.title = isDRCNote(n)
            ? (drcNoteIsFilled(n) ? "DRC — filled in" : "DRC — not filled in yet")
            : notePreviewText(n);
          noteIcon.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "note-single", { noteIndex: i }));
          noteIcon.addEventListener("click", (e) => {
            e.stopPropagation();
            openNoteModal(node.id, i);
          });
        }
        noteIcon.addEventListener("contextmenu", (e) => {
          e.preventDefault();
          e.stopPropagation();
          openNoteManageMenu(node.id, e.clientX, e.clientY);
        });
        strip.appendChild(noteIcon);
      });

      // Same note icon again, one per task that has notes on it — click
      // opens that task's own note editor directly (the exact same rich
      // editor as above, just scoped to the task; see openNoteModal).
      // Not draggable: unlike a node's own notes, a task's notes stay
      // with the task, not the node, so they don't make sense to drag
      // onto another node on their own.
      tasksWithNotes.forEach((t) => {
        const taskNoteIcon = document.createElement("span");
        // A task's note counts as a DRC note by the same rule as a
        // node's own notes — title exactly "DRC" (see isDRCNote) — so it
        // gets the same clipboard icon here too, not just at the node
        // level.
        const firstTaskNote = getTaskNotes(t)[0];
        const taskNoteIsDRC = isDRCNote(firstTaskNote);
        taskNoteIcon.className = "node-photo-thumb node-note-marker node-task-note-marker" + (taskNoteIsDRC ? " node-drc-marker" : "");
        taskNoteIcon.innerHTML = taskNoteIsDRC ? NODE_DRC_ICON_IMG : (isPlanNoteFor(firstTaskNote, t) ? NODE_PLAN_ICON_IMG : NODE_NOTE_ICON_SVG);
        // A task's own name already works as that note's title, so unlike
        // a node's or cell's own notes (notePreviewText), this never falls
        // back to a body-text preview — only the note's own separate
        // title, if it happens to have one of its own distinct from the
        // task name, is ever appended. A DRC note gets the same
        // filled-in-or-not status line the node-level DRC icon uses,
        // instead of that title suffix.
        if (taskNoteIsDRC) {
          const status = drcNoteIsFilled(firstTaskNote) ? "filled in" : "not filled in yet";
          taskNoteIcon.title = `Task "${t.text || "(untitled task)"}" — DRC, ${status}`;
        } else {
          const noteTitle = (firstTaskNote.title || "").trim();
          const titleSuffix = noteTitle ? ` — ${noteTitle.length > 40 ? noteTitle.slice(0, 39) + "…" : noteTitle}` : "";
          taskNoteIcon.title = `Task "${t.text || "(untitled task)"}"${titleSuffix}`;
        }
        taskNoteIcon.addEventListener("click", (e) => {
          e.stopPropagation();
          openNoteModal(node.id, undefined, null, t.id);
        });
        taskNoteIcon.addEventListener("contextmenu", (e) => {
          e.preventDefault();
          e.stopPropagation();
          openTasksModal(node.id);
        });
        strip.appendChild(taskNoteIcon);
      });

      // Same again, one per subtask that has its own note(s) — a subtask
      // named "DRC" shares the node's single DRC note instead (see the
      // redirect in openNoteModal), so it never shows up here on its own;
      // it already reads on the node as part of the DRC note above.
      subtasksWithNotes.forEach(({ t, s }) => {
        const subtaskNoteIcon = document.createElement("span");
        const firstSubtaskNote = getTaskNotes(s)[0];
        const subtaskNoteIsDRC = isDRCNote(firstSubtaskNote);
        subtaskNoteIcon.className = "node-photo-thumb node-note-marker node-subtask-note-marker" + (subtaskNoteIsDRC ? " node-drc-marker" : "");
        subtaskNoteIcon.innerHTML = subtaskNoteIsDRC ? NODE_DRC_ICON_IMG : (isPlanNoteFor(firstSubtaskNote, s) ? NODE_PLAN_ICON_IMG : NODE_NOTE_ICON_SVG);
        if (subtaskNoteIsDRC) {
          const status = drcNoteIsFilled(firstSubtaskNote) ? "filled in" : "not filled in yet";
          subtaskNoteIcon.title = `Subtask "${s.text || "(untitled subtask)"}" (in "${t.text || "(untitled task)"}") — DRC, ${status}`;
        } else {
          const noteTitle = (firstSubtaskNote.title || "").trim();
          const titleSuffix = noteTitle ? ` — ${noteTitle.length > 40 ? noteTitle.slice(0, 39) + "…" : noteTitle}` : "";
          subtaskNoteIcon.title = `Subtask "${s.text || "(untitled subtask)"}" (in "${t.text || "(untitled task)"}")${titleSuffix}`;
        }
        subtaskNoteIcon.addEventListener("click", (e) => {
          e.stopPropagation();
          openNoteModal(node.id, undefined, null, t.id, undefined, false, s.id);
        });
        subtaskNoteIcon.addEventListener("contextmenu", (e) => {
          e.preventDefault();
          e.stopPropagation();
          openTasksModal(node.id);
        });
        strip.appendChild(subtaskNoteIcon);
      });

      // One icon per link (instead of a single icon plus a count/chooser
      // menu), same treatment as the per-note icons above — each link is
      // independently visible, clickable, draggable, and editable, so a
      // node with several links reads at a glance without a submenu. Past
      // STRIP_OVERFLOW_CAP links, collapses the same way notes/photos do:
      // one representative link icon with a count badge, opening the full
      // list (openLinksManageMenu) on click or right-click.
      const urlsOverflow = nodeUrls.length > STRIP_OVERFLOW_CAP;
      (urlsOverflow ? nodeUrls.slice(0, 1) : nodeUrls).forEach((u, i) => {
        const urlIcon = document.createElement("span");
        urlIcon.className = "node-photo-thumb node-url-marker";
        urlIcon.draggable = true;
        urlIcon.addEventListener("dragend", endMarkerDrag);
        if (urlsOverflow) {
          urlIcon.innerHTML = LINK_ICON_SVGS.link;
          urlIcon.title = `${nodeUrls.length} links — click to view the list, or drag to move them all onto another node (hold Alt to copy)`;
          urlIcon.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "urls"));
          urlIcon.addEventListener("click", (e) => { e.stopPropagation(); openLinksManageMenu(node.id, e.clientX, e.clientY); });
          const badge = document.createElement("span");
          badge.className = "node-marker-count";
          badge.textContent = String(nodeUrls.length);
          urlIcon.appendChild(badge);
        } else {
          urlIcon.innerHTML = linkIconFor(u);
          const linkTitle = getLinkTitle(node, u);
          urlIcon.title = linkTitle || u;
          attachLinkCommentTooltip(urlIcon, u, () => getLinkComment(findNode(node.id) || node, u), () => getLinkTitle(findNode(node.id) || node, u));
          urlIcon.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "url-single", { urlIndex: i }));
          urlIcon.addEventListener("click", (e) => {
            e.stopPropagation();
            openLinkSmart(u, {
              videoKey: `${node.id}|${u}`,
              get: () => getLinkComment(findNode(node.id) || node, u),
              set: (v) => setLinkComment(findNode(node.id) || node, u, v),
              getFavorite: () => getLinkFavorite(findNode(node.id) || node, u),
              setFavorite: (v) => setLinkFavorite(findNode(node.id) || node, u, v),
              getPhotos: () => getLinkPhotos(findNode(node.id) || node, u),
              addPhoto: (dataUrl) => addLinkPhoto(findNode(node.id) || node, u, dataUrl),
              removePhoto: (id) => removeLinkPhoto(findNode(node.id) || node, u, id),
            });
          });
        }
        urlIcon.addEventListener("contextmenu", (e) => {
          e.preventDefault();
          e.stopPropagation();
          if (urlsOverflow) openLinksManageMenu(node.id, e.clientX, e.clientY);
          else openUrlSingleManageMenu(node.id, i, e.clientX, e.clientY);
        });
        strip.appendChild(urlIcon);
      });

      if (affirmationWins) {
        // One checkmark cell with an incrementing count badge once there's
        // more than one round completed — a single completed round is
        // just the checkmark, no redundant "1" — rather than a stack of
        // icons per win. This is the one place in the strip that still
        // uses a numeric badge at all (games track a running score, not
        // a count of attached items, so it isn't in the same category as
        // the links/notes/photos "how many things are here" badges).
        // Click it to jump straight into a new round.
        const affIcon = document.createElement("span");
        affIcon.className = "node-photo-thumb node-affirmation-marker";
        affIcon.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M4.5 12.5l5 5L19.5 7"/></svg>';
        affIcon.title = `Affirmation game — ${affirmationWins} round${affirmationWins === 1 ? "" : "s"} completed. Click to play again.`;
        affIcon.addEventListener("click", (e) => {
          e.stopPropagation();
          openAffirmationGame(node.id);
        });
        if (affirmationWins > 1) {
          const affCount = document.createElement("span");
          affCount.className = "node-marker-count";
          affCount.textContent = String(affirmationWins);
          affIcon.appendChild(affCount);
        }
        strip.appendChild(affIcon);
      }

      for (let i = 0; i < shownCount; i++) {
        const thumb = document.createElement("span");
        thumb.className = "node-photo-thumb";
        // Use the small pre-cropped stand-in (see getMarkerThumb) instead
        // of painting the full-resolution photo into this tiny box — keeps
        // the canvas cheap to composite no matter how many/how large the
        // attached photos are. Falls back to the full image for the one
        // frame before its thumbnail has been generated.
        const fullSrc = nodeImages[i];
        const cachedThumb = getMarkerThumb(fullSrc, () => {
          const liveThumb = nodesLayer.querySelector(`.node[data-id="${node.id}"] .node-photo-thumb[data-src-index="${i}"]`);
          if (liveThumb) liveThumb.style.backgroundImage = `url("${nodeThumbCache.get(fullSrc)}")`;
        });
        thumb.dataset.srcIndex = String(i);
        thumb.style.backgroundImage = `url("${cachedThumb || fullSrc}")`;
        thumb.draggable = true;
        thumb.addEventListener("dragend", endMarkerDrag);
        thumb.addEventListener("click", (e) => {
          e.stopPropagation();
          openPhotoModal(node.id, i);
        });
        if (overflow) {
          // The one cell stands in for the whole collection — a count
          // badge (photos are the one "how many things" marker that
          // still uses a number, since a wall of tiny individual
          // thumbnails past a handful gets unreadable) instead of a wall
          // of individual thumbnails, and dragging/clicking it acts on
          // all the photos together rather than just this one.
          thumb.title = `${nodeImages.length} photos — click to view, or drag to move them all onto another node (hold Alt to copy)`;
          thumb.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "photos"));
          const badge = document.createElement("span");
          badge.className = "node-marker-count";
          badge.textContent = String(nodeImages.length);
          thumb.appendChild(badge);
        } else {
          thumb.title = "Click to view photo — drag onto another node to move it there (hold Alt to copy)";
          thumb.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "photo", { photoIndex: i }));
          // Small dot marking that this specific photo has a comment
          // attached (see photoComments / photo-modal-comment-row) — only
          // meaningful here, one thumb per actual photo; the single
          // overflow cover thumbnail above stands for the whole pile and
          // already carries its own count badge, so it skips this.
          const comment = getPhotoComment(node, nodeImageIds[i]);
          if (comment) {
            thumb.classList.add("node-photo-thumb-has-comment");
            thumb.title += " — has a comment";
          }
        }
        strip.appendChild(thumb);
      }

      if (timePlayed) {
        // Same small cell size/box as a photo thumbnail (see below) rather
        // than its own wider pill — just the total's text, no clock icon,
        // with the cell's own border traced into a little alarm-clock
        // silhouette (round face + two angled "ears" up top) so it still
        // reads as a timer at a glance without needing an icon inside it.
        const tbadge = document.createElement("span");
        tbadge.className = "node-photo-thumb node-timer-badge";
        tbadge.title = `${formatTimePlayed(timePlayed)} logged — click to add more`;
        tbadge.addEventListener("mousedown", (e) => { e.stopPropagation(); });
        tbadge.addEventListener("pointerdown", (e) => { e.stopPropagation(); });
        tbadge.addEventListener("click", (e) => { e.stopPropagation(); openTimerModal(node.id); });
        const tlabel = document.createElement("span");
        tlabel.textContent = formatTimePlayed(timePlayed);
        tbadge.appendChild(tlabel);
        strip.appendChild(tbadge);
      }

      if (brainstormPts > 0) {
        // Same small cell box as the note/link/timer markers above — a
        // brain glyph with a purple tint, plus a count badge holding
        // the point total once it's more than 1 (mirrors the affirmation
        // checkmark's own count badge). Click jumps straight into the
        // scratchpad to keep writing.
        const bIcon = document.createElement("span");
        bIcon.className = "node-photo-thumb node-brainstorm-marker";
        bIcon.textContent = "🧠";
        bIcon.title = `Brainstorm — ${brainstormPts} point${brainstormPts === 1 ? "" : "s"} (${brainstormLineCount(node)} lines). Click to keep writing.`;
        bIcon.addEventListener("click", (e) => {
          e.stopPropagation();
          openBrainstormModal(node.id);
        });
        if (brainstormPts > 1) {
          const bCount = document.createElement("span");
          bCount.className = "node-marker-count";
          bCount.textContent = String(brainstormPts);
          bIcon.appendChild(bCount);
        }
        strip.appendChild(bIcon);
      }

      div.appendChild(strip);
    }

    if (taskProg.total && node.id !== state.editingId) {
      const row = document.createElement("span");
      row.className = "node-progress-row";
      row.addEventListener("mousedown", (e) => { e.stopPropagation(); });
      row.addEventListener("pointerdown", (e) => { e.stopPropagation(); });
      row.addEventListener("click", (e) => { e.stopPropagation(); openTasksModal(node.id); });
      row.title = `${taskProg.done} of ${taskProg.total} tasks done — drag onto another node to move the tasks there (hold Alt to copy)`;
      row.draggable = true;
      row.addEventListener("dragstart", (e) => startMarkerDrag(e, node, "tasks"));
      row.addEventListener("dragend", endMarkerDrag);

      const track = document.createElement("span");
      track.className = "node-progress-track";
      const fill = document.createElement("span");
      fill.className = "node-progress-fill" + (taskProg.pct >= 1 ? " done" : "");
      fill.style.width = Math.round(taskProg.pct * 100) + "%";
      track.appendChild(fill);

      const pctLabel = document.createElement("span");
      pctLabel.className = "node-progress-pct" + (taskProg.pct >= 1 ? " done" : "");
      pctLabel.textContent = String(taskProg.done);

      // On a level-1 node (the solid-filled branch pill) the bar sits on
      // top of an arbitrary branch color, so it can't rely on a fixed
      // teal/gold or a same-hue tint — either washes out depending on the
      // branch color. Instead the track is a neutral dark groove and the
      // fill a bright, near-opaque bar, which reads clearly as "progress"
      // against any branch color the same way a scrubber reads against
      // colorful album art. The % label gets its own small dark chip
      // behind it (rather than colored text sitting directly on the pill)
      // so it stays legible no matter how light or saturated the branch
      // color is.
      if (depth === 1 && color) {
        track.style.background = "rgba(0,0,0,0.32)";
        track.style.boxShadow = "inset 0 1px 3px rgba(0,0,0,0.45)";
        fill.style.background = taskProg.pct >= 1
          ? "linear-gradient(90deg, #ffe8ab, #ffc98a)"
          : "rgba(255,255,255,0.92)";
        fill.style.boxShadow = "0 0 5px rgba(255,255,255,0.35)";
        pctLabel.classList.add("node-progress-pct-chip");
      }

      row.appendChild(track);
      row.appendChild(pctLabel);
      div.appendChild(row);
    }

    function beginNodeDrag(e) {
      e.stopPropagation();
      if (!requireSignIn()) return;
      if (node.id === state.editingId) return;
      // A second (or third) finger landing on the node — e.g. the start of
      // a pinch that happens to begin over a node — shouldn't kick off a
      // node drag; only the first touch/click does.
      if (e.pointerType && activePointers.size > 1) return;
      dragCandidate = {
        id: node.id,
        pointerId: e.pointerId,
        startClientX: e.clientX,
        startClientY: e.clientY,
        startOx: node.ox || 0,
        startOy: node.oy || 0,
        // Absolute (layout-space) Y at the moment the drag starts, tracked
        // independently of node._y so it stays correct even after a sibling
        // reorder shifts the node into a new slot mid-drag.
        startAbsY: node._y + (node.oy || 0),
        moved: false,
        dropTargetId: null,
        // How much of the current drag delta is already "baked into" the
        // dragged nodes' left/top (as opposed to sitting in a live CSS
        // transform — see the mousemove handler). Starts at zero since
        // left/top haven't moved yet.
        bakedDx: 0,
        bakedDy: 0,
        // Snapshot every descendant's current offset so the whole branch can
        // be translated by the same delta as the node being dragged.
        descendants: collectDescendants(node).map(c => ({
          id: c.id,
          startOx: c.ox || 0,
          startOy: c.oy || 0
        }))
      };
    }
    div.addEventListener("mousedown", (e) => {
      if (e.button !== 0) return;
      beginNodeDrag(e);
    });
    div.addEventListener("pointerdown", (e) => {
      // Mouse is already handled by the mousedown listener above. Pen
      // behaves like mouse — a drag can start right away. Touch instead
      // only *arms* here; the actual drag only begins once the hold timer
      // in this arm fires (see TOUCH_DRAG_HOLD_MS above), so a quick swipe
      // starting on a node pans the canvas instead of yanking the node.
      if (e.pointerType === "mouse") return;
      if (e.pointerType !== "touch") { beginNodeDrag(e); return; }
      if (node.id === state.editingId) return;
      if (activePointers.size > 1) return;
      clearTouchDragArm();
      const pointerId = e.pointerId, clientX = e.clientX, clientY = e.clientY;
      touchDragArm = {
        pointerId,
        startClientX: clientX,
        startClientY: clientY,
        timer: setTimeout(() => {
          if (!touchDragArm || touchDragArm.pointerId !== pointerId) return;
          touchDragArm = null;
          beginNodeDrag({ pointerType: "touch", pointerId, clientX, clientY, stopPropagation() {} });
        }, TOUCH_DRAG_HOLD_MS)
      };
    });
    div.addEventListener("click", (e) => {
      e.stopPropagation();
      if (suppressNextNodeClick) { suppressNextNodeClick = false; return; }
      if (state.linkFromId) { completeLinkTo(node.id); return; }
      selectNode(node.id);
    });
    div.addEventListener("dblclick", (e) => { e.stopPropagation(); startEdit(node.id); });
    div.addEventListener("contextmenu", (e) => { e.preventDefault(); e.stopPropagation(); selectNode(node.id); openContextMenu(e.clientX, e.clientY, node); });

    // Accept a task-ring / progress-bar / photo-strip drag started on some
    // other node — or a photo/note/link/task dragged up from one of THIS
    // node's own cells (sourceR/sourceC set), which is a legitimate move
    // even though sourceNodeId matches this node's id. Only a whole-node
    // marker (no source cell) dropped back on its own node is a no-op —
    // that case is excluded below.
    div.addEventListener("dragover", (e) => {
      if (!markerDragState) return;
      if (markerDragState.sourceNodeId === node.id && markerDragState.sourceR == null && markerDragState.sourceC == null) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = e.altKey ? "copy" : "move";
      div.classList.add("marker-drop-target");
    });
    div.addEventListener("dragleave", (e) => {
      if (e.relatedTarget && div.contains(e.relatedTarget)) return;
      div.classList.remove("marker-drop-target");
    });
    div.addEventListener("drop", (e) => {
      if (!markerDragState) return;
      if (markerDragState.sourceNodeId === node.id && markerDragState.sourceR == null && markerDragState.sourceC == null) return;
      e.preventDefault();
      e.stopPropagation();
      div.classList.remove("marker-drop-target");
      completeMarkerDrop(node.id, e.altKey);
    });

    div.addEventListener("blur", () => { if (state.editingId === node.id) commitEdit(div); });
    div.addEventListener("keydown", (e) => nodeKeydown(e, node, div));

    nodesLayer.appendChild(div);

    if (node.id === state.editingId) {
      // Focus synchronously, not via requestAnimationFrame — the div is
      // already attached to the DOM (appendChild just above), and on
      // touch devices a deferred focus() falls outside the tap's "user
      // activation" window, so the on-screen keyboard doesn't reopen for
      // the new node (e.g. right after tapping the add-child/add-sibling
      // buttons) even though focus visibly lands there.
      div.focus();
      placeCaretAtEnd(div);
    }
  }

  // Reads a contenteditable node's text back out while preserving line
  // breaks the browser may represent as <br> or nested <div>s.
  function getEditableText(div) {
    let text = "";
    div.childNodes.forEach((node) => {
      if (node.nodeType === 3) {
        text += node.textContent;
      } else if (node.nodeName === "BR") {
        text += "\n";
      } else if (node.nodeType === 1 && (node.classList.contains("node-collapse") || node.classList.contains("node-badge") || node.classList.contains("node-photo-strip") || node.classList.contains("node-progress-row"))) {
        // These are UI overlays (collapse toggle, child-count badge, note
        // icon, photo thumbnail) rendered inside the node box, not part of
        // the typed text — skip them or their glyphs (e.g. "–") get
        // appended to the text.
      } else if (node.nodeName === "DIV" || node.nodeName === "P") {
        if (text.length && !text.endsWith("\n")) text += "\n";
        text += node.textContent;
      } else {
        text += node.textContent;
      }
    });
    return text.trim();
  }

  // Grows (or shrinks) the node box live as the person types, keeping it
  // centered on its layout position, so text never overflows its box.
  function autosizeEditingBox(div, node) {
    const text = getEditableText(div);
    const box = computeNodeBox(Object.assign({}, node, { text }));
    node._w = box.w;
    node._h = box.h;
    const cy = state.originY + node._y + (node.oy || 0);
    div.style.width = box.w + "px";
    div.style.height = box.h + "px";
    div.style.left = (state.originX + nodeLeftX(node)) + "px";
    div.style.top = (cy - box.h / 2) + "px";
    refreshConnectorsFor(node);
  }

  function countAll(node) {
    let n = 0;
    (function walk(x) { for (const c of x.children || []) { n++; walk(c); } })(node);
    return n;
  }

  function placeCaretAtEnd(el) {
    const range = document.createRange();
    range.selectNodeContents(el);
    range.collapse(false);
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
  }

  // When the caret is moved by hand (via a Range/Selection API call rather
  // than an actual key/mouse event the browser itself is handling), the
  // browser's own "keep the caret on screen" auto-scroll never kicks in —
  // that only fires for caret movement it drove itself. noteHandleEnter
  // below builds new lines and repositions the caret this way, which is
  // why hitting Enter at the bottom of a long note used to leave the new
  // line (and the caret on it) scrolled out of view. Call this right after
  // any such programmatic caret move to bring it back into view by hand.
  function scrollCaretIntoView(el) {
    if (el && el.scrollIntoView) el.scrollIntoView({ block: "nearest" });
  }

  /* ---------------- selection / editing ---------------- */

  function findNode(id, node = state.current && state.current.root) {
    if (!node) return null;
    if (node.id === id) return node;
    for (const c of node.children || []) {
      const r = findNode(id, c);
      if (r) return r;
    }
    return null;
  }

  function findParent(id, node = state.current && state.current.root) {
    if (!node) return null;
    for (const c of node.children || []) {
      if (c.id === id) return node;
      const r = findParent(id, c);
      if (r) return r;
    }
    return null;
  }

  // Every node in the current map, regardless of collapsed state — unlike
  // the layout/render walks (which skip collapsed branches because they
  // don't need to be drawn), callers like the photo-tag browser need to
  // find tagged photos even when they're tucked inside a collapsed branch.
  function collectAllNodesFlat(node = state.current && state.current.root, out = []) {
    if (!node) return out;
    out.push(node);
    (node.children || []).forEach(c => collectAllNodesFlat(c, out));
    return out;
  }

  // Un-collapses every ancestor of a node so it's actually visible/findable
  // in the DOM before we try to select or center the camera on it.
  function expandAncestorsOf(id) {
    let cur = findParent(id);
    while (cur) {
      cur.collapsed = false;
      cur = findParent(cur.id);
    }
  }

  // Groups every photo tag used anywhere in the current map by tag text
  // (case-insensitively, keeping whichever casing was typed first), each
  // with the list of {nodeId, id} photos carrying that tag. Powers the
  // "Photo tags" browser.
  function collectPhotoTagGroups() {
    const groups = new Map();
    let cleaned = false;
    collectAllNodesFlat().forEach((node) => {
      if (!node.photoTags) return;
      const liveIds = new Set(getNodeImageIds(node));
      Object.keys(node.photoTags).forEach((id) => {
        // A tag only ever means anything while the photo it's keyed by is
        // still actually attached to THIS node (see setPhotoTags) — but a
        // photo dragged onto a different node (see completeMarkerDrop)
        // used to leave its old tag entry behind here, pointing at a
        // photo this node no longer has. That showed up in the tag
        // browser as a permanently broken, unclickable thumbnail (open
        // its click handler no-ops once the id isn't found in the node's
        // own images). Clean up any such leftover the moment it's
        // noticed instead of surfacing it.
        if (!liveIds.has(id)) {
          delete node.photoTags[id];
          cleaned = true;
          return;
        }
        (node.photoTags[id] || []).forEach((tag) => {
          const key = tag.toLowerCase();
          if (!groups.has(key)) groups.set(key, { label: tag, items: [] });
          groups.get(key).items.push({ nodeId: node.id, id });
        });
      });
    });
    if (cleaned) persist();
    // Most-tagged first (the tag browser's whole point is surfacing your
    // biggest photo collections at a glance); ties broken alphabetically
    // so the order stays stable rather than shuffling on every render.
    return Array.from(groups.values()).sort((a, b) => b.items.length - a.items.length || a.label.localeCompare(b.label));
  }

  // Selects a node, expanding any collapsed ancestors so it renders, then
  // pans/centers the camera on it.
  function focusNodeInCanvas(nodeId) {
    const node = findNode(nodeId);
    if (!node) return;
    expandAncestorsOf(nodeId);
    state.selectedId = nodeId;
    state.editingId = null;
    renderAll();
    requestAnimationFrame(() => {
      const div = nodesLayer.querySelector(`.node[data-id="${nodeId}"]`);
      if (div) {
        const cx = div.offsetLeft + div.offsetWidth / 2;
        const cy = div.offsetTop + div.offsetHeight / 2;
        const vw = viewportEl.clientWidth;
        const vh = viewportEl.clientHeight;
        state.tx = vw / 2 - cx * state.scale;
        state.ty = vh / 2 - cy * state.scale;
        applyTransform();
        persistViewOnly();
      }
    });
  }

  // Selects a node, pans/centers the camera on it, and optionally opens the
  // photo modal to a specific photo on that node once the camera's
  // settled — used when jumping to a photo from the tag browser. When
  // `tagGroup` is passed, the main photo modal's prev/next will continue
  // stepping through every photo sharing that tag (across nodes) instead
  // of just this node's own photos.
  function jumpToNode(nodeId, focusId, tagGroup) {
    const node = findNode(nodeId);
    if (!node) return;
    focusNodeInCanvas(nodeId);
    requestAnimationFrame(() => {
      if (focusId) {
        const idx = getNodeImageIds(node).indexOf(focusId);
        if (idx >= 0) openPhotoModal(nodeId, idx, tagGroup);
      }
    });
  }

  // Flat list of every descendant under `node` (not including node itself),
  // used to drag a whole branch as one unit and to reset it after a reparent.
  function collectDescendants(node) {
    const list = [];
    (function walk(n) {
      (n.children || []).forEach(c => { list.push(c); walk(c); });
    })(node);
    return list;
  }

  // True if `id` belongs to node's own subtree (itself or any descendant) —
  // used to stop a branch from being dropped onto itself or its own child.
  function isWithinSubtree(node, id) {
    if (node.id === id) return true;
    for (const c of node.children || []) {
      if (isWithinSubtree(c, id)) return true;
    }
    return false;
  }

  // Moves a node (and everything under it) to become the last child of a
  // different node — this is what a completed drag-to-reparent does.
  function reparentNode(nodeId, newParentId) {
    const node = findNode(nodeId);
    const newParent = findNode(newParentId);
    if (!node || !newParent) return;
    const oldParent = findParent(nodeId);
    if (!oldParent) return; // the central node has no parent — can't be moved
    const idx = oldParent.children.findIndex(c => c.id === nodeId);
    if (idx === -1) return;
    oldParent.children.splice(idx, 1);
    newParent.children.push(node);
    newParent.collapsed = false;
    // Drop the manual nudge offset so the branch settles into its fresh
    // auto-layout spot under the new parent instead of an old, unrelated one.
    // Reset the whole subtree, not just the moved node, since it was dragged
    // (and dropped) as one unit.
    node.ox = 0;
    node.oy = 0;
    // Drop any explicit left/right override the node had picked up from a
    // drag under its old parent — under the new parent it should go back
    // to inheriting that branch's side until the user flips it again.
    node.side = null;
    // Same for an explicit above/below override from Timeline mode — it
    // only means anything for a direct child of the root, so it doesn't
    // carry over to a new (non-root) parent.
    node.vSide = null;
    // Same for the cached Timeline auto-balanced side (see layoutTimeline)
    // — it's scoped to whichever branch's left/right split it was computed
    // against, so it doesn't carry over to a new parent either.
    node._autoSide = null;
    // Same for a custom connector distance — a distance tailored to the
    // old parent isn't meaningful under a new one.
    node.xGap = null;
    // A node's own .color only ever means "this is a top-level branch and
    // this is its branch color" (set by assignBranchColors, or by the
    // "Branch color" swatch picker) — every other node just inherits
    // whichever branch it descends from (see branchColorFor), it never
    // has a real .color of its own. So if this node WAS a top-level
    // branch and is now being tucked under a different node, drop that
    // leftover color; left in place, it would keep outranking (via
    // `node.color || branchColorFor(...)`) the color of whatever branch
    // it's actually part of now, forever. Its own descendants can never
    // end up at depth 1 as a result of this move either (only `node`
    // itself, if dropped directly on the root, can) — clear any
    // color they're separately carrying from a past life too.
    if (newParent !== state.current.root) node.color = null;
    collectDescendants(node).forEach(d => { d.ox = 0; d.oy = 0; d._autoSide = null; d.color = null; });
    state.selectedId = node.id;
    renderAll();
  }

  // While dragging, checks whether the node has been pulled far enough past
  // an adjacent sibling (same parent) to swap places with it — repeated so a
  // fast drag can hop past more than one sibling in a single move. Returns
  // true if the sibling order actually changed, so the caller knows to
  // re-run layout. For most nodes this is a plain positional swap. For a
  // root-level branch in Mindmap layout, swapping past a sibling on the
  // *other* side of the map is treated as the user dragging that branch
  // across the center line: only the dragged node's side flips to follow
  // it — the neighbor it passed keeps whichever side it was already on, so
  // one drag never yanks an unrelated branch to the opposite side too.
  // Reorders a node among its siblings to match where it's currently being
  // dragged, vertically. This only ever touches array order (top-to-bottom
  // stacking) — it must NOT also decide the node's left/right side. Left
  // and right branches sit interleaved in the same array (not grouped), so
  // a purely vertical drag can easily swap past a sibling that happens to
  // be on the other side; flipping side on that alone was causing nodes to
  // jump to the opposite side from a plain up/down drag. Side is decided
  // separately, only from actual horizontal position, by
  // maybeFlipSideOnDrop() once the drag ends.
  function maybeReorderSiblings(node, targetAbsY) {
    const parent = findParent(node.id);
    if (!parent || !parent.children || parent.children.length < 2) return false;
    const siblings = parent.children;
    let idx = siblings.indexOf(node);
    if (idx === -1) return false;
    let changed = false;

    while (idx > 0 && targetAbsY < siblings[idx - 1]._y) {
      siblings[idx] = siblings[idx - 1];
      siblings[idx - 1] = node;
      idx--;
      changed = true;
    }
    while (idx < siblings.length - 1 && targetAbsY > siblings[idx + 1]._y) {
      siblings[idx] = siblings[idx + 1];
      siblings[idx + 1] = node;
      idx++;
      changed = true;
    }

    if (!changed) return false;
    layout(state.current.root);
    return true;
  }

  // Called once a drag finishes (mouseup), for any node at any depth in
  // Mindmap or Timeline layout: if the node ended up on the opposite side
  // of the center line from where it's currently drawn, give it an
  // explicit side override so it — and everything under it, via
  // place()/placeLocal() — flips to fan out the other way instead of
  // staying stuck following its parent branch's side. Returns true if a
  // flip happened, so the caller knows to snap the drag offset back to
  // zero and re-render.
  function maybeFlipSideOnDrop(node) {
    const layoutMode = (state.current && state.current.layout) || "mindmap";
    // "Righty mindmap" only ever fans one direction (right), so there's
    // no opposite side to flip to.
    if (layoutMode === "logic" || layoutMode === "righty") return false;
    // node._x is 0 for the root, and also for a Timeline branch's own node
    // (it sits directly on the spine) — neither has a side of its own to
    // flip; only their descendants do.
    if (!node._x) return false;
    // In Mindmap mode only a top-level branch (depth 1) can have its own
    // side — every deeper node just inherits its branch's direction (see
    // layoutMindmap's place()), so setting .side on a deeper node here
    // would have no visible effect. Block it rather than silently writing
    // a .side that layout ignores.
    if (layoutMode === "mindmap" && node._depth !== 1) return false;
    const finalWorldX = node._x + (node.ox || 0);
    if (finalWorldX === 0) return false;
    const curSide = node._x > 0 ? "right" : "left";
    const newSide = finalWorldX > 0 ? "right" : "left";
    if (newSide === curSide) return false;
    node.side = newSide;
    return true;
  }

  // Same idea, but live — called on every mousemove while a node is being
  // dragged, so its subtree flips direction the instant it crosses the
  // center line instead of waiting for the mouse to be released. Besides
  // setting the side, this has to keep the drag feeling continuous: the
  // dragged node must stay exactly under the cursor across the flip (its
  // own _x jumps when the side changes, so ox/startOx are re-anchored to
  // compensate), and every descendant is re-anchored to that SAME (ox, oy)
  // offset — not reset to zero — so the whole subtree keeps moving as one
  // rigid unit. That matters because each connector's on-screen length is
  // (clean gap) + (this node's ox − its parent's ox): as long as every
  // node in the subtree shares the identical ox/oy, that second term stays
  // zero and every connector's distance is exactly its clean gap,
  // unchanged by the flip — only the underlying clean layout (and so which
  // direction each hop fans) actually mirrors.
  function maybeFlipSideDuringDrag(node, dxLocal, dyLocal) {
    const layoutMode = (state.current && state.current.layout) || "mindmap";
    if (layoutMode === "logic" || layoutMode === "righty") return false;
    if (!node._x) return false;
    if (layoutMode === "mindmap" && node._depth !== 1) return false;
    const worldX = node._x + (node.ox || 0);
    const worldY = node._y + (node.oy || 0);
    if (worldX === 0) return false;
    const curSide = node._x > 0 ? "right" : "left";
    const newSide = worldX > 0 ? "right" : "left";
    if (newSide === curSide) return false;

    node.side = newSide;
    layout(state.current.root);

    node.ox = worldX - node._x;
    node.oy = worldY - node._y;
    dragCandidate.startOx = node.ox - dxLocal;
    // Vertical layout can shift too (e.g. a top-level branch moving
    // between the left/right lists re-centers both), so re-anchor the
    // reorder target the same way the horizontal one is re-anchored above.
    dragCandidate.startAbsY = worldY - dyLocal;

    dragCandidate.descendants.forEach(d => {
      d.startOx = node.ox - dxLocal;
      d.startOy = node.oy - dyLocal;
    });

    return true;
  }

  // Same idea as maybeFlipSideOnDrop, but for a Timeline branch's place
  // relative to the root along the vertical spine rather than a node's
  // side of a horizontal fan. Every top-level branch used to be locked
  // below the root, so there was nothing to flip; now dragging one up
  // past the root's own center gives it an explicit node.vSide =
  // "above" override (mirroring .side/"left"/"right"), sending it onto
  // the top half of the spine instead — everything else about it
  // (its own left/right-fanning children, its color, etc.) is untouched.
  // A null/missing vSide always means "below", the original default, so
  // maps saved before this feature keeps every branch exactly where it
  // was.
  function maybeFlipVSideOnDrop(node) {
    const layoutMode = (state.current && state.current.layout) || "mindmap";
    // Only a top-level branch sits directly on the spine; anything deeper
    // just fans left/right off its own branch and has no "above/below
    // the root" position of its own to flip.
    if (layoutMode !== "timeline" || node._depth !== 1) return false;
    const finalWorldY = node._y + (node.oy || 0);
    if (finalWorldY === 0) return false;
    const curVSide = node.vSide === "above" ? "above" : "below";
    const newVSide = finalWorldY < 0 ? "above" : "below";
    if (newVSide === curVSide) return false;
    node.vSide = newVSide === "above" ? "above" : null;
    return true;
  }

  // Live version of maybeFlipVSideOnDrop, called on every mousemove so a
  // branch crosses onto the other half of the spine the instant it's
  // dragged past the root, same continuous-drag treatment
  // maybeFlipSideDuringDrag gives a left/right flip: the node stays under
  // the cursor across the flip (oy/startAbsY re-anchored to compensate)
  // and every descendant rides along on that same offset so the whole
  // branch keeps moving as one rigid unit.
  function maybeFlipVSideDuringDrag(node, dxLocal, dyLocal) {
    const layoutMode = (state.current && state.current.layout) || "mindmap";
    if (layoutMode !== "timeline" || node._depth !== 1) return false;
    const worldX = node._x + (node.ox || 0);
    const worldY = node._y + (node.oy || 0);
    const curVSide = node.vSide === "above" ? "above" : "below";
    const newVSide = worldY < 0 ? "above" : "below";
    if (newVSide === curVSide) return false;

    node.vSide = newVSide === "above" ? "above" : null;
    layout(state.current.root);

    node.ox = worldX - node._x;
    node.oy = worldY - node._y;
    dragCandidate.startOx = node.ox - dxLocal;
    dragCandidate.startAbsY = worldY - dyLocal;

    dragCandidate.descendants.forEach(d => {
      d.startOx = node.ox - dxLocal;
      d.startOy = node.oy - dyLocal;
    });

    return true;
  }

  // While dragging a node, figure out whether the pointer is currently over
  // a different, droppable node, and keep the highlight in sync.
  function updateDropTarget(e, node) {
    let targetId = null;
    const el = document.elementFromPoint(e.clientX, e.clientY);
    const targetDiv = el && el.closest ? el.closest(".node[data-id]") : null;
    if (targetDiv) {
      const id = targetDiv.dataset.id;
      // Hovering over the node's OWN current parent isn't a meaningful
      // reparent (it's already there) — most importantly, that parent is
      // very often the root itself, and in Timeline mode a top-level
      // branch has to pass right over the root's box on its way to being
      // dragged above it. Without this guard, releasing the mouse there
      // was read as "drop onto root" (reparentNode), which silently
      // resets the branch's vSide/side/order — instead of the intended
      // above/below flip (see maybeFlipVSideOnDrop/maybeFlipSideOnDrop),
      // which only ever fires once no drop target is set.
      const curParent = findParent(node.id);
      const isOwnParent = curParent && curParent.id === id;
      if (id !== node.id && !isOwnParent && !isWithinSubtree(node, id)) targetId = id;
    }
    if (dragCandidate.dropTargetId && dragCandidate.dropTargetId !== targetId) {
      const prevDiv = nodesLayer.querySelector(`.node[data-id="${dragCandidate.dropTargetId}"]`);
      if (prevDiv) prevDiv.classList.remove("drop-target");
    }
    dragCandidate.dropTargetId = targetId;
    if (targetId) {
      const div = nodesLayer.querySelector(`.node[data-id="${targetId}"]`);
      if (div) div.classList.add("drop-target");
    }
  }

  // Toggles just the .selected class between two nodes' existing DOM
  // elements — used instead of a full renderAll() when a click only
  // changes which node is selected (see selectNode below). A full
  // renderAll() tears down and rebuilds every node's DOM from scratch,
  // which would reset other per-node DOM state on every single click.
  function updateSelectedClasses(prevId, id) {
    if (prevId) {
      const prevDiv = nodesLayer.querySelector(`.node[data-id="${prevId}"]`);
      if (prevDiv) prevDiv.classList.remove("selected");
    }
    if (id) {
      const div = nodesLayer.querySelector(`.node[data-id="${id}"]`);
      if (div) div.classList.add("selected");
    }
  }

  function selectNode(id, cellPos) {
    if (state.editingId === id) { state.selectedCell = cellPos || null; return; } // a click inside the box being edited is just caret placement, not a request to stop editing
    const wasEditing = !!state.editingId;
    commitEditIfActive({ render: false });
    const prevId = state.selectedId;
    state.selectedId = id;
    state.selectedCell = cellPos || null;
    if (wasEditing) {
      // Text/size may have just changed, which can shift the whole
      // layout — needs the real thing.
      renderAll();
      return;
    }
    updateSelectedClasses(prevId, id);
  }

  function startEdit(id) {
    if (!requireSignIn()) return;
    state.selectedId = id;
    state.editingId = id;
    renderAll();
  }

  // `render` can be set to false by a caller that is about to make further
  // state changes (e.g. creating and focusing a new node) and will do its
  // own single renderAll() afterward — see commitEditIfActive below for why
  // that matters on touch devices.
  function commitEdit(div, { render = true } = {}) {
    const id = div.dataset.id;
    const node = findNode(id);
    if (!node) return;
    const text = getEditableText(div);
    if (node.text !== text) {
      pushUndo();
      node.text = text;
      // The central/root node's text doubles as the map's title everywhere
      // else (sidebar list, title field) — keep them in sync.
      if (state.current && node.id === state.current.root.id) {
        state.current.title = text;
        titleInput.value = text;
        renderSidebar();
      }
    }
    state.editingId = null;
    if (render) renderAll();
    persist();
  }

  // Saves whatever is currently being typed before anything else (switching
  // maps, selecting another node, clicking empty canvas) is allowed to clear
  // state.editingId. Every place that ends editing should call this first —
  // otherwise the in-progress text is discarded instead of saved, which is
  // what was happening when clicking outside a node's box.
  //
  // Pass { render: false } when the caller is going to change more state
  // right after (e.g. fabTargetNode, before creating+focusing a new node)
  // and will call renderAll() itself once at the end. Doing two separate
  // renderAll() passes back-to-back — one here to exit the old node's edit,
  // one later to create and focus the new node — makes the whole sequence
  // take long enough that touch browsers stop treating the later focus()
  // as part of the original tap, so the on-screen keyboard doesn't reopen
  // even though focus visibly lands on the new node.
  function commitEditIfActive({ render = true } = {}) {
    if (!state.editingId) return;
    const div = nodesLayer.querySelector(`.node[data-id="${state.editingId}"]`);
    if (div) commitEdit(div, { render });
    else state.editingId = null;
  }

  function addChild(parentId) {
    if (!requireSignIn()) return null;
    const parent = findNode(parentId);
    if (!parent) return null;
    pushUndo();
    const n = newNode("");
    parent.children.push(n);
    parent.collapsed = false;
    return n;
  }

  // Same idea as addChild, but the new node holds a small editable grid
  // (see nodeIsTable) instead of a plain text label — offered from the
  // node right-click menu as "Add table child".
  function addTableChild(parentId) {
    if (!requireSignIn()) return null;
    const parent = findNode(parentId);
    if (!parent) return null;
    pushUndo();
    const n = newNode("");
    n.table = { cells: defaultTableCells() };
    parent.children.push(n);
    parent.collapsed = false;
    return n;
  }

  function tableAddRow(node) {
    const cols = (node.table.cells[0] || [""]).length;
    node.table.cells.push(new Array(cols).fill(""));
  }
  function tableAddColumn(node) {
    node.table.cells.forEach(row => row.push(""));
  }
  function tableRemoveRow(node) {
    if (node.table.cells.length > 1) node.table.cells.pop();
  }
  function tableRemoveColumn(node) {
    if (node.table.cells[0].length > 1) node.table.cells.forEach(row => row.pop());
  }

  function addSibling(nodeId) {
    if (!requireSignIn()) return null;
    const node = findNode(nodeId);
    if (!node) return null;
    const parent = findParent(nodeId);
    if (!parent) return addChild(nodeId); // root has no siblings -> add child instead
    pushUndo();
    const n = newNode("");
    const idx = parent.children.findIndex(c => c.id === nodeId);
    parent.children.splice(idx + 1, 0, n);
    return n;
  }

  function deleteBranch(nodeId) {
    if (!requireSignIn()) return;
    const parent = findParent(nodeId);
    if (!parent) { alert("The central idea can't be deleted."); return; }
    const node = findNode(nodeId);
    if (node.children && node.children.length > 0) {
      if (!confirm("Delete this node and all its children?")) return;
    }
    pushUndo();
    const removedIds = new Set();
    (function collect(n) { removedIds.add(n.id); (n.children || []).forEach(collect); })(node);
    parent.children = parent.children.filter(c => c.id !== nodeId);
    // any cross-link touching a node that no longer exists gets cleaned up too
    if (state.current.links && state.current.links.length) {
      state.current.links = state.current.links.filter(l => !removedIds.has(l.a) && !removedIds.has(l.b));
    }
    state.selectedId = parent.id;
    renderAll();
    persist();
  }

  /* ---------------- cross-links ---------------- */

  let defaultHintHTML = null;
  function updateLinkHint() {
    if (!hintBar) return;
    if (defaultHintHTML === null) defaultHintHTML = hintBar.innerHTML;
    if (state.linkFromId) {
      viewportEl.classList.add("linking");
      viewportEl.classList.remove("moving");
      hintBar.innerHTML = `<span>Click another node to link it &middot; <kbd>Esc</kbd> cancel</span>`;
    } else if (state.moveSourceId) {
      viewportEl.classList.remove("linking");
      viewportEl.classList.add("moving");
      hintBar.innerHTML = `<span>Right-click the new parent and choose "Move to here" &middot; or click a different map in the sidebar to move it there &middot; <kbd>Esc</kbd> cancel</span>`;
    } else {
      viewportEl.classList.remove("linking");
      viewportEl.classList.remove("moving");
      hintBar.innerHTML = defaultHintHTML;
    }
  }

  // Enters "pick the other end" mode: the next node the person clicks gets
  // linked to `nodeId`. Clicking the same node, empty canvas, or Escape
  // cancels it instead of completing a link.
  function startLinkFrom(nodeId) {
    if (!findNode(nodeId)) return;
    commitEditIfActive();
    state.linkFromId = nodeId;
    state.editingId = null;
    renderAll();
  }

  function cancelLinking() {
    if (!state.linkFromId) return;
    state.linkFromId = null;
    renderAll();
  }

  /* ---------------- move-to-new-parent (context menu) ---------------- */

  // Enters "pick the destination" mode: right-clicking a different node
  // next and choosing "Move to here" reparents `nodeId` there. This is a
  // click-based alternative to drag-and-drop reparenting — same end
  // result (reparentNode), just without needing to drag across a
  // possibly zoomed-out/scrolled canvas. Mirrors startLinkFrom above.
  function startMoveFrom(nodeId) {
    if (!findNode(nodeId)) return;
    commitEditIfActive();
    state.moveSourceId = nodeId;
    state.linkFromId = null;
    state.editingId = null;
    renderAll();
    renderSidebar(); // highlights every OTHER map as a drop target too (see completeMoveToMap)
  }

  function cancelMove() {
    if (!state.moveSourceId) return;
    state.moveSourceId = null;
    renderAll();
    renderSidebar();
  }

  // Whether targetId is a legal drop point for the pending move: not the
  // node itself, not somewhere inside its own subtree (would orphan it),
  // and not its current parent already (a no-op that would still cost an
  // undo step and a save).
  function canMoveSourceTo(targetId) {
    const srcId = state.moveSourceId;
    if (!srcId || !targetId || srcId === targetId) return false;
    const src = findNode(srcId);
    if (!src || !findNode(targetId)) return false;
    if (isWithinSubtree(src, targetId)) return false;
    const parent = findParent(srcId);
    if (parent && parent.id === targetId) return false;
    return true;
  }

  function completeMoveTo(targetId) {
    const srcId = state.moveSourceId;
    if (!canMoveSourceTo(targetId)) { state.moveSourceId = null; renderAll(); renderSidebar(); return; }
    state.moveSourceId = null;
    pushUndo();
    reparentNode(srcId, targetId);
    renderSidebar();
    persist();
  }

  // The cross-map counterpart of completeMoveTo: instead of picking a new
  // parent within the same tree (right-click → "Move to here"), the person
  // picks a whole different map from the sidebar while a move is pending
  // (see renderSidebar's .move-target rows). The moved branch lands as a
  // new top-level child of that map's root — same one-click simplicity as
  // the same-map version. Once it's there, opening that map and dragging
  // it deeper works exactly like any other reparent.
  async function completeMoveToMap(targetMapId) {
    const srcId = state.moveSourceId;
    const src = findNode(srcId);
    const parent = findParent(srcId);
    const targetMap = state.maps.find(m => m.id === targetMapId);
    state.moveSourceId = null;
    if (!src || !parent || !targetMap || !state.current || targetMap.id === state.current.id) {
      renderAll();
      renderSidebar();
      return;
    }
    pushUndo();

    // Detach from the source map's tree (mirrors reparentNode's removal
    // half) and drop any cross-links that touched the moved subtree — a
    // link is two node ids inside ONE map's `links` array, so a link to a
    // node about to live in a different map can't be expressed anymore.
    const movedIds = new Set();
    (function collect(n) { movedIds.add(n.id); (n.children || []).forEach(collect); })(src);
    parent.children = parent.children.filter(c => c.id !== srcId);
    if (state.current.links && state.current.links.length) {
      state.current.links = state.current.links.filter(l => !movedIds.has(l.a) && !movedIds.has(l.b));
    }
    if (state.selectedId && movedIds.has(state.selectedId)) state.selectedId = parent.id;
    if (state.highlightId && movedIds.has(state.highlightId)) state.highlightId = null;

    // The destination map may not have been opened yet this session, so
    // it could still be missing fields the running code assumes exist —
    // bring it up to date with the same one-time migrations openMap()
    // applies before writing into it.
    ensureTheme(targetMap);
    ensureLinks(targetMap);
    ensureLayout(targetMap);
    ensureFavorite(targetMap);
    ensureTrash(targetMap);
    ensureSidesRepaired(targetMap);
    ensureAffirmationMigrated(targetMap);
    if (!targetMap._photosMigrated) await ensurePhotosMigrated(targetMap);

    // The moved subtree's own photos live in PhotoDB tagged with the
    // source map's id (see PhotoDB/loadPhotoCacheForMap) — re-tag every
    // one to the destination map so it isn't orphaned there and actually
    // loads once that map is opened.
    const photoIds = collectReferencedPhotoIds(src);
    // src is already detached from the source tree, so this is what the
    // nodes staying behind still use.
    const stayingPhotoIds = collectReferencedPhotoIds(state.current.root);
    for (const id of photoIds) {
      const blob = photoBlobCache.get(id);
      if (blob === undefined) continue; // already gone/never loaded — nothing to carry over
      if (stayingPhotoIds.has(id)) {
        // Shared with a node that stays in this map: the moved branch gets
        // its own copy (new id) in the destination, the original stays put.
        try {
          const copyId = uid();
          (function swapIn(n) { replacePhotoIdInNode(n, id, copyId); (n.children || []).forEach(swapIn); })(src);
          await PhotoDB.put({ id: copyId, mapId: targetMap.id, blob });
        } catch (e) { console.error("Copying shared photo to new map failed", e); }
        continue;
      }
      try {
        await PhotoDB.put({ id, mapId: targetMap.id, blob });
        // No longer part of the currently-open (source) map — drop it
        // from both caches, revoking its object URL so the Blob isn't
        // held alive by a URL nothing points to anymore.
        const url = photoCache.get(id);
        if (url) { try { URL.revokeObjectURL(url); } catch (e) { /* already gone */ } }
        photoCache.delete(id);
        photoBlobCache.delete(id);
      } catch (e) { console.error("Moving photo to new map failed", e); }
    }

    // Same reset reparentNode applies when a branch lands under a new
    // parent — a manual nudge offset, an explicit left/right or Timeline
    // above/below override, a custom connector distance, and a top-level
    // branch color all only ever made sense relative to the old map, not
    // this one.
    targetMap.root.collapsed = false;
    if (!targetMap.root.children) targetMap.root.children = [];
    targetMap.root.children.push(src);
    src.ox = 0; src.oy = 0; src.side = null; src.vSide = null; src._autoSide = null; src.xGap = null; src.color = null;
    collectDescendants(src).forEach(d => { d.ox = 0; d.oy = 0; d._autoSide = null; d.color = null; });

    try {
      await DB.put(targetMap);
      await FolderDB.save(targetMap);
      await DriveDB.save(targetMap);
    } catch (e) { console.error("Saving the moved-to map failed", e); }

    renderAll();
    renderSidebar();
    persist(); // saves state.current (the source map) with the branch removed
  }

  function linkExists(aId, bId) {
    return (state.current.links || []).some(l =>
      (l.a === aId && l.b === bId) || (l.a === bId && l.b === aId));
  }

  function completeLinkTo(targetId) {
    const fromId = state.linkFromId;
    state.linkFromId = null;
    if (!fromId || !targetId || fromId === targetId) { renderAll(); return; }
    if (!findNode(fromId) || !findNode(targetId)) { renderAll(); return; }
    if (linkExists(fromId, targetId)) { renderAll(); return; }
    pushUndo();
    if (!state.current.links) state.current.links = [];
    state.current.links.push({ id: uid(), a: fromId, b: targetId });
    renderAll();
    persist();
  }

  function linksForNode(nodeId) {
    return (state.current.links || []).filter(l => l.a === nodeId || l.b === nodeId);
  }

  function removeLink(linkId) {
    if (!state.current || !state.current.links) return;
    pushUndo();
    state.current.links = state.current.links.filter(l => l.id !== linkId);
    renderAll();
    persist();
  }

  /* ---------------- keyboard ---------------- */

  function nodeKeydown(e, node, div) {
    const editing = state.editingId === node.id;
    if (editing) {
      if (e.key === "Tab") {
        e.preventDefault();
        commitEdit(div);
        const n = addChild(node.id);
        if (n) { state.selectedId = n.id; state.editingId = n.id; renderAll(); }
        persist();
      } else if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        commitEdit(div);
        const n = addSibling(node.id);
        if (n) { state.selectedId = n.id; state.editingId = n.id; renderAll(); }
        persist();
      } else if (e.key === "Escape") {
        e.preventDefault();
        commitEdit(div);
      }
      e.stopPropagation();
    }
  }

  document.addEventListener("keydown", (e) => {
    if (!state.current) return;
    const activeIsEditable = document.activeElement && document.activeElement.isContentEditable;
    const activeIsInput = document.activeElement && (document.activeElement.tagName === "INPUT" || document.activeElement.tagName === "TEXTAREA");
    if (activeIsEditable || activeIsInput) return; // handled by node/title listeners

    if (state.linkFromId && e.key === "Escape") {
      e.preventDefault();
      cancelLinking();
      return;
    }
    if (state.moveSourceId && e.key === "Escape") {
      e.preventDefault();
      cancelMove();
      return;
    }
    if (state.highlightId && e.key === "Escape") {
      e.preventDefault();
      clearHighlight();
      return;
    }

    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") {
      e.preventDefault();
      if (e.shiftKey) redo(); else undo();
      return;
    }
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k") {
      e.preventDefault();
      if (state.selectedId) addNodeUrl(state.selectedId);
      return;
    }
    if (!state.selectedId) {
      if (e.key === "Tab" || e.key === "Enter") {
        e.preventDefault();
        state.selectedId = state.current.root.id;
      }
      return;
    }
    const node = findNode(state.selectedId);
    if (!node) return;

    if (e.key === "Tab") {
      e.preventDefault();
      const n = addChild(node.id);
      if (n) { state.selectedId = n.id; state.editingId = n.id; renderAll(); }
      persist();
    } else if (e.key === "Enter") {
      e.preventDefault();
      const n = addSibling(node.id);
      if (n) { state.selectedId = n.id; state.editingId = n.id; renderAll(); }
      persist();
    } else if (e.key === "F2") {
      e.preventDefault();
      startEdit(node.id);
    } else if (e.key === "Delete" || e.key === "Backspace") {
      e.preventDefault();
      deleteBranch(node.id);
    } else if (e.key === " ") {
      e.preventDefault();
      if (node.children && node.children.length) {
        pushUndo();
        node.collapsed = !node.collapsed;
        renderAll();
        persist();
      }
    } else if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key.toLowerCase() === "x") {
      e.preventDefault();
      pushUndo();
      node.struck = !node.struck;
      renderAll();
      persist();
    } else if (e.key.startsWith("Arrow")) {
      e.preventDefault();
      navigate(node, e.key);
    }
  });

  function navigate(from, dir) {
    const all = [];
    (function collect(n) { all.push(n); if (!n.collapsed) (n.children || []).forEach(collect); })(state.current.root);
    const dx = dir === "ArrowRight" ? 1 : dir === "ArrowLeft" ? -1 : 0;
    const dy = dir === "ArrowDown" ? 1 : dir === "ArrowUp" ? -1 : 0;
    let best = null, bestScore = Infinity;
    for (const n of all) {
      if (n.id === from.id) continue;
      const ddx = n._x - from._x, ddy = n._y - from._y;
      if (dx !== 0 && Math.sign(ddx || 0) !== dx && !(dx === 1 && n._depth > from._depth) && !(dx === -1 && n._depth < from._depth)) {
        // fallback simple directional filter
      }
      const alongAxis = dx !== 0 ? ddx * dx : ddy * dy;
      if (alongAxis <= 0) continue;
      const perpPenalty = dx !== 0 ? Math.abs(ddy) : Math.abs(ddx);
      const score = alongAxis + perpPenalty * 2;
      if (score < bestScore) { bestScore = score; best = n; }
    }
    if (best) { state.selectedId = best.id; renderAll(); }
  }

  /* ---------------- context menu ---------------- */

  // Combined "Connector style" picker — one shared row of three
  // mutually-exclusive buttons (Curved / Elbow / Arrow) used identically
  // in three places: the root node's menu (sets the map-wide default),
  // a "mother" node's bulk picker (sets all of its direct children's
  // hops at once), and a single connector's own right-click menu (sets
  // just that one hop). `read()` returns which button should show as
  // active ("curved" | "elbow" | "arrow" | null for a mixed bulk
  // selection with no single answer), and `choose(value)` applies a click.
  function renderConnectorStyleRow(ctxMenu, label, read, choose) {
    const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep);
    const labelEl = document.createElement("div");
    labelEl.className = "ctx-item"; labelEl.style.cursor = "default";
    labelEl.textContent = label;
    ctxMenu.appendChild(labelEl);

    const row = document.createElement("div");
    row.className = "ctx-style-row";
    const current = read();
    [["curved", "Curved"], ["elbow", "Elbow"], ["arrow", "Arrow"]].forEach(([val, text]) => {
      const btn = document.createElement("div");
      btn.className = "ctx-style-btn" + (current === val ? " active" : "");
      btn.textContent = text;
      btn.addEventListener("click", () => {
        closeContextMenu();
        pushUndo();
        choose(val);
        renderAll();
        persist();
      });
      row.appendChild(btn);
    });
    ctxMenu.appendChild(row);
  }

  function openContextMenu(x, y, node) {
    resetContextMenu();

    // Renders a plain array of [label, fn, removeFn?] rows the same way
    // every "generic action" group below does — factored out once so
    // each group can just build its own small array and hand it here,
    // rather than repeating this same DOM-building loop per group.
    const renderItemRows = (list) => {
      for (const [label, fn, removeFn] of list) {
        const it = document.createElement("div");
        it.className = "ctx-item";
        const labelSpan = document.createElement("span");
        labelSpan.className = "ctx-item-label";
        labelSpan.textContent = label;
        it.appendChild(labelSpan);
        if (removeFn) {
          const rm = document.createElement("span");
          rm.className = "ctx-item-remove";
          rm.textContent = "✕";
          rm.title = "Remove";
          // Stop the click from also bubbling into the row's own handler
          // below (which would open the edit prompt right after removing).
          rm.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); removeFn(); });
          it.appendChild(rm);
        }
        it.addEventListener("click", () => { closeContextMenu(); fn(); });
        ctxMenu.appendChild(it);
      }
    };
    const addSep = () => { const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep); };

    // Group: structure — renaming, moving, and other actions that change
    // where/how this node sits in the tree, not what it contains.
    const structureItems = [];
    // Double-click/F2 rename a node's text just fine with a mouse and
    // keyboard, but neither is reliable on a touchscreen — a double-tap
    // doesn't always synthesize a dblclick event, and there's no F2 key.
    // Long-press already opens this menu on touch, so put Rename here too.
    if (!nodeIsTable(node)) {
      structureItems.push(["✏️ Rename", () => startEdit(node.id)]);
    }
    // Move-to-new-parent, as an alternative to dragging the node across
    // the canvas (handy when the destination is far away or off-screen).
    // The root has no parent, so it can never be the thing being moved —
    // but it's always a legal destination, handled by the block below.
    if (node !== state.current.root) {
      if (state.moveSourceId === node.id) {
        structureItems.push(["🚫 Cancel move", () => cancelMove()]);
      } else {
        structureItems.push(["📦 Move…", () => startMoveFrom(node.id)]);
      }
    }
    if (state.moveSourceId && state.moveSourceId !== node.id && canMoveSourceTo(node.id)) {
      structureItems.push(["📥 Move to here", () => completeMoveTo(node.id)]);
    }
    structureItems.push([node.struck ? "~~ Remove strikethrough" : "~~ Strikethrough", () => { pushUndo(); node.struck = !node.struck; renderAll(); persist(); }]);
    if (node.children && node.children.length > 0) {
      structureItems.push([node.collapsed ? "▸ Expand" : "▾ Collapse", () => { pushUndo(); node.collapsed = !node.collapsed; renderAll(); persist(); }]);
    }
    if (node.ox || node.oy) {
      structureItems.push(["↺ Reset position", () => { pushUndo(); delete node.ox; delete node.oy; renderAll(); persist(); }]);
    }
    renderItemRows(structureItems);

    // Group: content — the stuff actually living on this node (table
    // structure, notes, photos), kept apart from the structural actions
    // above since these add/change what the node holds rather than where
    // it sits.
    addSep();
    const contentItems = [];
    contentItems.push(["▦ Add table child", () => {
      const n = addTableChild(node.id);
      if (n) { state.selectedId = n.id; renderAll(); persist(); }
    }]);
    if (nodeIsTable(node)) {
      contentItems.push(["⬇️ Add row", () => { pushUndo(); tableAddRow(node); renderAll(); persist(); }]);
      contentItems.push(["➡️ Add column", () => { pushUndo(); tableAddColumn(node); renderAll(); persist(); }]);
      if (node.table.cells.length > 1) {
        contentItems.push(["⬆️ Remove row", () => { pushUndo(); tableRemoveRow(node); renderAll(); persist(); }]);
      }
      if (node.table.cells[0].length > 1) {
        contentItems.push(["⬅️ Remove column", () => { pushUndo(); tableRemoveColumn(node); renderAll(); persist(); }]);
      }
      // "Outline only" hides every interior cell border and keeps just
      // the table's outer edge (plus a thin rule under the second row,
      // for a header-style divider) — see the .node-table-outline CSS
      // and renderTableGrid's table.classList.add below. Handy for
      // calendar-style tables where a full interior grid looks noisy.
      const outline = node.table.gridStyle === "outline";
      contentItems.push([outline ? "▦ Grid lines: show all cells" : "▦ Grid lines: outline only", () => {
        pushUndo();
        node.table.gridStyle = outline ? "grid" : "outline";
        renderAll();
        persist();
      }]);
    }
    contentItems.push([nodeHasNotes(node) ? `📝 Notes (${getNodeNotes(node).length})…` : "📝 Add note…", () => openNoteModal(node.id)]);
    contentItems.push(["🖼️ Add photo…", () => openNodePhotoPicker(node.id)]);
    if (nodeHasImages(node)) {
      contentItems.push([getNodeImageIds(node).length > 1 ? "👁️ View photos…" : "👁️ View photo…", () => openPhotoModal(node.id, 0)]);
      contentItems.push(["🗑️ Remove all photos", () => {
        pushUndo();
        getNodeImageIds(node).forEach(deletePhotoRecord);
        node.images = []; node.image = null; node.photoTags = {}; node.photoNotes = {}; node.photoComments = {};
        renderAll(); persist();
      }]);
    }
    renderItemRows(contentItems);

    // Group: reference — actions that read/export/mark this branch
    // rather than change or add to it.
    addSep();
    renderItemRows([
      ["📋 Copy as outline", () => copyNodeBranchToClipboard(node)],
      [state.highlightId === node.id ? "🖍️ Remove highlight" : "🖍️ Highlight branch", () => setHighlight(node.id)],
    ]);

    // Tasks, Timer, Brainstorm, commented Links, and the Affirmation game —
    // grouped together in their own section (separated by a divider)
    // rather than scattered among the generic node actions above, since
    // these five are exactly the things nodeTaskProgress adds points for
    // (see that function's comments), i.e. the "work on this node for
    // score" actions as opposed to editing/formatting it.
    // The Affirmation game row carries a small "✎" button on its right
    // edge (reusing the same corner-icon slot as the ✕ remove buttons
    // elsewhere in this menu) that opens the shared lines-editor modal
    // instead of starting a round.
    {
      addSep();

      const addGroupRow = (label, fn) => {
        const row = document.createElement("div");
        row.className = "ctx-item";
        const labelSpan = document.createElement("span");
        labelSpan.className = "ctx-item-label";
        labelSpan.textContent = label;
        row.appendChild(labelSpan);
        row.addEventListener("click", () => { closeContextMenu(); fn(); });
        ctxMenu.appendChild(row);
        return row;
      };

      {
        const prog = nodeTaskProgress(node);
        const label = prog.total ? `✅ Tasks… (${prog.done}/${prog.total})` : "✅ Add tasks…";
        addGroupRow(label, () => openTasksModal(node.id));
      }
      {
        const played = getNodeTimePlayed(node);
        const label = played ? `⏱️ Timer — ${formatTimePlayed(played)}…` : "⏱️ Add timer…";
        addGroupRow(label, () => openTimerModal(node.id));
      }
      {
        const pts = brainstormPoints(node);
        const label = pts > 0 ? `🧠 Brainstorm (${pts} pt${pts === 1 ? "" : "s"})…` : "🧠 Brainstorm…";
        addGroupRow(label, () => openBrainstormModal(node.id));
      }
      {
        // Shortcut: opens this node's DRC note, pre-filled with the
        // "DRC" note template (see getDRCTemplateText / the forceDRCTemplate
        // branch in openNoteModal) the first time, or just reopens the
        // existing one on every click after that — only one DRC note is
        // allowed per node. Unlike the automatic prefill, this isn't tied
        // to any task being named "DRC". The label shows how many filled-in
        // DRC notes exist so far (see drcNoteIsFilled) — no longer a point
        // value, since DRC notes stopped contributing to the task score.
        const drcFilled = getNodeNotes(node).filter(n => isDRCNote(n) && drcNoteIsFilled(n)).length;
        const label = drcFilled > 0 ? `DRC (${drcFilled} filled in)…` : "DRC…";
        const drcItem = addGroupRow(label, () => openNoteModal(node.id, undefined, null, null, null, true));
        // Same notebook+pencil image as the DRC marker on the node itself,
        // instead of a 📋 emoji, so the two match.
        const drcLabelSpan = drcItem.querySelector(".ctx-item-label");
        if (drcLabelSpan) drcLabelSpan.prepend(drcIconEl(16));
      }
      {
        // Only *commented* links score points (see nodeTaskProgress), so
        // the count shown here — unlike the plain "Add link…" action this
        // replaces — reflects how many of the node's links have a comment
        // set, not just how many links exist. Still just opens the normal
        // add-link prompt; commenting on a link itself happens from that
        // link's own icon.
        const urls = getNodeUrls(node);
        const commented = urls.filter(u => getLinkComment(node, u)).length;
        const label = commented > 0 ? `🔗 Links (${commented} commented)…` : "🔗 Add link…";
        addGroupRow(label, () => addNodeUrl(node.id));
      }

      const wins = nodeAffirmationWins(node);
      const gameItem = addGroupRow(
        wins ? `🎮 Affirmation game (✓ ${wins})` : "🎮 Affirmation game",
        () => openAffirmationGame(node.id)
      );
      const editBtn = document.createElement("span");
      editBtn.className = "ctx-item-remove ctx-item-edit-affirmation";
      editBtn.textContent = "✎";
      editBtn.title = "Edit affirmation lines";
      // Stop the click from also bubbling into the row's own handler
      // above (which would start a game round right after opening the
      // editor).
      editBtn.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); openAffirmationQuotesModal(); });
      gameItem.appendChild(editBtn);
    }

    // Glow effect picker — several intensities/speeds rather than a plain
    // on/off toggle, plus "None" to turn it off. Reuses the same
    // label-then-row layout as the branch color swatches below.
    {
      const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep);
      const label = document.createElement("div");
      label.className = "ctx-item"; label.style.cursor = "default";
      label.textContent = "✨ Glow effect";
      ctxMenu.appendChild(label);

      const row = document.createElement("div");
      row.className = "ctx-glow-options";
      const GLOW_OPTIONS = [
        [null, "None"],
        ["soft", "Soft"],
        ["fast", "Fast"],
        ["blink", "Blink"],
      ];
      const currentGlow = node.glow === true ? "soft" : (node.glow || null);
      GLOW_OPTIONS.forEach(([value, glowLabel]) => {
        const opt = document.createElement("span");
        opt.className = "ctx-glow-opt" + (currentGlow === value ? " active" : "");
        opt.textContent = glowLabel;
        opt.addEventListener("click", () => {
          pushUndo();
          node.glow = value;
          closeContextMenu();
          renderAll();
          persist();
        });
        row.appendChild(opt);
      });
      ctxMenu.appendChild(row);
    }

    // Connector style — map-wide default, so it only makes sense to offer
    // on the root (level 0) node rather than per-branch. Any individual
    // node's or connector's own picker can still override it for just
    // that hop (see the bulk "children" picker below, and
    // openConnectorContextMenu for a single hop).
    if (node === state.current.root) {
      renderConnectorStyleRow(ctxMenu, "🔀 Connector style",
        () => {
          ensureTheme(state.current);
          return state.current.theme.connectorArrow ? "arrow" : (state.current.theme.connectorShape || "curved");
        },
        (val) => {
          ensureTheme(state.current);
          if (val === "arrow") {
            state.current.theme.connectorArrow = true;
          } else {
            state.current.theme.connectorArrow = false;
            state.current.theme.connectorShape = val;
          }
        }
      );
    }

    // Hide clock/calendar — moved here from the theme panel. Even though
    // the live clock only ever renders on the root node (and the 📅
    // Calendar button lives in the toolbar), the toggle is offered from
    // every node's right-click menu, not just root's, so it's reachable
    // without having to navigate back to the root first. Saved per-map —
    // see isClockHidden/ensureClockHidden — so it only affects the
    // mindmap currently open.
    {
      const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep);
      const clockItem = document.createElement("div");
      clockItem.className = "ctx-item";
      clockItem.textContent = isClockHidden() ? "🕐 Show root node clock & 📅 Calendar button" : "🕐 Hide root node clock & 📅 Calendar button";
      clockItem.addEventListener("click", () => { closeContextMenu(); setClockHidden(!isClockHidden()); });
      ctxMenu.appendChild(clockItem);
    }

    // A "mother" node with children gets a single input that sets the
    // distance for ALL of its descendants' connectors at once — every
    // generation below this node, not just its direct children — so one
    // number gives the whole subtree consistent spacing in one go. The
    // per-connector right-click menu (see openConnectorContextMenu) still
    // works for tweaking just one hop afterward.
    if (node.children && node.children.length) {
      const sep0 = document.createElement("div"); sep0.className = "ctx-sep"; ctxMenu.appendChild(sep0);
      const distLabel = document.createElement("div");
      distLabel.className = "ctx-item";
      distLabel.style.cursor = "default";
      distLabel.textContent = "↔️ Children distance";
      ctxMenu.appendChild(distLabel);

      const distRow = document.createElement("div");
      distRow.className = "ctx-distance-row";
      const distInput = document.createElement("input");
      distInput.type = "number";
      distInput.min = String(MIN_X_GAP);
      distInput.max = String(MAX_X_GAP);
      distInput.step = "5";
      distInput.value = Math.round(gapFor(node.children[0]));
      distInput.className = "ctx-distance-input";
      distRow.appendChild(distInput);
      const distUnit = document.createElement("span");
      distUnit.className = "ctx-distance-unit";
      distUnit.textContent = "px";
      distRow.appendChild(distUnit);
      ctxMenu.appendChild(distRow);

      const allDescendants = collectDescendants(node);

      distRow.addEventListener("click", (e) => e.stopPropagation());
      distInput.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Enter") { distInput.blur(); closeContextMenu(); }
      });
      distInput.addEventListener("change", () => {
        const v = parseFloat(distInput.value);
        if (Number.isNaN(v)) return;
        const clamped = Math.max(MIN_X_GAP, Math.min(MAX_X_GAP, Math.round(v)));
        pushUndo();
        allDescendants.forEach(d => { d.xGap = clamped; });
        renderAll();
        persist();
      });

      const anyCustomGap = allDescendants.some(d => typeof d.xGap === "number" && d.xGap >= 0);
      if (anyCustomGap) {
        const resetAll = document.createElement("div");
        resetAll.className = "ctx-item";
        resetAll.textContent = "↺ Reset all to default spacing";
        resetAll.addEventListener("click", () => {
          closeContextMenu();
          pushUndo();
          allDescendants.forEach(d => { d.xGap = null; });
          renderAll();
          persist();
        });
        ctxMenu.appendChild(resetAll);
      }

      // Bulk connector style — same combined Curved/Elbow/Arrow picker as
      // the per-connector menu (see openConnectorContextMenu), but applied
      // to every direct child's connector at once instead of one at a time.
      renderConnectorStyleRow(ctxMenu, "🔀 Children connector style",
        () => {
          ensureTheme(state.current);
          const values = node.children.map((c) => {
            if (c.connectorStyle === "arrow") return "arrow";
            if (c.connectorStyle === "line") return c.connectorShape || state.current.theme.connectorShape || "curved";
            return state.current.theme.connectorArrow ? "arrow" : (c.connectorShape || state.current.theme.connectorShape || "curved");
          });
          return values.every(v => v === values[0]) ? values[0] : null;
        },
        (val) => {
          node.children.forEach((c) => {
            if (val === "arrow") {
              c.connectorStyle = "arrow";
            } else {
              c.connectorStyle = "line";
              c.connectorShape = val;
            }
          });
        }
      );
    }

    const existingLinks = linksForNode(node.id);
    if (existingLinks.length) {
      const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep);
      for (const link of existingLinks) {
        const otherId = link.a === node.id ? link.b : link.a;
        const other = findNode(otherId);
        const it = document.createElement("div");
        it.className = "ctx-item danger";
        it.textContent = `🔗 Remove link to "${other ? (other.text || "(untitled)") : "unknown node"}"`;
        it.addEventListener("click", () => { closeContextMenu(); removeLink(link.id); });
        ctxMenu.appendChild(it);
      }
    }

    const topAncestor = findTopAncestor(node);
    if (topAncestor) {
      const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep);
      const label = document.createElement("div");
      label.className = "ctx-item"; label.style.cursor = "default";
      label.textContent = "🎨 Branch color";
      ctxMenu.appendChild(label);
      const sw = document.createElement("div"); sw.className = "ctx-swatches";
      PALETTE.forEach(c => {
        const s = document.createElement("span");
        s.className = "ctx-swatch" + (topAncestor.color === c ? " active" : "");
        s.style.background = c;
        s.addEventListener("click", () => { pushUndo(); topAncestor.color = c; closeContextMenu(); renderAll(); persist(); });
        sw.appendChild(s);
      });
      ctxMenu.appendChild(sw);
    } else if (node === state.current.root) {
      // The root/"mother topic" has no branch ancestor to color, but it
      // gets the same swatch picker for its own fill (see the rootColor
      // handling in renderNode) so the central idea isn't stuck with a
      // fixed color while every branch under it can be customized.
      const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep);
      const label = document.createElement("div");
      label.className = "ctx-item"; label.style.cursor = "default";
      label.textContent = "🎨 Node color";
      ctxMenu.appendChild(label);
      const sw = document.createElement("div"); sw.className = "ctx-swatches";
      PALETTE.forEach(c => {
        const s = document.createElement("span");
        s.className = "ctx-swatch" + (node.color === c ? " active" : "");
        s.style.background = c;
        s.addEventListener("click", () => { pushUndo(); node.color = c; closeContextMenu(); renderAll(); persist(); });
        sw.appendChild(s);
      });
      ctxMenu.appendChild(sw);
    }

    // Font color is independent of branch/root fill color above — it's a
    // per-node text override (see the fontColor field on newNode) that
    // wins over the branch tint, the map-wide theme font color, and the
    // auto-contrast default, in that order (see renderNode). Offered on
    // every node, not just branch tops/root, since any single node's text
    // can be recolored regardless of what's coloring its box.
    {
      const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep);
      const label = document.createElement("div");
      label.className = "ctx-item"; label.style.cursor = "default";
      label.textContent = "🔤 Font color";
      ctxMenu.appendChild(label);
      const sw = document.createElement("div"); sw.className = "ctx-swatches";
      const resetSwatch = document.createElement("span");
      resetSwatch.className = "ctx-swatch ctx-swatch-reset" + (!node.fontColor ? " active" : "");
      resetSwatch.title = "Default";
      resetSwatch.addEventListener("click", () => { pushUndo(); node.fontColor = null; closeContextMenu(); renderAll(); persist(); });
      sw.appendChild(resetSwatch);
      PALETTE.forEach(c => {
        const s = document.createElement("span");
        s.className = "ctx-swatch" + (node.fontColor === c ? " active" : "");
        s.style.background = c;
        s.addEventListener("click", () => { pushUndo(); node.fontColor = c; closeContextMenu(); renderAll(); persist(); });
        sw.appendChild(s);
      });
      ctxMenu.appendChild(sw);
    }

    if (findParent(node.id)) {
      const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep);
      const del = document.createElement("div");
      del.className = "ctx-item danger";
      del.textContent = "🗑️ Delete branch (Del)";
      del.addEventListener("click", () => { closeContextMenu(); deleteBranch(node.id); });
      ctxMenu.appendChild(del);
    }

    positionContextMenu(x, y);
  }

  function openLinkContextMenu(x, y, link) {
    resetContextMenu();
    const del = document.createElement("div");
    del.className = "ctx-item danger";
    del.textContent = "Delete link";
    del.addEventListener("click", () => { closeContextMenu(); removeLink(link.id); });
    ctxMenu.appendChild(del);

    positionContextMenu(x, y);
  }

  // The lower bound has to stay at or below the smallest distance the
  // layout can ever hand out by default — an elbow-shaped connector below
  // the root already defaults to X_GAP / 2 (see defaultGapForDepth), which
  // is well under what used to be the floor here. Whenever that default
  // fell below the input's own declared `min`, the field opened already
  // out of range, and typing into it (particularly on level-2+ nodes,
  // since only THEIR default sits below the old floor) never produced a
  // value the input would accept.
  const MIN_X_GAP = 10;
  const MAX_X_GAP = 900;

  // Right-click on a parent→child connector: lets the user type an exact
  // pixel distance for that one hop (see gapFor/place/placeLocal), instead
  // of only being able to eyeball it by dragging.
  function openConnectorContextMenu(x, y, parent, child) {
    resetContextMenu();

    const isCustom = typeof child.xGap === "number" && child.xGap >= 0;
    const currentGap = isCustom ? child.xGap : defaultGapForDepth(child._depth);

    const label = document.createElement("div");
    label.className = "ctx-item";
    label.style.cursor = "default";
    label.textContent = "Connector distance";
    ctxMenu.appendChild(label);

    const row = document.createElement("div");
    row.className = "ctx-distance-row";
    const input = document.createElement("input");
    input.type = "number";
    input.min = String(MIN_X_GAP);
    input.max = String(MAX_X_GAP);
    input.step = "5";
    input.value = Math.round(currentGap);
    input.className = "ctx-distance-input";
    row.appendChild(input);
    const unit = document.createElement("span");
    unit.className = "ctx-distance-unit";
    unit.textContent = "px";
    row.appendChild(unit);
    ctxMenu.appendChild(row);

    // Keep clicks/typing in the input from bubbling to the document-level
    // listener that closes the menu on any outside click.
    row.addEventListener("click", (e) => e.stopPropagation());
    input.addEventListener("keydown", (e) => {
      e.stopPropagation();
      if (e.key === "Enter") { input.blur(); closeContextMenu(); }
    });
    input.addEventListener("change", () => {
      const v = parseFloat(input.value);
      if (Number.isNaN(v)) return;
      const clamped = Math.max(MIN_X_GAP, Math.min(MAX_X_GAP, Math.round(v)));
      pushUndo();
      child.xGap = clamped;
      renderAll();
      persist();
    });

    if (isCustom) {
      const sep = document.createElement("div"); sep.className = "ctx-sep"; ctxMenu.appendChild(sep);
      const reset = document.createElement("div");
      reset.className = "ctx-item";
      reset.textContent = "Reset to default spacing";
      reset.addEventListener("click", () => {
        closeContextMenu();
        pushUndo();
        child.xGap = null;
        renderAll();
        persist();
      });
      ctxMenu.appendChild(reset);
    }

    renderConnectorStyleRow(ctxMenu, "Connector style",
      () => {
        ensureTheme(state.current);
        if (child.connectorStyle === "arrow") return "arrow";
        if (child.connectorStyle === "line") return child.connectorShape || state.current.theme.connectorShape || "curved";
        return state.current.theme.connectorArrow ? "arrow" : (child.connectorShape || state.current.theme.connectorShape || "curved");
      },
      (val) => {
        if (val === "arrow") {
          child.connectorStyle = "arrow";
        } else {
          child.connectorStyle = "line";
          child.connectorShape = val;
        }
      }
    );

    positionContextMenu(x, y);
    setTimeout(() => input.focus(), 0);
  }

  // Flattens a node and its descendants into an indented outline, e.g.:
  //   Project Launch
  //     - Research
  //       - Competitors
  //       - Market size
  //     - Design
  // Each level adds two spaces of indent plus a "- " marker, so depth
  // stays readable even if leading whitespace gets collapsed by whatever
  // it's pasted into (email clients, chat apps, etc. often strip runs of
  // spaces) — the accumulating "- " prefixes still show the level.
  function nodeBranchToOutline(node) {
    const lines = [];
    (function walk(n, depth) {
      const label = nodeIsTable(n)
        ? n.table.cells.map(row => row.map(c => c || "").join(" | ")).join(" / ") || "(empty table)"
        : ((n.text || "(untitled)").trim() || "(untitled)");
      const indent = "  ".repeat(depth);
      const marker = depth ? "- " : "";
      lines.push(indent + marker + label);
      (n.children || []).filter(Boolean).forEach(c => walk(c, depth + 1));
    })(node, 0);
    return lines.join("\n");
  }

  async function copyNodeBranchToClipboard(node) {
    const text = nodeBranchToOutline(node);
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(text);
      } else {
        throw new Error("no clipboard API");
      }
      showToast("Copied to clipboard");
    } catch (err) {
      // Fallback for browsers/contexts without navigator.clipboard
      // (e.g. non-secure local file contexts in some browsers).
      try {
        const ta = document.createElement("textarea");
        ta.value = text;
        ta.style.position = "fixed";
        ta.style.opacity = "0";
        document.body.appendChild(ta);
        ta.focus();
        ta.select();
        document.execCommand("copy");
        document.body.removeChild(ta);
        showToast("Copied to clipboard");
      } catch (err2) {
        showToast("Couldn't copy — try again");
      }
    }
  }

  let toastEl = null;
  let toastHideTimer = null;
  function showToast(message) {
    if (!toastEl) {
      toastEl = document.createElement("div");
      toastEl.className = "app-toast";
      document.body.appendChild(toastEl);
    }
    toastEl.textContent = message;
    toastEl.classList.remove("show");
    void toastEl.offsetWidth; // restart CSS transition
    toastEl.classList.add("show");
    clearTimeout(toastHideTimer);
    toastHideTimer = setTimeout(() => toastEl.classList.remove("show"), 1600);
  }

  function findTopAncestor(node) {
    if (!state.current) return null;
    if (node === state.current.root) return null;
    let found = null;
    (function walk(n, top) {
      for (const c of n.children || []) {
        const t = top || c;
        if (c === node) { found = t; return; }
        walk(c, t);
      }
    })(state.current.root, null);
    return found;
  }

  function closeContextMenu() { ctxMenu.classList.add("hidden"); }
  document.addEventListener("click", closeContextMenu);
  // Capture-phase "scroll" is meant to close the menu when the page/canvas
  // behind it scrolls out from under it — but "scroll" events still fire
  // through the capture phase on ancestors even though they don't bubble,
  // so without this guard, scrolling *inside* the menu's own internal
  // scroll area (see .ctx-menu's overflow-y in the CSS) was closing it
  // immediately instead of letting it scroll.
  document.addEventListener("scroll", (e) => {
    if (e.target === ctxMenu || (e.target.nodeType === 1 && ctxMenu.contains(e.target))) return;
    closeContextMenu();
  }, true);

  /* ---------------- canvas pan / zoom ---------------- */

  function applyTransform() {
    worldEl.style.transform = `translate(${state.tx}px, ${state.ty}px) scale(${state.scale})`;
    // Only promote #world to its own composited GPU layer *while* pan/zoom
    // is actually moving. Chromium (and others) render a composited layer
    // by scaling a cached bitmap rather than re-rasterizing text/lines at
    // the new scale, which is what was making the map look blurry once
    // zoomed in — especially visible on a high-DPI/4K display. Dropping
    // will-change back to "auto" a beat after the last change forces a
    // fresh, crisp repaint at rest; it's re-applied on the next move so
    // panning/zooming itself still stays smooth.
    worldEl.style.willChange = "transform";
    if (transformSettleTimer) clearTimeout(transformSettleTimer);
    transformSettleTimer = setTimeout(() => { worldEl.style.willChange = "auto"; }, 160);
  }
  let transformSettleTimer = null;

  let panning = false, panStart = null;
  // Set while two (or more) touches are down at once — drives pinch-zoom
  // instead of the single-finger pan/drag handling below. See the
  // viewportEl pointerdown listener for how it's populated.
  let pinchState = null;

  function startPan(clientX, clientY) {
    // What was on screen before this press decides how much has to be
    // redrawn afterwards (see the end of this function).
    const hadEditing = !!state.editingId;
    const hadCellState = !!(state.selectedCell || state.cellRange || state.cellRangeAnchor);
    const prevSelectedId = state.selectedId;
    // render:false — this function renders (at most) once itself below;
    // letting commitEditIfActive render too made every click on empty
    // canvas rebuild the whole map twice.
    commitEditIfActive({ render: false });
    panning = true;
    panStart = { x: clientX, y: clientY, tx: state.tx, ty: state.ty };
    viewportEl.classList.add("panning");
    state.selectedId = null;
    state.selectedCell = null;
    state.cellRangeAnchor = null;
    state.cellRange = null;
    state.editingId = null;
    // Deliberately NOT clearing linkFromId/moveSourceId here. Both
    // "pick the other end"/"pick the destination" modes are meant to
    // support a target that's off-screen — startMoveFrom's whole point is
    // letting you pan across the canvas to reach a far-away parent — so a
    // pan (which is exactly how you'd scroll to find that target) must not
    // cancel the pending link/move. Escape, completing the action, or
    // explicitly choosing "Cancel move" are the only ways to back out (see
    // updateLinkHint's hint text).
    //
    // Leaving an edit box or a table-cell selection needs the real
    // thing (text may have changed size; cell highlights are drawn per
    // render). A plain deselect only has to drop the .selected class —
    // same cheap path selectNode uses — instead of tearing down and
    // rebuilding every node, connector and photo thumbnail on the map
    // just because the empty background was pressed.
    if (hadEditing || hadCellState) renderAll();
    else updateSelectedClasses(prevSelectedId, null);
  }

  viewportEl.addEventListener("mousedown", (e) => {
    if (e.target.closest(".node") || e.target.closest("#node-fabs")) return;
    startPan(e.clientX, e.clientY);
  });

  // Touch handling for pan/pinch-zoom lives separately from the mouse path
  // above rather than trying to reuse mousedown, since touch needs to
  // recognize a *second* finger landing (anywhere, including on top of a
  // node) as the start of a pinch. This listener runs in the capture phase
  // so it always sees every touch inside the viewport even though a node's
  // own pointerdown handler (bubble phase, see beginNodeDrag) stops
  // propagation for its own purposes.
  viewportEl.addEventListener("pointerdown", (e) => {
    if (e.pointerType !== "touch") return;
    activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (activePointers.size === 2) {
      // Second finger down — cleanly end whatever single-finger gesture
      // (pan or node drag) the first finger had already started, then
      // switch entirely to pinch-zoom.
      finishInteraction();
      const pts = Array.from(activePointers.values());
      const dist = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
      const midX = (pts[0].x + pts[1].x) / 2, midY = (pts[0].y + pts[1].y) / 2;
      const rect = viewportEl.getBoundingClientRect();
      pinchState = {
        startDist: dist,
        startScale: state.scale,
        // World-space point currently under the pinch midpoint — held
        // fixed under the fingers as they move, the same way the wheel
        // zoom below keeps the point under the cursor fixed.
        anchorX: (midX - rect.left - state.tx) / state.scale,
        anchorY: (midY - rect.top - state.ty) / state.scale
      };
    } else if (activePointers.size === 1 && !e.target.closest(".node") && !e.target.closest("#node-fabs")) {
      startPan(e.clientX, e.clientY);
    }
  }, { capture: true });

  function handleMoveAt(e) {
    if (panning) {
      state.tx = panStart.tx + (e.clientX - panStart.x);
      state.ty = panStart.ty + (e.clientY - panStart.y);
      applyTransform();
      return;
    }
    if (!dragCandidate) return;
    const node = findNode(dragCandidate.id);
    if (!node) { dragCandidate = null; return; }
    const dxScreen = e.clientX - dragCandidate.startClientX;
    const dyScreen = e.clientY - dragCandidate.startClientY;
    if (!dragCandidate.moved) {
      if (Math.hypot(dxScreen, dyScreen) < DRAG_THRESHOLD) return;
      dragCandidate.moved = true;
      pushUndo();
      const div = nodesLayer.querySelector(`.node[data-id="${node.id}"]`);
      // Cache the dragged node's own div and every descendant's div once,
      // here, rather than re-querying the DOM on every mousemove — the
      // per-frame handler below only ever touches these cached elements.
      dragCandidate.div = div;
      dragCandidate.descendants.forEach(d => {
        d.div = nodesLayer.querySelector(`.node[data-id="${d.id}"]`);
        // Descendants ride along via the same live-drag transform as the
        // dragged node itself (see the mousemove handler) but don't carry
        // the .dragging class that gives it a will-change hint — set it
        // directly so the whole branch gets promoted to the compositor,
        // not just the node under the cursor.
        if (d.div) d.div.style.willChange = "transform";
      });
      if (div) {
        div.classList.add("dragging");
        // The dragged box always sits right under the cursor, so without
        // this, elementFromPoint below would just find itself and never
        // the node underneath it that it's about to be dropped onto.
        div.style.pointerEvents = "none";
      }
    }
    const dxLocal = dxScreen / state.scale;
    const dyLocal = dyScreen / state.scale;
    node.ox = dragCandidate.startOx + dxLocal;

    // Flip immediately if this drag just carried the node across the
    // center line — see maybeFlipSideDuringDrag for how it keeps the node
    // under the cursor and lets its children reflow to the new side right
    // away, while the mouse is still held.
    const flippedH = maybeFlipSideDuringDrag(node, dxLocal, dyLocal);
    // Same idea, but for a top-level Timeline branch crossing above/below
    // the root along the vertical spine (see maybeFlipVSideDuringDrag).
    const flippedV = maybeFlipVSideDuringDrag(node, dxLocal, dyLocal);
    const flipped = flippedH || flippedV;

    // Where the node "wants" to be vertically, tracked from the drag start
    // rather than from node._y directly, so it stays correct across any
    // sibling reorder that happens below.
    const targetAbsY = dragCandidate.startAbsY + dyLocal;
    const reordered = maybeReorderSiblings(node, targetAbsY);
    node.oy = targetAbsY - node._y;

    if (reordered || flipped) {
      // Sibling order or side changed — everyone needs a fresh layout pass,
      // not just this node, so the siblings/descendants that shifted are
      // actually redrawn. repositionAll(true) re-runs layout but moves
      // existing DOM elements in place rather than wiping and recreating
      // them (that full rebuild is what caused the visible blink crossing
      // the center line), and keeps the canvas origin frozen so unrelated
      // nodes — like the dragged node's parent or the root — don't visibly
      // shift just because the bounding box changed shape mid-drag. The
      // canvas gets resized/recentered properly once the drag ends.
      repositionAll(true);
      // repositionAll just wrote fresh left/top for this node (and every
      // descendant, via the loop below) reflecting the FULL delta so far.
      // Any transform left over from the plain-drag path below would now
      // double-count that delta, and the running "baked" total needs to
      // catch up to match, so the next plain-drag frame computes the right
      // remaining delta instead of jumping.
      if (dragCandidate.div) dragCandidate.div.style.transform = "";
      dragCandidate.descendants.forEach(d => { if (d.div) d.div.style.transform = ""; });
      dragCandidate.bakedDx = dxLocal;
      dragCandidate.bakedDy = dyLocal;
    } else {
      // No reorder/flip this frame — the common case on every mousemove.
      // Rewriting left/top here (as updateNodePositionDom does) forces the
      // browser to lay out and repaint the whole node box every frame,
      // including everything rendered inside it — a big photo strip makes
      // that repaint far more expensive, which is exactly what made drags
      // feel unsmooth on photo-heavy nodes. A CSS transform for just the
      // delta since the last full reposition is compositor-only: the node
      // (photos and all) is repainted once, then just moved as a bitmap,
      // so the drag stays smooth regardless of how much is inside the box.
      const tdx = dxLocal - dragCandidate.bakedDx;
      const tdy = dyLocal - dragCandidate.bakedDy;
      const t = `translate(${tdx}px, ${tdy}px)`;
      if (dragCandidate.div) dragCandidate.div.style.transform = t;
      dragCandidate.descendants.forEach(d => { if (d.div) d.div.style.transform = t; });
      // Connector lines are cheap SVG path updates (not affected by photo
      // count), so they still get refreshed every frame for a live feel.
      refreshConnectorsFor(node);
    }

    // Carry every descendant along by the same delta so a branch moves as
    // one rigid unit instead of the parent sliding out from under its kids.
    dragCandidate.descendants.forEach(d => {
      const dNode = findNode(d.id);
      if (!dNode) return;
      dNode.ox = d.startOx + dxLocal;
      dNode.oy = d.startOy + dyLocal;
      if (reordered || flipped) {
        // A full reposition already ran above (using each descendant's
        // pre-update ox/oy) — redo it now that the up-to-date offsets are
        // set, so descendants land exactly on this frame's delta too.
        updateNodePositionDom(dNode);
      } else {
        // Position is already handled by the shared transform above; just
        // keep this descendant's connectors in sync.
        refreshConnectorsFor(dNode);
      }
    });

    // The central node has nowhere to be reparented to, so only offer a
    // drop target for everything else.
    if (findParent(node.id)) updateDropTarget(e, node);
  }
  window.addEventListener("mousemove", handleMoveAt);
  // Touch/pen pointermove: pinch-zoom takes priority whenever two touches
  // are down; otherwise it's the same pan/node-drag handling as mouse.
  //
  // Touch fires pointermove far more often than the screen can actually
  // repaint (many phones sample touch at 90-120+Hz against a 60Hz+
  // display), and every event here does real work — updateDropTarget's
  // elementFromPoint forces a synchronous layout, plus multiple style
  // writes. Running all of that once per raw touch event, rather than
  // once per rendered frame, is what made drags feel laggy on phones:
  // the browser was doing several frames' worth of layout/paint work for
  // a single visible frame. Instead, each raw event just records the
  // latest pointer position; the actual drag/pan/pinch math and DOM
  // writes run at most once per animation frame, via rAF, using only the
  // freshest position. Nothing but a cheap Map/variable write happens
  // outside that rAF callback, so a flurry of touch events between two
  // frames costs almost nothing extra.
  let pendingTouchMoveEvent = null;
  let touchMoveRAF = null;
  function processPendingTouchMove() {
    touchMoveRAF = null;
    const e = pendingTouchMoveEvent;
    pendingTouchMoveEvent = null;
    if (!e) return;
    if (pinchState && activePointers.size === 2) {
      const pts = Array.from(activePointers.values());
      const dist = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
      const midX = (pts[0].x + pts[1].x) / 2, midY = (pts[0].y + pts[1].y) / 2;
      const newScale = clamp(pinchState.startScale * (dist / pinchState.startDist), 0.25, 2.5);
      const rect = viewportEl.getBoundingClientRect();
      state.scale = newScale;
      state.tx = (midX - rect.left) - pinchState.anchorX * newScale;
      state.ty = (midY - rect.top) - pinchState.anchorY * newScale;
      applyTransform();
      return;
    }
    handleMoveAt(e);
  }
  window.addEventListener("pointermove", (e) => {
    if (e.pointerType === "mouse") return;
    // A touch that's still waiting out its hold timer (see the node's
    // pointerdown listener above) and has now moved far enough is a swipe,
    // not a hold-to-drag — cancel the pending node drag and start panning
    // the canvas from here instead, same as a touch that started on empty
    // canvas would.
    if (touchDragArm && touchDragArm.pointerId === e.pointerId) {
      const dx = e.clientX - touchDragArm.startClientX;
      const dy = e.clientY - touchDragArm.startClientY;
      if (Math.hypot(dx, dy) >= TOUCH_DRAG_CANCEL_DIST) {
        const arm = touchDragArm;
        clearTouchDragArm();
        startPan(arm.startClientX, arm.startClientY);
      }
    }
    if (activePointers.has(e.pointerId)) activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    // Keep only clientX/clientY (that's all handleMoveAt/updateDropTarget
    // need) rather than the whole event object, since the browser may
    // reuse/invalidate the event by the time the rAF callback runs.
    pendingTouchMoveEvent = { clientX: e.clientX, clientY: e.clientY };
    if (touchMoveRAF == null) touchMoveRAF = requestAnimationFrame(processPendingTouchMove);
  });
  function finishInteraction() {
    if (panning) { panning = false; viewportEl.classList.remove("panning"); persistViewOnly(); }
    if (dragCandidate) {
      const node = findNode(dragCandidate.id);
      const moved = dragCandidate.moved;
      const dropTargetId = dragCandidate.dropTargetId;
      if (node) {
        const div = nodesLayer.querySelector(`.node[data-id="${node.id}"]`);
        if (div) { div.classList.remove("dragging"); div.style.pointerEvents = ""; div.style.transform = ""; }
      }
      // Clear any leftover live-drag transform (and its will-change hint)
      // on the descendants too — repositionAll/reparentNode below
      // re-establish the real left/top, but neither touches these.
      dragCandidate.descendants.forEach(d => {
        if (d.div) { d.div.style.transform = ""; d.div.style.willChange = ""; }
      });
      if (dropTargetId) {
        const targetDiv = nodesLayer.querySelector(`.node[data-id="${dropTargetId}"]`);
        if (targetDiv) targetDiv.classList.remove("drop-target");
      }
      if (moved && node && dropTargetId) {
        reparentNode(node.id, dropTargetId);
      } else if (moved && node) {
        // Live flip during the drag (see maybeFlipSideDuringDrag) already
        // keeps side in sync on every frame — this only catches the rare
        // case a flip is still needed right at the moment of release.
        const worldXAtDrop = node._x + (node.ox || 0);
        const worldYAtDrop = node._y + (node.oy || 0);
        const flippedH = maybeFlipSideOnDrop(node);
        const flippedV = maybeFlipVSideOnDrop(node);
        if (flippedH || flippedV) {
          layout(state.current.root);
          // Keep the node exactly where it visually was at release instead
          // of letting it jump to the new side's raw slot center.
          node.ox = worldXAtDrop - node._x;
          node.oy = worldYAtDrop - node._y;
        }
        // Deliberately no ox/oy reset here. They're already recomputed
        // fresh on every mousemove to reflect exactly where the node was
        // dragged to relative to its current (possibly reordered or
        // flipped) automatic slot — there's nothing to "clean up". Zeroing
        // them unconditionally used to snap the node onto its slot's raw
        // center on drop, and since whether a reorder happened was tracked
        // with a flag that, once set, never cleared even if a later swing
        // of the drag undid it, a long or fast drag could end up snapping
        // the node all the way back to right where it started.
        //
        // The canvas origin/size was frozen for the whole drag (see
        // repositionAll's freezeOrigin) so nothing not actually moving —
        // like the dragged node's parent or the root — visibly drifted.
        // Now that the drag is over, settle it properly in one shot.
        repositionAll(false);
      }
      dragCandidate = null;
      if (moved) { suppressNextNodeClick = true; persist(); }
    }
  }
  window.addEventListener("mouseup", finishInteraction);
  function onTouchPointerEnd(e) {
    if (e.pointerType === "mouse") return;
    activePointers.delete(e.pointerId);
    // Finger lifted before the hold timer armed a drag — this was just a
    // tap (the click listener already handles that), so drop the pending
    // arm instead of letting a stale timer fire against a released finger.
    if (touchDragArm && touchDragArm.pointerId === e.pointerId) clearTouchDragArm();
    // Drop any move still queued for the next frame — it holds a stale
    // position from before release, and applying it after finishInteraction()
    // below has already cleared dragCandidate/panning could otherwise let a
    // fresh gesture starting on the very next frame briefly see leftover state.
    if (touchMoveRAF != null) { cancelAnimationFrame(touchMoveRAF); touchMoveRAF = null; }
    pendingTouchMoveEvent = null;
    if (pinchState) {
      if (activePointers.size < 2) {
        pinchState = null;
        persistViewOnly();
        if (activePointers.size === 1) {
          // One finger remains down after the pinch ends — resume panning
          // from here instead of leaving the gesture stuck until the next
          // fresh touch.
          const remaining = Array.from(activePointers.values())[0];
          startPan(remaining.x, remaining.y);
        }
      }
      return;
    }
    finishInteraction();
  }
  window.addEventListener("pointerup", onTouchPointerEnd);
  window.addEventListener("pointercancel", onTouchPointerEnd);

  viewportEl.addEventListener("wheel", (e) => {
    if (!state.current) return;
    e.preventDefault();
    const delta = -e.deltaY * 0.0012;
    const newScale = clamp(state.scale * (1 + delta), 0.25, 2.5);
    const rect = viewportEl.getBoundingClientRect();
    const mx = e.clientX - rect.left, my = e.clientY - rect.top;
    const wx = (mx - state.tx) / state.scale, wy = (my - state.ty) / state.scale;
    state.tx = mx - wx * newScale;
    state.ty = my - wy * newScale;
    state.scale = newScale;
    applyTransform();
    persistViewOnly();
  }, { passive: false });

  $("#btn-undo").addEventListener("click", undo);
  $("#btn-redo").addEventListener("click", redo);
  $("#zoom-in").addEventListener("click", () => { state.scale = clamp(state.scale * 1.15, 0.25, 2.5); applyTransform(); persistViewOnly(); });
  $("#zoom-out").addEventListener("click", () => { state.scale = clamp(state.scale / 1.15, 0.25, 2.5); applyTransform(); persistViewOnly(); });
  $("#zoom-reset").addEventListener("click", () => { state.scale = 1; state.tx = 60; state.ty = 60; applyTransform(); persistViewOnly(); });

  // Floating add-child / add-sibling buttons — same effect as the Tab/Enter
  // shortcuts, for anyone who'd rather click (or has no keyboard handy).
  // Falls back to the central node when nothing is selected yet, same as
  // the global Tab/Enter handler above.
  function fabTargetNode() {
    if (!state.current) return null;
    // render: false — the fab click handlers below set state.selectedId /
    // state.editingId for the *new* node right after this returns, then do
    // their own single renderAll(). That renderAll() both commits the DOM
    // change that drops the old node out of edit mode and creates+focuses
    // the new node's div in one pass, instead of two renderAll() passes
    // back-to-back (see commitEditIfActive's comment for why that matters).
    commitEditIfActive({ render: false });
    return (state.selectedId && findNode(state.selectedId)) || state.current.root;
  }
  // Belt-and-suspenders alongside the closest("#node-fabs") checks in the
  // pan-start handlers above: stop the mousedown here too so a click never
  // races a pan-start that would null out state.selectedId first.
  $("#fab-add-child").addEventListener("mousedown", (e) => e.stopPropagation());
  $("#fab-add-sibling").addEventListener("mousedown", (e) => e.stopPropagation());
  $("#fab-add-child").addEventListener("click", () => {
    const node = fabTargetNode();
    if (!node) return;
    const n = addChild(node.id);
    if (n) { state.selectedId = n.id; state.editingId = n.id; renderAll(); }
    persist();
  });
  $("#fab-add-sibling").addEventListener("click", () => {
    const node = fabTargetNode();
    if (!node) return;
    const n = addSibling(node.id);
    if (n) { state.selectedId = n.id; state.editingId = n.id; renderAll(); }
    persist();
  });

  /* ---------------- toolbar ---------------- */

  titleInput.addEventListener("input", () => {
    if (!state.current) return;
    if (!isEditingAllowed()) {
      titleInput.value = state.current.title || "";
      requireSignIn();
      return;
    }
    state.current.title = titleInput.value;
    // Keep the central node's text in sync with the title field, the same
    // way editing the central node itself updates the title (see commitEdit).
    if (state.current.root.text !== titleInput.value) {
      state.current.root.text = titleInput.value;
      renderAll();
    }
    renderSidebar();
    persist();
  });
  titleInput.addEventListener("keydown", (e) => { if (e.key === "Enter") titleInput.blur(); });

  layoutSelect.addEventListener("change", () => {
    if (!state.current) return;
    state.current.layout = layoutSelect.value;
    state.selectedId = null;
    state.selectedCell = null;
    state.cellRangeAnchor = null;
    state.cellRange = null;
    renderAll();
    persist();
  });

  $("#btn-new-map").addEventListener("click", createMap);
  $("#btn-empty-new").addEventListener("click", createMap);
  $("#btn-delete-map").addEventListener("click", () => { if (state.current) deleteMap(state.current.id); });

  // Clears every node's manual drag offset (ox/oy) in one go, so the whole
  // map snaps back to the automatic layout — the fix for branches that have
  // drifted into overlapping each other after being nudged around.
  function autoArrange() {
    if (!state.current) return;
    let touched = false;
    (function check(n) {
      if (n.ox || n.oy) touched = true;
      (n.children || []).forEach(check);
    })(state.current.root);
    if (!touched) return;
    pushUndo();
    (function clear(n) {
      delete n.ox; delete n.oy;
      (n.children || []).forEach(clear);
    })(state.current.root);
    renderAll();
    persist();
  }
  $("#btn-auto-arrange").addEventListener("click", autoArrange);

  $("#btn-help").addEventListener("click", () => zoomModalOpen($("#help-modal")));
  $("#help-close").addEventListener("click", () => zoomModalClose($("#help-modal")));
  $("#help-modal").addEventListener("click", (e) => { if (e.target.id === "help-modal") zoomModalClose(e.currentTarget); });

  $("#btn-export").addEventListener("click", async () => {
    if (!state.current) return;
    const portable = await inlinePhotosForPortableCopy(state.current);
    const blob = new Blob([JSON.stringify(portable, null, 2)], { type: "application/json" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = (state.current.title || "mindmap").replace(/[^a-z0-9\-_]+/gi, "_") + ".json";
    a.click();
    URL.revokeObjectURL(a.href);
  });

  $("#btn-import").addEventListener("click", () => {
    if (!requireSignIn()) return;
    $("#file-import").click();
  });
  $("#file-import").addEventListener("change", async (e) => {
    if (!requireSignIn()) { e.target.value = ""; return; }
    const file = e.target.files[0];
    if (!file) return;
    try {
      const text = await file.text();
      const data = JSON.parse(text);
      if (!data.root || !data.root.id) throw new Error("bad format");
      data.id = uid(); // avoid collisions
      data.updatedAt = Date.now();
      data.trashedAt = null; // an imported map always lands in the active list, never pre-trashed
      ensureTheme(data);
      ensureLayout(data);
      ensureFavorite(data);
      ensureSidesRepaired(data);
      // An imported .json is always the self-contained, inline-photos
      // format (see inlinePhotosForPortableCopy) — pull those bytes into
      // this browser's own photo store now, replacing them with ids.
      await ensurePhotosMigrated(data);
      state.maps.unshift(data);
      sortMaps(state.maps);
      await DB.put(data);
      await FolderDB.save(data);
      await DriveDB.save(data);
      await openMap(data.id);
    } catch (err) {
      alert("Couldn't import that file — it doesn't look like a Branchline map.");
    }
    e.target.value = "";
  });

  /* ---------------- global shortcuts (map list / new) ---------------- */

  document.addEventListener("keydown", (e) => {
    // Was missing TEXTAREA here — only INPUT and contenteditable were
    // excluded, so typing a plain "n" while focused in any <textarea>
    // (the affirmation editor, a photo/video/link comment box, the
    // brainstorm pad, etc.) fell straight through to createMap() below
    // and silently spawned a brand-new blank mindmap mid-sentence. This
    // is what was happening while editing an affirmation, since almost
    // any English or Vietnamese line contains the letter "n" somewhere.
    const activeIsEditable = document.activeElement && (document.activeElement.isContentEditable || document.activeElement.tagName === "INPUT" || document.activeElement.tagName === "TEXTAREA");
    if (activeIsEditable) return;
    // Same reasoning, for modals with no text field to catch it: the note
    // editor, task list, photo/video (YouTube) viewer, trash, storage,
    // etc. — an "n" typed there (nothing focused, or focus on a plain
    // button) fell through the check above and still spawned a new map
    // behind the open modal. Same ".modal:not(.hidden)" guard the global
    // paste handler (further down) already uses, for the same reason.
    if (document.querySelector(".modal:not(.hidden)")) return;
    if (e.key.toLowerCase() === "n" && !e.ctrlKey && !e.metaKey) createMap();
  });

  /* ---------------- theme panel ---------------- */

  const themeModal = $("#theme-modal");
  const bgInput = $("#theme-bg");
  const connectorModeSel = $("#theme-connector-mode");
  const connectorColorInput = $("#theme-connector-color");
  const fontModeSel = $("#theme-font-mode");
  const fontColorInput = $("#theme-font-color");

  function openThemePanel() {
    if (!state.current) return;
    ensureTheme(state.current);
    const t = state.current.theme;
    bgInput.value = t.background || defaultBg();
    connectorModeSel.value = t.connectorMode;
    connectorColorInput.value = t.connectorColor;
    connectorColorInput.disabled = t.connectorMode !== "custom";
    fontModeSel.value = t.fontMode;
    fontColorInput.value = t.fontColor;
    zoomModalOpen(themeModal);
  }


  function updateTheme(patch) {
    if (!state.current) return;
    Object.assign(state.current.theme, patch);
    applyTheme();
    renderAll();
    persist();
  }

  $("#btn-theme").addEventListener("click", openThemePanel);
  $("#theme-close").addEventListener("click", () => zoomModalClose(themeModal));
  themeModal.addEventListener("click", (e) => { if (e.target === themeModal) zoomModalClose(themeModal); });

  /* ---------------- toolbar quote banner ----------------
     Ported from a companion clock/timer page: a short scrolling
     affirmation in the toolbar, picked from (or added to) a small
     editable list, remembered across reloads via localStorage. This is
     separate from the per-node "Affirmation" typing-practice task
     below — that one quizzes you on retyping a line 20 times; this one
     just quietly displays one. Named "quote banner" internally (ids,
     classes, functions) so nothing here collides with that feature's
     own affirmation-* names, even though both surface the word
     "Affirmation" to the user.
     The banner itself is desktop/mouse-only — see
     .toolbar-quote-banner's media query in style.css — so all of this
     simply has nothing to drive on a touch device; the "click" here
     means a real mouse/pen click, never a touch tap.

     Redesigned to one interaction per action instead of a list-plus-a-
     separate-editor-textarea-plus-a-dual-purpose-Save/Add-button: tap a
     line to use it, ✏️ to fix it in place, 🗑 to remove it, one input at
     the top to add a new one. Also collapses storage down to a single
     persisted list (seeded from the defaults once) plus the current
     line's own text — the old scheme re-merged a separate saved list
     against the hardcoded defaults on every read, so editing the text
     of a default line didn't replace it, it silently left the original
     behind and appended the edited text as a second, near-duplicate
     entry every time. */

  const QUOTE_BANNER_LIST_KEY = "branchlineQuoteBannerList_v1";
  const QUOTE_BANNER_CURRENT_KEY = "branchlineQuoteBannerCurrent_v1";

  const DEFAULT_QUOTE_BANNER_LINES = [
    "a successful life start with a successful day",
    "buồn như buồn, vui như vui, phiền não như phiền não",
    "Nó là chính nó",
    "Phiền Não Tức Bồ Đề",
    "ta là cái biết thân tâm hoàn cảnh",
    "tham sân si tức bồ đề",
    "thêm cũng ko được, bớt cũng chẳng xong",
    "Tôi hoàn toàn chấp nhận hiện tại",
    "tôi không muốn thay đổi bất cứ điều gì",
    "trăm triệu hạt mưa ko hạt nào rơi nhầm chỗ",
    "Tri kiến lập tri là gốc của vô minh",
    "Tự Nhiên tâm là đạo",
    "Tôi bình tĩnh, tập trung và làm đúng kế hoạch",
    "Tôi chỉ giao dịch khi có vị trí đẹp và xác suất cao",
    "Tôi kiên nhẫn chờ failure test rõ ràng",
    "Tôi bảo vệ vốn trước, lợi nhuận đến sau",
    "Tôi vào lệnh nhỏ, thoát nhanh, không hy vọng",
    "Tôi làm đúng quy trình, không revenge trade",
    "Tôi đọc thanh khoản, range và phản ứng giá thật chậm rãi"
  ];

  const quoteBannerEl = $("#toolbar-quote-banner");
  const quoteBannerMarquee = $("#quote-banner-marquee");
  const quoteBannerModal = $("#quote-banner-modal");
  const quoteBannerListEl = $("#quote-banner-list");
  const quoteBannerAddInput = $("#quote-banner-add-input");
  let editingQuoteBannerIndex = null; // which row (if any) is mid-inline-edit

  // One persisted list, seeded from the defaults exactly once. After
  // that, this key is the sole source of truth — add/edit/delete all
  // just mutate and re-save this same array, so there's no separate
  // "defaults" copy anywhere else for a saved edit to fall out of sync
  // with.
  function getQuoteBannerLines() {
    try {
      const saved = JSON.parse(localStorage.getItem(QUOTE_BANNER_LIST_KEY));
      if (Array.isArray(saved) && saved.length) return saved;
    } catch (e) {}
    const seeded = DEFAULT_QUOTE_BANNER_LINES.slice();
    saveQuoteBannerLines(seeded);
    return seeded;
  }

  function saveQuoteBannerLines(list) {
    localStorage.setItem(QUOTE_BANNER_LIST_KEY, JSON.stringify(list));
  }

  function applyQuoteBanner(text) {
    const clean = (text || "").trim();
    if (!clean || !quoteBannerMarquee) return;
    quoteBannerMarquee.textContent = clean;
    localStorage.setItem(QUOTE_BANNER_CURRENT_KEY, clean);
  }

  function initQuoteBanner() {
    if (!quoteBannerEl) return;
    const list = getQuoteBannerLines();
    const saved = localStorage.getItem(QUOTE_BANNER_CURRENT_KEY);
    applyQuoteBanner(saved && list.includes(saved) ? saved : list[Math.floor(Math.random() * list.length)]);
  }

  function renderQuoteBannerList() {
    const list = getQuoteBannerLines();
    const current = quoteBannerMarquee ? quoteBannerMarquee.textContent : null;
    quoteBannerListEl.innerHTML = "";
    list.forEach((text, index) => {
      const row = document.createElement("div");
      row.className = "quote-banner-item" + (text === current ? " selected" : "");

      if (index === editingQuoteBannerIndex) {
        const input = document.createElement("input");
        input.type = "text";
        input.className = "quote-banner-item-edit-input";
        input.maxLength = 200;
        input.value = text;
        const commit = () => {
          const val = input.value.trim();
          editingQuoteBannerIndex = null;
          if (val && val !== text) {
            const wasCurrent = text === current;
            list[index] = val;
            saveQuoteBannerLines(list);
            if (wasCurrent) applyQuoteBanner(val);
          }
          renderQuoteBannerList();
        };
        input.addEventListener("keydown", (e) => {
          e.stopPropagation();
          if (e.key === "Enter") { e.preventDefault(); commit(); }
          else if (e.key === "Escape") { e.preventDefault(); editingQuoteBannerIndex = null; renderQuoteBannerList(); }
        });
        input.addEventListener("blur", commit);
        row.appendChild(input);
        quoteBannerListEl.appendChild(row);
        requestAnimationFrame(() => { input.focus(); input.select(); });
        return;
      }

      const label = document.createElement("span");
      label.textContent = text;
      label.title = "Tap to use this line";
      label.addEventListener("click", () => { applyQuoteBanner(text); renderQuoteBannerList(); });

      const editBtn = document.createElement("button");
      editBtn.type = "button";
      editBtn.className = "quote-banner-item-btn";
      editBtn.title = "Edit this line";
      editBtn.setAttribute("aria-label", "Edit this line");
      editBtn.textContent = "✏️";
      editBtn.addEventListener("click", (e) => { e.stopPropagation(); editingQuoteBannerIndex = index; renderQuoteBannerList(); });

      const deleteBtn = document.createElement("button");
      deleteBtn.type = "button";
      deleteBtn.className = "quote-banner-item-btn quote-banner-item-delete";
      deleteBtn.title = "Delete this line";
      deleteBtn.setAttribute("aria-label", "Delete this line");
      deleteBtn.textContent = "🗑";
      deleteBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        const wasCurrent = text === current;
        list.splice(index, 1);
        saveQuoteBannerLines(list);
        if (wasCurrent && list.length) applyQuoteBanner(list[Math.floor(Math.random() * list.length)]);
        renderQuoteBannerList();
      });

      row.append(label, editBtn, deleteBtn);
      quoteBannerListEl.appendChild(row);
    });
  }

  function addQuoteBannerLine() {
    const val = quoteBannerAddInput.value.trim();
    if (!val) return;
    const list = getQuoteBannerLines();
    list.push(val);
    saveQuoteBannerLines(list);
    quoteBannerAddInput.value = "";
    applyQuoteBanner(val);
    renderQuoteBannerList();
  }

  function openQuoteBannerModal() {
    editingQuoteBannerIndex = null;
    quoteBannerAddInput.value = "";
    renderQuoteBannerList();
    zoomModalOpen(quoteBannerModal);
  }

  function randomizeQuoteBanner() {
    const list = getQuoteBannerLines();
    const current = quoteBannerMarquee ? quoteBannerMarquee.textContent : null;
    const others = list.filter((t) => t !== current);
    applyQuoteBanner(others.length ? others[Math.floor(Math.random() * others.length)] : list[0]);
    renderQuoteBannerList();
  }

  if (quoteBannerEl) {
    initQuoteBanner();
    quoteBannerEl.addEventListener("click", openQuoteBannerModal);
    quoteBannerEl.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); openQuoteBannerModal(); }
    });
    $("#quote-banner-add-btn").addEventListener("click", addQuoteBannerLine);
    quoteBannerAddInput.addEventListener("keydown", (e) => {
      e.stopPropagation();
      if (e.key === "Enter") { e.preventDefault(); addQuoteBannerLine(); }
    });
    $("#quote-banner-random").addEventListener("click", randomizeQuoteBanner);
    $("#quote-banner-close").addEventListener("click", () => zoomModalClose(quoteBannerModal));
    quoteBannerModal.addEventListener("click", (e) => { if (e.target === quoteBannerModal) zoomModalClose(quoteBannerModal); });
  }

  /* ---------------- DRC "cards" ---------------- */
  // A DRC note shows each section heading
  // (📊 OVERVIEW, ✅ GOOD, …) and the lines typed under it as one rounded,
  // tinted card — the same look as a colored task row — with a small ring
  // at the heading's right edge that opens a swatch popover to recolor
  // that card.
  //
  // Purely a *decoration* layered on the editor's existing flat line
  // <div>s: nothing is wrapped or moved, so Enter, checklists, undo and
  // every other line-based editing feature keep working exactly as
  // before. Which lines belong to which card is recomputed from position
  // (a card = its heading line + everything up to the next heading), so a
  // line typed under a heading is in that card immediately. Only the
  // chosen color is stored, as a `data-card-color` attribute on the heading
  // line; the classes/CSS variables that draw the card are stripped again
  // before a note/template is saved (see drcStripCardMarkup).
  //
  // Which lines count as headings: any line marked data-card (added with
  // the note editor's card button), and — in a DRC note — any line whose
  // text equals one of the "DRC" note template's lines.
  const DRC_CARD_COLORS = ["#6F94CC", "#5DBB63", "#E84D42", "#F39236", "#756BD1", "#0BC09C", "#E86BB8", "#F2C94C"];
  const DRC_CARD_NEUTRAL = "#9A9A94";
  const DRC_CARD_CLASSES = ["drc-card-line", "drc-card-head", "drc-card-last", "drc-card-gap"];
  const drcCardSig = new WeakMap(); // line element -> last decoration applied (skips redundant DOM writes)

  function drcNorm(s) { return (s || "").replace(/\s+/g, " ").trim(); }
  function drcIsBlankLine(el) {
    return !(el.textContent || "").replace(/[\u200b\u00a0]/g, "").trim() && !(el.querySelector && el.querySelector("img"));
  }
  function drcCardPaint(color) {
    const hex = (color && /^#[0-9a-f]{6}$/i.test(color)) ? color : DRC_CARD_NEUTRAL;
    const r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);
    return { accent: hex, tint: `rgba(${r}, ${g}, ${b}, 0.10)`, strong: `rgba(${r}, ${g}, ${b}, 0.20)` };
  }
  function drcResetLine(el) {
    el.classList.remove(...DRC_CARD_CLASSES);
    el.style.removeProperty("--dc-accent");
    el.style.removeProperty("--dc-tint");
    el.style.removeProperty("--dc-strong");
    if (!el.getAttribute("style")) el.removeAttribute("style");
    if (!el.getAttribute("class")) el.removeAttribute("class");
  }
  // state: null (plain line) or { head, last, gap, color }.
  function drcSetCardState(el, state) {
    const sig = state ? `${state.head ? 1 : 0}${state.last ? 1 : 0}${state.gap ? 1 : 0}|${state.color}` : "none";
    if (drcCardSig.get(el) === sig) return;
    // A plain line that was never decorated: leave its markup completely
    // alone (so opening an ordinary note can't alter its stored HTML).
    if (!state && !el.classList.contains("drc-card-line") && !el.classList.contains("drc-card-gap")
        && (el.getAttribute("style") || "").indexOf("--dc-") === -1) {
      drcCardSig.set(el, sig);
      return;
    }
    drcResetLine(el);
    if (state) {
      if (state.gap) {
        el.classList.add("drc-card-gap");
      } else {
        const p = drcCardPaint(state.color);
        el.classList.add("drc-card-line");
        if (state.head) el.classList.add("drc-card-head");
        if (state.last) el.classList.add("drc-card-last");
        el.style.setProperty("--dc-accent", p.accent);
        el.style.setProperty("--dc-tint", p.tint);
        el.style.setProperty("--dc-strong", p.strong);
      }
    }
    drcCardSig.set(el, sig);
  }

  // The template's own sections as [{ title, color }] — colors come from
  // each line's data-card-color, else a default by position. Used to
  // recognise (and color) the heading lines inside a DRC note.
  function drcTemplateCards() {
    const raw = getDRCTemplateText();
    const found = [];
    if (looksLikeHtml(raw)) {
      const box = document.createElement("div");
      box.innerHTML = raw;
      Array.from(box.childNodes).forEach((n) => {
        if (n.nodeType === 3) {
          const t = drcNorm(n.nodeValue);
          if (t) found.push({ title: t, color: null });
        } else if (n.nodeType === 1) {
          const t = drcNorm(n.textContent);
          if (t) found.push({ title: t, color: n.getAttribute("data-card-color") || null });
        }
      });
    } else {
      raw.split("\n").map(drcNorm).filter(Boolean).forEach((t) => found.push({ title: t, color: null }));
    }
    // While 🎨 auto-color is off, a section with no color of its own
    // (nothing picked via the recolor ring, nothing baked into the
    // template) falls back to neutral instead of the auto-cycled palette —
    // same "off means plain/uniform" rule noteAutoColorParagraphs follows
    // for line text, now applied to card backgrounds too.
    return found.map((c, i) => ({ title: c.title, color: c.color || (noteAutoColorEnabled ? DRC_CARD_COLORS[i % DRC_CARD_COLORS.length] : null) }));
  }

  // mode: "note" (a DRC note: headings are the "DRC" template's lines plus
  // any line marked data-card) | "cards" (any other note that has cards:
  // headings are only the lines marked data-card — see noteAddCard) |
  // null (not a card view: clear it).
  function decorateDRCCards(root, mode) {
    if (!root) return;
    const kids = Array.from(root.children).filter((el) => el.tagName !== "BR");
    if (!mode) {
      root.classList.remove("drc-cards");
      kids.forEach((el) => drcSetCardState(el, null));
      return;
    }
    root.classList.add("drc-cards");
    const titleColor = mode === "note"
      ? new Map(drcTemplateCards().map((c) => [drcNorm(c.title), c.color]))
      : new Map();
    const isHead = (el) => {
      // A card added with the editor's "🗂 Add card" button is marked on
      // the line itself — even while its heading is still blank.
      if (el.hasAttribute("data-card")) return true;
      const t = drcNorm(el.textContent);
      // Otherwise a blank line is never a heading — it belongs to the
      // card above it.
      if (!t) return false;
      return titleColor.has(t);
    };
    let i = 0;
    while (i < kids.length) {
      const head = kids[i];
      if (!isHead(head)) {
        drcSetCardState(head, null);
        // A stray copy of a card color on a non-heading line (the browser
        // can clone attributes when a line is split) has no meaning.
        if (head.hasAttribute("data-card-color")) head.removeAttribute("data-card-color");
        i++;
        continue;
      }
      let j = i + 1;
      while (j < kids.length && !isHead(kids[j])) j++;
      // A color picked on this heading (the ring) wins; otherwise the
      // "DRC" template's color for that section.
      let color = head.getAttribute("data-card-color");
      if (!color) color = titleColor.get(drcNorm(head.textContent));
      // Every line up to the next heading is part of this card — blank
      // ones included. They used to be drawn as a card-less "gap" once past
      // the last filled line, which left the caret outside any card
      // (e.g. right after pressing Enter, before typing anything).
      for (let k = i; k < j; k++) {
        drcSetCardState(kids[k], { head: k === i, last: k === j - 1, color });
      }
      i = j;
    }
  }

  // Removes everything decorateDRCCards adds (classes + CSS variables) from
  // an HTML string, keeping the real content and data-card-color — so a
  // saved note/template is the same as it would have been without cards,
  // and just opening a note never counts as editing it.
  function drcStripCardMarkup(html) {
    if (!html || (html.indexOf("drc-card") === -1 && html.indexOf("--dc-") === -1)) return html;
    const box = document.createElement("div");
    box.innerHTML = html;
    box.querySelectorAll("[class*='drc-card'], [style*='--dc-']").forEach(drcResetLine);
    return box.innerHTML;
  }

  // ---- Card color popover (reuses the task color-dot popover styling) ----
  const drcCardPopover = document.createElement("div");
  drcCardPopover.className = "task-color-popover drc-card-popover hidden";
  let drcCardPopoverPick = null; // callback(color | "none") for the popover's current owner
  (function buildDrcCardPopover() {
    const none = document.createElement("span");
    none.className = "task-color-swatch task-color-swatch-none";
    none.title = "No color";
    none.dataset.color = "none";
    drcCardPopover.appendChild(none);
    PALETTE.forEach((c) => {
      const sw = document.createElement("span");
      sw.className = "task-color-swatch";
      sw.style.background = c;
      sw.dataset.color = c;
      drcCardPopover.appendChild(sw);
    });
    drcCardPopover.addEventListener("mousedown", (e) => { e.preventDefault(); e.stopPropagation(); });
    drcCardPopover.addEventListener("click", (e) => {
      const sw = e.target.closest(".task-color-swatch");
      if (!sw) return;
      e.stopPropagation();
      const pick = drcCardPopoverPick;
      closeDrcCardPopover();
      if (pick) pick(sw.dataset.color);
    });
    document.body.appendChild(drcCardPopover);
    document.addEventListener("mousedown", (e) => {
      if (!drcCardPopover.classList.contains("hidden") && !drcCardPopover.contains(e.target)) closeDrcCardPopover();
    });
  })();
  function closeDrcCardPopover() {
    drcCardPopover.classList.add("hidden");
    drcCardPopoverPick = null;
  }
  function openDrcCardPopover(head, pick) {
    const cur = head.getAttribute("data-card-color");
    drcCardPopover.querySelectorAll(".task-color-swatch").forEach((sw) => {
      sw.classList.toggle("active", sw.dataset.color === cur);
    });
    drcCardPopoverPick = pick;
    drcCardPopover.classList.remove("hidden");
    const margin = 8;
    const r = head.getBoundingClientRect();
    const pop = drcCardPopover.getBoundingClientRect();
    let left = r.right - 34 + 8 - pop.width / 2;
    left = Math.max(margin, Math.min(left, window.innerWidth - pop.width - margin));
    let top = r.top + r.height / 2 + 14;
    if (top + pop.height > window.innerHeight - margin) top = r.top + r.height / 2 - pop.height - 14;
    drcCardPopover.style.left = `${left}px`;
    drcCardPopover.style.top = `${Math.max(margin, top)}px`;
  }

  // The recolor ring is drawn by CSS (::after) on the card's heading line,
  // so there's no real button to click — a click/tap counts as hitting it
  // when it lands on a heading line's right-hand edge.
  function drcCardDotHit(root, e) {
    const head = e.target && e.target.closest ? e.target.closest(".drc-card-head") : null;
    if (!head || head.parentNode !== root) return null;
    const r = head.getBoundingClientRect();
    const cy = r.top + r.height / 2;
    return (e.clientX >= r.right - 38 && e.clientX <= r.right && Math.abs(e.clientY - cy) <= 18) ? head : null;
  }
  // `canEdit()` gates it (a locked note shouldn't be recolorable);
  // `apply(head, color)` writes the color and does whatever refresh/save
  // the owning editor needs.
  function bindDRCCardColorDot(root, canEdit, apply) {
    root.addEventListener("mousedown", (e) => { if (drcCardDotHit(root, e)) e.preventDefault(); });
    root.addEventListener("click", (e) => {
      const head = drcCardDotHit(root, e);
      if (!head || !canEdit()) return;
      e.preventDefault();
      e.stopPropagation();
      openDrcCardPopover(head, (color) => apply(head, color));
    });
    root.addEventListener("mousemove", (e) => {
      root.style.cursor = drcCardDotHit(root, e) ? "pointer" : "";
    });
  }

  /* ---------------- node photo attachments ---------------- */

  // WebP typically renders the same visual quality as JPEG at roughly
  // 25–35% of the file size, so we prefer it wherever the browser can
  // produce it. Feature-detected once (canvas.toDataURL silently falls
  // back to PNG in browsers that don't support the "image/webp" argument,
  // so we check the returned data: URL prefix rather than trusting the
  // call to throw).
  const WEBP_SUPPORTED = (() => {
    try {
      const c = document.createElement("canvas");
      c.width = c.height = 1;
      return c.toDataURL("image/webp", 0.8).startsWith("data:image/webp");
    } catch (e) { return false; }
  })();

  // Central place that decides how a photo canvas gets encoded to a data
  // URL: PNG stays PNG (lossless, whatever the size), everything else
  // goes to WebP (lossless-ish at max quality) if the browser supports
  // it, or JPEG otherwise. `quality` is only used for the lossy formats —
  // callers pass 1.0 so cropping/annotating a photo doesn't add any
  // further compression loss on top of the edit itself.
  function encodePhotoCanvas(canvas, sourceType, pixelCount, quality) {
    if (sourceType === "image/png") return canvas.toDataURL("image/png");
    if (WEBP_SUPPORTED) return canvas.toDataURL("image/webp", quality);
    return canvas.toDataURL("image/jpeg", quality);
  }

  // ---- Zoom-from-icon open/close animation --------------------------
  // Shared by the photo, note, video and link-comment modals: instead of
  // just popping into view, each one grows out of whatever icon/button
  // was clicked to open it, and shrinks back into that same spot on
  // close — like an app icon expanding into its window. Every one of
  // these modals already funnels through a single open*/close* function
  // (openPhotoModal/closePhotoModal, openNoteModal/closeNoteModal, etc.),
  // so the animation lives entirely in those two helpers below rather
  // than needing to touch the many call sites scattered around the file.
  //
  // The origin point comes from the most recent pointerdown anywhere on
  // the page (tracked globally here), since that's whatever icon/marker
  // the user just clicked — no need to thread click coordinates through
  // every caller. Keyboard-triggered opens (no recent click) just fall
  // back to zooming in from the center of the screen.
  let zoomOriginX = null, zoomOriginY = null;
  document.addEventListener("pointerdown", (e) => {
    zoomOriginX = e.clientX;
    zoomOriginY = e.clientY;
  }, true);

  // Skips the animation (and the artificial close delay it needs) for
  // anyone with reduced-motion turned on at the OS level — the CSS above
  // already disables the visual transition for them; this just keeps
  // closing instant to match.
  const MODAL_ZOOM_MS = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches
    ? 0
    : 260; // keep roughly in sync with the CSS transition durations above

  // Shows `modalEl` (a ".modal" backdrop containing one ".modal-card",
  // or another backdrop/card pair — pass `cardSelector` for those, e.g.
  // the calendar day popup's ".day-modal"), animating the card outward
  // from the last click position — the classic iOS "grow from the thing
  // you tapped" pop. With no recent click (keyboard-triggered opens) it
  // falls back to growing from the card's own center, which reads as a
  // plain centered pop/fade — still the same iPhone-style motion, just
  // without a specific origin to grow from.
  /* ---------------- viewer "← Back" navigation ---------------- */
  // The note editor, photo viewer and YouTube player each get a ← Back
  // button. Where it goes depends on where the viewer was opened from:
  //  - a browser (Notes / Photos / Videos / Favorites / Comments / a tag
  //    gallery): the browser is closed to make room for the viewer, so
  //    Back re-opens it with the same folder, search text, tag gallery and
  //    scroll position it had;
  //  - a modal that is still open underneath (Tasks, Calendar, or the note
  //    a photo was clicked in): Back just closes the viewer and that modal
  //    is right there again;
  //  - the map itself (node marker, right-click menu): Back closes the
  //    viewer, which is exactly "back to the node".
  // A caller describes where it came from with a "return point"
  // { label, restore } and hands it over with withViewerReturn(); the
  // viewer's open function picks it up via takeViewerReturn().
  let pendingViewerReturn = null;
  function withViewerReturn(ret, openFn) {
    pendingViewerReturn = ret || null;
    try { openFn(); } finally { pendingViewerReturn = null; }
  }
  function takeViewerReturn() {
    const r = pendingViewerReturn;
    pendingViewerReturn = null;
    return r;
  }
  function runViewerReturn(ret) {
    if (!ret || typeof ret.restore !== "function") return;
    try { ret.restore(); } catch (err) { console.warn("Branchline: couldn't go back to", ret.label, err); }
  }
  function viewerBackTitle(ret) {
    return ret && ret.label ? `Back to ${ret.label}` : "Back to map";
  }
  // "Notes", or "Notes › Work" when a folder is selected in that browser.
  function browserReturnLabel(base, mgr) {
    const sel = mgr && mgr.getSelected();
    if (!sel) return base;
    return `${base} › ${sel === "__unfiled__" ? "Unfiled" : sel}`;
  }
  // Builds the return point for a browser modal. Call it BEFORE closing the
  // browser so the scroll position can still be read. `reopen(true)` must
  // re-open the browser without resetting its search box.
  function makeBrowserReturn(label, listEl, reopen, mgr) {
    const sel = mgr ? mgr.getSelected() : null;
    const top = listEl ? listEl.scrollTop : 0;
    return {
      label: mgr ? browserReturnLabel(label, mgr) : label,
      restore: () => {
        if (mgr) mgr.select(sel);
        reopen(true);
        const apply = () => { if (listEl) listEl.scrollTop = top; };
        apply();
        requestAnimationFrame(apply);
      },
    };
  }
  // A modal that stays open underneath a viewer: Back = just close the
  // viewer, so there's nothing to restore — only a label for the tooltip.
  function underlyingModalReturn() {
    const under = [["#tasks-modal", "Tasks"], ["#calendar-modal", "Calendar"]];
    for (const [sel, label] of under) {
      const el = document.querySelector(sel);
      if (el && !el.classList.contains("hidden")) return { label, restore: null };
    }
    return null;
  }

  function zoomModalOpen(modalEl, cardSelector) {
    if (!modalEl) return;
    clearTimeout(modalEl.__zoomTimer);
    const card = modalEl.querySelector(cardSelector || ".modal-card");
    modalEl.classList.remove("hidden");
    if (card) {
      // Measure the card BEFORE modal-zoom-init's shrink is applied, at
      // its natural full-size position — not after, like this used to.
      // Scaling alone is centered so it wouldn't matter, but the shrink
      // also carries a translate(--zoom-dx, --zoom-dy) offset left over
      // from whatever point this modal last grew from, and that stale
      // offset was still in effect at measurement time — corrupting the
      // very calculation meant to replace it, so every open after the
      // first grew from a progressively wrong spot instead of the click.
      // Measuring here, before that shrink exists at all, sidesteps it.
      const rect = card.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      const ox = zoomOriginX != null ? zoomOriginX : cx;
      const oy = zoomOriginY != null ? zoomOriginY : cy;
      modalEl.style.setProperty("--zoom-dx", (ox - cx) + "px");
      modalEl.style.setProperty("--zoom-dy", (oy - cy) + "px");
    }
    modalEl.classList.add("modal-zoom-init");
    // Force a reflow so the browser paints the shrunk-near-the-icon state
    // from modal-zoom-init before it's removed on the next frame — doing
    // both in the same tick would collapse into one frame and skip the
    // transition entirely.
    void modalEl.offsetWidth;
    requestAnimationFrame(() => modalEl.classList.remove("modal-zoom-init"));
  }

  // Hides `modalEl` the same way in reverse, shrinking back toward
  // whichever point it grew from, then calls `afterHide` (for whatever
  // state cleanup the caller used to do immediately) once it's actually
  // gone. Cleanup is deferred so things like an image's `src` don't
  // disappear mid-animation, leaving nothing left to shrink away.
  function zoomModalClose(modalEl, afterHide) {
    if (!modalEl) { if (afterHide) afterHide(); return; }
    modalEl.classList.add("modal-zoom-init");
    clearTimeout(modalEl.__zoomTimer);
    modalEl.__zoomTimer = setTimeout(() => {
      modalEl.classList.add("hidden");
      modalEl.classList.remove("modal-zoom-init");
      if (afterHide) afterHide();
    }, MODAL_ZOOM_MS);
  }

  // Photos are stored exactly as provided — no downscaling, no lossy
  // re-encoding — so what you attach is byte-for-byte what you get back.
  // Accepts one or more files and appends each as a new photo on the
  // node, rather than replacing whatever is already attached.
  const nodeImageInput = $("#node-image-input");
  const photoModal = $("#photo-modal");
  const photoModalImg = $("#photo-modal-img");
  let pendingPhotoNodeId = null;

  // Generic "grow to fit a paragraph" behavior shared by every comment
  // textarea in the app (video modal's inline box, and the standalone
  // link-comment modal below) — Enter just inserts a newline like any
  // textarea; this only keeps the whole thing visible without an inner
  // scrollbar kicking in early.
  function autoGrowTextarea(el) {
    el.style.height = "auto";
    el.style.height = el.scrollHeight + "px";
  }

  // Embedded YouTube player modal — opened in place of a new tab when a
  // link icon whose URL is a YouTube video/short is clicked (see
  // youtubeVideoId and the urlIcon/linkIcon click handlers). Any other
  // link still opens normally with window.open.
  const videoModal = $("#video-modal");
  const videoModalCard = $(".video-modal-card");
  const videoModalIframe = $("#video-modal-iframe");
  const videoModalOpenLink = $("#video-modal-open-link");
  const videoModalFavoriteBtn = $("#video-modal-favorite");
  const videoModalFolderBtn = $("#video-modal-folder");
  const videoModalMinimizeBtn = $("#video-modal-minimize");
  const videoModalSizeBtn = $("#video-modal-size");
  const videoModalCloseBtn = $("#video-modal-close");
  const videoModalBackBtn = $("#video-modal-back");
  let videoModalReturn = null;
  const videoModalCommentRow = $("#video-modal-comment-row");
  const videoModalCommentInput = $("#video-modal-comment-input");
  const videoModalPhotoStrip = $("#video-modal-photo-strip");
  const videoModalPhotoAddBtn = $("#video-modal-photo-add");
  const videoModalPhotoInput = $("#video-modal-photo-input");
  let videoModalCommentCtx = null;

  // Remembers where each video was last playing, keyed by YouTube video
  // id, so reopening the same video resumes instead of starting over.
  // This lives in localStorage rather than the map's own data (persist())
  // since it's a per-browser playback preference, not part of the map
  // itself — no reason to sync it via Google Drive or undo/redo.
  const YT_POSITIONS_KEY = "branchline:yt-positions";
  function loadYtPositions() {
    try { return JSON.parse(localStorage.getItem(YT_POSITIONS_KEY)) || {}; }
    catch { return {}; }
  }
  function getYtPosition(ytId) {
    return loadYtPositions()[ytId] || 0;
  }
  function saveYtPosition(ytId, seconds) {
    if (!ytId || !Number.isFinite(seconds)) return;
    const positions = loadYtPositions();
    positions[ytId] = Math.max(0, Math.floor(seconds));
    try { localStorage.setItem(YT_POSITIONS_KEY, JSON.stringify(positions)); } catch {}
  }

  // Player size is a per-browser display preference (like the playback
  // position above), not part of the map itself, so it lives in
  // localStorage too and carries over between videos and sessions. The
  // button cycles normal → large → full each click; the CSS for each is
  // on .video-modal-card.size-large / .size-full (see style.css).
  const VIDEO_MODAL_SIZES = ["normal", "large", "full"];
  const VIDEO_MODAL_SIZE_KEY = "branchline:video-modal-size";
  function loadVideoModalSize() {
    const saved = localStorage.getItem(VIDEO_MODAL_SIZE_KEY);
    return VIDEO_MODAL_SIZES.includes(saved) ? saved : "normal";
  }
  function applyVideoModalSize(size) {
    VIDEO_MODAL_SIZES.forEach(s => videoModalCard.classList.remove("size-" + s));
    if (size !== "normal") videoModalCard.classList.add("size-" + size);
    const next = VIDEO_MODAL_SIZES[(VIDEO_MODAL_SIZES.indexOf(size) + 1) % VIDEO_MODAL_SIZES.length];
    const label = size === "normal" ? "Make player bigger" : size === "large" ? "Make player even bigger" : "Back to normal size";
    videoModalSizeBtn.title = label;
    videoModalSizeBtn.setAttribute("aria-label", label);
    videoModalSizeBtn.textContent = size === "full" ? "⤡" : "⤢";
    videoModalSizeBtn.dataset.next = next;
  }
  videoModalSizeBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    const next = videoModalSizeBtn.dataset.next || "large";
    try { localStorage.setItem(VIDEO_MODAL_SIZE_KEY, next); } catch {}
    applyVideoModalSize(next);
  });
  applyVideoModalSize(loadVideoModalSize());

  // "Mini" mode: instead of the normal/large/full sizes above (a centered,
  // backdropped modal), the player shrinks into a small frame docked at
  // the top-right of the window with no backdrop, so the mindmap stays
  // usable underneath while the video keeps playing (see the .video-modal
  // .mini rules in style.css for how clicks pass through everywhere except
  // the little card itself). The size the player was at before minimizing
  // is remembered so un-minimizing restores it exactly.
  let videoModalPreMiniSize = "normal";
  function setVideoModalMini(mini) {
    if (mini === videoModal.classList.contains("mini")) return;
    if (mini) {
      videoModalPreMiniSize = VIDEO_MODAL_SIZES.find(s => videoModalCard.classList.contains("size-" + s)) || "normal";
      VIDEO_MODAL_SIZES.forEach(s => videoModalCard.classList.remove("size-" + s));
    } else {
      applyVideoModalSize(videoModalPreMiniSize);
    }
    videoModal.classList.toggle("mini", mini);
    const label = mini ? "Restore player" : "Minimize player";
    videoModalMinimizeBtn.textContent = mini ? "⤢" : "─";
    videoModalMinimizeBtn.title = label;
    videoModalMinimizeBtn.setAttribute("aria-label", label);
  }
  videoModalMinimizeBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    setVideoModalMini(!videoModal.classList.contains("mini"));
  });

  // Lazily loads the YouTube IFrame Player API — only needed the first
  // time a video is actually opened. A plain <iframe src="...embed/...">
  // (the old approach) has no way to report back the current playback
  // time, so tracking position requires the real player object.
  let ytApiReadyPromise = null;
  function ensureYtApi() {
    if (window.YT && window.YT.Player) return Promise.resolve();
    if (ytApiReadyPromise) return ytApiReadyPromise;
    ytApiReadyPromise = new Promise((resolve) => {
      const prevReady = window.onYouTubeIframeAPIReady;
      window.onYouTubeIframeAPIReady = () => { if (prevReady) prevReady(); resolve(); };
      const tag = document.createElement("script");
      tag.src = "https://www.youtube.com/iframe_api";
      document.head.appendChild(tag);
    });
    return ytApiReadyPromise;
  }

  // One player instance is created and reused across opens (loadVideoById
  // swaps the video in place) rather than tearing it down each time.
  let ytPlayer = null;
  let ytPlayerCurrentId = null;
  let ytSaveTimer = null;
  function startYtSaveTimer() {
    stopYtSaveTimer();
    ytSaveTimer = setInterval(() => {
      if (ytPlayer && ytPlayerCurrentId && typeof ytPlayer.getCurrentTime === "function") {
        try { saveYtPosition(ytPlayerCurrentId, ytPlayer.getCurrentTime()); } catch {}
      }
    }, 4000);
  }
  function stopYtSaveTimer() {
    if (ytSaveTimer) { clearInterval(ytSaveTimer); ytSaveTimer = null; }
  }
  function handleYtStateChange(e) {
    if (!ytPlayerCurrentId) return;
    if (e.data === YT.PlayerState.PAUSED) {
      try { saveYtPosition(ytPlayerCurrentId, ytPlayer.getCurrentTime()); } catch {}
    } else if (e.data === YT.PlayerState.ENDED) {
      // Finished videos resume from the start next time, not the last frame.
      saveYtPosition(ytPlayerCurrentId, 0);
    }
  }

  // Opens the resumable YouTube player modal for a video/short link.
  // (Non-YouTube links no longer use this modal — see openLinkSmart,
  // which now just opens them directly in a new tab.) Kept as its own
  // <iframe> element (video-modal-iframe) so the YouTube player object,
  // once created, can stay attached to its own iframe permanently — swapping that same
  // element's .src to an arbitrary site would leave the player object
  // pointed at a page that no longer understands its postMessage calls.
  async function openVideoModal(url, ytId, commentCtx) {
    // Must be read before the first await — see withViewerReturn.
    const pendingRet = takeViewerReturn();
    if (pendingRet) videoModalReturn = pendingRet;
    else if (videoModal.classList.contains("hidden")) videoModalReturn = null;
    videoModalBackBtn.title = viewerBackTitle(videoModalReturn);
    videoModalBackBtn.setAttribute("aria-label", videoModalBackBtn.title);
    setVideoModalMini(false);
    videoModalOpenLink.href = url;
    videoModalOpenLink.textContent = "Open on YouTube ↗";
    videoModalCommentCtx = commentCtx || null;
    videoModalCommentInput.value = commentCtx ? commentCtx.get() : "";
    videoModalCommentRow.classList.toggle("hidden", !commentCtx);
    renderVideoModalFavorite();
    renderVideoModalFolder();
    renderVideoModalPhotos();
    zoomModalOpen(videoModal);

    videoModalIframe.classList.remove("hidden");

    ytPlayerCurrentId = ytId;
    const startSeconds = getYtPosition(ytId);
    await ensureYtApi();
    // Bail if the modal was closed or switched to a different video while
    // the API script was still loading.
    if (ytPlayerCurrentId !== ytId || videoModal.classList.contains("hidden")) return;

    if (ytPlayer && typeof ytPlayer.loadVideoById === "function") {
      ytPlayer.loadVideoById({ videoId: ytId, startSeconds });
      startYtSaveTimer();
    } else {
      ytPlayer = new YT.Player("video-modal-iframe", {
        videoId: ytId,
        host: "https://www.youtube-nocookie.com",
        playerVars: { autoplay: 1, start: Math.floor(startSeconds), playsinline: 1 },
        events: {
          onReady: () => startYtSaveTimer(),
          onStateChange: handleYtStateChange,
        },
      });
    }
  }
  // Syncs the ☆/★ favorite button to whichever video is currently loaded
  // (see openVideoModal) — hidden when this video's commentCtx doesn't
  // carry favorite accessors (shouldn't normally happen, since every
  // caller of openLinkSmart for a node-level URL supplies them; only a
  // cell-scoped link omits them, and those never reach the video modal
  // today, but this stays defensive rather than assuming so).
  function renderVideoModalFavorite() {
    if (!videoModalCommentCtx || !videoModalCommentCtx.getFavorite) {
      videoModalFavoriteBtn.style.display = "none";
      return;
    }
    videoModalFavoriteBtn.style.display = "";
    const fav = !!videoModalCommentCtx.getFavorite();
    videoModalFavoriteBtn.textContent = fav ? "★" : "☆";
    videoModalFavoriteBtn.classList.toggle("favorited", fav);
    videoModalFavoriteBtn.title = fav ? "Remove from favorites" : "Add to favorites";
    videoModalFavoriteBtn.setAttribute("aria-label", videoModalFavoriteBtn.title);
  }
  videoModalFavoriteBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    if (!videoModalCommentCtx || !videoModalCommentCtx.getFavorite || !videoModalCommentCtx.setFavorite) return;
    pushUndo();
    videoModalCommentCtx.setFavorite(!videoModalCommentCtx.getFavorite());
    persist();
    renderVideoModalFavorite();
    renderVideoModalFolder();
  });
  // Same "📁, dotted when filed" idea as the note/photo viewers — keyed
  // by videoKey (nodeId|url, same shape collectAllVideos uses), which
  // only node-level links carry (see the videoKey additions above) —
  // a cell-scoped link's commentCtx has neither this nor getFavorite,
  // so the button stays hidden there, same split as the favorite star.
  function renderVideoModalFolder() {
    if (!videoModalFolderBtn) return;
    const key = videoModalCommentCtx && videoModalCommentCtx.videoKey;
    videoModalFolderBtn.style.display = key ? "" : "none";
    if (!key) return;
    // Hidden once starred — same reasoning as Notes/Photos:
    // syncVideosFavoriteFolderAssignments (next Videos-browser render)
    // will claim it for Favorite regardless.
    const fav = videoModalCommentCtx.getFavorite && videoModalCommentCtx.getFavorite();
    videoModalFolderBtn.classList.toggle("hidden", !!fav);
    if (fav) return;
    const folder = videosFolderMgr.folderOf(key);
    videoModalFolderBtn.title = folder ? `In folder: ${folder}` : "Move to folder";
    videoModalFolderBtn.classList.toggle("has-folder", !!folder);
  }
  if (videoModalFolderBtn) {
    videoModalFolderBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      const key = videoModalCommentCtx && videoModalCommentCtx.videoKey;
      if (!key) return;
      openFolderMovePopover(videoModalFolderBtn, videosFolderMgr, key, renderVideoModalFolder);
    });
  }
  function closeVideoModal() {
    if (ytPlayer && ytPlayerCurrentId && typeof ytPlayer.getCurrentTime === "function") {
      try { saveYtPosition(ytPlayerCurrentId, ytPlayer.getCurrentTime()); } catch {}
    }
    stopYtSaveTimer();
    if (ytPlayer && typeof ytPlayer.stopVideo === "function") {
      try { ytPlayer.stopVideo(); } catch {} // stop playback
    }
    videoModalCommentCtx = null;
    ytPlayerCurrentId = null;
    videoModalReturn = null;
    zoomModalClose(videoModal);
  }
  videoModalCloseBtn.addEventListener("click", closeVideoModal);
  videoModalBackBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    const ret = videoModalReturn;
    closeVideoModal();
    runViewerReturn(ret);
  });
  videoModal.addEventListener("click", (e) => { if (e.target === videoModal) closeVideoModal(); });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !videoModal.classList.contains("hidden")) closeVideoModal();
  });
  // Saves on blur (clicking/tabbing away) and on Ctrl/Cmd+Enter, same
  // "commit when you're done typing" feel as the rest of the app's plain
  // text inputs — no explicit Save button needed for a single field.
  function saveVideoModalComment() {
    if (!videoModalCommentCtx) return;
    pushUndo();
    videoModalCommentCtx.set(videoModalCommentInput.value);
    persist();
  }
  videoModalCommentInput.addEventListener("blur", saveVideoModalComment);
  videoModalCommentInput.addEventListener("keydown", (e) => {
    e.stopPropagation();
    if ((e.metaKey || e.ctrlKey) && e.key === "Enter") { e.preventDefault(); videoModalCommentInput.blur(); }
  });

  // Photos attached to the video's comment (see getLinkPhotos/addLinkPhoto/
  // removeLinkPhoto and their table-cell equivalents) — a simple thumbnail
  // strip below the comment box. Paste a screenshot straight into the
  // textarea, or use the "+ 📷" button, to attach one; click a thumbnail
  // to open it full-size in a new tab; click its "×" to remove it.
  function renderVideoModalPhotos() {
    videoModalPhotoStrip.querySelectorAll(".video-modal-photo-thumb").forEach((el) => el.remove());
    videoModalPhotoAddBtn.style.display = videoModalCommentCtx && videoModalCommentCtx.addPhoto ? "" : "none";
    if (!videoModalCommentCtx || !videoModalCommentCtx.getPhotos) return;
    const ids = videoModalCommentCtx.getPhotos();
    ids.forEach((id) => {
      const thumb = document.createElement("div");
      thumb.className = "video-modal-photo-thumb";
      thumb.title = "Open full size";
      const img = document.createElement("img");
      img.src = photoUrl(id);
      img.alt = "Attached photo";
      thumb.appendChild(img);
      thumb.addEventListener("click", () => window.open(photoUrl(id), "_blank"));
      if (videoModalCommentCtx.removePhoto) {
        const rm = document.createElement("button");
        rm.type = "button";
        rm.className = "video-modal-photo-thumb-remove";
        rm.textContent = "×";
        rm.title = "Remove photo";
        rm.setAttribute("aria-label", "Remove photo");
        rm.addEventListener("click", (e) => {
          e.stopPropagation();
          if (!videoModalCommentCtx) return;
          pushUndo();
          videoModalCommentCtx.removePhoto(id);
          persist();
          renderVideoModalPhotos();
        });
        thumb.appendChild(rm);
      }
      videoModalPhotoStrip.insertBefore(thumb, videoModalPhotoAddBtn);
    });
  }

  // Reads and attaches one or more image files (from a file picker or a
  // clipboard paste) to the video's comment — downscaling large screenshots
  // first via the same helper the note editor's image paste already uses,
  // so a full-resolution screenshot doesn't bloat the map's saved size.
  function videoModalHandleImageFiles(fileList) {
    if (!videoModalCommentCtx || !videoModalCommentCtx.addPhoto) return;
    const files = Array.from(fileList || []).filter((f) => f && f.type && f.type.startsWith("image/"));
    if (!files.length) return;
    Promise.all(files.map((file) => new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = () => resolve(null);
      reader.readAsDataURL(file);
    })))
      .then((dataUrls) => Promise.all(dataUrls.filter(Boolean).map(downscaleNoteImageDataUrl)))
      .then((dataUrls) => {
        if (!dataUrls.length || !videoModalCommentCtx) return;
        pushUndo();
        dataUrls.forEach((dataUrl) => videoModalCommentCtx.addPhoto(dataUrl));
        persist();
        renderVideoModalPhotos();
      });
  }
  videoModalCommentInput.addEventListener("paste", (e) => {
    const items = e.clipboardData && e.clipboardData.items;
    if (!items) return;
    const imageItems = Array.from(items).filter((item) => item.type && item.type.startsWith("image/"));
    if (!imageItems.length) return;
    e.preventDefault();
    videoModalHandleImageFiles(imageItems.map((item) => item.getAsFile()));
  });
  videoModalPhotoAddBtn.addEventListener("click", () => videoModalPhotoInput.click());
  videoModalPhotoInput.addEventListener("change", () => {
    if (videoModalPhotoInput.files && videoModalPhotoInput.files.length) {
      videoModalHandleImageFiles(videoModalPhotoInput.files);
    }
    videoModalPhotoInput.value = "";
  });

  // Standalone comment editor — opened by the right-click "💬" button on
  // any link icon (see openUrlSingleManageMenu/openCellUrlManageMenu),
  // including non-YouTube links that never touch the video modal above.
  // Same auto-growing paragraph textarea and save-on-blur/Ctrl+Enter
  // behavior as the video modal's inline comment box, just in its own
  // small modal.
  const linkCommentModal = $("#link-comment-modal");
  const linkCommentModalUrl = $("#link-comment-modal-url");
  const linkCommentModalInput = $("#link-comment-modal-input");
  const linkCommentModalCloseBtn = $("#link-comment-modal-close");
  const linkCommentModalFavorite = $("#link-comment-modal-favorite");
  let linkCommentModalCtx = null;
  function renderLinkCommentModalFavorite() {
    if (!linkCommentModalCtx || !linkCommentModalCtx.getFavorite) {
      linkCommentModalFavorite.style.display = "none";
      return;
    }
    linkCommentModalFavorite.style.display = "";
    const fav = !!linkCommentModalCtx.getFavorite();
    linkCommentModalFavorite.textContent = fav ? "★" : "☆";
    linkCommentModalFavorite.classList.toggle("favorited", fav);
    linkCommentModalFavorite.title = fav ? "Remove from favorites" : "Add to favorites";
    linkCommentModalFavorite.setAttribute("aria-label", linkCommentModalFavorite.title);
  }
  function openLinkCommentModal(url, commentCtx) {
    linkCommentModalCtx = commentCtx;
    linkCommentModalUrl.textContent = url;
    linkCommentModalInput.value = commentCtx.get();
    renderLinkCommentModalFavorite();
    zoomModalOpen(linkCommentModal);
    requestAnimationFrame(() => { autoGrowTextarea(linkCommentModalInput); linkCommentModalInput.focus(); });
  }
  function saveLinkCommentModal() {
    if (!linkCommentModalCtx) return;
    pushUndo();
    linkCommentModalCtx.set(linkCommentModalInput.value);
    persist();
  }
  function closeLinkCommentModal() {
    saveLinkCommentModal();
    linkCommentModalCtx = null;
    zoomModalClose(linkCommentModal);
  }
  linkCommentModalFavorite.addEventListener("click", (e) => {
    e.stopPropagation();
    if (!linkCommentModalCtx || !linkCommentModalCtx.setFavorite || !linkCommentModalCtx.getFavorite) return;
    pushUndo();
    linkCommentModalCtx.setFavorite(!linkCommentModalCtx.getFavorite());
    persist();
    renderLinkCommentModalFavorite();
  });
  linkCommentModalCloseBtn.addEventListener("click", closeLinkCommentModal);
  linkCommentModal.addEventListener("click", (e) => { if (e.target === linkCommentModal) closeLinkCommentModal(); });
  linkCommentModalInput.addEventListener("keydown", (e) => {
    e.stopPropagation();
    if ((e.metaKey || e.ctrlKey) && e.key === "Enter") { e.preventDefault(); closeLinkCommentModal(); }
    if (e.key === "Escape") { e.preventDefault(); closeLinkCommentModal(); }
  });
  linkCommentModalInput.addEventListener("input", () => autoGrowTextarea(linkCommentModalInput));

  // Shared by every link click handler (node links, table-cell links):
  // YouTube videos/shorts open in the resumable in-app player modal;
  // every other link opens in its own sized, centered popup window (see
  // openUrlAsPopup below) rather than a plain new tab — so following a
  // link never navigates away from/covers up the mindmap tab itself,
  // letting you browse alongside the map instead of losing your place.
  // `commentCtx` (optional) is a { get, set } pair scoped to that one
  // link's comment (see getLinkComment/setLinkComment and their cell
  // equivalents), letting the modal's comment box read and save without
  // knowing whether the link lives on a node or inside a table cell.
  function openLinkSmart(url, commentCtx) {
    const ytId = youtubeVideoId(url);
    if (!ytId) {
      openUrlAsPopup(url);
      return;
    }
    openVideoModal(url, ytId, commentCtx);
  }

  // Opens a URL in its own sized, centered browser window rather than a
  // plain new tab. Used to open as a chromeless "popup" style window (no
  // address bar/tabs, via the `popup=1` window feature) — now opens as a
  // regular browser window instead (full address bar/back-forward/tabs),
  // just sized and centered smaller than the mindmap's own window so it
  // reads as a companion window rather than covering it up. Ported in-app
  // as a right-click "🪟" action on any node/cell link (see
  // openUrlSingleManageMenu/openCellUrlManageMenu) and as the standalone
  // "🪟 Popup" toolbar button/modal for a URL that isn't attached to any
  // node.
  //
  // Sized as a fraction of the CURRENT browser window (screenX/Y +
  // outerWidth/Height) rather than a fixed 1368×720 — that fixed size
  // used to end up BIGGER than the mindmap window on a smaller screen,
  // which defeated the "keep it smaller than the mindmap" idea. Clamped
  // between a sane minimum (still usable) and a sane maximum (doesn't
  // balloon on a huge monitor).
  function openUrlAsPopup(url) {
    if (!url) return;
    const mmW = window.outerWidth || screen.width;
    const mmH = window.outerHeight || screen.height;
    const w = Math.round(clamp(mmW * 0.5, 480, Math.max(480, mmW - 80)));
    const h = Math.round(clamp(mmH * 0.5, 360, Math.max(360, mmH - 80)));
    const left = Math.max(0, Math.round((window.screenX || 0) + (mmW - w) / 2));
    const top = Math.max(0, Math.round((window.screenY || 0) + (mmH - h) / 2));
    // toolbar=yes/location=yes ask the browser to show its normal
    // navigation bar (back/forward/reload) and address bar on the popup.
    // Any yes/no feature left out of this string is treated as "no" by
    // the window.open spec, which is why the popup used to come up with
    // no way to go back after following a link inside it.
    const features = `width=${w},height=${h},left=${left},top=${top},toolbar=yes,location=yes,noopener`;
    window.open(url, "_blank", features);
  }

  // Standalone "🪟 Popup" toolbar button + modal — a URL box you can type
  // or paste into (auto-filled from the clipboard when available, same
  // as the Popup Link Opener extension it's modeled on) to send any link
  // through openUrlAsPopup() above, even one that isn't attached to any
  // node yet.
  //
  // Everything below is guarded on all the required elements actually
  // existing (see popupOpenerReady) — if index.html/style.css ever lag
  // behind a newer app.js (e.g. only one file got redeployed), this
  // feature just quietly no-ops instead of throwing and taking the rest
  // of boot() down with it, which is a much worse failure mode (missing
  // photos, dead sidebar, etc. that have nothing to do with this feature).
  const popupOpenerBtn = $("#btn-popup-opener");
  const popupOpenerModal = $("#popup-opener-modal");
  const popupOpenerInput = $("#popup-opener-input");
  const popupOpenerOpenBtn = $("#popup-opener-open");
  const popupOpenerBlankBtn = $("#popup-opener-blank");
  const popupOpenerCloseBtn = $("#popup-opener-close");
  const popupOpenerBackBtn = $("#popup-opener-back");
  const popupOpenerClipTag = $("#popup-opener-clip-tag");
  const popupOpenerErrorEl = $("#popup-opener-error");
  const popupOpenerReady = !!(popupOpenerBtn && popupOpenerModal && popupOpenerInput &&
    popupOpenerOpenBtn && popupOpenerBlankBtn && popupOpenerCloseBtn && popupOpenerBackBtn && popupOpenerClipTag && popupOpenerErrorEl);
  if (!popupOpenerReady) {
    console.warn("[Branchline] Popup-opener UI elements missing from index.html — skipping that feature's wiring (app.js/index.html may be out of sync).");
  }

  function normaliseForPopupOpener(s) {
    const trimmed = (s || "").trim();
    if (!trimmed) return "";
    if (/^https?:\/\//i.test(trimmed)) return trimmed;
    if (/^localhost(:\d+)?$|^\d{1,3}(\.\d{1,3}){3}/i.test(trimmed)) return "http://" + trimmed;
    return "https://" + trimmed;
  }
  function isValidPopupOpenerUrl(url) {
    try {
      const u = new URL(url);
      return u.protocol === "http:" || u.protocol === "https:";
    } catch (e) { return false; }
  }
  function showPopupOpenerError(msg) {
    popupOpenerErrorEl.textContent = "⚠ " + msg;
    popupOpenerErrorEl.classList.remove("hidden");
    popupOpenerClipTag.classList.add("hidden");
  }
  function hidePopupOpenerStatus() {
    popupOpenerErrorEl.classList.add("hidden");
    popupOpenerClipTag.classList.add("hidden");
  }

  async function openPopupOpenerModal() {
    hidePopupOpenerStatus();
    popupOpenerInput.value = "";
    zoomModalOpen(popupOpenerModal);
    // Best-effort clipboard auto-fill, same as the extension this is
    // modeled on — quietly does nothing if the browser denies clipboard
    // read (e.g. no permission prompt shown yet, or an insecure origin).
    try {
      const text = (await navigator.clipboard.readText()).trim();
      if (text && isValidPopupOpenerUrl(normaliseForPopupOpener(text))) {
        popupOpenerInput.value = text;
        popupOpenerClipTag.classList.remove("hidden");
      }
    } catch (e) { /* clipboard denied/unavailable — fall through silently */ }
    requestAnimationFrame(() => { popupOpenerInput.focus(); popupOpenerInput.select(); });
  }
  function closePopupOpenerModal() {
    zoomModalClose(popupOpenerModal);
  }
  function openFromPopupOpenerInput() {
    const raw = popupOpenerInput.value.trim();
    if (!raw) { showPopupOpenerError("Please enter a URL"); return; }
    const url = normaliseForPopupOpener(raw);
    if (!isValidPopupOpenerUrl(url)) { showPopupOpenerError("Enter a valid URL (http / https)"); return; }
    hidePopupOpenerStatus();
    openUrlAsPopup(url);
    closePopupOpenerModal();
  }

  if (popupOpenerReady) {
    popupOpenerBtn.addEventListener("click", openPopupOpenerModal);
    popupOpenerOpenBtn.addEventListener("click", openFromPopupOpenerInput);
    popupOpenerInput.addEventListener("keydown", (e) => { e.stopPropagation(); if (e.key === "Enter") openFromPopupOpenerInput(); });
    popupOpenerInput.addEventListener("input", hidePopupOpenerStatus);
    popupOpenerBlankBtn.addEventListener("click", () => { openUrlAsPopup("about:blank"); closePopupOpenerModal(); });
    popupOpenerCloseBtn.addEventListener("click", closePopupOpenerModal);
    popupOpenerBackBtn.addEventListener("click", closePopupOpenerModal);
    popupOpenerModal.addEventListener("click", (e) => { if (e.target === popupOpenerModal) closePopupOpenerModal(); });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && !popupOpenerModal.classList.contains("hidden")) { closePopupOpenerModal(); return; }
      // Ctrl/Cmd+Shift+O — same hotkey as the Popup Link Opener extension.
      // Skipped while typing anywhere (contenteditable/input/textarea) so
      // it can't hijack an "O" typed into a node or field.
      const activeIsTyping = document.activeElement && (
        document.activeElement.isContentEditable ||
        document.activeElement.tagName === "INPUT" ||
        document.activeElement.tagName === "TEXTAREA"
      );
      if (!activeIsTyping && (e.ctrlKey || e.metaKey) && e.shiftKey && e.key.toLowerCase() === "o") {
        e.preventDefault();
        openPopupOpenerModal();
      }
    });
  }

  // Quick-launch toolbar buttons — one-click shortcuts straight to
  // YouTube / Google Docs / Sheets / Photos, each opened via the same
  // openUrlAsPopup() sized/centered popup window as any other link's 🪟
  // action, rather than a plain new tab. Wired defensively (each button
  // is optional) so an index.html that hasn't picked up these buttons
  // yet doesn't break anything else in boot().
  [
    ["#btn-quick-youtube", "https://www.youtube.com/"],
    ["#btn-quick-gdocs", "https://docs.google.com/document/u/0/"],
    ["#btn-quick-gsheets", "https://sheets.google.com/u/0/"],
    ["#btn-quick-gphotos", "https://photos.google.com/"],
  ].forEach(([selector, url]) => {
    const btn = $(selector);
    if (btn) btn.addEventListener("click", () => openUrlAsPopup(url));
  });

  function openNodePhotoPicker(nodeId) {
    if (!requireSignIn()) return;
    pendingPhotoNodeId = nodeId;
    nodeImageInput.click();
  }

  function handleNodePhotoFiles(nodeId, fileList) {
    const node = findNode(nodeId);
    const files = Array.from(fileList || []).filter(f => f && f.type && f.type.startsWith("image/"));
    if (!node || !files.length) return;
    if (!Array.isArray(node.images)) node.images = getNodeImageIds(node);
    pushUndo();
    let remaining = files.length;
    let hadError = false;
    const done = () => {
      remaining--;
      if (remaining === 0) {
        node.image = null; // fully migrated onto the images array
        renderAll();
        persist();
        if (hadError) alert("Some images couldn't be read.");
      }
    };
    files.forEach((file) => {
      const reader = new FileReader();
      reader.onload = () => {
        const id = addPhotoRecord(reader.result, { avoid: getNodeImageIds(node) });
        node.images.push(id);
        setPhotoTimestamp(node, id, Date.now());
        done();
      };
      reader.onerror = () => { hadError = true; done(); };
      reader.readAsDataURL(file);
    });
  }

  nodeImageInput.addEventListener("change", () => {
    if (nodeImageInput.files && nodeImageInput.files.length && pendingPhotoNodeId) {
      handleNodePhotoFiles(pendingPhotoNodeId, nodeImageInput.files);
    }
    nodeImageInput.value = ""; // reset so picking the same file again still fires change
    pendingPhotoNodeId = null;
  });

  // Shared validity check behind all three clipboard-URL detectors below:
  // normalizes a bare host ("youtu.be/xyz" -> "https://youtu.be/xyz"), then
  // requires an http(s) scheme (no javascript:, data:, etc.) and an actual
  // dot in the hostname (skips "https://localhost"-style false positives).
  function validatePasteableUrl(raw) {
    const trimmed = (raw || "").trim();
    if (!trimmed) return null;
    const url = normalizeUrl(trimmed);
    try {
      const parsed = new URL(url);
      if (!/^https?:$/.test(parsed.protocol)) return null;
      if (!parsed.hostname.includes(".")) return null;
      return url;
    } catch (e) {
      return null; // not a URL at all
    }
  }

  // Recognizes clipboard text that's nothing BUT a URL — e.g. a YouTube
  // link typed or copied as plain text — so it can be pasted straight onto
  // a node/cell as a new link, the same "just paste it" shortcut the image
  // branch below gives screenshots. Deliberately conservative: the entire
  // trimmed text must be that one URL — a sentence that merely contains a
  // link, or anything with a second line/word, falls through to ordinary
  // text-paste behavior instead of silently swallowing it as a link.
  function pasteableUrlFromClipboardText(text) {
    const trimmed = (text || "").trim();
    if (!trimmed || /\s/.test(trimmed)) return null;
    return validatePasteableUrl(trimmed);
  }

  // Copying a hyperlinked run of text — e.g. selecting "Watch here" on a
  // page and hitting Ctrl/Cmd+C, or a rich "share" card from another app —
  // puts an <a href> in text/html even though text/plain only carries the
  // link's display text, not its address. Only trusted when the pasted
  // HTML contains exactly one link, so pasting a paragraph with several
  // links in it doesn't guess which one was meant.
  function pasteableUrlFromClipboardHtml(html) {
    if (!html) return null;
    try {
      const doc = new DOMParser().parseFromString(html, "text/html");
      const anchors = doc.querySelectorAll("a[href]");
      if (anchors.length !== 1) return null;
      return validatePasteableUrl(anchors[0].getAttribute("href"));
    } catch (e) {
      return null;
    }
  }

  // Tries every clipboard format a copied link might arrive in, in order
  // of how literally it signals "a link was copied": text/uri-list (what
  // a browser's own "Copy link address" writes), then plain text that's
  // just a bare URL, then a lone <a href> inside pasted HTML. Returns the
  // first one that checks out, or null if the clipboard isn't a link at
  // all — in which case the paste falls through to normal behavior.
  function pasteableUrlFromClipboard(cd) {
    if (!cd) return null;
    const uriList = cd.getData("text/uri-list");
    if (uriList) {
      const line = uriList.split(/\r?\n/).map(s => s.trim()).find(s => s && !s.startsWith("#"));
      const fromUriList = validatePasteableUrl(line);
      if (fromUriList) return fromUriList;
    }
    const fromText = pasteableUrlFromClipboardText(cd.getData("text/plain"));
    if (fromText) return fromText;
    return pasteableUrlFromClipboardHtml(cd.getData("text/html"));
  }

  // Adds a URL straight onto a node with no prompts — the paste-shortcut
  // counterpart to addNodeUrl. Skips both of addNodeUrl's window.prompt
  // calls (there's nothing to prompt for: the URL is already known, and a
  // paste shouldn't stop to ask for a display name) — the link just shows
  // its shortened URL until "Rename link…" is used, same fallback as any
  // link whose title fetch fails.
  function pasteUrlOntoNode(nodeId, url) {
    const node = findNode(nodeId);
    if (!node) return;
    pushUndo();
    const urls = getNodeUrls(node).slice();
    urls.push(url);
    node.urls = urls;
    node.url = null; // fully migrated onto the array field
    setLinkTimestamp(node, url, Date.now());
    renderAll();
    persist();
    fetchLinkTitle(node, url);
  }

  // Same as pasteUrlOntoNode, scoped to a table cell — the paste-shortcut
  // counterpart to addCellUrl.
  function pasteUrlOntoCell(nodeId, r, c, url) {
    const node = findNode(nodeId);
    if (!node) return;
    pushUndo();
    const a = getCellAttach(node, r, c);
    const urls = getCellUrls(a).slice();
    urls.push(url);
    a.urls = urls;
    a.url = null;
    renderAll();
    persist();
    fetchCellLinkTitle(nodeId, r, c, url);
  }

  // Paste a screenshot (or any copied image) straight onto the selected
  // node — or, if a table cell was last clicked (see state.selectedCell/
  // handleCellPhotoFiles), onto that cell instead — as a new photo, no
  // need to save it to disk first and go through "Add photo…". A copied
  // link (a YouTube video, say) gets the same one-step treatment as a new
  // link instead, via pasteableUrlFromClipboard/pasteUrlOntoNode above —
  // covers a raw pasted URL, a browser's "Copy link address", and a
  // hyperlinked run of text copied from a page or another app.
  // Only kicks in when the paste isn't headed for a text field (typing
  // into a node, a cell, a modal, the title bar, etc. — those get to
  // handle their own paste, e.g. the note editor's own image-paste
  // support) and no modal is currently open, so it can't hijack a paste
  // the person meant for something else.
  document.addEventListener("paste", (e) => {
    if (!state.current) return;
    const t = e.target;
    if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable)) return;
    if (document.querySelector(".modal:not(.hidden)")) return;
    const items = e.clipboardData && e.clipboardData.items;
    if (!items) return;
    const imageItem = Array.from(items).find(i => i.type && i.type.startsWith("image/"));
    const file = imageItem && imageItem.getAsFile();
    const url = !file ? pasteableUrlFromClipboard(e.clipboardData) : null;
    if (!file && !url) return;
    if (state.selectedCell) {
      e.preventDefault();
      if (file) handleCellPhotoFiles(state.selectedCell.nodeId, state.selectedCell.r, state.selectedCell.c, [file]);
      else pasteUrlOntoCell(state.selectedCell.nodeId, state.selectedCell.r, state.selectedCell.c, url);
      return;
    }
    if (!state.selectedId || state.editingId) return;
    e.preventDefault();
    if (file) handleNodePhotoFiles(state.selectedId, [file]);
    else pasteUrlOntoNode(state.selectedId, url);
  });

  // Gallery state for the lightbox — which node's photos, and which index.
  let photoModalState = null;
  const photoModalPrev = $("#photo-modal-prev");
  const photoModalNext = $("#photo-modal-next");
  const photoModalCount = $("#photo-modal-count");
  const photoModalDelete = $("#photo-modal-delete");
  const photoModalFolder = $("#photo-modal-folder");
  const photoModalTags = $("#photo-modal-tags");
  const photoModalTagChips = $("#photo-modal-tag-chips");
  const photoModalTagInput = $("#photo-modal-tag-input");
  const photoModalTagSuggest = $("#photo-modal-tag-suggest");
  const photoModalClose = $("#photo-modal-close");
  const photoModalBack = $("#photo-modal-back");
  const photoModalCommentInput = $("#photo-modal-comment-input");
  const photoModalCommentRow = $("#photo-modal-comment-row");
  const photoModalCommentToggle = $("#photo-modal-comment-toggle");
  const photoModalGoto = $("#photo-modal-goto");
  const photoModalZoomIn = $("#photo-modal-zoom-in");
  const photoModalZoomOut = $("#photo-modal-zoom-out");

  // All per-photo action buttons now live in one fixed top-right toolbar
  // (see #photo-modal-toolbar-top in index.html) instead of each being
  // pinned to its own viewport corner or recomputed off the rendered
  // <img> box — so there's nothing here to reposition on load/resize
  // anymore, just a fixed order to insert into.
  const photoModalToolbarTop = $("#photo-modal-toolbar-top");
  const photoModalToolbarBottom = $("#photo-modal-toolbar-bottom");

  // Crop button — built here rather than in index.html so the whole
  // feature lives in this one file. Sits in the shared top-right toolbar
  // alongside close/delete/Aa/🔢/☆.
  const photoModalCrop = document.createElement("button");
  photoModalCrop.id = "photo-modal-crop";
  photoModalCrop.className = "photo-modal-toolbar-btn";
  photoModalCrop.title = "Crop this photo";
  photoModalCrop.setAttribute("aria-label", "Crop this photo");
  photoModalCrop.textContent = "⛶";

  // Text button — Lets the user drop editable labels onto the photo and
  // bake them in.
  const photoModalText = document.createElement("button");
  photoModalText.id = "photo-modal-text";
  photoModalText.className = "photo-modal-toolbar-btn";
  photoModalText.title = "Add text to this photo";
  photoModalText.setAttribute("aria-label", "Add text to this photo");
  photoModalText.textContent = "Aa";
  photoModalText.style.fontSize = "12px";
  photoModalText.style.fontWeight = "700";

  // Symbol button — sits right next to the text button, same styling.
  // Opens a small popover of number-in-circle emoji (1️⃣–9️⃣) that get
  // dropped onto the photo as draggable labels (see startAddText/
  // dropSymbol below), for numbering points directly on the photo.
  const photoModalSymbol = document.createElement("button");
  photoModalSymbol.id = "photo-modal-symbol";
  photoModalSymbol.className = "photo-modal-toolbar-btn";
  photoModalSymbol.title = "Insert a number symbol into the photo";
  photoModalSymbol.setAttribute("aria-label", "Insert a number symbol into the photo");
  photoModalSymbol.textContent = "🔢";

  // Combine button — pastes an image from the clipboard and stitches it
  // onto the top or bottom of the current photo, replacing it with the
  // taller combined result (see combinePhotoFromClipboard below).
  const photoModalCombine = document.createElement("button");
  photoModalCombine.id = "photo-modal-combine";
  photoModalCombine.className = "photo-modal-toolbar-btn";
  photoModalCombine.title = "Paste a photo above, below, left, or right of this one";
  photoModalCombine.setAttribute("aria-label", "Paste a photo above, below, left, or right of this one");
  photoModalCombine.textContent = "⬍";

  // Favorite star — same ☆/★ toggle as the note editor and link/video
  // modals (see toggleNoteFavorite/getPhotoFavorite), sat in the same
  // top-right toolbar as crop/text/symbol. Hidden for an inline note photo
  // (see notePhoto branch in renderPhotoModal below) since there's no
  // per-node attach record backing one of those to star.
  const photoModalFavorite = document.createElement("button");
  photoModalFavorite.id = "photo-modal-favorite";
  photoModalFavorite.className = "photo-modal-toolbar-btn item-star-btn";
  photoModalFavorite.title = "Add to favorites";
  photoModalFavorite.setAttribute("aria-label", "Add to favorites");
  photoModalFavorite.textContent = "☆";

  // Inserted right before the comment toggle (which, along with
  // delete/close, is already in the toolbar in index.html), giving a
  // final left-to-right order of: 🔢, Aa, ⛶, ⬍, ☆, 💬, 🗑, ✕.
  [photoModalSymbol, photoModalText, photoModalCrop, photoModalCombine, photoModalFavorite].forEach(btn => {
    photoModalToolbarTop.insertBefore(btn, photoModalCommentToggle);
  });

  const PHOTO_SYMBOL_CHARS = ["1️⃣", "2️⃣", "3️⃣", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣"];
  const photoModalSymbolPopover = document.createElement("div");
  photoModalSymbolPopover.id = "photo-modal-symbol-popover";
  photoModalSymbolPopover.className = "photo-modal-symbol-popover hidden";
  PHOTO_SYMBOL_CHARS.forEach(ch => {
    const swatch = document.createElement("button");
    swatch.type = "button";
    swatch.className = "photo-modal-symbol-swatch";
    swatch.textContent = ch;
    swatch.addEventListener("mousedown", (e) => e.preventDefault());
    swatch.addEventListener("click", (e) => {
      e.stopPropagation();
      closePhotoSymbolPopover();
      // If the "add text" overlay is already open (from a previous symbol
      // or from the Aa button), just drop another label into that same
      // session instead of restarting the whole placement flow.
      if (addingText && addSymbolToActiveSession) addSymbolToActiveSession(ch);
      else startAddText(ch);
    });
    photoModalSymbolPopover.appendChild(swatch);
  });
  document.body.appendChild(photoModalSymbolPopover);

  function openPhotoSymbolPopover() {
    photoModalSymbolPopover.classList.remove("hidden");
    positionPhotoSymbolPopover();
  }
  function closePhotoSymbolPopover() {
    photoModalSymbolPopover.classList.add("hidden");
  }
  // Same fixed-viewport-coordinates + clamp approach as the note editor's
  // color popover (positionNoteColorPopover) — lives outside the modal
  // card so it's never clipped, and flips above the button if there's
  // not enough room below.
  function positionPhotoSymbolPopover() {
    const margin = 8;
    const btnRect = photoModalSymbol.getBoundingClientRect();
    const popRect = photoModalSymbolPopover.getBoundingClientRect();
    let left = btnRect.left + btnRect.width / 2 - popRect.width / 2;
    left = Math.max(margin, Math.min(left, window.innerWidth - popRect.width - margin));
    let top = btnRect.bottom + 6;
    if (top + popRect.height > window.innerHeight - margin) {
      top = btnRect.top - popRect.height - 6;
    }
    photoModalSymbolPopover.style.left = `${left}px`;
    photoModalSymbolPopover.style.top = `${top}px`;
  }
  photoModalSymbol.addEventListener("mousedown", (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (photoModalSymbolPopover.classList.contains("hidden")) openPhotoSymbolPopover();
    else closePhotoSymbolPopover();
  });
  photoModalSymbolPopover.addEventListener("mousedown", (e) => e.stopPropagation());
  document.addEventListener("mousedown", (e) => {
    if (!photoModalSymbolPopover.classList.contains("hidden") &&
        !photoModalSymbolPopover.contains(e.target) && e.target !== photoModalSymbol) {
      closePhotoSymbolPopover();
    }
  });
  window.addEventListener("resize", () => {
    if (!photoModalSymbolPopover.classList.contains("hidden")) positionPhotoSymbolPopover();
  });

  // ---- Combine (paste a photo above/below/left/right) ----
  // Pick a side, paste an image, and the two are stitched into one larger
  // photo that replaces the current one. Deliberately no other options:
  // above/below stitch vertically, left/right stitch horizontally, always
  // at each image's own native pixel size (nothing is rescaled, so
  // neither half loses detail), and encoded at quality 1.0 through the
  // same encodePhotoCanvas the crop/text tools use.
  //
  // Laid out as a directional pad (a plus sign) rather than a stacked
  // list, so each button's position matches the side it pastes onto —
  // above sits on top, left/right flank the middle, below sits on the
  // bottom — which reads at a glance instead of needing the arrow +
  // label text to spell it out.
  const photoCombinePopover = document.createElement("div");
  photoCombinePopover.id = "photo-modal-combine-popover";
  photoCombinePopover.className = "photo-modal-symbol-popover hidden photo-modal-combine-dpad";
  photoCombinePopover.style.maxWidth = "none";
  photoCombinePopover.style.gridTemplateAreas = '". above ." "left . right" ". below ."';
  photoCombinePopover.style.gridTemplateColumns = "repeat(3, 30px)";
  photoCombinePopover.style.gridTemplateRows = "repeat(3, 30px)";
  photoCombinePopover.style.gap = "4px";
  [["above", "⬆", "Paste above"], ["below", "⬇", "Paste below"], ["left", "⬅", "Paste left"], ["right", "➡", "Paste right"]].forEach(([where, arrow, label]) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "photo-modal-symbol-swatch";
    btn.textContent = arrow;
    btn.title = label;
    btn.setAttribute("aria-label", label);
    btn.style.gridArea = where;
    btn.style.width = "100%";
    btn.style.height = "100%";
    btn.addEventListener("mousedown", (e) => e.preventDefault());
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      closePhotoCombinePopover();
      combinePhotoFromClipboard(where);
    });
    photoCombinePopover.appendChild(btn);
  });
  document.body.appendChild(photoCombinePopover);

  function openPhotoCombinePopover() {
    photoCombinePopover.classList.remove("hidden");
    photoCombinePopover.style.display = "grid";
    positionPhotoCombinePopover();
  }
  function closePhotoCombinePopover() {
    photoCombinePopover.classList.add("hidden");
    photoCombinePopover.style.display = "";
  }
  function positionPhotoCombinePopover() {
    const margin = 8;
    const btnRect = photoModalCombine.getBoundingClientRect();
    const popRect = photoCombinePopover.getBoundingClientRect();
    let left = btnRect.left + btnRect.width / 2 - popRect.width / 2;
    left = Math.max(margin, Math.min(left, window.innerWidth - popRect.width - margin));
    let top = btnRect.bottom + 6;
    if (top + popRect.height > window.innerHeight - margin) top = btnRect.top - popRect.height - 6;
    photoCombinePopover.style.left = `${left}px`;
    photoCombinePopover.style.top = `${top}px`;
  }
  photoModalCombine.addEventListener("mousedown", (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (cropping || addingText) return;
    if (photoCombinePopover.classList.contains("hidden")) openPhotoCombinePopover();
    else closePhotoCombinePopover();
  });
  photoModalCombine.addEventListener("click", (e) => e.stopPropagation());
  photoCombinePopover.addEventListener("mousedown", (e) => e.stopPropagation());
  document.addEventListener("mousedown", (e) => {
    if (!photoCombinePopover.classList.contains("hidden") &&
        !photoCombinePopover.contains(e.target) && e.target !== photoModalCombine) {
      closePhotoCombinePopover();
    }
  });
  window.addEventListener("resize", () => {
    if (!photoCombinePopover.classList.contains("hidden")) positionPhotoCombinePopover();
  });

  // Whichever photo the viewer is showing right now, note-mode or not —
  // the same two places renderPhotoModal itself reads from.
  function currentPhotoModalSrc() {
    if (!photoModalState) return null;
    const images = photoModalState.noteMode
      ? photoModalState.images
      : getNodeImages(findNode(photoModalState.nodeId));
    return images[photoModalState.index] || null;
  }

  function loadImageElement(src) {
    return new Promise((resolve, reject) => {
      const im = new Image();
      im.onload = () => resolve(im);
      im.onerror = () => reject(new Error("could not decode image"));
      im.src = src;
    });
  }
  // (blobToDataUrl — the clipboard/file → data: URL step — already exists
  // up near the photo store; reused here rather than redeclared.)
  // navigator.clipboard.read() is the direct path, but it needs the
  // clipboard-read permission and isn't available at all in some
  // browsers, so a failure here isn't an error — it just means falling
  // back to waiting for a real Ctrl+V (see armCombinePaste).
  async function readClipboardImageDataUrl() {
    if (!navigator.clipboard || !navigator.clipboard.read) return null;
    const items = await navigator.clipboard.read();
    for (const item of items) {
      const type = item.types.find(t => t.startsWith("image/"));
      if (type) return await blobToDataUrl(await item.getType(type));
    }
    return null;
  }

  // Browsers cap canvas dimensions (~32,767px in Chrome/Firefox, lower on
  // some mobiles); past that the canvas silently comes back blank, so
  // refuse rather than replacing a good photo with an empty one.
  const PHOTO_COMBINE_MAX_PX = 32000;

  async function combineTwo(baseSrc, addSrc, where) {
    const [baseImg, addImg] = await Promise.all([loadImageElement(baseSrc), loadImageElement(addSrc)]);
    const vertical = where === "above" || where === "below";
    // For above/below the added image goes first (top) or second (bottom);
    // for left/right the same slot logic applies along the horizontal axis.
    const first = (where === "above" || where === "left") ? addImg : baseImg;
    const second = (where === "above" || where === "left") ? baseImg : addImg;
    const width = vertical
      ? Math.max(first.naturalWidth, second.naturalWidth)
      : first.naturalWidth + second.naturalWidth;
    const height = vertical
      ? first.naturalHeight + second.naturalHeight
      : Math.max(first.naturalHeight, second.naturalHeight);
    if (height > PHOTO_COMBINE_MAX_PX || width > PHOTO_COMBINE_MAX_PX) {
      throw new Error(`The combined photo would be too ${vertical ? "tall" : "wide"} for the browser to render.`);
    }
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");
    // Only stays lossless/transparent when BOTH halves are PNG; otherwise
    // the result goes out as WebP/JPEG, where transparency wouldn't
    // survive anyway, so any size difference is padded white instead of
    // left as black.
    const isPng = baseSrc.startsWith("data:image/png") && addSrc.startsWith("data:image/png");
    if (!isPng) {
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(0, 0, width, height);
    }
    // Each half is drawn at 1:1 and centered on the cross-axis, so the
    // smaller one gets padding rather than being stretched to match.
    if (vertical) {
      ctx.drawImage(first, Math.round((width - first.naturalWidth) / 2), 0);
      ctx.drawImage(second, Math.round((width - second.naturalWidth) / 2), first.naturalHeight);
    } else {
      ctx.drawImage(first, 0, Math.round((height - first.naturalHeight) / 2));
      ctx.drawImage(second, first.naturalWidth, Math.round((height - second.naturalHeight) / 2));
    }
    return encodePhotoCanvas(canvas, isPng ? "image/png" : "image/jpeg", width * height, 1.0);
  }

  // Swaps the photo the viewer is currently showing for `outUrl`, keeping
  // its tags/notes/comment/star/timestamp attached — the same hand-off
  // the crop and add-text tools do when they bake their edit in.
  function replacePhotoModalImage(outUrl) {
    if (!photoModalState) return;
    if (photoModalState.noteMode) {
      const noteImgs = Array.from(noteTextarea.querySelectorAll("img"));
      const targetImg = noteImgs[photoModalState.index];
      let oldId = null;
      if (targetImg) {
        // A combined image is a fresh picture, not the original one with a
        // few pixels changed — same "always a new id" rule crop/text/
        // combine use for a node's own photos (see the noDedupe below and
        // its counterpart in the non-note branch), so it gets its own
        // PhotoDB record rather than dedup'ing against the original.
        const newId = addPhotoRecord(outUrl, { noDedupe: true });
        oldId = targetImg.dataset.photoId;
        targetImg.dataset.photoId = newId;
        targetImg.src = photoUrl(newId);
      }
      photoModalState.images[photoModalState.index] = outUrl;
      // Commit first, so the node's own stored notes drop the old id
      // before deletePhotoRecord checks whether anything still
      // references it — otherwise the still-unsaved old reference would
      // make it look referenced and the swap would leak that copy.
      commitNotesToNode();
      if (oldId) deletePhotoRecord(oldId);
    } else {
      const liveNode = findNode(photoModalState.nodeId);
      const liveIds = getNodeImageIds(liveNode);
      if (!liveIds.length) return;
      pushUndo();
      const newId = addPhotoRecord(outUrl, { noDedupe: true });
      const oldId = liveIds[photoModalState.index];
      carryPhotoTags(liveNode, liveNode, [[oldId, newId]]);
      carryPhotoNotes(liveNode, liveNode, [[oldId, newId]]);
      carryPhotoComments(liveNode, liveNode, [[oldId, newId]]);
      carryPhotoFavorites(liveNode, liveNode, [[oldId, newId]]);
      carryPhotoTimestamps(liveNode, liveNode, [[oldId, newId]]);
      setPhotoTags(liveNode, oldId, null);
      setPhotoNotes(liveNode, oldId, null);
      setPhotoComment(liveNode, oldId, null);
      setPhotoTimestamp(liveNode, oldId, null);
      liveIds[photoModalState.index] = newId;
      liveNode.images = liveIds;
      liveNode.image = null;
      deletePhotoRecord(oldId); // after the old reference is gone, so a shared id is kept if another node still uses it
      renderAll();
      persist();
    }
    resetPhotoZoom();
    renderPhotoModal();
  }

  let combiningPhoto = false;
  // Set while waiting for a manual Ctrl+V: which side the pasted image
  // should land on. Cleared by the paste itself, by Escape, or by the
  // photo viewer closing.
  let pendingCombineSide = null;

  function armCombinePaste(where) {
    pendingCombineSide = where;
    showToast(`Press Ctrl+V (⌘V) to paste the photo to add ${where}`);
  }
  function cancelCombinePaste() {
    pendingCombineSide = null;
  }

  async function applyCombine(addSrc, where) {
    const baseSrc = currentPhotoModalSrc();
    if (!baseSrc) return;
    combiningPhoto = true;
    photoModalCombine.disabled = true;
    try {
      replacePhotoModalImage(await combineTwo(baseSrc, addSrc, where));
      showToast(`Photo added ${where}`);
    } catch (err) {
      showToast(err && err.message ? err.message : "Couldn't combine those photos.");
    } finally {
      combiningPhoto = false;
      photoModalCombine.disabled = false;
    }
  }

  async function combinePhotoFromClipboard(where) {
    if (combiningPhoto || cropping || addingText || !photoModalState) return;
    if (!currentPhotoModalSrc()) return;
    let addSrc = null;
    try {
      addSrc = await readClipboardImageDataUrl();
    } catch (err) {
      addSrc = null; // permission denied or unsupported — fall through to Ctrl+V
    }
    if (!addSrc) { armCombinePaste(where); return; }
    await applyCombine(addSrc, where);
  }

  // The manual Ctrl+V path. Only ever does anything while a side is armed
  // and the photo viewer is open, so it can't hijack pasting elsewhere.
  document.addEventListener("paste", (e) => {
    if (!pendingCombineSide || !photoModalState || combiningPhoto) return;
    const items = e.clipboardData ? Array.from(e.clipboardData.items || []) : [];
    const imageItem = items.find(it => it.type && it.type.startsWith("image/"));
    if (!imageItem) return;
    const file = imageItem.getAsFile();
    if (!file) return;
    e.preventDefault();
    e.stopPropagation();
    const where = pendingCombineSide;
    cancelCombinePaste();
    blobToDataUrl(file).then(src => applyCombine(src, where))
      .catch(() => showToast("Couldn't read the pasted image."));
  }, true);

  let cropping = false;
  let cropCleanup = null;
  let addingText = false;
  let textCleanup = null;
  let rearmTextPlacement = null;
  // Set while the "add text" overlay is open, to a function that drops a
  // new symbol label onto the photo (see photoModalSymbol below) without
  // having to re-enter the whole placement flow.
  let addSymbolToActiveSession = null;

  // ---- Scroll-to-zoom on the photo preview ----
  // A separate pan/zoom of just the currently displayed photo (independent
  // of the mindmap canvas's own zoom) — scroll to zoom in/out toward the
  // cursor, drag to pan around once zoomed in. Resets whenever a different
  // photo is shown, or the modal is closed.
  let photoZoom = { scale: 1, tx: 0, ty: 0 };
  const PHOTO_ZOOM_MIN = 1, PHOTO_ZOOM_MAX = 6;

  // Set while the add-text overlay is open, so that overlay can re-apply
  // the exact same transform to itself and stay glued to the photo — the
  // whole point being that you can zoom right into a detail and drop a
  // small label precisely on it, instead of the tool snapping back to 1x.
  let onPhotoZoomChange = null;

  function applyPhotoZoom() {
    photoModalImg.style.transform = photoZoom.scale === 1
      ? ""
      : `translate(${photoZoom.tx}px, ${photoZoom.ty}px) scale(${photoZoom.scale})`;
    photoModalImg.classList.toggle("zoomed", photoZoom.scale > 1);
    if (onPhotoZoomChange) onPhotoZoomChange();
  }

  // Cursor-anchored zoom step, shared by the image's own wheel handler and
  // by the add-text overlay's (which sits on top of the image and would
  // otherwise swallow the wheel events before they ever reached it).
  function zoomPhotoAtPoint(clientX, clientY, deltaY) {
    const rect = photoModalImg.getBoundingClientRect();
    // Cursor's offset from the image's current (already zoomed/panned)
    // on-screen center — used to keep the point under the cursor fixed
    // as the scale changes, so zooming feels anchored to the mouse
    // rather than always zooming toward the photo's center.
    const offX = clientX - (rect.left + rect.width / 2);
    const offY = clientY - (rect.top + rect.height / 2);
    const prevScale = photoZoom.scale;
    const delta = -deltaY * 0.0018;
    const newScale = clamp(prevScale * (1 + delta), PHOTO_ZOOM_MIN, PHOTO_ZOOM_MAX);
    if (newScale === prevScale) return;
    const factor = newScale / prevScale;
    photoZoom.tx += offX * (1 - factor);
    photoZoom.ty += offY * (1 - factor);
    photoZoom.scale = newScale;
    if (photoZoom.scale === PHOTO_ZOOM_MIN) { photoZoom.tx = 0; photoZoom.ty = 0; }
    applyPhotoZoom();
  }
  function resetPhotoZoom() {
    photoZoom = { scale: 1, tx: 0, ty: 0 };
    applyPhotoZoom();
  }

  photoModalImg.draggable = false; // don't fight our own pan drag with the browser's native image-drag
  photoModalImg.addEventListener("wheel", (e) => {
    if (!photoModalState || cropping || addingText) return;
    e.preventDefault();
    e.stopPropagation();
    zoomPhotoAtPoint(e.clientX, e.clientY, e.deltaY);
  }, { passive: false });

  // Drag to pan once zoomed in — only kicks in above 1x so a plain click
  // still behaves normally (e.g. not stealing the click-outside-to-close).
  let photoPanState = null;
  photoModalImg.addEventListener("mousedown", (e) => {
    if (!photoModalState || cropping || addingText || photoZoom.scale <= 1) return;
    e.preventDefault();
    e.stopPropagation();
    photoPanState = { startX: e.clientX, startY: e.clientY, tx: photoZoom.tx, ty: photoZoom.ty };
    photoModalImg.classList.add("panning");
  });
  window.addEventListener("mousemove", (e) => {
    if (!photoPanState) return;
    photoZoom.tx = photoPanState.tx + (e.clientX - photoPanState.startX);
    photoZoom.ty = photoPanState.ty + (e.clientY - photoPanState.startY);
    applyPhotoZoom();
  });
  window.addEventListener("mouseup", () => {
    if (!photoPanState) return;
    photoPanState = null;
    photoModalImg.classList.remove("panning");
  });
  // Double-click to jump back to 1x, since there's no on-screen zoom
  // control otherwise (scroll is the only way in).
  photoModalImg.addEventListener("dblclick", (e) => {
    if (!photoModalState || cropping || addingText) return;
    e.stopPropagation();
    resetPhotoZoom();
  });

  // `tagGroup` (optional): { label, items: [{nodeId, id}, ...] }. When
  // present, the modal's prev/next step through every photo sharing that
  // tag across the whole map instead of just this node's own photos —
  // used when opening a photo from the tag browser's "Go to node".
  function openPhotoModal(nodeId, index, tagGroup) {
    const node = findNode(nodeId);
    const images = getNodeImages(node);
    if (!images.length) return;
    const clampedIndex = clamp(index || 0, 0, images.length - 1);
    let tagIndex = 0;
    if (tagGroup && tagGroup.items && tagGroup.items.length) {
      const id = getNodeImageIds(node)[clampedIndex];
      const found = tagGroup.items.findIndex(it => it.nodeId === nodeId && it.id === id);
      tagIndex = found >= 0 ? found : 0;
    }
    photoModalState = {
      nodeId,
      index: clampedIndex,
      tagGroup: (tagGroup && tagGroup.items && tagGroup.items.length) ? tagGroup : null,
      tagIndex,
      // Where ← Back goes — see withViewerReturn. Kept on the state so it
      // survives stepping through the group with prev/next.
      ret: takeViewerReturn() || underlyingModalReturn(),
    };
    resetPhotoZoom();
    renderPhotoModal();
    zoomModalOpen(photoModal);
  }
  function renderPhotoModal() {
    if (!photoModalState) return;
    photoModalBack.title = viewerBackTitle(photoModalState.ret);
    photoModalBack.setAttribute("aria-label", photoModalBack.title);
    const images = photoModalState.noteMode
      ? photoModalState.images
      : getNodeImages(findNode(photoModalState.nodeId));
    if (!images.length) { closePhotoModal(); return; }
    if (photoModalState.index >= images.length) photoModalState.index = images.length - 1;
    photoModalImg.src = images[photoModalState.index];
    const group = photoModalState.tagGroup;
    photoModalGoto.classList.toggle("hidden", !group);
    if (group) {
      const n = group.items.length;
      const multi = n > 1;
      photoModalPrev.classList.toggle("hidden", !multi);
      photoModalNext.classList.toggle("hidden", !multi);
      photoModalCount.classList.toggle("hidden", !multi);
      photoModalCount.textContent = multi ? `${photoModalState.tagIndex + 1} / ${n} · ${group.label}` : "";
    } else {
      const multi = images.length > 1;
      photoModalPrev.classList.toggle("hidden", !multi);
      photoModalNext.classList.toggle("hidden", !multi);
      photoModalCount.classList.toggle("hidden", !multi);
      photoModalCount.textContent = multi ? `${photoModalState.index + 1} / ${images.length}` : "";
    }
    // Tags, comments, crop, and favoriting all read/write a per-photo
    // record keyed by an id that only exists for photos actually
    // attached to a node (see getPhotoTags/getPhotoComment etc.) — an
    // image just pasted inline into a note has no such record, so those
    // controls are hidden rather than rendered against a missing node.
    // The text-label tool (and its number-symbol shortcut) is the
    // exception: it bakes the label straight into the photo's pixels and
    // writes the result back into the note's own HTML (see startAddText
    // and its noteMode branch below), so it works here too.
    const notePhoto = !!photoModalState.noteMode;
    photoModalTags.style.display = notePhoto ? "none" : "";
    photoModalCommentRow.style.display = notePhoto ? "none" : "";
    photoModalDelete.style.display = notePhoto ? "none" : "";
    if (photoModalFolder) photoModalFolder.style.display = notePhoto ? "none" : "";
    photoModalCrop.style.display = notePhoto ? "none" : "";
    photoModalText.style.display = "";
    photoModalSymbol.style.display = "";
    // Combine works in note mode too: like the text tool, it bakes a new
    // image and writes it straight back (see replacePhotoModalImage).
    photoModalCombine.style.display = "";
    photoModalFavorite.style.display = notePhoto ? "none" : "";
    closePhotoSymbolPopover();
    closePhotoCombinePopover();
    if (notePhoto) return;
    renderPhotoModalTags();
    renderPhotoModalComment();
    renderPhotoModalFavorite();
    updatePhotoModalFolderUI();
  }

  // Same 📁-with-a-dot idea as the note editor's folder button — see
  // updateNoteFolderUI — keyed by the photo's own id (getNodeImageIds),
  // the same id the Photos browser files it under.
  function updatePhotoModalFolderUI() {
    if (!photoModalFolder || !photoModalState || photoModalState.noteMode) return;
    const node = findNode(photoModalState.nodeId);
    const id = node && getNodeImageIds(node)[photoModalState.index];
    // Hidden once starred — same reasoning as the Photos browser's own
    // rows: syncPhotosFavoriteFolderAssignments (which runs the next
    // time the Photos browser itself renders) will claim this photo for
    // Favorite regardless, so offering a manual choice here would just
    // be undone.
    const fav = id && getPhotoFavorite(node, id);
    photoModalFolder.classList.toggle("hidden", !!fav);
    if (fav) return;
    const folder = id ? photosFolderMgr.folderOf(id) : null;
    photoModalFolder.title = folder ? `In folder: ${folder}` : "Move to folder";
    photoModalFolder.classList.toggle("has-folder", !!folder);
  }

  // Syncs the ☆/★ favorite button to match whichever photo is currently
  // shown — called whenever the visible photo changes (see
  // renderPhotoModal) so stepping through the gallery doesn't leave one
  // photo's star showing on a different photo.
  function renderPhotoModalFavorite() {
    if (!photoModalState || photoModalState.noteMode) return;
    const node = findNode(photoModalState.nodeId);
    const id = getNodeImageIds(node)[photoModalState.index];
    const fav = getPhotoFavorite(node, id);
    photoModalFavorite.textContent = fav ? "★" : "☆";
    photoModalFavorite.classList.toggle("favorited", fav);
    photoModalFavorite.title = fav ? "Remove from favorites" : "Add to favorites";
    photoModalFavorite.setAttribute("aria-label", photoModalFavorite.title);
  }

  // Opens the same lightbox used for a node's attached photos, but for an
  // image pasted/inserted directly inline into the note editor instead —
  // clicking any photo in a note shows it full-size here, with prev/next
  // stepping through the other images in that same note if there are
  // more than one. Tags/comments/crop/delete don't apply (see the
  // notePhoto branch in renderPhotoModal above) since there's no
  // per-node attach record backing an inline note image.
  function openNotePhotoViewer(imgEl, container = noteTextarea) {
    const imgs = Array.from(container.querySelectorAll("img"));
    const index = imgs.indexOf(imgEl);
    if (index < 0) return;
    photoModalState = {
      noteMode: true,
      images: imgs.map(im => im.src),
      index,
      ret: { label: "note", restore: null }, // the note editor is still open underneath
    };
    // The note editor's modal is deliberately raised above the shared
    // modal z-index (see #note-modal in style.css) so it can be opened
    // on top of the tasks/calendar modals — which otherwise leaves it
    // sitting on top of the photo viewer too, covering up the very photo
    // just clicked. This class bumps the photo modal one level above
    // that for just this flow; removed again on close.
    photoModal.classList.add("photo-modal-above-note");
    resetPhotoZoom();
    renderPhotoModal();
    zoomModalOpen(photoModal);
  }
  // Fills the comment box with whichever photo is currently shown, same
  // auto-growing paragraph textarea as the video modal's inline comment
  // box (see autoGrowTextarea) — called whenever the visible photo
  // changes so stepping through the gallery doesn't leave one photo's
  // comment showing under a different photo.
  function renderPhotoModalComment() {
    if (!photoModalState || photoModalState.noteMode) return;
    const node = findNode(photoModalState.nodeId);
    const id = getNodeImageIds(node)[photoModalState.index];
    const comment = getPhotoComment(node, id);
    photoModalCommentInput.value = comment;
    // The comment box stays collapsed by default (see .photo-modal-
    // comment-row.hidden) — only auto-opened here when the photo being
    // shown already has a saved comment, so existing comments are never
    // hidden from view; an empty photo starts collapsed until the 💬
    // toggle button is clicked. Re-evaluated every time the visible
    // photo changes so stepping through the gallery doesn't leave one
    // photo's open/closed state stuck on the next one.
    photoModalCommentRow.classList.toggle("hidden", !comment);
    photoModalCommentToggle.classList.toggle("has-comment", !!comment);
    requestAnimationFrame(() => autoGrowTextarea(photoModalCommentInput));
  }
  // Saves on blur (clicking/tabbing away, including stepping to the next/
  // prev photo) and on Ctrl/Cmd+Enter — same "commit when you're done
  // typing" behavior as the video modal's comment box.
  function savePhotoModalComment() {
    if (!photoModalState || photoModalState.noteMode) return;
    const node = findNode(photoModalState.nodeId);
    const id = getNodeImageIds(node)[photoModalState.index];
    if (!node || !id) return;
    if (getPhotoComment(node, id) === photoModalCommentInput.value.trim()) return;
    pushUndo();
    setPhotoComment(node, id, photoModalCommentInput.value);
    photoModalCommentToggle.classList.toggle("has-comment", !!getPhotoComment(node, id));
    persist();
  }
  // 💬 toggle button — the comment box is collapsed by default (see
  // renderPhotoModalComment), so this is the only way to open it for a
  // photo that doesn't have a comment yet. Clicking again while open
  // collapses it back (but only if there's nothing typed, so an in-
  // progress comment can't be accidentally hidden without saving —
  // blur/Ctrl+Enter still commit it first either way).
  photoModalCommentToggle.addEventListener("click", (e) => {
    e.stopPropagation();
    const willShow = photoModalCommentRow.classList.contains("hidden");
    if (willShow) {
      photoModalCommentRow.classList.remove("hidden");
      requestAnimationFrame(() => { photoModalCommentInput.focus(); autoGrowTextarea(photoModalCommentInput); });
    } else if (!photoModalCommentInput.value.trim()) {
      photoModalCommentRow.classList.add("hidden");
    }
  });
  photoModalCommentInput.addEventListener("blur", savePhotoModalComment);
  photoModalCommentInput.addEventListener("keydown", (e) => {
    e.stopPropagation();
    if ((e.metaKey || e.ctrlKey) && e.key === "Enter") { e.preventDefault(); photoModalCommentInput.blur(); }
  });
  photoModalCommentInput.addEventListener("input", () => autoGrowTextarea(photoModalCommentInput));
  // Renders the tag chips for whichever photo is currently shown, plus
  // clears the "add a tag" input so it doesn't carry text over between
  // photos as you step through the gallery.
  function renderPhotoModalTags() {
    if (!photoModalState) return;
    const node = findNode(photoModalState.nodeId);
    const id = getNodeImageIds(node)[photoModalState.index];
    photoModalTagChips.innerHTML = "";
    getPhotoTags(node, id).forEach((tag) => {
      const chip = document.createElement("span");
      chip.className = "photo-modal-tag-chip";
      const label = document.createElement("span");
      label.textContent = tag;
      chip.appendChild(label);
      const remove = document.createElement("button");
      remove.className = "photo-modal-tag-chip-remove";
      remove.type = "button";
      remove.textContent = "✕";
      remove.title = `Remove tag "${tag}"`;
      remove.setAttribute("aria-label", `Remove tag ${tag}`);
      remove.addEventListener("click", (e) => {
        e.stopPropagation();
        pushUndo();
        removePhotoTag(node, id, tag);
        persist();
        renderPhotoModalTags();
      });
      chip.appendChild(remove);
      photoModalTagChips.appendChild(chip);
    });
    photoModalTagInput.value = "";
    hideTagSuggestions();
  }
  function closePhotoModal() {
    savePhotoModalComment();
    closePhotoSymbolPopover();
    closePhotoCombinePopover();
    cancelCombinePaste();
    photoModalState = null;
    photoModal.classList.remove("photo-modal-above-note");
    zoomModalClose(photoModal, () => {
      photoModalImg.src = "";
      resetPhotoZoom();
    });
  }
  function stepPhotoModal(delta) {
    if (!photoModalState) return;
    if (photoModalState.noteMode) {
      const images = photoModalState.images;
      if (!images.length) return;
      photoModalState.index = (photoModalState.index + delta + images.length) % images.length;
      resetPhotoZoom();
      renderPhotoModal();
      return;
    }
    savePhotoModalComment();
    const group = photoModalState.tagGroup;
    if (group) {
      const n = group.items.length;
      if (!n) return;
      const prevNodeId = photoModalState.nodeId;
      // Skip over any stale entries (node or photo deleted since the tag
      // group was collected) rather than getting stuck on them.
      for (let tries = 0; tries < n; tries++) {
        photoModalState.tagIndex = (photoModalState.tagIndex + delta + n) % n;
        const it = group.items[photoModalState.tagIndex];
        const node = findNode(it.nodeId);
        if (!node) continue;
        const idx = getNodeImageIds(node).indexOf(it.id);
        if (idx < 0) continue;
        photoModalState.nodeId = it.nodeId;
        photoModalState.index = idx;
        break;
      }
      resetPhotoZoom();
      renderPhotoModal();
      // The new photo may live on a different node — keep the canvas
      // behind the modal in sync so it's already centered if the user
      // closes the modal.
      if (photoModalState.nodeId !== prevNodeId) focusNodeInCanvas(photoModalState.nodeId);
      return;
    }
    const images = getNodeImages(findNode(photoModalState.nodeId));
    if (!images.length) return;
    photoModalState.index = (photoModalState.index + delta + images.length) % images.length;
    resetPhotoZoom();
    renderPhotoModal();
  }
  photoModalClose.addEventListener("click", closePhotoModal);
  photoModalBack.addEventListener("click", (e) => {
    e.stopPropagation();
    const ret = photoModalState && photoModalState.ret;
    closePhotoModal();
    runViewerReturn(ret);
  });
  photoModalPrev.addEventListener("click", (e) => { e.stopPropagation(); stepPhotoModal(-1); });
  photoModalNext.addEventListener("click", (e) => { e.stopPropagation(); stepPhotoModal(1); });
  photoModalGoto.addEventListener("click", (e) => {
    e.stopPropagation();
    if (!photoModalState) return;
    const nodeId = photoModalState.nodeId;
    closePhotoModal();
    focusNodeInCanvas(nodeId);
  });
  photoModalFavorite.addEventListener("click", (e) => {
    e.stopPropagation();
    if (!photoModalState || photoModalState.noteMode) return;
    const node = findNode(photoModalState.nodeId);
    const id = getNodeImageIds(node)[photoModalState.index];
    if (!node || !id) return;
    pushUndo();
    togglePhotoFavorite(node, id);
    persist();
    renderPhotoModalFavorite();
    updatePhotoModalFolderUI();
  });
  // Zoom buttons — same centered zoom math as the scroll-wheel handler
  // below, just anchored to the image's center instead of the cursor.
  function zoomPhotoBy(factor) {
    if (!photoModalState) return;
    const prevScale = photoZoom.scale;
    const newScale = clamp(prevScale * factor, PHOTO_ZOOM_MIN, PHOTO_ZOOM_MAX);
    if (newScale === prevScale) return;
    const scaleFactor = newScale / prevScale;
    photoZoom.tx *= scaleFactor;
    photoZoom.ty *= scaleFactor;
    photoZoom.scale = newScale;
    if (photoZoom.scale === PHOTO_ZOOM_MIN) { photoZoom.tx = 0; photoZoom.ty = 0; }
    applyPhotoZoom();
  }
  photoModalZoomIn.addEventListener("click", (e) => { e.stopPropagation(); zoomPhotoBy(1.4); });
  photoModalZoomOut.addEventListener("click", (e) => { e.stopPropagation(); zoomPhotoBy(1 / 1.4); });
  if (photoModalFolder) {
    photoModalFolder.addEventListener("mousedown", (e) => e.preventDefault());
    photoModalFolder.addEventListener("click", (e) => {
      e.stopPropagation();
      if (!photoModalState || photoModalState.noteMode) return;
      const node = findNode(photoModalState.nodeId);
      const id = node && getNodeImageIds(node)[photoModalState.index];
      if (!id) return;
      openFolderMovePopover(photoModalFolder, photosFolderMgr, id, updatePhotoModalFolderUI);
    });
  }
  photoModalDelete.addEventListener("click", (e) => {
    e.stopPropagation();
    if (!photoModalState || photoModalState.noteMode) return;
    const node = findNode(photoModalState.nodeId);
    if (!node) return;
    const ids = getNodeImageIds(node);
    if (!ids.length) return;
    const deletedId = ids[photoModalState.index];
    pushUndo();
    ids.splice(photoModalState.index, 1);
    node.images = ids;
    node.image = null;
    setPhotoTags(node, deletedId, null);
    setPhotoNotes(node, deletedId, null);
    setPhotoComment(node, deletedId, null);
    setPhotoTimestamp(node, deletedId, null);
    deletePhotoRecord(deletedId);
    // Keep the tag group's item list in sync so prev/next doesn't try to
    // step onto the photo we just deleted.
    if (photoModalState.tagGroup) {
      const gi = photoModalState.tagGroup.items.findIndex(
        it => it.nodeId === photoModalState.nodeId && it.id === deletedId
      );
      if (gi >= 0) {
        photoModalState.tagGroup.items.splice(gi, 1);
        if (photoModalState.tagIndex > gi) photoModalState.tagIndex--;
      }
    }
    renderAll();
    persist();
    if (!ids.length) {
      if (photoModalState.tagGroup && photoModalState.tagGroup.items.length) {
        // This node's photos are gone but the tag group still has others —
        // step to the next one instead of closing.
        photoModalState.tagIndex = clamp(photoModalState.tagIndex - 1, 0, photoModalState.tagGroup.items.length - 1);
        stepPhotoModal(1);
      } else {
        closePhotoModal();
      }
    } else {
      renderPhotoModal();
    }
  });
  photoModal.addEventListener("click", (e) => {
    if (e.target !== photoModal || cropping || addingText) return;
    closePhotoModal();
  });
  document.addEventListener("keydown", (e) => {
    if (photoModal.classList.contains("hidden")) return;
    // Let the tag input handle its own keys (its own listener below adds
    // the tag on Enter and blurs on Escape) — don't let this steal
    // Escape to close the whole modal or the arrow keys while typing a
    // tag. (The note editor, opened via the 📝 button, is a separate
    // top-level modal with its own Escape/keydown handling — see
    // noteTextarea/noteTitleInput below — so it doesn't need handling
    // here.)
    if (e.target === photoModalTagInput) return;
    if (e.key === "Escape") { if (cropping) cropCleanup(); else if (addingText) textCleanup(); else closePhotoModal(); }
    else if (cropping || addingText) return;
    else if (e.key === "ArrowLeft") stepPhotoModal(-1);
    else if (e.key === "ArrowRight") stepPhotoModal(1);
  });

  // ---- Tagging ----
  // Enter adds the typed tag to the currently displayed photo (or, if a
  // suggestion is highlighted, adds that suggestion instead); Escape
  // closes the suggestion list first, then just clears/blurs the field
  // rather than closing the whole modal.
  let tagSuggestActiveIndex = -1;

  function getAllPhotoTagLabels() {
    return collectPhotoTagGroups().map(g => g.label);
  }
  function hideTagSuggestions() {
    photoModalTagSuggest.classList.add("hidden");
    photoModalTagSuggest.innerHTML = "";
    tagSuggestActiveIndex = -1;
  }
  function setTagSuggestActive(index) {
    const items = photoModalTagSuggest.children;
    tagSuggestActiveIndex = index;
    for (let i = 0; i < items.length; i++) items[i].classList.toggle("active", i === index);
  }
  function applyTagSuggestion(tag) {
    if (!photoModalState) return;
    const node = findNode(photoModalState.nodeId);
    const id = node ? getNodeImageIds(node)[photoModalState.index] : null;
    if (!node || !id) return;
    const existing = getPhotoTags(node, id);
    if (existing.some(t => t.toLowerCase() === tag.toLowerCase())) { hideTagSuggestions(); return; }
    pushUndo();
    addPhotoTag(node, id, tag);
    persist();
    renderPhotoModalTags();
    photoModalTagInput.focus();
  }
  // Suggests tags already used elsewhere in the map — filtered by what's
  // typed so far, and never a tag already on this photo — so repeat tags
  // (e.g. #receipt, #before/#after) can be added with one click instead
  // of retyping them each time.
  function renderTagSuggestions() {
    if (!photoModalState) { hideTagSuggestions(); return; }
    const node = findNode(photoModalState.nodeId);
    const id = node ? getNodeImageIds(node)[photoModalState.index] : null;
    if (!node || !id) { hideTagSuggestions(); return; }
    const q = (photoModalTagInput.value || "").trim().toLowerCase();
    const existing = new Set(getPhotoTags(node, id).map(t => t.toLowerCase()));
    let matches = getAllPhotoTagLabels().filter(t => !existing.has(t.toLowerCase()));
    if (q) matches = matches.filter(t => t.toLowerCase().includes(q));
    matches = matches.slice(0, 6);
    if (!matches.length) { hideTagSuggestions(); return; }
    photoModalTagSuggest.innerHTML = "";
    matches.forEach((tag) => {
      const li = document.createElement("li");
      li.textContent = tag;
      // mousedown + preventDefault (not click) so this fires before the
      // input blurs — otherwise the blur handler below would hide the
      // list right out from under the click.
      li.addEventListener("mousedown", (e) => { e.preventDefault(); applyTagSuggestion(tag); });
      photoModalTagSuggest.appendChild(li);
    });
    tagSuggestActiveIndex = -1;
    photoModalTagSuggest.classList.remove("hidden");
  }
  photoModalTagInput.addEventListener("input", renderTagSuggestions);
  photoModalTagInput.addEventListener("focus", renderTagSuggestions);
  photoModalTagInput.addEventListener("blur", () => setTimeout(hideTagSuggestions, 120));
  photoModalTagInput.addEventListener("keydown", (e) => {
    e.stopPropagation();
    const suggestVisible = !photoModalTagSuggest.classList.contains("hidden");
    if (suggestVisible && (e.key === "ArrowDown" || e.key === "ArrowUp")) {
      e.preventDefault();
      const n = photoModalTagSuggest.children.length;
      if (!n) return;
      const next = e.key === "ArrowDown"
        ? (tagSuggestActiveIndex + 1) % n
        : (tagSuggestActiveIndex - 1 + n) % n;
      setTagSuggestActive(next);
      return;
    }
    if (e.key === "Enter") {
      e.preventDefault();
      if (suggestVisible && tagSuggestActiveIndex >= 0) {
        const active = photoModalTagSuggest.children[tagSuggestActiveIndex];
        if (active) { applyTagSuggestion(active.textContent); return; }
      }
      if (!photoModalState) return;
      const node = findNode(photoModalState.nodeId);
      const id = node ? getNodeImageIds(node)[photoModalState.index] : null;
      if (!node || !id) return;
      const clean = (photoModalTagInput.value || "").trim();
      if (!clean) return;
      const existing = getPhotoTags(node, id);
      if (existing.some(t => t.toLowerCase() === clean.toLowerCase())) {
        photoModalTagInput.value = "";
        hideTagSuggestions();
        return;
      }
      pushUndo();
      addPhotoTag(node, id, clean);
      persist();
      renderPhotoModalTags();
      photoModalTagInput.focus();
    } else if (e.key === "Escape") {
      if (suggestVisible) { hideTagSuggestions(); return; }
      photoModalTagInput.value = "";
      photoModalTagInput.blur();
    }
  });
  // Clicks/drags inside the tag bar shouldn't fall through to the
  // image's own zoom/pan handling or close the modal.
  photoModalTags.addEventListener("mousedown", (e) => e.stopPropagation());
  photoModalTags.addEventListener("click", (e) => e.stopPropagation());

  // ---- Crop ----
  // Lets the user drag out a rectangle over the currently displayed photo
  // and replace it with just that region. Built with plain absolutely-
  // positioned elements over the image rather than a canvas overlay, so
  // it stays crisp at any zoom and needs no extra markup in index.html.
  photoModalCrop.addEventListener("click", (e) => {
    e.stopPropagation();
    if (addingText || (photoModalState && photoModalState.noteMode)) return;
    startCrop();
  });
  photoModalText.addEventListener("click", (e) => {
    e.stopPropagation();
    if (cropping) return;
    if (addingText) { if (rearmTextPlacement) rearmTextPlacement(); return; }
    startAddText();
  });

  function startCrop() {
    if (cropping || !photoModalState) return;
    resetPhotoZoom();
    const node = findNode(photoModalState.nodeId);
    const images = getNodeImages(node);
    const src = images[photoModalState.index];
    if (!src) return;

    cropping = true;
    const card = photoModal.querySelector(".photo-modal-card");
    const img = photoModalImg;
    const iw = img.offsetWidth, ih = img.offsetHeight;

    // Hide everything except the image and the crop controls while
    // cropping — the whole top/bottom toolbars (not just a few individual
    // buttons), so nothing from either one is left dangling on screen
    // mid-crop.
    const hiddenWhileCropping = [photoModalPrev, photoModalNext, photoModalToolbarTop, photoModalToolbarBottom];
    hiddenWhileCropping.forEach(el => { el.dataset.prevDisplay = el.style.display; el.style.display = "none"; });

    const overlay = document.createElement("div");
    Object.assign(overlay.style, {
      position: "absolute", left: img.offsetLeft + "px", top: img.offsetTop + "px",
      width: iw + "px", height: ih + "px",
      overflow: "hidden", borderRadius: "10px", zIndex: "5", touchAction: "none"
    });

    const box = document.createElement("div");
    Object.assign(box.style, {
      position: "absolute", boxSizing: "border-box",
      border: "2px solid #fff",
      boxShadow: "0 0 0 9999px rgba(0,0,0,0.6)",
      cursor: "move", touchAction: "none"
    });
    overlay.appendChild(box);

    let rect = { x: iw * 0.1, y: ih * 0.1, w: iw * 0.8, h: ih * 0.8 };
    const minSize = 24;

    const handles = {};
    ["nw", "ne", "sw", "se"].forEach(pos => {
      const h = document.createElement("div");
      Object.assign(h.style, {
        position: "absolute", width: "14px", height: "14px", background: "#fff",
        border: "2px solid var(--accent, #7c9eff)", borderRadius: "50%",
        touchAction: "none",
        cursor: (pos === "nw" || pos === "se") ? "nwse-resize" : "nesw-resize"
      });
      if (pos.includes("n")) h.style.top = "-8px"; else h.style.bottom = "-8px";
      if (pos.includes("w")) h.style.left = "-8px"; else h.style.right = "-8px";
      box.appendChild(h);
      handles[pos] = h;
    });

    function applyRect() {
      box.style.left = rect.x + "px";
      box.style.top = rect.y + "px";
      box.style.width = rect.w + "px";
      box.style.height = rect.h + "px";
    }
    applyRect();

    let dragMode = null, dragStart = null;
    function onPointerDown(e, mode) {
      e.preventDefault(); e.stopPropagation();
      dragMode = mode;
      dragStart = { x: e.clientX, y: e.clientY, rect: { ...rect } };
      document.addEventListener("pointermove", onPointerMove);
      document.addEventListener("pointerup", onPointerUp);
    }
    function onPointerMove(e) {
      if (!dragMode) return;
      const dx = e.clientX - dragStart.x, dy = e.clientY - dragStart.y;
      const s = dragStart.rect;
      if (dragMode === "move") {
        rect = { ...s, x: clamp(s.x + dx, 0, iw - s.w), y: clamp(s.y + dy, 0, ih - s.h) };
      } else {
        let left = s.x, top = s.y, right = s.x + s.w, bottom = s.y + s.h;
        if (dragMode.includes("w")) left = clamp(s.x + dx, 0, right - minSize);
        if (dragMode.includes("e")) right = clamp(s.x + s.w + dx, left + minSize, iw);
        if (dragMode.includes("n")) top = clamp(s.y + dy, 0, bottom - minSize);
        if (dragMode.includes("s")) bottom = clamp(s.y + s.h + dy, top + minSize, ih);
        rect = { x: left, y: top, w: right - left, h: bottom - top };
      }
      applyRect();
    }
    function onPointerUp() {
      dragMode = null;
      document.removeEventListener("pointermove", onPointerMove);
      document.removeEventListener("pointerup", onPointerUp);
    }
    box.addEventListener("pointerdown", (e) => { if (e.target === box) onPointerDown(e, "move"); });
    Object.entries(handles).forEach(([pos, h]) => h.addEventListener("pointerdown", (e) => onPointerDown(e, pos)));

    const toolbar = document.createElement("div");
    Object.assign(toolbar.style, {
      position: "absolute", left: "50%", bottom: "-52px", transform: "translateX(-50%)",
      display: "flex", gap: "10px", zIndex: "6", whiteSpace: "nowrap"
    });
    const cancelBtn = document.createElement("button");
    cancelBtn.type = "button"; cancelBtn.className = "btn-ghost"; cancelBtn.textContent = "Cancel";
    const applyBtn = document.createElement("button");
    applyBtn.type = "button"; applyBtn.className = "btn-primary"; applyBtn.textContent = "Apply crop";
    toolbar.appendChild(cancelBtn);
    toolbar.appendChild(applyBtn);

    card.appendChild(overlay);
    card.appendChild(toolbar);

    function cleanup() {
      onPointerUp();
      overlay.remove();
      toolbar.remove();
      hiddenWhileCropping.forEach(el => { el.style.display = el.dataset.prevDisplay || ""; delete el.dataset.prevDisplay; });
      cropping = false;
      cropCleanup = null;
      renderPhotoModal();
    }
    cropCleanup = cleanup;
    cancelBtn.addEventListener("click", (e) => { e.stopPropagation(); cleanup(); });

    applyBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      const scaleX = img.naturalWidth / iw, scaleY = img.naturalHeight / ih;
      const sx = Math.round(rect.x * scaleX), sy = Math.round(rect.y * scaleY);
      const sw = Math.round(rect.w * scaleX), sh = Math.round(rect.h * scaleY);
      if (sw < 2 || sh < 2) { cleanup(); return; }

      const canvas = document.createElement("canvas");
      canvas.width = sw; canvas.height = sh;
      canvas.getContext("2d").drawImage(img, sx, sy, sw, sh, 0, 0, sw, sh);
      const isPng = src.startsWith("data:image/png");
      const croppedUrl = encodePhotoCanvas(canvas, isPng ? "image/png" : "image/jpeg", sw * sh, 1.0);

      const liveNode = findNode(photoModalState.nodeId);
      const liveIds = getNodeImageIds(liveNode);
      if (liveIds.length) {
        pushUndo();
        // A crop replaces the photo's actual bytes, so it gets a new id
        // (the old id/record is retired) — its tags carry over onto the
        // new id since it's still conceptually "the same" photo.
        const newId = addPhotoRecord(croppedUrl, { noDedupe: true });
        const oldId = liveIds[photoModalState.index];
        carryPhotoTags(liveNode, liveNode, [[oldId, newId]]);
        carryPhotoNotes(liveNode, liveNode, [[oldId, newId]]);
        carryPhotoComments(liveNode, liveNode, [[oldId, newId]]);
        carryPhotoFavorites(liveNode, liveNode, [[oldId, newId]]);
        carryPhotoTimestamps(liveNode, liveNode, [[oldId, newId]]);
        setPhotoTags(liveNode, oldId, null);
        setPhotoNotes(liveNode, oldId, null);
        setPhotoComment(liveNode, oldId, null);
        setPhotoTimestamp(liveNode, oldId, null);
        liveIds[photoModalState.index] = newId;
        liveNode.images = liveIds;
        liveNode.image = null;
        deletePhotoRecord(oldId); // after the old reference is gone, so a shared id is kept if another node still uses it
        renderAll();
        persist();
      }
      cleanup();
    });
  }

  // ---- Add text ----
  // Click anywhere on the photo to drop a short editable label, drag it
  // into place, pick a color/size, add as many as you like, then Apply
  // bakes every label into the photo as real pixels (so it travels with
  // exports/screenshots like any other part of the image).
  function isLightColor(hex) {
    const c = hex.replace("#", "");
    const r = parseInt(c.substring(0, 2), 16), g = parseInt(c.substring(2, 4), 16), b = parseInt(c.substring(4, 6), 16);
    return (0.299 * r + 0.587 * g + 0.114 * b) > 150;
  }

  function startAddText(initialSymbol) {
    if (addingText || cropping || !photoModalState) return;
    // Deliberately does NOT reset the zoom (crop still does): zooming in
    // and then labelling a fine detail is exactly the case this tool is
    // most useful for, so the overlay below just mirrors whatever
    // pan/zoom is currently applied to the image instead.
    // A note-photo session (see openNotePhotoViewer) has no backing node —
    // its images live only in photoModalState.images, taken straight from
    // the note's own <img> elements — so read from there instead of the
    // node's attached-photo list.
    const node = photoModalState.noteMode ? null : findNode(photoModalState.nodeId);
    const images = photoModalState.noteMode ? photoModalState.images : getNodeImages(node);
    const src = images[photoModalState.index];
    if (!src) return;

    addingText = true;
    const card = photoModal.querySelector(".photo-modal-card");
    const img = photoModalImg;
    const iw = img.offsetWidth, ih = img.offsetHeight;

    // Same full-toolbar hide as startCrop above, so the add-text overlay
    // doesn't leave the favorite/comment/zoom/goto buttons floating on
    // top of it either.
    const hiddenWhileAddingText = [photoModalPrev, photoModalNext, photoModalToolbarTop, photoModalToolbarBottom];
    hiddenWhileAddingText.forEach(el => { el.dataset.prevDisplay = el.style.display; el.style.display = "none"; });

    const overlay = document.createElement("div");
    Object.assign(overlay.style, {
      position: "absolute", left: img.offsetLeft + "px", top: img.offsetTop + "px",
      width: iw + "px", height: ih + "px",
      overflow: "hidden", borderRadius: "10px", zIndex: "5", cursor: "text", touchAction: "none",
      // Same box and same origin as the image, so copying the image's
      // transform verbatim (see syncOverlayZoom) lands the overlay exactly
      // on top of it at any zoom/pan.
      transformOrigin: "50% 50%"
    });

    // Everything inside the overlay — box.x/box.y, font sizes, the baked
    // canvas math in Apply — stays in the image's *unzoomed* display
    // coordinates. The zoom is purely a transform on the overlay itself,
    // so nothing downstream has to care about it; only the handful of
    // places that read raw screen pixels (click placement, drag deltas,
    // resize deltas) divide by the scale to convert back.
    function syncOverlayZoom() {
      overlay.style.transform = photoZoom.scale === 1
        ? ""
        : `translate(${photoZoom.tx}px, ${photoZoom.ty}px) scale(${photoZoom.scale})`;
      boxes.forEach(sizeHandles);
    }

    // The overlay's transform scales its children too, which would blow
    // the little ✕/grab/resize dots up to thumb-sized blobs at 6x — so
    // their sizes and corner offsets are divided back down by the scale,
    // keeping them the same physical size on screen at every zoom level.
    function sizeHandles(box) {
      const inv = 1 / photoZoom.scale;
      const d = 18 * inv, off = -10 * inv, bw = 1.5 * inv;
      Object.assign(box.del.style, {
        width: d + "px", height: d + "px", top: off + "px", right: off + "px",
        fontSize: (10 * inv) + "px", borderWidth: bw + "px"
      });
      Object.assign(box.grab.style, {
        width: d + "px", height: d + "px", top: off + "px", left: off + "px",
        fontSize: (11 * inv) + "px", borderWidth: bw + "px"
      });
      Object.assign(box.resize.style, {
        width: (14 * inv) + "px", height: (14 * inv) + "px",
        bottom: (-8 * inv) + "px", right: (-8 * inv) + "px", borderWidth: (2 * inv) + "px"
      });
      // The selected-box dashes come from .bl-text-box-active in the
      // stylesheet; these inline widths override them so the dashes don't
      // thicken into a solid band at high zoom.
      box.wrap.style.outlineWidth = (1.5 * inv) + "px";
      box.wrap.style.outlineOffset = (3 * inv) + "px";
    }

    // Where the centre of the *visible* (zoomed) region falls in overlay-
    // local coordinates — so a dropped symbol lands in view rather than
    // at the photo's true centre, which may be far off-screen at 4x.
    function visibleCenter() {
      const s = photoZoom.scale;
      return { x: iw / 2 - photoZoom.tx / s, y: ih / 2 - photoZoom.ty / s };
    }

    const TEXT_COLORS = ["#e0433a", "#ffffff", "#2b2a25", "#f5b301", "#4a9e4a", "#4a72d6"];
    let currentColor = TEXT_COLORS[0];
    let currentSize = 28; // px, at the displayed (not natural) scale
    const boxes = [];
    let activeBox = null;
    // Each click on the photo places exactly one box, then arms itself
    // off — click the "Aa" button again to place another.
    let placementArmed = true;
    photoModalText.classList.add("bl-text-armed");

    rearmTextPlacement = () => {
      placementArmed = true;
      photoModalText.classList.add("bl-text-armed");
    };

    // Declared here (rather than down by the toolbar it actually belongs
    // to) because selectBox — called below by dropSymbol as soon as a
    // number-symbol is placed — needs it immediately. A number-symbol
    // click supplies startAddText's initialSymbol and drops+selects a box
    // before the toolbar further down ever gets built, so defining
    // swatchEls there instead left it in the temporal dead zone at the
    // moment selectBox's syncSwatches() call ran — a ReferenceError that
    // aborted startAddText mid-setup, after it had already hidden the
    // modal's nav/close buttons and flipped addingText on, but before it
    // ever appended the overlay/toolbar (with the Cancel button) that
    // would have undone that. That's what left the photo viewer with
    // nothing left to click and no way to close it.
    const swatchEls = [];
    function syncSwatches() {
      swatchEls.forEach((sw, i) => {
        sw.style.border = TEXT_COLORS[i] === currentColor ? "2px solid var(--accent, #7c9eff)" : "1.5px solid rgba(255,255,255,0.4)";
      });
    }

    function deselectAll() {
      boxes.forEach(b => { b.wrap.classList.remove("bl-text-box-active"); if (b.del) b.del.style.display = "none"; if (b.resize) b.resize.style.display = "none"; if (b.grab) b.grab.style.display = "none"; });
      activeBox = null;
    }

    function selectBox(box) {
      deselectAll();
      activeBox = box;
      box.wrap.classList.add("bl-text-box-active");
      if (box.del) box.del.style.display = "flex";
      if (box.resize) box.resize.style.display = "block";
      if (box.grab) box.grab.style.display = "flex";
      currentColor = box.color;
      currentSize = box.size;
      syncSwatches();
    }

    function makeBox(x, y) {
      // Wrapper is NOT contenteditable and holds the text plus the del/
      // resize controls as siblings — keeping them out of the editable
      // node is what stops "select all + type" from wiping them out.
      const wrap = document.createElement("div");
      wrap.className = "bl-text-box";
      Object.assign(wrap.style, {
        position: "absolute", left: x + "px", top: y + "px",
        cursor: "move", touchAction: "none"
      });

      const el = document.createElement("div");
      el.contentEditable = "true";
      el.spellcheck = false;
      Object.assign(el.style, {
        color: currentColor, fontSize: currentSize + "px",
        fontFamily: "system-ui, -apple-system, 'Segoe UI', sans-serif",
        fontWeight: "700", lineHeight: "1.15", whiteSpace: "pre-wrap",
        padding: "4px 6px", minWidth: "16px", maxWidth: Math.max(40, iw - x) + "px",
        outline: "none", userSelect: "text",
        textShadow: "0 1px 3px rgba(0,0,0,0.65), 0 0 8px rgba(0,0,0,0.35)"
      });
      el.textContent = "Text";
      // Contenteditable's default Enter behavior inserts a wrapping <div>
      // or a <br> element rather than an actual newline character — so
      // el.textContent (what Apply reads, see the bake loop below) loses
      // every line break the browser drew, collapsing multi-line labels
      // back to one line. Inserting a literal "\n" text node ourselves
      // keeps textContent's line breaks in sync with what's on screen
      // (white-space: pre-wrap above is what renders that character as
      // a visible break).
      el.addEventListener("keydown", (e) => {
        if (e.key !== "Enter") return;
        e.preventDefault();
        const sel = window.getSelection();
        if (!sel || !sel.rangeCount) return;
        const range = sel.getRangeAt(0);
        range.deleteContents();
        const br = document.createTextNode("\n");
        range.insertNode(br);
        range.setStartAfter(br);
        range.setEndAfter(br);
        sel.removeAllRanges();
        sel.addRange(range);
      });
      wrap.appendChild(el);

      const del = document.createElement("button");
      del.type = "button"; del.textContent = "✕";
      Object.assign(del.style, {
        position: "absolute", top: "-10px", right: "-10px", width: "18px", height: "18px",
        borderRadius: "50%", border: "1.5px solid rgba(255,255,255,0.5)", background: "rgba(8,9,13,0.85)",
        color: "#fff", fontSize: "10px", lineHeight: "1", display: "none",
        alignItems: "center", justifyContent: "center", cursor: "pointer", padding: "0"
      });
      wrap.appendChild(del);

      // Corner handle — drag to scale the font size up/down, same idea as
      // the crop tool's resize handles.
      const resize = document.createElement("div");
      Object.assign(resize.style, {
        position: "absolute", bottom: "-8px", right: "-8px", width: "14px", height: "14px",
        borderRadius: "50%", background: "#fff", border: "2px solid var(--accent, #7c9eff)",
        display: "none", cursor: "nwse-resize", touchAction: "none"
      });
      wrap.appendChild(resize);

      // Grab handle — top-left corner, always moves the box no matter
      // where the text caret is. Without this, moving a label you're
      // actively editing means fighting the wrap's own pointerdown
      // handler (which lets a click land as a caret placement once the
      // box is already selected) — this handle sidesteps that entirely
      // by unconditionally starting a drag.
      const grab = document.createElement("div");
      grab.title = "Drag to move";
      grab.textContent = "⠿";
      Object.assign(grab.style, {
        position: "absolute", top: "-10px", left: "-10px", width: "18px", height: "18px",
        borderRadius: "50%", background: "rgba(8,9,13,0.85)", border: "1.5px solid rgba(255,255,255,0.5)",
        color: "#fff", fontSize: "11px", lineHeight: "1",
        display: "none", alignItems: "center", justifyContent: "center",
        cursor: "grab", touchAction: "none", userSelect: "none"
      });
      wrap.appendChild(grab);

      const box = { wrap, el, del, resize, grab, x, y, color: currentColor, size: currentSize };
      sizeHandles(box); // counter-scale the controls for the current zoom
      del.addEventListener("pointerdown", (e) => e.stopPropagation());
      del.addEventListener("click", (e) => {
        e.stopPropagation();
        const idx = boxes.indexOf(box);
        if (idx >= 0) boxes.splice(idx, 1);
        wrap.remove();
        if (activeBox === box) activeBox = null;
      });

      let resizing = false, resizeStart = null, pendingResizeSize = null, resizeRafId = null;
      resize.addEventListener("pointerdown", (e) => {
        e.preventDefault(); e.stopPropagation();
        selectBox(box);
        resizing = true;
        resizeStart = { x: e.clientX, y: e.clientY, size: box.size };
        document.addEventListener("pointermove", onResizeMove);
        document.addEventListener("pointerup", onResizeEnd);
      });
      function onResizeMove(e) {
        if (!resizing) return;
        // Divided by the zoom so a given hand movement changes the font by
        // the same *visual* amount at 1x and at 6x — at high zoom that
        // also makes fine adjustment of a small label possible, which is
        // the point of being able to label while zoomed in.
        const s = photoZoom.scale;
        const dx = (e.clientX - resizeStart.x) / s, dy = (e.clientY - resizeStart.y) / s;
        const delta = (dx + dy) / 2;
        pendingResizeSize = clamp(Math.round(resizeStart.size + delta), 6, 140);
        // Pointermove can fire far faster than the screen repaints (well
        // over 60/sec on a trackpad or high-poll-rate mouse). Writing
        // fontSize straight from every event forces the browser to
        // reflow this contentEditable box that often, which is what
        // made the resize feel laggy — so instead we just record the
        // latest target size and let one rAF apply it right before the
        // next paint, coalescing any events that arrived in between.
        if (resizeRafId == null) {
          resizeRafId = requestAnimationFrame(() => {
            resizeRafId = null;
            if (pendingResizeSize == null) return;
            box.size = pendingResizeSize;
            el.style.fontSize = box.size + "px";
            if (activeBox === box) { currentSize = box.size; }
          });
        }
      }
      function onResizeEnd() {
        resizing = false;
        if (resizeRafId != null) { cancelAnimationFrame(resizeRafId); resizeRafId = null; }
        // Apply whatever the final pointer position computed, even if it
        // hadn't been painted yet, so releasing mid-frame doesn't leave
        // the box one step behind where the pointer actually ended up.
        if (pendingResizeSize != null) {
          box.size = pendingResizeSize;
          el.style.fontSize = box.size + "px";
          if (activeBox === box) { currentSize = box.size; }
          pendingResizeSize = null;
        }
        document.removeEventListener("pointermove", onResizeMove);
        document.removeEventListener("pointerup", onResizeEnd);
      }

      let dragging = false, dragStart = null;
      // Whenever the text itself gains focus — whether from the native
      // click below, Tab, or a programmatic .focus() elsewhere — show it
      // as selected. Previously selectBox() only ran from inside
      // beginDrag()/dblclick, so a plain click that the browser handled
      // natively (see DRAG_CLICK_PX below) never lit up the handles.
      el.addEventListener("focus", () => selectBox(box));
      function beginDrag(e) {
        e.preventDefault(); e.stopPropagation();
        selectBox(box);
        dragging = true;
        dragStart = { x: e.clientX, y: e.clientY, bx: box.x, by: box.y };
        document.addEventListener("pointermove", onDrag);
        document.addEventListener("pointerup", onDragEnd);
      }
      // A plain mouse click on the label text is ambiguous: it might mean
      // "put the caret here" or "start dragging this box". We used to
      // resolve that by always dragging unless the box was already
      // focused — which meant a click on any box you weren't mid-edit in
      // could never just move the caret with the mouse. Now we let the
      // browser handle the click natively (so it focuses the box and
      // places the caret exactly where you clicked) and only hijack it
      // into a drag once the pointer actually travels past a small
      // threshold — the same click-vs-drag distinction most editors use.
      const DRAG_CLICK_PX = 4;
      wrap.addEventListener("pointerdown", (e) => {
        if (e.target !== el) { beginDrag(e); return; } // clicked the box's own frame, not its text — always drag
        e.stopPropagation();
        const startX = e.clientX, startY = e.clientY;
        const bx = box.x, by = box.y;
        let candidate = true;
        function onCandidateMove(ev) {
          if (!candidate) return;
          if (Math.hypot(ev.clientX - startX, ev.clientY - startY) < DRAG_CLICK_PX) return;
          candidate = false;
          document.removeEventListener("pointermove", onCandidateMove);
          document.removeEventListener("pointerup", onCandidateUp);
          // The browser may have started selecting text during the moved
          // mousedown; a real drag shouldn't leave a text selection behind.
          const sel = window.getSelection();
          if (sel && sel.rangeCount && !sel.isCollapsed) sel.removeAllRanges();
          selectBox(box);
          dragging = true;
          dragStart = { x: startX, y: startY, bx, by };
          document.addEventListener("pointermove", onDrag);
          document.addEventListener("pointerup", onDragEnd);
          onDrag(ev); // apply this move immediately so the box doesn't jump on the next event
        }
        function onCandidateUp() {
          candidate = false;
          document.removeEventListener("pointermove", onCandidateMove);
          document.removeEventListener("pointerup", onCandidateUp);
        }
        document.addEventListener("pointermove", onCandidateMove);
        document.addEventListener("pointerup", onCandidateUp);
      });
      // The grab handle always starts a drag immediately, even while the
      // box is selected and focused for editing — a guaranteed way to
      // move a label without needing to clear the caret first.
      grab.addEventListener("pointerdown", beginDrag);
      function onDrag(e) {
        if (!dragging) return;
        const s = photoZoom.scale;
        const dx = (e.clientX - dragStart.x) / s, dy = (e.clientY - dragStart.y) / s;
        box.x = clamp(dragStart.bx + dx, 0, Math.max(0, iw - wrap.offsetWidth));
        box.y = clamp(dragStart.by + dy, 0, Math.max(0, ih - wrap.offsetHeight));
        wrap.style.left = box.x + "px";
        wrap.style.top = box.y + "px";
      }
      function onDragEnd() {
        dragging = false;
        document.removeEventListener("pointermove", onDrag);
        document.removeEventListener("pointerup", onDragEnd);
      }
      wrap.addEventListener("dblclick", (e) => { e.stopPropagation(); selectBox(box); el.focus(); });

      overlay.appendChild(wrap);
      boxes.push(box);
      return box;
    }

    // Drops a number-symbol label onto the photo, already sized up and
    // centered/selected so it's immediately visible and ready to drag
    // into place — used both for the very first symbol (via
    // initialSymbol below) and for any further ones added while this
    // overlay session is still open (see addSymbolToActiveSession).
    function dropSymbol(ch) {
      // Scaled down by the zoom so the symbol looks the same size on
      // screen wherever you drop it, and lands in whatever part of the
      // photo you're actually looking at.
      const size = clamp(Math.round(56 / photoZoom.scale), 6, 140);
      const c = visibleCenter();
      const x = clamp(c.x - size / 2, 0, Math.max(0, iw - size));
      const y = clamp(c.y - size / 2, 0, Math.max(0, ih - size));
      currentSize = size;
      const box = makeBox(x, y);
      box.el.textContent = ch;
      box.size = size;
      box.el.style.fontSize = size + "px";
      selectBox(box);
    }
    addSymbolToActiveSession = dropSymbol;
    if (initialSymbol) {
      // A symbol is already placed, so an incidental click elsewhere on
      // the photo shouldn't drop an unrelated blank "Text" box — the Aa
      // button still re-arms plain text placement on demand.
      placementArmed = false;
      photoModalText.classList.remove("bl-text-armed");
      dropSymbol(initialSymbol);
    }

    // The overlay covers the image, so the image's own wheel/drag pan-zoom
    // handlers never see these events — re-implement them here so you can
    // keep zooming and panning around the photo mid-session, e.g. zoom
    // further in after placing one label to position the next.
    overlay.addEventListener("wheel", (e) => {
      e.preventDefault();
      e.stopPropagation();
      zoomPhotoAtPoint(e.clientX, e.clientY, e.deltaY);
    }, { passive: false });

    overlay.addEventListener("dblclick", (e) => {
      if (e.target !== overlay) return;
      e.stopPropagation();
      resetPhotoZoom();
    });

    let overlayPan = null;
    function onOverlayPanMove(e) {
      if (!overlayPan) return;
      photoZoom.tx = overlayPan.tx + (e.clientX - overlayPan.x);
      photoZoom.ty = overlayPan.ty + (e.clientY - overlayPan.y);
      applyPhotoZoom();
    }
    function onOverlayPanEnd() {
      overlayPan = null;
      overlay.style.cursor = "text";
      document.removeEventListener("pointermove", onOverlayPanMove);
      document.removeEventListener("pointerup", onOverlayPanEnd);
    }

    overlay.addEventListener("pointerdown", (e) => {
      if (e.target !== overlay) return; // a click landed on an existing box, not empty space
      if (!placementArmed) {
        // Click away just finishes the current label — and, while zoomed,
        // doubles as the drag-to-pan gesture, since the image underneath
        // can't receive it any more.
        deselectAll();
        if (photoZoom.scale > 1) {
          e.preventDefault();
          overlayPan = { x: e.clientX, y: e.clientY, tx: photoZoom.tx, ty: photoZoom.ty };
          overlay.style.cursor = "grabbing";
          document.addEventListener("pointermove", onOverlayPanMove);
          document.addEventListener("pointerup", onOverlayPanEnd);
        }
        return;
      }
      placementArmed = false;
      photoModalText.classList.remove("bl-text-armed");
      const rect = overlay.getBoundingClientRect();
      // rect is the *transformed* box, so divide the click's offset back
      // down into the image's own unzoomed coordinates.
      const s = photoZoom.scale;
      const x = clamp((e.clientX - rect.left) / s, 0, Math.max(0, iw - 20));
      const y = clamp((e.clientY - rect.top) / s, 0, Math.max(0, ih - 20));
      const box = makeBox(x, y);
      selectBox(box);
      requestAnimationFrame(() => {
        box.el.focus();
        const range = document.createRange();
        range.selectNodeContents(box.el);
        const sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
      });
    });

    // Bottom toolbar: color swatches + size picker apply to whichever box
    // is currently selected (or set the default for the next one placed).
    const toolbar = document.createElement("div");
    Object.assign(toolbar.style, {
      position: "absolute", left: "50%", bottom: "-56px", transform: "translateX(-50%)",
      display: "flex", alignItems: "center", gap: "8px", zIndex: "6", whiteSpace: "nowrap"
    });

    // (swatchEls/syncSwatches now declared earlier, alongside the rest of
    // this session's state — see the comment there for why.)
    TEXT_COLORS.forEach(c => {
      const sw = document.createElement("button");
      sw.type = "button"; sw.title = c;
      Object.assign(sw.style, {
        width: "20px", height: "20px", borderRadius: "50%", background: c,
        border: "1.5px solid rgba(255,255,255,0.4)", cursor: "pointer", padding: "0"
      });
      sw.addEventListener("click", (e) => {
        e.stopPropagation();
        currentColor = c;
        if (activeBox) { activeBox.color = c; activeBox.el.style.color = c; }
        syncSwatches();
      });
      toolbar.appendChild(sw);
      swatchEls.push(sw);
    });
    syncSwatches();

    // The modal's own zoom buttons are hidden for the duration of this
    // session (see hiddenWhileAddingText), so mirror them here — scroll
    // still works, but a trackpad-less/touch user needs a button.
    [["−", 1 / 1.4], ["+", 1.4], ["1:1", 0]].forEach(([label, factor]) => {
      const zb = document.createElement("button");
      zb.type = "button"; zb.className = "btn-ghost";
      zb.textContent = label;
      zb.title = factor ? (factor > 1 ? "Zoom in" : "Zoom out") : "Reset zoom";
      Object.assign(zb.style, { padding: "2px 8px", fontSize: "12px", lineHeight: "1.4" });
      zb.addEventListener("click", (ev) => {
        ev.stopPropagation();
        if (factor) zoomPhotoBy(factor); else resetPhotoZoom();
      });
      toolbar.appendChild(zb);
    });

    const sizeHint = document.createElement("span");
    sizeHint.textContent = "Drag a label's corner dot to resize";
    Object.assign(sizeHint.style, {
      color: "rgba(255,255,255,0.75)", fontSize: "12px", padding: "0 2px"
    });
    toolbar.appendChild(sizeHint);

    const cancelBtn = document.createElement("button");
    cancelBtn.type = "button"; cancelBtn.className = "btn-ghost"; cancelBtn.textContent = "Cancel";
    const applyBtn = document.createElement("button");
    applyBtn.type = "button"; applyBtn.className = "btn-primary"; applyBtn.textContent = "Apply text";
    toolbar.appendChild(cancelBtn);
    toolbar.appendChild(applyBtn);

    card.appendChild(overlay);
    card.appendChild(toolbar);
    // Follow every later zoom/pan (wheel, buttons, drag) for as long as
    // this session is open, and adopt the current one right now.
    onPhotoZoomChange = syncOverlayZoom;
    syncOverlayZoom();

    function cleanup() {
      onPhotoZoomChange = null;
      if (overlayPan) onOverlayPanEnd();
      overlay.remove();
      toolbar.remove();
      hiddenWhileAddingText.forEach(el => { el.style.display = el.dataset.prevDisplay || ""; delete el.dataset.prevDisplay; });
      photoModalText.classList.remove("bl-text-armed");
      addingText = false;
      textCleanup = null;
      rearmTextPlacement = null;
      addSymbolToActiveSession = null;
      renderPhotoModal();
    }
    textCleanup = cleanup;
    cancelBtn.addEventListener("click", (e) => { e.stopPropagation(); cleanup(); });

    applyBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      const withText = boxes.filter(b => b.el.textContent.trim().length > 0);
      if (!withText.length) { cleanup(); return; }

      const scaleX = img.naturalWidth / iw, scaleY = img.naturalHeight / ih;
      const canvas = document.createElement("canvas");
      canvas.width = img.naturalWidth; canvas.height = img.naturalHeight;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

      withText.forEach(b => {
        const fontPx = Math.round(b.size * scaleY);
        ctx.font = `700 ${fontPx}px system-ui, -apple-system, "Segoe UI", sans-serif`;
        ctx.textBaseline = "top";
        ctx.lineJoin = "round";
        ctx.fillStyle = b.color;
        // Outline every glyph so the label stays readable no matter what
        // it's sitting on top of in the photo.
        ctx.strokeStyle = isLightColor(b.color) ? "rgba(0,0,0,0.75)" : "rgba(255,255,255,0.75)";
        ctx.lineWidth = Math.max(2, fontPx * 0.06);
        const lines = b.el.textContent.split("\n");
        const lineHeight = fontPx * 1.15;
        lines.forEach((line, i) => {
          if (!line) return;
          const lx = b.x * scaleX + 6 * scaleX;
          const ly = b.y * scaleY + 4 * scaleY + i * lineHeight;
          ctx.strokeText(line, lx, ly);
          ctx.fillText(line, lx, ly);
        });
      });

      const isPng = src.startsWith("data:image/png");
      const outUrl = encodePhotoCanvas(canvas, isPng ? "image/png" : "image/jpeg", canvas.width * canvas.height, 1.0);

      if (photoModalState.noteMode) {
        // The baked-in image (with the label now part of its pixels) is a
        // fresh picture — gets its own PhotoDB record via addPhotoRecord
        // (same noDedupe rule the non-note branch below uses for crop/
        // text/combine edits), swapped onto the actual <img> element
        // sitting in the note editor's live DOM. commitNotesToNode() then
        // reads that updated innerHTML back into the note (see
        // captureActiveNote), same as any other in-note edit, and handles
        // its own pushUndo/persist; only once that's landed is the old
        // id's reference actually gone, so the old copy is freed after,
        // not before.
        const noteImgs = Array.from(noteTextarea.querySelectorAll("img"));
        const targetImg = noteImgs[photoModalState.index];
        let oldId = null;
        if (targetImg) {
          const newId = addPhotoRecord(outUrl, { noDedupe: true });
          oldId = targetImg.dataset.photoId;
          targetImg.dataset.photoId = newId;
          targetImg.src = photoUrl(newId);
        }
        photoModalState.images[photoModalState.index] = outUrl;
        commitNotesToNode();
        if (oldId) deletePhotoRecord(oldId);
      } else {
        const liveNode = findNode(photoModalState.nodeId);
        const liveIds = getNodeImageIds(liveNode);
        if (liveIds.length) {
          pushUndo();
          const newId = addPhotoRecord(outUrl, { noDedupe: true });
          const oldId = liveIds[photoModalState.index];
          carryPhotoTags(liveNode, liveNode, [[oldId, newId]]);
          carryPhotoNotes(liveNode, liveNode, [[oldId, newId]]);
          carryPhotoComments(liveNode, liveNode, [[oldId, newId]]);
          carryPhotoFavorites(liveNode, liveNode, [[oldId, newId]]);
          carryPhotoTimestamps(liveNode, liveNode, [[oldId, newId]]);
          setPhotoTags(liveNode, oldId, null);
          setPhotoNotes(liveNode, oldId, null);
          setPhotoComment(liveNode, oldId, null);
          setPhotoTimestamp(liveNode, oldId, null);
          liveIds[photoModalState.index] = newId;
          liveNode.images = liveIds;
          liveNode.image = null;
          deletePhotoRecord(oldId); // after the old reference is gone, so a shared id is kept if another node still uses it
          renderAll();
          persist();
        }
      }
      cleanup();
    });
  }

  /* ---------------- note editor ---------------- */

  const noteModal = $("#note-modal");
  const noteTextarea = $("#note-textarea");
  const noteTitleInput = $("#note-title-input");
  const noteCard = $(".note-modal-card");
  const noteResizeHandle = $("#note-resize-handle");
  const noteLineCountEl = $("#note-line-count");
  let noteEditingId = null;
  // When set, the editor is scoped to one photo on noteEditingId's node
  // (its notes live in node.photoNotes[photoId] — see getPhotoNotes)
  // instead of the node's own `notes` array. Everything else about the
  // editor — the rich text, title, paging, add/delete — behaves
  // identically either way; only load/save need to know which.
  let noteEditingPhotoId = null;
  // Same idea, but scoped to one task on the node instead (its notes
  // live in that task's own `notes` array — see getTaskNotes). Mutually
  // exclusive with noteEditingPhotoId; at most one of the two is set.
  let noteEditingTaskId = null;
  // When set alongside noteEditingTaskId, the editor is scoped to one
  // *subtask* of that task instead (its notes live in the subtask's own
  // `notes` array, same shape as a task's — see getTaskNotes).
  let noteEditingSubtaskId = null;
  // Same idea again, but scoped to one table cell on the node instead
  // (its notes live in that cell's attach record — see getCellNotes).
  // {r, c}, or null. Mutually exclusive with the photo/task cases above —
  // at most one of the three is ever set.
  let noteEditingCellPos = null;
  let noteSaveTimer = null;
  let noteLinkifyTimer = null;
  let noteIsResizing = false;
  // A node can now hold several notes. While the modal is open,
  // noteWorkingList holds an editable in-memory copy of that node's notes
  // ({id, title, html} each) and noteActiveIndex is which one is in the
  // editor right now. Nothing here is written back to the node itself
  // until commitNotesToNode() runs (autosave, navigating away, or closing).
  let noteWorkingList = [];
  let noteActiveIndex = 0;
  const noteNavAdd = $("#note-nav-add");
  const noteNavBack = $("#note-nav-back");
  let noteReturn = null; // where ← Back goes — see withViewerReturn
  const noteNavFavorite = $("#note-nav-favorite");
  const noteNavFolder = $("#note-nav-folder");
  const noteNavDelete = $("#note-nav-delete");

  // ---- Note editor undo/redo ----
  // Kept separate from the map-level undo/redo (pushUndo/undo, for
  // structural changes to nodes) since this is a much finer-grained,
  // nested kind of edit history that only applies while the note editor
  // is focused. It's custom rather than relying on the browser's native
  // contenteditable undo because several toolbar actions here (numbered
  // list, checklist, strikethrough, image insert) mutate the DOM directly
  // (el.textContent = ..., insertBefore, etc.) instead of going through
  // execCommand, which resets/breaks the native undo history — so without
  // this, undo would silently stop working the moment any toolbar button
  // was used. Snapshots are just the editor's full innerHTML; simple and
  // plenty robust for a field this size.
  const NOTE_UNDO_LIMIT = 100;
  let noteUndoStack = [];
  let noteRedoStack = [];
  let noteLastPushAt = 0;
  const noteUndoBtn = $("#note-tool-undo");
  const noteRedoBtn = $("#note-tool-redo");

  function updateNoteUndoButtons() {
    if (noteUndoBtn) noteUndoBtn.disabled = !noteUndoStack.length;
    if (noteRedoBtn) noteRedoBtn.disabled = !noteRedoStack.length;
  }

  // Records the editor's current state onto the undo stack. Call this
  // immediately BEFORE a mutation (toolbar click, image insert, paste,
  // Enter-to-continue-list), not after.
  //
  // Images pasted/dropped into a note are embedded as full-resolution,
  // un-downscaled base64 <img> tags directly in this same innerHTML (see
  // noteHandleImageFiles) — so once a note has even one screenshot in
  // it, EVERY subsequent edit anywhere in that note (not just to the
  // image) re-clones that image's full bytes into a new snapshot here.
  // At a 100-entry cap with no size limit, a note with a couple of
  // pasted screenshots could balloon into hundreds of MB of undo history
  // from perfectly ordinary typing — the same class of bug already fixed
  // for the map-level undo/redo stacks (see pushBoundedSnapshot), just
  // reused here since notes are the other place large embedded images
  // live.
  function notePushUndo() {
    pushBoundedSnapshot(noteUndoStack, noteTextarea.innerHTML, NOTE_UNDO_LIMIT);
    noteRedoStack = [];
    noteLastPushAt = Date.now();
    updateNoteUndoButtons();
  }

  // Clears the history — called whenever a different note (or a
  // different one of a node's several notes) is loaded into the shared
  // editor, so undo never reaches back into a note that's no longer open.
  function noteResetUndoHistory() {
    noteUndoStack = [];
    noteRedoStack = [];
    noteLastPushAt = 0;
    updateNoteUndoButtons();
    noteUppercasePending = false;
    updateNoteToolActiveStates();
  }

  // --- Bold / AA "pressed while it applies to what you type next" state ---
  //
  // Bold piggybacks on the browser's own contenteditable behavior: calling
  // execCommand("bold") with a collapsed caret (no selection) doesn't touch
  // any existing text — it just flips the style that new text will be
  // typed in, same as Word/Docs. document.queryCommandState("bold") then
  // tells us whether that's currently "on", so the toolbar button can show
  // pressed exactly when it applies.
  //
  // AA (uppercase) has no native browser equivalent, so noteUppercasePending
  // recreates the same idea by hand: toggling it on with a collapsed caret
  // doesn't uppercase anything yet, it just arms a beforeinput hook (below)
  // that uppercases each character as it's typed, until toggled off or the
  // caret is moved by a click.
  let noteUppercasePending = false;
  let noteUppercaseInserting = false; // re-entrancy guard for the hook below

  function updateNoteToolActiveStates() {
    let boldOn = false;
    try { boldOn = document.queryCommandState("bold"); } catch (_) { /* ignore */ }
    $("#note-tool-bold").classList.toggle("active", !!boldOn);
    $("#note-tool-upper").classList.toggle("active", noteUppercasePending);
  }

  function noteRestoreSnapshot(html) {
    noteTextarea.innerHTML = html;
    refreshDRCCards();
    noteSyncAllCheckedLines();
    noteSyncAllOrderedColors();
    noteAutoColorParagraphs();
    placeCaretAtEnd(noteTextarea);
    scheduleNoteAutosave();
    updateNoteUndoButtons();
  }

  function noteUndo() {
    if (!noteUndoStack.length) return;
    pushBoundedSnapshot(noteRedoStack, noteTextarea.innerHTML, NOTE_UNDO_LIMIT);
    noteRestoreSnapshot(noteUndoStack.pop());
  }

  function noteRedo() {
    if (!noteRedoStack.length) return;
    pushBoundedSnapshot(noteUndoStack, noteTextarea.innerHTML, NOTE_UNDO_LIMIT);
    noteRestoreSnapshot(noteRedoStack.pop());
  }

  // Custom resize grip: dragging it changes both the note card's width and
  // height (a plain CSS `resize` on the textarea only ever does one axis
  // for a contenteditable, so this drives it by hand instead).
  (function setupNoteResize() {
    let startX, startY, startW, startH;

    function onMove(e) {
      const dw = e.clientX - startX;
      const dh = e.clientY - startY;
      const maxW = window.innerWidth * 0.96;
      const maxH = window.innerHeight * 0.92;
      noteCard.style.width = clamp(startW + dw, 420, maxW) + "px";
      noteCard.style.height = clamp(startH + dh, 320, maxH) + "px";
    }
    function onUp() {
      document.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseup", onUp);
      document.removeEventListener("pointermove", onMove);
      document.removeEventListener("pointerup", onUp);
      document.body.style.userSelect = "";
      // A drag that ends past the card's edge fires a "click" on the modal
      // backdrop right after this mouseup — defer clearing the flag so
      // that click (which runs synchronously, before this timeout) still
      // sees the drag as in progress and doesn't close the note.
      setTimeout(() => { noteIsResizing = false; }, 0);
    }
    function onResizeStart(e) {
      e.preventDefault();
      e.stopPropagation();
      noteIsResizing = true;
      startX = e.clientX;
      startY = e.clientY;
      const rect = noteCard.getBoundingClientRect();
      startW = rect.width;
      startH = rect.height;
      document.body.style.userSelect = "none"; // avoid selecting page text while dragging
      document.addEventListener("mousemove", onMove);
      document.addEventListener("mouseup", onUp);
      document.addEventListener("pointermove", onMove);
      document.addEventListener("pointerup", onUp);
    }
    noteResizeHandle.addEventListener("mousedown", onResizeStart);
    noteResizeHandle.addEventListener("pointerdown", (e) => {
      if (e.pointerType === "mouse") return;
      onResizeStart(e);
    });
  })();


  function escapeHtml(s) {
    return (s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  function looksLikeHtml(s) {
    return /<[a-z][\s\S]*>/i.test(s || "");
  }

  // Old notes were stored as plain text with real newlines. New notes are
  // stored as HTML (one <div> per line, matching how Chrome/Edge structure
  // contenteditable content). This converts old plain-text notes on first
  // load so they still display correctly in the rich editor.
  function noteHtmlFromRaw(raw) {
    if (!raw) return "";
    if (looksLikeHtml(raw)) return raw;
    return raw.split(/\n/).map(line => `<div>${escapeHtml(line) || "<br>"}</div>`).join("");
  }

  // ---- Clickable links inside notes -----------------------------------
  // Notes are rich contenteditable HTML, so URL recognition works on text
  // nodes only: existing formatting, checklist prefixes, cards and photos
  // stay untouched. We recognize http(s):// links, www.* links and normal
  // bare domains (example.com/path). Auto-created anchors are saved as part
  // of the note, so they stay clickable after reopening/exporting/syncing.
  const NOTE_URL_RE = /(^|[\s([{])((?:https?:\/\/|www\.)[^\s<>"']+|(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,24}(?::\d{2,5})?(?:[\/?#][^\s<>"']*)?)/gi;

  function trimNoteUrlPunctuation(raw) {
    let url = raw || "";
    let suffix = "";
    // Sentence punctuation is almost never part of the URL. Closing
    // brackets are kept only when they have a matching opener in the URL
    // (e.g. a Wikipedia title containing parentheses).
    while (/[.,!?;:]$/.test(url)) { suffix = url.slice(-1) + suffix; url = url.slice(0, -1); }
    const pairs = [[")", "("], ["]", "["], ["}", "{"]];
    let changed = true;
    while (changed && url) {
      changed = false;
      for (const [close, open] of pairs) {
        if (!url.endsWith(close)) continue;
        const opens = url.split(open).length - 1;
        const closes = url.split(close).length - 1;
        if (closes > opens) { suffix = close + suffix; url = url.slice(0, -1); changed = true; }
      }
    }
    return { url, suffix };
  }

  function noteHrefForText(text) {
    let candidate = (text || "").trim();
    if (!candidate || /\s/.test(candidate)) return null;
    if (!/^https?:\/\//i.test(candidate)) candidate = "https://" + candidate;
    try {
      const parsed = new URL(candidate);
      if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return null;
      return parsed.href;
    } catch (_) {
      return null;
    }
  }

  // For an <a> pasted from rich text, trust only ordinary web protocols.
  // Relative hrefs are allowed and resolve against this app's own page;
  // javascript:, data:, file:, etc. never open from a note click.
  function noteSafeAnchorHref(raw) {
    const candidate = (raw || "").trim();
    if (!candidate) return null;
    try {
      const parsed = new URL(candidate, window.location.href);
      if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return null;
      return parsed.href;
    } catch (_) {
      return null;
    }
  }

  function unwrapNoteLink(a) {
    const parent = a && a.parentNode;
    if (!parent) return;
    while (a.firstChild) parent.insertBefore(a.firstChild, a);
    a.remove();
    parent.normalize();
  }

  function refreshAutoNoteLinks(root) {
    let changed = false;
    root.querySelectorAll("a.note-auto-link").forEach((a) => {
      const text = a.textContent || "";
      const href = noteHrefForText(text);
      if (!href) { unwrapNoteLink(a); changed = true; return; }
      if (a.getAttribute("href") !== href) { a.setAttribute("href", href); changed = true; }
      if (a.getAttribute("target") !== "_blank") { a.setAttribute("target", "_blank"); changed = true; }
      if (a.getAttribute("rel") !== "noopener noreferrer") { a.setAttribute("rel", "noopener noreferrer"); changed = true; }
      a.title = "Open link";
    });
    return changed;
  }

  function noteLinkifyUrls(root, preserveCaret) {
    if (!root) return false;
    let marker = null;
    const sel = window.getSelection();
    // Do not rewrite DOM under an active text selection — that would throw
    // the selection away. A later input/paste/open will retry linkifying.
    if (preserveCaret && sel && sel.rangeCount && root.contains(sel.anchorNode) && !sel.isCollapsed) return false;
    if (preserveCaret && sel && sel.rangeCount && sel.isCollapsed && root.contains(sel.anchorNode)) {
      marker = document.createComment("note-caret");
      const caret = sel.getRangeAt(0).cloneRange();
      caret.insertNode(marker);
    }

    let changed = refreshAutoNoteLinks(root);
    const textNodes = [];
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        const parent = node.parentElement;
        if (!parent || parent.closest("a") || parent.closest('[contenteditable="false"]')) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    });
    while (walker.nextNode()) textNodes.push(walker.currentNode);

    textNodes.forEach((node) => {
      const text = node.nodeValue || "";
      NOTE_URL_RE.lastIndex = 0;
      let match;
      let last = 0;
      let frag = null;
      while ((match = NOTE_URL_RE.exec(text))) {
        const prefix = match[1] || "";
        const raw = match[2] || "";
        const start = match.index + prefix.length;
        const trimmed = trimNoteUrlPunctuation(raw);
        const href = noteHrefForText(trimmed.url);
        if (!href || !trimmed.url) continue;
        if (!frag) frag = document.createDocumentFragment();
        if (start > last) frag.appendChild(document.createTextNode(text.slice(last, start)));
        const a = document.createElement("a");
        a.className = "note-auto-link";
        a.href = href;
        a.target = "_blank";
        a.rel = "noopener noreferrer";
        a.title = "Open link";
        a.textContent = trimmed.url;
        frag.appendChild(a);
        if (trimmed.suffix) frag.appendChild(document.createTextNode(trimmed.suffix));
        last = start + raw.length;
      }
      if (frag) {
        if (last < text.length) frag.appendChild(document.createTextNode(text.slice(last)));
        node.replaceWith(frag);
        changed = true;
      }
    });

    if (marker && marker.parentNode) {
      const range = document.createRange();
      range.setStartBefore(marker);
      range.collapse(true);
      marker.remove();
      sel.removeAllRanges();
      sel.addRange(range);
    }
    return changed;
  }

  // A note's stored HTML never carries an inline photo's actual src — an
  // <img data-photo-id="…"> with no src (see stripNotePhotoSrcForStorage
  // below) — so the moment it's loaded into the live, editable DOM, every
  // such tag needs its src filled back in from PhotoDB (see photoUrl).
  // Also self-heals notes saved by an older build, or just brought in
  // from Drive/a folder/import (see ensurePhotosMigrated/
  // inlinePhotosForPortableCopy), which can still have a raw `data:` src
  // and no data-photo-id yet: those get moved into PhotoDB right here too
  // — via the exact same dedup'd addPhotoRecord every fresh paste already
  // goes through — so an old note full of repeated screenshots shrinks
  // the moment it's opened, same spirit as noteDownscaleOversizedImagesInEditor
  // below. Returns whether anything changed, so the caller knows whether
  // the now-smaller HTML needs to be autosaved back onto the node.
  function hydrateNotePhotoImages(container = noteTextarea) {
    let migrated = false;
    Array.from(container.querySelectorAll("img")).forEach((img) => {
      const id = img.dataset.photoId;
      if (id) {
        img.src = photoUrl(id);
        return;
      }
      const src = img.getAttribute("src") || "";
      if (src.startsWith("data:")) {
        const newId = addPhotoRecord(src);
        img.dataset.photoId = newId;
        img.src = photoUrl(newId);
        migrated = true;
      }
    });
    return migrated;
  }

  // The inverse, run just before a note's live DOM is read back into
  // storage (see captureActiveNote) — strips every inline photo's src
  // (a tab-local blob: object URL, meaningless the moment this tab
  // closes — see loadPhotoCacheForMap) back down to just its
  // data-photo-id reference, so the note's stored HTML stays a small
  // string no matter how many/how large its photos are.
  function stripNotePhotoSrcForStorage(html) {
    if (!html || html.indexOf("data-photo-id") === -1) return html;
    const tmp = document.createElement("div");
    tmp.innerHTML = html;
    tmp.querySelectorAll("img[data-photo-id]").forEach((img) => img.removeAttribute("src"));
    return tmp.innerHTML;
  }

  // Same conversion as noteHtmlFromRaw, but bolds each non-blank line —
  // used only for a fresh DRC note's starting content, so the template's
  // section headers (📊 OVERVIEW, ✅ GOOD, ❌ BAD, 🔄 CHANGE FROM TOMORROW,
  // 📈 TRADES IN DETAILS — the only non-blank lines the template has by
  // convention) land bold from the start instead of plain text. Blank
  // separator lines between them are left alone.
  function noteHtmlFromDRCTemplate(raw) {
    if (!raw) return "";
    if (looksLikeHtml(raw)) return raw;
    return raw.split(/\n/).map(line => {
      const escaped = escapeHtml(line);
      if (!escaped) return "<div><br></div>";
      return `<div><b>${escaped}</b></div>`;
    }).join("");
  }

  // Keeps a line's strikethrough in sync with its checklist glyph: struck
  // when it starts with the checked box (☑), plain otherwise. `el` is
  // whatever noteToggleLinePrefix / the glyph-click handler already treated
  // as "the line" — normally a line <div>, but occasionally noteTextarea
  // itself for the very first line of a brand-new note (see
  // noteCurrentLine/noteToggleLinePrefix).
  function noteSyncLineChecked(el) {
    if (!el) return;
    el.classList.toggle("note-line-checked", /^☑(\s|$)/.test(el.textContent || ""));
  }

  // Re-applies that per-line strikethrough across every line, for notes
  // loaded from storage that may already contain checked items.
  function noteSyncAllCheckedLines() {
    noteSyncLineChecked(noteTextarea);
    Array.from(noteTextarea.children).forEach(noteSyncLineChecked);
  }

  // Standing template for a "DRC" (Daily Report Card) note — see
  // openNoteModal below, which drops this into a fresh DRC note (and into
  // the first note of a task/subtask named "DRC") instead of a blank
  // editor.
  //
  // It is simply the saved *note template* named "DRC" (the 📋 button in
  // the note editor — see saveNoteAsTemplate/findNoteTemplateByName): write
  // a DRC note the way you want new ones to start (section headings, and
  // recolor each card from the ring at its right edge), save it as a
  // template called "DRC", and every new DRC note starts from it. Each
  // non-blank line of that template is a section heading. Until a "DRC"
  // template has been saved, notes start from the older standalone
  // template (if this browser had customized one) or the built-in default.
  const DRC_TEMPLATE_KEY = "branchlineDRCTemplateSections_v1"; // legacy: read-only fallback
  const DEFAULT_DRC_TEMPLATE_TEXT =
    "📊 OVERVIEW\n\n✅ GOOD\n\n❌ BAD\n\n🔄 CHANGE FROM TOMORROW\n\n📈 TRADES IN DETAILS\n";

  function getDRCTemplateText() {
    const tpl = findNoteTemplateByName("DRC");
    if (tpl && (tpl.html || "").trim()) return tpl.html;
    const raw = localStorage.getItem(DRC_TEMPLATE_KEY);
    if (raw) {
      try {
        const parsed = JSON.parse(raw);
        // Oldest format: a JSON array of section labels.
        if (Array.isArray(parsed) && parsed.length) return parsed.join("\n\n") + "\n";
      } catch (e) {}
      return raw;
    }
    return DEFAULT_DRC_TEMPLATE_TEXT;
  }

  // The template's own lines — excluded when checking how much the person
  // has actually typed into a DRC note (see drcNoteIsFilled below), so an
  // untouched template doesn't itself count as "filled".
  function drcTemplateLines() {
    const raw = getDRCTemplateText();
    if (looksLikeHtml(raw)) return noteLinesFromHtml(raw).map(l => l.trim()).filter(Boolean);
    return raw.split("\n").map(l => l.trim()).filter(Boolean);
  }

  // The task — or, when noteEditingSubtaskId is set, the subtask of that
  // task — whose `notes` the editor is currently reading/writing.
  function noteEditingNoteOwner(taskHost) {
    const t = taskHost && getNodeTasks(taskHost).find(x => x.id === noteEditingTaskId);
    if (t && noteEditingSubtaskId) return getTaskSubtasks(t).find(x => x.id === noteEditingSubtaskId) || null;
    return t || null;
  }

  // Opens the note editor for a node, or (with `photoId`) for one photo
  // on that node, or (with `taskId`) for one task on that node, or (with
  // `cellPos`, {r, c}) for one table cell on that node instead — same
  // editor in all four cases, just a different backing list (see
  // noteEditingPhotoId/noteEditingTaskId/noteEditingCellPos above).
  // `index` picks which existing note to show: omit it to land on the
  // last (most recently added) one, or pass notes.length (or any
  // out-of-range index) to start a brand-new blank note instead of an
  // existing one.
  function openNoteModal(nodeId, index, photoId, taskId, cellPos, forceDRCTemplate, subtaskId) {
    const node = findNode(nodeId);
    if (!node) return;
    commitEditIfActive();
    // Where ← Back should go. A return point handed over by a browser wins;
    // otherwise, if this is a fresh open (not a jump between notes while the
    // editor is already up), fall back to whichever modal is sitting
    // underneath (Tasks/Calendar) or to the map.
    const pendingRet = takeViewerReturn();
    if (pendingRet) noteReturn = pendingRet;
    else if (noteModal.classList.contains("hidden")) noteReturn = underlyingModalReturn();
    noteNavBack.title = viewerBackTitle(noteReturn);
    noteNavBack.setAttribute("aria-label", noteNavBack.title);
    // A task — or now a subtask — literally named "DRC" shares the exact
    // same single per-node DRC note as the right-click "📋 DRC…" shortcut
    // below, instead of owning a separate note of its own — otherwise a
    // node could end up showing multiple DRC clipboard icons at once (one
    // from the node's own notes, one from this task/subtask). Only
    // redirect on a genuinely fresh click (this task/subtask doesn't have
    // a note of its own yet); one that already has previously-written
    // note content of its own keeps opening that note untouched, so
    // nothing existing gets silently orphaned.
    if (taskId) {
      const taskHostForRedirect = cellPos ? getCellAttach(node, cellPos.r, cellPos.c) : node;
      const parentTaskForRedirect = getNodeTasks(taskHostForRedirect).find(x => x.id === taskId);
      const drcOwner = subtaskId
        ? (parentTaskForRedirect ? getTaskSubtasks(parentTaskForRedirect).find(x => x.id === subtaskId) : null)
        : parentTaskForRedirect;
      if (drcOwner && (drcOwner.text || "").trim().toUpperCase() === "DRC" && !getTaskNotes(drcOwner).length) {
        taskId = null;
        subtaskId = null;
        cellPos = null;
        photoId = null;
        forceDRCTemplate = true;
      }
    }
    noteEditingId = nodeId;
    noteEditingPhotoId = photoId || null;
    noteEditingTaskId = taskId || null;
    noteEditingSubtaskId = (taskId && subtaskId) || null;
    noteEditingCellPos = cellPos || null;
    // A task's own notes take priority over the cellPos check below even
    // when both are set — that combination means "a task living inside
    // this cell's task list" (see the Tasks modal's note button, opened
    // with both a taskId and this cell's {r, c}), not a plain cell note.
    // cellPos still gets used to resolve which task list to search.
    const taskHost = noteEditingCellPos ? getCellAttach(node, noteEditingCellPos.r, noteEditingCellPos.c) : node;
    const existing = noteEditingTaskId
      ? getTaskNotes(noteEditingNoteOwner(taskHost))
      : noteEditingCellPos
      ? getCellNotes(getCellAttach(node, noteEditingCellPos.r, noteEditingCellPos.c))
      : (noteEditingPhotoId ? getPhotoNotes(node, noteEditingPhotoId) : getNodeNotes(node));
    noteWorkingList = existing.map(n => ({ id: n.id || uid(), title: n.title || "", html: n.html, favorite: !!n.favorite, createdAt: n.createdAt, updatedAt: n.updatedAt }));
    // The "DRC" context-menu shortcut (see the Tasks/Timer/Brainstorm
    // group below). Only one DRC note is allowed per node: if one
    // already exists among this node's notes (title "DRC" — see
    // isDRCNote), just jump to it instead of starting another; only when
    // there isn't one yet does this start a brand-new note pre-filled
    // with the template. Titling it "DRC" is what makes isDRCNote/
    // drcPoints/the node-strip icon recognize it — not a separate
    // internal flag — so a note gets the same treatment if the title is
    // set to "DRC" any other way too.
    if (forceDRCTemplate) {
      const existingDRCIndex = noteWorkingList.findIndex(n => isDRCNote(n));
      if (existingDRCIndex >= 0) {
        noteActiveIndex = existingDRCIndex;
      } else {
        noteWorkingList.push({ id: uid(), title: "DRC", html: noteHtmlFromDRCTemplate(getDRCTemplateText()), createdAt: Date.now(), updatedAt: Date.now() });
        noteActiveIndex = noteWorkingList.length - 1;
      }
    } else {
      const wantsNew = index != null && index >= noteWorkingList.length;
      if (!noteWorkingList.length || wantsNew) {
        // A task/subtask named "plan" with no note yet starts from the
        // "Plan" note template (if one is saved) instead of a blank note.
        const planSeed = (noteEditingTaskId && !noteWorkingList.length)
          ? planTemplateSeedFor(noteEditingNoteOwner(taskHost)) : null;
        noteWorkingList.push({ id: uid(), title: planSeed ? planSeed.title : "", html: planSeed ? planSeed.html : "", createdAt: Date.now(), updatedAt: Date.now() });
      }
      noteActiveIndex = wantsNew ? noteWorkingList.length - 1
        : clamp(index == null ? noteWorkingList.length - 1 : index, 0, noteWorkingList.length - 1);
    }
    loadNoteIntoEditor();
    // A photo's note is really a caption/comment on that photo, viewed
    // right after (or over) the photo itself, so it benefits from more
    // horizontal room than a regular node/task/cell note — give it 2x the
    // default width. Reset back to the normal width for every other note
    // type so a previous photo-note session doesn't leak into them.
    noteCard.style.width = noteEditingPhotoId ? "1520px" : "";
    zoomModalOpen(noteModal);
    const current = noteWorkingList[noteActiveIndex];
    const isBlank = !(current.title && current.title.trim()) && !(current.html && current.html.trim());
    requestAnimationFrame(() => { (isBlank ? noteTitleInput : noteTextarea).focus(); });
  }

  // Simple "Lines: N" readout in the editor's corner — counts actual
  // line breaks (one per paragraph/checklist/list line, same unit as
  // pressing Enter), not wrapped display lines, same as a plain text
  // editor's line count. innerText (not textContent) so block-level
  // line breaks between the editor's line <div>s are included. Shared
  // by both a node's own notes and a task's notes, since they're the
  // exact same editor element (see loadNoteIntoEditor).
  function updateNoteLineCount() {
    if (!noteLineCountEl) return;
    noteLineCountEl.textContent = "Lines: " + noteTextarea.innerText.split("\n").length;
  }

  // Loads noteWorkingList[noteActiveIndex] into the visible editor and
  // refreshes the nav row (‹ 2 / 3 › + 🗑) to match.
  function loadNoteIntoEditor() {
    const node = findNode(noteEditingId);
    const current = noteWorkingList[noteActiveIndex];
    noteTitleInput.value = current.title || "";
    if (noteEditingTaskId) {
      const taskHost = noteEditingCellPos ? getCellAttach(node, noteEditingCellPos.r, noteEditingCellPos.c) : node;
      const t = noteEditingNoteOwner(taskHost);
      const kind = noteEditingSubtaskId ? "subtask" : "task";
      noteTextarea.dataset.placeholder = `Note for ${kind} "${t ? (t.text || `(untitled ${kind})`) : ""}"…`;
      noteNavAdd.title = `Start a new note on this ${kind}`;
    } else if (noteEditingCellPos) {
      noteTextarea.dataset.placeholder = "Note for this cell…";
      noteNavAdd.title = "Start a new note on this cell";
    } else if (noteEditingPhotoId) {
      noteTextarea.dataset.placeholder = "Note on this photo…";
      noteNavAdd.title = "Start a new note on this photo";
    } else {
      noteTextarea.dataset.placeholder = `Note for "${node ? (node.text || "(untitled)") : ""}"…`;
      noteNavAdd.title = "Start a new note on this node";
    }
    noteTextarea.innerHTML = noteHtmlFromRaw(current.html);
    // Retire any old Mood-To-Day widget stored in this note, preserving its
    // selected face as ordinary emoji text. Then run the existing photo/URL
    // migrations. Any migration is saved through the normal autosave path.
    const migratedMood = noteMigrateLegacyMoodBlocks();
    const migratedPhotos = hydrateNotePhotoImages();
    const linkedUrls = noteLinkifyUrls(noteTextarea, false);
    if (migratedMood || migratedPhotos || linkedUrls) scheduleNoteAutosave();
    setNoteAutoColorEnabled(!isDRCNote(current));
    refreshDRCCards();
    noteSyncAllCheckedLines();
    noteSyncAllOrderedColors();
    noteAutoColorParagraphs();
    noteResetUndoHistory();
    updateNoteNavUI();
    updateNoteLineCount();
    updateNoteFavoriteUI();
    updateNoteFolderUI();
    updateNoteColorToolAvailability();
    noteDownscaleOversizedImagesInEditor();
  }

  // One-time self-heal for notes that already had an oversized image
  // embedded before downscaleNoteImageDataUrl existed (see
  // noteHandleImageFiles) — shrinks any still-oversized <img> already
  // sitting in this note the moment it's opened, then lets the normal
  // autosave commit the smaller version. Without this, an old bloated
  // note keeps re-triggering the same full-map-tree stringify (see
  // pushUndo/persist) on every edit, forever, even after new pastes stop
  // adding to the problem.
  function noteDownscaleOversizedImagesInEditor() {
    if (!NOTE_IMAGE_DOWNSCALE) return; // photos are kept at full quality — see NOTE_IMAGE_DOWNSCALE
    const oversized = Array.from(noteTextarea.querySelectorAll("img[src^='data:']"))
      .filter(img => img.src.length > NOTE_IMAGE_SKIP_BYTES);
    if (!oversized.length) return;
    Promise.all(oversized.map((img) => downscaleNoteImageDataUrl(img.src).then((smaller) => {
      if (smaller && smaller !== img.src) img.src = smaller;
    }))).then(() => {
      // commitNotesToNode only actually writes/pushUndo's if the note's
      // serialized content changed, so this is a no-op when nothing here
      // needed shrinking after all.
      scheduleNoteAutosave();
    });
  }

  // Syncs the ☆/★ favorite button in the note editor's nav row to match
  // whichever note is currently loaded (see loadNoteIntoEditor) — same
  // idea as toggleNoteFavorite below, just the read side.
  function updateNoteFavoriteUI() {
    const current = noteWorkingList[noteActiveIndex];
    const fav = !!(current && current.favorite);
    noteNavFavorite.textContent = fav ? "★" : "☆";
    noteNavFavorite.classList.toggle("favorited", fav);
    noteNavFavorite.title = fav ? "Remove from favorites" : "Add to favorites";
    noteNavFavorite.setAttribute("aria-label", noteNavFavorite.title);
  }

  // Toggles the favorite star on whichever note is currently loaded in the
  // editor and saves immediately — same commit-on-change behavior as
  // adding/deleting a note (see addAnotherNote/deleteActiveNote), so the
  // star shows up in the "Favorites" sidebar browser right away.
  function toggleNoteFavorite() {
    const current = noteWorkingList[noteActiveIndex];
    if (!current) return;
    captureActiveNote();
    current.favorite = !current.favorite;
    updateNoteFavoriteUI();
    updateNoteFolderUI();
    commitNotesToNode();
  }

  function updateNoteNavUI() {
    // No more pager buttons/label to sync — paging between notes is now
    // keyboard-only (Alt+←/→), see the keydown handlers below.
  }

  // Syncs the 📁 button in the note editor's nav row to whichever note is
  // currently loaded — hidden for a DRC note or a starred one, same
  // reasoning as the Notes browser rows (see the isDRC/favorite branch
  // in buildNoteBrowserRow): either one's folder isn't a choice —
  // syncDRCFolderAssignments/syncFavoriteFolderAssignments would just
  // put it straight back — so a button here would silently undo itself.
  function updateNoteFolderUI() {
    if (!noteNavFolder) return;
    const current = noteWorkingList[noteActiveIndex];
    const forced = !!(current && (isDRCNote(current) || current.favorite));
    noteNavFolder.classList.toggle("hidden", forced);
    if (forced) return;
    const folder = current ? notesFolderMgr.folderOf(current.id) : null;
    noteNavFolder.title = folder ? `In folder: ${folder}` : "Move to folder";
    noteNavFolder.classList.toggle("has-folder", !!folder);
  }

  // Shared QUEUE TASKS task. It is rendered as the first task in every
  // Tasks modal, but its subtasks are stored globally rather than on that
  // node. This makes it a true inbox/queue that is the same on phone, PC,
  // and every task list. Completed queue subtasks are always sorted last.
  let sharedQueueAddOpen = false;

  function openSharedQueueSubtaskMenu(x, y, s) {
    resetContextMenu();
    const addItem = (label, cls, fn) => {
      const it = document.createElement("div");
      it.className = "ctx-item" + (cls ? " " + cls : "");
      const labelSpan = document.createElement("span");
      labelSpan.className = "ctx-item-label";
      labelSpan.textContent = label;
      it.appendChild(labelSpan);
      it.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); fn(); });
      ctxMenu.appendChild(it);
    };
    addItem(s.failed ? "\u21a9 Clear failed" : "Mark failed", "", () => {
      updateDRCQueueSubtask(s.id, (live) => {
        live.failed = !live.failed;
        if (live.failed) live.done = false;
      });
    });
    addItem("Copy text", "", () => copySubtaskText(s.text || ""));
    addItem("Delete subtask", "danger", () => {
      if (!confirm(`Delete the subtask "${s.text || "Untitled subtask"}"?`)) return;
      deleteDRCQueueSubtask(s.id);
    });
    positionContextMenu(x, y);
  }

  function setAllSharedQueueDone(done) {
    if (!requireSignIn()) return;
    const items = getDRCQueueItems();
    const now = Date.now();
    let changed = false;
    items.forEach((s, i) => {
      if (!!s.done === !!done && (!done || !s.failed)) return;
      s.done = !!done;
      if (done) s.failed = false;
      s.updatedAt = now + i;
      changed = true;
    });
    if (changed) saveDRCQueueMutation(items);
  }

  function renderSharedQueueTask() {
    if (!tasksListEl) return;
    const items = drcQueueDisplayItems();
    const doneCount = items.filter(x => x.done).length;
    const allDone = items.length > 0 && doneCount === items.length;

    const taskRow = document.createElement("li");
    taskRow.className = "task-row shared-queue-task-row has-open-subtasks" + (allDone ? " done" : "");
    taskRow.dataset.sharedQueue = "1";

    const cb = document.createElement("input");
    cb.type = "checkbox";
    cb.className = "task-checkbox";
    cb.checked = allDone;
    cb.title = allDone ? "Mark all queue subtasks undone" : "Mark all queue subtasks done";
    cb.addEventListener("change", (e) => {
      e.stopPropagation();
      setAllSharedQueueDone(cb.checked);
    });

    const title = document.createElement("span");
    title.className = "task-text";
    title.textContent = "QUEUE TASKS";
    title.contentEditable = "false";
    title.title = "Shared queue — synced across every task list and device";

    const count = document.createElement("span");
    count.className = "shared-queue-count";
    count.textContent = items.length ? `${doneCount}/${items.length}` : "0";

    const addBtn = document.createElement("button");
    addBtn.type = "button";
    addBtn.className = "task-subtask-btn shared-queue-add-btn";
    addBtn.textContent = "+";
    addBtn.title = "Add a queue subtask";
    addBtn.addEventListener("mousedown", (e) => e.stopPropagation());
    addBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      if (!requireSignIn()) return;
      sharedQueueAddOpen = true;
      renderTasksModal();
    });

    taskRow.append(cb, title, count, addBtn);
    tasksListEl.appendChild(taskRow);

    const wrap = document.createElement("li");
    wrap.className = "subtask-panel shared-queue-subtask-panel";

    const list = document.createElement("ul");
    list.className = "subtask-list";

    items.forEach((s) => {
      const row = document.createElement("li");
      row.className = "subtask-row" + (s.done ? " done" : "") + (s.failed ? " failed" : "");
      row.dataset.subtaskId = s.id;
      row.draggable = false;

      const stext = document.createElement("span");
      stext.className = "subtask-text";
      stext.contentEditable = "false";
      stext.spellcheck = false;
      stext.textContent = s.text || "";
      stext.title = s.text || "";

      let clickTimer = null;
      row.addEventListener("click", (e) => {
        if (row.__subtaskLongPressConsumed) {
          e.preventDefault();
          e.stopPropagation();
          row.__subtaskLongPressConsumed = false;
          if (clickTimer) { clearTimeout(clickTimer); clickTimer = null; }
          return;
        }
        if (stext.contentEditable === "true") return;
        if (clickTimer) { clearTimeout(clickTimer); clickTimer = null; return; }
        clickTimer = setTimeout(() => {
          clickTimer = null;
          updateDRCQueueSubtask(s.id, (live) => {
            live.done = !live.done;
            if (live.done) live.failed = false;
          });
        }, 220);
      });

      stext.addEventListener("dblclick", (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (!requireSignIn()) return;
        stext.contentEditable = "true";
        stext.focus();
        const sel = window.getSelection();
        const range = document.createRange();
        range.selectNodeContents(stext);
        sel.removeAllRanges();
        sel.addRange(range);
      });
      stext.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Enter") { e.preventDefault(); stext.blur(); }
        else if (e.key === "Escape") { e.preventDefault(); stext.textContent = s.text || ""; stext.blur(); }
      });
      stext.addEventListener("blur", () => {
        const v = stext.textContent.trim();
        stext.contentEditable = "false";
        if (v && v !== (s.text || "")) updateDRCQueueSubtask(s.id, (live) => { live.text = v; });
        else stext.textContent = s.text || "";
      });

      row.addEventListener("contextmenu", (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (row.__subtaskLongPressConsumed) return;
        openSharedQueueSubtaskMenu(e.clientX, e.clientY, s);
      });
      installSubtaskLongPress(row, (x, y) => openSharedQueueSubtaskMenu(x, y, s));

      row.appendChild(stext);
      list.appendChild(row);
    });

    if (!sharedQueueAddOpen) {
      const addTriggerLi = document.createElement("li");
      addTriggerLi.className = "subtask-add-trigger shared-queue-add-trigger";
      const trigger = document.createElement("button");
      trigger.type = "button";
      trigger.className = "subtask-add-btn";
      trigger.textContent = "+";
      trigger.title = "Add a queue subtask";
      trigger.addEventListener("click", (e) => {
        e.stopPropagation();
        if (!requireSignIn()) return;
        sharedQueueAddOpen = true;
        renderTasksModal();
      });
      addTriggerLi.appendChild(trigger);
      list.appendChild(addTriggerLi);
    }

    wrap.appendChild(list);

    if (sharedQueueAddOpen) {
      const addRow = document.createElement("div");
      addRow.className = "subtask-add-row";
      const input = document.createElement("textarea");
      input.rows = 1;
      input.className = "subtask-new-input autosize-input shared-queue-new-input";
      input.placeholder = "Add a queue subtask and press Enter…";
      input.spellcheck = false;
      input.addEventListener("input", () => autosizeTextarea(input));
      input.addEventListener("click", (e) => e.stopPropagation());
      input.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Enter" && !e.shiftKey) {
          e.preventDefault();
          const v = input.value.trim();
          if (!v) return;
          if (addDRCQueueSubtask(v)) {
            sharedQueueAddOpen = true;
            requestAnimationFrame(() => {
              const el = tasksListEl.querySelector(".shared-queue-new-input");
              if (el) el.focus();
            });
          }
        } else if (e.key === "Escape") {
          e.preventDefault();
          sharedQueueAddOpen = false;
          renderTasksModal();
        }
      });
      input.addEventListener("blur", () => {
        if (!input.value.trim()) {
          sharedQueueAddOpen = false;
          renderTasksModal();
        }
      });
      addRow.appendChild(input);
      wrap.appendChild(addRow);
      requestAnimationFrame(() => {
        const el = tasksListEl.querySelector(".shared-queue-new-input");
        if (el) el.focus();
      });
    }

    tasksListEl.appendChild(wrap);
  }

  // Shows the open note as cards when its title is "DRC", or when it has
  // any card added with the 🗂 button — see decorateDRCCards. Cheap and idempotent, so it's simply
  // re-run after every load/edit/undo and whenever the title changes.
  function refreshDRCCards() {
    const mode = isDRCNote({ title: noteTitleInput.value }) ? "note"
      : (noteTextarea.querySelector(":scope > [data-card]") ? "cards" : null);
    decorateDRCCards(noteTextarea, mode);
  }
  let drcNoteCardsRaf = 0;
  function refreshDRCCardsSoon() {
    if (drcNoteCardsRaf) return;
    drcNoteCardsRaf = requestAnimationFrame(() => { drcNoteCardsRaf = 0; refreshDRCCards(); });
  }

  // Reads whatever's currently in the editor (title + body) back into the
  // working list, without touching the node yet — called before
  // navigating away from the note currently on screen so nothing typed
  // is lost.
  function captureActiveNote() {
    const current = noteWorkingList[noteActiveIndex];
    if (!current) return;
    const newTitle = noteTitleInput.value;
    // The card decoration (classes + CSS variables) lives only in the open
    // editor — never in what's saved — so merely opening a DRC note isn't
    // counted as changing it.
    const newHtml = stripNotePhotoSrcForStorage(
      noteTextarea.classList.contains("drc-cards")
        ? drcStripCardMarkup(noteTextarea.innerHTML)
        : noteTextarea.innerHTML
    );
    if (current.title !== newTitle || current.html !== newHtml) {
      current.updatedAt = Date.now();
      // Backfills a timestamp for notes written before this field existed,
      // the first time one of them actually gets touched again — rather
      // than leaving createdAt permanently blank for every pre-existing
      // note (see the Notes browser's date sort, which falls back to "no
      // date" only when neither field is set).
      if (!current.createdAt) current.createdAt = current.updatedAt;
    }
    current.title = newTitle;
    current.html = newHtml;
  }

  function goToNote(delta) {
    captureActiveNote();
    noteActiveIndex = clamp(noteActiveIndex + delta, 0, noteWorkingList.length - 1);
    loadNoteIntoEditor();
    commitNotesToNode();
  }

  function addAnotherNote() {
    captureActiveNote();
    noteWorkingList.push({ id: uid(), title: "", html: "", createdAt: Date.now(), updatedAt: Date.now() });
    noteActiveIndex = noteWorkingList.length - 1;
    loadNoteIntoEditor();
    commitNotesToNode();
    requestAnimationFrame(() => { noteTitleInput.focus(); });
  }

  // Deletes the note currently in the editor. If it's the only one left,
  // just clears it instead — closing the marker down to zero without
  // leaving the editor in a no-notes-open state.
  function deleteActiveNote() {
    captureActiveNote();
    if (noteWorkingList.length <= 1) {
      noteWorkingList[0].title = "";
      noteWorkingList[0].html = "";
    } else {
      noteWorkingList.splice(noteActiveIndex, 1);
      noteActiveIndex = clamp(noteActiveIndex, 0, noteWorkingList.length - 1);
    }
    loadNoteIntoEditor();
    commitNotesToNode();
  }

  function closeNoteModal() {
    closeNoteTemplatesPopover();
    clearTimeout(noteLinkifyTimer);
    noteLinkifyTimer = null;
    // Catch a URL typed at the very end of a note even if the 250ms idle
    // recognizer has not fired yet, then flush that final HTML to storage.
    noteLinkifyUrls(noteTextarea, false);
    flushNoteAutosave();
    noteEditingId = null;
    noteEditingPhotoId = null;
    noteEditingTaskId = null;
    noteEditingSubtaskId = null;
    noteEditingCellPos = null;
    noteWorkingList = [];
    noteActiveIndex = 0;
    noteReturn = null;
    $("#note-color-popover").classList.add("hidden");
    $("#note-emoji-popover").classList.add("hidden");
    zoomModalClose(noteModal);
  }

  // Debounced autosave: fires a short beat after the user stops typing,
  // so notes save themselves without needing an explicit Save click.
  function scheduleNoteAutosave() {
    captureActiveNote();
    updateNoteLineCount();
    clearTimeout(noteSaveTimer);
    noteSaveTimer = setTimeout(commitNotesToNode, 500);
  }

  function flushNoteAutosave() {
    clearTimeout(noteSaveTimer);
    noteSaveTimer = null;
    commitNotesToNode();
  }

  // Writes noteWorkingList onto the node's `notes` array, or (when
  // noteEditingPhotoId is set) onto that one photo's own note list
  // instead — see getPhotoNotes/setPhotoNotes. Entries that are still
  // genuinely blank (no title and never typed into) are dropped so an
  // idle "+ New note" click doesn't leave a phantom entry inflating the
  // marker's count — matches the old single-note behavior, where an
  // empty note never made the marker appear in the first place.
  function commitNotesToNode() {
    const node = findNode(noteEditingId);
    if (!node) return;
    captureActiveNote();
    const cleaned = noteWorkingList.filter(n => (n.title && n.title.trim()) || (n.html && n.html.trim()));
    if (noteEditingTaskId) {
      const taskHost = noteEditingCellPos ? getCellAttach(node, noteEditingCellPos.r, noteEditingCellPos.c) : node;
      const t = noteEditingNoteOwner(taskHost);
      if (!t) return;
      const before = JSON.stringify(getTaskNotes(t));
      const after = JSON.stringify(cleaned);
      if (before !== after) {
        pushUndo();
        t.notes = cleaned;
        t.note = "";
        renderAll();
        persist();
        if (!tasksModal.classList.contains("hidden")) renderTasksModal();
      }
      return;
    }
    if (noteEditingCellPos) {
      const a = getCellAttach(node, noteEditingCellPos.r, noteEditingCellPos.c);
      const before = JSON.stringify(getCellNotes(a));
      const after = JSON.stringify(cleaned);
      if (before !== after) {
        pushUndo();
        a.notes = cleaned.length ? cleaned : null;
        a.note = null;
        renderAll();
        persist();
      }
      return;
    }
    if (noteEditingPhotoId) {
      const before = JSON.stringify(getPhotoNotes(node, noteEditingPhotoId));
      const after = JSON.stringify(cleaned);
      if (before !== after) {
        pushUndo();
        setPhotoNotes(node, noteEditingPhotoId, cleaned);
        renderAll();
        persist();
      }
      return;
    }
    const before = JSON.stringify(getNodeNotes(node));
    const after = JSON.stringify(cleaned);
    if (before !== after) {
      pushUndo();
      node.notes = cleaned;
      node.note = "";
      renderAll();
      persist();
    }
  }


  // Finds the block-level "line" element containing the caret, so toolbar
  // actions and Enter-to-continue behave per line rather than globally.
  // Takes the editable container so this also serves the per-task note
  // editor (a second, simpler contenteditable) below, not just the
  // per-node rich note editor.
  function noteCurrentLine(container = noteTextarea) {
    const sel = window.getSelection();
    if (!sel.rangeCount) return null;
    const range = sel.getRangeAt(0);
    let node = range.startContainer;
    if (node.nodeType === 3) {
      node = node.parentNode;
    } else if (node.childNodes.length) {
      // The caret's container can itself be an *element* rather than a
      // text node — most commonly right at the very end of the whole
      // editor (after the last character of the last line), where the
      // browser reports the selection as sitting inside `container`
      // itself, past its last child, instead of inside a leaf text node.
      // Left unhandled, the walk below would immediately see node ===
      // container and bail out to null — which then made every caller
      // (notably noteHandleEnter) fall back to treating the *entire*
      // editor as "the current line," splitting/overwriting all lines
      // at once instead of just the one the caret is actually on.
      // Resolving to the adjacent child first fixes that: offset 0 means
      // "before the first child" (use it), any other offset means "after
      // the child before it" (use that one, clamped to the last child).
      const idx = Math.min(Math.max(range.startOffset - 1, 0), node.childNodes.length - 1);
      node = node.childNodes[idx];
    }
    while (node && node !== container && node.parentNode !== container) {
      node = node.parentNode;
    }
    return node === container ? null : node;
  }

  // True when the caret sits at the very start of lineDiv's text (nothing
  // typed before it on that line) — used so an inserted photo lands above
  // the line instead of below it when the cursor is at position zero.
  function noteCaretIsAtLineStart(lineDiv) {
    if (!lineDiv) return false;
    const sel = window.getSelection();
    if (!sel.rangeCount) return false;
    const range = sel.getRangeAt(0);
    if (!range.collapsed) return false;
    const preRange = document.createRange();
    preRange.selectNodeContents(lineDiv);
    try {
      preRange.setEnd(range.startContainer, range.startOffset);
    } catch (err) {
      return false; // caret isn't actually inside lineDiv
    }
    return preRange.toString().length === 0;
  }

  function noteSelectLine(lineDiv) {
    const target = lineDiv || noteTextarea;
    const r = document.createRange();
    r.selectNodeContents(target);
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(r);
  }

  // Toggles a line-start prefix like "☐ " on the current line — powers the
  // checklist toolbar button. (The numbered-list button has its own
  // function below, since it also needs to manage per-number colors.)
  function noteToggleLinePrefix(prefixRegex, makePrefix) {
    noteTextarea.focus();
    notePushUndo();
    const lineDiv = noteCurrentLine();
    const el = lineDiv || noteTextarea;
    const text = el.textContent;
    const match = text.match(prefixRegex);
    el.textContent = match ? text.slice(match[0].length) : makePrefix() + text;
    noteSyncLineChecked(el);
    placeCaretAtEnd(el);
    scheduleNoteAutosave();
  }

  // Each numbered line gets its own color, cycling through this palette by
  // its number (1, 2, 3, ... wrapping back to the start), so consecutive
  // list items are easy to tell apart at a glance.
  const NOTE_OL_COLORS = [
    "#b5504a", // red
    "#c98a3a", // orange
    "#5a8f5a", // green
    "#4a72b5", // blue
    "#8a5fb0", // purple
    "#3a8f8a", // teal
    "#a5723a", // brown
    "#6a6a2b", // olive
  ];
  function noteColorForOrdinal(n) {
    return NOTE_OL_COLORS[(n - 1) % NOTE_OL_COLORS.length];
  }

  // Gives every plain paragraph (a line broken off by pressing Enter) its
  // own color, cycling through the same palette as numbered-list lines, so
  // separate paragraphs in a note are easy to tell apart at a glance even
  // without numbering them. Only touches lines that don't have a color of
  // their own yet, so it never overwrites a numbered/checklist line's own
  // ordinal color, or a color someone already picked by hand for a whole
  // line. A manual foreColor selection over just *part* of a line (via the
  // toolbar) is a separate <font>/span wrapper inside the line, not this
  // div-level style, so the two never fight over the same text either.
  // `container` defaults to the per-node rich note editor but also serves
  // the per-task note editor.
  let noteAutoColorEnabled = true;
  // Shared by the toggle button below and by loadNoteIntoEditor (which
  // defaults it off specifically for DRC notes — see isDRCNote — since a
  // Daily Report Card reads better as plain, uniform text rather than a
  // cycling rainbow of line colors). `btn` is passed in lazily since this
  // runs before the button element itself is declared further down.
  function setNoteAutoColorEnabled(enabled) {
    noteAutoColorEnabled = enabled;
    const btn = $("#note-tool-autocolor");
    if (!btn) return;
    btn.classList.toggle("active", enabled);
    btn.setAttribute("aria-pressed", String(enabled));
    btn.title = "Auto alternate line colors: " + (enabled ? "on" : "off");
  }
  function noteAutoColorParagraphs(container = noteTextarea) {
    if (!noteAutoColorEnabled) return;
    let idx = 0;
    Array.from(container.children).forEach(el => {
      if (el.classList && el.classList.contains("note-mood")) return; // the Mood To Day block has its own colors
      const text = el.textContent || "";
      // Numbered/checklist lines keep their own ordinal-based color, and an
      // image line has no text to color — skip both instead of assigning
      // them a paragraph color too.
      if (/^(\d+\.\s|[☐☑])\s?/.test(text)) return;
      if (el.querySelector && el.querySelector("img")) return;
      if (!el.style.color) el.style.color = noteColorForOrdinal(idx + 1);
      idx++;
    });
  }

  // Colors a line based on the number in its own "N. " prefix, or clears
  // the color if the line isn't numbered. Applied at the div level (not
  // wrapped in a span), so it never collides with a manual foreColor
  // selection made via the color picker inside the line's text.
  // Follows the 🎨 auto-color toggle like every other auto color: while
  // it's off (the default for DRC notes) numbered lines are left exactly
  // as they are — every caller (the 1. button, Enter continuing a list,
  // loading/undoing a note) goes through here, so this is the one gate.
  function noteSetOrderedLineColor(el) {
    if (!el || !noteAutoColorEnabled) return;
    const match = (el.textContent || "").match(/^(\d+)\.\s/);
    el.style.color = match ? noteColorForOrdinal(parseInt(match[1], 10)) : "";
  }

  // Re-applies auto ordinal colors across every line, for notes loaded
  // from storage (or imported/exported) that have numbered prefixes but no
  // inline color saved yet. `container` defaults to the per-node rich note
  // editor but is also passed the per-task note editor.
  function noteSyncAllOrderedColors(container = noteTextarea) {
    if (!noteAutoColorEnabled) return;
    Array.from(container.children).forEach(el => {
      if (/^\d+\.\s/.test(el.textContent || "") && !el.style.color) {
        noteSetOrderedLineColor(el);
      }
    });
  }

  // Toggles the "N. " prefix on the current line, auto-coloring the line
  // by its number when turning numbering on, and clearing that auto-color
  // when turning it off.
  function noteToggleOrderedList() {
    noteTextarea.focus();
    notePushUndo();
    const lineDiv = noteCurrentLine();
    const el = lineDiv || noteTextarea;
    const text = el.textContent;
    const match = text.match(/^\d+\.\s+/);
    if (match) {
      el.textContent = text.slice(match[0].length);
      el.style.color = "";
    } else {
      el.textContent = "1. " + text;
      noteSetOrderedLineColor(el);
    }
    noteSyncLineChecked(el);
    placeCaretAtEnd(el);
    scheduleNoteAutosave();
  }

  function noteApplyForeColor(color) {
    noteTextarea.focus();
    notePushUndo();
    const sel = window.getSelection();
    if (sel.rangeCount && sel.getRangeAt(0).collapsed) {
      noteSelectLine(noteCurrentLine());
    }
    document.execCommand("foreColor", false, color);
    scheduleNoteAutosave();
  }

  // Previously greyed out and disabled the color-picker trigger while a
  // DRC note was loaded, forcing DRC notes to stay plain black text. Now
  // a no-op so the text-color tool stays available for DRC notes too.
  function updateNoteColorToolAvailability() {
    noteColorTriggerBtn.disabled = false;
    noteColorTriggerBtn.classList.remove("disabled");
    noteColorTriggerBtn.title = "Text color";
  }

  function noteApplyStrikethrough() {
    noteTextarea.focus();
    notePushUndo();
    const sel = window.getSelection();
    if (sel.rangeCount && sel.getRangeAt(0).collapsed) {
      noteSelectLine(noteCurrentLine());
    }
    document.execCommand("strikeThrough");
    scheduleNoteAutosave();
  }

  function noteApplyBold() {
    noteTextarea.focus();
    const sel = window.getSelection();
    const collapsed = !sel.rangeCount || sel.getRangeAt(0).collapsed;
    if (collapsed) {
      // No selection: don't touch existing text. Just flip the "type in
      // bold" state for whatever gets typed next — the button below
      // reflects this via queryCommandState so it shows pressed exactly
      // while it's in effect, same as Word.
      document.execCommand("bold");
    } else {
      notePushUndo();
      document.execCommand("bold");
      scheduleNoteAutosave();
    }
    updateNoteToolActiveStates();
  }

  function noteApplyUppercase() {
    noteTextarea.focus();
    const sel = window.getSelection();
    const collapsed = !sel.rangeCount || sel.getRangeAt(0).collapsed;
    if (collapsed) {
      // No selection: arm/disarm "type in caps" mode for what comes next
      // (see the beforeinput hook below) instead of uppercasing anything
      // that already exists.
      noteUppercasePending = !noteUppercasePending;
      updateNoteToolActiveStates();
      return;
    }
    notePushUndo();
    const text = sel.toString();
    if (!text) return;
    document.execCommand("insertText", false, text.toUpperCase());
    scheduleNoteAutosave();
    updateNoteToolActiveStates();
  }

  function noteInsertSymbol(symbol) {
    noteTextarea.focus();
    notePushUndo();
    document.execCommand("insertText", false, symbol);
    scheduleNoteAutosave();
  }

  // Enter key on a numbered or checklist line continues the pattern
  // ("1." -> "2.", "☐" -> "☐"); pressing Enter on an empty list line
  // breaks out of the list instead of continuing it forever.
  //
  // The split happens at the caret, not always at the end of the line:
  // whatever was typed before the caret stays on the current line, and
  // whatever was typed after it moves down onto the new list line (same
  // as a normal editor). Without this, pressing Enter with the caret at
  // the very start of a line's typed content (right after the "☐ "/"1. "
  // prefix) would leave the line's text untouched and just add a new,
  // empty list item below it — moving the cursor without moving the text
  // the user meant to push down.
  // Splits a plain (non-numbered, non-checklist) line into two SIBLING
  // <div>s ourselves on Enter, instead of letting the browser's native
  // "insertParagraph" handle it. Left to the browser, pressing Enter a
  // second (or later) time inside an existing line <div> can nest the
  // new line INSIDE that div rather than placing it next to it as a
  // sibling — invisible while just reading the note, but it breaks
  // every bit of per-line logic that walks the editor's direct children
  // (notably noteAutoColorParagraphs' cycling palette), since a nested
  // line is never seen as a line of its own and just inherits its
  // parent's color instead of getting the next one in rotation — which
  // is why every line after the first can end up stuck on one color.
  // Splitting via Range.extractContents (rather than textContent, which
  // would flatten any bold/colored spans already in the line) keeps
  // existing inline formatting intact on both halves of the split.
  // A bare <br> for an empty line, or that <br> wrapped in a <font color>
  // when `color` isn't the note's plain default — used when a new line
  // has nothing extracted onto it (see noteHandlePlainLineEnter below).
  // Without this, an empty line has no colored span for the caret to sit
  // inside, so anything typed on it falls back to the browser's default
  // black instead of continuing in whatever color the line above it was.
  const NOTE_DEFAULT_TEXT_RGB = "rgb(43, 42, 37)"; // #2b2a25, the "Default text" swatch
  // `baseRgb` (optional) is the color the line itself already renders in —
  // e.g. its own div-level color. The <font> wrapper is only needed when the
  // caret color differs from that, not from the global default.
  function noteEmptyLineContent(color, baseRgb) {
    const br = document.createElement("br");
    const plain = (baseRgb || NOTE_DEFAULT_TEXT_RGB).replace(/\s+/g, "");
    if (!color || color.replace(/\s+/g, "") === plain) return br;
    const font = document.createElement("font");
    font.setAttribute("color", color);
    font.appendChild(br);
    return font;
  }

  function noteHandlePlainLineEnter(el, sel) {
    if (el === noteTextarea) return false; // no wrapping div yet — let the browser create the very first one
    notePushUndo();
    // Capture the color in effect right at the caret before splitting —
    // needed below if either half of the split ends up empty.
    const caretColor = document.queryCommandValue("foreColor");
    // With 🎨 auto-color off nothing re-colors lines for us, so Enter has to
    // carry the current color over by itself: the line's own div-level color
    // (left over from when auto-color was on) and whatever inline color the
    // caret is sitting in. With it on, noteAutoColorParagraphs below keeps
    // assigning the next color in the rotation, as before.
    const keepColor = !noteAutoColorEnabled;
    const range = sel.getRangeAt(0);
    const afterRange = document.createRange();
    afterRange.setStart(range.startContainer, range.startOffset);
    // An empty line (no children yet) has nothing after the caret to
    // move — end the range right where it started rather than calling
    // setEndAfter(el), which would straddle el's own boundary and throw.
    if (el.lastChild) afterRange.setEndAfter(el.lastChild);
    else afterRange.setEnd(range.startContainer, range.startOffset);
    const frag = afterRange.extractContents();
    const newDiv = document.createElement("div");
    if (keepColor && el.style.color) newDiv.style.color = el.style.color;
    el.parentNode.insertBefore(newDiv, el.nextSibling);
    // Caret at the very end of a colored run leaves only empty inline
    // shells (<font color></font>) in the extracted fragment; the caret
    // would then land before them, outside the color. Treat that as an
    // empty line so the color is rebuilt around the caret below.
    const fragHasContent = frag.hasChildNodes() &&
      !(keepColor && !(frag.textContent || "").replace(/\u200b/g, "") && !(frag.querySelector && frag.querySelector("img")));
    let newDivEmptyContent = null;
    if (fragHasContent) newDiv.appendChild(frag);
    else newDiv.appendChild((newDivEmptyContent = noteEmptyLineContent(caretColor, keepColor ? getComputedStyle(newDiv).color : undefined)));
    if (!el.hasChildNodes()) el.appendChild(noteEmptyLineContent(caretColor, keepColor ? getComputedStyle(el).color : undefined));
    noteAutoColorParagraphs();
    const caretRange = document.createRange();
    // If the new line is the empty-<font><br></font> case, put the caret
    // *inside* the font element (before the <br>) so typed text lands
    // inside that colored span instead of as a plain sibling of it.
    if (newDivEmptyContent && newDivEmptyContent.nodeName === "FONT") {
      caretRange.setStart(newDivEmptyContent, 0);
    } else {
      caretRange.selectNodeContents(newDiv);
    }
    caretRange.collapse(true);
    sel.removeAllRanges();
    sel.addRange(caretRange);
    scrollCaretIntoView(newDiv);
    scheduleNoteAutosave();
    return true;
  }

  function noteHandleEnter() {
    const sel = window.getSelection();
    if (!sel.rangeCount || !sel.getRangeAt(0).collapsed) return false;
    const lineDiv = noteCurrentLine();
    const el = lineDiv || noteTextarea;
    const lineText = el.textContent;
    const numMatch = lineText.match(/^(\d+)\.\s+/);
    const checkMatch = lineText.match(/^([☐☑])\s+/);
    if (!numMatch && !checkMatch) return noteHandlePlainLineEnter(el, sel);
    const prefix = (numMatch || checkMatch)[0];
    const rest = lineText.slice(prefix.length);
    if (rest.trim() === "") {
      notePushUndo();
      el.textContent = "";
      placeCaretAtEnd(el);
      scrollCaretIntoView(el);
      scheduleNoteAutosave();
      return true;
    }

    // How much of the line's text (prefix included) sits before the
    // caret, measured via a range from the start of the line to the
    // caret — same technique as noteCaretIsAtLineStart, but keeping the
    // length instead of just checking for zero.
    const range = sel.getRangeAt(0);
    let beforeCaretLen = lineText.length; // fall back to "caret at end"
    try {
      const preRange = document.createRange();
      preRange.selectNodeContents(el);
      preRange.setEnd(range.startContainer, range.startOffset);
      beforeCaretLen = preRange.toString().length;
    } catch (err) { /* keep fallback */ }

    const caretInRest = Math.max(0, Math.min(rest.length, beforeCaretLen - prefix.length));
    const before = rest.slice(0, caretInRest);
    const after = rest.slice(caretInRest);

    notePushUndo();
    const nextPrefix = numMatch ? `${parseInt(numMatch[1], 10) + 1}. ` : "☐ ";
    // With 🎨 auto-color off, the new line must keep the current color:
    // capture it before the text is rewritten below.
    const keepColor = !noteAutoColorEnabled;
    const caretColor = keepColor ? document.queryCommandValue("foreColor") : "";
    // Enter at the end of the line moves no text, so leave the line's
    // markup (and any inline colors in it) untouched instead of flattening
    // it through textContent.
    if (after !== "" || !keepColor) el.textContent = prefix + before;
    if (numMatch) noteSetOrderedLineColor(el);
    noteSyncLineChecked(el);

    const newDiv = document.createElement("div");
    newDiv.textContent = nextPrefix + after;
    if (keepColor) {
      if (el.style.color) newDiv.style.color = el.style.color;
      // Inline color at the caret (picked via the toolbar) isn't inherited
      // by a fresh div, so wrap the new line's text in it when it differs
      // from what the line already renders as.
      if (lineDiv && lineDiv.parentNode) lineDiv.parentNode.insertBefore(newDiv, lineDiv.nextSibling);
      else noteTextarea.appendChild(newDiv);
      const plain = getComputedStyle(newDiv).color.replace(/\s+/g, "");
      if (caretColor && caretColor.replace(/\s+/g, "") !== plain) {
        const font = document.createElement("font");
        font.setAttribute("color", caretColor);
        font.textContent = newDiv.textContent;
        newDiv.textContent = "";
        newDiv.appendChild(font);
      }
    }
    if (numMatch) noteSetOrderedLineColor(newDiv);
    noteSyncLineChecked(newDiv);
    if (!newDiv.parentNode) {
      if (lineDiv && lineDiv.parentNode) {
        lineDiv.parentNode.insertBefore(newDiv, lineDiv.nextSibling);
      } else {
        noteTextarea.appendChild(newDiv);
      }
    }

    // Caret goes right after the new line's prefix — i.e. right before
    // whatever text got pushed down onto it.
    const textNode = newDiv.firstChild && newDiv.firstChild.nodeName === "FONT" ? newDiv.firstChild.firstChild : newDiv.firstChild;
    const caretRange = document.createRange();
    if (textNode && textNode.nodeType === 3) {
      caretRange.setStart(textNode, Math.min(nextPrefix.length, textNode.length));
    } else {
      caretRange.selectNodeContents(newDiv);
    }
    caretRange.collapse(true);
    sel.removeAllRanges();
    sel.addRange(caretRange);
    scrollCaretIntoView(newDiv);
    scheduleNoteAutosave();
    return true;
  }

  // Photos are embedded directly as data-URI <img> tags inside the note's
  // HTML — consistent with the app being fully offline/self-contained, since
  // nothing needs to be uploaded anywhere and the image travels with the
  // map's .json (export, or the mirrored folder file) automatically.
  const noteImageInput = $("#note-image-input");
  // Line (and caret-at-start state) captured at the moment the image-toolbar
  // button is clicked, before the native file picker steals focus/selection
  // away from the note.
  let noteImageInsertLine = null;
  let noteImageInsertAtStart = false;

  // Inserts one line per dataUrl, each containing an <img>, in order.
  // Normally they go right after the current line, with a single empty
  // line left after the last one so the caret has somewhere to keep
  // typing. But if the caret was at the very start of the line (nothing
  // typed before it), the images go above that line instead, since that's
  // where a cursor at position zero implies the photo(s) belong.
  //
  // Every newly inserted photo starts at 20% of the note's own default
  // display size — the same width/height style.css falls back to (see
  // .note-textarea img: width min(420px,100%), height 300px) — rather
  // than full size, since a freshly dropped-in photo is more often
  // glanced at than read closely; the ➖/➕ buttons (see
  // noteImageShrinkBtn/noteImageGrowBtn below) resize it from there.
  const NOTE_IMG_DEFAULT_INSERT_WIDTH = 84;  // 20% of the 420px default width
  const NOTE_IMG_DEFAULT_INSERT_HEIGHT = 60; // 20% of the 300px default height
  // Builds the actual <img> for one inserted photo — stores it in PhotoDB
  // (dedup'd against every other photo already on this map, node photos
  // included, see addPhotoRecord) rather than embedding its base64 bytes
  // straight into the note's HTML. The live DOM element still shows the
  // photo via a normal object-URL src (see photoUrl); only the note's
  // *stored* copy (see captureActiveNote's stripping step) drops that src
  // down to just the data-photo-id reference.
  function noteMakeImageEl(dataUrl) {
    const id = addPhotoRecord(dataUrl);
    const img = document.createElement("img");
    img.dataset.photoId = id;
    img.src = photoUrl(id);
    img.style.width = `${NOTE_IMG_DEFAULT_INSERT_WIDTH}px`;
    img.style.height = `${NOTE_IMG_DEFAULT_INSERT_HEIGHT}px`;
    return img;
  }
  function noteInsertImages(dataUrls, targetLine, atStart) {
    noteTextarea.focus();
    notePushUndo();
    // Prefer the line captured before focus was stolen (e.g. by the native
    // file picker); falling back to a fresh lookup covers callers (like
    // paste) where the selection is still live at call time.
    const lineDiv = targetLine !== undefined ? targetLine : noteCurrentLine();
    const validLine = lineDiv && lineDiv.parentNode === noteTextarea;
    const parent = validLine ? lineDiv.parentNode : noteTextarea;

    if (atStart && validLine) {
      // Place every image above the line, in order, and leave the line
      // (and its caret) untouched below them — no extra spacer line
      // needed since the original line is already there to keep typing
      // into.
      dataUrls.forEach((dataUrl) => {
        const imgLine = document.createElement("div");
        imgLine.appendChild(noteMakeImageEl(dataUrl));
        parent.insertBefore(imgLine, lineDiv);
      });
      const range = document.createRange();
      range.setStart(lineDiv, 0);
      range.collapse(true);
      const sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(range);
    } else {
      let cursor = validLine ? lineDiv : parent.lastChild;
      let lastImgLine = null;
      dataUrls.forEach((dataUrl) => {
        const imgLine = document.createElement("div");
        imgLine.appendChild(noteMakeImageEl(dataUrl));
        parent.insertBefore(imgLine, cursor ? cursor.nextSibling : null);
        cursor = imgLine;
        lastImgLine = imgLine;
      });
      const afterLine = document.createElement("div");
      afterLine.appendChild(document.createElement("br"));
      parent.insertBefore(afterLine, lastImgLine ? lastImgLine.nextSibling : null);
      placeCaretAtEnd(afterLine);
    }
    scheduleNoteAutosave();
  }


  // Single-image convenience wrapper (used by clipboard paste, which only
  // ever offers one image at a time).
  function noteInsertImage(dataUrl, targetLine, atStart) {
    noteInsertImages([dataUrl], targetLine, atStart);
  }

  // Images embedded in a note live inline as base64 in the node's own
  // `notes` array — which is part of the same tree that gets fully
  // JSON.stringify'd on every pushUndo() (map-level undo, fired by the
  // note's own autosave — see commitNotesToNode) and on every persist().
  // Storing screenshots at their original, un-downscaled resolution meant
  // every one of those serializations re-cloned every embedded image
  // across the *whole map*, not just the note being edited — on a
  // trading-journal map with a run of DRC notes full of pasted chart
  // screenshots, a single one of those clones could itself spike memory
  // into an "Out of Memory" tab crash, independent of how many snapshots
  // the undo stacks keep. Downscaling/re-encoding each pasted image here
  // (skipped when it's already small) keeps that per-image cost small
  // regardless of how many screenshots accumulate in the map.
  //
  // Photos are now kept exactly as added: NOTE_IMAGE_DOWNSCALE is off, so
  // nothing is resized or re-encoded on paste/drop/pick, and photos already
  // in a note are no longer shrunk when it's opened. Flip it back to true
  // to restore the memory-saving behavior above (1600px long edge, JPEG 0.85).
  const NOTE_IMAGE_DOWNSCALE = false;
  const NOTE_IMAGE_MAX_DIM = 1600; // long-edge cap, px
  const NOTE_IMAGE_SKIP_BYTES = 400 * 1024; // already-small pastes go through untouched
  function downscaleNoteImageDataUrl(dataUrl) {
    return new Promise((resolve) => {
      if (!NOTE_IMAGE_DOWNSCALE) { resolve(dataUrl); return; } // keep the original bytes, 100% quality
      if (!dataUrl || dataUrl.length <= NOTE_IMAGE_SKIP_BYTES) { resolve(dataUrl); return; }
      const img = new Image();
      img.onload = () => {
        try {
          const scale = Math.min(1, NOTE_IMAGE_MAX_DIM / Math.max(img.width, img.height));
          if (scale >= 1) { resolve(dataUrl); return; } // small dimensions, just a big/lossless file — leave it
          const w = Math.max(1, Math.round(img.width * scale));
          const h = Math.max(1, Math.round(img.height * scale));
          const canvas = document.createElement("canvas");
          canvas.width = w;
          canvas.height = h;
          canvas.getContext("2d").drawImage(img, 0, 0, w, h);
          resolve(canvas.toDataURL("image/jpeg", 0.85));
        } catch (e) {
          resolve(dataUrl); // fail safe — keep the original rather than lose the paste
        } finally {
          img.onload = img.onerror = null;
        }
      };
      img.onerror = () => { img.onload = img.onerror = null; resolve(dataUrl); };
      img.src = dataUrl;
    });
  }

  // Reads every file first (in parallel), downscales any that are large,
  // then inserts them in their original order once they've all finished,
  // so a slow read/downscale never scrambles the sequence.
  function noteHandleImageFiles(fileList, targetLine, atStart) {
    const files = Array.from(fileList || []).filter(f => f && f.type && f.type.startsWith("image/"));
    if (!files.length) return;
    let hadError = false;
    Promise.all(files.map((file) => new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = () => { hadError = true; resolve(null); };
      reader.readAsDataURL(file);
    })))
      .then((dataUrls) => Promise.all(dataUrls.map(downscaleNoteImageDataUrl)))
      .then((dataUrls) => {
        const loaded = dataUrls.filter(Boolean);
        if (loaded.length) noteInsertImages(loaded, targetLine, atStart);
        if (hadError) alert("Some images couldn't be read.");
      });
  }

  // Kept for the single-file paste path.
  function noteHandleImageFile(file, targetLine, atStart) {
    if (!file) return;
    noteHandleImageFiles([file], targetLine, atStart);
  }

  $("#note-tool-image").addEventListener("mousedown", (e) => e.preventDefault());
  $("#note-tool-image").addEventListener("click", () => {
    // Capture the cursor's line (and whether it's at the line's start) now,
    // before the native file picker opens and steals focus/selection out
    // from under the note (see noteInsertImage).
    noteImageInsertLine = noteCurrentLine();
    noteImageInsertAtStart = noteCaretIsAtLineStart(noteImageInsertLine);
    noteImageInput.click();
  });
  noteImageInput.addEventListener("change", () => {
    if (noteImageInput.files && noteImageInput.files.length) {
      noteHandleImageFiles(noteImageInput.files, noteImageInsertLine, noteImageInsertAtStart);
    }
    noteImageInput.value = ""; // reset so picking the same file(s) again still fires change
  });

  noteTextarea.addEventListener("paste", (e) => {
    const items = e.clipboardData && e.clipboardData.items;
    if (!items) return;
    for (const item of items) {
      if (item.type && item.type.startsWith("image/")) {
        e.preventDefault();
        // Capture the line and start-of-line state synchronously, while the
        // selection is still live, before the async file read resolves.
        const pasteLine = noteCurrentLine();
        const pasteAtStart = noteCaretIsAtLineStart(pasteLine);
        noteHandleImageFile(item.getAsFile(), pasteLine, pasteAtStart);
        return;
      }
    }
    // Let the browser perform an ordinary text/rich-text paste first, then
    // convert any plain URLs it inserted. A caret marker keeps the insertion
    // point exactly where the browser left it, so typing can continue.
    setTimeout(() => {
      if (noteLinkifyUrls(noteTextarea, true)) scheduleNoteAutosave();
    }, 0);
  });

  function noteDraggedImageFile(e) {
    const dt = e.dataTransfer;
    if (!dt) return null;
    const fromFiles = dt.files && Array.from(dt.files).find(f => f.type && f.type.startsWith("image/"));
    if (fromFiles) return fromFiles;
    const hasImageItem = dt.items && Array.from(dt.items).some(i => i.type && i.type.startsWith("image/"));
    return hasImageItem ? true : null; // "true" just signals we should preventDefault on dragover
  }

  noteTextarea.addEventListener("dragover", (e) => {
    if (noteDraggedImageFile(e)) {
      e.preventDefault();
      noteTextarea.classList.add("drag-over");
    }
  });
  noteTextarea.addEventListener("dragleave", () => noteTextarea.classList.remove("drag-over"));
  noteTextarea.addEventListener("drop", (e) => {
    const file = noteDraggedImageFile(e);
    if (file && file !== true) {
      e.preventDefault();
      noteTextarea.classList.remove("drag-over");
      noteHandleImageFile(file);
    } else {
      noteTextarea.classList.remove("drag-over");
    }
  });

  // ---- Shrink/grow buttons for inline note photos ----
  // A small "−" and "+" pair that hover over whichever note image the
  // pointer is currently over, so the photo's display size can be shrunk
  // or grown back with one click instead of dragging the resize handle in
  // its corner (see the resize:both rule on .note-textarea img in
  // style.css). Kept as a single floating pair positioned over whichever
  // image is hovered, rather than one pair per image, so nothing extra
  // needs wiring up when new images are pasted or dropped in.
  const noteImageShrinkBtn = document.createElement("button");
  noteImageShrinkBtn.type = "button";
  noteImageShrinkBtn.className = "note-img-shrink-btn hidden";
  noteImageShrinkBtn.title = "Make this photo smaller";
  noteImageShrinkBtn.setAttribute("aria-label", "Make this photo smaller");
  noteImageShrinkBtn.textContent = "−";
  document.body.appendChild(noteImageShrinkBtn);

  const noteImageGrowBtn = document.createElement("button");
  noteImageGrowBtn.type = "button";
  noteImageGrowBtn.className = "note-img-shrink-btn note-img-grow-btn hidden";
  noteImageGrowBtn.title = "Make this photo bigger";
  noteImageGrowBtn.setAttribute("aria-label", "Make this photo bigger");
  noteImageGrowBtn.textContent = "+";
  document.body.appendChild(noteImageGrowBtn);

  let noteImageShrinkTarget = null;
  // Which editor the hovered photo belongs to — the note editor by default,
  // or the Brainstorm scratchpad (see the brainstormTextarea listeners
  // below) — so the same floating −/+ pair can snapshot undo and autosave
  // through the right editor.
  const NOTE_IMG_HOST_NOTE = { pushUndo: () => notePushUndo(), save: () => scheduleNoteAutosave() };
  let noteImageShrinkHost = NOTE_IMG_HOST_NOTE;

  function positionNoteImageShrinkBtn(img) {
    const rect = img.getBoundingClientRect();
    noteImageGrowBtn.style.left = `${rect.right - 26}px`;
    noteImageGrowBtn.style.top = `${rect.top + 4}px`;
    noteImageShrinkBtn.style.left = `${rect.right - 52}px`;
    noteImageShrinkBtn.style.top = `${rect.top + 4}px`;
  }
  function showNoteImageShrinkBtn(img, host) {
    noteImageShrinkTarget = img;
    noteImageShrinkHost = host || NOTE_IMG_HOST_NOTE;
    positionNoteImageShrinkBtn(img);
    noteImageShrinkBtn.classList.remove("hidden");
    noteImageGrowBtn.classList.remove("hidden");
  }
  function hideNoteImageShrinkBtn() {
    noteImageShrinkTarget = null;
    noteImageShrinkBtn.classList.add("hidden");
    noteImageGrowBtn.classList.add("hidden");
  }
  noteTextarea.addEventListener("mouseover", (e) => {
    if (e.target && e.target.tagName === "IMG") showNoteImageShrinkBtn(e.target, NOTE_IMG_HOST_NOTE);
  });
  noteTextarea.addEventListener("mouseout", (e) => {
    if (e.target && e.target.tagName === "IMG" &&
        !noteImageShrinkBtn.contains(e.relatedTarget) && !noteImageGrowBtn.contains(e.relatedTarget)) {
      hideNoteImageShrinkBtn();
    }
  });
  noteTextarea.addEventListener("scroll", () => {
    if (noteImageShrinkTarget) positionNoteImageShrinkBtn(noteImageShrinkTarget);
  });
  window.addEventListener("resize", () => {
    if (noteImageShrinkTarget) positionNoteImageShrinkBtn(noteImageShrinkTarget);
  });
  // Prevent the mousedown from stealing focus/selection out of the note,
  // same pattern as the symbol/color popovers.
  noteImageShrinkBtn.addEventListener("mousedown", (e) => e.preventDefault());
  noteImageGrowBtn.addEventListener("mousedown", (e) => e.preventDefault());
  noteImageShrinkBtn.addEventListener("mouseleave", hideNoteImageShrinkBtn);
  noteImageGrowBtn.addEventListener("mouseleave", hideNoteImageShrinkBtn);
  const NOTE_IMG_MIN_WIDTH = 80;
  const NOTE_IMG_MIN_HEIGHT = 60;
  noteImageShrinkBtn.addEventListener("click", (e) => {
    e.preventDefault();
    const img = noteImageShrinkTarget;
    if (!img) return;
    const NOTE_IMG_SHRINK_FACTOR = 0.2;
    noteImageShrinkHost.pushUndo();
    const w = Math.max(NOTE_IMG_MIN_WIDTH, Math.round(img.offsetWidth * NOTE_IMG_SHRINK_FACTOR));
    const h = Math.max(NOTE_IMG_MIN_HEIGHT, Math.round(img.offsetHeight * NOTE_IMG_SHRINK_FACTOR));
    img.style.width = `${w}px`;
    img.style.height = `${h}px`;
    positionNoteImageShrinkBtn(img);
    noteImageShrinkHost.save();
  });
  // Grows back by the shrink button's inverse (5x), capped at the photo's
  // own natural resolution so it never upscales past its real pixel size.
  noteImageGrowBtn.addEventListener("click", (e) => {
    e.preventDefault();
    const img = noteImageShrinkTarget;
    if (!img) return;
    const NOTE_IMG_GROW_FACTOR = 5;
    noteImageShrinkHost.pushUndo();
    const maxW = img.naturalWidth || Infinity;
    const maxH = img.naturalHeight || Infinity;
    const w = Math.min(maxW, Math.round(img.offsetWidth * NOTE_IMG_GROW_FACTOR));
    const h = Math.min(maxH, Math.round(img.offsetHeight * NOTE_IMG_GROW_FACTOR));
    img.style.width = `${w}px`;
    img.style.height = `${h}px`;
    positionNoteImageShrinkBtn(img);
    noteImageShrinkHost.save();
  });

  // Clicking directly on a recognized URL opens it in a new tab. This is
  // handled explicitly because links inside a contenteditable normally put
  // the caret in the anchor instead of navigating. It also covers real
  // <a> tags pasted from rich text, not only our own auto-created links.
  // Clicking directly on a checklist glyph toggles it, like a real checkbox.
  noteTextarea.addEventListener("click", (e) => {
    const link = e.target && e.target.closest ? e.target.closest("a[href]") : null;
    if (link && noteTextarea.contains(link)) {
      const href = noteSafeAnchorHref(link.getAttribute("href"));
      if (href) {
        e.preventDefault();
        e.stopPropagation();
        const opened = window.open(href, "_blank", "noopener,noreferrer");
        if (opened) opened.opener = null;
      }
      return;
    }
    if (e.target && e.target.tagName === "IMG") {
      openNotePhotoViewer(e.target);
      return;
    }
    const lineDiv = noteCurrentLine();
    const text = (lineDiv || noteTextarea).textContent;
    if (!/^[☐☑]\s/.test(text)) return;
    const sel = window.getSelection();
    if (!sel.rangeCount) return;
    // A click-drag that selects text (rather than a plain click) still
    // lands here as a "click" once the mouse is released — without this,
    // starting a text selection right at/near the glyph toggled the
    // checkbox as a side effect instead of just selecting the line.
    if (!sel.isCollapsed) return;
    const range = sel.getRangeAt(0);
    const preRange = range.cloneRange();
    preRange.selectNodeContents(lineDiv || noteTextarea);
    preRange.setEnd(range.startContainer, range.startOffset);
    if (preRange.toString().length > 1) return; // only toggle when clicking right on the glyph
    notePushUndo();
    const el = lineDiv || noteTextarea;
    el.textContent = text.replace(/^[☐☑]/, m => (m === "☐" ? "☑" : "☐"));
    noteSyncLineChecked(el);
    scheduleNoteAutosave();
  });

  noteUndoBtn.addEventListener("mousedown", (e) => e.preventDefault());
  noteUndoBtn.addEventListener("click", () => noteUndo());
  noteRedoBtn.addEventListener("mousedown", (e) => e.preventDefault());
  noteRedoBtn.addEventListener("click", () => noteRedo());

  $("#note-tool-ol").addEventListener("mousedown", (e) => {
    e.preventDefault();
    noteToggleOrderedList();
  });
  // "🗂 Add card": starts a new colored section card — a heading line
  // (marked data-card, with its own color) that the lines typed under it
  // belong to, until the next card. Goes on the caret's blank line if it's
  // on one; otherwise after the current card (if the caret is inside one)
  // or after the current line; with no caret in the note, at the end.
  function noteAddCard() {
    notePushUndo();
    const count = noteTextarea.querySelectorAll(":scope > .drc-card-head, :scope > [data-card]").length;
    const color = DRC_CARD_COLORS[count % DRC_CARD_COLORS.length];
    const sel = window.getSelection();
    let line = (sel.rangeCount && noteTextarea.contains(sel.anchorNode)) ? noteCurrentLine() : null;
    if (line && line.nodeType !== 1) line = null; // bare first-line text node: add at the end instead
    const isBlank = (el) => !(el.textContent || "").replace(/[\u200b\u00a0]/g, "").trim() && !el.querySelector("img");
    let card;
    if (line && !line.hasAttribute("data-card") && isBlank(line)) {
      card = line; // the empty line the caret is on becomes the heading
    } else {
      if (line && line.classList.contains("drc-card-line")) {
        // Inside a card: the new one goes right after that card's last line.
        while (!line.classList.contains("drc-card-last") && line.nextElementSibling) line = line.nextElementSibling;
      }
      card = document.createElement("div");
      card.appendChild(document.createElement("br"));
      if (line) line.parentNode.insertBefore(card, line.nextSibling);
      else noteTextarea.appendChild(card);
    }
    card.setAttribute("data-card", "1");
    card.setAttribute("data-card-color", color);
    noteTextarea.focus();
    const range = document.createRange();
    range.selectNodeContents(card);
    range.collapse(true);
    sel.removeAllRanges();
    sel.addRange(range);
    refreshDRCCards();
    scheduleNoteAutosave();
    scrollCaretIntoView(card);
  }
  $("#note-tool-card").addEventListener("mousedown", (e) => {
    e.preventDefault();
    noteAddCard();
  });

  // ---- "😊 Mood To Day" block ----
  // A reusable, non-editable block dropped into the note from the toolbar:
  // a heading plus a row of five faces. Tapping a face marks it (tap it
  // again to clear). The block is plain markup (class + data attributes,
  // no state kept in JS), so it saves with the note, survives undo/redo
  // and reload, and copies/pastes between notes like any other content —
  // the click handler below is delegated on the editor, so a pasted or
  // reloaded block works without any re-wiring.
  const NOTE_MOOD_FACES = [["😀", "Great"], ["🙂", "Good"], ["😐", "Okay"], ["🙁", "Low"], ["😞", "Bad"]];
  function noteBuildMoodBlock() {
    const block = document.createElement("div");
    block.className = "note-mood";
    block.setAttribute("data-mood-block", "1");
    block.setAttribute("contenteditable", "false");
    const title = document.createElement("div");
    title.className = "note-mood-title";
    title.textContent = "Mood To Day";
    const row = document.createElement("div");
    row.className = "note-mood-faces";
    NOTE_MOOD_FACES.forEach(([ch, label], i) => {
      const face = document.createElement("span");
      face.className = "note-mood-face";
      face.dataset.moodValue = String(i + 1);
      face.title = label;
      face.setAttribute("role", "button");
      face.setAttribute("aria-pressed", "false");
      face.textContent = ch;
      row.appendChild(face);
    });
    block.append(title, row);
    return block;
  }
  // The old note-editor "Mood To Day" widget has been retired. Existing
  // saved mood blocks are migrated to the single face that was selected,
  // preserving the user's information without leaving the old interactive
  // widget behind. An unselected old block carries no choice, so it is removed.
  function noteMigrateLegacyMoodBlocks() {
    let changed = false;
    noteTextarea.querySelectorAll(".note-mood").forEach((block) => {
      let emoji = "";
      const selected = block.querySelector(".note-mood-face.selected");
      if (selected) {
        emoji = selected.textContent || "";
      } else {
        const moodValue = Number(block.getAttribute("data-mood"));
        if (moodValue >= 1 && moodValue <= NOTE_MOOD_FACES.length) {
          emoji = NOTE_MOOD_FACES[moodValue - 1][0];
        }
      }
      if (emoji) {
        const line = document.createElement("div");
        line.textContent = emoji;
        block.replaceWith(line);
      } else {
        block.remove();
      }
      changed = true;
    });
    return changed;
  }

  // ---- Add emoji -------------------------------------------------------
  // The note toolbar's 😊 button now opens a simple five-face picker.
  // Choosing one inserts that emoji as ordinary editable note text at the
  // current caret/selection; there is no mood heading, block, selection
  // state, or special saved markup.
  const noteEmojiTriggerBtn = $("#note-tool-emoji");
  const noteEmojiPopover = $("#note-emoji-popover");

  function positionNoteEmojiPopover() {
    const margin = 8;
    const btnRect = noteEmojiTriggerBtn.getBoundingClientRect();
    const popRect = noteEmojiPopover.getBoundingClientRect();
    let left = btnRect.left + btnRect.width / 2 - popRect.width / 2;
    left = Math.max(margin, Math.min(left, window.innerWidth - popRect.width - margin));
    let top = btnRect.bottom + 6;
    if (top + popRect.height > window.innerHeight - margin) {
      top = btnRect.top - popRect.height - 6;
    }
    noteEmojiPopover.style.left = `${left}px`;
    noteEmojiPopover.style.top = `${top}px`;
  }
  function openNoteEmojiPopover() {
    noteEmojiPopover.classList.remove("hidden");
    positionNoteEmojiPopover();
  }
  function closeNoteEmojiPopover() {
    noteEmojiPopover.classList.add("hidden");
  }

  noteEmojiTriggerBtn.addEventListener("pointerdown", (e) => {
    e.preventDefault(); // preserve the note caret/selection
    e.stopPropagation();
    // Only one floating note-toolbar picker should be open at a time.
    const colorPopover = $("#note-color-popover");
    if (colorPopover && !colorPopover.classList.contains("hidden")) colorPopover.classList.add("hidden");
    if (noteEmojiPopover.classList.contains("hidden")) openNoteEmojiPopover();
    else closeNoteEmojiPopover();
  });
  noteEmojiPopover.addEventListener("pointerdown", (e) => e.stopPropagation());
  noteEmojiPopover.querySelectorAll(".note-emoji-swatch").forEach((btn) => {
    btn.addEventListener("pointerdown", (e) => {
      e.preventDefault();
      e.stopPropagation();
      noteInsertSymbol(btn.dataset.emoji || btn.textContent);
      closeNoteEmojiPopover();
    });
  });
  document.addEventListener("pointerdown", (e) => {
    if (!noteEmojiPopover.classList.contains("hidden") &&
        !noteEmojiPopover.contains(e.target) && e.target !== noteEmojiTriggerBtn) {
      closeNoteEmojiPopover();
    }
  });
  window.addEventListener("resize", () => {
    if (!noteEmojiPopover.classList.contains("hidden")) positionNoteEmojiPopover();
  });

  $("#note-tool-check").addEventListener("mousedown", (e) => {
    e.preventDefault();
    noteToggleLinePrefix(/^[☐☑]\s+/, () => "☐ ");
  });
  $("#note-tool-strike").addEventListener("mousedown", (e) => {
    e.preventDefault();
    noteApplyStrikethrough();
  });
  $("#note-tool-bold").addEventListener("mousedown", (e) => {
    e.preventDefault();
    noteApplyBold();
  });
  $("#note-tool-upper").addEventListener("mousedown", (e) => {
    e.preventDefault();
    noteApplyUppercase();
  });
  document.querySelectorAll(".note-color-swatch").forEach(btn => {
    btn.addEventListener("mousedown", (e) => {
      e.preventDefault(); // keep focus (and the note's text selection) off this button
      noteApplyForeColor(btn.dataset.color);
      setNoteColorTrigger(btn.dataset.color);
    });
    // Close the popover on "click" rather than inside the mousedown handler
    // above. Hiding it mid-mousedown used to remove it from the hit tree
    // before mouseup/click fired, so the browser re-targeted that click
    // onto whatever sat underneath — the note-modal backdrop, since the
    // popover intentionally renders outside the card (see the
    // .note-color-popover CSS comment) so it isn't clipped — which closed
    // the whole note editor. Waiting for "click" lets the swatch stay put
    // through the full mousedown→mouseup→click sequence, so the click
    // always resolves on the swatch itself and never leaks to the modal.
    btn.addEventListener("click", () => { closeNoteColorPopover(); });
  });
  $("#note-color-custom").addEventListener("input", (e) => {
    noteApplyForeColor(e.target.value);
    setNoteColorTrigger(e.target.value);
  });
  $("#note-color-custom").addEventListener("mousedown", (e) => e.stopPropagation());

  // Single trigger button that opens/closes the color popover, instead of
  // 6 separate swatch buttons always taking up space in the toolbar.
  const noteAutoColorBtn = $("#note-tool-autocolor");
  noteAutoColorBtn.addEventListener("mousedown", (e) => {
    e.preventDefault(); // keep focus off this button, same as the other toolbar buttons
    setNoteAutoColorEnabled(!noteAutoColorEnabled);
    // DRC cards' own section coloring now follows this same toggle (see
    // drcTemplateCards) — refresh immediately so an open DRC note updates
    // right away instead of waiting for the next edit/reopen.
    refreshDRCCards();
    if (!noteAutoColorEnabled) {
      // Once lines stop getting auto-colored, plain default-color typing
      // would be hard to tell apart from a still-active line — default
      // to gray instead, same as picking it from the color popover, so
      // new typing is visibly "auto-color is off" rather than looking
      // like nothing happened.
      noteTextarea.focus();
      document.execCommand("foreColor", false, "#7c7c76");
      setNoteColorTrigger("#7c7c76");
    } else {
      // Turned back on: numbered lines (and paragraphs) only ever get
      // colored while this is on, so bring the whole note up to date now
      // instead of leaving them plain until the note is reopened.
      notePushUndo();
      noteSyncAllOrderedColors();
      noteAutoColorParagraphs();
      scheduleNoteAutosave();
    }
  });
  const noteColorTriggerBtn = $("#note-tool-color");
  const noteColorPopover = $("#note-color-popover");
  noteColorTriggerBtn.addEventListener("mousedown", (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (!noteEmojiPopover.classList.contains("hidden")) closeNoteEmojiPopover();
    if (noteColorPopover.classList.contains("hidden")) {
      openNoteColorPopover();
    } else {
      closeNoteColorPopover();
    }
  });
  noteColorPopover.addEventListener("mousedown", (e) => e.stopPropagation());
  document.addEventListener("mousedown", (e) => {
    if (!noteColorPopover.classList.contains("hidden") &&
        !noteColorPopover.contains(e.target) && e.target !== noteColorTriggerBtn) {
      closeNoteColorPopover();
    }
  });
  window.addEventListener("resize", () => {
    if (!noteColorPopover.classList.contains("hidden")) positionNoteColorPopover();
  });
  function openNoteColorPopover(){
    noteColorPopover.classList.remove("hidden");
    positionNoteColorPopover();
  }
  function closeNoteColorPopover(){ noteColorPopover.classList.add("hidden"); }
  // Places the popover using fixed viewport coordinates (rather than CSS
  // relative-to-button positioning) and clamps it so it always stays fully
  // on-screen, whichever edge of the note modal the trigger button is near.
  function positionNoteColorPopover(){
    const margin = 8;
    const btnRect = noteColorTriggerBtn.getBoundingClientRect();
    const popRect = noteColorPopover.getBoundingClientRect();
    let left = btnRect.left + btnRect.width / 2 - popRect.width / 2;
    left = Math.max(margin, Math.min(left, window.innerWidth - popRect.width - margin));
    let top = btnRect.bottom + 6;
    if (top + popRect.height > window.innerHeight - margin) {
      top = btnRect.top - popRect.height - 6; // not enough room below: flip above
    }
    noteColorPopover.style.left = `${left}px`;
    noteColorPopover.style.top = `${top}px`;
  }
  function setNoteColorTrigger(color){ $("#note-color-trigger-swatch").style.background = color; }

  // ---- Symbol button — used to open a popover of choices, but now only
  // one symbol (➡️) remains, so clicking the button inserts it directly
  // instead of opening a list with a single option. ----
  const noteSymbolTriggerBtn = $("#note-tool-symbol");
  noteSymbolTriggerBtn.addEventListener("mousedown", (e) => {
    e.preventDefault(); // keep focus (and the note's caret position) off this button
    e.stopPropagation();
    noteInsertSymbol("➡️");
  });
  // Close on a genuine backdrop click only — not a text selection that was
  // started inside the note card but dragged past its edge before mouseup.
  // In that case mousedown's target is inside the card while mouseup's
  // target is the backdrop, and the browser still fires "click" targeted
  // at their common ancestor (the backdrop itself), which used to close
  // the note out from under an in-progress selection. Requiring the
  // mousedown to ALSO have started on the backdrop rules that out.
  let noteBackdropMousedown = false;
  noteModal.addEventListener("mousedown", (e) => { noteBackdropMousedown = (e.target === noteModal); });
  noteModal.addEventListener("click", (e) => {
    if (!noteIsResizing && e.target === noteModal && noteBackdropMousedown) closeNoteModal();
  });
  noteTitleInput.addEventListener("input", () => {
    scheduleNoteAutosave();
    refreshDRCCardsSoon();
  });
  noteTitleInput.addEventListener("keydown", (e) => {
    e.stopPropagation(); // don't let Enter/Delete/arrows trigger the canvas shortcuts while typing a title
    if (e.key === "Escape") { e.preventDefault(); closeNoteModal(); return; }
    // Enter jumps down into the note body instead of doing nothing (it's
    // a single-line input, so there's no newline to insert here anyway).
    if (e.key === "Enter") { e.preventDefault(); noteTextarea.focus(); return; }
    if (e.altKey && e.key === "ArrowLeft" && noteActiveIndex > 0) { e.preventDefault(); goToNote(-1); }
    if (e.altKey && e.key === "ArrowRight" && noteActiveIndex < noteWorkingList.length - 1) { e.preventDefault(); goToNote(1); }
  });
  // Groups plain typing into undo-sized bursts: a snapshot is only taken
  // when there's been a pause since the last one, so undo doesn't have to
  // be pressed once per character. Toolbar-driven mutations push their
  // own snapshot explicitly (see notePushUndo call sites above) and don't
  // rely on this.
  const NOTE_TYPING_BURST_MS = 600;
  noteTextarea.addEventListener("beforeinput", () => {
    const now = Date.now();
    if (now - noteLastPushAt > NOTE_TYPING_BURST_MS || !noteUndoStack.length) {
      pushBoundedSnapshot(noteUndoStack, noteTextarea.innerHTML, NOTE_UNDO_LIMIT);
    }
    noteRedoStack = [];
    noteLastPushAt = now;
    updateNoteUndoButtons();
  });
  // While "type in caps" mode is armed (AA button pressed), transform each
  // character as it's typed rather than inserting it as-is. Guarded by
  // noteUppercaseInserting so the re-inserted (already-uppercase) text
  // doesn't loop back through this same handler.
  noteTextarea.addEventListener("beforeinput", (e) => {
    if (!noteUppercasePending || noteUppercaseInserting) return;
    if (e.inputType === "insertText" && e.data) {
      e.preventDefault();
      noteUppercaseInserting = true;
      document.execCommand("insertText", false, e.data.toUpperCase());
      noteUppercaseInserting = false;
    }
  });
  // Clicking to reposition the caret (rather than typing) drops caps
  // mode, mirroring how Word's Bold button un-presses once you click
  // somewhere that isn't bold — this "AA" is otherwise a plain toggle,
  // so it has no such position to check and just resets on click.
  noteTextarea.addEventListener("mousedown", () => {
    if (noteUppercasePending) {
      noteUppercasePending = false;
      updateNoteToolActiveStates();
    }
  });
  document.addEventListener("selectionchange", () => {
    if (!noteModal.classList.contains("hidden") && document.activeElement === noteTextarea) {
      updateNoteToolActiveStates();
    }
  });
  noteTextarea.addEventListener("input", (e) => {
    // Keep an already-created auto-link's href in sync if its visible text
    // is edited. When typing/pasting produces a separator, also recognize
    // any newly completed URL without disturbing the caret.
    refreshAutoNoteLinks(noteTextarea);
    clearTimeout(noteLinkifyTimer);
    noteLinkifyTimer = setTimeout(() => {
      noteLinkifyTimer = null;
      if (noteLinkifyUrls(noteTextarea, true)) scheduleNoteAutosave();
    }, 250);
    // Chrome's own Enter handling copies a line's attributes onto the line
    // it splits off — so pressing Enter in a card heading would otherwise
    // make the new line a second heading. Only the original stays one.
    if (e && e.inputType === "insertParagraph") {
      const ln = noteCurrentLine();
      const prev = ln && ln.previousElementSibling;
      if (ln && ln.nodeType === 1 && ln.hasAttribute("data-card") && prev && prev.hasAttribute("data-card")
          && (prev.textContent || "").trim()) {
        ln.removeAttribute("data-card");
        ln.removeAttribute("data-card-color");
      }
    }
    noteAutoColorParagraphs(); scheduleNoteAutosave(); refreshDRCCardsSoon();
  });
  // DRC notes show a color ring at the right edge of each section card;
  // clicking it recolors that card. The color is stored on the heading
  // line itself (data-card-color, honored by decorateDRCCards), so it is
  // part of the note — and of the "DRC" note template when the note is
  // saved as one.
  bindDRCCardColorDot(
    noteTextarea,
    () => !noteModal.classList.contains("note-locked") && noteTextarea.classList.contains("drc-cards"),
    (head, color) => {
      notePushUndo();
      head.setAttribute("data-card-color", color);
      refreshDRCCards();
      scheduleNoteAutosave();
    }
  );
  noteTextarea.addEventListener("keydown", (e) => {
    e.stopPropagation(); // don't let Tab/Enter/Delete trigger the canvas shortcuts while typing a note
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") {
      e.preventDefault();
      if (e.shiftKey) noteRedo(); else noteUndo();
      return;
    }
    // Ctrl/Cmd+B mirrors the toolbar Bold button — intercepted (rather
    // than left to the browser's own native Ctrl+B handling) so it goes
    // through noteApplyBold and picks up undo tracking and the toolbar's
    // pressed-state highlight the same way a click on the button would.
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "b") {
      e.preventDefault();
      noteApplyBold();
      return;
    }
    // Caps Lock mirrors the toolbar "AA" (force-uppercase) toggle — each
    // physical press fires its own keydown, so this just flips the same
    // toggle the button does rather than tracking the key as held down.
    if (e.key === "CapsLock") {
      noteApplyUppercase();
      return;
    }
    if (e.key === "Escape") { e.preventDefault(); closeNoteModal(); return; }
    if (e.key === "Enter" && !e.shiftKey) {
      if (noteHandleEnter()) {
        e.preventDefault();
        // noteHandleEnter builds the new line itself (no `input` event
        // fires), so on a DRC note give that line its card immediately —
        // otherwise the caret sits outside the card until you type.
        refreshDRCCards();
      }
    }
    // Alt+Left/Right switch between a node's notes without leaving the
    // keyboard — plain arrow keys stay reserved for moving the caret.
    if (e.altKey && e.key === "ArrowLeft" && noteActiveIndex > 0) { e.preventDefault(); goToNote(-1); }
    if (e.altKey && e.key === "ArrowRight" && noteActiveIndex < noteWorkingList.length - 1) { e.preventDefault(); goToNote(1); }
  });

  noteNavAdd.addEventListener("mousedown", (e) => e.preventDefault());
  noteNavAdd.addEventListener("click", addAnotherNote);
  noteNavFavorite.addEventListener("mousedown", (e) => e.preventDefault());
  noteNavFavorite.addEventListener("click", toggleNoteFavorite);
  if (noteNavFolder) {
    noteNavFolder.addEventListener("mousedown", (e) => e.preventDefault());
    noteNavFolder.addEventListener("click", (e) => {
      e.stopPropagation();
      const current = noteWorkingList[noteActiveIndex];
      if (!current) return;
      openFolderMovePopover(noteNavFolder, notesFolderMgr, current.id, updateNoteFolderUI);
    });
  }
  // ---- Note templates popover ("📋" in the note editor's nav row) ----
  // Top row saves the open note as a template; below it, every saved
  // template — click one to pull it into the open note (fills an empty
  // note, otherwise adds it at the end), 🔁 to overwrite it with the open
  // note, × to delete. Same fixed-position popover pattern as the task
  // list's "📋 Templates" one (see renderTaskTemplatesPopover).
  const noteNavTemplates = $("#note-nav-templates");
  const noteTemplatesPopover = document.createElement("div");
  noteTemplatesPopover.className = "task-templates-popover note-templates-popover hidden";
  document.body.appendChild(noteTemplatesPopover);

  // Adds a template's content to the note that's open right now. An empty
  // note is simply filled in (title too, if it has none); a note that
  // already has text gets the template added after it, separated by a
  // blank line. Goes through the editor's own undo stack, so ↶ takes it
  // straight back out.
  function insertNoteTemplate(tpl) {
    if (!tpl || !noteWorkingList[noteActiveIndex]) return;
    const html = noteHtmlFromRaw(tpl.html || "");
    if (!html && !tpl.title) return;
    notePushUndo();
    const bodyEmpty = !noteTextarea.textContent.trim() && !noteTextarea.querySelector("img");
    if (!noteTitleInput.value.trim() && tpl.title) noteTitleInput.value = tpl.title;
    if (html) {
      if (bodyEmpty) noteTextarea.innerHTML = html;
      else noteTextarea.insertAdjacentHTML("beforeend", "<div><br></div>" + html);
    }
    noteSyncAllCheckedLines();
    noteSyncAllOrderedColors();
    noteAutoColorParagraphs();
    refreshDRCCards();
    scheduleNoteAutosave();
    noteTextarea.focus();
    const range = document.createRange();
    range.selectNodeContents(noteTextarea);
    range.collapse(false);
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
    noteTextarea.scrollTop = noteTextarea.scrollHeight;
  }

  function renderNoteTemplatesPopover() {
    noteTemplatesPopover.innerHTML = "";
    const current = noteWorkingList[noteActiveIndex];
    if (current) captureActiveNote(); // pick up whatever's typed so far
    const canSave = !!(current && snapshotNoteForTemplate(current));

    const saveBtn = document.createElement("button");
    saveBtn.type = "button";
    saveBtn.className = "task-template-save-btn";
    saveBtn.textContent = "💾 Save this note as a template…";
    saveBtn.disabled = !canSave;
    saveBtn.title = canSave
      ? "Save this note's title and text as a reusable template (photos aren't included)"
      : "This note is empty — write something first";
    saveBtn.addEventListener("click", () => {
      const cur = noteWorkingList[noteActiveIndex];
      if (!cur) return;
      captureActiveNote();
      const name = window.prompt("Name this note template:", (cur.title || "").trim());
      if (name === null) return; // cancelled
      const clean = name.trim();
      const existing = clean && getNoteTemplates().find(t => (t.name || "").trim().toLowerCase() === clean.toLowerCase());
      if (existing) {
        if (!confirm(`A template named "${existing.name}" already exists. Replace it with this note?`)) return;
        updateNoteTemplate(existing.id, cur);
        showToast(`Replaced template "${existing.name}"`);
      } else {
        saveNoteAsTemplate(cur, name);
        showToast("Saved note as a template");
      }
      renderNoteTemplatesPopover();
    });
    noteTemplatesPopover.appendChild(saveBtn);

    // "DRC" and "Plan" are special template names — say so, since it's the
    // only way to know a template of that name is picked up automatically.
    const addHint = () => {
      const hint = document.createElement("div");
      hint.className = "task-templates-empty task-templates-hint";
      hint.textContent = "Tip: a template named “DRC” starts every new DRC note; one named “Plan” starts the note of a task or subtask called plan.";
      noteTemplatesPopover.appendChild(hint);
    };
    const templates = getNoteTemplates();
    if (!templates.length) {
      const empty = document.createElement("div");
      empty.className = "task-templates-empty";
      empty.textContent = "No saved note templates yet.";
      noteTemplatesPopover.appendChild(empty);
      addHint();
      return;
    }
    const divider = document.createElement("div");
    divider.className = "task-templates-divider";
    noteTemplatesPopover.appendChild(divider);
    templates.forEach((tpl) => {
      const row = document.createElement("div");
      row.className = "task-template-row";
      const label = document.createElement("span");
      label.className = "task-template-row-label";
      label.textContent = tpl.name || "Untitled template";
      label.title = "Add this template to the open note";
      label.addEventListener("click", () => {
        insertNoteTemplate(tpl);
        closeNoteTemplatesPopover();
      });
      const replace = document.createElement("button");
      replace.type = "button";
      replace.className = "task-template-row-replace";
      replace.textContent = "🔁";
      replace.disabled = !canSave;
      replace.title = canSave
        ? `Replace "${tpl.name}" with the open note`
        : "This note is empty — write something first";
      replace.addEventListener("click", (e) => {
        e.stopPropagation();
        const cur = noteWorkingList[noteActiveIndex];
        if (!cur || !canSave) return;
        if (!confirm(`Replace template "${tpl.name}" with the open note?`)) return;
        captureActiveNote();
        updateNoteTemplate(tpl.id, cur);
        renderNoteTemplatesPopover();
        showToast(`Replaced template "${tpl.name}"`);
      });
      const del = document.createElement("button");
      del.type = "button";
      del.className = "task-template-row-del";
      del.title = "Delete this template";
      del.textContent = "×";
      del.addEventListener("click", (e) => {
        e.stopPropagation();
        if (!confirm(`Delete the template "${tpl.name}"?`)) return;
        deleteNoteTemplate(tpl.id);
        renderNoteTemplatesPopover();
      });
      row.appendChild(label);
      row.appendChild(replace);
      row.appendChild(del);
      noteTemplatesPopover.appendChild(row);
    });
    addHint();
  }
  function positionNoteTemplatesPopover(btn) {
    const margin = 8;
    const btnRect = btn.getBoundingClientRect();
    const popRect = noteTemplatesPopover.getBoundingClientRect();
    let left = btnRect.left + btnRect.width / 2 - popRect.width / 2;
    left = Math.max(margin, Math.min(left, window.innerWidth - popRect.width - margin));
    let top = btnRect.bottom + 6;
    if (top + popRect.height > window.innerHeight - margin) {
      top = Math.max(margin, btnRect.top - popRect.height - 6);
    }
    noteTemplatesPopover.style.left = `${left}px`;
    noteTemplatesPopover.style.top = `${top}px`;
  }
  function openNoteTemplatesPopover(btn) {
    renderNoteTemplatesPopover();
    noteTemplatesPopover.classList.remove("hidden");
    positionNoteTemplatesPopover(btn);
    // Pull whatever the other device saved, then redraw if it added any.
    syncTaskTemplatesWithDrive().then((changed) => {
      if (changed && !noteTemplatesPopover.classList.contains("hidden")) {
        renderNoteTemplatesPopover();
        positionNoteTemplatesPopover(btn);
      }
    });
  }
  function closeNoteTemplatesPopover() {
    noteTemplatesPopover.classList.add("hidden");
  }
  if (noteNavTemplates) {
    // Keep the editor's selection/caret where it is while clicking this.
    noteNavTemplates.addEventListener("mousedown", (e) => e.preventDefault());
    noteNavTemplates.addEventListener("click", (e) => {
      e.stopPropagation();
      if (noteTemplatesPopover.classList.contains("hidden")) openNoteTemplatesPopover(noteNavTemplates);
      else closeNoteTemplatesPopover();
    });
  }
  noteTemplatesPopover.addEventListener("mousedown", (e) => e.stopPropagation());
  document.addEventListener("mousedown", (e) => {
    if (!noteTemplatesPopover.classList.contains("hidden") &&
        !noteTemplatesPopover.contains(e.target) &&
        e.target !== noteNavTemplates) {
      closeNoteTemplatesPopover();
    }
  });

  noteNavDelete.addEventListener("mousedown", (e) => e.preventDefault());
  noteNavDelete.addEventListener("click", deleteActiveNote);
  $("#note-nav-close").addEventListener("click", closeNoteModal);
  noteNavBack.addEventListener("mousedown", (e) => e.preventDefault());
  noteNavBack.addEventListener("click", () => {
    const ret = noteReturn;
    closeNoteModal();
    runViewerReturn(ret);
  });

  bgInput.addEventListener("input", () => updateTheme({ background: bgInput.value }));
  $("#theme-bg-reset").addEventListener("click", () => { bgInput.value = defaultBg(); updateTheme({ background: null }); });

  connectorModeSel.addEventListener("change", () => {
    connectorColorInput.disabled = connectorModeSel.value !== "custom";
    updateTheme({ connectorMode: connectorModeSel.value });
  });
  connectorColorInput.addEventListener("input", () => updateTheme({ connectorColor: connectorColorInput.value }));

  fontModeSel.addEventListener("change", () => {
    updateTheme({ fontMode: fontModeSel.value });
  });
  fontColorInput.addEventListener("input", () => updateTheme({ fontColor: fontColorInput.value }));

  /* ---------------- tasks editor ---------------- */

  const tasksModal = $("#tasks-modal");
  const tasksModalTitle = $("#tasks-modal-title");
  const tasksCard = $(".tasks-modal-card");
  const tasksResizeHandle = $("#tasks-resize-handle");
  const tasksListEl = $("#tasks-list");
  const tasksNewInput = $("#tasks-new-input");
  const tasksAddSubmitBtn = $("#tasks-add-submit");
  const tasksProgressBar = $("#tasks-progress-bar");
  const tasksProgressLabel = $("#tasks-progress-label");
  const tasksSortStarsBtn = $("#tasks-sort-stars");
  const tasksFontColorToggleBtn = $("#tasks-font-color-toggle");
  const tasksTemplatesBtn = $("#tasks-templates-btn");
  const tasksRandomBtn = $("#tasks-random-btn");
  const tasksFocusTimerEl = $("#tasks-focus-timer");
  let tasksEditingTarget = null; // {nodeId, r, c} — r/c null when the modal is open for a whole node instead of one table cell
  // Guards the same race as noteIsResizing above: dragging the resize
  // handle and releasing the mouse past the card's edge fires a "click"
  // on the modal backdrop right after mouseup, which would otherwise
  // close the tasks modal mid-drag.
  let tasksIsResizing = false;
  // Custom two-axis resize grip, same approach as setupNoteResize, but
  // the chosen size is also remembered across reloads (localStorage),
  // which the note editor's resize doesn't do.
  const TASKS_CARD_SIZE_KEY = "branchline_tasks_card_size";
  (function setupTasksResize() {
    try {
      const saved = JSON.parse(localStorage.getItem(TASKS_CARD_SIZE_KEY) || "null");
      if (saved && saved.w && saved.h) {
        tasksCard.style.width = saved.w + "px";
        tasksCard.style.height = saved.h + "px";
      }
    } catch (e) {}

    let startX, startY, startW, startH;

    function onMove(e) {
      const dw = e.clientX - startX;
      const dh = e.clientY - startY;
      const maxW = window.innerWidth * 0.94;
      const maxH = window.innerHeight * 0.9;
      tasksCard.style.width = clamp(startW + dw, 480, maxW) + "px";
      tasksCard.style.height = clamp(startH + dh, 320, maxH) + "px";
    }
    function onUp() {
      document.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseup", onUp);
      document.removeEventListener("pointermove", onMove);
      document.removeEventListener("pointerup", onUp);
      document.body.style.userSelect = "";
      const rect = tasksCard.getBoundingClientRect();
      try {
        localStorage.setItem(TASKS_CARD_SIZE_KEY, JSON.stringify({ w: Math.round(rect.width), h: Math.round(rect.height) }));
      } catch (e) {}
      setTimeout(() => { tasksIsResizing = false; }, 0);
    }
    function onResizeStart(e) {
      e.preventDefault();
      e.stopPropagation();
      tasksIsResizing = true;
      startX = e.clientX;
      startY = e.clientY;
      const rect = tasksCard.getBoundingClientRect();
      startW = rect.width;
      startH = rect.height;
      document.body.style.userSelect = "none";
      document.addEventListener("mousemove", onMove);
      document.addEventListener("mouseup", onUp);
      document.addEventListener("pointermove", onMove);
      document.addEventListener("pointerup", onUp);
    }
    tasksResizeHandle.addEventListener("mousedown", onResizeStart);
    tasksResizeHandle.addEventListener("pointerdown", (e) => {
      if (e.pointerType === "mouse") return;
      onResizeStart(e);
    });
  })();
  // Which tasks have their subtask checklist explicitly collapsed in the
  // tasks modal — subtasks are expanded by default, so this only tracks
  // the ones someone has double-clicked closed. Keyed by task id, kept
  // for the life of the page (not persisted) so it survives re-renders
  // but resets on reload.
  const collapsedSubtaskIds = new Set();
  // On a phone, a task keeps its common actions tucked behind one large
  // "…" button so the title gets most of the screen width. Remember the
  // open drawer across re-renders caused by checkbox/date/star changes.
  let mobileTaskActionsOpenId = null;
  // The subtask most recently chosen by the "🎲 Random" button — drawn
  // highlighted in the tasks modal until it's done, another one is
  // picked, or the modal closes. Just an id; nothing is saved.
  let randomPickedSubtaskId = null;
  // Every unfinished subtask across the WHOLE task list (all tasks),
  // each paired with the task it belongs to.
  function unfinishedSubtasksOfHost(host) {
    return getNodeTasks(host).flatMap((t) =>
      getTaskSubtasks(t).filter((s) => !s.done && !s.failed).map((s) => ({ t, s }))
    );
  }

  // Shared color-dot popover for a task's optional color label (see
  // getTaskColor/setTaskColor) — one instance reused by every task row,
  // in both the Tasks modal and the Calendar day modal's task list,
  // since both render the same underlying task objects. Same
  // fixed-viewport-coordinates + clamp positioning as the photo modal's
  // symbol popover (see positionPhotoSymbolPopover).
  let taskColorPopoverCtx = null; // { t, rerender } — set by openTaskColorPopover
  const taskColorPopover = document.createElement("div");
  taskColorPopover.className = "task-color-popover hidden";
  const taskColorNoneSwatch = document.createElement("span");
  taskColorNoneSwatch.className = "task-color-swatch task-color-swatch-none";
  taskColorNoneSwatch.title = "No color";
  taskColorNoneSwatch.addEventListener("click", (e) => { e.stopPropagation(); applyTaskColor(null); });
  taskColorPopover.appendChild(taskColorNoneSwatch);
  PALETTE.forEach((c) => {
    const sw = document.createElement("span");
    sw.className = "task-color-swatch";
    sw.style.background = c;
    sw.dataset.color = c;
    sw.addEventListener("click", (e) => { e.stopPropagation(); applyTaskColor(c); });
    taskColorPopover.appendChild(sw);
  });
  document.body.appendChild(taskColorPopover);

  function applyTaskColor(color) {
    if (!taskColorPopoverCtx) return;
    const { t, rerender } = taskColorPopoverCtx;
    pushUndo();
    setTaskColor(t, color);
    persist();
    closeTaskColorPopover();
    rerender();
  }
  function openTaskColorPopover(btn, t, rerender) {
    taskColorPopoverCtx = { t, rerender };
    taskColorPopover.querySelectorAll(".task-color-swatch").forEach((sw) => {
      sw.classList.toggle("active", getTaskColor(t) === (sw.dataset.color || null));
    });
    taskColorPopover.classList.remove("hidden");
    positionTaskColorPopover(btn);
  }
  function closeTaskColorPopover() {
    taskColorPopover.classList.add("hidden");
    taskColorPopoverCtx = null;
  }
  function positionTaskColorPopover(btn) {
    const margin = 8;
    const btnRect = btn.getBoundingClientRect();
    const popRect = taskColorPopover.getBoundingClientRect();
    let left = btnRect.left + btnRect.width / 2 - popRect.width / 2;
    left = Math.max(margin, Math.min(left, window.innerWidth - popRect.width - margin));
    let top = btnRect.bottom + 6;
    if (top + popRect.height > window.innerHeight - margin) {
      top = btnRect.top - popRect.height - 6;
    }
    taskColorPopover.style.left = `${left}px`;
    taskColorPopover.style.top = `${top}px`;
  }
  taskColorPopover.addEventListener("mousedown", (e) => e.stopPropagation());
  document.addEventListener("mousedown", (e) => {
    if (!taskColorPopover.classList.contains("hidden") &&
        !taskColorPopover.contains(e.target) &&
        !e.target.closest(".task-color-dot")) {
      closeTaskColorPopover();
    }
  });

  // Templates popover — opened from the tasks modal's "📋 Templates"
  // button. Its top row saves the *entire* current task list under a
  // name (see saveTaskListAsTemplate above); below that is every
  // previously saved list-template, each insertable onto whichever
  // node's task list is currently open. Same fixed-viewport popover
  // pattern as the task-color one just above.
  const taskTemplatesPopover = document.createElement("div");
  taskTemplatesPopover.className = "task-templates-popover hidden";
  document.body.appendChild(taskTemplatesPopover);

  function renderTaskTemplatesPopover() {
    taskTemplatesPopover.innerHTML = "";
    const target = tasksEditingTarget;
    const host = target && resolveHost(target.nodeId, target.r, target.c);
    const currentTaskCount = host ? getNodeTasks(host).length : 0;

    const saveBtn = document.createElement("button");
    saveBtn.type = "button";
    saveBtn.className = "task-template-save-btn";
    saveBtn.textContent = "💾 Save this list as a template…";
    saveBtn.disabled = !currentTaskCount;
    saveBtn.title = currentTaskCount
      ? `Save all ${currentTaskCount} task(s) here as a reusable template`
      : "This list is empty — add a task first";
    saveBtn.addEventListener("click", () => {
      if (!host) return;
      const name = window.prompt("Name this task-list template:", "");
      if (name === null) return; // cancelled
      const clean = name.trim();
      // Saving under a name that already exists would otherwise leave two
      // near-identical templates behind — offer to replace that one's
      // tasks in place instead of always creating a new entry.
      const existing = clean && getTaskListTemplates().find(t => t.name.trim().toLowerCase() === clean.toLowerCase());
      if (existing) {
        if (!confirm(`A template named "${existing.name}" already exists. Replace it with the current list?`)) return;
        updateTaskListTemplate(existing.id, host);
        showToast(`Replaced template "${existing.name}"`);
      } else {
        saveTaskListAsTemplate(host, name);
        showToast("Saved task list as a template");
      }
      renderTaskTemplatesPopover();
    });
    taskTemplatesPopover.appendChild(saveBtn);

    const templates = getTaskListTemplates();
    if (!templates.length) {
      const empty = document.createElement("div");
      empty.className = "task-templates-empty";
      empty.textContent = "No saved templates yet.";
      taskTemplatesPopover.appendChild(empty);
      return;
    }
    const divider = document.createElement("div");
    divider.className = "task-templates-divider";
    taskTemplatesPopover.appendChild(divider);
    templates.forEach((tpl) => {
      const row = document.createElement("div");
      row.className = "task-template-row";
      const label = document.createElement("span");
      label.className = "task-template-row-label";
      const count = (tpl.tasks || []).length;
      label.textContent = `${tpl.name} (${count} task${count === 1 ? "" : "s"})`;
      label.title = `Add these ${count} task(s) to the current list`;
      label.addEventListener("click", () => {
        const t2 = tasksEditingTarget;
        const h2 = t2 && resolveHost(t2.nodeId, t2.r, t2.c);
        if (!h2) return;
        insertTaskListTemplate(tpl, h2);
        closeTaskTemplatesPopover();
        renderTasksModal();
      });
      // Overwrites this template's saved tasks with whatever's on the
      // currently open list — the explicit way to update a template
      // without retyping its exact name into the save prompt above.
      const replace = document.createElement("button");
      replace.type = "button";
      replace.className = "task-template-row-replace";
      replace.title = currentTaskCount
        ? `Replace "${tpl.name}" with the current list (${currentTaskCount} task${currentTaskCount === 1 ? "" : "s"})`
        : "This list is empty — add a task first";
      replace.textContent = "🔁";
      replace.disabled = !currentTaskCount;
      replace.addEventListener("click", (e) => {
        e.stopPropagation();
        if (!host || !currentTaskCount) return;
        if (!confirm(`Replace template "${tpl.name}" with the current list?`)) return;
        updateTaskListTemplate(tpl.id, host);
        renderTaskTemplatesPopover();
        showToast(`Replaced template "${tpl.name}"`);
      });
      const del = document.createElement("button");
      del.type = "button";
      del.className = "task-template-row-del";
      del.title = "Delete this template";
      del.textContent = "×";
      del.addEventListener("click", (e) => {
        e.stopPropagation();
        if (!confirm(`Delete the template "${tpl.name}"?`)) return;
        deleteTaskListTemplate(tpl.id);
        renderTaskTemplatesPopover();
      });
      row.appendChild(label);
      row.appendChild(replace);
      row.appendChild(del);
      taskTemplatesPopover.appendChild(row);
    });
  }
  function openTaskTemplatesPopover(btn) {
    renderTaskTemplatesPopover();
    taskTemplatesPopover.classList.remove("hidden");
    positionTaskTemplatesPopover(btn);
    // Pull whatever the other device saved, then redraw if it added any.
    syncTaskTemplatesWithDrive().then((changed) => {
      if (changed && !taskTemplatesPopover.classList.contains("hidden")) {
        renderTaskTemplatesPopover();
        positionTaskTemplatesPopover(btn);
      }
    });
  }
  function closeTaskTemplatesPopover() {
    taskTemplatesPopover.classList.add("hidden");
  }
  function positionTaskTemplatesPopover(btn) {
    const margin = 8;
    const btnRect = btn.getBoundingClientRect();
    const popRect = taskTemplatesPopover.getBoundingClientRect();
    let left = btnRect.left + btnRect.width / 2 - popRect.width / 2;
    left = Math.max(margin, Math.min(left, window.innerWidth - popRect.width - margin));
    let top = btnRect.bottom + 6;
    if (top + popRect.height > window.innerHeight - margin) {
      top = btnRect.top - popRect.height - 6;
    }
    taskTemplatesPopover.style.left = `${left}px`;
    taskTemplatesPopover.style.top = `${top}px`;
  }
  if (tasksTemplatesBtn) {
    tasksTemplatesBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      if (taskTemplatesPopover.classList.contains("hidden")) openTaskTemplatesPopover(tasksTemplatesBtn);
      else closeTaskTemplatesPopover();
    });
  }
  taskTemplatesPopover.addEventListener("mousedown", (e) => e.stopPropagation());
  document.addEventListener("mousedown", (e) => {
    if (!taskTemplatesPopover.classList.contains("hidden") &&
        !taskTemplatesPopover.contains(e.target) &&
        e.target !== tasksTemplatesBtn) {
      closeTaskTemplatesPopover();
    }
  });

  // Per-task focus timer — a lightweight, non-persisted countdown so the
  // person can start a quick focus session on one task at a time. It
  // keeps running (via setInterval) even if the tasks modal is closed or
  // switched to a different node, so leaving the modal doesn't cancel it.
  // Starts short — an extra "+1m" button lets you stack on more time
  // instead of committing to a long duration up front.
  const FOCUS_DURATION = 1 * 60; // 1 minute
  const FOCUS_EXTEND = 1 * 60; // added per "+1m" click
  let focusTimer = null; // { target: {nodeId, r, c}, taskId, subtaskId, taskText, remaining, duration, paused, intervalId } — subtaskId is null for a task-level timer
  let focusJustCompleted = null; // { target, taskId, subtaskId } — shown briefly after a session finishes
  let lastFocusTaskText = ""; // kept around so the "Time's up!" tab title can still name the task once focusTimer itself is cleared

  // The browser tab title mirrors the countdown, so the time is visible
  // even when this tab isn't the active one. BASE_TITLE is captured once
  // up front (before anything ever overwrites document.title) so it can
  // always be restored exactly once the timer/alarm is done.
  const BASE_TITLE = document.title;
  const TITLE_TASK_MAX = 40;

  function titleTaskLabel(text) {
    const t = (text || "").trim() || "Focus";
    return t.length > TITLE_TASK_MAX ? t.slice(0, TITLE_TASK_MAX - 1) + "…" : t;
  }

  function updateFocusTitle() {
    if (focusTimer) {
      document.title = `${focusTimer.paused ? "⏸" : "⏱"} ${formatFocusTime(focusTimer.remaining)} · ${titleTaskLabel(focusTimer.taskText)}`;
    } else if (focusChimeIntervalId) {
      document.title = `⏰ Time's up! · ${titleTaskLabel(lastFocusTaskText)}`;
    } else {
      document.title = BASE_TITLE;
    }
  }

  function formatFocusTime(totalSeconds) {
    const m = Math.floor(totalSeconds / 60);
    const s = totalSeconds % 60;
    return `${m}:${String(s).padStart(2, "0")}`;
  }

  // Single focus-timer widget, shown once at the top of the tasks modal
  // (next to its title) rather than duplicated on every task/subtask row.
  // It isn't tied to any particular task — just a general session for
  // whatever the person is working through in this list.
  function renderFocusTimerWidget() {
    if (!tasksFocusTimerEl) return;
    tasksFocusTimerEl.innerHTML = "";

    if (focusTimer) {
      const timeLabel = document.createElement("span");
      timeLabel.className = "task-timer-time" + (focusTimer.paused ? " paused" : "");
      timeLabel.textContent = formatFocusTime(focusTimer.remaining);
      timeLabel.title = focusTimer.paused ? "Focus timer paused" : "Focusing — time remaining";

      const pauseBtn = document.createElement("button");
      pauseBtn.type = "button";
      pauseBtn.className = "task-timer-btn";
      pauseBtn.title = focusTimer.paused ? "Resume" : "Pause";
      pauseBtn.textContent = focusTimer.paused ? "▶" : "⏸";
      pauseBtn.addEventListener("click", (e) => { e.stopPropagation(); toggleFocusPause(); });

      const extendBtn = document.createElement("button");
      extendBtn.type = "button";
      extendBtn.className = "task-timer-btn task-timer-extend";
      extendBtn.title = "Add 1 more minute";
      extendBtn.textContent = "+1m";
      extendBtn.addEventListener("click", (e) => { e.stopPropagation(); extendFocusTimer(FOCUS_EXTEND); });

      const stopBtn = document.createElement("button");
      stopBtn.type = "button";
      stopBtn.className = "task-timer-btn task-timer-stop";
      stopBtn.title = "Stop focus timer";
      stopBtn.textContent = "■";
      stopBtn.addEventListener("click", (e) => { e.stopPropagation(); stopFocusTimer(); });

      tasksFocusTimerEl.appendChild(timeLabel);
      tasksFocusTimerEl.appendChild(pauseBtn);
      tasksFocusTimerEl.appendChild(stopBtn);
      tasksFocusTimerEl.appendChild(extendBtn);
    } else if (focusJustCompleted) {
      const doneLabel = document.createElement("span");
      doneLabel.className = "task-timer-done-label";
      doneLabel.textContent = "✓ Focus done";
      doneLabel.title = "Tap anywhere to stop the chime";
      tasksFocusTimerEl.appendChild(doneLabel);
    } else {
      const startBtn = document.createElement("button");
      startBtn.type = "button";
      startBtn.className = "task-timer-btn task-timer-start";
      startBtn.title = "Start a focus timer (1 min, +1m button to extend)";
      startBtn.textContent = "⏱";
      startBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        startFocusTimer(tasksEditingTarget, null, "Focus session");
      });
      tasksFocusTimerEl.appendChild(startBtn);
    }
  }

  function refreshTasksModalIfOpen(target) {
    if (!tasksModal.classList.contains("hidden") && sameTarget(tasksEditingTarget, target)) {
      renderTasksModal();
    }
  }

  function startFocusTimer(target, taskId, taskText, subtaskId = null) {
    stopFocusTimer();
    stopFocusChime();
    focusJustCompleted = null;
    focusTimer = {
      target, taskId, subtaskId, taskText,
      remaining: FOCUS_DURATION,
      duration: FOCUS_DURATION,
      paused: false,
      intervalId: setInterval(focusTimerTick, 1000),
    };
    updateFocusTitle();
    refreshTasksModalIfOpen(target);
  }

  function focusTimerTick() {
    if (!focusTimer || focusTimer.paused) return;
    focusTimer.remaining--;
    if (focusTimer.remaining <= 0) {
      focusTimerComplete();
      return;
    }
    updateFocusTitle();
    refreshTasksModalIfOpen(focusTimer.target);
  }

  function toggleFocusPause() {
    if (!focusTimer) return;
    focusTimer.paused = !focusTimer.paused;
    updateFocusTitle();
    refreshTasksModalIfOpen(focusTimer.target);
  }

  // Stacks more time onto a running (or paused) timer, e.g. from a "+1m"
  // button — lets a short default session grow as long as needed instead
  // of forcing a long duration up front.
  function extendFocusTimer(seconds) {
    if (!focusTimer) return;
    focusTimer.remaining += seconds;
    focusTimer.duration += seconds;
    updateFocusTitle();
    refreshTasksModalIfOpen(focusTimer.target);
  }

  function stopFocusTimer() {
    if (focusTimer && focusTimer.intervalId) clearInterval(focusTimer.intervalId);
    const prev = focusTimer;
    focusTimer = null;
    updateFocusTitle();
    if (prev) refreshTasksModalIfOpen(prev.target);
  }

  function focusTimerComplete() {
    const finished = focusTimer;
    if (finished && finished.intervalId) clearInterval(finished.intervalId);
    focusTimer = null;
    if (finished) lastFocusTaskText = finished.taskText;
    startFocusChime();
    updateFocusTitle();
    if (finished) {
      focusJustCompleted = { target: finished.target, taskId: finished.taskId, subtaskId: finished.subtaskId };
      refreshTasksModalIfOpen(finished.target);
      setTimeout(() => {
        if (focusJustCompleted && focusJustCompleted.taskId === finished.taskId && focusJustCompleted.subtaskId === finished.subtaskId) {
          focusJustCompleted = null;
          refreshTasksModalIfOpen(finished.target);
        }
      }, 4000);
    }
  }

  // The alarm keeps chiming — not just a single beep — until the person
  // dismisses it with any click/tap/keypress anywhere on the page, or
  // starts another focus timer. A generous safety cap stops it on its
  // own if the tab is left unattended, so it can never ring forever.
  const FOCUS_CHIME_INTERVAL = 1500;
  const FOCUS_CHIME_MAX_MS = 5 * 60 * 1000; // 5 minutes, just in case
  let focusChimeIntervalId = null;
  let focusChimeCapTimeoutId = null;
  let focusChimeDismissHandler = null;

  function startFocusChime() {
    stopFocusChime();
    playFocusChime();
    focusChimeIntervalId = setInterval(playFocusChime, FOCUS_CHIME_INTERVAL);
    focusChimeCapTimeoutId = setTimeout(stopFocusChime, FOCUS_CHIME_MAX_MS);
    focusChimeDismissHandler = () => stopFocusChime();
    // capture:true so it fires even if the click lands on something that
    // would otherwise stop propagation before reaching document.
    document.addEventListener("pointerdown", focusChimeDismissHandler, { capture: true, once: true });
    document.addEventListener("keydown", focusChimeDismissHandler, { capture: true, once: true });
    updateFocusTitle();
  }

  function stopFocusChime() {
    if (focusChimeIntervalId) { clearInterval(focusChimeIntervalId); focusChimeIntervalId = null; }
    if (focusChimeCapTimeoutId) { clearTimeout(focusChimeCapTimeoutId); focusChimeCapTimeoutId = null; }
    if (focusChimeDismissHandler) {
      document.removeEventListener("pointerdown", focusChimeDismissHandler, { capture: true });
      document.removeEventListener("keydown", focusChimeDismissHandler, { capture: true });
      focusChimeDismissHandler = null;
    }
    updateFocusTitle();
  }

  // A short two-tone chime via the Web Audio API — no audio file needed,
  // and it fails silently if the browser blocks autoplay before any
  // user gesture (there will have been one, since a click started the
  // timer, but this stays defensive either way).
  function playFocusChime() {
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      const ctx = new Ctx();
      [880, 1174.66].forEach((freq, i) => {
        const o = ctx.createOscillator();
        const g = ctx.createGain();
        o.type = "sine";
        o.frequency.value = freq;
        g.gain.value = 0.0001;
        o.connect(g);
        g.connect(ctx.destination);
        const start = ctx.currentTime + i * 0.16;
        g.gain.exponentialRampToValueAtTime(0.16, start + 0.02);
        g.gain.exponentialRampToValueAtTime(0.0001, start + 0.5);
        o.start(start);
        o.stop(start + 0.55);
      });
      setTimeout(() => ctx.close(), 1000);
    } catch (e) { /* ignore — chime is a nice-to-have, not essential */ }
  }


  // Reordering tasks by drag — drag the ⠿ handle on the left of any task
  // up or down to drop it before/after another task in the list.
  let taskDragState = null;

  function startTaskDrag(e, li, taskId) {
    e.stopPropagation();
    if (!requireSignIn()) { e.preventDefault(); return; }
    taskDragState = { taskId };
    e.dataTransfer.effectAllowed = "move";
    try { e.dataTransfer.setData("text/plain", ""); } catch (err) {}
    li.classList.add("task-dragging");
  }

  function endTaskDrag(li) {
    li.classList.remove("task-dragging");
    taskDragState = null;
    tasksListEl.querySelectorAll(".task-row").forEach(r => r.classList.remove("drag-over-top", "drag-over-bottom"));
  }

  // Mouse uses native HTML5 drag/drop. Touch browsers are much less
  // reliable there, so the same visible task grip uses Pointer Events on
  // phones: hold the grip and move immediately, with a floating preview
  // and auto-scroll near the list edges.
  function installTaskTouchDrag(handle, li, taskId) {
    let pointerId = null;
    let ghost = null;
    let target = null; // { id, before }

    const clearTargets = () => {
      tasksListEl.querySelectorAll(".task-row.drag-over-top, .task-row.drag-over-bottom")
        .forEach(el => el.classList.remove("drag-over-top", "drag-over-bottom"));
    };
    const cleanup = () => {
      clearTargets();
      if (ghost && ghost.parentNode) ghost.remove();
      ghost = null;
      target = null;
      li.classList.remove("task-dragging", "touch-dragging");
      taskDragState = null;
      pointerId = null;
    };
    const moveGhost = (x, y) => {
      if (!ghost) return;
      ghost.style.left = Math.max(6, Math.min(x + 12, window.innerWidth - ghost.offsetWidth - 6)) + "px";
      ghost.style.top = Math.max(6, Math.min(y + 12, window.innerHeight - ghost.offsetHeight - 6)) + "px";
    };
    const findTarget = (x, y) => {
      clearTargets();
      target = null;
      const stack = document.elementsFromPoint ? document.elementsFromPoint(x, y) : [document.elementFromPoint(x, y)];
      for (const el of stack) {
        if (!el || !el.closest) continue;
        const row = el.closest(".task-row[data-task-id]");
        if (!row || row === li || !tasksListEl.contains(row) || row.dataset.sharedQueue === "1") continue;
        const rect = row.getBoundingClientRect();
        const before = y < rect.top + rect.height / 2;
        row.classList.toggle("drag-over-top", before);
        row.classList.toggle("drag-over-bottom", !before);
        target = { id: row.dataset.taskId, before };
        break;
      }
    };
    const autoScroll = (y) => {
      const r = tasksListEl.getBoundingClientRect();
      if (y < r.top + 52) tasksListEl.scrollTop -= 14;
      else if (y > r.bottom - 52) tasksListEl.scrollTop += 14;
    };

    handle.addEventListener("pointerdown", (e) => {
      if (e.pointerType !== "touch" && e.pointerType !== "pen") return;
      if (e.isPrimary === false || !requireSignIn()) return;
      e.preventDefault();
      e.stopPropagation();
      closeContextMenu();
      pointerId = e.pointerId;
      taskDragState = { taskId };
      li.classList.add("task-dragging", "touch-dragging");
      try { handle.setPointerCapture(pointerId); } catch (err) {}
      try { if (navigator.vibrate) navigator.vibrate(8); } catch (err) {}
      ghost = document.createElement("div");
      ghost.className = "task-touch-ghost";
      const label = li.querySelector(".task-text");
      ghost.textContent = label ? label.textContent : "";
      document.body.appendChild(ghost);
      moveGhost(e.clientX, e.clientY);
      findTarget(e.clientX, e.clientY);
    }, { passive:false });

    handle.addEventListener("pointermove", (e) => {
      if (pointerId == null || e.pointerId !== pointerId) return;
      e.preventDefault();
      e.stopPropagation();
      moveGhost(e.clientX, e.clientY);
      autoScroll(e.clientY);
      findTarget(e.clientX, e.clientY);
    }, { passive:false });

    const finish = (e, commit) => {
      if (pointerId == null || e.pointerId !== pointerId) return;
      e.preventDefault();
      e.stopPropagation();
      const drop = target ? { ...target } : null;
      try { handle.releasePointerCapture(pointerId); } catch (err) {}
      cleanup();
      if (commit && drop) reorderTask(taskId, drop.id, drop.before);
    };
    handle.addEventListener("pointerup", (e) => finish(e, true), { passive:false });
    handle.addEventListener("pointercancel", (e) => finish(e, false), { passive:false });
  }

  // Single "★ Sort" button that alternates between two one-click reorders
  // each time it's pressed: star (then color) first, then color-only next
  // time, then back to star, etc. Each press is a real edit (goes through
  // pushUndo like any other reorder) using a stable sort, so equally-
  // ranked tasks keep their existing relative order. tasksSortMode tracks
  // which sort the *next* press will apply, and the button's label always
  // shows that upcoming action.
  let tasksSortMode = "star";
  function sortTasksModal() {
    if (!requireSignIn()) return;
    const target = tasksEditingTarget;
    const host = target && resolveHost(target.nodeId, target.r, target.c);
    if (!host) return;
    const tasks = getNodeTasks(host);
    if (tasks.length < 2) return;
    const cmp = tasksSortMode === "star"
      ? compareTasksByStarAndColor
      : (a, b) => taskColorSortIndex(a) - taskColorSortIndex(b);
    const sorted = tasks.slice().sort(cmp);
    pushUndo();
    host.tasks = sorted;
    persist();
    tasksSortMode = tasksSortMode === "star" ? "color" : "star";
    updateTasksSortBtnLabel();
    renderTasksModal();
  }
  function updateTasksSortBtnLabel() {
    tasksSortStarsBtn.textContent = tasksSortMode === "star" ? "★ Sort" : "🎨 Sort";
    tasksSortStarsBtn.title = tasksSortMode === "star"
      ? "Sort tasks by star, then color. Click again to sort by color instead."
      : "Sort tasks by color, ignoring star. Click again to sort by star instead.";
  }

  function reorderTask(sourceTaskId, targetTaskId, before) {
    const target = tasksEditingTarget;
    const host = target && resolveHost(target.nodeId, target.r, target.c);
    if (!host || sourceTaskId === targetTaskId) return;
    const tasks = getNodeTasks(host).slice();
    const fromIdx = tasks.findIndex(x => x.id === sourceTaskId);
    if (fromIdx === -1) return;
    const [moved] = tasks.splice(fromIdx, 1);
    const toIdx = tasks.findIndex(x => x.id === targetTaskId);
    if (toIdx === -1) {
      tasks.push(moved);
    } else {
      tasks.splice(before ? toIdx : toIdx + 1, 0, moved);
    }
    pushUndo();
    host.tasks = tasks;
    persist();
    renderTasksModal();
  }

  // Reordering subtasks by drag — same ⠿ handle convention as tasks. A
  // subtask can be dropped on another subtask row (to land at that exact
  // spot) or directly on a task's own row (to land at the end of that
  // task's list) — either way, it works both within the same task and
  // across two different tasks.
  let subtaskDragState = null;

  // Which tasks currently have their "add a subtask" input expanded —
  // it starts life as a small + button and swaps for the input on
  // click, collapsing back once you click away with nothing typed.
  let subtaskAddOpenFor = new Set();

  // ---- Line breaks between subtask pills ----------------------------
  // Click in the gap between two pills (or in the empty space beside
  // one) to drop a blinking caret there, then press Enter to force the
  // pill after the caret onto a new line. Enter again adds a blank line;
  // Backspace takes a break back out; ←/→ walk the caret between pills;
  // Esc (or clicking away) hides it. The break is stored on the pill it
  // sits in front of as `brBefore` (a small count), so the subtask data
  // model — and progress counting — is untouched.
  let subtaskCaret = null;        // { taskId, beforeId } while a caret is showing
  let subtaskCaretBusy = false;   // true while a re-render is swapping the list out

  function clearSubtaskCaret() {
    subtaskCaret = null;
    document.querySelectorAll(".subtask-caret").forEach(el => el.remove());
  }

  function enhanceSubtaskList(list, t, rerender) {
    const subs = getTaskSubtasks(t);
    const rows = Array.from(list.children).filter(el => el.classList.contains("subtask-row"));
    if (rows.length !== subs.length) return;
    list.tabIndex = -1;

    // Line-break spacers: the first forces a wrap, any extras are blank lines.
    rows.forEach((row, i) => {
      const n = Math.max(0, Math.min(5, subs[i].brBefore | 0));
      for (let k = 0; k < n; k++) {
        const br = document.createElement("li");
        br.className = "subtask-break" + (k > 0 ? " subtask-break-extra" : "");
        list.insertBefore(br, row);
      }
    });

    function placeCaret() {
      list.querySelectorAll(".subtask-caret").forEach(el => el.remove());
      if (!subtaskCaret || subtaskCaret.taskId !== t.id) return;
      const i = subs.findIndex(x => x.id === subtaskCaret.beforeId);
      if (i === -1) return;
      const caret = document.createElement("li");
      caret.className = "subtask-caret";
      list.insertBefore(caret, rows[i]);
    }
    placeCaret();
    if (subtaskCaret && subtaskCaret.taskId === t.id) {
      requestAnimationFrame(() => { if (list.isConnected) list.focus({ preventScroll: true }); });
    }

    // Which gap did the click land in? Nearest pill wins (vertical
    // distance weighted more so a click beside a line stays on that
    // line); left half of it = before, right half = after.
    function gapIndexFor(e) {
      let best = -1, bestD = Infinity;
      rows.forEach((row, i) => {
        const r = row.getBoundingClientRect();
        const dx = e.clientX < r.left ? r.left - e.clientX : (e.clientX > r.right ? e.clientX - r.right : 0);
        const dy = e.clientY < r.top ? r.top - e.clientY : (e.clientY > r.bottom ? e.clientY - r.bottom : 0);
        const d = dx * dx + dy * dy * 4;
        if (d < bestD) { bestD = d; best = i; }
      });
      if (best === -1) return -1;
      const r = rows[best].getBoundingClientRect();
      return e.clientX < (r.left + r.right) / 2 ? best : best + 1;
    }

    list.addEventListener("mousedown", (e) => {
      const c = e.target.classList;
      // (Not the pill itself: cancelling mousedown on it would stop it being dragged.)
      const isGap = e.target === list || (c && (c.contains("subtask-break") || c.contains("subtask-caret")));
      if (!isGap) { if (subtaskCaret) clearSubtaskCaret(); return; }
      e.preventDefault();
      const idx = gapIndexFor(e);
      document.querySelectorAll(".subtask-caret").forEach(el => el.remove());
      // Nothing follows the very end of the list, so there's nothing to break.
      if (idx < 0 || idx >= subs.length) { subtaskCaret = null; return; }
      subtaskCaret = { taskId: t.id, beforeId: subs[idx].id };
      placeCaret();
      list.focus({ preventScroll: true });
    });

    function commit() {
      persist();
      subtaskCaretBusy = true;
      rerender();
      requestAnimationFrame(() => { subtaskCaretBusy = false; });
    }

    list.addEventListener("keydown", (e) => {
      if (!subtaskCaret || subtaskCaret.taskId !== t.id) return;
      const i = subs.findIndex(x => x.id === subtaskCaret.beforeId);
      if (i === -1) return;
      if (e.key === "Enter") {
        e.preventDefault(); e.stopPropagation();
        if (!requireSignIn()) return;
        pushUndo();
        subs[i].brBefore = Math.min(5, (subs[i].brBefore | 0) + 1);
        commit();
      } else if (e.key === "Backspace") {
        e.preventDefault(); e.stopPropagation();
        if (!(subs[i].brBefore > 0)) return;
        if (!requireSignIn()) return;
        pushUndo();
        subs[i].brBefore -= 1;
        if (!subs[i].brBefore) delete subs[i].brBefore;
        commit();
      } else if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
        e.preventDefault(); e.stopPropagation();
        const j = i + (e.key === "ArrowLeft" ? -1 : 1);
        if (j < 0 || j >= subs.length) return;
        subtaskCaret = { taskId: t.id, beforeId: subs[j].id };
        placeCaret();
      } else if (e.key === "Escape") {
        e.preventDefault(); e.stopPropagation();
        clearSubtaskCaret();
        list.blur();
      }
    });

    list.addEventListener("blur", () => {
      if (subtaskCaretBusy) return;
      if (subtaskCaret && subtaskCaret.taskId === t.id) clearSubtaskCaret();
    });
  }

  function startSubtaskDrag(e, row, taskId, subtaskId) {
    e.stopPropagation();
    if (!requireSignIn()) { e.preventDefault(); return; }
    subtaskDragState = { taskId, subtaskId };
    e.dataTransfer.effectAllowed = "move";
    try { e.dataTransfer.setData("text/plain", ""); } catch (err) {}
    row.classList.add("task-dragging");
  }

  function endSubtaskDrag(row) {
    row.classList.remove("task-dragging");
    subtaskDragState = null;
    tasksListEl.querySelectorAll(".subtask-row").forEach(r => r.classList.remove("drag-over-top", "drag-over-bottom"));
    tasksListEl.querySelectorAll(".task-row.subtask-drop-target").forEach(r => r.classList.remove("subtask-drop-target"));
  }

  // Moves a subtask to a new spot — anywhere in its own task's list, or
  // into a different task's list entirely. `targetTaskId`/`targetSubtaskId`
  // describe where it's landing: pass a specific targetSubtaskId (plus
  // `before`) to drop it right next to that subtask, or leave
  // targetSubtaskId null to just drop it at the end of targetTaskId's list
  // (e.g. when it's dropped on the task's row rather than one of its
  // existing subtasks).
  function moveSubtask(sourceTaskId, sourceSubtaskId, targetTaskId, targetSubtaskId, before) {
    const target = tasksEditingTarget;
    const host = target && resolveHost(target.nodeId, target.r, target.c);
    if (!host) return;
    if (sourceTaskId === targetTaskId && sourceSubtaskId === targetSubtaskId) return;
    const tasks = getNodeTasks(host);
    const sourceTask = tasks.find(x => x.id === sourceTaskId);
    const targetTask = tasks.find(x => x.id === targetTaskId);
    if (!sourceTask || !targetTask) return;
    const sourceSubs = getTaskSubtasks(sourceTask).slice();
    const fromIdx = sourceSubs.findIndex(x => x.id === sourceSubtaskId);
    if (fromIdx === -1) return;
    const [moved] = sourceSubs.splice(fromIdx, 1);

    pushUndo();

    const sameTask = sourceTaskId === targetTaskId;
    const destSubs = sameTask ? sourceSubs : getTaskSubtasks(targetTask).slice();
    const toIdx = targetSubtaskId ? destSubs.findIndex(x => x.id === targetSubtaskId) : -1;
    if (toIdx === -1) {
      destSubs.push(moved);
    } else {
      destSubs.splice(before ? toIdx : toIdx + 1, 0, moved);
    }

    sourceTask.subtasks = sourceSubs;
    targetTask.subtasks = destSubs;
    if (!sameTask) {
      // Moving a subtask in or out changes what each task's own subtasks
      // add up to, which can flip its auto-derived done state.
      syncTaskDoneFromSubtasks(sourceTask);
      syncTaskDoneFromSubtasks(targetTask);
    }
    persist();
    renderTasksModal();
  }

  // Moves a subtask onto a task belonging to a *different* node entirely
  // (unlike moveSubtask above, which only reshuffles within the currently
  // open Tasks modal's own host). `targetTaskId` null means "create a new
  // task on targetNode named newTaskText and drop the subtask into that".
  function moveSubtaskToNode(sourceTaskId, sourceSubtaskId, targetNode, targetTaskId, newTaskText) {
    const target = tasksEditingTarget;
    const sourceHost = target && resolveHost(target.nodeId, target.r, target.c);
    if (!sourceHost || !targetNode) return;
    const sourceTasks = getNodeTasks(sourceHost);
    const sourceTask = sourceTasks.find(x => x.id === sourceTaskId);
    if (!sourceTask) return;
    const sourceSubs = getTaskSubtasks(sourceTask).slice();
    const fromIdx = sourceSubs.findIndex(x => x.id === sourceSubtaskId);
    if (fromIdx === -1) return;

    pushUndo();

    const [moved] = sourceSubs.splice(fromIdx, 1);
    sourceTask.subtasks = sourceSubs;

    if (!Array.isArray(targetNode.tasks)) targetNode.tasks = [];
    let targetTask = targetTaskId ? getNodeTasks(targetNode).find(x => x.id === targetTaskId) : null;
    if (!targetTask) {
      targetTask = { id: uid(), text: (newTaskText || "").trim() || "(untitled task)", done: false, stars: 0, due: null, subtasks: [] };
      targetNode.tasks = targetNode.tasks.concat([targetTask]);
    }
    if (!Array.isArray(targetTask.subtasks)) targetTask.subtasks = [];
    targetTask.subtasks = targetTask.subtasks.concat([moved]);

    // Moving a subtask in or out changes what each task's own subtasks
    // add up to, which can flip its auto-derived done state.
    syncTaskDoneFromSubtasks(sourceTask);
    syncTaskDoneFromSubtasks(targetTask);

    persist();
    renderTasksModal();
    showToast(`Moved to "${targetNode.text || "(untitled)"}"`);
  }

  // Popover for "Move to another node…" (see openSubtaskContextMenu): a
  // two-step picker since there's no way to drag a subtask onto a node on
  // the canvas while the Tasks modal — a full-screen overlay — is open.
  // Step 1 searches/lists every node in the map (collectAllNodesFlat);
  // picking one moves to step 2, which lists that node's existing tasks
  // plus a "new task" input, either of which completes the move.
  let subtaskMovePopoverEl = null;
  let subtaskMovePopoverOutsideHandler = null;
  function closeSubtaskMovePopover() {
    if (subtaskMovePopoverEl) { subtaskMovePopoverEl.remove(); subtaskMovePopoverEl = null; }
    if (subtaskMovePopoverOutsideHandler) {
      document.removeEventListener("mousedown", subtaskMovePopoverOutsideHandler);
      subtaskMovePopoverOutsideHandler = null;
    }
  }
  function openSubtaskMoveToNodePopover(x, y, sourceTask, subtask) {
    closeSubtaskMovePopover();
    const pop = document.createElement("div");
    pop.className = "folder-move-popover subtask-move-popover";
    let selectedNode = null;

    function reposition() {
      const margin = 8;
      let left = x, top = y;
      left = Math.max(margin, Math.min(left, window.innerWidth - pop.offsetWidth - margin));
      top = Math.max(margin, Math.min(top, window.innerHeight - pop.offsetHeight - margin));
      pop.style.left = `${left}px`;
      pop.style.top = `${top}px`;
    }

    function renderNodeList() {
      pop.innerHTML = "";
      selectedNode = null;
      const searchRow = document.createElement("div");
      searchRow.className = "folder-move-add-row";
      const search = document.createElement("input");
      search.type = "text";
      search.className = "folder-move-add-input";
      search.placeholder = "Search nodes…";
      search.spellcheck = false;
      search.autocomplete = "off";
      search.addEventListener("click", (e) => e.stopPropagation());
      search.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Escape") { e.preventDefault(); closeSubtaskMovePopover(); }
      });
      searchRow.appendChild(search);
      pop.appendChild(searchRow);

      const list = document.createElement("div");
      pop.appendChild(list);

      const allNodes = collectAllNodesFlat().filter(n => n.id !== (tasksEditingTarget && tasksEditingTarget.nodeId));
      function renderMatches() {
        list.innerHTML = "";
        const q = search.value.trim().toLowerCase();
        const matches = (q ? allNodes.filter(n => (n.text || "").toLowerCase().includes(q)) : allNodes).slice(0, 200);
        if (!matches.length) {
          const empty = document.createElement("div");
          empty.className = "folder-move-option";
          empty.textContent = "No matching nodes";
          list.appendChild(empty);
          return;
        }
        matches.forEach((n) => {
          const opt = document.createElement("button");
          opt.type = "button";
          opt.className = "folder-move-option";
          opt.textContent = n.text || "(untitled)";
          opt.addEventListener("mousedown", (e) => e.preventDefault());
          opt.addEventListener("click", (e) => {
            e.stopPropagation();
            renderTaskList(n);
            reposition();
          });
          list.appendChild(opt);
        });
      }
      search.addEventListener("input", renderMatches);
      renderMatches();
      reposition();
      setTimeout(() => search.focus(), 0);
    }

    function renderTaskList(node) {
      selectedNode = node;
      pop.innerHTML = "";

      const backRow = document.createElement("button");
      backRow.type = "button";
      backRow.className = "folder-move-option subtask-move-back";
      backRow.textContent = `← ${node.text || "(untitled)"}`;
      backRow.title = "Back to node search";
      backRow.addEventListener("mousedown", (e) => e.preventDefault());
      backRow.addEventListener("click", (e) => { e.stopPropagation(); renderNodeList(); });
      pop.appendChild(backRow);

      getNodeTasks(node).forEach((t) => {
        const opt = document.createElement("button");
        opt.type = "button";
        opt.className = "folder-move-option";
        opt.textContent = t.text || "(untitled task)";
        opt.addEventListener("mousedown", (e) => e.preventDefault());
        opt.addEventListener("click", (e) => {
          e.stopPropagation();
          moveSubtaskToNode(sourceTask.id, subtask.id, node, t.id, null);
          closeSubtaskMovePopover();
        });
        pop.appendChild(opt);
      });

      const addRow = document.createElement("div");
      addRow.className = "folder-move-add-row";
      const addInput = document.createElement("input");
      addInput.type = "text";
      addInput.className = "folder-move-add-input";
      addInput.placeholder = "New task…";
      addInput.spellcheck = false;
      addInput.autocomplete = "off";
      const addBtn = document.createElement("button");
      addBtn.type = "button";
      addBtn.className = "folder-move-add-btn";
      addBtn.textContent = "+";
      addBtn.title = "Create task and move here";
      function submitNewTask() {
        const name = addInput.value.trim();
        if (!name) { addInput.focus(); return; }
        moveSubtaskToNode(sourceTask.id, subtask.id, node, null, name);
        closeSubtaskMovePopover();
      }
      addBtn.addEventListener("mousedown", (e) => e.preventDefault());
      addBtn.addEventListener("click", (e) => { e.stopPropagation(); submitNewTask(); });
      addInput.addEventListener("click", (e) => e.stopPropagation());
      addInput.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Enter" && !e.isComposing) { e.preventDefault(); submitNewTask(); }
        else if (e.key === "Escape") { e.preventDefault(); closeSubtaskMovePopover(); }
      });
      addRow.append(addInput, addBtn);
      pop.appendChild(addRow);
      reposition();
      setTimeout(() => addInput.focus(), 0);
    }

    document.body.appendChild(pop);
    renderNodeList();
    pop.addEventListener("mousedown", (e) => e.stopPropagation());
    subtaskMovePopoverEl = pop;
    subtaskMovePopoverOutsideHandler = (e) => {
      if (!pop.contains(e.target)) closeSubtaskMovePopover();
    };
    setTimeout(() => document.addEventListener("mousedown", subtaskMovePopoverOutsideHandler), 0);
  }

  function openTasksModal(nodeId, r, c) {
    const host = resolveHost(nodeId, r, c);
    if (!host) return;
    commitEditIfActive();
    closeContextMenu();
    tasksEditingTarget = { nodeId, r, c };
    const node = findNode(nodeId);
    const cellText = (r != null && node && node.table && node.table.cells[r]) ? node.table.cells[r][c] : null;
    const label = r == null ? ((node && node.text) || "(untitled)") : (cellText || `Cell (row ${r + 1}, col ${c + 1})`);
    tasksModalTitle.textContent = `Tasks — ${label}`;
    renderTasksModal();
    zoomModalOpen(tasksModal);
    requestAnimationFrame(() => {
      autosizeTextarea(tasksNewInput);
      // Desktop benefits from immediate typing. On a phone this used to
      // open the keyboard every single time the task list was opened,
      // hiding half the list before the user even chose what to do.
      const phoneLike = window.matchMedia && window.matchMedia("(max-width: 700px) and (any-pointer: coarse)").matches;
      if (!phoneLike) tasksNewInput.focus();
    });
  }

  function closeTasksModal() {
    tasksEditingTarget = null;
    randomPickedSubtaskId = null;
    mobileTaskActionsOpenId = null;
    subtaskAddOpenFor.clear();
    closeTaskTemplatesPopover();
    renderAll();
    zoomModalClose(tasksModal);
  }

  // Right-click (or long-press on touch) menu for a single subtask pill —
  // replaces the hover-only copy (⧉) and delete (×) buttons that used to
  // sit inside every pill. Reuses the shared ctx-menu element.
  function copySubtaskText(text) {
    const done = () => showToast("Subtask copied");
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done).catch(done);
    } else {
      // Fallback for contexts without the async clipboard API.
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand("copy"); } catch (err) {}
      document.body.removeChild(ta);
      done();
    }
  }
  function openSubtaskContextMenu(x, y, t, s, rerender, openNotes) {
    resetContextMenu();
    const addItem = (label, cls, fn) => {
      const it = document.createElement("div");
      it.className = "ctx-item" + (cls ? " " + cls : "");
      const labelSpan = document.createElement("span");
      labelSpan.className = "ctx-item-label";
      labelSpan.textContent = label;
      it.appendChild(labelSpan);
      it.addEventListener("click", (e) => { e.stopPropagation(); closeContextMenu(); fn(); });
      ctxMenu.appendChild(it);
    };
    if (openNotes) {
      const n = getTaskNotes(s).length;
      addItem(n ? `📝 Notes (${n})…` : "📝 Add note…", "", openNotes);
    }
    addItem(s.failed ? "\u21a9 Clear failed" : "Mark failed", "", () => {
      pushUndo();
      setSubtaskFailed(t, s, !s.failed);
      persist();
      rerender();
    });
    addItem("Copy text", "", () => copySubtaskText(s.text));
    addItem("Move to another node…", "", () => {
      openSubtaskMoveToNodePopover(x, y, t, s);
    });
    addItem("Delete subtask", "danger", () => {
      if (!requireSignIn()) return;
      if (!confirm(`Delete the subtask "${s.text || "Untitled subtask"}"?`)) return;
      pushUndo();
      t.subtasks = getTaskSubtasks(t).filter(x => x !== s);
      syncTaskDoneFromSubtasks(t);
      persist();
      rerender();
    });
    positionContextMenu(x, y);
  }

  // Mobile browsers do not reliably synthesize `contextmenu` for an element
  // that is also draggable (our subtask pills are).  Give touch/pen input an
  // explicit long-press detector instead.  A small movement tolerance keeps
  // normal vertical scrolling from opening the menu, and the consumed flag
  // suppresses the synthetic click many browsers emit after the hold —
  // otherwise a successful long-press would also toggle the subtask done.
  function installSubtaskLongPress(row, openMenu) {
    let timer = null;
    let pointerId = null;
    let startX = 0, startY = 0;
    let restoreDraggable = null;

    const cancelPending = () => {
      if (timer) clearTimeout(timer);
      timer = null;
      pointerId = null;
      // A draggable element can enter the browser's native drag gesture on
      // Android before it ever emits contextmenu.  We temporarily turn that
      // behavior off only for the active touch, then put it back here.
      if (restoreDraggable !== null) {
        row.draggable = restoreDraggable;
        restoreDraggable = null;
      }
    };

    row.addEventListener("pointerdown", (e) => {
      if (e.pointerType !== "touch" && e.pointerType !== "pen") return;
      if (e.isPrimary === false) return;
      if (e.target.closest && e.target.closest(".subtask-touch-drag-handle")) return;
      if (e.target.closest && e.target.closest('[contenteditable="true"]')) return;
      cancelPending();
      pointerId = e.pointerId;
      startX = e.clientX;
      startY = e.clientY;
      restoreDraggable = row.draggable;
      row.draggable = false;
      timer = setTimeout(() => {
        timer = null;
        // Keep pointerId until pointerup/pointercancel so draggable is restored
        // after the finger actually leaves the screen.
        row.__subtaskLongPressConsumed = true;
        clearTimeout(row.__subtaskLongPressResetTimer);
        row.__subtaskLongPressResetTimer = setTimeout(() => {
          row.__subtaskLongPressConsumed = false;
        }, 900);
        try { if (navigator.vibrate) navigator.vibrate(12); } catch (err) {}
        closeContextMenu();
        openMenu(startX, startY);
      }, 520);
    }, { passive: true });

    row.addEventListener("pointermove", (e) => {
      if (!timer || e.pointerId !== pointerId) return;
      const dx = e.clientX - startX, dy = e.clientY - startY;
      if ((dx * dx + dy * dy) > 144) cancelPending(); // > 12 px = scrolling
    }, { passive: true });
    row.addEventListener("pointerup", (e) => {
      if (e.pointerId === pointerId) cancelPending();
    }, { passive: true });
    row.addEventListener("pointercancel", (e) => {
      if (e.pointerId === pointerId) cancelPending();
    }, { passive: true });
    row.addEventListener("dragstart", cancelPending);
  }

  // Native HTML5 drag/drop (row.draggable + dragstart/drop) works well
  // with a mouse but is inconsistent on touch browsers. Give touch/pen
  // users a dedicated grip that uses Pointer Events instead. Starting a
  // gesture on the grip means "drag", while starting on the pill itself
  // still means tap/scroll/long-press menu — no gesture conflict.
  function installSubtaskTouchDrag(row, taskId, subtaskId) {
    const grip = document.createElement("span");
    grip.className = "subtask-touch-drag-handle";
    grip.textContent = "⠿";
    grip.title = "Drag subtask";
    grip.setAttribute("role", "button");
    grip.setAttribute("aria-label", "Drag subtask");

    let pointerId = null;
    let ghost = null;
    let restoreDraggable = null;
    let dropTarget = null; // { taskId, subtaskId, before }

    const clearHints = () => {
      if (!tasksListEl) return;
      tasksListEl.querySelectorAll(".subtask-row.drag-over-top, .subtask-row.drag-over-bottom")
        .forEach(el => el.classList.remove("drag-over-top", "drag-over-bottom"));
      tasksListEl.querySelectorAll(".task-row.subtask-drop-target")
        .forEach(el => el.classList.remove("subtask-drop-target"));
    };

    const removeGhost = () => {
      if (ghost && ghost.parentNode) ghost.parentNode.removeChild(ghost);
      ghost = null;
    };

    const cleanup = () => {
      clearHints();
      removeGhost();
      row.classList.remove("task-dragging", "touch-dragging");
      subtaskDragState = null;
      if (restoreDraggable !== null) {
        row.draggable = restoreDraggable;
        restoreDraggable = null;
      }
      pointerId = null;
      dropTarget = null;
    };

    const makeGhost = (x, y) => {
      ghost = document.createElement("div");
      ghost.className = "subtask-touch-ghost";
      const label = row.querySelector(".subtask-text");
      ghost.textContent = label ? label.textContent : "";
      document.body.appendChild(ghost);
      ghost.style.left = (x + 12) + "px";
      ghost.style.top = (y + 12) + "px";
    };

    const moveGhost = (x, y) => {
      if (!ghost) return;
      const margin = 6;
      const maxX = Math.max(margin, window.innerWidth - ghost.offsetWidth - margin);
      const maxY = Math.max(margin, window.innerHeight - ghost.offsetHeight - margin);
      ghost.style.left = Math.max(margin, Math.min(x + 12, maxX)) + "px";
      ghost.style.top = Math.max(margin, Math.min(y + 12, maxY)) + "px";
    };

    const findDropTarget = (x, y) => {
      clearHints();
      dropTarget = null;

      // elementsFromPoint lets us ignore the source pill if the finger is
      // still partly over it and pick the real pill/task underneath.
      const stack = document.elementsFromPoint ? document.elementsFromPoint(x, y) : [document.elementFromPoint(x, y)];
      let targetSub = null;
      for (const el of stack) {
        if (!el || !el.closest) continue;
        const candidate = el.closest(".subtask-row[data-task-id]");
        if (candidate && candidate !== row && tasksListEl.contains(candidate)) {
          targetSub = candidate;
          break;
        }
      }
      if (targetSub) {
        const rect = targetSub.getBoundingClientRect();
        const phoneVertical = !!(window.matchMedia &&
          window.matchMedia("(max-width: 700px) and (any-pointer: coarse)").matches);
        const before = phoneVertical
          ? y < rect.top + rect.height / 2
          : (x - rect.left) < rect.width / 2;
        targetSub.classList.toggle("drag-over-top", before);
        targetSub.classList.toggle("drag-over-bottom", !before);
        dropTarget = {
          taskId: targetSub.dataset.taskId,
          subtaskId: targetSub.dataset.subtaskId,
          before
        };
        return;
      }

      let targetTask = null;
      for (const el of stack) {
        if (!el || !el.closest) continue;
        const candidate = el.closest(".task-row[data-task-id]");
        if (candidate && tasksListEl.contains(candidate)) {
          targetTask = candidate;
          break;
        }
      }
      if (targetTask) {
        targetTask.classList.add("subtask-drop-target");
        dropTarget = { taskId: targetTask.dataset.taskId, subtaskId: null, before: false };
      }
    };

    const autoScroll = (y) => {
      if (!tasksListEl) return;
      const r = tasksListEl.getBoundingClientRect();
      const edge = 44;
      if (y < r.top + edge) tasksListEl.scrollTop -= 12;
      else if (y > r.bottom - edge) tasksListEl.scrollTop += 12;
    };

    grip.addEventListener("pointerdown", (e) => {
      if (e.pointerType !== "touch" && e.pointerType !== "pen") return;
      if (e.isPrimary === false) return;
      if (!requireSignIn()) return;
      e.preventDefault();
      e.stopPropagation();
      closeContextMenu();

      pointerId = e.pointerId;
      dropTarget = null;
      restoreDraggable = row.draggable;
      row.draggable = false; // keep native drag from competing with pointer drag
      row.classList.add("task-dragging", "touch-dragging");
      subtaskDragState = { taskId, subtaskId };
      try { grip.setPointerCapture(pointerId); } catch (err) {}
      try { if (navigator.vibrate) navigator.vibrate(8); } catch (err) {}
      makeGhost(e.clientX, e.clientY);
      findDropTarget(e.clientX, e.clientY);
    }, { passive: false });

    grip.addEventListener("pointermove", (e) => {
      if (pointerId == null || e.pointerId !== pointerId) return;
      e.preventDefault();
      e.stopPropagation();
      moveGhost(e.clientX, e.clientY);
      autoScroll(e.clientY);
      findDropTarget(e.clientX, e.clientY);
    }, { passive: false });

    const finish = (e, commit) => {
      if (pointerId == null || e.pointerId !== pointerId) return;
      e.preventDefault();
      e.stopPropagation();
      const target = dropTarget ? { ...dropTarget } : null;
      try { grip.releasePointerCapture(pointerId); } catch (err) {}
      cleanup();
      if (commit && target && target.taskId) {
        moveSubtask(taskId, subtaskId, target.taskId, target.subtaskId, target.before);
      }
    };

    grip.addEventListener("pointerup", (e) => finish(e, true), { passive: false });
    grip.addEventListener("pointercancel", (e) => finish(e, false), { passive: false });
    // A synthetic click can follow touch pointerup; never let it bubble to
    // the pill's "toggle done" click handler.
    grip.addEventListener("click", (e) => { e.preventDefault(); e.stopPropagation(); });
    grip.addEventListener("contextmenu", (e) => { e.preventDefault(); e.stopPropagation(); });

    return grip;
  }

  // Builds the expanded subtask checklist panel for one task — a nested
  // <li> (so it sits inline in the same <ul> right under its task row)
  // holding a checkbox list plus a small "add subtask" input.
  function renderSubtaskPanel(node, t) {
    const wrap = document.createElement("li");
    wrap.className = "subtask-panel";
    // Keep the panel's fill in sync with its task row's own color tint
    // (rather than the flat --panel-2 default), so a colored task and
    // its open subtask list read as one continuous, matching card.
    wrap.style.background = taskColorTint(getTaskColor(t)) || "";

    const list = document.createElement("ul");
    list.className = "subtask-list";

    getTaskSubtasks(t).forEach((s) => {
      const row = document.createElement("li");
      row.className = "subtask-row" + (s.done ? " done" : "") + (s.failed ? " failed" : "") + (!s.done && !s.failed && s.id === randomPickedSubtaskId ? " picked" : "");
      row.dataset.taskId = t.id;
      row.dataset.subtaskId = s.id;

      row.addEventListener("dragover", (e) => {
        if (!subtaskDragState) return;
        if (subtaskDragState.taskId === t.id && subtaskDragState.subtaskId === s.id) return;
        e.preventDefault();
        e.stopPropagation(); // don't also trigger this task's row-level drop target below it
        e.dataTransfer.dropEffect = "move";
        const rect = row.getBoundingClientRect();
        const before = (e.clientX - rect.left) < rect.width / 2;
        row.classList.toggle("drag-over-top", before);
        row.classList.toggle("drag-over-bottom", !before);
      });
      row.addEventListener("dragleave", (e) => {
        if (e.relatedTarget && row.contains(e.relatedTarget)) return;
        row.classList.remove("drag-over-top", "drag-over-bottom");
      });
      row.addEventListener("drop", (e) => {
        if (!subtaskDragState) return;
        if (subtaskDragState.taskId === t.id && subtaskDragState.subtaskId === s.id) return;
        e.preventDefault();
        e.stopPropagation();
        const rect = row.getBoundingClientRect();
        const before = (e.clientX - rect.left) < rect.width / 2;
        row.classList.remove("drag-over-top", "drag-over-bottom");
        moveSubtask(subtaskDragState.taskId, subtaskDragState.subtaskId, t.id, s.id, before);
      });

      // The whole pill is the drag handle — grab it anywhere to reorder
      // (turned off while its text is being edited, so text can be selected).
      row.draggable = true;
      row.addEventListener("dragstart", (e) => startSubtaskDrag(e, row, t.id, s.id));
      row.addEventListener("dragend", () => endSubtaskDrag(row));

      const stext = document.createElement("span");
      stext.className = "subtask-text";
      stext.contentEditable = "false";
      stext.spellcheck = false;
      stext.textContent = s.text;
      // Skip the auto color once done — the .subtask-row.done .subtask-text
      // rule (dim + strikethrough) is the done indicator and would
      // otherwise be masked by this inline color, which always wins.
      if (!s.done && !s.failed) stext.style.color = taskFontColor(t);
      // The pill ellipsizes long text, so the title tooltip is the only
      // way to read it in full without double-clicking into edit mode.
      stext.title = s.text;

      // No more checkbox — a single click anywhere on the pill (other
      // than its note icon, or while its text is
      // mid-edit) toggles done. A short timer tells a single click apart
      // from the first half of a double-click, which opens text editing
      // instead (see the dblclick handler right below).
      let subtaskClickTimer = null;
      row.addEventListener("click", (e) => {
        if (row.__subtaskLongPressConsumed) {
          e.preventDefault();
          e.stopPropagation();
          row.__subtaskLongPressConsumed = false;
          if (subtaskClickTimer) { clearTimeout(subtaskClickTimer); subtaskClickTimer = null; }
          return;
        }
        if (stext.contentEditable === "true") return;
        if (subtaskClickTimer) { clearTimeout(subtaskClickTimer); subtaskClickTimer = null; return; }
        subtaskClickTimer = setTimeout(() => {
          subtaskClickTimer = null;
          try { if (navigator.vibrate) navigator.vibrate(7); } catch (err) {}
          pushUndo();
          setSubtaskDone(t, s, !s.done);
          persist();
          renderTasksModal();
        }, 220);
      });

      stext.addEventListener("dblclick", (e) => {
        e.preventDefault();
        row.draggable = false;
        stext.contentEditable = "true";
        stext.focus();
        const sel = window.getSelection();
        const range = document.createRange();
        range.selectNodeContents(stext);
        sel.removeAllRanges();
        sel.addRange(range);
      });
      stext.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Enter") { e.preventDefault(); stext.blur(); }
        else if (e.key === "Escape") { e.preventDefault(); stext.textContent = s.text; stext.blur(); }
      });
      stext.addEventListener("blur", () => {
        const v = stext.textContent.trim();
        if (v && v !== s.text) {
          pushUndo();
          s.text = v;
          persist();
        } else {
          stext.textContent = s.text;
        }
        stext.title = s.text;
        stext.contentEditable = "false";
        row.draggable = true;
      });

      row.addEventListener("contextmenu", (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (row.__subtaskLongPressConsumed) return;
        openSubtaskContextMenu(e.clientX, e.clientY, t, s, () => renderTasksModal(), openSubtaskNotes);
      });

      // Notes on a subtask — same editor as a task's notes (see
      // openNoteModal's subtaskId). Added from the right-click menu; once
      // a subtask has notes, a small note icon on the pill opens them directly.
      const openSubtaskNotes = () => {
        const target = tasksEditingTarget;
        if (!target) return;
        openNoteModal(node.id, undefined, null, t.id, target.r != null ? { r: target.r, c: target.c } : null, false, s.id);
      };
      installSubtaskLongPress(row, (x, y) => {
        openSubtaskContextMenu(x, y, t, s, () => renderTasksModal(), openSubtaskNotes);
      });
      const subtaskNotesForS = getTaskNotes(s);
      // A subtask literally named "DRC" behaves exactly like a task named
      // "DRC" (see the redirect in openNoteModal above): it shares the
      // node's single DRC note rather than owning one of its own, so the
      // icon shows up front — before any note exists — the same way a
      // DRC task's note button always shows the DRC image (see
      // taskNotes/noteBtn above).
      const subtaskIsDRC = isDRCNote(subtaskNotesForS[0]) || (s.text || "").trim().toUpperCase() === "DRC";
      // Same idea for a subtask named "plan": isPlanNoteFor also checks the
      // subtask's own name, so the plan icon shows up front — before any
      // note exists — just like the DRC icon does, and like a "plan" task's
      // note button already does.
      const subtaskIsPlan = isPlanNoteFor(subtaskNotesForS[0], s);
      let snote = null;
      if (subtaskNotesForS.length || subtaskIsDRC || subtaskIsPlan) {
        snote = document.createElement("span");
        snote.className = "subtask-note-icon";
        if (subtaskIsDRC) snote.appendChild(drcIconEl(13));
        else if (subtaskIsPlan) snote.appendChild(planIconEl(13));
        else snote.innerHTML = CELL_NOTE_ICON_SVG; // same sticky-note icon as everywhere else
        snote.title = subtaskNotesForS.length ? `Notes (${subtaskNotesForS.length})` : "Add note";
        snote.addEventListener("click", (e) => { e.stopPropagation(); openSubtaskNotes(); });
      }

      // Native whole-pill drag stays for mouse. Touch browsers get a
      // dedicated grip because native draggable rows are not reliable there.
      const touchDragGrip = installSubtaskTouchDrag(row, t.id, s.id);

      // No inline ✗ button on subtask pills — "Mark failed" / "Clear failed"
      // lives only in the pill's right-click menu (openSubtaskContextMenu).
      row.appendChild(touchDragGrip);
      row.appendChild(stext);
      if (snote) row.appendChild(snote);
      list.appendChild(row);
    });

    // "+" trigger for adding another subtask now lives at the end of
    // this task's own subtask list (it used to sit on the main task
    // row) — hidden while the add-input below is already open, so the
    // two don't show at once.
    if (!subtaskAddOpenFor.has(t.id)) {
      const addTriggerLi = document.createElement("li");
      addTriggerLi.className = "subtask-add-trigger";
      const addTriggerBtn = document.createElement("button");
      addTriggerBtn.type = "button";
      addTriggerBtn.className = "subtask-add-btn";
      addTriggerBtn.title = "Add a subtask";
      addTriggerBtn.textContent = "+";
      addTriggerBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        subtaskAddOpenFor.add(t.id);
        renderTasksModal();
      });
      addTriggerLi.appendChild(addTriggerBtn);
      list.appendChild(addTriggerLi);
    }

    enhanceSubtaskList(list, t, () => renderTasksModal());
    wrap.appendChild(list);

    // The "+" trigger itself now lives on the main task row, next to its
    // timer, so it's reachable without opening the panel first. This add
    // row only needs to exist while that trigger has put it into "open"
    // (typing) mode.
    if (subtaskAddOpenFor.has(t.id)) {
      const addRow = document.createElement("div");
      addRow.className = "subtask-add-row";

      const addInput = document.createElement("textarea");
      addInput.rows = 1;
      addInput.className = "subtask-new-input autosize-input";
      addInput.placeholder = "Add a subtask and press Enter…";
      addInput.spellcheck = false;
      addInput.dataset.taskId = t.id;
      addInput.addEventListener("click", (e) => e.stopPropagation());
      addInput.addEventListener("input", () => autosizeTextarea(addInput));
      addInput.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Enter" && !e.shiftKey) {
          e.preventDefault();
          const v = addInput.value.trim();
          if (!v) return;
          pushUndo();
          if (!Array.isArray(t.subtasks)) t.subtasks = [];
          t.subtasks.push({ id: uid(), text: v, done: false });
          // A brand-new subtask is unchecked, so the parent can no longer
          // be considered fully done (or fully failed).
          t.done = false;
          t.failed = false;
          persist();
          renderTasksModal();
          // Re-render rebuilds the DOM, so re-focus the (new) input for
          // this same task, letting the person add several in a row.
          requestAnimationFrame(() => {
            const el = tasksListEl.querySelector(`.subtask-new-input[data-task-id="${t.id}"]`);
            if (el) el.focus();
          });
        } else if (e.key === "Escape") {
          e.preventDefault();
          addInput.blur();
        }
      });
      addInput.addEventListener("blur", () => {
        // Nothing typed — collapse the input away again. A pending value
        // is left as-is (re-opening keeps it) rather than lost.
        if (!addInput.value.trim()) {
          subtaskAddOpenFor.delete(t.id);
          renderTasksModal();
        }
      });
      addRow.appendChild(addInput);
      wrap.appendChild(addRow);
      requestAnimationFrame(() => addInput.focus());
    }

    return wrap;
  }

  function renderTasksModal() {
    const target = tasksEditingTarget;
    if (!target) return;
    const node = findNode(target.nodeId);
    const host = resolveHost(target.nodeId, target.r, target.c);
    if (!node || !host) { closeTasksModal(); return; }
    renderFocusTimerWidget();
    const tasks = getNodeTasks(host);
    tasksListEl.innerHTML = "";
    renderSharedQueueTask();
    if (Date.now() - taskTemplateLastSyncAt > 5000 && !taskTemplateSyncRunning) {
      syncTaskTemplatesWithDrive().then((changed) => {
        if (changed && tasksEditingTarget) renderTasksModal();
      });
    }
    tasks.forEach((t) => {
      const li = document.createElement("li");
      const subProg = taskSubtaskProgress(t);
      // The panel (and its border/fill) should only ever appear for a task
      // that actually has subtasks, or one whose "+" button was just
      // clicked to start adding its first one — not for every plain task
      // by default.
      const subExpanded = (subProg.total > 0 || subtaskAddOpenFor.has(t.id)) && !collapsedSubtaskIds.has(t.id);
      const showingSubtasks = subExpanded && subProg.total > 0;
      li.className = "task-row" + (t.done ? " done" : "") + (t.failed ? " failed" : "") + (getTaskStars(t) > 0 ? " starred" : "") + (showingSubtasks ? " has-open-subtasks" : "");
      li.dataset.taskId = t.id;
      const rowColor = getTaskColor(t);
      li.style.background = taskColorTint(rowColor) || "";

      li.addEventListener("dragover", (e) => {
        if (taskDragState && taskDragState.taskId !== t.id) {
          e.preventDefault();
          e.dataTransfer.dropEffect = "move";
          const rect = li.getBoundingClientRect();
          const before = (e.clientY - rect.top) < rect.height / 2;
          li.classList.toggle("drag-over-top", before);
          li.classList.toggle("drag-over-bottom", !before);
        } else if (subtaskDragState) {
          // A subtask dragged onto a task's own row (rather than one of
          // its existing subtask rows) — drop it at the end of this
          // task's subtask list. Works for a different task or, just as
          // well, sending it to the bottom of its own current task.
          e.preventDefault();
          e.dataTransfer.dropEffect = "move";
          li.classList.add("subtask-drop-target");
        }
      });
      li.addEventListener("dragleave", (e) => {
        if (e.relatedTarget && li.contains(e.relatedTarget)) return;
        li.classList.remove("drag-over-top", "drag-over-bottom", "subtask-drop-target");
      });
      li.addEventListener("drop", (e) => {
        if (taskDragState && taskDragState.taskId !== t.id) {
          e.preventDefault();
          const rect = li.getBoundingClientRect();
          const before = (e.clientY - rect.top) < rect.height / 2;
          li.classList.remove("drag-over-top", "drag-over-bottom");
          reorderTask(taskDragState.taskId, t.id, before);
        } else if (subtaskDragState) {
          e.preventDefault();
          li.classList.remove("subtask-drop-target");
          moveSubtask(subtaskDragState.taskId, subtaskDragState.subtaskId, t.id, null, false);
        }
      });

      const handle = document.createElement("span");
      handle.className = "task-drag-handle";
      handle.textContent = "⠿";
      handle.title = "Drag to reorder";
      handle.draggable = true;
      handle.addEventListener("mousedown", (e) => { e.stopPropagation(); });
      handle.addEventListener("dragstart", (e) => startTaskDrag(e, li, t.id));
      handle.addEventListener("dragend", () => endTaskDrag(li));
      installTaskTouchDrag(handle, li, t.id);

      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.className = "task-checkbox";
      cb.checked = !!t.done;
      cb.addEventListener("change", () => {
        try { if (navigator.vibrate) navigator.vibrate(8); } catch (err) {}
        pushUndo();
        // Checking/unchecking a task with subtasks cascades to all of
        // them, mirroring the auto-complete-parent behavior below.
        // (Marking done also clears a failed mark.)
        setTaskDone(t, cb.checked);
        persist();
        renderTasksModal();
      });

      // ✗ — mark this task failed (the opposite of the done checkbox).
      const failBtn = makeTaskFailButton(!!t.failed, () => {
        pushUndo();
        setTaskFailed(t, !t.failed);
        persist();
        renderTasksModal();
      });

      const stars = getTaskStars(t);
      const star = document.createElement("button");
      star.type = "button";
      star.className = "task-star" + (stars > 0 ? " starred" : "");
      star.textContent = stars > 0 ? "★" : "☆";
      star.title = stars > 0
        ? "Starred — counts 10x toward progress. Click to clear."
        : "Star this task for priority — counts 10x toward progress";
      star.addEventListener("click", (e) => {
        e.stopPropagation();
        if (blockedByStarCap(host, t)) return;
        const next = stars > 0 ? 0 : 1;
        pushUndo();
        t.stars = next;
        t.starred = t.stars > 0; // kept in sync for older code paths reading the legacy flag
        persist();
        renderTasksModal();
      });

      // Optional color label (see getTaskColor/setTaskColor) — click opens
      // the shared swatch popover. The button itself is a small hollow
      // ring in the current color (the light fill on the whole row is
      // the primary indicator), or a faint dashed ring when there isn't
      // one set yet.
      const colorBtn = document.createElement("button");
      colorBtn.type = "button";
      const taskColor = getTaskColor(t);
      colorBtn.className = "task-color-dot" + (taskColor ? "" : " task-color-dot-empty");
      if (taskColor) colorBtn.style.borderColor = taskColor;
      colorBtn.title = taskColor ? "Change color label" : "Add a color label";
      colorBtn.addEventListener("mousedown", (e) => e.stopPropagation());
      colorBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        openTaskColorPopover(colorBtn, t, renderTasksModal);
      });

      const text = document.createElement("span");
      text.className = "task-text";
      text.contentEditable = "true";
      text.spellcheck = false;
      text.textContent = t.text;
      // Skip the auto color once done — .task-row.done .task-text (dim)
      // is the done indicator and would otherwise be masked by this
      // inline color, which always wins over a class-based rule.
      if (!t.done && !t.failed) text.style.color = taskFontColor(t);
      text.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Enter") { e.preventDefault(); text.blur(); }
        else if (e.key === "Escape") { e.preventDefault(); text.textContent = t.text; text.blur(); }
      });
      text.addEventListener("blur", () => {
        const v = text.textContent.trim();
        if (v && v !== t.text) {
          pushUndo();
          t.text = v;
          persist();
        } else {
          text.textContent = t.text;
        }
      });

      // Desktop keeps the old double-click shortcut. Phones also get a
      // dedicated one-tap subtask count button below, because double-tap
      // is slow and conflicts with zoom/text selection on touch screens.
      li.title = subExpanded
        ? "Double-click to hide subtasks"
        : (subProg.total ? `${subProg.done} of ${subProg.total} subtasks — double-click to view` : "Double-click to add subtasks");
      li.addEventListener("dblclick", (e) => {
        if (e.target.closest(".task-checkbox, .task-fail-btn, .task-star, .task-color-dot, .task-delete, .task-drag-handle, .task-note-btn, .task-due-btn, .task-text, .task-mobile-more, .task-mobile-subtasks, .task-mobile-actions")) return;
        if (subExpanded) {
          collapsedSubtaskIds.add(t.id);
        } else {
          collapsedSubtaskIds.delete(t.id);
          if (!subProg.total) subtaskAddOpenFor.add(t.id);
        }
        renderTasksModal();
      });

      const mobileSubtasksBtn = document.createElement("button");
      mobileSubtasksBtn.type = "button";
      mobileSubtasksBtn.className = "task-mobile-subtasks" + (subProg.total ? "" : " hidden");
      mobileSubtasksBtn.textContent = subProg.total
        ? ((subExpanded ? "▾ " : "▸ ") + subProg.done + "/" + subProg.total)
        : "";
      mobileSubtasksBtn.title = subExpanded ? "Hide subtasks" : "Show subtasks";
      mobileSubtasksBtn.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (!subProg.total) return;
        if (subExpanded) collapsedSubtaskIds.add(t.id);
        else collapsedSubtaskIds.delete(t.id);
        renderTasksModal();
      });

      // Due date — feeds the toolbar's 📅 Calendar month view. Click
      // anywhere on the button to open a native date picker positioned
      // right over it; picking a date (or clearing it) stamps t.due as
      // a plain "YYYY-MM-DD" string, same convention as the standalone
      // Tasks app.
      const dueDate = t.due ? fromISODate(t.due) : null;
      const isOverdue = !!(dueDate && !t.done && !t.failed && dueDate < startOfToday());
      const dueBtn = document.createElement("span");
      dueBtn.className = "task-due-btn" + (t.due ? " has-due" : "") + (isOverdue ? " overdue" : "");
      dueBtn.title = t.due ? "Change or clear due date" : "Set a due date";
      const dueIcon = document.createElement("span");
      dueIcon.className = "task-due-icon";
      dueIcon.textContent = "📅";
      dueBtn.appendChild(dueIcon);
      if (t.due) {
        const dueLabel = document.createElement("span");
        dueLabel.className = "task-due-label";
        dueLabel.textContent = `${dueDate.getMonth() + 1}/${dueDate.getDate()}`;
        dueBtn.appendChild(dueLabel);
      }
      const dueInput = document.createElement("input");
      dueInput.type = "date";
      dueInput.className = "task-due-input";
      if (t.due) dueInput.value = t.due;
      dueInput.addEventListener("click", (e) => e.stopPropagation());
      dueInput.addEventListener("change", () => {
        pushUndo();
        t.due = dueInput.value || null;
        persist();
        renderTasksModal();
      });
      dueBtn.appendChild(dueInput);

      // A task's note(s) now use the exact same rich, multi-entry note
      // editor as a node's own notes (title, rich text, multiple notes
      // with paging) — see openNoteModal/getTaskNotes — just opened from
      // this one button instead of a strip of per-note icons.
      const noteBtn = document.createElement("button");
      noteBtn.type = "button";
      const taskNotes = getTaskNotes(t);
      noteBtn.className = "task-note-btn" + (taskNotes.length ? " has-note" : "");
      noteBtn.title = taskNotes.length ? `Notes (${taskNotes.length})` : "Add note";
      // Same sticky-note icon as the node/cell note markers (CELL_NOTE_ICON_SVG).
      // A task whose note is a DRC (or a task literally named "DRC", which
      // opens the node's DRC note) shows the DRC image instead.
      if (isDRCNote(taskNotes[0]) || (t.text || "").trim().toUpperCase() === "DRC") noteBtn.appendChild(drcIconEl(16));
      else if (isPlanNoteFor(taskNotes[0], t)) noteBtn.appendChild(planIconEl(16));
      else noteBtn.innerHTML = CELL_NOTE_ICON_SVG;
      noteBtn.addEventListener("mousedown", (e) => { e.stopPropagation(); });
      noteBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        openNoteModal(node.id, undefined, null, t.id, target.r != null ? { r: target.r, c: target.c } : null);
      });

      // Add-subtask icon — reachable straight from the row, even for a
      // brand-new task with no subtasks yet, without needing the
      // double-click gesture first. Clicking it opens (or reveals) this
      // task's subtask panel with the "add" input already focused.
      const subtaskBtn = document.createElement("button");
      subtaskBtn.type = "button";
      subtaskBtn.className = "task-subtask-btn" + (subProg.total ? " has-subtasks" : "");
      subtaskBtn.title = subProg.total ? "Add another subtask" : "Add a subtask";
      subtaskBtn.textContent = "+";
      subtaskBtn.addEventListener("mousedown", (e) => e.stopPropagation());
      subtaskBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        collapsedSubtaskIds.delete(t.id);
        subtaskAddOpenFor.add(t.id);
        renderTasksModal();
      });

      const del = document.createElement("button");
      del.className = "task-delete";
      del.title = "Delete task";
      del.textContent = "×";
      del.addEventListener("click", () => {
        if (!requireSignIn()) return;
        if (!confirm(`Delete the task "${t.text || "Untitled task"}"?`)) return;
        pushUndo();
        host.tasks = getNodeTasks(host).filter(x => x !== t);
        if (mobileTaskActionsOpenId === t.id) mobileTaskActionsOpenId = null;
        persist();
        renderTasksModal();
      });

      // Desktop renders the wrapper as display:contents, preserving the
      // familiar one-line controls. On a phone it becomes a wide action
      // drawer revealed by one large "…" button, so the task name does
      // not get crushed by seven tiny controls.
      const mobileActions = document.createElement("div");
      mobileActions.className = "task-mobile-actions" + (mobileTaskActionsOpenId === t.id ? " open" : "");
      failBtn.dataset.mobileLabel = t.failed ? "Clear fail" : "Fail";
      subtaskBtn.dataset.mobileLabel = "Subtask";
      dueBtn.dataset.mobileLabel = t.due ? ("Due " + (dueDate.getMonth() + 1) + "/" + dueDate.getDate()) : "Due date";
      noteBtn.dataset.mobileLabel = taskNotes.length ? "Notes" : "Note";
      star.dataset.mobileLabel = stars > 0 ? "Unstar" : "Priority";
      colorBtn.dataset.mobileLabel = "Color";
      del.dataset.mobileLabel = "Delete";
      mobileActions.append(failBtn, subtaskBtn, dueBtn, noteBtn, star, colorBtn, del);

      const mobileMore = document.createElement("button");
      mobileMore.type = "button";
      mobileMore.className = "task-mobile-more" + (mobileTaskActionsOpenId === t.id ? " active" : "");
      mobileMore.textContent = "⋯";
      mobileMore.title = mobileTaskActionsOpenId === t.id ? "Hide task actions" : "Show task actions";
      mobileMore.setAttribute("aria-expanded", mobileTaskActionsOpenId === t.id ? "true" : "false");
      mobileMore.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
        const opening = mobileTaskActionsOpenId !== t.id;
        mobileTaskActionsOpenId = opening ? t.id : null;
        tasksListEl.querySelectorAll(".task-mobile-actions.open").forEach(el => el.classList.remove("open"));
        tasksListEl.querySelectorAll(".task-mobile-more.active").forEach(el => {
          el.classList.remove("active");
          el.setAttribute("aria-expanded", "false");
        });
        if (opening) {
          mobileActions.classList.add("open");
          mobileMore.classList.add("active");
          mobileMore.setAttribute("aria-expanded", "true");
        }
      });

      li.appendChild(handle);
      li.appendChild(cb);
      li.appendChild(text);
      li.appendChild(mobileSubtasksBtn);
      li.appendChild(mobileMore);
      li.appendChild(mobileActions);
      tasksListEl.appendChild(li);

      if (subExpanded) tasksListEl.appendChild(renderSubtaskPanel(node, t));
    });

    const prog = nodeTaskProgress(host);
    tasksProgressBar.style.width = Math.round(prog.pct * 100) + "%";
    tasksProgressBar.classList.toggle("done", prog.pct >= 1);
    tasksProgressLabel.textContent = prog.total
      ? `${prog.done} of ${prog.total} done`
      : "No tasks yet";
    tasksSortStarsBtn.disabled = tasks.length < 2;
    tasksRandomBtn.disabled = unfinishedSubtasksOfHost(host).length === 0;
    updateTaskFontColorToggleBtn();
  }

  // 🎲 Random — picks one unfinished subtask uniformly from every task in
  // the list (not just within a single task), highlights it and scrolls
  // it into view. Avoids repeating the previous pick when there's a choice.
  function pickRandomSubtask() {
    const target = tasksEditingTarget;
    const host = target && resolveHost(target.nodeId, target.r, target.c);
    if (!host) return;
    let pool = unfinishedSubtasksOfHost(host);
    if (!pool.length) { showToast("No unfinished subtasks to pick from"); return; }
    if (pool.length > 1) pool = pool.filter(({ s }) => s.id !== randomPickedSubtaskId);
    const { t, s } = pool[Math.floor(Math.random() * pool.length)];
    randomPickedSubtaskId = s.id;
    // Make sure its task's subtask panel isn't collapsed, or the pick would be hidden.
    collapsedSubtaskIds.delete(t.id);
    renderTasksModal();
    const row = tasksListEl.querySelector(`.subtask-row[data-subtask-id="${s.id}"]`);
    if (row) row.scrollIntoView({ block: "center", behavior: "smooth" });
    showToast(`🎲 ${s.text}`);
  }
  tasksRandomBtn.addEventListener("click", pickRandomSubtask);

  // Reflects the current taskFontBlackMode on the toggle button itself
  // (label + pressed state) — called whenever the tasks modal (re)renders.
  function updateTaskFontColorToggleBtn() {
    tasksFontColorToggleBtn.textContent = taskFontBlackMode ? "⚫ Font" : "🎨 Font";
    tasksFontColorToggleBtn.title = taskFontBlackMode
      ? "Task text is plain black — click to use dynamic per-task colors again"
      : "Task text uses dynamic per-task colors — click to make it all black";
    tasksFontColorToggleBtn.classList.toggle("active", taskFontBlackMode);
  }

  function addTaskFromModal() {
    const target = tasksEditingTarget;
    const host = target && resolveHost(target.nodeId, target.r, target.c);
    if (!host) return;
    const val = tasksNewInput.value.trim();
    if (!val) return;
    pushUndo();
    if (!Array.isArray(host.tasks)) host.tasks = [];
    host.tasks = host.tasks.concat([{ id: uid(), text: val, done: false, stars: 0, due: null }]);
    tasksNewInput.value = "";
    autosizeTextarea(tasksNewInput);
    persist();
    renderTasksModal();
  }

  // Grows a textarea's height to fit whatever's been typed (up to its
  // CSS max-height, after which it scrolls), so a long task/subtask is
  // visible in full while composing instead of scrolling sideways in a
  // single-line box.
  function autosizeTextarea(el) {
    el.style.height = "auto";
    el.style.height = el.scrollHeight + "px";
  }

  tasksNewInput.addEventListener("input", () => autosizeTextarea(tasksNewInput));
  if (tasksAddSubmitBtn) {
    tasksAddSubmitBtn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (tasksNewInput.value.trim()) {
        addTaskFromModal();
        try { if (navigator.vibrate) navigator.vibrate(8); } catch (err) {}
      } else {
        tasksNewInput.focus();
      }
    });
  }
  // Belt-and-suspenders for the keyboard-overlap fix above: the CSS
  // --keyboard-inset padding shifts the whole modal up, but if the task
  // list itself is long enough that the modal card was already scrolled,
  // the input can still end up just out of view. A short delay lets the
  // on-screen keyboard's open animation (and the resulting visualViewport
  // resize) finish first, so scrollIntoView measures against the final,
  // keyboard-shrunk layout rather than the pre-keyboard one.
  tasksNewInput.addEventListener("focus", () => {
    setTimeout(() => tasksNewInput.scrollIntoView({ block: "nearest", behavior: "smooth" }), 300);
  });
  tasksNewInput.addEventListener("keydown", (e) => {
    e.stopPropagation();
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); addTaskFromModal(); }
    else if (e.key === "Escape") { e.preventDefault(); closeTasksModal(); }
  });
  $("#tasks-back").addEventListener("click", closeTasksModal);
  $("#tasks-close").addEventListener("click", closeTasksModal);
  tasksSortStarsBtn.addEventListener("click", sortTasksModal);
  tasksFontColorToggleBtn.addEventListener("click", () => {
    setTaskFontBlackMode(!taskFontBlackMode);
    renderTasksModal();
    // Keep the calendar day popup's task list (same task objects, same
    // taskFontColor) in sync if it happens to be open at the same time.
    const calDayModalEl = $("#cal-day-modal");
    if (calDayModalEl && !calDayModalEl.classList.contains("hidden")) renderCalDayModal();
  });
  tasksModal.addEventListener("click", (e) => { if (!tasksIsResizing && e.target === tasksModal) closeTasksModal(); });
  document.addEventListener("keydown", (e) => {
    if (tasksModal.classList.contains("hidden")) return;
    if (e.key === "Escape" && document.activeElement !== tasksNewInput) closeTasksModal();
  });

  /* ---------------- calendar (📅 toolbar button) ----------------
     A single month grid across every task, on every node, in the
     current map that has a due date — the Calendar tab from the
     standalone Tasks app, promoted into Branchline as a read-through
     view over the same per-node task lists (nothing new is stored;
     it just reads node.tasks[].due across the whole tree, including
     inside collapsed branches). Tapping a day opens a popup with that
     day's full due list; each row can be checked off and jumped to on
     the canvas, same as tapping a task normally would. */
  const WEEKDAY_LABELS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const MONTH_LABELS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

  const calendarModal = $("#calendar-modal");
  const calMonthLabelEl = $("#cal-month-label");
  const calWeekdaysEl = $("#calendar-weekdays");
  const calGridEl = $("#calendar-grid");
  const calPrevBtn = $("#cal-prev-btn");
  const calNextBtn = $("#cal-next-btn");
  const calTodayBtn = $("#cal-today-btn");
  const calDayModalBackdrop = $("#cal-day-modal-backdrop");
  const calDayModalTitle = $("#cal-day-modal-title");
  const calDayModalList = $("#cal-day-modal-task-list");
  const calDayModalEmpty = $("#cal-day-modal-empty-state");
  const calDayNewInput = $("#cal-day-new-input");
  const calDaySortBtn = $("#cal-day-sort-stars");
  let calCursor = new Date();
  calCursor.setDate(1); // first of the currently-displayed month
  let calDayModalDate = null; // "YYYY-MM-DD" of the day currently shown, or null when closed
  let calDaySortMode = "off"; // "off" | "star" | "color" — view-only sort toggle for the day popup, reset each time it opens

  // Every task on every node, anywhere in the tree — deliberately
  // ignores node.collapsed (unlike the render walks) so a task due
  // today still shows up on the calendar even if its node is tucked
  // inside a collapsed branch.
  function allTasksWithNodes() {
    const out = [];
    if (!state.current) return out;
    (function walk(n) {
      getNodeTasks(n).forEach(t => out.push({ task: t, node: n, r: null, c: null }));
      if (n.table && Array.isArray(n.table.attach)) {
        n.table.attach.forEach((row, r) => (row || []).forEach((a, c) => {
          getNodeTasks(a).forEach(t => out.push({ task: t, node: n, r, c }));
        }));
      }
      (n.children || []).forEach(walk);
    })(state.current.root);
    return out;
  }

  function calendarBoxFontSize(count) {
    const base = 13, min = 6.5, step = 0.35, freeSlots = 8;
    const size = base - Math.max(0, count - freeSlots) * step;
    return Math.max(min, size).toFixed(2) + "px";
  }

  // A task with 2+ subtasks gets broken into one small box per subtask
  // (so each can be seen/ticked from the calendar); a task with 0-1
  // subtasks stays a single box for the whole task.
  function calendarDayItems(dayEntries) {
    const items = [];
    dayEntries.forEach(({ task: t, node }) => {
      const subs = getTaskSubtasks(t);
      if (subs.length >= 2) {
        subs.forEach((s) => {
          items.push({ kind: "subtask", task: t, subtask: s, node, done: !!s.done, failed: !!s.failed && !s.done, label: `${t.text || "Untitled task"} — ${s.text || "Untitled subtask"}` });
        });
      } else {
        items.push({ kind: "task", task: t, node, done: !!t.done, failed: !!t.failed && !t.done, label: t.text || "Untitled task" });
      }
    });
    return items;
  }

  function openCalendarModal() {
    commitEditIfActive();
    closeContextMenu();
    calCursor = new Date();
    calCursor.setDate(1);
    renderCalendar();
    zoomModalOpen(calendarModal);
  }
  function closeCalendarModal() {
    zoomModalClose(calendarModal);
  }

  function renderCalendar() {
    calMonthLabelEl.textContent = `${MONTH_LABELS[calCursor.getMonth()]} ${calCursor.getFullYear()}`;

    if (!calWeekdaysEl.childElementCount) {
      WEEKDAY_LABELS.forEach((w) => {
        const el = document.createElement("div");
        el.className = "calendar-weekday";
        el.textContent = w;
        calWeekdaysEl.appendChild(el);
      });
    }

    calGridEl.innerHTML = "";
    const year = calCursor.getFullYear(), month = calCursor.getMonth();
    const startWeekday = new Date(year, month, 1).getDay();
    const gridStart = new Date(year, month, 1 - startWeekday);
    const today = new Date();

    const entriesByDate = {};
    allTasksWithNodes().forEach((entry) => {
      if (entry.task.due) (entriesByDate[entry.task.due] = entriesByDate[entry.task.due] || []).push(entry);
    });

    for (let i = 0; i < 42; i++) {
      const cellDate = new Date(gridStart.getFullYear(), gridStart.getMonth(), gridStart.getDate() + i);
      const iso = toISODate(cellDate);
      const cell = document.createElement("div");
      cell.className = "calendar-cell";
      if (cellDate.getMonth() !== month) cell.classList.add("other-month");
      if (isSameDate(cellDate, today)) cell.classList.add("today");

      const dayHead = document.createElement("div");
      dayHead.className = "calendar-day-head";

      const dayNum = document.createElement("span");
      dayNum.className = "calendar-day-num";
      dayNum.textContent = cellDate.getDate();
      dayHead.appendChild(dayNum);

      const dayEntries = entriesByDate[iso] || [];
      const dayItems = calendarDayItems(dayEntries);
      if (dayItems.length) {
        const doneCount = dayItems.filter((it) => it.done).length;
        const counter = document.createElement("span");
        counter.className = "calendar-day-counter" + (doneCount === dayItems.length ? " all-done" : "");
        counter.textContent = `✓${doneCount}`;
        const failedCount = dayItems.filter((it) => it.failed).length;
        counter.title = `${doneCount} of ${dayItems.length} done` + (failedCount ? `, ${failedCount} failed` : "");
        dayHead.appendChild(counter);
      }

      cell.appendChild(dayHead);

      const tasksWrap = document.createElement("div");
      tasksWrap.className = "calendar-day-tasks";
      tasksWrap.style.fontSize = calendarBoxFontSize(dayItems.length);
      dayItems.forEach((it) => {
        const box = document.createElement("span");
        box.className = "calendar-task-box" + (it.done ? " done" : "") + (it.failed ? " failed" : "") + (it.kind === "subtask" ? " calendar-subtask-box" : "");
        box.textContent = it.done ? "☑" : (it.failed ? "☒" : "☐");
        box.title = it.label || "Untitled task";
        tasksWrap.appendChild(box);
      });
      cell.appendChild(tasksWrap);

      cell.addEventListener("click", () => openCalDayModal(iso));
      calGridEl.appendChild(cell);
    }
  }

  calPrevBtn.addEventListener("click", () => { calCursor.setMonth(calCursor.getMonth() - 1); renderCalendar(); });
  calNextBtn.addEventListener("click", () => { calCursor.setMonth(calCursor.getMonth() + 1); renderCalendar(); });
  calTodayBtn.addEventListener("click", () => { calCursor = new Date(); calCursor.setDate(1); renderCalendar(); });
  $("#calendar-back").addEventListener("click", closeCalendarModal);
  $("#calendar-close").addEventListener("click", closeCalendarModal);
  calendarModal.addEventListener("click", (e) => { if (e.target === calendarModal) closeCalendarModal(); });
  $("#btn-calendar").addEventListener("click", openCalendarModal);

  /* ---- Day detail popup — now the same rich, hover-revealed row used
     by the standalone Tasks modal (drag handle, checkbox, "+" to add a
     subtask, ★ priority, delete) rather than the old read-only row, so
     a task can be triaged right from the calendar. The due date itself
     is left off each row — the whole popup is already scoped to one
     day, so repeating it would just be noise. Tasks here still live on
     whichever node owns them (this list is a filtered view across the
     whole tree), so each row keeps a small hover-reveal pill to jump
     to that node, and drag-reorder only takes effect between two tasks
     on the *same* node — a drop across nodes is a no-op. */
  let calDayTaskDragState = null; // { taskId, nodeId, r, c }
  let calDaySubtaskDragState = null; // { taskId, subtaskId } — reorder within one task's own list

  function openCalDayModal(iso) {
    calDayModalDate = iso;
    calDaySortMode = "off";
    renderCalDayModal();
    zoomModalOpen(calDayModalBackdrop, ".day-modal");
    requestAnimationFrame(() => autosizeTextarea(calDayNewInput));
  }
  function closeCalDayModal() {
    calDayModalDate = null;
    zoomModalClose(calDayModalBackdrop);
  }
  function renderCalDayModal() {
    if (!calDayModalDate) return;
    const d = fromISODate(calDayModalDate);
    const today = new Date();
    calDayModalTitle.textContent = isSameDate(d, today)
      ? `Today · ${MONTH_LABELS[d.getMonth()]} ${d.getDate()}`
      : `${MONTH_LABELS[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`;

    let dayEntries = allTasksWithNodes().filter(e => e.task.due === calDayModalDate);
    if (calDaySortMode === "star") {
      dayEntries = dayEntries.slice().sort((a, b) => compareTasksByStarAndColor(a.task, b.task));
    } else if (calDaySortMode === "color") {
      dayEntries = dayEntries.slice().sort((a, b) => taskColorSortIndex(a.task) - taskColorSortIndex(b.task));
    }
    calDayModalList.innerHTML = "";
    dayEntries.forEach(({ task: t, node, r, c }) => {
      calDayModalList.appendChild(buildCalDayTaskRow(t, node, r, c));
      const subProg = taskSubtaskProgress(t);
      const subExpanded = (subProg.total > 0 || subtaskAddOpenFor.has(t.id)) && !collapsedSubtaskIds.has(t.id);
      if (subExpanded) calDayModalList.appendChild(renderCalDaySubtaskPanel(node, t));
    });
    calDayModalEmpty.classList.toggle("hidden", dayEntries.length > 0);
    calDaySortBtn.disabled = dayEntries.length < 2;
    updateCalDaySortBtnLabel();
  }
  function updateCalDaySortBtnLabel() {
    calDaySortBtn.classList.toggle("active", calDaySortMode !== "off");
    calDaySortBtn.textContent = calDaySortMode === "color" ? "🎨 Sort" : "★ Sort";
    calDaySortBtn.title = calDaySortMode === "off"
      ? "Sort by star, then color"
      : calDaySortMode === "star"
        ? "Sorted by star, then color. Click to sort by color instead."
        : "Sorted by color, ignoring star. Click to turn off sorting.";
  }

  function buildCalDayTaskRow(t, node, r, c) {
    const li = document.createElement("li");
    const host = resolveHost(node.id, r, c);
    const subProg = taskSubtaskProgress(t);
    const subExpanded = (subProg.total > 0 || subtaskAddOpenFor.has(t.id)) && !collapsedSubtaskIds.has(t.id);
    li.className = "task-row" + (t.done ? " done" : "") + (t.failed ? " failed" : "") + (getTaskStars(t) > 0 ? " starred" : "") + (subExpanded ? " has-open-subtasks" : "");
    const rowColor = getTaskColor(t);
    li.style.background = taskColorTint(rowColor) || "";

    const sameList = (state) => state && state.nodeId === node.id && (state.r ?? null) === (r ?? null) && (state.c ?? null) === (c ?? null);

    li.addEventListener("dragover", (e) => {
      if (!calDayTaskDragState || calDayTaskDragState.taskId === t.id || !sameList(calDayTaskDragState)) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
      const rect = li.getBoundingClientRect();
      const before = (e.clientY - rect.top) < rect.height / 2;
      li.classList.toggle("drag-over-top", before);
      li.classList.toggle("drag-over-bottom", !before);
    });
    li.addEventListener("dragleave", (e) => {
      if (e.relatedTarget && li.contains(e.relatedTarget)) return;
      li.classList.remove("drag-over-top", "drag-over-bottom");
    });
    li.addEventListener("drop", (e) => {
      if (!calDayTaskDragState || calDayTaskDragState.taskId === t.id || !sameList(calDayTaskDragState)) return;
      e.preventDefault();
      const rect = li.getBoundingClientRect();
      const before = (e.clientY - rect.top) < rect.height / 2;
      li.classList.remove("drag-over-top", "drag-over-bottom");
      reorderCalDayTask(host, calDayTaskDragState.taskId, t.id, before);
    });

    const handle = document.createElement("span");
    handle.className = "task-drag-handle";
    handle.textContent = "⠿";
    handle.title = `Drag to reorder within "${node.text || "(untitled)"}"`;
    handle.draggable = true;
    handle.addEventListener("mousedown", (e) => { e.stopPropagation(); });
    handle.addEventListener("dragstart", (e) => {
      e.stopPropagation();
      if (!requireSignIn()) { e.preventDefault(); return; }
      calDayTaskDragState = { taskId: t.id, nodeId: node.id, r: r ?? null, c: c ?? null };
      e.dataTransfer.effectAllowed = "move";
      try { e.dataTransfer.setData("text/plain", ""); } catch (err) {}
      li.classList.add("task-dragging");
    });
    handle.addEventListener("dragend", () => {
      li.classList.remove("task-dragging");
      calDayTaskDragState = null;
      calDayModalList.querySelectorAll(".task-row").forEach(r => r.classList.remove("drag-over-top", "drag-over-bottom"));
    });

    const cb = document.createElement("input");
    cb.type = "checkbox";
    cb.className = "task-checkbox";
    cb.checked = !!t.done;
    cb.addEventListener("change", () => {
      pushUndo();
      setTaskDone(t, cb.checked);
      persist();
      renderCalDayModal();
      renderCalendar();
    });

    // ✗ — mark this task failed (the opposite of the done checkbox).
    const failBtn = makeTaskFailButton(!!t.failed, () => {
      pushUndo();
      setTaskFailed(t, !t.failed);
      persist();
      renderCalDayModal();
      renderCalendar();
    });

    // Optional color label — same shared popover as the Tasks modal (see
    // getTaskColor/openTaskColorPopover), since both edit the same task
    // objects. Shown as a hollow ring in the current color; the light
    // fill on the whole row is the primary indicator.
    const colorBtn = document.createElement("button");
    colorBtn.type = "button";
    const calTaskColor = getTaskColor(t);
    colorBtn.className = "task-color-dot" + (calTaskColor ? "" : " task-color-dot-empty");
    if (calTaskColor) colorBtn.style.borderColor = calTaskColor;
    colorBtn.title = calTaskColor ? "Change color label" : "Add a color label";
    colorBtn.addEventListener("mousedown", (e) => e.stopPropagation());
    colorBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      openTaskColorPopover(colorBtn, t, renderCalDayModal);
    });

    const text = document.createElement("span");
    text.className = "task-text";
    text.textContent = t.text || "Untitled task";
    if (!t.done && !t.failed) text.style.color = taskFontColor(t);
    text.title = subProg.total ? `${subProg.done} of ${subProg.total} subtasks` : "";

    // ★ priority — same 0/1 star toggle as the Tasks modal.
    const stars = getTaskStars(t);
    const star = document.createElement("button");
    star.type = "button";
    star.className = "task-star" + (stars > 0 ? " starred" : "");
    star.textContent = stars > 0 ? "★" : "☆";
    star.title = stars > 0 ? "Starred — click to clear" : "Star this task for priority";
    star.addEventListener("click", (e) => {
      e.stopPropagation();
      if (blockedByStarCap(host, t)) return;
      const next = stars > 0 ? 0 : 1;
      pushUndo();
      t.stars = next;
      t.starred = t.stars > 0;
      persist();
      renderCalDayModal();
    });

    // Add-subtask icon — same reachable-without-double-click affordance
    // as the Tasks modal row.
    const subtaskBtn = document.createElement("button");
    subtaskBtn.type = "button";
    subtaskBtn.className = "task-subtask-btn" + (subProg.total ? " has-subtasks" : "");
    subtaskBtn.title = subProg.total ? "Add another subtask" : "Add a subtask";
    subtaskBtn.textContent = "+";
    subtaskBtn.addEventListener("mousedown", (e) => e.stopPropagation());
    subtaskBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      collapsedSubtaskIds.delete(t.id);
      subtaskAddOpenFor.add(t.id);
      renderCalDayModal();
    });

    const del = document.createElement("button");
    del.type = "button";
    del.className = "task-delete";
    del.title = "Delete task";
    del.textContent = "×";
    del.addEventListener("click", (e) => {
      e.stopPropagation();
      if (!requireSignIn()) return;
      if (!confirm(`Delete the task "${t.text || "Untitled task"}"?`)) return;
      pushUndo();
      host.tasks = getNodeTasks(host).filter(x => x !== t);
      persist();
      renderCalDayModal();
      renderCalendar();
    });

    // Which node this task lives on — a small hover-reveal pill (rather
    // than always-on) so the row itself stays a clean, flat to-do line.
    const nodeBtn = document.createElement("button");
    nodeBtn.type = "button";
    nodeBtn.className = "task-source-node";
    nodeBtn.title = "Jump to this node on the canvas";
    nodeBtn.textContent = node.text || "(untitled)";
    nodeBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      closeCalDayModal();
      closeCalendarModal();
      focusNodeInCanvas(node.id);
    });

    li.title = subExpanded
      ? "Double-click to hide subtasks"
      : (subProg.total ? `${subProg.done} of ${subProg.total} subtasks — double-click to view` : "Double-click to add subtasks");
    li.addEventListener("dblclick", (e) => {
      if (e.target.closest(".task-checkbox, .task-fail-btn, .task-star, .task-color-dot, .task-delete, .task-drag-handle, .task-source-node")) return;
      if (subExpanded) {
        collapsedSubtaskIds.add(t.id);
      } else {
        collapsedSubtaskIds.delete(t.id);
        if (!subProg.total) subtaskAddOpenFor.add(t.id);
      }
      renderCalDayModal();
    });

    li.appendChild(handle);
    li.appendChild(cb);
    li.appendChild(failBtn);
    li.appendChild(text);
    li.appendChild(subtaskBtn);
    li.appendChild(star);
    li.appendChild(colorBtn);
    li.appendChild(del);
    li.appendChild(nodeBtn);
    return li;
  }

  function reorderCalDayTask(host, sourceTaskId, targetTaskId, before) {
    if (sourceTaskId === targetTaskId) return;
    const tasks = getNodeTasks(host).slice();
    const fromIdx = tasks.findIndex(x => x.id === sourceTaskId);
    if (fromIdx === -1) return;
    const [moved] = tasks.splice(fromIdx, 1);
    const toIdx = tasks.findIndex(x => x.id === targetTaskId);
    pushUndo();
    if (toIdx === -1) tasks.push(moved);
    else tasks.splice(before ? toIdx : toIdx + 1, 0, moved);
    host.tasks = tasks;
    persist();
    renderCalDayModal();
  }

  // Builds the same expanded subtask checklist panel as the Tasks
  // modal (checkbox, drag handle, delete, add-subtask input), just
  // re-rendering into the day popup's own list instead.
  function renderCalDaySubtaskPanel(node, t) {
    const wrap = document.createElement("li");
    wrap.className = "subtask-panel";
    // Same sync as renderSubtaskPanel: match the task row's own color
    // tint instead of the flat default panel background.
    wrap.style.background = taskColorTint(getTaskColor(t)) || "";

    const list = document.createElement("ul");
    list.className = "subtask-list";

    getTaskSubtasks(t).forEach((s) => {
      const row = document.createElement("li");
      row.className = "subtask-row" + (s.done ? " done" : "") + (s.failed ? " failed" : "");

      row.addEventListener("dragover", (e) => {
        if (!calDaySubtaskDragState || calDaySubtaskDragState.taskId !== t.id || calDaySubtaskDragState.subtaskId === s.id) return;
        e.preventDefault();
        e.stopPropagation();
        e.dataTransfer.dropEffect = "move";
        const rect = row.getBoundingClientRect();
        const before = (e.clientX - rect.left) < rect.width / 2;
        row.classList.toggle("drag-over-top", before);
        row.classList.toggle("drag-over-bottom", !before);
      });
      row.addEventListener("dragleave", (e) => {
        if (e.relatedTarget && row.contains(e.relatedTarget)) return;
        row.classList.remove("drag-over-top", "drag-over-bottom");
      });
      row.addEventListener("drop", (e) => {
        if (!calDaySubtaskDragState || calDaySubtaskDragState.taskId !== t.id || calDaySubtaskDragState.subtaskId === s.id) return;
        e.preventDefault();
        e.stopPropagation();
        const rect = row.getBoundingClientRect();
        const before = (e.clientX - rect.left) < rect.width / 2;
        row.classList.remove("drag-over-top", "drag-over-bottom");
        moveCalDaySubtask(t, calDaySubtaskDragState.subtaskId, s.id, before);
      });

      // The whole pill is the drag handle — grab it anywhere to reorder
      // (turned off while its text is being edited, so text can be selected).
      row.draggable = true;
      row.addEventListener("dragstart", (e) => {
        e.stopPropagation();
        if (!requireSignIn()) { e.preventDefault(); return; }
        calDaySubtaskDragState = { taskId: t.id, subtaskId: s.id };
        e.dataTransfer.effectAllowed = "move";
        try { e.dataTransfer.setData("text/plain", ""); } catch (err) {}
        row.classList.add("task-dragging");
      });
      row.addEventListener("dragend", () => {
        row.classList.remove("task-dragging");
        calDaySubtaskDragState = null;
        calDayModalList.querySelectorAll(".subtask-row").forEach(r => r.classList.remove("drag-over-top", "drag-over-bottom"));
      });

      const stext = document.createElement("span");
      stext.className = "subtask-text";
      stext.contentEditable = "false";
      stext.spellcheck = false;
      stext.textContent = s.text;
      if (!s.done && !s.failed) stext.style.color = taskFontColor(t);
      // The pill ellipsizes long text, so the title tooltip is the only
      // way to read it in full without double-clicking into edit mode.
      stext.title = s.text;

      // No more checkbox — a single click anywhere on the pill (other
      // than its note icon, or while its text is
      // mid-edit) toggles done. A short timer tells a single click apart
      // from the first half of a double-click, which opens text editing
      // instead (see the dblclick handler right below).
      let subtaskClickTimer = null;
      row.addEventListener("click", (e) => {
        if (row.__subtaskLongPressConsumed) {
          e.preventDefault();
          e.stopPropagation();
          row.__subtaskLongPressConsumed = false;
          if (subtaskClickTimer) { clearTimeout(subtaskClickTimer); subtaskClickTimer = null; }
          return;
        }
        if (stext.contentEditable === "true") return;
        if (subtaskClickTimer) { clearTimeout(subtaskClickTimer); subtaskClickTimer = null; return; }
        subtaskClickTimer = setTimeout(() => {
          subtaskClickTimer = null;
          pushUndo();
          setSubtaskDone(t, s, !s.done);
          persist();
          renderCalDayModal();
          renderCalendar();
        }, 220);
      });

      stext.addEventListener("dblclick", (e) => {
        e.preventDefault();
        row.draggable = false;
        stext.contentEditable = "true";
        stext.focus();
        const sel = window.getSelection();
        const range = document.createRange();
        range.selectNodeContents(stext);
        sel.removeAllRanges();
        sel.addRange(range);
      });
      stext.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Enter") { e.preventDefault(); stext.blur(); }
        else if (e.key === "Escape") { e.preventDefault(); stext.textContent = s.text; stext.blur(); }
      });
      stext.addEventListener("blur", () => {
        const v = stext.textContent.trim();
        if (v && v !== s.text) {
          pushUndo();
          s.text = v;
          persist();
        } else {
          stext.textContent = s.text;
        }
        stext.title = s.text;
        stext.contentEditable = "false";
        row.draggable = true;
      });

      row.addEventListener("contextmenu", (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (row.__subtaskLongPressConsumed) return;
        openSubtaskContextMenu(e.clientX, e.clientY, t, s, () => { renderCalDayModal(); renderCalendar(); });
      });
      installSubtaskLongPress(row, (x, y) => {
        openSubtaskContextMenu(x, y, t, s, () => { renderCalDayModal(); renderCalendar(); });
      });

      // No inline ✗ button on subtask pills — "Mark failed" / "Clear failed"
      // lives only in the pill's right-click menu (openSubtaskContextMenu).
      row.appendChild(stext);
      list.appendChild(row);
    });

    // "+" trigger for adding another subtask now lives at the end of
    // this task's own subtask list (it used to sit on the main task
    // row) — hidden while the add-input below is already open.
    if (!subtaskAddOpenFor.has(t.id)) {
      const addTriggerLi = document.createElement("li");
      addTriggerLi.className = "subtask-add-trigger";
      const addTriggerBtn = document.createElement("button");
      addTriggerBtn.type = "button";
      addTriggerBtn.className = "subtask-add-btn";
      addTriggerBtn.title = "Add a subtask";
      addTriggerBtn.textContent = "+";
      addTriggerBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        subtaskAddOpenFor.add(t.id);
        renderCalDayModal();
      });
      addTriggerLi.appendChild(addTriggerBtn);
      list.appendChild(addTriggerLi);
    }

    enhanceSubtaskList(list, t, () => renderCalDayModal());
    wrap.appendChild(list);

    if (subtaskAddOpenFor.has(t.id)) {
      const addRow = document.createElement("div");
      addRow.className = "subtask-add-row";

      const addInput = document.createElement("textarea");
      addInput.rows = 1;
      addInput.className = "subtask-new-input autosize-input";
      addInput.placeholder = "Add a subtask and press Enter…";
      addInput.spellcheck = false;
      addInput.dataset.taskId = t.id;
      addInput.addEventListener("click", (e) => e.stopPropagation());
      addInput.addEventListener("input", () => autosizeTextarea(addInput));
      addInput.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Enter" && !e.shiftKey) {
          e.preventDefault();
          const v = addInput.value.trim();
          if (!v) return;
          pushUndo();
          if (!Array.isArray(t.subtasks)) t.subtasks = [];
          t.subtasks.push({ id: uid(), text: v, done: false });
          t.done = false;
          t.failed = false;
          persist();
          renderCalDayModal();
          requestAnimationFrame(() => {
            const el = calDayModalList.querySelector(`.subtask-new-input[data-task-id="${t.id}"]`);
            if (el) el.focus();
          });
        } else if (e.key === "Escape") {
          e.preventDefault();
          addInput.blur();
        }
      });
      addInput.addEventListener("blur", () => {
        if (!addInput.value.trim()) {
          subtaskAddOpenFor.delete(t.id);
          renderCalDayModal();
        }
      });
      addRow.appendChild(addInput);
      wrap.appendChild(addRow);
      requestAnimationFrame(() => addInput.focus());
    }

    return wrap;
  }

  function moveCalDaySubtask(t, sourceSubtaskId, targetSubtaskId, before) {
    if (sourceSubtaskId === targetSubtaskId) return;
    const subs = getTaskSubtasks(t).slice();
    const fromIdx = subs.findIndex(x => x.id === sourceSubtaskId);
    if (fromIdx === -1) return;
    const [moved] = subs.splice(fromIdx, 1);
    const toIdx = targetSubtaskId ? subs.findIndex(x => x.id === targetSubtaskId) : -1;
    pushUndo();
    if (toIdx === -1) subs.push(moved);
    else subs.splice(before ? toIdx : toIdx + 1, 0, moved);
    t.subtasks = subs;
    persist();
    renderCalDayModal();
  }

  // "Add a task and press Enter…" — a quick-add for this day. New tasks
  // don't have a node to live on yet in this cross-node view, so they're
  // filed on the current map's root node (same place "drag markers onto
  // another node" can move them out of afterward) with their due date
  // stamped to the day the popup is open on.
  function addTaskFromCalDayModal() {
    if (!calDayModalDate || !state.current) return;
    if (!requireSignIn()) return;
    const val = calDayNewInput.value.trim();
    if (!val) return;
    const node = state.current.root;
    pushUndo();
    if (!Array.isArray(node.tasks)) node.tasks = [];
    node.tasks = node.tasks.concat([{ id: uid(), text: val, done: false, stars: 0, due: calDayModalDate }]);
    calDayNewInput.value = "";
    autosizeTextarea(calDayNewInput);
    persist();
    renderCalDayModal();
    renderCalendar();
  }
  calDayNewInput.addEventListener("input", () => autosizeTextarea(calDayNewInput));
  calDayNewInput.addEventListener("keydown", (e) => {
    e.stopPropagation();
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); addTaskFromCalDayModal(); }
    else if (e.key === "Escape") { e.preventDefault(); calDayNewInput.blur(); }
  });
  calDaySortBtn.addEventListener("click", () => {
    calDaySortMode = calDaySortMode === "off" ? "star" : calDaySortMode === "star" ? "color" : "off";
    renderCalDayModal();
  });

  $("#cal-day-modal-close-btn").addEventListener("click", closeCalDayModal);
  calDayModalBackdrop.addEventListener("click", (e) => { if (e.target === calDayModalBackdrop) closeCalDayModal(); });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && calDayModalDate && document.activeElement !== calDayNewInput) closeCalDayModal();
  });

  /* ---------------- affirmation typing game ---------------- */
  // A lightweight typing-practice task: pick a random line, and the task
  // is complete once it's been retyped (matching exactly) AFFIRMATION_TARGET
  // times. Progress (t.count) lives on the task itself, same as `done` on
  // a regular task, so it's saved with the map and survives reloads.

  const affirmationModal = $("#affirmation-modal");
  const affirmationQuoteEl = $("#affirmation-quote");
  const affirmationInput = $("#affirmation-input");
  const affirmationProgressBar = $("#affirmation-progress-bar");
  const affirmationProgressLabel = $("#affirmation-progress-label");
  const affirmationFeedback = $("#affirmation-feedback");
  let affirmationTarget = null; // {nodeId, r, c} — r/c omitted for a node-level game, both given for a table-cell game

  function getAffirmationHost() {
    return affirmationTarget ? resolveHost(affirmationTarget.nodeId, affirmationTarget.r, affirmationTarget.c) : null;
  }

  // Opens the game for a node (r/c omitted) or one of its table cells
  // (r/c given), from the right-click / "+" menu. Resumes an in-progress
  // round if one exists on the target already; otherwise picks a fresh
  // random line and starts a new one.
  function openAffirmationGame(nodeId, r, c) {
    const host = resolveHost(nodeId, r, c);
    if (!host) return;
    if (!affirmationQuotesList.length) {
      openAffirmationQuotesModal();
      return;
    }
    if (!host.affirmation) host.affirmation = { wins: 0, quote: null, count: 0, target: affirmationTargetForRound(0) };
    if (!host.affirmation.quote) {
      host.affirmation.quote = affirmationQuotesList[Math.floor(Math.random() * affirmationQuotesList.length)];
      host.affirmation.count = 0;
      host.affirmation.target = affirmationTargetForRound(host.affirmation.wins || 0);
      persist();
    }
    affirmationTarget = { nodeId, r, c };
    affirmationFeedback.textContent = "";
    affirmationFeedback.className = "affirmation-feedback";
    renderAffirmationModal();
    zoomModalOpen(affirmationModal);
    requestAnimationFrame(() => affirmationInput.focus());
  }

  function closeAffirmationGame() {
    affirmationInput.value = "";
    affirmationInput.classList.remove("shake");
    affirmationTarget = null;
    renderAll();
    zoomModalClose(affirmationModal);
  }

  function renderAffirmationModal() {
    const host = getAffirmationHost();
    const a = getNodeAffirmation(host);
    if (!a) { closeAffirmationGame(); return; }
    affirmationQuoteEl.textContent = a.quote || "";
    const target = a.target || AFFIRMATION_TARGET;
    const count = Math.min(a.count || 0, target);
    affirmationInput.value = "";
    affirmationInput.disabled = false;
    affirmationInput.placeholder = "Type the line above and press Enter…";
    renderAffirmationProgress(a, "");
  }

  // Single combined progress bar: each full rep fills 1/target of the
  // bar, and the rep currently being typed fills its own slice live,
  // letter by letter, as leading characters match — so the bar visibly
  // ticks up on every correct keystroke, not just on a full match.
  function renderAffirmationProgress(a, typedRaw) {
    const target = a.target || AFFIRMATION_TARGET;
    const count = Math.min(a.count || 0, target);
    const quote = a.quote || "";
    const chars = Array.from(stripAffirmationCommas(quote).trim());
    const typed = Array.from(stripAffirmationCommas(typedRaw).replace(/^\s+/, ""));
    let correctCount = 0;
    let hitMismatch = false;
    for (let i = 0; i < typed.length && !hitMismatch; i++) {
      if (i < chars.length && typed[i].toLocaleLowerCase("vi") === chars[i].toLocaleLowerCase("vi")) {
        correctCount++;
      } else {
        hitMismatch = true;
      }
    }
    const lineFraction = chars.length ? correctCount / chars.length : 0;
    const combined = count >= target ? 1 : (count + lineFraction) / target;
    affirmationProgressBar.style.width = Math.round(combined * 100) + "%";
    affirmationProgressBar.classList.toggle("done", count >= target);
    affirmationProgressBar.classList.toggle("wrong", hitMismatch && count < target);
    affirmationProgressLabel.textContent = `${count} / ${target}`;
  }

  function submitAffirmationAttempt() {
    const host = getAffirmationHost();
    const a = getNodeAffirmation(host);
    if (!a) return;
    const target = a.target || AFFIRMATION_TARGET;
    if ((a.count || 0) >= target) return;
    const typed = normalizeAffirmationText(affirmationInput.value);
    if (!typed) return;
    const expected = normalizeAffirmationText(a.quote);
    if (typed === expected) {
      pushUndo();
      a.count = (a.count || 0) + 1;
      const justWon = a.count >= target;
      if (justWon) {
        a.wins = (a.wins || 0) + 1;
        // Round complete — clear it so the next open starts a fresh line.
        a.quote = null;
        a.count = 0;
      }
      persist();
      affirmationFeedback.textContent = justWon ? "🎉 All done!" : "";
      affirmationFeedback.className = "affirmation-feedback" + (justWon ? " ok" : "");
      if (justWon) {
        renderAll();
        requestAnimationFrame(() => affirmationInput.blur());
        affirmationInput.disabled = true;
        affirmationInput.placeholder = "All done — great job!";
      } else {
        renderAffirmationModal();
      }
    } else {
      affirmationInput.classList.remove("shake");
      void affirmationInput.offsetWidth; // restart the CSS animation on repeat misses
      affirmationInput.classList.add("shake");
      affirmationFeedback.textContent = "Not quite — try again";
      affirmationFeedback.className = "affirmation-feedback bad";
    }
  }

  affirmationInput.addEventListener("input", () => {
    const a = getNodeAffirmation(getAffirmationHost());
    if (!a) return;
    renderAffirmationProgress(a, affirmationInput.value);
  });
  affirmationInput.addEventListener("keydown", (e) => {
    e.stopPropagation();
    if (e.key === "Enter") { e.preventDefault(); submitAffirmationAttempt(); }
    else if (e.key === "Escape") { e.preventDefault(); closeAffirmationGame(); }
  });
  $("#affirmation-back").addEventListener("click", closeAffirmationGame);
  affirmationModal.addEventListener("click", (e) => { if (e.target === affirmationModal) closeAffirmationGame(); });

  /* ---------------- node timer ("time played") ---------------- */
  // A per-node countdown timer. Start it and it ticks down like a normal
  // countdown (pause/resume, "+1m" to stack on more time, chimes when it
  // hits zero) — but the number that actually matters is the *total*
  // stored on the node (node.timePlayedSec): every second the countdown
  // is genuinely running (not paused) adds one second to that total, so
  // it reflects time actually played/worked, not just time scheduled.
  // That total is shown live both here and as the small "⏱ 45m" badge on
  // the node itself (see renderNode), and is saved with the map like
  // everything else.
  const NODE_TIMER_DEFAULT_SEC = 1 * 60; // default countdown length when starting fresh
  const NODE_TIMER_EXTEND_SEC = 60; // added per "+1m" click while running

  const timerModal = $("#timer-modal");
  const timerNodeLabel = $("#timer-node-label");
  const timerTotalDisplay = $("#timer-total-display");
  const timerResetBtn = $("#timer-reset-btn");
  const timerStartRow = $("#timer-start-row");
  const timerStartBtn = $("#timer-start-btn");
  const timerCountdownRow = $("#timer-countdown-row");
  const timerCountdownDisplay = $("#timer-countdown-display");
  const timerPauseBtn = $("#timer-pause-btn");
  const timerStopBtn = $("#timer-stop-btn");
  const timerExtendBtn = $("#timer-extend-btn");
  const timerDoneLabel = $("#timer-done-label");
  let timerEditingId = null; // {nodeId, r, c} — r/c omitted for a node-level timer, both given for a table-cell timer

  // Only one countdown can run at a time (mirrors the per-task focus
  // timer) but, like that one, it keeps running via setInterval even if
  // this modal is closed or a different node/map is opened, so switching
  // away doesn't quietly cancel a session that's in progress.
  let nodeTimer = null; // { target: {nodeId, r, c}, remaining, duration, paused, intervalId }
  let nodeTimerJustCompleted = null; // {nodeId, r, c}, shown briefly in the modal after a session finishes

  function getNodeTimePlayed(node) {
    return (node && typeof node.timePlayedSec === "number" && node.timePlayedSec > 0) ? node.timePlayedSec : 0;
  }

  // "45m", "1h", "1h 20m" — always whole minutes, so no seconds ever show.
  function formatTimePlayed(totalSeconds) {
    const s = Math.max(0, Math.round(totalSeconds || 0));
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    if (h > 0) return m > 0 ? `${h}h ${m}m` : `${h}h`;
    return `${m}m`;
  }

  function openTimerModal(nodeId, r, c) {
    const host = resolveHost(nodeId, r, c);
    if (!host) return;
    commitEditIfActive();
    closeContextMenu();
    timerEditingId = { nodeId, r, c };
    renderTimerModal();
    zoomModalOpen(timerModal);
  }

  function closeTimerModal() {
    timerEditingId = null;
    renderAll();
    zoomModalClose(timerModal);
  }

  function renderTimerModal() {
    const t = timerEditingId;
    const host = t ? resolveHost(t.nodeId, t.r, t.c) : null;
    if (!host) { closeTimerModal(); return; }
    const node = findNode(t.nodeId);
    const cellText = (t.r != null && node && node.table && node.table.cells[t.r]) ? node.table.cells[t.r][t.c] : null;
    timerNodeLabel.textContent = t.r == null ? ((node && node.text) || "(untitled)") : (cellText || `Cell (row ${t.r + 1}, col ${t.c + 1})`);
    const total = getNodeTimePlayed(host);
    timerTotalDisplay.textContent = formatTimePlayed(total);
    timerResetBtn.style.visibility = total ? "visible" : "hidden";

    const runningHere = nodeTimer && sameTarget(nodeTimer.target, t);
    timerCountdownRow.classList.toggle("hidden", !runningHere);
    const justCompletedHere = nodeTimerJustCompleted && sameTarget(nodeTimerJustCompleted, t);
    timerDoneLabel.classList.toggle("hidden", !justCompletedHere);
    timerStartRow.style.display = (runningHere || justCompletedHere) ? "none" : "flex";

    if (runningHere) {
      timerCountdownDisplay.textContent = formatFocusTime(nodeTimer.remaining);
      timerCountdownDisplay.classList.toggle("paused", nodeTimer.paused);
      timerPauseBtn.textContent = nodeTimer.paused ? "▶" : "⏸";
      timerPauseBtn.title = nodeTimer.paused ? "Resume" : "Pause";
    }
  }

  // Cheap live update used on every tick: pushes the new total straight
  // into the node's (or table cell's) badge on the canvas — and this
  // modal, if open for the same target — without a full renderAll() — a
  // per-second re-layout of the whole map would be wasteful, especially
  // on a large mind map.
  function updateNodeTimerLiveUI(target) {
    if (!target) return;
    const host = resolveHost(target.nodeId, target.r, target.c);
    if (!host) return;
    const total = getNodeTimePlayed(host);
    const badgeLabel = target.r == null
      ? nodesLayer.querySelector(`.node[data-id="${target.nodeId}"] .node-timer-badge span`)
      : nodesLayer.querySelector(`.node[data-id="${target.nodeId}"] .node-table-cell[data-r="${target.r}"][data-c="${target.c}"] .node-table-cell-timer span`);
    if (badgeLabel) {
      badgeLabel.textContent = formatTimePlayed(total);
      badgeLabel.parentElement.title = `${formatTimePlayed(total)} logged — click to add more`;
    } else if (total && target.nodeId !== state.editingId && nodeTimer && sameTarget(nodeTimer.target, target) && !nodeTimer.badgeRenderAttempted) {
      // The badge doesn't exist yet in the DOM — either this target had
      // no logged time before the countdown started, or it isn't
      // currently rendered at all (e.g. inside a collapsed branch, or
      // off in a part of the tree not mounted). A one-time full render
      // will create it if it's visible; badgeRenderAttempted makes sure
      // this only ever fires once per session instead of on every tick
      // forever when the target simply isn't on screen (a collapsed
      // branch, for instance, never gets a DOM node to find, and
      // calling renderAll() every second was crashing the tab).
      nodeTimer.badgeRenderAttempted = true;
      renderAll();
    }
    if (timerEditingId && sameTarget(timerEditingId, target) && !timerModal.classList.contains("hidden")) {
      timerTotalDisplay.textContent = formatTimePlayed(total);
      timerResetBtn.style.visibility = total ? "visible" : "hidden";
    }
  }

  function startNodeTimer(target, durationSec = NODE_TIMER_DEFAULT_SEC) {
    const host = resolveHost(target.nodeId, target.r, target.c);
    if (!host) return;
    stopNodeTimerInterval();
    stopFocusChime();
    nodeTimerJustCompleted = null;
    pushUndo();
    nodeTimer = {
      target,
      remaining: durationSec,
      duration: durationSec,
      paused: false,
      ticksSincePersist: 0,
      intervalId: setInterval(nodeTimerTick, 1000),
    };
    renderTimerModal();
  }

  // How often the countdown writes its running total to disk while it's
  // actually ticking. This is a *cheap* in-memory update every second
  // (host.timePlayedSec++), but persist() triggers this app's full save
  // path — which re-embeds every photo's bytes into JSON for the folder
  // mirror/Drive upload — so calling it every single second would re-run
  // that heavy work once a second for as long as the timer runs and can
  // exhaust memory on a photo-heavy map. Saving every 10s instead (plus
  // on pause/stop/complete, and the existing flushPersist safety net on
  // tab-hide/close) keeps at most ~10s of countdown time at risk of loss
  // without hammering the save path.
  const NODE_TIMER_PERSIST_EVERY_SEC = 10;

  function nodeTimerTick() {
    if (!nodeTimer || nodeTimer.paused) return;
    nodeTimer.remaining--;
    const host = resolveHost(nodeTimer.target.nodeId, nodeTimer.target.r, nodeTimer.target.c);
    if (host) {
      host.timePlayedSec = getNodeTimePlayed(host) + 1;
      unsavedEdits = true;
      nodeTimer.ticksSincePersist++;
      if (nodeTimer.ticksSincePersist >= NODE_TIMER_PERSIST_EVERY_SEC) {
        nodeTimer.ticksSincePersist = 0;
        persist();
      }
      updateNodeTimerLiveUI(nodeTimer.target);
    }
    if (nodeTimer.remaining <= 0) {
      nodeTimerComplete();
      return;
    }
    if (timerEditingId && sameTarget(timerEditingId, nodeTimer.target)) renderTimerModal();
  }

  function toggleNodeTimerPause() {
    if (!nodeTimer) return;
    nodeTimer.paused = !nodeTimer.paused;
    if (nodeTimer.paused) {
      nodeTimer.ticksSincePersist = 0;
      persist();
    }
    renderTimerModal();
  }

  function extendNodeTimer(seconds) {
    if (!nodeTimer) return;
    nodeTimer.remaining += seconds;
    nodeTimer.duration += seconds;
    renderTimerModal();
  }

  // Clears the interval only — used internally before starting a new
  // countdown, without touching the "just completed" flash state.
  function stopNodeTimerInterval() {
    if (nodeTimer && nodeTimer.intervalId) clearInterval(nodeTimer.intervalId);
    nodeTimer = null;
  }

  function stopNodeTimer() {
    const prev = nodeTimer;
    stopNodeTimerInterval();
    if (prev) {
      persist();
      updateNodeTimerLiveUI(prev.target);
      if (timerEditingId && sameTarget(timerEditingId, prev.target)) renderTimerModal();
    }
  }

  function nodeTimerComplete() {
    const finished = nodeTimer;
    stopNodeTimerInterval();
    if (!finished) return;
    persist();
    updateNodeTimerLiveUI(finished.target);
    startFocusChime();
    nodeTimerJustCompleted = finished.target;
    if (timerEditingId && sameTarget(timerEditingId, finished.target)) renderTimerModal();
    setTimeout(() => {
      if (nodeTimerJustCompleted && sameTarget(nodeTimerJustCompleted, finished.target)) {
        nodeTimerJustCompleted = null;
        if (timerEditingId && sameTarget(timerEditingId, finished.target)) renderTimerModal();
      }
    }, 4000);
  }

  timerStartBtn.addEventListener("click", () => {
    if (!timerEditingId) return;
    startNodeTimer(timerEditingId);
  });
  timerPauseBtn.addEventListener("click", (e) => { e.stopPropagation(); toggleNodeTimerPause(); });
  timerStopBtn.addEventListener("click", (e) => { e.stopPropagation(); stopNodeTimer(); });
  timerExtendBtn.addEventListener("click", (e) => { e.stopPropagation(); extendNodeTimer(NODE_TIMER_EXTEND_SEC); });

  timerResetBtn.addEventListener("click", () => {
    const t = timerEditingId;
    if (!t) return;
    const host = resolveHost(t.nodeId, t.r, t.c);
    if (!host || !getNodeTimePlayed(host)) return;
    pushUndo();
    host.timePlayedSec = 0;
    persist();
    renderTimerModal();
    updateNodeTimerLiveUI(t);
  });

  $("#timer-back").addEventListener("click", closeTimerModal);
  timerModal.addEventListener("click", (e) => { if (e.target === timerModal) closeTimerModal(); });
  document.addEventListener("keydown", (e) => {
    if (timerModal.classList.contains("hidden")) return;
    if (e.key === "Escape") closeTimerModal();
  });

  /* ---------------- node brainstorm scratchpad ---------------- */
  // A per-node (or per-cell) free-typed note scratchpad — reached from
  // the same right-click menu as the Timer and Affirmation game, but far
  // simpler than either: a contenteditable scratchpad (host.brainstorm =
  // {text, html}) that autosaves as you type, no quote to match and
  // nothing to start or stop. Every 2 non-empty lines written is worth 1
  // point toward the task score (see nodeTaskProgress/brainstormPoints
  // above) and shows as a small brain badge on the node/cell itself
  // (see renderNode). Uses the same host-based {nodeId, r, c} target
  // pattern as the timer above (see resolveHost).
  //
  // `text` is the plain-text version (one line per paragraph, via
  // .innerText) that brainstormLineCount/brainstormPoints score against;
  // `html` is the same content with each line's own color baked in (see
  // brainstormAutoColorLines below), reusing the exact same per-paragraph
  // cycling palette as the node note editor (see noteColorForOrdinal) so
  // separate lines are just as easy to tell apart here as they are there.
  const brainstormModal = $("#brainstorm-modal");
  const brainstormNodeLabel = $("#brainstorm-node-label");
  const brainstormTextarea = $("#brainstorm-textarea");
  const brainstormProgressLabel = $("#brainstorm-progress-label");
  const brainstormClearBtn = $("#brainstorm-clear-btn");
  const brainstormCard = $(".brainstorm-modal-card");
  const brainstormResizeHandle = $("#brainstorm-resize-handle");
  let brainstormEditingId = null; // {nodeId, r, c} — r/c omitted for a node-level scratchpad, both given for a table-cell one
  let brainstormSaveTimer = null;
  let brainstormIsResizing = false;

  // Same custom drag-to-resize grip as the note editor (see
  // setupNoteResize) — kept as its own copy rather than a shared function
  // since the two modals' card/handle elements differ, but the behavior
  // (and min/max bounds) match exactly for a consistent feel.
  (function setupBrainstormResize() {
    let startX, startY, startW, startH;
    function onMove(e) {
      const dw = e.clientX - startX;
      const dh = e.clientY - startY;
      const maxW = window.innerWidth * 0.96;
      const maxH = window.innerHeight * 0.92;
      brainstormCard.style.width = clamp(startW + dw, 420, maxW) + "px";
      brainstormCard.style.height = clamp(startH + dh, 320, maxH) + "px";
    }
    function onUp() {
      document.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseup", onUp);
      document.removeEventListener("pointermove", onMove);
      document.removeEventListener("pointerup", onUp);
      document.body.style.userSelect = "";
      setTimeout(() => { brainstormIsResizing = false; }, 0);
    }
    function onResizeStart(e) {
      e.preventDefault();
      e.stopPropagation();
      brainstormIsResizing = true;
      startX = e.clientX;
      startY = e.clientY;
      const rect = brainstormCard.getBoundingClientRect();
      startW = rect.width;
      startH = rect.height;
      document.body.style.userSelect = "none";
      document.addEventListener("mousemove", onMove);
      document.addEventListener("mouseup", onUp);
      document.addEventListener("pointermove", onMove);
      document.addEventListener("pointerup", onUp);
    }
    brainstormResizeHandle.addEventListener("mousedown", onResizeStart);
    brainstormResizeHandle.addEventListener("pointerdown", (e) => {
      if (e.pointerType === "mouse") return;
      onResizeStart(e);
    });
  })();

  // Gives every plain line its own color, cycling through the same
  // palette as the note editor's numbered-list lines (see
  // noteAutoColorParagraphs, which this mirrors exactly) — only touches
  // lines that don't have a color yet, so existing lines keep the color
  // they were given rather than shifting as new ones are added below
  // them. Numbered/checklist lines keep their own ordinal-based color
  // (see brainstormSetOrderedLineColor) and image lines have no text to
  // color, so both are skipped here instead of getting a paragraph color
  // too.
  function brainstormAutoColorLines(container = brainstormTextarea) {
    let idx = 0;
    Array.from(container.children).forEach(el => {
      const text = el.textContent || "";
      if (/^(\d+\.\s|[☐☑])\s?/.test(text)) return;
      if (el.querySelector && el.querySelector("img")) return;
      if (el.classList && el.classList.contains("note-mood")) return; // the Mood To Day block has its own colors
      if (!el.style.color) el.style.color = noteColorForOrdinal(idx + 1);
      idx++;
    });
  }

  // ---- "🗂 Add card" — brainstorm version ----
  // Same card mechanics as the note editor's noteAddCard/refreshDRCCards
  // (decorateDRCCards and bindDRCCardColorDot are shared, generic helpers
  // that already take any container as their root); duplicated against
  // this editor's own undo/current-line/autosave helpers for the same
  // reason the mood block is. Brainstorm has no "DRC" template, so cards
  // here only ever come from this button — refreshBrainstormCards' mode
  // is "cards" or nothing, never "note".
  function refreshBrainstormCards() {
    const mode = brainstormTextarea.querySelector(":scope > [data-card]") ? "cards" : null;
    decorateDRCCards(brainstormTextarea, mode);
  }
  function brainstormAddCard() {
    brainstormPushUndo();
    const count = brainstormTextarea.querySelectorAll(":scope > .drc-card-head, :scope > [data-card]").length;
    const color = DRC_CARD_COLORS[count % DRC_CARD_COLORS.length];
    const sel = window.getSelection();
    let line = (sel.rangeCount && brainstormTextarea.contains(sel.anchorNode)) ? brainstormCurrentLine() : null;
    if (line && line.nodeType !== 1) line = null;
    const isBlank = (el) => !(el.textContent || "").replace(/[\u200b\u00a0]/g, "").trim() && !el.querySelector("img");
    let card;
    if (line && !line.hasAttribute("data-card") && isBlank(line)) {
      card = line;
    } else {
      if (line && line.classList.contains("drc-card-line")) {
        while (!line.classList.contains("drc-card-last") && line.nextElementSibling) line = line.nextElementSibling;
      }
      card = document.createElement("div");
      card.appendChild(document.createElement("br"));
      if (line) line.parentNode.insertBefore(card, line.nextSibling);
      else brainstormTextarea.appendChild(card);
    }
    card.setAttribute("data-card", "1");
    card.setAttribute("data-card-color", color);
    brainstormTextarea.focus();
    const range = document.createRange();
    range.selectNodeContents(card);
    range.collapse(true);
    sel.removeAllRanges();
    sel.addRange(range);
    refreshBrainstormCards();
    scheduleBrainstormAutosave();
  }
  $("#brainstorm-tool-card").addEventListener("mousedown", (e) => {
    e.preventDefault();
    brainstormAddCard();
  });
  // Same recolor ring as the note editor's cards (see the note editor's
  // bindDRCCardColorDot call for the DRC-note version of this comment).
  bindDRCCardColorDot(
    brainstormTextarea,
    () => brainstormTextarea.getAttribute("contenteditable") !== "false" && brainstormTextarea.classList.contains("drc-cards"),
    (head, color) => {
      brainstormPushUndo();
      head.setAttribute("data-card-color", color);
      refreshBrainstormCards();
      scheduleBrainstormAutosave();
    }
  );

  // ---- "😊 Mood To Day" block, brainstorm version ----
  // Same block and behavior as the note editor's (see noteInsertMoodBlock/
  // noteBuildMoodBlock above); duplicated against this editor's own
  // undo/current-line/autosave helpers rather than shared, since the two
  // editors don't share a DOM root.
  function brainstormInsertMoodBlock() {
    brainstormPushUndo();
    const sel = window.getSelection();
    let line = (sel.rangeCount && brainstormTextarea.contains(sel.anchorNode)) ? brainstormCurrentLine() : null;
    if (line && line.nodeType !== 1) line = null;
    const isBlank = (el) => !(el.textContent || "").replace(/[\u200b\u00a0]/g, "").trim() && !el.querySelector("img") && !el.hasAttribute("data-mood-block");
    const block = noteBuildMoodBlock();
    if (line && line.parentNode === brainstormTextarea) {
      if (isBlank(line)) line.replaceWith(block);
      else line.after(block);
    } else {
      brainstormTextarea.appendChild(block);
    }
    let tail = block.nextElementSibling;
    if (!tail || !isBlank(tail)) {
      tail = document.createElement("div");
      tail.appendChild(document.createElement("br"));
      block.after(tail);
    }
    brainstormTextarea.focus();
    const range = document.createRange();
    range.selectNodeContents(tail);
    range.collapse(true);
    sel.removeAllRanges();
    sel.addRange(range);
    refreshBrainstormCards();
    brainstormAutoColorLines();
    scheduleBrainstormAutosave();
  }
  $("#brainstorm-tool-mood").addEventListener("mousedown", (e) => {
    e.preventDefault();
    brainstormInsertMoodBlock();
  });
  brainstormTextarea.addEventListener("click", (e) => {
    const face = e.target && e.target.closest ? e.target.closest(".note-mood-face") : null;
    if (!face || !brainstormTextarea.contains(face)) return;
    if (brainstormTextarea.getAttribute("contenteditable") === "false") return;
    const block = face.closest(".note-mood");
    if (!block) return;
    brainstormPushUndo();
    const wasSelected = face.classList.contains("selected");
    block.querySelectorAll(".note-mood-face").forEach((f) => {
      f.classList.remove("selected");
      f.setAttribute("aria-pressed", "false");
    });
    if (wasSelected) {
      block.removeAttribute("data-mood");
    } else {
      face.classList.add("selected");
      face.setAttribute("aria-pressed", "true");
      block.setAttribute("data-mood", face.dataset.moodValue);
    }
    scheduleBrainstormAutosave();
  });

  // Colors a line based on the number in its own "N. " prefix, or clears
  // the color if the line isn't numbered — same idea as the note
  // editor's noteSetOrderedLineColor.
  function brainstormSetOrderedLineColor(el) {
    if (!el) return;
    const match = (el.textContent || "").match(/^(\d+)\.\s/);
    el.style.color = match ? noteColorForOrdinal(parseInt(match[1], 10)) : "";
  }

  // Re-applies auto ordinal colors across every line, for a brainstorm
  // loaded from storage that has numbered prefixes but no inline color
  // saved yet.
  function brainstormSyncAllOrderedColors(container = brainstormTextarea) {
    Array.from(container.children).forEach(el => {
      if (/^\d+\.\s/.test(el.textContent || "") && !el.style.color) {
        brainstormSetOrderedLineColor(el);
      }
    });
  }

  // Keeps a line's strikethrough in sync with its checklist glyph — same
  // idea as the note editor's noteSyncLineChecked.
  function brainstormSyncLineChecked(el) {
    if (!el) return;
    el.classList.toggle("note-line-checked", /^☑(\s|$)/.test(el.textContent || ""));
  }

  function brainstormSyncAllCheckedLines(container = brainstormTextarea) {
    brainstormSyncLineChecked(container);
    Array.from(container.children).forEach(brainstormSyncLineChecked);
  }

  // Renders host.brainstorm.html if it's already been colored, or builds
  // a fresh one-<div>-per-line version from the plain-text field (same
  // conversion the note editor uses for old plain-text notes — see
  // noteHtmlFromRaw) for a scratchpad that predates this coloring, or was
  // never opened in a browser session yet.
  function getBrainstormHtml(host) {
    const b = getNodeBrainstorm(host);
    if (b && b.html) return b.html;
    return noteHtmlFromRaw(getBrainstormText(host));
  }

  function openBrainstormModal(nodeId, r, c) {
    const host = resolveHost(nodeId, r, c);
    if (!host) return;
    commitEditIfActive();
    closeContextMenu();
    brainstormEditingId = { nodeId, r, c };
    renderBrainstormModal();
    // Same width-reset-on-open behavior as the note editor (see
    // openNoteModal/noteCard.style.width above) — a previous manual
    // resize shouldn't leak its width into the next brainstorm session,
    // though height is deliberately left alone, matching notes.
    brainstormCard.style.width = "";
    zoomModalOpen(brainstormModal);
    requestAnimationFrame(() => brainstormTextarea.focus());
  }

  function closeBrainstormModal() {
    flushBrainstormAutosave();
    brainstormEditingId = null;
    renderAll();
    zoomModalClose(brainstormModal);
  }

  function renderBrainstormModal() {
    const t = brainstormEditingId;
    const host = t ? resolveHost(t.nodeId, t.r, t.c) : null;
    if (!host) { closeBrainstormModal(); return; }
    const node = findNode(t.nodeId);
    const cellText = (t.r != null && node && node.table && node.table.cells[t.r]) ? node.table.cells[t.r][t.c] : null;
    brainstormNodeLabel.textContent = t.r == null ? ((node && node.text) || "(untitled)") : (cellText || `Cell (row ${t.r + 1}, col ${t.c + 1})`);
    brainstormTextarea.innerHTML = getBrainstormHtml(host);
    brainstormSyncAllCheckedLines();
    brainstormSyncAllOrderedColors();
    brainstormAutoColorLines();
    refreshBrainstormCards();
    brainstormResetUndoHistory();
    renderBrainstormProgress(host);
  }

  function renderBrainstormProgress(host) {
    const lines = brainstormLineCount(host);
    const pts = brainstormPoints(host);
    brainstormProgressLabel.textContent = `${lines} line${lines === 1 ? "" : "s"} · ${pts} pt${pts === 1 ? "" : "s"}`;
  }

  // Debounced autosave: fires a short beat after the user stops typing,
  // so the scratchpad saves itself without needing an explicit Save
  // click — same 500ms pattern as the node/task note editor (see
  // scheduleNoteAutosave).
  function scheduleBrainstormAutosave() {
    const t = brainstormEditingId;
    if (!t) return;
    const host = resolveHost(t.nodeId, t.r, t.c);
    if (!host) return;
    brainstormAutoColorLines();
    if (!host.brainstorm) host.brainstorm = { text: "", html: "" };
    host.brainstorm.text = brainstormTextarea.innerText;
    host.brainstorm.html = brainstormTextarea.innerHTML;
    unsavedEdits = true;
    renderBrainstormProgress(host);
    updateBrainstormLiveUI(t);
    clearTimeout(brainstormSaveTimer);
    brainstormSaveTimer = setTimeout(() => { pushUndo(); persist(); }, 500);
  }

  function flushBrainstormAutosave() {
    if (!brainstormSaveTimer) return;
    clearTimeout(brainstormSaveTimer);
    brainstormSaveTimer = null;
    persist();
  }

  // Cheap live update — pushes the new line/point count straight into
  // the node's (or table cell's) badge on the canvas without a full
  // renderAll(), same idea as updateNodeTimerLiveUI above.
  function updateBrainstormLiveUI(target) {
    if (!target) return;
    const host = resolveHost(target.nodeId, target.r, target.c);
    if (!host) return;
    const pts = brainstormPoints(host);
    const badge = target.r == null
      ? nodesLayer.querySelector(`.node[data-id="${target.nodeId}"] .node-brainstorm-marker`)
      : nodesLayer.querySelector(`.node[data-id="${target.nodeId}"] .node-table-cell[data-r="${target.r}"][data-c="${target.c}"] .node-table-cell-brainstorm`);
    if (badge) {
      badge.title = `Brainstorm — ${pts} point${pts === 1 ? "" : "s"} (${brainstormLineCount(host)} lines). Click to keep writing.`;
    } else if (pts > 0 && target.nodeId !== state.editingId) {
      // The badge doesn't exist in the DOM yet (this is the first line
      // pair that's earned a point) — a one-time full render creates it
      // if it's actually visible right now, same fallback
      // updateNodeTimerLiveUI uses above.
      renderAll();
    }
  }

  // ---- Rich-text toolbar (undo/redo, bold, AA, numbered list, checklist,
  // strikethrough, image, color, symbol) — same exact behavior as the
  // node/task note editor's toolbar above, just bound to
  // brainstormTextarea instead of noteTextarea. Kept as its own copy
  // (rather than sharing the note editor's functions directly) since the
  // two editors' DOM elements differ and the note editor's own toolbar
  // listeners are attached via a couple of `document.querySelectorAll`
  // calls that would otherwise also pick up these buttons.
  const BRAINSTORM_UNDO_LIMIT = 100;
  let brainstormUndoStack = [];
  let brainstormRedoStack = [];
  let brainstormLastPushAt = 0;
  const brainstormUndoBtn = $("#brainstorm-tool-undo");
  const brainstormRedoBtn = $("#brainstorm-tool-redo");

  function updateBrainstormUndoButtons() {
    if (brainstormUndoBtn) brainstormUndoBtn.disabled = !brainstormUndoStack.length;
    if (brainstormRedoBtn) brainstormRedoBtn.disabled = !brainstormRedoStack.length;
  }

  // Records the editor's current state onto the undo stack. Call this
  // immediately BEFORE a mutation, not after — same contract as the note
  // editor's notePushUndo. Same fix applied here as notePushUndo/pushUndo
  // above: brainstorm pads can embed pasted images too, so this reuses
  // pushBoundedSnapshot instead of a bare count-capped push.
  function brainstormPushUndo() {
    pushBoundedSnapshot(brainstormUndoStack, brainstormTextarea.innerHTML, BRAINSTORM_UNDO_LIMIT);
    brainstormRedoStack = [];
    brainstormLastPushAt = Date.now();
    updateBrainstormUndoButtons();
  }

  // Clears the local undo history — called whenever a different
  // node/cell's brainstorm is loaded into the shared editor (see
  // renderBrainstormModal), so undo never reaches back into a scratchpad
  // that's no longer open.
  function brainstormResetUndoHistory() {
    brainstormUndoStack = [];
    brainstormRedoStack = [];
    brainstormLastPushAt = 0;
    updateBrainstormUndoButtons();
    brainstormUppercasePending = false;
    updateBrainstormToolActiveStates();
  }

  // --- Bold / AA "pressed while it applies to what you type next" state,
  // same idea as the note editor's noteUppercasePending above. ---
  let brainstormUppercasePending = false;
  let brainstormUppercaseInserting = false; // re-entrancy guard for the hook below

  function updateBrainstormToolActiveStates() {
    let boldOn = false;
    try { boldOn = document.queryCommandState("bold"); } catch (_) { /* ignore */ }
    $("#brainstorm-tool-bold").classList.toggle("active", !!boldOn);
    $("#brainstorm-tool-upper").classList.toggle("active", brainstormUppercasePending);
  }

  function brainstormRestoreSnapshot(html) {
    brainstormTextarea.innerHTML = html;
    brainstormSyncAllCheckedLines();
    brainstormSyncAllOrderedColors();
    brainstormAutoColorLines();
    refreshBrainstormCards();
    placeCaretAtEnd(brainstormTextarea);
    scheduleBrainstormAutosave();
    updateBrainstormUndoButtons();
  }

  function brainstormUndo() {
    if (!brainstormUndoStack.length) return;
    pushBoundedSnapshot(brainstormRedoStack, brainstormTextarea.innerHTML, BRAINSTORM_UNDO_LIMIT);
    brainstormRestoreSnapshot(brainstormUndoStack.pop());
  }

  function brainstormRedo() {
    if (!brainstormRedoStack.length) return;
    pushBoundedSnapshot(brainstormUndoStack, brainstormTextarea.innerHTML, BRAINSTORM_UNDO_LIMIT);
    brainstormRestoreSnapshot(brainstormRedoStack.pop());
  }

  function brainstormCurrentLine(container = brainstormTextarea) {
    const sel = window.getSelection();
    if (!sel.rangeCount) return null;
    const range = sel.getRangeAt(0);
    let node = range.startContainer;
    if (node.nodeType === 3) {
      node = node.parentNode;
    } else if (node.childNodes.length) {
      const idx = Math.min(Math.max(range.startOffset - 1, 0), node.childNodes.length - 1);
      node = node.childNodes[idx];
    }
    while (node && node !== container && node.parentNode !== container) {
      node = node.parentNode;
    }
    return node === container ? null : node;
  }

  function brainstormCaretIsAtLineStart(lineDiv) {
    if (!lineDiv) return false;
    const sel = window.getSelection();
    if (!sel.rangeCount) return false;
    const range = sel.getRangeAt(0);
    if (!range.collapsed) return false;
    const preRange = document.createRange();
    preRange.selectNodeContents(lineDiv);
    try {
      preRange.setEnd(range.startContainer, range.startOffset);
    } catch (err) {
      return false;
    }
    return preRange.toString().length === 0;
  }

  function brainstormSelectLine(lineDiv) {
    const target = lineDiv || brainstormTextarea;
    const r = document.createRange();
    r.selectNodeContents(target);
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(r);
  }

  function brainstormToggleLinePrefix(prefixRegex, makePrefix) {
    brainstormTextarea.focus();
    brainstormPushUndo();
    const lineDiv = brainstormCurrentLine();
    const el = lineDiv || brainstormTextarea;
    const text = el.textContent;
    const match = text.match(prefixRegex);
    el.textContent = match ? text.slice(match[0].length) : makePrefix() + text;
    brainstormSyncLineChecked(el);
    placeCaretAtEnd(el);
    scheduleBrainstormAutosave();
  }

  function brainstormToggleOrderedList() {
    brainstormTextarea.focus();
    brainstormPushUndo();
    const lineDiv = brainstormCurrentLine();
    const el = lineDiv || brainstormTextarea;
    const text = el.textContent;
    const match = text.match(/^\d+\.\s+/);
    if (match) {
      el.textContent = text.slice(match[0].length);
      el.style.color = "";
    } else {
      el.textContent = "1. " + text;
      brainstormSetOrderedLineColor(el);
    }
    brainstormSyncLineChecked(el);
    placeCaretAtEnd(el);
    scheduleBrainstormAutosave();
  }

  function brainstormApplyForeColor(color) {
    brainstormTextarea.focus();
    brainstormPushUndo();
    const sel = window.getSelection();
    if (sel.rangeCount && sel.getRangeAt(0).collapsed) {
      brainstormSelectLine(brainstormCurrentLine());
    }
    document.execCommand("foreColor", false, color);
    scheduleBrainstormAutosave();
  }

  function brainstormApplyStrikethrough() {
    brainstormTextarea.focus();
    brainstormPushUndo();
    const sel = window.getSelection();
    if (sel.rangeCount && sel.getRangeAt(0).collapsed) {
      brainstormSelectLine(brainstormCurrentLine());
    }
    document.execCommand("strikeThrough");
    scheduleBrainstormAutosave();
  }

  function brainstormApplyBold() {
    brainstormTextarea.focus();
    const sel = window.getSelection();
    const collapsed = !sel.rangeCount || sel.getRangeAt(0).collapsed;
    if (collapsed) {
      document.execCommand("bold");
    } else {
      brainstormPushUndo();
      document.execCommand("bold");
      scheduleBrainstormAutosave();
    }
    updateBrainstormToolActiveStates();
  }

  function brainstormApplyUppercase() {
    brainstormTextarea.focus();
    const sel = window.getSelection();
    const collapsed = !sel.rangeCount || sel.getRangeAt(0).collapsed;
    if (collapsed) {
      brainstormUppercasePending = !brainstormUppercasePending;
      updateBrainstormToolActiveStates();
      return;
    }
    brainstormPushUndo();
    const text = sel.toString();
    if (!text) return;
    document.execCommand("insertText", false, text.toUpperCase());
    scheduleBrainstormAutosave();
    updateBrainstormToolActiveStates();
  }

  function brainstormInsertSymbol(symbol) {
    brainstormTextarea.focus();
    brainstormPushUndo();
    document.execCommand("insertText", false, symbol);
    scheduleBrainstormAutosave();
  }

  // Enter key on a numbered or checklist line continues the pattern,
  // same as the note editor's noteHandleEnter.
  // Mirrors noteHandlePlainLineEnter above — see its comment for why the
  // split is done by hand instead of relying on the browser's native
  // Enter handling (which can nest a new plain line inside the previous
  // one, breaking brainstormAutoColorLines' per-line color cycling).
  function brainstormHandlePlainLineEnter(el, sel) {
    if (el === brainstormTextarea) return false; // no wrapping div yet — let the browser create the very first one
    brainstormPushUndo();
    const range = sel.getRangeAt(0);
    const afterRange = document.createRange();
    afterRange.setStart(range.startContainer, range.startOffset);
    // An empty line (no children yet) has nothing after the caret to
    // move — end the range right where it started rather than calling
    // setEndAfter(el), which would straddle el's own boundary and throw.
    if (el.lastChild) afterRange.setEndAfter(el.lastChild);
    else afterRange.setEnd(range.startContainer, range.startOffset);
    const frag = afterRange.extractContents();
    const newDiv = document.createElement("div");
    if (frag.hasChildNodes()) newDiv.appendChild(frag);
    else newDiv.appendChild(document.createElement("br"));
    if (!el.hasChildNodes()) el.appendChild(document.createElement("br"));
    el.parentNode.insertBefore(newDiv, el.nextSibling);
    brainstormAutoColorLines();
    const caretRange = document.createRange();
    caretRange.selectNodeContents(newDiv);
    caretRange.collapse(true);
    sel.removeAllRanges();
    sel.addRange(caretRange);
    scrollCaretIntoView(newDiv);
    scheduleBrainstormAutosave();
    return true;
  }

  function brainstormHandleEnter() {
    const sel = window.getSelection();
    if (!sel.rangeCount || !sel.getRangeAt(0).collapsed) return false;
    const lineDiv = brainstormCurrentLine();
    const el = lineDiv || brainstormTextarea;
    const lineText = el.textContent;
    const numMatch = lineText.match(/^(\d+)\.\s+/);
    const checkMatch = lineText.match(/^([☐☑])\s+/);
    if (!numMatch && !checkMatch) return brainstormHandlePlainLineEnter(el, sel);
    const prefix = (numMatch || checkMatch)[0];
    const rest = lineText.slice(prefix.length);
    if (rest.trim() === "") {
      brainstormPushUndo();
      el.textContent = "";
      placeCaretAtEnd(el);
      scrollCaretIntoView(el);
      scheduleBrainstormAutosave();
      return true;
    }

    const range = sel.getRangeAt(0);
    let beforeCaretLen = lineText.length;
    try {
      const preRange = document.createRange();
      preRange.selectNodeContents(el);
      preRange.setEnd(range.startContainer, range.startOffset);
      beforeCaretLen = preRange.toString().length;
    } catch (err) { /* keep fallback */ }

    const caretInRest = Math.max(0, Math.min(rest.length, beforeCaretLen - prefix.length));
    const before = rest.slice(0, caretInRest);
    const after = rest.slice(caretInRest);

    brainstormPushUndo();
    const nextPrefix = numMatch ? `${parseInt(numMatch[1], 10) + 1}. ` : "☐ ";
    el.textContent = prefix + before;
    if (numMatch) brainstormSetOrderedLineColor(el);
    brainstormSyncLineChecked(el);

    const newDiv = document.createElement("div");
    newDiv.textContent = nextPrefix + after;
    if (numMatch) brainstormSetOrderedLineColor(newDiv);
    brainstormSyncLineChecked(newDiv);
    if (lineDiv && lineDiv.parentNode) {
      lineDiv.parentNode.insertBefore(newDiv, lineDiv.nextSibling);
    } else {
      brainstormTextarea.appendChild(newDiv);
    }

    const textNode = newDiv.firstChild;
    const caretRange = document.createRange();
    if (textNode && textNode.nodeType === 3) {
      caretRange.setStart(textNode, Math.min(nextPrefix.length, textNode.length));
    } else {
      caretRange.selectNodeContents(newDiv);
    }
    caretRange.collapse(true);
    sel.removeAllRanges();
    sel.addRange(caretRange);
    scrollCaretIntoView(newDiv);
    scheduleBrainstormAutosave();
    return true;
  }

  // Images are embedded directly as data-URI <img> tags, same as the
  // note editor (see noteInsertImages).
  const brainstormImageInput = $("#brainstorm-image-input");
  let brainstormImageInsertLine = null;
  let brainstormImageInsertAtStart = false;

  // Same small starting size as photos dropped into a note (see
  // NOTE_IMG_DEFAULT_INSERT_WIDTH/HEIGHT) — the ➖/➕ buttons resize from there.
  function brainstormInsertImages(dataUrls, targetLine, atStart) {
    brainstormTextarea.focus();
    brainstormPushUndo();
    const lineDiv = targetLine !== undefined ? targetLine : brainstormCurrentLine();
    const validLine = lineDiv && lineDiv.parentNode === brainstormTextarea;
    const parent = validLine ? lineDiv.parentNode : brainstormTextarea;

    if (atStart && validLine) {
      dataUrls.forEach((dataUrl) => {
        const imgLine = document.createElement("div");
        const img = document.createElement("img");
        img.src = dataUrl;
        img.style.width = `${NOTE_IMG_DEFAULT_INSERT_WIDTH}px`;
        img.style.height = `${NOTE_IMG_DEFAULT_INSERT_HEIGHT}px`;
        imgLine.appendChild(img);
        parent.insertBefore(imgLine, lineDiv);
      });
      const range = document.createRange();
      range.setStart(lineDiv, 0);
      range.collapse(true);
      const sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(range);
    } else {
      let cursor = validLine ? lineDiv : parent.lastChild;
      let lastImgLine = null;
      dataUrls.forEach((dataUrl) => {
        const imgLine = document.createElement("div");
        const img = document.createElement("img");
        img.src = dataUrl;
        img.style.width = `${NOTE_IMG_DEFAULT_INSERT_WIDTH}px`;
        img.style.height = `${NOTE_IMG_DEFAULT_INSERT_HEIGHT}px`;
        imgLine.appendChild(img);
        parent.insertBefore(imgLine, cursor ? cursor.nextSibling : null);
        cursor = imgLine;
        lastImgLine = imgLine;
      });
      const afterLine = document.createElement("div");
      afterLine.appendChild(document.createElement("br"));
      parent.insertBefore(afterLine, lastImgLine ? lastImgLine.nextSibling : null);
      placeCaretAtEnd(afterLine);
    }
    scheduleBrainstormAutosave();
  }

  function brainstormInsertImage(dataUrl, targetLine, atStart) {
    brainstormInsertImages([dataUrl], targetLine, atStart);
  }

  function brainstormHandleImageFiles(fileList, targetLine, atStart) {
    const files = Array.from(fileList || []).filter(f => f && f.type && f.type.startsWith("image/"));
    if (!files.length) return;
    let hadError = false;
    Promise.all(files.map((file) => new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = () => { hadError = true; resolve(null); };
      reader.readAsDataURL(file);
    })))
      .then((dataUrls) => Promise.all(dataUrls.map(downscaleNoteImageDataUrl)))
      .then((dataUrls) => {
      const loaded = dataUrls.filter(Boolean);
      if (loaded.length) brainstormInsertImages(loaded, targetLine, atStart);
      if (hadError) alert("Some images couldn't be read.");
    });
  }

  function brainstormHandleImageFile(file, targetLine, atStart) {
    if (!file) return;
    brainstormHandleImageFiles([file], targetLine, atStart);
  }

  $("#brainstorm-tool-image").addEventListener("mousedown", (e) => e.preventDefault());
  $("#brainstorm-tool-image").addEventListener("click", () => {
    brainstormImageInsertLine = brainstormCurrentLine();
    brainstormImageInsertAtStart = brainstormCaretIsAtLineStart(brainstormImageInsertLine);
    brainstormImageInput.click();
  });
  brainstormImageInput.addEventListener("change", () => {
    if (brainstormImageInput.files && brainstormImageInput.files.length) {
      brainstormHandleImageFiles(brainstormImageInput.files, brainstormImageInsertLine, brainstormImageInsertAtStart);
    }
    brainstormImageInput.value = "";
  });

  brainstormTextarea.addEventListener("paste", (e) => {
    const items = e.clipboardData && e.clipboardData.items;
    if (!items) return;
    for (const item of items) {
      if (item.type && item.type.startsWith("image/")) {
        e.preventDefault();
        const pasteLine = brainstormCurrentLine();
        const pasteAtStart = brainstormCaretIsAtLineStart(pasteLine);
        brainstormHandleImageFile(item.getAsFile(), pasteLine, pasteAtStart);
        return;
      }
    }
  });

  function brainstormDraggedImageFile(e) {
    const dt = e.dataTransfer;
    if (!dt) return null;
    const fromFiles = dt.files && Array.from(dt.files).find(f => f.type && f.type.startsWith("image/"));
    if (fromFiles) return fromFiles;
    const hasImageItem = dt.items && Array.from(dt.items).some(i => i.type && i.type.startsWith("image/"));
    return hasImageItem ? true : null;
  }

  brainstormTextarea.addEventListener("dragover", (e) => {
    if (brainstormDraggedImageFile(e)) {
      e.preventDefault();
      brainstormTextarea.classList.add("drag-over");
    }
  });
  brainstormTextarea.addEventListener("dragleave", () => brainstormTextarea.classList.remove("drag-over"));
  brainstormTextarea.addEventListener("drop", (e) => {
    const file = brainstormDraggedImageFile(e);
    if (file && file !== true) {
      e.preventDefault();
      brainstormTextarea.classList.remove("drag-over");
      brainstormHandleImageFile(file);
    } else {
      brainstormTextarea.classList.remove("drag-over");
    }
  });

  // Hover −/+ buttons on photos — the same floating pair the note editor
  // uses (see showNoteImageShrinkBtn), wired to this editor's own undo and
  // autosave.
  const NOTE_IMG_HOST_BRAINSTORM = { pushUndo: () => brainstormPushUndo(), save: () => scheduleBrainstormAutosave() };
  brainstormTextarea.addEventListener("mouseover", (e) => {
    if (e.target && e.target.tagName === "IMG") showNoteImageShrinkBtn(e.target, NOTE_IMG_HOST_BRAINSTORM);
  });
  brainstormTextarea.addEventListener("mouseout", (e) => {
    if (e.target && e.target.tagName === "IMG" &&
        !noteImageShrinkBtn.contains(e.relatedTarget) && !noteImageGrowBtn.contains(e.relatedTarget)) {
      hideNoteImageShrinkBtn();
    }
  });
  brainstormTextarea.addEventListener("scroll", () => {
    if (noteImageShrinkTarget && brainstormTextarea.contains(noteImageShrinkTarget)) positionNoteImageShrinkBtn(noteImageShrinkTarget);
  });

  // Clicking directly on a checklist glyph toggles it, or on an image
  // opens the photo viewer — same as the note editor.
  brainstormTextarea.addEventListener("click", (e) => {
    if (e.target && e.target.tagName === "IMG") {
      openNotePhotoViewer(e.target, brainstormTextarea);
      return;
    }
    const lineDiv = brainstormCurrentLine();
    const text = (lineDiv || brainstormTextarea).textContent;
    if (!/^[☐☑]\s/.test(text)) return;
    const sel = window.getSelection();
    if (!sel.rangeCount) return;
    if (!sel.isCollapsed) return;
    const range = sel.getRangeAt(0);
    const preRange = range.cloneRange();
    preRange.selectNodeContents(lineDiv || brainstormTextarea);
    preRange.setEnd(range.startContainer, range.startOffset);
    if (preRange.toString().length > 1) return;
    brainstormPushUndo();
    const el = lineDiv || brainstormTextarea;
    el.textContent = text.replace(/^[☐☑]/, m => (m === "☐" ? "☑" : "☐"));
    brainstormSyncLineChecked(el);
    scheduleBrainstormAutosave();
  });

  brainstormUndoBtn.addEventListener("mousedown", (e) => e.preventDefault());
  brainstormUndoBtn.addEventListener("click", () => brainstormUndo());
  brainstormRedoBtn.addEventListener("mousedown", (e) => e.preventDefault());
  brainstormRedoBtn.addEventListener("click", () => brainstormRedo());

  $("#brainstorm-tool-ol").addEventListener("mousedown", (e) => {
    e.preventDefault();
    brainstormToggleOrderedList();
  });
  $("#brainstorm-tool-check").addEventListener("mousedown", (e) => {
    e.preventDefault();
    brainstormToggleLinePrefix(/^[☐☑]\s+/, () => "☐ ");
  });
  $("#brainstorm-tool-strike").addEventListener("mousedown", (e) => {
    e.preventDefault();
    brainstormApplyStrikethrough();
  });
  $("#brainstorm-tool-bold").addEventListener("mousedown", (e) => {
    e.preventDefault();
    brainstormApplyBold();
  });
  $("#brainstorm-tool-upper").addEventListener("mousedown", (e) => {
    e.preventDefault();
    brainstormApplyUppercase();
  });
  document.querySelectorAll(".brainstorm-color-swatch").forEach(btn => {
    btn.addEventListener("mousedown", (e) => {
      e.preventDefault();
      brainstormApplyForeColor(btn.dataset.color);
      setBrainstormColorTrigger(btn.dataset.color);
    });
    btn.addEventListener("click", () => { closeBrainstormColorPopover(); });
  });
  $("#brainstorm-color-custom").addEventListener("input", (e) => {
    brainstormApplyForeColor(e.target.value);
    setBrainstormColorTrigger(e.target.value);
  });
  $("#brainstorm-color-custom").addEventListener("mousedown", (e) => e.stopPropagation());

  const brainstormColorTriggerBtn = $("#brainstorm-tool-color");
  const brainstormColorPopover = $("#brainstorm-color-popover");
  brainstormColorTriggerBtn.addEventListener("mousedown", (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (brainstormColorPopover.classList.contains("hidden")) {
      openBrainstormColorPopover();
    } else {
      closeBrainstormColorPopover();
    }
  });
  brainstormColorPopover.addEventListener("mousedown", (e) => e.stopPropagation());
  document.addEventListener("mousedown", (e) => {
    if (!brainstormColorPopover.classList.contains("hidden") &&
        !brainstormColorPopover.contains(e.target) && e.target !== brainstormColorTriggerBtn) {
      closeBrainstormColorPopover();
    }
  });
  window.addEventListener("resize", () => {
    if (!brainstormColorPopover.classList.contains("hidden")) positionBrainstormColorPopover();
  });
  function openBrainstormColorPopover(){
    brainstormColorPopover.classList.remove("hidden");
    positionBrainstormColorPopover();
  }
  function closeBrainstormColorPopover(){ brainstormColorPopover.classList.add("hidden"); }
  function positionBrainstormColorPopover(){
    const margin = 8;
    const btnRect = brainstormColorTriggerBtn.getBoundingClientRect();
    const popRect = brainstormColorPopover.getBoundingClientRect();
    let left = btnRect.left + btnRect.width / 2 - popRect.width / 2;
    left = Math.max(margin, Math.min(left, window.innerWidth - popRect.width - margin));
    let top = btnRect.bottom + 6;
    if (top + popRect.height > window.innerHeight - margin) {
      top = btnRect.top - popRect.height - 6;
    }
    brainstormColorPopover.style.left = `${left}px`;
    brainstormColorPopover.style.top = `${top}px`;
  }
  function setBrainstormColorTrigger(color){ $("#brainstorm-color-trigger-swatch").style.background = color; }

  const brainstormSymbolTriggerBtn = $("#brainstorm-tool-symbol");
  const brainstormSymbolPopover = $("#brainstorm-symbol-popover");
  document.querySelectorAll(".brainstorm-symbol-swatch").forEach(btn => {
    btn.addEventListener("mousedown", (e) => {
      e.preventDefault();
      brainstormInsertSymbol(btn.dataset.symbol);
    });
    btn.addEventListener("click", () => { closeBrainstormSymbolPopover(); });
  });
  brainstormSymbolTriggerBtn.addEventListener("mousedown", (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (brainstormSymbolPopover.classList.contains("hidden")) {
      openBrainstormSymbolPopover();
    } else {
      closeBrainstormSymbolPopover();
    }
  });
  brainstormSymbolPopover.addEventListener("mousedown", (e) => e.stopPropagation());
  document.addEventListener("mousedown", (e) => {
    if (!brainstormSymbolPopover.classList.contains("hidden") &&
        !brainstormSymbolPopover.contains(e.target) && e.target !== brainstormSymbolTriggerBtn) {
      closeBrainstormSymbolPopover();
    }
  });
  window.addEventListener("resize", () => {
    if (!brainstormSymbolPopover.classList.contains("hidden")) positionBrainstormSymbolPopover();
  });
  function openBrainstormSymbolPopover(){
    brainstormSymbolPopover.classList.remove("hidden");
    positionBrainstormSymbolPopover();
  }
  function closeBrainstormSymbolPopover(){ brainstormSymbolPopover.classList.add("hidden"); }
  function positionBrainstormSymbolPopover(){
    const margin = 8;
    const btnRect = brainstormSymbolTriggerBtn.getBoundingClientRect();
    const popRect = brainstormSymbolPopover.getBoundingClientRect();
    let left = btnRect.left + btnRect.width / 2 - popRect.width / 2;
    left = Math.max(margin, Math.min(left, window.innerWidth - popRect.width - margin));
    let top = btnRect.bottom + 6;
    if (top + popRect.height > window.innerHeight - margin) {
      top = btnRect.top - popRect.height - 6;
    }
    brainstormSymbolPopover.style.left = `${left}px`;
    brainstormSymbolPopover.style.top = `${top}px`;
  }

  // Groups plain typing into undo-sized bursts, same 600ms pattern as
  // the note editor.
  const BRAINSTORM_TYPING_BURST_MS = 600;
  brainstormTextarea.addEventListener("beforeinput", () => {
    const now = Date.now();
    if (now - brainstormLastPushAt > BRAINSTORM_TYPING_BURST_MS || !brainstormUndoStack.length) {
      pushBoundedSnapshot(brainstormUndoStack, brainstormTextarea.innerHTML, BRAINSTORM_UNDO_LIMIT);
    }
    brainstormRedoStack = [];
    brainstormLastPushAt = now;
    updateBrainstormUndoButtons();
  });
  // While "type in caps" mode is armed (AA button pressed), transform
  // each character as it's typed, same as the note editor.
  brainstormTextarea.addEventListener("beforeinput", (e) => {
    if (!brainstormUppercasePending || brainstormUppercaseInserting) return;
    if (e.inputType === "insertText" && e.data) {
      e.preventDefault();
      brainstormUppercaseInserting = true;
      document.execCommand("insertText", false, e.data.toUpperCase());
      brainstormUppercaseInserting = false;
    }
  });
  brainstormTextarea.addEventListener("mousedown", () => {
    if (brainstormUppercasePending) {
      brainstormUppercasePending = false;
      updateBrainstormToolActiveStates();
    }
  });
  document.addEventListener("selectionchange", () => {
    if (!brainstormModal.classList.contains("hidden") && document.activeElement === brainstormTextarea) {
      updateBrainstormToolActiveStates();
    }
  });

  brainstormTextarea.addEventListener("input", () => { brainstormAutoColorLines(); scheduleBrainstormAutosave(); });
  brainstormTextarea.addEventListener("keydown", (e) => {
    e.stopPropagation(); // don't let Tab/Enter/Delete/etc trigger canvas shortcuts while typing
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") {
      e.preventDefault();
      if (e.shiftKey) brainstormRedo(); else brainstormUndo();
      return;
    }
    // Same Ctrl/Cmd+B and Caps Lock shortcuts as the note editor — see
    // noteHandleEnter's keydown handler for why these are intercepted.
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "b") {
      e.preventDefault();
      brainstormApplyBold();
      return;
    }
    if (e.key === "CapsLock") {
      brainstormApplyUppercase();
      return;
    }
    if (e.key === "Escape") { e.preventDefault(); closeBrainstormModal(); return; }
    if (e.key === "Enter" && !e.shiftKey) {
      if (brainstormHandleEnter()) {
        e.preventDefault();
        refreshBrainstormCards();
      }
    }
  });

  brainstormClearBtn.addEventListener("click", () => {
    const t = brainstormEditingId;
    if (!t) return;
    const host = resolveHost(t.nodeId, t.r, t.c);
    if (!host || !getBrainstormText(host)) return;
    pushUndo();
    host.brainstorm = { text: "", html: "" };
    brainstormTextarea.innerHTML = "";
    brainstormResetUndoHistory();
    renderBrainstormProgress(host);
    persist();
    updateBrainstormLiveUI(t);
  });

  $("#brainstorm-back").addEventListener("click", closeBrainstormModal);
  // Same fix as noteModal above: require the mousedown to have started on
  // the backdrop too, so dragging a text selection past the card's edge
  // doesn't get misread as a click-away-to-close.
  let brainstormBackdropMousedown = false;
  brainstormModal.addEventListener("mousedown", (e) => { brainstormBackdropMousedown = (e.target === brainstormModal); });
  brainstormModal.addEventListener("click", (e) => {
    if (!brainstormIsResizing && e.target === brainstormModal && brainstormBackdropMousedown) closeBrainstormModal();
  });

  /* ---------------- affirmation lines manager ---------------- */
  // Lets the person edit the pool of lines itself: rename any existing
  // line in place, delete one, or add new ones. Changes save immediately
  // (debounced text edits save on blur/Enter) via saveAffirmationQuotes().

  const affirmationQuotesModal = $("#affirmation-quotes-modal");
  const affirmationQuotesListEl = $("#affirmation-quotes-list");
  const affirmationQuotesNewInput = $("#affirmation-quotes-new-input");

  function openAffirmationQuotesModal() {
    renderAffirmationQuotesModal();
    zoomModalOpen(affirmationQuotesModal);
    requestAnimationFrame(() => affirmationQuotesNewInput.focus());
  }
  function closeAffirmationQuotesModal() {
    zoomModalClose(affirmationQuotesModal, () => { affirmationQuotesNewInput.value = ""; });
  }

  function renderAffirmationQuotesModal() {
    affirmationQuotesListEl.innerHTML = "";
    if (!affirmationQuotesList.length) {
      const empty = document.createElement("li");
      empty.className = "affirmation-quotes-empty";
      empty.textContent = "No lines yet — add one below.";
      affirmationQuotesListEl.appendChild(empty);
      return;
    }
    affirmationQuotesList.forEach((quote, idx) => {
      const li = document.createElement("li");
      li.className = "affirmation-quote-row";

      const input = document.createElement("input");
      input.type = "text";
      input.className = "affirmation-quote-row-input";
      input.spellcheck = false;
      input.value = quote;
      input.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Enter") { e.preventDefault(); input.blur(); }
        else if (e.key === "Escape") { e.preventDefault(); input.value = quote; input.blur(); }
      });
      input.addEventListener("blur", () => {
        const v = input.value.trim();
        if (v && v !== affirmationQuotesList[idx]) {
          affirmationQuotesList[idx] = v;
          saveAffirmationQuotes();
        } else {
          input.value = affirmationQuotesList[idx];
        }
      });

      const del = document.createElement("button");
      del.type = "button";
      del.className = "affirmation-quote-row-delete";
      del.title = "Remove this line";
      del.textContent = "×";
      del.addEventListener("click", () => {
        affirmationQuotesList.splice(idx, 1);
        saveAffirmationQuotes();
        renderAffirmationQuotesModal();
      });

      li.appendChild(input);
      li.appendChild(del);
      affirmationQuotesListEl.appendChild(li);
    });
  }

  function addAffirmationQuoteFromModal() {
    const v = affirmationQuotesNewInput.value.trim();
    if (!v) return;
    affirmationQuotesList.push(v);
    saveAffirmationQuotes();
    affirmationQuotesNewInput.value = "";
    renderAffirmationQuotesModal();
  }

  $("#affirmation-quotes-close").addEventListener("click", closeAffirmationQuotesModal);
  affirmationQuotesModal.addEventListener("click", (e) => { if (e.target === affirmationQuotesModal) closeAffirmationQuotesModal(); });
  affirmationQuotesNewInput.addEventListener("keydown", (e) => {
    e.stopPropagation();
    if (e.key === "Enter") { e.preventDefault(); addAffirmationQuoteFromModal(); }
    else if (e.key === "Escape") { e.preventDefault(); closeAffirmationQuotesModal(); }
  });
  document.addEventListener("keydown", (e) => {
    if (affirmationQuotesModal.classList.contains("hidden")) return;
    if (e.key === "Escape" && document.activeElement !== affirmationQuotesNewInput) closeAffirmationQuotesModal();
  });

  /* ---------------- trash modal ---------------- */

  const trashModal = $("#trash-modal");
  const trashListEl = $("#trash-list");

  function openTrashModal() {
    renderTrashModal();
    zoomModalOpen(trashModal);
  }
  function closeTrashModal() {
    zoomModalClose(trashModal);
  }

  function renderTrashModal() {
    updateTrashBadge();
    trashListEl.innerHTML = "";
    const trashed = trashedMapsList().sort((a, b) => (b.trashedAt || 0) - (a.trashedAt || 0));
    if (!trashed.length) {
      const empty = document.createElement("li");
      empty.className = "trash-empty";
      empty.textContent = "Trash is empty.";
      trashListEl.appendChild(empty);
      $("#trash-empty-btn").disabled = true;
      return;
    }
    $("#trash-empty-btn").disabled = false;
    trashed.forEach((m) => {
      const li = document.createElement("li");
      li.className = "trash-row";

      const text = document.createElement("div");
      text.className = "trash-row-text";
      const name = document.createElement("span");
      name.className = "trash-row-name";
      name.textContent = m.title || "Untitled map";
      const rel = relTime(m.trashedAt);
      const meta = document.createElement("span");
      meta.className = "trash-row-meta";
      meta.textContent = rel === "now" ? "Trashed just now" : `Trashed ${rel} ago`;
      text.append(name, meta);

      const actions = document.createElement("div");
      actions.className = "trash-row-actions";
      const restoreBtn = document.createElement("button");
      restoreBtn.type = "button";
      restoreBtn.className = "trash-row-restore";
      restoreBtn.textContent = "Restore";
      restoreBtn.addEventListener("click", () => restoreMap(m.id));
      const delBtn = document.createElement("button");
      delBtn.type = "button";
      delBtn.className = "trash-row-delete";
      delBtn.textContent = "Delete forever";
      delBtn.addEventListener("click", () => permanentlyDeleteMap(m.id));
      actions.append(restoreBtn, delBtn);

      li.append(text, actions);
      trashListEl.appendChild(li);
    });
  }

  $("#btn-trash").addEventListener("click", openTrashModal);
  $("#trash-close").addEventListener("click", closeTrashModal);
  $("#trash-empty-btn").addEventListener("click", emptyTrash);
  trashModal.addEventListener("click", (e) => { if (e.target === trashModal) closeTrashModal(); });
  document.addEventListener("keydown", (e) => {
    if (trashModal.classList.contains("hidden")) return;
    if (e.key === "Escape") closeTrashModal();
  });

  /* ---------------- storage modal ---------------- */
  // Answers "why is this site using way more browser storage than my
  // maps look like they should?" — almost always either (a) trashed
  // maps, which are only ever soft-deleted (see deleteMap) and keep
  // every one of their photo rows in PhotoDB until Empty Trash actually
  // runs, or (b) leftover photo rows in PhotoDB that nothing in the
  // current node tree references anymore (gcOrphanedPhotos above exists
  // for exactly this, but is deliberately never called automatically —
  // see the big comment on it — so it only ever runs from the button
  // here, on the one map that's actually open).

  const storageModal = $("#storage-modal");
  const storageListEl = $("#storage-list");
  const storageTotalLine = $("#storage-total-line");

  function formatStorageBytes(n) {
    if (!n) return "0 B";
    if (n < 1024) return `${n} B`;
    if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
    if (n < 1024 * 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;
    return `${(n / 1024 / 1024 / 1024).toFixed(2)} GB`;
  }

  // Blob rows report their own size directly; legacy pre-Blob rows only
  // have a base64 `data:` string, whose raw byte count is ~3/4 of the
  // string length minus the "data:image/...;base64," header — close
  // enough for a usage estimate, not worth decoding just to measure.
  async function estimateMapPhotoBytes(mapId) {
    let total = 0;
    try {
      const rows = await PhotoDB.getAllForMap(mapId);
      for (const r of rows) {
        if (r.blob && typeof r.blob.size === "number") total += r.blob.size;
        else if (typeof r.data === "string") {
          const commaIdx = r.data.indexOf(",");
          total += Math.floor((r.data.length - (commaIdx + 1)) * 0.75);
        }
      }
    } catch (e) { /* best-effort estimate */ }
    return total;
  }

  async function openStorageModal() {
    zoomModalOpen(storageModal);
    await renderStorageModal();
  }
  function closeStorageModal() {
    zoomModalClose(storageModal);
  }

  async function renderStorageModal() {
    storageListEl.innerHTML = "";
    storageTotalLine.textContent = "Calculating…";
    $("#storage-empty-trash-btn").disabled = trashedMapsList().length === 0;

    const rows = await Promise.all(state.maps.map(async (m) => {
      const photoBytes = await estimateMapPhotoBytes(m.id);
      const treeBytes = JSON.stringify(m).length;
      return { map: m, bytes: photoBytes + treeBytes };
    }));
    rows.sort((a, b) => b.bytes - a.bytes);

    // Rows in PhotoDB whose mapId doesn't match ANY map this browser
    // still knows about — active or trashed. These are invisible to
    // every other view in the app (Trash included, since their owning
    // map record is already gone) and can only ever have come from a
    // map being deleted without its photos being cleaned up first: an
    // older build's delete path, or a write that got interrupted
    // partway through permanentlyDeleteMap/emptyTrash. Safe to delete
    // outright — by definition nothing references them anymore.
    const knownMapIds = new Set(state.maps.map(m => m.id));
    let orphanBytes = 0;
    let orphanIds = [];
    try {
      const allPhotoRows = await PhotoDB.getAllRaw();
      for (const r of allPhotoRows) {
        if (knownMapIds.has(r.mapId)) continue;
        orphanIds.push(r.id);
        if (r.blob && typeof r.blob.size === "number") orphanBytes += r.blob.size;
        else if (typeof r.data === "string") {
          const commaIdx = r.data.indexOf(",");
          orphanBytes += Math.floor((r.data.length - (commaIdx + 1)) * 0.75);
        }
      }
    } catch (e) { /* best-effort scan */ }
    storageOrphanIds = orphanIds;
    const orphanBtn = $("#storage-orphan-btn");
    orphanBtn.disabled = orphanIds.length === 0;
    orphanBtn.textContent = orphanIds.length
      ? `Delete ${orphanIds.length} unowned photo${orphanIds.length === 1 ? "" : "s"} (${formatStorageBytes(orphanBytes)})`
      : "No unowned photos found";

    const trashedTotal = rows.filter(r => r.map.trashedAt).reduce((s, r) => s + r.bytes, 0);
    const grandTotal = rows.reduce((s, r) => s + r.bytes, 0) + orphanBytes;

    let quotaLine = "";
    if (navigator.storage && navigator.storage.estimate) {
      try {
        const est = await navigator.storage.estimate();
        if (typeof est.usage === "number") {
          quotaLine = ` Chrome reports ${formatStorageBytes(est.usage)} actually on disk for this site — the gap from the estimate above is normal IndexedDB/browser overhead.`;
        }
      } catch (e) { /* estimate() not available in this context */ }
    }
    const parts = [`~${formatStorageBytes(grandTotal)} across ${rows.length} map${rows.length === 1 ? "" : "s"}`];
    if (trashedTotal > 0) parts.push(`~${formatStorageBytes(trashedTotal)} of that is sitting in the trash`);
    if (orphanBytes > 0) parts.push(`~${formatStorageBytes(orphanBytes)} more is photos left behind by maps that no longer exist at all — not shown in the trash, only below`);
    storageTotalLine.textContent = parts.join(". ") + `.${quotaLine}`;

    if (!rows.length) {
      const empty = document.createElement("li");
      empty.className = "trash-empty";
      empty.textContent = "No maps yet.";
      storageListEl.appendChild(empty);
      return;
    }

    rows.forEach(({ map: m, bytes }) => {
      const li = document.createElement("li");
      li.className = "trash-row" + (m.trashedAt ? " storage-row-trashed" : "");

      const text = document.createElement("div");
      text.className = "trash-row-text";
      const name = document.createElement("span");
      name.className = "trash-row-name";
      name.textContent = m.title || "Untitled map";
      const meta = document.createElement("span");
      meta.className = "trash-row-meta";
      meta.textContent = formatStorageBytes(bytes);
      text.append(name, meta);

      const actions = document.createElement("div");
      actions.className = "trash-row-actions";
      if (m.trashedAt) {
        const delBtn = document.createElement("button");
        delBtn.type = "button";
        delBtn.className = "trash-row-delete";
        delBtn.textContent = "Delete forever";
        delBtn.addEventListener("click", async () => {
          await permanentlyDeleteMap(m.id);
          renderStorageModal();
        });
        actions.appendChild(delBtn);
      }

      li.append(text, actions);
      storageListEl.appendChild(li);
    });
  }

  let storageOrphanIds = [];

  $("#btn-storage").addEventListener("click", openStorageModal);
  $("#storage-close").addEventListener("click", closeStorageModal);
  $("#storage-empty-trash-btn").addEventListener("click", async () => {
    await emptyTrash();
    renderStorageModal();
  });
  $("#storage-cleanup-btn").addEventListener("click", async () => {
    if (!state.current) { showToast("Open a map first."); return; }
    const before = await estimateMapPhotoBytes(state.current.id);
    await gcOrphanedPhotos(state.current);
    await loadPhotoCacheForMap(state.current.id); // refresh the in-tab cache to match what's left on disk
    const after = await estimateMapPhotoBytes(state.current.id);
    const freed = before - after;
    showToast(freed > 0 ? `Freed ${formatStorageBytes(freed)} of unused photos on this map.` : "No unused photos found on this map.");
    renderStorageModal();
  });
  // Folds photos that are byte-for-byte identical (added before identical
  // photos shared an id) onto one id per picture, on the currently open map.
  $("#storage-merge-btn").addEventListener("click", async () => {
    if (!state.current) { showToast("Open a map first."); return; }
    if (!requireSignIn()) return;
    if (!confirm("Merge identical photos on this map? Photos that are exactly the same picture will share one stored copy. Nothing you see changes, but this clears the undo history.")) return;
    showToast("Checking photos…");
    const map = state.current;
    await photoFpIndexPromise; // make sure every stored photo has been fingerprinted
    if (state.current !== map) return;
    const before = await estimateMapPhotoBytes(map.id);
    const groups = new Map();
    collectReferencedPhotoIds(map.root).forEach((id) => {
      const fp = photoFpById.get(id);
      if (!fp || !photoBlobCache.has(id)) return;
      if (!groups.has(fp)) groups.set(fp, []);
      groups.get(fp).push(id);
    });
    let merged = 0;
    groups.forEach((ids) => {
      if (ids.length < 2) return;
      const keep = ids[0];
      ids.slice(1).forEach((dupId) => {
        (function walk(n) { merged += replacePhotoIdInNode(n, dupId, keep); (n.children || []).forEach(walk); })(map.root);
      });
    });
    if (!merged) { showToast("No identical photos to merge."); return; }
    // The old ids no longer exist in the tree, so earlier undo snapshots
    // would point at photos that are about to be swept — drop them.
    state.undoStack = [];
    state.redoStack = [];
    renderAll();
    persist();
    // Get the merged tree onto disk BEFORE sweeping the now-unused photo
    // rows, so a crash in between can never leave the saved map pointing
    // at photos that no longer exist.
    try { await DB.put(map); } catch (e) {
      showToast("Couldn't save the merge — nothing was deleted.");
      renderStorageModal();
      return;
    }
    await gcOrphanedPhotos(map);
    await loadPhotoCacheForMap(map.id);
    const after = await estimateMapPhotoBytes(map.id);
    const freed = before - after;
    showToast(`Merged ${merged} duplicate photo reference${merged === 1 ? "" : "s"}` + (freed > 0 ? ` — freed ${formatStorageBytes(freed)}.` : "."));
    renderStorageModal();
  });
  $("#storage-cleanup-all-btn").addEventListener("click", async () => {
    if (!confirm(`Scan all ${state.maps.length} map${state.maps.length === 1 ? "" : "s"} for unused photo bytes and delete them? This can't be undone.`)) return;
    let before = 0;
    for (const m of state.maps) before += await estimateMapPhotoBytes(m.id);
    for (const m of state.maps) await gcOrphanedPhotos(m);
    // Only the currently-open map's photos are cached in this tab (see
    // photoCache/photoBlobCache) — refresh that one so anything just
    // deleted from under it doesn't leave a dangling object URL around.
    if (state.current) await loadPhotoCacheForMap(state.current.id);
    let after = 0;
    for (const m of state.maps) after += await estimateMapPhotoBytes(m.id);
    const freed = before - after;
    showToast(freed > 0 ? `Freed ${formatStorageBytes(freed)} of unused photos across all maps.` : "No unused photos found.");
    renderStorageModal();
  });
  $("#storage-orphan-btn").addEventListener("click", async () => {
    if (!storageOrphanIds.length) return;
    if (!confirm(`Permanently delete ${storageOrphanIds.length} photo${storageOrphanIds.length === 1 ? "" : "s"} left behind by maps that no longer exist? This can't be undone.`)) return;
    await PhotoDB.deleteMany(storageOrphanIds);
    storageOrphanIds = [];
    renderStorageModal();
  });
  storageModal.addEventListener("click", (e) => { if (e.target === storageModal) closeStorageModal(); });
  document.addEventListener("keydown", (e) => {
    if (storageModal.classList.contains("hidden")) return;
    if (e.key === "Escape") closeStorageModal();
  });

  /* ---------------- photo tag browser ---------------- */

  const tagBrowserModal = $("#tagbrowser-modal");
  const tagBrowserListView = $("#tagbrowser-list-view");
  const tagBrowserGalleryView = $("#tagbrowser-gallery-view");
  const tagBrowserTagList = $("#tagbrowser-tag-list");
  const tagBrowserGalleryGrid = $("#tagbrowser-gallery-grid");
  const tagBrowserGalleryTitle = $("#tagbrowser-gallery-title");

  // The tag browser now lives inside the Photos browser (its 🏷 Tags
  // button), so when it's opened from there the list view shows a back
  // arrow that returns to Photos instead of just closing.
  const tagBrowserListBack = $("#tagbrowser-list-back");

  function openTagBrowserModal(fromPhotos) {
    renderTagBrowserList();
    tagBrowserGalleryView.classList.add("hidden");
    tagBrowserListView.classList.remove("hidden");
    tagBrowserListBack.classList.toggle("hidden", !fromPhotos);
    zoomModalOpen(tagBrowserModal);
  }
  function closeTagBrowserModal() {
    zoomModalClose(tagBrowserModal);
  }

  function renderTagBrowserList() {
    tagBrowserTagList.innerHTML = "";
    const groups = collectPhotoTagGroups();
    if (!groups.length) {
      const empty = document.createElement("li");
      empty.className = "tagbrowser-empty";
      empty.textContent = "No tagged photos yet — open a photo and add a tag to start grouping them here.";
      tagBrowserTagList.appendChild(empty);
      return;
    }
    groups.forEach((group) => {
      const li = document.createElement("li");
      li.className = "tagbrowser-tag-row";

      const thumb = document.createElement("img");
      thumb.className = "tagbrowser-tag-thumb";
      thumb.alt = "";
      // Defensive fallback: if this photo's bytes genuinely aren't in
      // this browser's local PhotoDB (data loss, or a not-yet-finished
      // cache load), hide the broken-image icon rather than show it.
      const thumbUrl = photoUrl(group.items[0].id);
      if (thumbUrl) thumb.src = thumbUrl; else thumb.style.visibility = "hidden";
      thumb.addEventListener("error", () => { thumb.style.visibility = "hidden"; });

      const name = document.createElement("span");
      name.className = "tagbrowser-tag-name";
      name.textContent = group.label;

      const count = document.createElement("span");
      count.className = "tagbrowser-tag-count";
      count.textContent = String(group.items.length);

      const chevron = document.createElement("span");
      chevron.className = "tagbrowser-tag-chevron";
      chevron.textContent = "›";

      li.append(thumb, name, count, chevron);
      li.addEventListener("click", () => openTagGallery(group));
      tagBrowserTagList.appendChild(li);
    });
  }

  function openTagGallery(group) {
    tagBrowserGalleryTitle.textContent = group.label;
    tagBrowserGalleryGrid.innerHTML = "";
    group.items.forEach((it) => {
      const node = findNode(it.nodeId);
      if (!node) return; // stale entry (shouldn't normally happen)
      const cell = document.createElement("div");
      cell.className = "tagbrowser-gallery-item";

      const thumb = document.createElement("img");
      thumb.className = "tagbrowser-gallery-thumb";
      thumb.alt = "";
      const thumbUrl = photoUrl(it.id);
      if (thumbUrl) thumb.src = thumbUrl; else thumb.style.visibility = "hidden";
      thumb.addEventListener("error", () => { thumb.style.visibility = "hidden"; });

      const label = document.createElement("span");
      label.className = "tagbrowser-gallery-label";
      label.textContent = node.text || "Untitled node";

      cell.append(thumb, label);
      // Opens the very same full photo viewer used from a node (zoom, crop,
      // add text, tag it, etc.) — with the group attached so its prev/next
      // step through every photo sharing this tag instead of just this
      // node's own photos, plus a "Go to node" button to jump to the map.
      cell.addEventListener("click", () => {
        const idx = getNodeImageIds(node).indexOf(it.id);
        if (idx < 0) return;
        // Back re-opens this tag's gallery (and, if the tag browser was
        // reached through the Photos browser, keeps its ← to Photos).
        const fromPhotos = !tagBrowserListBack.classList.contains("hidden");
        const ret = {
          label: fromPhotos ? `Photos › ${group.label}` : `tag “${group.label}”`,
          restore: () => { openTagBrowserModal(fromPhotos); openTagGallery(group); },
        };
        closeTagBrowserModal();
        withViewerReturn(ret, () => openPhotoModal(it.nodeId, idx, group));
      });
      tagBrowserGalleryGrid.appendChild(cell);
    });
    tagBrowserListView.classList.add("hidden");
    tagBrowserGalleryView.classList.remove("hidden");
  }

  tagBrowserListBack.addEventListener("click", () => {
    closeTagBrowserModal();
    openPhotosBrowserModal();
  });
  $("#tagbrowser-close").addEventListener("click", closeTagBrowserModal);
  $("#tagbrowser-gallery-close").addEventListener("click", closeTagBrowserModal);
  $("#tagbrowser-back").addEventListener("click", () => {
    tagBrowserGalleryView.classList.add("hidden");
    tagBrowserListView.classList.remove("hidden");
  });
  tagBrowserModal.addEventListener("click", (e) => { if (e.target === tagBrowserModal) closeTagBrowserModal(); });
  document.addEventListener("keydown", (e) => {
    if (tagBrowserModal.classList.contains("hidden")) return;
    if (e.key === "Escape") {
      if (!tagBrowserGalleryView.classList.contains("hidden")) {
        tagBrowserGalleryView.classList.add("hidden");
        tagBrowserListView.classList.remove("hidden");
      } else {
        closeTagBrowserModal();
      }
    }
  });

  // Comment browser — same idea as the tag browser above (collect every
  // photo carrying the attribute across the whole map, click to jump
  // straight to it), but flat rather than grouped, since a comment is
  // freeform text rather than a shared label multiple photos sit under.
  // A search box stands in for the tag browser's grouping, so comments
  // are still findable at scale instead of only visible one-at-a-time
  // inside whichever photo they're attached to.
  const commentBrowserModal = $("#commentbrowser-modal");
  const commentBrowserGrid = $("#commentbrowser-grid");
  const commentBrowserSearch = $("#commentbrowser-search");
  let commentBrowserItems = [];

  function collectPhotoCommentItems() {
    const items = [];
    let cleaned = false;
    collectAllNodesFlat().forEach((node) => {
      if (!node.photoComments) return;
      const liveIds = new Set(getNodeImageIds(node));
      Object.keys(node.photoComments).forEach((id) => {
        // Same leftover cleanup as collectPhotoTagGroups — a photo dragged
        // onto a different node shouldn't leave a comment behind here
        // pointing at a photo this node no longer actually holds.
        if (!liveIds.has(id)) {
          delete node.photoComments[id];
          cleaned = true;
          return;
        }
        items.push({ nodeId: node.id, id, comment: node.photoComments[id], nodeLabel: node.text || "Untitled node" });
      });
    });
    if (cleaned) persist();
    return items.sort((a, b) => a.nodeLabel.localeCompare(b.nodeLabel));
  }

  function openCommentBrowserModal(keep) {
    commentBrowserItems = collectPhotoCommentItems();
    if (keep !== true) commentBrowserSearch.value = "";
    renderCommentBrowserGrid();
    zoomModalOpen(commentBrowserModal);
    if (keep !== true) requestAnimationFrame(() => commentBrowserSearch.focus());
  }
  function closeCommentBrowserModal() {
    zoomModalClose(commentBrowserModal);
  }

  function renderCommentBrowserGrid() {
    const q = commentBrowserSearch.value.trim().toLowerCase();
    const filtered = !q ? commentBrowserItems : commentBrowserItems.filter(it =>
      it.comment.toLowerCase().includes(q) || it.nodeLabel.toLowerCase().includes(q));
    commentBrowserGrid.innerHTML = "";
    if (!filtered.length) {
      const empty = document.createElement("p");
      empty.className = "tagbrowser-hint";
      empty.textContent = commentBrowserItems.length
        ? "No comments match that search."
        : "No commented photos yet — open a photo and add a comment below it to start collecting them here.";
      commentBrowserGrid.appendChild(empty);
      return;
    }
    // Every commented photo (not just the filtered/visible ones) so
    // prev/next inside the opened photo modal steps through the full set,
    // same as a tag group does — the search box only narrows what's shown
    // here, not what you can browse once you're inside a photo.
    const group = { label: "Comments", items: commentBrowserItems.map(it => ({ nodeId: it.nodeId, id: it.id })) };
    filtered.forEach((it) => {
      const node = findNode(it.nodeId);
      if (!node) return; // stale entry (shouldn't normally happen)
      const cell = document.createElement("div");
      cell.className = "tagbrowser-gallery-item";

      const thumb = document.createElement("img");
      thumb.className = "tagbrowser-gallery-thumb";
      thumb.alt = "";
      const thumbUrl = photoUrl(it.id);
      if (thumbUrl) thumb.src = thumbUrl; else thumb.style.visibility = "hidden";
      thumb.addEventListener("error", () => { thumb.style.visibility = "hidden"; });

      const label = document.createElement("span");
      label.className = "tagbrowser-gallery-label";
      label.textContent = it.nodeLabel;

      const excerpt = document.createElement("span");
      excerpt.className = "commentbrowser-excerpt";
      excerpt.textContent = it.comment.length > 140 ? it.comment.slice(0, 140) + "…" : it.comment;

      cell.append(thumb, label, excerpt);
      cell.addEventListener("click", () => {
        const idx = getNodeImageIds(node).indexOf(it.id);
        if (idx < 0) return;
        const ret = makeBrowserReturn("Photo comments", commentBrowserGrid, openCommentBrowserModal, null);
        closeCommentBrowserModal();
        withViewerReturn(ret, () => openPhotoModal(it.nodeId, idx, group));
      });
      commentBrowserGrid.appendChild(cell);
    });
  }

  $("#btn-commentbrowser").addEventListener("click", openCommentBrowserModal);
  $("#commentbrowser-close").addEventListener("click", closeCommentBrowserModal);
  commentBrowserModal.addEventListener("click", (e) => { if (e.target === commentBrowserModal) closeCommentBrowserModal(); });
  commentBrowserSearch.addEventListener("input", renderCommentBrowserGrid);
  document.addEventListener("keydown", (e) => {
    if (commentBrowserModal.classList.contains("hidden")) return;
    if (e.key === "Escape") closeCommentBrowserModal();
  });

  /* ---------------- favorites browser ---------------- */

  // Same idea as the tag/comment browsers above (collect a starred
  // attribute from across the whole map, click to jump straight to it),
  // but spanning three different kinds of thing at once — a favorited
  // note, photo, or link/video — since that's what "favorite" means here
  // (see getPhotoFavorite/getLinkFavorite and the note editor's own
  // .favorite field, toggled from the ☆ buttons added alongside each).
  const favoritesBrowserModal = $("#favoritesbrowser-modal");
  const favoritesBrowserList = $("#favoritesbrowser-list");
  const favoritesBrowserSearch = $("#favoritesbrowser-search");
  let favoritesBrowserItems = [];

  function collectFavoriteItems() {
    const items = [];
    let cleaned = false;
    collectAllNodesFlat().forEach((node) => {
      const nodeLabel = node.text || "Untitled node";

      getNodeNotes(node).forEach((n) => {
        if (!n.favorite) return;
        items.push({ type: "note", nodeId: node.id, noteId: n.id, nodeLabel, preview: notePreviewText(n), isDRC: isDRCNote(n), isPlan: isPlanNote(n) });
      });

      // A task's own notes (see getTaskNotes) are a separate list from
      // the node's own `notes` array above — easy to miss here, which
      // used to mean a note favorited from inside a task's note editor
      // silently never showed up in this browser. Labelled with both the
      // node and the task it lives on so it's clear which checklist item
      // it came from.
      getNodeTasks(node).forEach((t) => {
        getTaskNotes(t).forEach((n) => {
          if (!n.favorite) return;
          items.push({
            type: "note",
            nodeId: node.id,
            taskId: t.id,
            noteId: n.id,
            nodeLabel: `${nodeLabel} → ${t.text || "Untitled task"}`,
            preview: notePreviewText(n),
            isDRC: isDRCNote(n),
            isPlan: isPlanNoteFor(n, t),
          });
        });
      });

      if (node.photoFavorites) {
        const liveIds = new Set(getNodeImageIds(node));
        Object.keys(node.photoFavorites).forEach((id) => {
          // Same leftover cleanup as collectPhotoTagGroups/
          // collectPhotoCommentItems — a photo dragged onto a different
          // node (which carries its star along, see carryPhotoFavorites)
          // shouldn't leave a stale star behind here pointing at a photo
          // this node no longer actually holds.
          if (!liveIds.has(id)) { delete node.photoFavorites[id]; cleaned = true; return; }
          if (!node.photoFavorites[id]) return;
          items.push({ type: "photo", nodeId: node.id, photoId: id, nodeLabel, preview: "Photo" });
        });
      }

      if (node.linkFavorites) {
        const liveUrls = new Set(getNodeUrls(node));
        Object.keys(node.linkFavorites).forEach((url) => {
          if (!liveUrls.has(url)) { delete node.linkFavorites[url]; cleaned = true; return; }
          if (!node.linkFavorites[url]) return;
          const isVideo = !!youtubeVideoId(url);
          items.push({
            type: isVideo ? "video" : "link",
            nodeId: node.id,
            url,
            nodeLabel,
            preview: getLinkTitle(node, url) || url,
          });
        });
      }
    });
    if (cleaned) persist();
    return items.sort((a, b) => a.nodeLabel.localeCompare(b.nodeLabel));
  }

  const FAVORITE_TYPE_ICON = { note: "📝", photo: "🖼", link: "🔗" };

  // Puts the red YouTube logo (the same LINK_ICON_SVGS.youtube used on a
  // node's link markers and the sidebar Videos button) into `el`, at a
  // fixed pixel size — used anywhere a row/heading stands for a video, so
  // every video reads with one consistent icon instead of an emoji.
  function setYoutubeIcon(el, size) {
    el.innerHTML = LINK_ICON_SVGS.youtube;
    const svg = el.firstElementChild;
    if (svg && size) {
      svg.setAttribute("width", String(size));
      svg.setAttribute("height", String(size));
    }
  }

  // Section-heading icon for the Favorites browser groups — reuses the
  // same true note/link icons as the rows below each heading (and as
  // the rest of the app) rather than the FAVORITE_TYPE_ICON emoji, so a
  // heading never shows a different "note" or "link" glyph than the
  // items filed under it. Videos use the red YouTube logo; photos keep
  // their emoji since there's no single app-wide icon to match against.
  function favoriteTypeIconEl(type) {
    const el = document.createElement("span");
    el.className = "favoritesbrowser-heading-icon";
    if (type === "note") el.innerHTML = CELL_NOTE_ICON_SVG;
    else if (type === "link") el.innerHTML = LINK_ICON_SVGS.link;
    else if (type === "video") el.innerHTML = LINK_ICON_SVGS.youtube;
    else el.textContent = FAVORITE_TYPE_ICON[type];
    return el;
  }

  function openFavoritesBrowserModal(keep) {
    favoritesBrowserItems = collectFavoriteItems();
    if (keep !== true) favoritesBrowserSearch.value = "";
    renderFavoritesBrowserList();
    zoomModalOpen(favoritesBrowserModal);
    if (keep !== true) requestAnimationFrame(() => favoritesBrowserSearch.focus());
  }
  function closeFavoritesBrowserModal() {
    zoomModalClose(favoritesBrowserModal);
  }

  // Resolves a favorited/browsed note item back to its live `notes` array
  // — the node's own, or (when the item carries a taskId — see
  // collectFavoriteItems/collectAllNotes) that task's own separate notes
  // list instead.
  function resolveNoteListForItem(node, item) {
    if (item.taskId) {
      const t = getNodeTasks(node).find(x => x.id === item.taskId);
      return t ? getTaskNotes(t) : [];
    }
    return getNodeNotes(node);
  }

  // Unstars one item directly from the list (the row's own ☆) without
  // opening it — same underlying toggle each item's own star button uses
  // (toggleNoteFavorite's field write / togglePhotoFavorite/
  // toggleLinkFavorite), just entered from here instead.
  function unfavoriteItem(item) {
    const node = findNode(item.nodeId);
    if (!node) return;
    pushUndo();
    if (item.type === "note") {
      const n = resolveNoteListForItem(node, item).find(x => x.id === item.noteId);
      if (n) n.favorite = false;
    } else if (item.type === "photo") {
      setPhotoFavorite(node, item.photoId, false);
    } else {
      setLinkFavorite(node, item.url, false);
    }
    persist();
    renderAll();
  }

  function jumpToFavoriteItem(item) {
    const node = findNode(item.nodeId);
    if (!node) return;
    const ret = makeBrowserReturn("Favorites", favoritesBrowserList, openFavoritesBrowserModal, null);
    closeFavoritesBrowserModal();
    withViewerReturn(ret, () => {
    if (item.type === "note") {
      const idx = resolveNoteListForItem(node, item).findIndex(n => n.id === item.noteId);
      openNoteModal(item.nodeId, idx >= 0 ? idx : undefined, null, item.taskId || null);
    } else if (item.type === "photo") {
      const idx = getNodeImageIds(node).indexOf(item.photoId);
      if (idx < 0) return;
      // Every favorited photo (not just the filtered/visible ones), so
      // prev/next inside the opened photo modal steps through the whole
      // starred set — same idea as the tag browser's group.
      const group = {
        label: "Favorites",
        items: favoritesBrowserItems.filter(it => it.type === "photo").map(it => ({ nodeId: it.nodeId, id: it.photoId })),
      };
      openPhotoModal(item.nodeId, idx, group);
    } else {
      // Plain link or YouTube video — same click behavior as the link's
      // own icon on the canvas (see openLinkSmart): a video opens in the
      // in-app player, anything else opens its own popup window.
      openLinkSmart(item.url, {
        videoKey: `${item.nodeId}|${item.url}`,
        get: () => getLinkComment(findNode(item.nodeId) || node, item.url),
        set: (v) => setLinkComment(findNode(item.nodeId) || node, item.url, v),
        getFavorite: () => getLinkFavorite(findNode(item.nodeId) || node, item.url),
        setFavorite: (v) => setLinkFavorite(findNode(item.nodeId) || node, item.url, v),
        getPhotos: () => getLinkPhotos(findNode(item.nodeId) || node, item.url),
        addPhoto: (dataUrl) => addLinkPhoto(findNode(item.nodeId) || node, item.url, dataUrl),
        removePhoto: (id) => removeLinkPhoto(findNode(item.nodeId) || node, item.url, id),
      });
    }
    });
  }

  const FAVORITE_TYPE_LABEL = { note: "Notes", photo: "Photos", link: "Links", video: "Videos" };
  const FAVORITE_TYPE_ORDER = ["note", "photo", "link", "video"];

  function buildFavoritesBrowserRow(it) {
    const li = document.createElement("li");
    li.className = "favoritesbrowser-row";

    const icon = document.createElement("span");
    icon.className = "favoritesbrowser-row-icon";
    if (it.type === "photo") {
      const thumbUrl = photoUrl(it.photoId);
      if (thumbUrl) {
        const thumb = document.createElement("img");
        thumb.className = "tagbrowser-tag-thumb";
        thumb.alt = "";
        thumb.src = thumbUrl;
        thumb.addEventListener("error", () => { thumb.style.visibility = "hidden"; });
        icon.appendChild(thumb);
      } else {
        icon.textContent = FAVORITE_TYPE_ICON.photo;
      }
    } else if (it.type === "note") {
      // Same yellow sticky-note / DRC notebook icons as everywhere else
      // in the app (see noteIconEl/drcIconEl), instead of a generic emoji.
      icon.appendChild(it.isDRC ? drcIconEl(22) : (it.isPlan ? planIconEl(22) : noteIconEl(22)));
    } else if (it.type === "link") {
      // Same recognizable per-destination icon as the link menus/markers
      // elsewhere (see linkIconFor), instead of a generic 🔗 emoji.
      icon.innerHTML = linkIconFor(it.url);
    } else if (it.type === "video") {
      setYoutubeIcon(icon, 22);
    } else {
      icon.textContent = FAVORITE_TYPE_ICON[it.type];
    }

    const text = document.createElement("span");
    text.className = "favoritesbrowser-row-text";
    const name = document.createElement("span");
    name.className = "favoritesbrowser-row-name";
    name.textContent = it.nodeLabel;
      name.title = it.nodeLabel;
    const preview = document.createElement("span");
    preview.className = "favoritesbrowser-row-preview";
    preview.textContent = it.preview;
    text.append(name, preview);

    const star = document.createElement("span");
    star.className = "item-star favorited";
    star.textContent = "★";
    star.title = "Remove from favorites";
    star.addEventListener("click", (e) => { e.stopPropagation(); unfavoriteItem(it); renderFavoritesBrowserList(); });

    li.append(icon, text, star);
    li.addEventListener("click", () => jumpToFavoriteItem(it));
    return li;
  }

  function renderFavoritesBrowserList() {
    const q = favoritesBrowserSearch.value.trim().toLowerCase();
    const filtered = !q ? favoritesBrowserItems : favoritesBrowserItems.filter(it =>
      it.preview.toLowerCase().includes(q) || it.nodeLabel.toLowerCase().includes(q));
    favoritesBrowserList.innerHTML = "";
    if (!filtered.length) {
      const empty = document.createElement("li");
      empty.className = "tagbrowser-empty";
      empty.textContent = favoritesBrowserItems.length
        ? "No favorites match that search."
        : "No favorites yet — tap the ☆ on a note, photo, link, or video to start collecting them here.";
      favoritesBrowserList.appendChild(empty);
      return;
    }
    // Grouped by kind (Notes / Photos / Links / Videos), each its own
    // section with a heading and count — only sections that actually
    // have a match are shown, in the fixed order above rather than
    // whatever order items happen to appear in.
    FAVORITE_TYPE_ORDER.forEach((type) => {
      const group = filtered.filter(it => it.type === type);
      if (!group.length) return;
      const heading = document.createElement("li");
      heading.className = "favoritesbrowser-heading";
      heading.appendChild(favoriteTypeIconEl(type));
      heading.appendChild(document.createTextNode(`${FAVORITE_TYPE_LABEL[type]} (${group.length})`));
      favoritesBrowserList.appendChild(heading);
      group.forEach((it) => {
        const node = findNode(it.nodeId);
        if (!node) return; // stale entry (shouldn't normally happen)
        favoritesBrowserList.appendChild(buildFavoritesBrowserRow(it));
      });
    });
  }

  // The sidebar ⭐ Favorites button was removed — each browser (Notes / Photos /
  // Videos) has its own "Favorite" folder now. The modal below is kept but is no
  // longer opened from anywhere.
  $("#favoritesbrowser-close").addEventListener("click", closeFavoritesBrowserModal);
  favoritesBrowserModal.addEventListener("click", (e) => { if (e.target === favoritesBrowserModal) closeFavoritesBrowserModal(); });
  favoritesBrowserSearch.addEventListener("input", renderFavoritesBrowserList);
  document.addEventListener("keydown", (e) => {
    if (favoritesBrowserModal.classList.contains("hidden")) return;
    if (e.key === "Escape") closeFavoritesBrowserModal();
  });

  /* ---------------- shared sort-toggle helper ---------------- */

  // Wires up a row of "Sort by" buttons (Notes/Photos/Videos browsers
  // below all use the same markup: a few buttons with a data-sort
  // attribute and a nested .notesbrowser-sort-arrow span) so that
  // clicking a button switches to that sort, and clicking the
  // already-active button reverses its direction instead — same click
  // toggles ascending/descending, rather than needing separate buttons
  // for "newest first" vs "oldest first". Returns a live { sort, dir }
  // object the caller's own sort function reads on every render.
  const SORT_TOGGLE_DEFAULT_DIR = { date: "desc", favorite: "desc", alpha: "asc" };
  function setupSortToggle(buttons, initialSort, onChange) {
    const state = { sort: initialSort, dir: SORT_TOGGLE_DEFAULT_DIR[initialSort] || "desc" };
    function updateArrows() {
      buttons.forEach((btn) => {
        const isActive = btn.dataset.sort === state.sort;
        btn.classList.toggle("active", isActive);
        const arrow = btn.querySelector(".notesbrowser-sort-arrow");
        if (arrow) arrow.textContent = isActive ? (state.dir === "asc" ? " ▲" : " ▼") : "";
      });
    }
    buttons.forEach((btn) => {
      btn.addEventListener("click", () => {
        const sort = btn.dataset.sort;
        if (sort === state.sort) {
          state.dir = state.dir === "asc" ? "desc" : "asc";
        } else {
          state.sort = sort;
          state.dir = SORT_TOGGLE_DEFAULT_DIR[sort] || "desc";
        }
        updateArrows();
        onChange();
      });
    });
    updateArrows();
    return state;
  }

  /* ---------------- notes browser ---------------- */

  /* ---------------- simple per-browser folder system ---------------- */
  // A lightweight, file-manager-style way to sort items in the Notes,
  // Photos, and Videos browsers into folders. Kept deliberately simple:
  // both the folder names and which item belongs to which folder are
  // stored in localStorage, keyed by the item's own id — entirely
  // separate from the map's own data, so this works the same way across
  // every map without touching how notes/photos/videos are themselves
  // saved, exported, or synced. Each browser gets its own independent
  // set of folders (its own storage prefix).
  //
  // Which folders a browser starts with is now the caller's decision
  // (`opts.defaults`) instead of being hardcoded to ["DRC"] for all
  // three. DRC is a notes-only idea — it's a note title (see isDRCNote),
  // and there is no such thing as a DRC photo or a DRC video — so the
  // Photos and Videos browsers were starting life with a folder that
  // could never have anything in it. `opts.retired` cleans up after
  // that: any folder named there is dropped (along with anything filed
  // into it) the first time this runs on a browser that still has it
  // stored from an older version.
  function createFolderManager(storagePrefix, opts) {
    const defaults = (opts && opts.defaults) || [];
    const retired = (opts && opts.retired) || [];
    const foldersKey = `branchline-folders-${storagePrefix}`;
    const assignKey = `branchline-folder-assign-${storagePrefix}`;

    function loadFolders() {
      try {
        const raw = localStorage.getItem(foldersKey);
        const list = raw ? JSON.parse(raw) : null;
        if (Array.isArray(list)) return list;
      } catch (e) {}
      return defaults.slice();
    }
    function saveFolders(list) {
      try { localStorage.setItem(foldersKey, JSON.stringify(list)); } catch (e) {}
    }
    function loadAssign() {
      try {
        const raw = localStorage.getItem(assignKey);
        const obj = raw ? JSON.parse(raw) : null;
        if (obj && typeof obj === "object") return obj;
      } catch (e) {}
      return {};
    }
    function saveAssign(obj) {
      try { localStorage.setItem(assignKey, JSON.stringify(obj)); } catch (e) {}
    }

    let folders = loadFolders();
    let assign = loadAssign();
    let selected = null; // null = "All"; "__unfiled__" = the Unfiled bucket

    // One-time cleanup of folders this browser no longer has any use for
    // (see `opts.retired` above). Anything that was filed into one goes
    // back to Unfiled rather than disappearing — same as deleting a
    // folder by hand.
    if (retired.length) {
      const doomed = folders.filter(f => retired.includes(f));
      if (doomed.length) {
        folders = folders.filter(f => !doomed.includes(f));
        saveFolders(folders);
        Object.keys(assign).forEach((id) => { if (doomed.includes(assign[id])) delete assign[id]; });
        saveAssign(assign);
      }
    }

    return {
      list() { return folders.slice(); },
      getSelected() { return selected; },
      select(name) { selected = name; },
      folderOf(id) { return assign[id] || null; },
      countIn(name, allIds) {
        return allIds.filter(id => assign[id] === name).length;
      },
      countUnfiled(allIds) {
        return allIds.filter(id => !assign[id]).length;
      },
      moveTo(id, name) {
        if (name) assign[id] = name; else delete assign[id];
        saveAssign(assign);
      },
      create(name) {
        name = (name || "").trim();
        if (!name || folders.includes(name)) return false;
        folders.push(name);
        saveFolders(folders);
        return true;
      },
      remove(name) {
        folders = folders.filter(f => f !== name);
        saveFolders(folders);
        Object.keys(assign).forEach((id) => { if (assign[id] === name) delete assign[id]; });
        saveAssign(assign);
        if (selected === name) selected = null;
      },
      // Whether an item (by id) should show under whichever folder is
      // currently selected — "All" shows everything, "Unfiled" shows only
      // items with no folder, anything else shows only that folder's own.
      matches(id) {
        if (selected === null) return true;
        if (selected === "__unfiled__") return !assign[id];
        return assign[id] === selected;
      },
      // Drops stale assignments for ids no longer present (e.g. a note or
      // photo that's since been deleted) so storage doesn't grow forever.
      prune(liveIds) {
        const liveSet = new Set(liveIds);
        let changed = false;
        Object.keys(assign).forEach((id) => {
          if (!liveSet.has(id)) { delete assign[id]; changed = true; }
        });
        if (changed) saveAssign(assign);
      },
    };
  }

  // Builds the "All / <folders> / Unfiled" column shown to the left of a
  // browser's list, plus the "+ new folder" row at the bottom. `onChange`
  // re-renders the whole browser (folder column and list both) whenever a
  // folder is picked, created, or deleted.
  // `protectedNames` lists folders this browser maintains itself, so they
  // get no delete button — deleting one would only have it reappear on
  // the next render (see syncDRCFolderAssignments), which reads as a bug.
  function renderFolderSidebar(container, mgr, allIds, onChange, protectedNames) {
    const protectedSet = new Set(protectedNames || []);
    container.innerHTML = "";
    function makeRow(name, label, icon, count, deletable) {
      const row = document.createElement("div");
      row.className = "browser-folder-row" + (mgr.getSelected() === name ? " active" : "");
      const iconEl = document.createElement("span");
      iconEl.className = "browser-folder-row-icon";
      iconEl.textContent = icon;
      const text = document.createElement("span");
      text.className = "browser-folder-row-label";
      text.textContent = label;
      // Belt-and-braces for a name long enough to still be clipped after
      // wrapping — hovering the row spells it out in full.
      row.title = label;
      const badge = document.createElement("span");
      badge.className = "browser-folder-row-count";
      badge.textContent = String(count);
      row.append(iconEl, text, badge);
      if (deletable) {
        const del = document.createElement("button");
        del.type = "button";
        del.className = "browser-folder-row-del";
        del.textContent = "×";
        del.title = `Delete "${name}" folder`;
        del.addEventListener("click", (e) => {
          e.stopPropagation();
          if (!confirm(`Delete the "${name}" folder? Its items go back to Unfiled.`)) return;
          mgr.remove(name);
          onChange();
        });
        row.appendChild(del);
      }
      row.addEventListener("click", () => { mgr.select(name); onChange(); });
      container.appendChild(row);
    }
    makeRow(null, "All", "🗂", allIds.length, false);
    mgr.list().forEach((name) => makeRow(name, name, "📁", mgr.countIn(name, allIds), !protectedSet.has(name)));
    makeRow("__unfiled__", "Unfiled", "📄", mgr.countUnfiled(allIds), false);

    const addRow = document.createElement("div");
    addRow.className = "browser-folder-add-row";
    const input = document.createElement("input");
    input.type = "text";
    input.placeholder = "New folder…";
    input.className = "browser-folder-add-input";
    input.spellcheck = false;
    const addBtn = document.createElement("button");
    addBtn.type = "button";
    addBtn.className = "browser-folder-add-btn";
    addBtn.textContent = "+";
    addBtn.title = "Create folder";
    function submit() {
      if (mgr.create(input.value)) { input.value = ""; onChange(); }
    }
    addBtn.addEventListener("click", submit);
    input.addEventListener("keydown", (e) => { if (e.key === "Enter") submit(); });
    addRow.append(input, addBtn);
    container.appendChild(addRow);
  }

  // Small "📁" button (added to each browser row) that opens a popover
  // listing every folder plus "Unfiled" — clicking one files that item
  // straight away, no dragging required.
  let folderMovePopoverEl = null;
  let folderMovePopoverOutsideHandler = null;
  function closeFolderMovePopover() {
    if (folderMovePopoverEl) { folderMovePopoverEl.remove(); folderMovePopoverEl = null; }
    if (folderMovePopoverOutsideHandler) {
      document.removeEventListener("mousedown", folderMovePopoverOutsideHandler);
      folderMovePopoverOutsideHandler = null;
    }
  }
  function openFolderMovePopover(anchorBtn, mgr, id, onChange) {
    closeFolderMovePopover();
    const pop = document.createElement("div");
    pop.className = "folder-move-popover";
    const current = mgr.folderOf(id);
    function addOption(name, label) {
      const opt = document.createElement("button");
      opt.type = "button";
      opt.className = "folder-move-option" + (current === name ? " active" : "");
      opt.textContent = label;
      opt.addEventListener("mousedown", (e) => e.preventDefault());
      opt.addEventListener("click", (e) => {
        e.stopPropagation();
        mgr.moveTo(id, name);
        closeFolderMovePopover();
        onChange();
      });
      pop.appendChild(opt);
    }
    addOption(null, "Unfiled");
    mgr.list().forEach((name) => addOption(name, name));

    // "New folder…" row at the bottom — creates the folder and files this
    // item into it in one step, so there's no need to close the popover,
    // go make the folder in the browser's own sidebar, then come back.
    // Typing an existing folder's name just files the item there.
    const addRow = document.createElement("div");
    addRow.className = "folder-move-add-row";
    const addInput = document.createElement("input");
    addInput.type = "text";
    addInput.className = "folder-move-add-input";
    addInput.placeholder = "New folder…";
    addInput.spellcheck = false;
    addInput.autocomplete = "off";
    const addBtn = document.createElement("button");
    addBtn.type = "button";
    addBtn.className = "folder-move-add-btn";
    addBtn.textContent = "+";
    addBtn.title = "Create folder and move here";
    function submitNewFolder() {
      const name = addInput.value.trim();
      if (!name) { addInput.focus(); return; }
      mgr.create(name); // no-op (false) if it already exists — moveTo below still applies
      if (!mgr.list().includes(name)) return;
      mgr.moveTo(id, name);
      closeFolderMovePopover();
      onChange();
    }
    addBtn.addEventListener("mousedown", (e) => e.preventDefault());
    addBtn.addEventListener("click", (e) => { e.stopPropagation(); submitNewFolder(); });
    addInput.addEventListener("click", (e) => e.stopPropagation());
    addInput.addEventListener("keydown", (e) => {
      // Keep typing here from triggering the host modal's own keyboard
      // shortcuts (photo arrows, note editor keys, Esc-to-close, …).
      e.stopPropagation();
      if (e.key === "Enter" && !e.isComposing) { e.preventDefault(); submitNewFolder(); }
      else if (e.key === "Escape") { e.preventDefault(); closeFolderMovePopover(); }
    });
    addRow.append(addInput, addBtn);
    pop.appendChild(addRow);
    document.body.appendChild(pop);
    const margin = 8;
    const rect = anchorBtn.getBoundingClientRect();
    let left = rect.left;
    left = Math.max(margin, Math.min(left, window.innerWidth - pop.offsetWidth - margin));
    let top = rect.bottom + 6;
    if (top + pop.offsetHeight > window.innerHeight - margin) top = rect.top - pop.offsetHeight - 6;
    pop.style.left = `${left}px`;
    pop.style.top = `${top}px`;
    pop.addEventListener("mousedown", (e) => e.stopPropagation());
    folderMovePopoverEl = pop;
    folderMovePopoverOutsideHandler = (e) => {
      if (!pop.contains(e.target) && e.target !== anchorBtn) closeFolderMovePopover();
    };
    setTimeout(() => document.addEventListener("mousedown", folderMovePopoverOutsideHandler), 0);
  }
  function buildFolderMoveBtn(mgr, id, onChange) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "browser-row-folder-btn";
    const current = mgr.folderOf(id);
    btn.textContent = "📁";
    btn.title = current ? `In "${current}" — click to move` : "Move to folder";
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      openFolderMovePopover(btn, mgr, id, onChange);
    });
    return btn;
  }

  // Lists every node-level note across the whole map (see getNodeNotes)
  // in one place — versus the Favorites browser above, which only shows
  // the subset you've starred. Sortable by date (most recently touched
  // first — see captureActiveNote for where updatedAt/createdAt get
  // set), favorite status, or alphabetically by the note's own preview
  // text (see notePreviewText: its title, or else its first line). Click
  // the active sort button again to reverse its direction (see
  // setupSortToggle above).
  const notesBrowserModal = $("#notesbrowser-modal");
  const notesBrowserList = $("#notesbrowser-list");
  const notesBrowserSearch = $("#notesbrowser-search");
  const notesBrowserFoldersEl = $("#notesbrowser-folders");
  const notesBrowserSortBtns = [$("#notesbrowser-sort-date"), $("#notesbrowser-sort-alpha")];
  // The one browser where DRC means something — see
  // syncDRCFolderAssignments below, which keeps it filled automatically.
  const DRC_FOLDER = "DRC";
  // Shared with the Photos and Videos browsers below — a folder every
  // browser maintains the same way (auto-filled, protected from manual
  // move/delete), for the same reason DRC is: the sort-by-favorite
  // button it replaces only ever gave you "favorites first in this one
  // list, until you close it" — the star ended up cleared when you
  // reopened the browser tomorrow and it had already sorted by date
  // again. A real folder persists and is one click away from any
  // browser's "All" view.
  const FAVORITE_FOLDER = "Favorite";
  const notesFolderMgr = createFolderManager("notes", { defaults: [DRC_FOLDER, FAVORITE_FOLDER] });
  let notesBrowserItems = [];


  function collectAllNotes() {
    const items = [];
    collectAllNodesFlat().forEach((node) => {
      const nodeLabel = node.text || "Untitled node";
      getNodeNotes(node).forEach((n) => {
        items.push({
          nodeId: node.id,
          noteId: n.id,
          nodeLabel,
          taskLabel: "",
          title: (n.title || "").trim(),
          preview: notePreviewText(n),
          favorite: !!n.favorite,
          ts: n.updatedAt || n.createdAt || 0,
          isDRC: isDRCNote(n),
          isPlan: isPlanNote(n),
        });
      });
      // A task's own notes (see getTaskNotes) live in a separate list
      // from the node's own `notes` array above — missing this meant a
      // note written (and favorited) from inside a task's note editor
      // never showed up here. taskLabel is kept as its own field (rather
      // than folded into nodeLabel) so noteBrowserRowLabel below can
      // build "node → task → title", skipping any segment that's empty.
      getNodeTasks(node).forEach((t) => {
        getTaskNotes(t).forEach((n) => {
          items.push({
            nodeId: node.id,
            taskId: t.id,
            noteId: n.id,
            nodeLabel,
            taskLabel: t.text || "Untitled task",
            title: (n.title || "").trim(),
            preview: notePreviewText(n),
            favorite: !!n.favorite,
            ts: n.updatedAt || n.createdAt || 0,
            isDRC: isDRCNote(n),
            isPlan: isPlanNoteFor(n, t),
          });
        });
      });
    });
    return items;
  }

  // Builds the single display/sort/search line for a Notes browser row —
  // "node.text → task name → note title", dropping any segment that's
  // empty (a plain node note has no task, and plenty of notes have no
  // title at all) rather than leaving a dangling arrow or blank segment.
  // A DRC note's title is always literally "DRC" (see isDRCNote) — that's
  // already said by the group heading it sits under (see
  // renderNotesBrowserList), so it's dropped here to avoid every DRC row
  // ending in a redundant "→ DRC".
  function noteBrowserRowLabel(it) {
    return [it.nodeLabel, it.taskLabel, it.isDRC ? "" : it.title].filter(Boolean).join(" → ");
  }

  function sortNotesBrowserItems(items) {
    const sorted = items.slice();
    const dir = notesBrowserSortState.dir === "asc" ? 1 : -1;
    if (notesBrowserSortState.sort === "alpha") {
      sorted.sort((a, b) => noteBrowserRowLabel(a).localeCompare(noteBrowserRowLabel(b)) * dir);
    } else {
      sorted.sort((a, b) => (b.ts - a.ts) * dir);
    }
    return sorted;
  }

  // `keep === true` re-opens with the search text left as it was (used by
  // the viewers' ← Back button) instead of starting fresh. Strictly `true`
  // because this is also bound directly as a click handler.
  function openNotesBrowserModal(keep) {
    notesBrowserItems = collectAllNotes();
    if (keep !== true) notesBrowserSearch.value = "";
    renderNotesBrowserList();
    zoomModalOpen(notesBrowserModal);
    if (keep !== true) requestAnimationFrame(() => notesBrowserSearch.focus());
  }
  function closeNotesBrowserModal() {
    closeFolderMovePopover();
    zoomModalClose(notesBrowserModal);
  }

  function jumpToNoteBrowserItem(it) {
    const node = findNode(it.nodeId);
    if (!node) return;
    const idx = resolveNoteListForItem(node, it).findIndex(n => n.id === it.noteId);
    const ret = makeBrowserReturn("Notes", notesBrowserList, openNotesBrowserModal, notesFolderMgr);
    closeNotesBrowserModal();
    withViewerReturn(ret, () => openNoteModal(it.nodeId, idx >= 0 ? idx : undefined, null, it.taskId || null));
  }

  // Same direct toggle as unfavoriteItem in the Favorites browser above —
  // lets you star/unstar right from the list without opening the note.
  function toggleNoteBrowserFavorite(it) {
    const node = findNode(it.nodeId);
    if (!node) return;
    const n = resolveNoteListForItem(node, it).find(x => x.id === it.noteId);
    if (!n) return;
    pushUndo();
    n.favorite = !n.favorite;
    it.favorite = n.favorite;
    persist();
  }

  // Builds one row for the Notes browser list — shared by both the DRC
  // and regular-notes groups below (see renderNotesBrowserList), so the
  // only difference between the two groups is which heading they sit
  // under, not how their rows look or behave.
  function buildNoteBrowserRow(it) {
    const li = document.createElement("li");
    li.className = "favoritesbrowser-row";

    const icon = document.createElement("span");
    icon.className = "favoritesbrowser-row-icon";
    if (it.isDRC) icon.appendChild(drcIconEl(22));
    else if (it.isPlan) icon.appendChild(planIconEl(22));
    else icon.appendChild(noteIconEl(22));

    // A single combined line — "node → task → title", each segment
    // skipped when empty (see noteBrowserRowLabel) — rather than the
    // separate name/preview lines the Favorites browser's rows use.
    const text = document.createElement("span");
    text.className = "favoritesbrowser-row-text";
    const name = document.createElement("span");
    name.className = "favoritesbrowser-row-name";
    const label = noteBrowserRowLabel(it);
    name.textContent = label;
    name.title = label; // full text on hover too, in case a very long label still clips at the row's max height
    text.append(name);

    const meta = document.createElement("span");
    meta.className = "notesbrowser-row-date";
    meta.textContent = it.ts ? relTime(it.ts) : "—";
    meta.title = it.ts ? new Date(it.ts).toLocaleString() : "No date recorded";

    const star = document.createElement("span");
    star.className = "item-star" + (it.favorite ? " favorited" : "");
    star.textContent = it.favorite ? "★" : "☆";
    star.title = it.favorite ? "Remove from favorites" : "Add to favorites";
    star.addEventListener("click", (e) => {
      e.stopPropagation();
      toggleNoteBrowserFavorite(it);
      star.textContent = it.favorite ? "★" : "☆";
      star.classList.toggle("favorited", it.favorite);
      star.title = it.favorite ? "Remove from favorites" : "Add to favorites";
      renderNotesBrowserList();
    });

    // No "move to folder" button on a DRC or a starred row: both have
    // their folder decided for them (syncDRCFolderAssignments /
    // syncFavoriteFolderAssignments would just put it straight back), so
    // offering one would be a button that silently undoes itself.
    if (it.isDRC || it.favorite) {
      li.append(icon, text, meta, star);
    } else {
      li.append(icon, text, meta, buildFolderMoveBtn(notesFolderMgr, it.noteId, renderNotesBrowserList), star);
    }
    li.addEventListener("click", () => jumpToNoteBrowserItem(it));
    return li;
  }

  // Files every DRC note into the "DRC" folder, without anyone having to
  // move it there. "DRC note" is decided the one way it's decided
  // everywhere else in the app — the title, see isDRCNote — so this
  // covers both notes started from the 📋 DRC… shortcut (which titles
  // them "DRC") and notes simply titled DRC by hand, and it keeps
  // covering them if a title is edited either way later on. Runs on
  // every render rather than at note-creation time so nothing can drift:
  // notes made on another device and pulled in by Drive sync land in the
  // right folder here too, even though the folder assignments themselves
  // are local to this browser.
  function syncDRCFolderAssignments() {
    const drcIds = notesBrowserItems.filter((it) => it.isDRC).map((it) => it.noteId);
    if (!drcIds.length) return;
    notesFolderMgr.create(DRC_FOLDER); // no-op if it's already there
    drcIds.forEach((id) => {
      if (notesFolderMgr.folderOf(id) !== DRC_FOLDER) notesFolderMgr.moveTo(id, DRC_FOLDER);
    });
  }

  // Same idea, for starred notes — except a note titled DRC keeps its
  // DRC folder even if it's also starred: DRC is the stronger,
  // title-based category, and letting a star quietly move it out of DRC
  // (or bounce it back and forth depending on which sync ran last)
  // would be more confusing than one note simply not living in two
  // folders at once.
  function syncFavoriteFolderAssignments() {
    const favIds = notesBrowserItems.filter((it) => it.favorite && !it.isDRC).map((it) => it.noteId);
    if (!favIds.length) return;
    notesFolderMgr.create(FAVORITE_FOLDER);
    favIds.forEach((id) => {
      if (notesFolderMgr.folderOf(id) !== FAVORITE_FOLDER) notesFolderMgr.moveTo(id, FAVORITE_FOLDER);
    });
  }

  function renderNotesBrowserList() {
    const allIds = notesBrowserItems.map((it) => it.noteId);
    notesFolderMgr.prune(allIds);
    syncDRCFolderAssignments();
    syncFavoriteFolderAssignments();
    renderFolderSidebar(notesBrowserFoldersEl, notesFolderMgr, allIds, renderNotesBrowserList, [DRC_FOLDER, FAVORITE_FOLDER]);
    const q = notesBrowserSearch.value.trim().toLowerCase();
    const filtered = notesBrowserItems.filter((it) =>
      notesFolderMgr.matches(it.noteId) &&
      (!q || it.preview.toLowerCase().includes(q) || noteBrowserRowLabel(it).toLowerCase().includes(q)));
    const sorted = sortNotesBrowserItems(filtered);
    notesBrowserList.innerHTML = "";
    if (!sorted.length) {
      const empty = document.createElement("li");
      empty.className = "tagbrowser-empty";
      empty.textContent = notesBrowserItems.length
        ? "No notes match that search."
        : "No notes yet — add one from any node to see it here.";
      notesBrowserList.appendChild(empty);
      return;
    }
    // Used to split into a "📋 DRC" heading ahead of everything else,
    // even under "All". Removed now that DRC notes are already sorted
    // into their own real folder (see syncDRCFolderAssignments/DRC_FOLDER
    // above) — with that folder already doing the separating, the extra
    // heading here was the same grouping shown twice.
    sorted.forEach((it) => {
      const node = findNode(it.nodeId);
      if (!node) return; // stale entry (shouldn't normally happen)
      notesBrowserList.appendChild(buildNoteBrowserRow(it));
    });
  }

  $("#btn-notesbrowser").addEventListener("click", openNotesBrowserModal);
  $("#notesbrowser-close").addEventListener("click", closeNotesBrowserModal);
  notesBrowserModal.addEventListener("click", (e) => { if (e.target === notesBrowserModal) closeNotesBrowserModal(); });
  notesBrowserSearch.addEventListener("input", renderNotesBrowserList);
  const notesBrowserSortState = setupSortToggle(notesBrowserSortBtns, "date", renderNotesBrowserList);
  document.addEventListener("keydown", (e) => {
    if (notesBrowserModal.classList.contains("hidden")) return;
    if (e.key === "Escape") closeNotesBrowserModal();
  });

  /* ---------------- photos browser ---------------- */

  // Lists every photo attached to any node across the whole map (not just
  // starred ones — contrast the Favorites browser above) in one place,
  // same idea as the Notes browser but for photos. Sortable by date
  // added (see getPhotoTimestamp/collectAllPhotos below), favorite status
  // (reusing the same photoFavorites star as the photo viewer and the
  // Favorites browser), or alphabetically — by the photo's own first tag
  // when it has one (a tag reads as more "the photo's name" than the node
  // it happens to sit on), falling back to the node's name otherwise.
  const photosBrowserModal = $("#photosbrowser-modal");
  const photosBrowserList = $("#photosbrowser-list");
  const photosBrowserSearch = $("#photosbrowser-search");
  const photosBrowserFoldersEl = $("#photosbrowser-folders");
  const photosBrowserSortBtns = [$("#photosbrowser-sort-date"), $("#photosbrowser-sort-alpha")];
  const photosFolderMgr = createFolderManager("photos", { retired: ["DRC"], defaults: [FAVORITE_FOLDER] });
  let photosBrowserItems = [];

  function collectAllPhotos() {
    const items = [];
    // Photos attached before photoTimestamps existed have no recorded
    // date — backfilled with "now" the first time they're listed here
    // (and persisted once, below), same lazy-backfill idea as a note's
    // createdAt (see captureActiveNote) rather than leaving them
    // permanently dateless.
    let backfilled = false;
    collectAllNodesFlat().forEach((node) => {
      const nodeLabel = node.text || "Untitled node";
      getNodeImageIds(node).forEach((id) => {
        let ts = getPhotoTimestamp(node, id);
        if (!ts) { ts = Date.now(); setPhotoTimestamp(node, id, ts); backfilled = true; }
        const tag = getPhotoTags(node, id)[0] || "";
        items.push({
          nodeId: node.id,
          photoId: id,
          nodeLabel,
          tag,
          alphaKey: tag || nodeLabel,
          favorite: getPhotoFavorite(node, id),
          ts,
        });
      });
    });
    if (backfilled) persist();
    return items;
  }

  function sortPhotosBrowserItems(items) {
    const sorted = items.slice();
    const dir = photosBrowserSortState.dir === "asc" ? 1 : -1;
    if (photosBrowserSortState.sort === "alpha") {
      sorted.sort((a, b) => a.alphaKey.localeCompare(b.alphaKey) * dir);
    } else {
      sorted.sort((a, b) => (b.ts - a.ts) * dir);
    }
    return sorted;
  }

  function openPhotosBrowserModal(keep) {
    photosBrowserItems = collectAllPhotos();
    if (keep !== true) photosBrowserSearch.value = "";
    renderPhotosBrowserList();
    zoomModalOpen(photosBrowserModal);
    if (keep !== true) requestAnimationFrame(() => photosBrowserSearch.focus());
  }
  function closePhotosBrowserModal() {
    closeFolderMovePopover();
    zoomModalClose(photosBrowserModal);
  }

  function jumpToPhotoBrowserItem(it) {
    const node = findNode(it.nodeId);
    if (!node) return;
    const idx = getNodeImageIds(node).indexOf(it.photoId);
    if (idx < 0) return;
    const ret = makeBrowserReturn("Photos", photosBrowserList, openPhotosBrowserModal, photosFolderMgr);
    closePhotosBrowserModal();
    // Every photo across the map (not just the filtered/visible ones), so
    // prev/next inside the opened photo modal steps through the whole set
    // the browser knows about — same idea as the Favorites browser's
    // photo group.
    const group = {
      label: "Photos",
      items: photosBrowserItems.map(x => ({ nodeId: x.nodeId, id: x.photoId })),
    };
    withViewerReturn(ret, () => openPhotoModal(it.nodeId, idx, group));
  }

  // Same direct toggle as unfavoriteItem in the Favorites browser above —
  // lets you star/unstar right from the list without opening the photo.
  function togglePhotoBrowserFavorite(it) {
    const node = findNode(it.nodeId);
    if (!node) return;
    pushUndo();
    setPhotoFavorite(node, it.photoId, !getPhotoFavorite(node, it.photoId));
    it.favorite = getPhotoFavorite(node, it.photoId);
    persist();
  }

  // Same rule as the Notes browser's syncFavoriteFolderAssignments —
  // photos have no DRC-equivalent concept, so this is the only folder
  // rule they need.
  function syncPhotosFavoriteFolderAssignments() {
    const favIds = photosBrowserItems.filter((it) => it.favorite).map((it) => it.photoId);
    if (!favIds.length) return;
    photosFolderMgr.create(FAVORITE_FOLDER);
    favIds.forEach((id) => {
      if (photosFolderMgr.folderOf(id) !== FAVORITE_FOLDER) photosFolderMgr.moveTo(id, FAVORITE_FOLDER);
    });
  }

  function renderPhotosBrowserList() {
    const allIds = photosBrowserItems.map((it) => it.photoId);
    photosFolderMgr.prune(allIds);
    syncPhotosFavoriteFolderAssignments();
    renderFolderSidebar(photosBrowserFoldersEl, photosFolderMgr, allIds, renderPhotosBrowserList, [FAVORITE_FOLDER]);
    const q = photosBrowserSearch.value.trim().toLowerCase();
    // A photo shared by two nodes has one id, so a folder assignment (and
    // "Favorite", synced from ONE node's star) is keyed by that id — only
    // list a node's copy under Favorite if that node really starred it.
    const filtered = photosBrowserItems.filter((it) =>
      photosFolderMgr.matches(it.photoId) &&
      (photosFolderMgr.getSelected() !== FAVORITE_FOLDER || it.favorite) &&
      (!q || it.nodeLabel.toLowerCase().includes(q) || it.tag.toLowerCase().includes(q)));
    const sorted = sortPhotosBrowserItems(filtered);
    photosBrowserList.innerHTML = "";
    if (!sorted.length) {
      const empty = document.createElement("li");
      empty.className = "tagbrowser-empty";
      empty.textContent = photosBrowserItems.length
        ? "No photos match that search."
        : "No photos yet — add one to any node to see it here.";
      photosBrowserList.appendChild(empty);
      return;
    }
    sorted.forEach((it) => {
      const node = findNode(it.nodeId);
      if (!node) return; // stale entry (shouldn't normally happen)
      const li = document.createElement("li");
      li.className = "favoritesbrowser-row";

      const icon = document.createElement("span");
      icon.className = "favoritesbrowser-row-icon";
      const thumbUrl = photoUrl(it.photoId);
      if (thumbUrl) {
        const thumb = document.createElement("img");
        thumb.className = "tagbrowser-tag-thumb";
        thumb.alt = "";
        thumb.src = thumbUrl;
        thumb.addEventListener("error", () => { thumb.style.visibility = "hidden"; });
        icon.appendChild(thumb);
      } else {
        icon.textContent = "🖼";
      }

      const text = document.createElement("span");
      text.className = "favoritesbrowser-row-text";
      const name = document.createElement("span");
      name.className = "favoritesbrowser-row-name";
      name.textContent = it.nodeLabel;
      name.title = it.nodeLabel;
      const preview = document.createElement("span");
      preview.className = "favoritesbrowser-row-preview";
      preview.textContent = it.tag ? `Tagged “${it.tag}”` : "Photo";
      text.append(name, preview);

      const meta = document.createElement("span");
      meta.className = "notesbrowser-row-date";
      meta.textContent = it.ts ? relTime(it.ts) : "—";
      meta.title = it.ts ? new Date(it.ts).toLocaleString() : "No date recorded";

      const star = document.createElement("span");
      star.className = "item-star" + (it.favorite ? " favorited" : "");
      star.textContent = it.favorite ? "★" : "☆";
      star.title = it.favorite ? "Remove from favorites" : "Add to favorites";
      star.addEventListener("click", (e) => {
        e.stopPropagation();
        togglePhotoBrowserFavorite(it);
        renderPhotosBrowserList();
      });

      // No folder button on a starred row — same reasoning as the Notes
      // browser's DRC/starred rows: syncPhotosFavoriteFolderAssignments
      // would just put it straight back into Favorite.
      if (it.favorite) {
        li.append(icon, text, meta, star);
      } else {
        li.append(icon, text, meta, buildFolderMoveBtn(photosFolderMgr, it.photoId, renderPhotosBrowserList), star);
      }
      li.addEventListener("click", () => jumpToPhotoBrowserItem(it));
      photosBrowserList.appendChild(li);
    });
  }

  $("#btn-photosbrowser").addEventListener("click", openPhotosBrowserModal);
  $("#photosbrowser-tags-btn").addEventListener("click", () => {
    closePhotosBrowserModal();
    openTagBrowserModal(true);
  });
  $("#photosbrowser-close").addEventListener("click", closePhotosBrowserModal);
  photosBrowserModal.addEventListener("click", (e) => { if (e.target === photosBrowserModal) closePhotosBrowserModal(); });
  photosBrowserSearch.addEventListener("input", renderPhotosBrowserList);
  const photosBrowserSortState = setupSortToggle(photosBrowserSortBtns, "date", renderPhotosBrowserList);
  document.addEventListener("keydown", (e) => {
    if (photosBrowserModal.classList.contains("hidden")) return;
    if (e.key === "Escape") closePhotosBrowserModal();
  });

  /* ---------------- videos browser ---------------- */

  // Same idea as the Photos browser above, but for links that actually
  // open in the in-app video player — a URL where youtubeVideoId(url) is
  // truthy (see openLinkSmart). A plain (non-video) link is skipped
  // entirely here; that's what the Links entries in the Favorites browser
  // are for. Sortable by date added, favorite status (reusing the same
  // linkFavorites star as the video modal and the Favorites browser), or
  // alphabetically by the video's own title (falling back to its URL when
  // it has no title — see getLinkTitle).
  const videosBrowserModal = $("#videosbrowser-modal");
  const videosBrowserList = $("#videosbrowser-list");
  const videosBrowserSearch = $("#videosbrowser-search");
  const videosBrowserFoldersEl = $("#videosbrowser-folders");
  const videosBrowserSortBtns = [$("#videosbrowser-sort-date"), $("#videosbrowser-sort-alpha")];
  const videosFolderMgr = createFolderManager("videos", { retired: ["DRC"], defaults: [FAVORITE_FOLDER] });
  let videosBrowserItems = [];

  function collectAllVideos() {
    const items = [];
    // Same lazy-backfill idea as collectAllPhotos above — a link added
    // before linkTimestamps existed gets stamped with "now" the first
    // time it's listed here, rather than staying permanently dateless.
    let backfilled = false;
    collectAllNodesFlat().forEach((node) => {
      const nodeLabel = node.text || "Untitled node";
      getNodeUrls(node).forEach((url) => {
        if (!youtubeVideoId(url)) return; // plain links aren't "videos"
        let ts = getLinkTimestamp(node, url);
        if (!ts) { ts = Date.now(); setLinkTimestamp(node, url, ts); backfilled = true; }
        items.push({
          nodeId: node.id,
          url,
          id: `${node.id}|${url}`,
          nodeLabel,
          title: getLinkTitle(node, url) || url,
          favorite: getLinkFavorite(node, url),
          ts,
        });
      });
    });
    if (backfilled) persist();
    return items;
  }

  function sortVideosBrowserItems(items) {
    const sorted = items.slice();
    const dir = videosBrowserSortState.dir === "asc" ? 1 : -1;
    if (videosBrowserSortState.sort === "alpha") {
      sorted.sort((a, b) => a.title.localeCompare(b.title) * dir);
    } else {
      sorted.sort((a, b) => (b.ts - a.ts) * dir);
    }
    return sorted;
  }

  function openVideosBrowserModal(keep) {
    videosBrowserItems = collectAllVideos();
    if (keep !== true) videosBrowserSearch.value = "";
    renderVideosBrowserList();
    zoomModalOpen(videosBrowserModal);
    if (keep !== true) requestAnimationFrame(() => videosBrowserSearch.focus());
  }
  function closeVideosBrowserModal() {
    closeFolderMovePopover();
    zoomModalClose(videosBrowserModal);
  }

  // Opens the video the same way clicking its link icon on the canvas
  // does — the in-app player, wired to the same comment/favorite fields
  // (see openLinkSmart/openVideoModal) — rather than anything bespoke to
  // this browser.
  function jumpToVideoBrowserItem(it) {
    const node = findNode(it.nodeId);
    if (!node) return;
    const ret = makeBrowserReturn("Videos", videosBrowserList, openVideosBrowserModal, videosFolderMgr);
    closeVideosBrowserModal();
    withViewerReturn(ret, () => openLinkSmart(it.url, {
      videoKey: `${it.nodeId}|${it.url}`,
      get: () => getLinkComment(findNode(it.nodeId) || node, it.url),
      set: (v) => setLinkComment(findNode(it.nodeId) || node, it.url, v),
      getFavorite: () => getLinkFavorite(findNode(it.nodeId) || node, it.url),
      setFavorite: (v) => setLinkFavorite(findNode(it.nodeId) || node, it.url, v),
      getPhotos: () => getLinkPhotos(findNode(it.nodeId) || node, it.url),
      addPhoto: (dataUrl) => addLinkPhoto(findNode(it.nodeId) || node, it.url, dataUrl),
      removePhoto: (id) => removeLinkPhoto(findNode(it.nodeId) || node, it.url, id),
    }));
  }

  function toggleVideoBrowserFavorite(it) {
    const node = findNode(it.nodeId);
    if (!node) return;
    pushUndo();
    setLinkFavorite(node, it.url, !getLinkFavorite(node, it.url));
    it.favorite = getLinkFavorite(node, it.url);
    persist();
  }

  // Same rule as Photos — videos have no DRC-equivalent either.
  function syncVideosFavoriteFolderAssignments() {
    const favIds = videosBrowserItems.filter((it) => it.favorite).map((it) => it.id);
    if (!favIds.length) return;
    videosFolderMgr.create(FAVORITE_FOLDER);
    favIds.forEach((id) => {
      if (videosFolderMgr.folderOf(id) !== FAVORITE_FOLDER) videosFolderMgr.moveTo(id, FAVORITE_FOLDER);
    });
  }

  function renderVideosBrowserList() {
    const allIds = videosBrowserItems.map((it) => it.id);
    videosFolderMgr.prune(allIds);
    syncVideosFavoriteFolderAssignments();
    renderFolderSidebar(videosBrowserFoldersEl, videosFolderMgr, allIds, renderVideosBrowserList, [FAVORITE_FOLDER]);
    const q = videosBrowserSearch.value.trim().toLowerCase();
    const filtered = videosBrowserItems.filter((it) =>
      videosFolderMgr.matches(it.id) &&
      (!q || it.title.toLowerCase().includes(q) || it.nodeLabel.toLowerCase().includes(q)));
    const sorted = sortVideosBrowserItems(filtered);
    videosBrowserList.innerHTML = "";
    if (!sorted.length) {
      const empty = document.createElement("li");
      empty.className = "tagbrowser-empty";
      empty.textContent = videosBrowserItems.length
        ? "No videos match that search."
        : "No videos yet — add a YouTube link to any node to see it here.";
      videosBrowserList.appendChild(empty);
      return;
    }
    sorted.forEach((it) => {
      const node = findNode(it.nodeId);
      if (!node) return; // stale entry (shouldn't normally happen)
      const li = document.createElement("li");
      li.className = "favoritesbrowser-row";

      const icon = document.createElement("span");
      icon.className = "favoritesbrowser-row-icon";
      setYoutubeIcon(icon, 22);

      const text = document.createElement("span");
      text.className = "favoritesbrowser-row-text";
      const name = document.createElement("span");
      name.className = "favoritesbrowser-row-name";
      name.textContent = it.nodeLabel;
      name.title = it.nodeLabel;
      const preview = document.createElement("span");
      preview.className = "favoritesbrowser-row-preview";
      preview.textContent = it.title;
      preview.title = it.title;
      text.append(name, preview);

      const meta = document.createElement("span");
      meta.className = "notesbrowser-row-date";
      meta.textContent = it.ts ? relTime(it.ts) : "—";
      meta.title = it.ts ? new Date(it.ts).toLocaleString() : "No date recorded";

      const star = document.createElement("span");
      star.className = "item-star" + (it.favorite ? " favorited" : "");
      star.textContent = it.favorite ? "★" : "☆";
      star.title = it.favorite ? "Remove from favorites" : "Add to favorites";
      star.addEventListener("click", (e) => {
        e.stopPropagation();
        toggleVideoBrowserFavorite(it);
        renderVideosBrowserList();
      });

      // No folder button on a starred row — same reasoning as Notes/
      // Photos: syncVideosFavoriteFolderAssignments would just put it
      // straight back into Favorite.
      if (it.favorite) {
        li.append(icon, text, meta, star);
      } else {
        li.append(icon, text, meta, buildFolderMoveBtn(videosFolderMgr, it.id, renderVideosBrowserList), star);
      }
      li.addEventListener("click", () => jumpToVideoBrowserItem(it));
      videosBrowserList.appendChild(li);
    });
  }

  $("#btn-videosbrowser").addEventListener("click", openVideosBrowserModal);
  $("#videosbrowser-close").addEventListener("click", closeVideosBrowserModal);
  videosBrowserModal.addEventListener("click", (e) => { if (e.target === videosBrowserModal) closeVideosBrowserModal(); });
  videosBrowserSearch.addEventListener("input", renderVideosBrowserList);
  const videosBrowserSortState = setupSortToggle(videosBrowserSortBtns, "date", renderVideosBrowserList);
  document.addEventListener("keydown", (e) => {
    if (videosBrowserModal.classList.contains("hidden")) return;
    if (e.key === "Escape") closeVideosBrowserModal();
  });

  /* ---------------- boot ---------------- */

  async function boot() {
    // If web/custom fonts (e.g. "Inter") are still loading, the very first
    // layout pass may measure text with fallback font metrics, sizing boxes
    // slightly too narrow and forcing a mid-word wrap. Re-run layout once
    // the real fonts are ready so box widths match what's actually painted.
    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(() => renderAll());
    }
    await loadAllMaps();
    await loadAffirmationQuotes();
    await FolderDB.restore();
    if (FolderDB.dir && !FolderDB.needsPermission) {
      await FolderDB.syncFromFolder();
    }
    await DriveDB.restore(); // silent re-sign-in, only if previously connected
    const dupesTrashed = await autoRemoveDuplicateMaps();
    if (dupesTrashed) console.log(`Auto-removed ${dupesTrashed} duplicate map(s) to trash`);
    if (activeMaps().length === 0) {
      const sample = sampleMindMap();
      await DB.put(sample);
      await FolderDB.save(sample);
      await DriveDB.save(sample);
      state.maps.push(sample);
    }
    updateFolderUI();
    updateDriveUI();
    renderSidebar();
    // Reopen whichever map you had open last, if it still exists and isn't
    // trashed — falls back to the top of the active list (e.g. first run,
    // or that map got deleted/trashed on another device since).
    let lastId = null;
    try { lastId = localStorage.getItem(LAST_OPENED_MAP_KEY); } catch (e) {}
    const activeList = activeMaps();
    const lastStillActive = lastId && activeList.find(m => m.id === lastId);
    const toOpen = lastStillActive ? lastId : activeList[0].id;
    await openMap(toOpen);
  }

  $("#btn-connect-folder").addEventListener("click", () => FolderDB.pick());
  $("#btn-google-signin").addEventListener("click", () => {
    if (DriveDB.needsReauth) {
      // A real tap gives Chrome a genuine user gesture, which is exactly
      // what the failing silent path above can't rely on — so this uses
      // the normal (non-silent) consent flow rather than another silent
      // attempt.
      DriveDB.signIn(false)
        .then(() => DriveDB.scheduleRefresh())
        .catch(err => alert(err.message || "Google sign-in failed."));
    } else if (DriveDB.signedIn) {
      DriveDB.signOut();
    } else {
      DriveDB.signIn(false).catch(err => alert(err.message || "Google sign-in failed."));
    }
  });
  const btnDriveLostReconnect = $("#drive-lost-reconnect");
  if (btnDriveLostReconnect) {
    btnDriveLostReconnect.addEventListener("click", () => {
      DriveDB.signIn(false)
        .then(() => DriveDB.scheduleRefresh())
        .catch(err => alert(err.message || "Google sign-in failed."));
    });
  }

  const btnSignedOutSignin = $("#btn-signed-out-signin");
  if (btnSignedOutSignin) {
    btnSignedOutSignin.addEventListener("click", () => {
      DriveDB.signIn(false).catch(err => alert(err.message || "Google sign-in failed."));
    });
  }

  // Hide clock/calendar — a one-tap way to get rid of the root node's
  // live clock block and the toolbar's 📅 Calendar button, for anyone who
  // doesn't want them cluttering the map. Saved on the map itself
  // (map.clockHidden — see ensureClockHidden) so the toggle only affects
  // whichever mindmap it was set on; other maps are unaffected. Defaults
  // to hidden for maps that have never had it touched.
  function isClockHidden() {
    return !state.current || state.current.clockHidden !== false;
  }
  function setClockHidden(hidden) {
    if (!state.current) return;
    state.current.clockHidden = hidden;
    persist();
    document.getElementById("app").classList.toggle("hide-clock-widgets", hidden);
    // Rebuilds every node so the root node picks up (or drops) the extra
    // width/height it reserves for the clock block — see computeNodeBox.
    renderAll();
  }

  // Sidebar hide/show — a fixed 260px sidebar eats a lot of screen and
  // isn't resizable, so this gives a one-tap way to get it out of the
  // way (rather than something to drag, which doesn't work well with
  // touch scrolling gestures anyway). Remembered across reloads; hidden
  // by default the very first time, on any screen size, so the map gets
  // full width until you actually ask for the sidebar.
  const SIDEBAR_HIDDEN_KEY = "branchline_sidebar_hidden";
  function setSidebarHidden(hidden) {
    document.getElementById("app").classList.toggle("sidebar-hidden", hidden);
    try { localStorage.setItem(SIDEBAR_HIDDEN_KEY, hidden ? "1" : "0"); } catch (e) {}
  }
  (function initSidebarToggle() {
    let hidden;
    try {
      const saved = localStorage.getItem(SIDEBAR_HIDDEN_KEY);
      hidden = saved === null ? true : saved === "1";
    } catch (e) { hidden = true; }
    setSidebarHidden(hidden);
    $("#btn-toggle-sidebar").addEventListener("click", () => {
      setSidebarHidden(!document.getElementById("app").classList.contains("sidebar-hidden"));
    });
  })();

  // Keeps the floating add-child/add-sibling buttons above the on-screen
  // keyboard on touch devices. Opening the keyboard shrinks the visual
  // viewport without necessarily resizing the page layout, so anything
  // pinned to the bottom of the screen (like #node-fabs) would otherwise
  // end up hidden underneath it while you're mid-edit on a node — right
  // when you're most likely to want to tap "add branch". The formula
  // works whether or not the browser also resizes the layout viewport:
  // if it does, vv.height already accounts for the keyboard and the
  // inset comes out ~0, so this is a no-op there.
  (function initKeyboardInset() {
    const vv = window.visualViewport;
    if (!vv) return;
    function update() {
      const inset = Math.max(0, window.innerHeight - vv.height - vv.offsetTop);
      document.documentElement.style.setProperty("--keyboard-inset", inset + "px");
    }
    vv.addEventListener("resize", update);
    vv.addEventListener("scroll", update);
    update();
  })();

  boot();

})();
